// ── Hi-DPI helper — call at start of every renderMap / dice frame ──
function applyDPR(canvas, cssW, cssH){
  const dpr=window.devicePixelRatio||1;
  const pw=Math.round(cssW*dpr), ph=Math.round(cssH*dpr);
  if(canvas.width!==pw||canvas.height!==ph){
    canvas.width=pw; canvas.height=ph;
    canvas.style.width=cssW+'px'; canvas.style.height=cssH+'px';
  }
  canvas.getContext('2d').setTransform(dpr,0,0,dpr,0,0);
  return dpr;
}

// ── Thin send wrapper so existing call sites need no change ────────────────
function send(obj){ return GS.send(obj); }

function $(id){ return document.getElementById(id); }

// Estado visual da barra de atalhos. Declarado antes de showScreen(), pois
// essa função também pode ser chamada por botões da tela inicial.
let _atalhosAbertos = false;
// Há uma barra de slots em cada menu (habilidades, magias e itens). Como os
// overlays continuam no DOM quando são fechados, não podemos usar apenas
// `getElementById`, pois ele pode devolver a barra de um menu oculto.
let _atalhosMenuAtual = null;

function showScreen(id){
  if(id !== 'screen-game') _clearGamepadEndTurnConfirm();
  document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));
  $(id).classList.add('active');
  // A barra de configuração dos atalhos também é usada na cidade, onde o
  // jogador prepara habilidades, magias e itens para a próxima masmorra.
  if(id !== 'screen-game' && id !== 'screen-city'){
    _atalhosAbertos = false;
    const shortcutBar = document.getElementById('shortcut-bar');
    if(shortcutBar){ shortcutBar.hidden = true; shortcutBar.innerHTML = ''; }
    // Saindo da masmorra por qualquer via que não seja a cidade (menu, lobby,
    // fim de jogo, desconexão) — o ambiente sonoro da masmorra não deve tocar
    // fora dela. Idempotente: _ambienciaParar() já não faz nada sem loop ativo.
    _ambienciaParar();
  }
  // Os HUDs de uso rápido e efeitos da partida continuam exclusivos da
  // masmorra; não devem atravessar a transição para a cidade.
  if(id !== 'screen-game'){
    const activeEffects = document.getElementById('active-effects-hud');
    if(activeEffects){ activeEffects.hidden = true; activeEffects.innerHTML = ''; }
    const gamepadContext = document.getElementById('gamepad-context-hud');
    if(gamepadContext){ gamepadContext.hidden = true; gamepadContext.innerHTML = ''; }
    const gamepadShortcuts = document.getElementById('gamepad-shortcuts-hud');
    if(gamepadShortcuts){ gamepadShortcuts.hidden = true; gamepadShortcuts.innerHTML = ''; }
    const gamepadShortcutsTray = document.getElementById('gamepad-shortcuts-tray');
    if(gamepadShortcutsTray){ gamepadShortcutsTray.hidden = true; gamepadShortcutsTray.innerHTML = ''; }
  }
  if(!['screen-game', 'screen-city', 'screen-class-select'].includes(id)){
    document.getElementById('pause-menu')?.classList.remove('open');
  }
  // O botão flutuante ficou reservado ao Mapa de CR do mestre. O inventário
  // dos heróis é acessado pelo menu de personagem, sem atalho duplicado.
  const fichaFab = document.getElementById('ficha-fab');
  if(fichaFab) fichaFab.style.display = (id === 'screen-game' && GS.isMaster()) ? 'flex' : 'none';
  if (typeof _menuMusicOnScreen === 'function') _menuMusicOnScreen(id);
  // HUD do Mestre (#hud-mestre) só existe dentro da masmorra (screen-game) —
  // some ao trocar de tela (o elemento persiste no DOM entre telas até o
  // próximo renderMyPanel, então sem isto ficaria flutuando por cima).
  if(id !== 'screen-game'){
    const hudM = document.getElementById('hud-mestre');
    if(hudM) hudM.classList.remove('aberto');
    if(window._mpRelogioTimer){ clearInterval(window._mpRelogioTimer); window._mpRelogioTimer = null; }
    const mm = document.getElementById('minimapa-cr');
    if(mm) mm.style.display = 'none';
  }
}

function togglePauseMenu(open){
  const menu = document.getElementById('pause-menu');
  if(!menu) return;
  menu.classList.toggle('open', !!open);
  if(open) menu.querySelector('.pause-menu-primary')?.focus();
}

function returnToInitialMenu(){
  togglePauseMenu(false);
  document.getElementById('loja-overlay')?.remove();
  document.getElementById('painel-ajuda')?.remove();
  document.getElementById('ficha-overlay-jogo')?.remove();
  if(typeof closeTargetModal === 'function') closeTargetModal();
  if(typeof closeChestWindow === 'function') closeChestWindow();
  if(g3) { dispose3D(); mode3D = false; }
  if(_city3) destroyCity3D();
  if(_cityImg) destroyCityImage();
  GS.leaveSession();
  showScreen('screen-connect');
}

function exitGameWindow(){
  returnToInitialMenu();
  window.close();
  window.setTimeout(() => {
    if(!window.closed) toast(t('ui.conexao.fechamento_bloqueado'), 'var(--text2)');
  }, 150);
}

function toast(msg, color='var(--red)'){
  const t=$('toast'); t.textContent=msg; t.style.background=color;
  t.style.display='block';
  clearTimeout(t._t); t._t=setTimeout(()=>t.style.display='none',3000);
}

function formatGMText(text){
  return text
    .replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>')
    .replace(/\*(.+?)\*/g,'<em>$1</em>');
}

function getName(){
  const n=$('input-name').value.trim();
  if(!n){ toast(t('ui.conexao.digite_nome')); return null; }
  return n;
}

// Endereço do servidor inferido de ONDE a página foi aberta:
//  • localhost / arquivo local → servidor local na porta 8765 (host jogando no PC)
//  • domínio real (túnel https) → MESMO domínio via wss (amigos pelo link único).
// Assim ninguém precisa digitar endereço: o cliente fala com quem o serviu.
function defaultServerUrl(){
  const loc = window.location;
  const host = loc.hostname;
  if(loc.protocol==='file:' || !host || host==='localhost' || host==='127.0.0.1'){
    return 'ws://localhost:8765';
  }
  return (loc.protocol==='https:' ? 'wss:' : 'ws:') + '//' + loc.host;
}
// Página aberta via link de túnel (domínio real) → amigo entrando: o endereço é
// automático, então esconde o campo de servidor e a dica de iniciar.bat (do host).
function serverIsAutoDetected(){
  const h = window.location.hostname;
  return !!h && h!=='localhost' && h!=='127.0.0.1' && window.location.protocol!=='file:';
}

function createRoom(){
  const name=getName(); if(!name) return;
  const url=$('input-server').value.trim()||defaultServerUrl();
  GS.connect(url, name, 'create');
}

// Login por conta (apelido+PIN) — Fase 3 dos Jogos Salvos.
function entrarComConta() {
  const name = (document.getElementById('input-name').value || '').trim();
  // SEM trim(): espaco no comeco ou no fim faz parte da senha, e cortar em
  // silencio faria o login falhar sem explicacao nenhuma para o jogador.
  const senha = document.getElementById('input-senha').value || '';
  const url  = (document.getElementById('input-server').value || 'ws://localhost:8765').trim();
  if (!name) { alert(t('ui.conta.escolha_apelido')); return; }
  if (senha.length < 8) { alert(t('ui.conta.senha_curta')); return; }
  window._contaCtx = { url, name, password: senha };
  GS.loginConta(url, name, senha);
}

// Criação de novo jogo salvo (tela "Meus Jogos") — Fase 3 dos Jogos Salvos.
function criarJogoSalvo() {
  const name = (document.getElementById('sg-name').value || '').trim();
  const campaign_file = document.getElementById('sg-campaign').value || null;
  const has_master = document.getElementById('sg-master').checked;
  const entry_mode = document.getElementById('sg-entry-mode')?.value || 'vote';
  const replacement_rule = document.getElementById('sg-replacement-rule')?.value || 'experienced';
  if (!name) { alert(t('ui.save.de_nome_ao_jogo')); return; }
  GS.createSavegame({ name, mode: 'campaign', campaign_file, has_master,
    rules: { allow_new_players: true, entry_mode, replacement_rule, vote_timeout_hours: 72 } });
}

// Entrar (já logado) na sala do jogo salvo de um amigo pelo código — Fase 3.
function entrarPorCodigoLogado() {
  const code = (document.getElementById('sg-join-code').value || '').trim().toUpperCase();
  if (code.length !== 4) { alert(t('ui.save.codigo_4_letras')); return; }
  GS.joinByCode(code);   // usa a conexão já logada (leva a conta junto)
}

// Reconexão manual a partir da sessão salva (botão da tela inicial).
function rejoinSaved(){
  if(!GS.rejoin()){
    toast(t('ui.hud.nenhuma_partida_salva_para_reconectar'), 'var(--orange)');
    const b=$('btn-rejoin'); if(b) b.style.display='none';
  }
}

// Pré-preenche o endereço do servidor com o detectado automaticamente. Para
// amigos entrando pelo link do túnel, esconde o campo de endereço e a dica de
// iniciar.bat (instruções só fazem sentido para o host na própria máquina).
(function(){
  const si = $('input-server');
  if(si) si.value = defaultServerUrl();
  if(serverIsAutoDetected()){
    const fs = $('field-server'); if(fs) fs.style.display = 'none';
    const hh = $('hint-host');    if(hh) hh.style.display = 'none';
  }
})();

// Mostra o botão de reconexão na tela inicial quando há sessão salva e
// pré-preenche o nome do herói da última partida.
//
// É FUNÇÃO, e não mais um IIFE: o texto do botão passa por t(), e um IIFE aqui
// rodaria no CARREGAMENTO — antes de `const t` existir —, lançando o
// ReferenceError de temporal dead zone que ABORTA o resto do game.js. Como o
// corpo só roda quando há sessão salva (`if(!s || !s.code) return;`), a quebra
// só aparecia DEPOIS da primeira partida: a tela inicial desenhava (o markup é
// HTML), mas nenhum handler existia, e o jogo travava na seleção de herói.
//
// Quem chama é _audioInit(), depois de _langLoadPref(), para o botão já nascer
// no idioma salvo; _setLang() rechama na troca de idioma. O texto leva
// parâmetros (código e nome), então data-i18n não o alcança — mesmo caso de
// _refreshTurnTimerOption().
function _refreshBtnReconectar(){
  const s = GS.savedSession && GS.savedSession();
  if(!s || !s.code) return;
  const b = $('btn-rejoin');
  if(b){
    b.style.display = 'block';
    b.textContent = t('ui.conexao.reconectar_sala', {codigo:s.code, nome:s.name});
  }
  const ni = $('input-name');
  if(ni && !ni.value) ni.value = s.name;
  const si = $('input-server');
  if(si && s.url) si.value = s.url;
}

function joinRoom(){
  const name=getName(); if(!name) return;
  const code=$('input-code').value.trim().toUpperCase();
  if(code.length!==4){ toast(t('ui.conexao.codigo_4_letras')); return; }
  const url=$('input-server').value.trim()||defaultServerUrl();
  GS.connect(url, name, 'join', code);
}

// Sessão temporária aberta pelo Editor de Masmorras. Não usa lobby, conta nem
// save: o token só serve para entregar o controle de Mestre desta aba ao teste.
(function abrirTesteDoEditor(){
  const token = new URLSearchParams(window.location.search).get('teste_masmorra');
  if (!token) return;
  const nome = 'Mestre de Teste';
  const input = $('input-name'); if (input) input.value = nome;
  GS.connect(defaultServerUrl(), nome, 'test', token);
})();

function copyCode(){
  const code=($('cs-room-code')||{}).textContent||'';
  navigator.clipboard.writeText(code).then(()=>toast(t('ui.conexao.codigo_copiado'),'var(--green)'));
}

// ── MESSAGE HANDLER (delegated to GS — callbacks registered at bottom) ────

function handleLobby(msg){
  // GS._handle já atualizou GS.lobbyState e GS.myPid antes deste callback.
  // Tudo é exibido na tela de seleção full-screen (csf); o lobby antigo foi removido.
  showScreen('screen-class-select');
  csUpdateLobbyBar(msg);
  if(!csf && window.THREE) initClassSelectFull();
  if(csf){
    const meP = msg.players.find(p=>p.id===GS.myPid);
    const myClass = meP?.class_id;
    csf.selectedId = myClass ?? csf.selectedId;
    if(myClass) csf.gridSelectionMade = true;
    // Jogo salvo: se a minha conta já tem personagem fixo, a classe fica travada
    // (o servidor força; a UI só reflete). Jogo rápido: classLocked=false.
    csf.classLocked = !!(msg.savegame && meP && meP.bound);
    // Classes escolhidas por OUTROS jogadores ficam indisponíveis.
    csf.takenIds = new Set(
      msg.players.filter(p => p.id !== GS.myPid && p.class_id).map(p => p.class_id));
    _csfApplyTaken();
  }
  // Reaplica por último — initClassSelectFull() (chamado acima, só na 1ª vez)
  // reseta o texto de #cs-hint para o padrão de herói; isto garante que o
  // aviso "Você é o Mestre" vença mesmo no 1º lobby_state do Mestre.
  _csApplyMasterMode();
}

// Aplica o visual de "indisponível" (esmaecido) aos heróis já escolhidos por
// outros jogadores; restaura a opacidade original dos disponíveis.
function _csfApplyTaken(){
  if(!csf) return;
  for(const [id, pg] of Object.entries(csf.heroGroups)){
    const taken = csf.takenIds.has(id);
    pg.traverse(o => {
      if(!o.isMesh || !o.material) return;
      const m = o.material;
      if(m.userData._origOpacity === undefined){
        m.userData._origOpacity     = m.opacity;
        m.userData._origTransparent = m.transparent;
      }
      if(taken){ m.transparent = true; m.opacity = 0.16; }
      else     { m.transparent = m.userData._origTransparent; m.opacity = m.userData._origOpacity; }
    });
  }
  _csHeroGridSync();
}

function startGame(){ send({type:'start_game'}); }

// ■  CITY SCREEN — Three.js 3D isometric hub

// 'image' = cidade ilustrada com hotspots (padrão). '3d' = cena Three.js antiga (fallback).
const CITY_MODE = 'image';
let _cityImg = null;   // estado do overlay de imagem (espelha _city3)
let _cityPointDraft = null;
let _cityPointDraggingId = null;
let _cityPointDragOffset = {x:0, y:0};
let _city3 = null;
let _cityTOD = 0.78; // time-of-day: 0=midnight, 0.25=dawn, 0.5=noon, 0.75=dusk

// Nome e ação de cada prédio da cidade: chave por id, não campo na estrutura
// (padrão do Lote 1 para mapas {id:'texto'}). O `_CTY_BLDGS` guarda só geometria.
const _predioNome = id => _rotulo(id, 'ui.cidade.predio', id);
const _predioAcao = id => _rotulo(id, 'ui.cidade.acao', '');

const _CTY_BLDGS = [
  {id:'taverna',  emoji:'🍺',
   x:-5.5,z:-4,  w:3.2,d:2.4,wallH:2.2,roofH:1.8, wallHex:0x7a3a10,roofHex:0x4a2208,winHex:0xffcc44,
   hx:32, hy:46, hero:false},
  {id:'templo',   emoji:'⛪',
   x:0,  z:-7.5, w:4.0,d:3.2,wallH:3.0,roofH:2.2, wallHex:0x283088,roofHex:0x181858,winHex:0x88aaff,
   hx:67, hy:35, hero:true},
  {id:'ferreiro', emoji:'⚒',
   x:5.5,z:-4,   w:3.2,d:2.4,wallH:2.2,roofH:1.8, wallHex:0x5a2810,roofHex:0x3a1808,winHex:0xff8822,
   hx:83, hy:38, hero:false},
  {id:'guilda',   emoji:'⚔',
   x:-5.5,z:2,   w:3.0,d:2.4,wallH:2.2,roofH:1.8, wallHex:0x5a4a10,roofHex:0x3a3008,winHex:0xffee88,
   hx:52, hy:21, hero:false},
  {id:'mercador', emoji:'🛒',
   x:5.5,z:2,    w:3.0,d:2.4,wallH:2.2,roofH:1.8, wallHex:0x205a20,roofHex:0x103815,winHex:0x88ff88,
   hx:50, hy:40, hero:true},
];

function initCity3D(){
  if(_city3) return;
  if(!window.THREE) return;
  const T = window.THREE;

  const canvas = document.getElementById('city-3d-canvas');
  if(!canvas) return;
  const W = canvas.offsetWidth  || window.innerWidth;
  const H = canvas.offsetHeight || window.innerHeight;

  const renderer = new T.WebGLRenderer({canvas, antialias:true, powerPreference:'high-performance'});
  renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
  renderer.setSize(W, H);
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = T.PCFShadowMap   /* PCF simples: ~igual visualmente, bem mais barato que PCFSoft */;
  renderer.toneMapping = T.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.15;

  const scene = new T.Scene();
  scene.background = new T.Color(0x0a0818);
  scene.fog = new T.FogExp2(0x080612, 0.015);

  // ── Camera: isometric 45° orthographic ──
  const aspect = W / H;
  const fV     = _cityFitFV(aspect);   // enquadra a cidade inteira (telas estreitas dão zoom-out)
  const cam = new T.OrthographicCamera(-fV*aspect, fV*aspect, fV, -fV, 0.1, 200);
  cam.position.set(18, 18, 18);
  cam.lookAt(0, 0, 0);
  cam.updateProjectionMatrix();

  const ambient = new T.AmbientLight(0x20182a, 0.22);
  scene.add(ambient);

  const sun = new T.DirectionalLight(0xffdd99, 0.95);
  sun.position.set(10, 16, 8);
  sun.castShadow = true;
  sun.shadow.mapSize.width = sun.shadow.mapSize.height = 2048;
  const sc = sun.shadow.camera;
  sc.left=-22; sc.right=22; sc.top=22; sc.bottom=-22; sc.far=100;
  sun.shadow.bias = -0.0008;
  scene.add(sun);

  const moon = new T.DirectionalLight(0x5070c8, 0.30);
  moon.position.set(-7, 12, -5); scene.add(moon);

  // ── Ground (cobblestone canvas texture) ──
  const cobbleTex = _cityMakeCobbleTex(T, 512);
  const ground = new T.Mesh(
    new T.PlaneGeometry(40, 40),
    new T.MeshStandardMaterial({map:cobbleTex, roughness:0.94, metalness:0.02})
  );
  ground.rotation.x = -Math.PI/2; ground.receiveShadow = true; scene.add(ground);

  // Street (lighter plaza strip)
  const streetTex = _cityMakeCobbleTex(T, 256, true);
  for(const [sw,sd,sx,sz] of [[14,3,0,-1],[3,18,0,0]]){
    const str = new T.Mesh(new T.PlaneGeometry(sw,sd),
      new T.MeshStandardMaterial({map:streetTex, roughness:0.90, metalness:0.02}));
    str.rotation.x=-Math.PI/2; str.position.set(sx,0.003,sz);
    str.receiveShadow=true; scene.add(str);
  }

  // ── Buildings ──
  const bldgGroups = {}, bldgPickMeshes = [];
  for(const bd of _CTY_BLDGS){
    const bg = _cityBuildBldg(T, bd);
    scene.add(bg);
    bldgGroups[bd.id] = bg;
    // Collect pickable wall meshes
    bg.traverse(c=>{ if(c.isMesh && !c.userData.noRay) bldgPickMeshes.push(c); });
  }

  // ── Street lamps ──
  const lamps = [];
  const lampPos = [[-3.5,0,-2],[3.5,0,-2],[-3.5,0,2.5],[3.5,0,2.5],[-6.5,0,-1],[6.5,0,-1]];
  for(const [lx,ly,lz] of lampPos){
    const lmp = _cityBuildLamp(T);
    lmp.group.position.set(lx,ly,lz); scene.add(lmp.group); lamps.push(lmp);
  }

  const treePos = [[-9,0,-7],[-9,0,0],[-9,0,5],[9,0,-7],[9,0,0],[9,0,5],
                    [-2.5,0,6.5],[2.5,0,6.5],[0,0,-11],[-4.5,0,-10],[4.5,0,-10]];
  for(const [tx,ty,tz] of treePos){ const tr=_cityBuildTree(T); tr.position.set(tx,ty,tz); scene.add(tr); }

  // ── Well/fountain at center ──
  scene.add(_cityBuildWell(T));

  const npcWP = [[-3,0,1],[0,0,3.5],[3,0,1],[3,0,-1.5],[0,0,-4],[-3,0,-1.5]];
  const npcs  = [];
  const npcC  = [0xcc8844, 0x8888cc, 0x44cc88, 0xcc4488, 0xcccc44];
  for(let i=0;i<5;i++){
    const npc = _cityBuildNPC(T, npcC[i%npcC.length]);
    npc.userData.wpIdx = i % npcWP.length;
    npc.userData.wpT   = i / 5;
    npc.userData.npcSpd = 0.65 + Math.random()*0.35;
    const wp = npcWP[npc.userData.wpIdx];
    npc.position.set(wp[0], 0, wp[2]);
    scene.add(npc); npcs.push(npc);
  }

  // ── Portal pulsing point light ──
  const portalLight = new T.PointLight(0xff1020, 1.0, 9);
  portalLight.position.set(0, 1.8, 8); scene.add(portalLight);

  _city3 = {
    T, scene, renderer, cam,
    ambient, sun, moon,
    bldgGroups, bldgPickMeshes,
    lamps, npcs, npcWP,
    portalLight,
    raycaster: new T.Raycaster(),
    hoveredId: null,
    animFrame: null,
    fV, aspect,
    zoomTween: null,
  };

  renderer.domElement.addEventListener('mousemove',  _cityMouseMove);
  renderer.domElement.addEventListener('click',      _cityClick);
  renderer.domElement.addEventListener('mouseleave', ()=>{ if(_city3){_city3.hoveredId=null; _cityHideTooltip(); }});

  // Toque: enquadramento já mostra tudo; um toque curto entra no prédio.
  let _ctx0, _cty0, _ctMoved;
  renderer.domElement.addEventListener('touchstart', e=>{
    if(e.touches.length===1){ _ctx0=e.touches[0].clientX; _cty0=e.touches[0].clientY; _ctMoved=0; } else { _ctMoved=999; }
  }, { passive:true });
  renderer.domElement.addEventListener('touchmove', e=>{
    if(e.touches.length===1) _ctMoved+=Math.abs(e.touches[0].clientX-_ctx0)+Math.abs(e.touches[0].clientY-_cty0);
  }, { passive:true });
  renderer.domElement.addEventListener('touchend', (e)=>{
    if(_ctMoved<14){ e.preventDefault(); _cityClick({ clientX:_ctx0, clientY:_cty0 }); }
  }, { passive:false });

  window.addEventListener('resize', _cityOnResize);

  _startCity3Loop();
  _updateCityTimeBadge();
  // Corrige o enquadramento depois que o layout assenta (canvas pode iniciar 0px).
  requestAnimationFrame(()=>{ if(_city3) _cityOnResize(); });
}

// Meia-altura do frustum que enquadra a cidade inteira. Em telas estreitas
// (aspect pequeno) aumenta para caber a largura; no desktop fica em 11 (igual).
function _cityFitFV(aspect){
  return Math.max(11, 10.5 / Math.max(aspect, 0.0001));
}
// Reajusta a câmera/renderer da cidade quando a tela muda (rotação/redimensão).
function _cityOnResize(){
  if(!_city3){ window.removeEventListener('resize', _cityOnResize); return; }
  const cv = document.getElementById('city-3d-canvas'); if(!cv) return;
  const W = cv.clientWidth || window.innerWidth, H = cv.clientHeight || window.innerHeight;
  const aspect = W / H, fV = _cityFitFV(aspect);
  _city3.renderer.setSize(W, H, false);
  _city3.aspect = aspect; _city3.fV = fV;
  const cam = _city3.cam;
  cam.left = -fV*aspect; cam.right = fV*aspect; cam.top = fV; cam.bottom = -fV;
  cam.updateProjectionMatrix();
}

function _cityMakeCobbleTex(T, sz, light=false){
  const cv=document.createElement('canvas'); cv.width=cv.height=sz;
  const c=cv.getContext('2d');
  const base = light ? 36 : 28;
  const CS=Math.round(sz/16);
  for(let gy=0;gy<sz;gy+=CS){
    const rowOff=((gy/CS|0)%2)*(CS/2);
    for(let gx=-CS+rowOff;gx<sz;gx+=CS){
      const v=base+((gx*7+gy*13)&0xff)%14; const bv=light?2:0;
      c.fillStyle=`rgb(${v},${v-bv},${v+3})`; c.fillRect(gx+1,gy+1,CS-2,CS-2);
    }
  }
  c.strokeStyle=`rgba(6,4,10,${light?0.45:0.65})`; c.lineWidth=1;
  for(let gy=0;gy<sz;gy+=CS){
    const rowOff=((gy/CS|0)%2)*(CS/2);
    c.beginPath(); c.moveTo(0,gy); c.lineTo(sz,gy); c.stroke();
    for(let gx=-CS+rowOff;gx<sz;gx+=CS){ c.beginPath(); c.moveTo(gx,gy); c.lineTo(gx,gy+CS); c.stroke(); }
  }
  const tex=new T.CanvasTexture(cv);
  tex.wrapS=tex.wrapT=T.RepeatWrapping; tex.repeat.set(6,6); return tex;
}

function _cityMakeWallTex(T, hex){
  const cv=document.createElement('canvas'); cv.width=cv.height=256;
  const c=cv.getContext('2d');
  const r=(hex>>16)&0xff, g=(hex>>8)&0xff, b=hex&0xff;
  c.fillStyle=`rgb(${r},${g},${b})`; c.fillRect(0,0,256,256);
  const bH=22, bW=46;
  for(let by=0;by<256;by+=bH){
    const rowOff=((by/bH|0)%2)*(bW/2);
    for(let bx=-bW+rowOff;bx<256;bx+=bW){
      const dr=Math.round((Math.random()-0.5)*20);
      c.fillStyle=`rgb(${Math.min(255,Math.max(0,r+dr))},${Math.min(255,Math.max(0,g+dr))},${Math.min(255,Math.max(0,b+dr))})`;
      c.fillRect(bx+1,by+1,bW-2,bH-2);
    }
  }
  c.strokeStyle='rgba(0,0,0,0.55)'; c.lineWidth=2;
  for(let by=0;by<256;by+=bH){
    const ro=((by/bH|0)%2)*(bW/2);
    c.beginPath(); c.moveTo(0,by); c.lineTo(256,by); c.stroke();
    for(let bx=-bW+ro;bx<256;bx+=bW){ c.beginPath(); c.moveTo(bx,by); c.lineTo(bx,by+bH); c.stroke(); }
  }
  return new T.CanvasTexture(cv);
}

function _cityBuildBldg(T, bd){
  const {id,wallHex,roofHex,winHex,x,z,w,d,wallH,roofH,isDungeon} = bd;
  const pg = new T.Group();
  pg.userData.bldgId = id;
  pg.position.set(x, 0, z);

  const wallTex = _cityMakeWallTex(T, wallHex);
  const wallMat = new T.MeshStandardMaterial({map:wallTex, roughness:0.88, metalness:0.08});
  const walls = new T.Mesh(new T.BoxGeometry(w, wallH, d), wallMat);
  walls.position.y = wallH/2;
  walls.castShadow = walls.receiveShadow = true;
  walls.userData.bldgId = id;  // for raycasting
  pg.add(walls);

  if(!isDungeon && roofH>0){
    const rR = Math.hypot(w,d)*0.5;
    const roof = new T.Mesh(
      new T.ConeGeometry(rR*0.72, roofH, 4),
      new T.MeshStandardMaterial({color:new T.Color(roofHex), roughness:0.92, metalness:0.06})
    );
    roof.rotation.y = Math.PI/4; roof.position.y = wallH+roofH/2;
    roof.castShadow = true; roof.userData.noRay=true; pg.add(roof);
  }

  if(isDungeon){
    // Gothic arch opening
    const stoneMat = new T.MeshStandardMaterial({color:new T.Color(wallHex), roughness:0.95, metalness:0.12});
    const darkMat  = new T.MeshStandardMaterial({color:0x040208, emissive:new T.Color(0x440068), emissiveIntensity:0.7, roughness:0.5});
    const aW=w*0.52, aH=wallH*0.78;
    // Dark hollow
    const hollow=new T.Mesh(new T.BoxGeometry(aW,aH,d+0.12),darkMat);
    hollow.position.y=aH/2; hollow.userData.noRay=true; pg.add(hollow);
    // Arch lintel
    const lintel=new T.Mesh(new T.BoxGeometry(aW+0.45,0.38,d+0.12),stoneMat);
    lintel.position.y=aH+0.19; lintel.userData.noRay=true; pg.add(lintel);
    // Side pillars
    for(const sx of [-(aW/2+0.22), aW/2+0.22]){
      const pil=new T.Mesh(new T.BoxGeometry(0.38,aH+0.38,d+0.12),stoneMat);
      pil.position.set(sx,aH*0.5,0); pil.userData.noRay=true; pg.add(pil);
    }
    // Steps in front
    [[w+0.4,0.14,0.4],[w+0.7,0.08,0.6]].forEach(([sw,sh,sd],i)=>{
      const step=new T.Mesh(new T.BoxGeometry(sw,sh,sd),stoneMat);
      step.position.set(0,sh/2,d/2+0.4+i*0.25); step.castShadow=true; step.receiveShadow=true; step.userData.noRay=true; pg.add(step);
    });
    // Skull emblem
    const skullMat = new T.MeshStandardMaterial({color:0xddddcc, emissive:0x332222, emissiveIntensity:0.3, roughness:0.7});
    const skull = new T.Mesh(new T.SphereGeometry(0.18,7,5), skullMat);
    skull.position.set(0, aH+0.72, d/2+0.05); skull.userData.noRay=true; pg.add(skull);
  } else {
    // Door
    const doorMat = new T.MeshStandardMaterial({color:0x100800, roughness:0.95});
    const door=new T.Mesh(new T.BoxGeometry(0.65,1.2,0.07),doorMat);
    door.position.set(0,0.6,d/2+0.03); door.userData.noRay=true; pg.add(door);
    // Windows
    const winMat = new T.MeshStandardMaterial({color:new T.Color(winHex), emissive:new T.Color(winHex), emissiveIntensity:0.55, roughness:0.3});
    for(const wx of [-w*0.25, w*0.25]){
      const win=new T.Mesh(new T.BoxGeometry(0.46,0.58,0.07),winMat);
      win.position.set(wx,wallH*0.62,d/2+0.03); win.userData.noRay=true; win.userData.isWindow=true; pg.add(win);
    }
    // Window point light (off at day)
    const wl=new T.PointLight(new T.Color(winHex), 0, 3.2);
    wl.position.set(0,wallH*0.62,d/2+0.5); wl.userData.isWinLight=true; pg.add(wl);
    // Torch flame + light
    const torchMat=new T.MeshStandardMaterial({color:0xffdd40,emissive:0xff8010,emissiveIntensity:2.0,roughness:0.5});
    const flame=new T.Mesh(new T.SphereGeometry(0.09,5,4),torchMat);
    flame.position.set(w*0.38,wallH*0.52,d/2+0.18); flame.userData.noRay=true; pg.add(flame);
    const tl=new T.PointLight(0xff9920,0,3.0);
    tl.position.set(w*0.38,wallH*0.52,d/2+0.38); tl.userData.isTorchLight=true; pg.add(tl);
  }

  return pg;
}

function _cityBuildLamp(T){
  const grp=new T.Group();
  const met=new T.MeshStandardMaterial({color:0x383040,roughness:0.65,metalness:0.70});
  const pole=new T.Mesh(new T.CylinderGeometry(0.042,0.058,2.3,7),met);
  pole.position.y=1.15; pole.castShadow=true; pole.userData.noRay=true; grp.add(pole);
  const arm=new T.Mesh(new T.CylinderGeometry(0.026,0.026,0.75,7),met);
  arm.rotation.z=Math.PI/2; arm.position.set(0.375,2.15,0); arm.userData.noRay=true; grp.add(arm);
  const head=new T.Mesh(new T.BoxGeometry(0.22,0.20,0.22),met);
  head.position.set(0.75,2.16,0); head.userData.noRay=true; grp.add(head);
  const bulbMat=new T.MeshStandardMaterial({color:0xffee88,emissive:new T.Color(0xffcc40),emissiveIntensity:2.5,roughness:0.3});
  const bulb=new T.Mesh(new T.SphereGeometry(0.075,6,6),bulbMat);
  bulb.position.set(0.75,2.14,0); bulb.userData.noRay=true; grp.add(bulb);
  const base=new T.Mesh(new T.CylinderGeometry(0.13,0.16,0.13,7),met);
  base.position.y=0.065; base.userData.noRay=true; grp.add(base);
  const light=new T.PointLight(0xffcc44, 0, 5.8); // intensity driven by day/night
  light.position.set(0.75,2.05,0); grp.add(light);
  return {group:grp, light, bulbMat};
}

function _cityBuildTree(T){
  const grp=new T.Group();
  const tH=1.2+Math.random()*0.9, lR=0.95+Math.random()*0.45;
  const trunkMat=new T.MeshStandardMaterial({color:0x3a2510,roughness:0.95,metalness:0.0});
  const leavesMat=new T.MeshStandardMaterial({color:0x1a4010,roughness:0.88,metalness:0.0});
  const leavesDark=new T.MeshStandardMaterial({color:0x0e2a08,roughness:0.88,metalness:0.0});
  const trunk=new T.Mesh(new T.CylinderGeometry(0.12,0.18,tH,6),trunkMat);
  trunk.position.y=tH/2; trunk.castShadow=true; trunk.userData.noRay=true; grp.add(trunk);
  const leaves=new T.Mesh(new T.SphereGeometry(lR,8,5),leavesMat);
  leaves.position.y=tH+lR*0.65; leaves.castShadow=true; leaves.userData.noRay=true; grp.add(leaves);
  const inner=new T.Mesh(new T.SphereGeometry(lR*0.62,6,4),leavesDark);
  inner.position.y=tH+lR*0.5; inner.userData.noRay=true; grp.add(inner);
  return grp;
}

function _cityBuildWell(T){
  const grp=new T.Group();
  const ston=new T.MeshStandardMaterial({color:0x2a2438,roughness:0.92,metalness:0.10});
  const watr=new T.MeshStandardMaterial({color:0x2040a0,roughness:0.10,metalness:0.60,transparent:true,opacity:0.85});
  const wood=new T.MeshStandardMaterial({color:0x4a2810,roughness:0.95,metalness:0.0});
  const basin=new T.Mesh(new T.CylinderGeometry(0.90,0.78,0.30,12),ston);
  basin.position.y=0.15; basin.receiveShadow=true; grp.add(basin);
  const water=new T.Mesh(new T.CircleGeometry(0.74,12),watr);
  water.rotation.x=-Math.PI/2; water.position.y=0.29; water.userData.noRay=true; grp.add(water);
  for(const px of [-0.70,0.70]){
    const post=new T.Mesh(new T.CylinderGeometry(0.056,0.056,1.1,7),wood);
    post.position.set(px,0.55,0); post.castShadow=true; grp.add(post);
  }
  const beam=new T.Mesh(new T.BoxGeometry(1.5,0.09,0.09),wood);
  beam.position.y=1.1; beam.castShadow=true; grp.add(beam);
  return grp;
}

function _cityBuildNPC(T, hexColor){
  const grp=new T.Group();
  const bodyMat=new T.MeshStandardMaterial({color:new T.Color(hexColor),roughness:0.9,metalness:0.0});
  const headMat=new T.MeshStandardMaterial({color:0xc89860,roughness:0.85,metalness:0.0});
  const body=new T.Mesh(new T.CylinderGeometry(0.14,0.16,0.52,8),bodyMat);
  body.position.y=0.46; body.castShadow=true; body.userData.noRay=true; grp.add(body);
  const head=new T.Mesh(new T.SphereGeometry(0.15,8,6),headMat);
  head.position.y=0.88; head.castShadow=true; head.userData.noRay=true; grp.add(head);
  return grp;
}

function _startCity3Loop(){
  let _last=Date.now();
  function tick(){
    if(!_city3) return;
    _city3.animFrame=requestAnimationFrame(tick);
    const now=Date.now(), dt=Math.min((now-_last)*0.001,0.05); _last=now;
    const t=now*0.001;
    const {T,scene,renderer,cam,ambient,sun,moon,bldgGroups,lamps,npcs,npcWP,portalLight,zoomTween}=_city3;

    // ── Day/night cycle ──
    _cityTOD=(_cityTOD+dt*0.008)%1.0; // full cycle ≈ 125 s
    const dayF=Math.max(0,Math.sin(_cityTOD*Math.PI));

    const nightAmb=new T.Color(0x12103a), dayAmb=new T.Color(0x908898);
    ambient.color.lerpColors(nightAmb,dayAmb,dayF);
    ambient.intensity=0.12+dayF*0.30;
    sun.intensity=dayF*0.98; moon.intensity=(1-dayF)*0.32;
    const nightSky=new T.Color(0x08060f), daySky=new T.Color(0x3a5890);
    scene.background.lerpColors(nightSky,daySky,dayF*dayF);
    const nightFog=new T.Color(0x060410), dayFog=new T.Color(0x283060);
    scene.fog.color.lerpColors(nightFog,dayFog,dayF);

    const lampInt=(1-dayF)*(0.75+0.15*Math.sin(t*2.8));
    for(const lmp of lamps){
      lmp.light.intensity=lampInt*1.1;
      lmp.bulbMat.emissiveIntensity=lampInt>0.05?2.5:0.4;
    }

    for(const bg of Object.values(bldgGroups)){
      bg.traverse(c=>{
        if(c.userData.isWinLight)   c.intensity=lampInt*0.55;
        if(c.userData.isTorchLight) c.intensity=lampInt*0.65*(0.8+0.2*Math.sin(t*4.8+c.position.x));
      });
    }

    // ── Portal pulsing ──
    portalLight.intensity=0.7+0.7*Math.sin(t*1.9);

    // ── Building hover lift ──
    for(const [id,bg] of Object.entries(bldgGroups)){
      const targetY=id===_city3.hoveredId ? 0.09 : 0;
      bg.position.y+=(targetY-bg.position.y)*0.12;
    }

    // ── NPC movement ──
    for(const npc of npcs){
      const {wpIdx,wpT,npcSpd}=npc.userData;
      const from=npcWP[wpIdx], to=npcWP[(wpIdx+1)%npcWP.length];
      const dist=Math.hypot(to[0]-from[0],to[2]-from[2]);
      let newT=wpT+dt*npcSpd/(dist||1);
      if(newT>=1){ newT=0; npc.userData.wpIdx=(wpIdx+1)%npcWP.length; }
      npc.userData.wpT=newT;
      npc.position.x=from[0]+(to[0]-from[0])*newT;
      npc.position.z=from[2]+(to[2]-from[2])*newT;
      const dx=to[0]-from[0],dz=to[2]-from[2];
      if(Math.abs(dx)+Math.abs(dz)>0.01) npc.rotation.y=Math.atan2(dx,dz);
    }

    // ── Zoom tween (dungeon entrance) ──
    if(_city3.zoomTween){
      const zt=_city3.zoomTween;
      zt.elapsed=(zt.elapsed||0)+dt;
      const p=Math.min(zt.elapsed/zt.duration,1);
      const e=p*p*(3-2*p); // smoothstep
      const newFV=zt.startFV+(zt.endFV-zt.startFV)*e;
      const a=_city3.aspect;
      cam.left=-newFV*a; cam.right=newFV*a; cam.top=newFV; cam.bottom=-newFV;
      cam.position.x+=(zt.tx-cam.position.x)*0.06;
      cam.position.z+=(zt.tz-cam.position.z)*0.06;
      cam.lookAt(0,1.5,8);
      cam.updateProjectionMatrix();
      if(p>=1 && zt.onDone){ const cb=zt.onDone; _city3.zoomTween=null; cb(); }
    }

    // ── Time badge ──
    if(Math.floor(t)%3===0 && Math.floor(t*10)%10===0) _updateCityTimeBadge();

    renderer.render(scene,cam);
  }
  tick();
}

function _cityPickBldg(e){
  if(!_city3) return null;
  const {raycaster,cam,bldgPickMeshes,renderer,T}=_city3;
  const rc=renderer.domElement.getBoundingClientRect();
  const mx=((e.clientX-rc.left)/rc.width)*2-1;
  const my=((e.clientY-rc.top)/rc.height)*-2+1;
  raycaster.setFromCamera(new T.Vector2(mx,my),cam);
  const hits=raycaster.intersectObjects(bldgPickMeshes,false);
  return hits.length ? hits[0].object.userData.bldgId??null : null;
}
function _cityMouseMove(e){
  if(!_city3) return;
  const id=_cityPickBldg(e);
  if(id!==_city3.hoveredId){
    _city3.hoveredId=id;
    _city3.renderer.domElement.style.cursor=id?'pointer':'default';
    if(id) _cityShowTooltip(id,e); else _cityHideTooltip();
  } else if(id) _cityMoveTooltip(e);
}

// O raycaster dos meshes 3D conhece tipo de prédio, não ponto. Resolve para o
// primeiro ponto daquele tipo na cidade atual.
function _pontoDoTipo(type){
  const pontos = GS.cityPoints();
  return Object.keys(pontos).find(id => (pontos[id].type || id) === type) || type;
}

function _cityClick(e){
  if(!_city3) return;
  const id=_cityPickBldg(e);
  if(!id) return;
  if(id==='caravana') showWorldMap();
  else if(id==='guilda') toast(t('ui.cidade.guilda_missoes_em_breve'),'var(--gold)');
  else _cityHotspotClick(_pontoDoTipo(id), id);
}

function _cityShowTooltip(id,e){
  const bd=_CTY_BLDGS.find(b=>b.id===id); if(!bd) return;
  const tip=document.getElementById('city-bldg-tooltip'); if(!tip) return;
  const isDng=id==='dungeon';
  tip.innerHTML=`<h4>${bd.emoji} ${_predioNome(bd.id)}</h4>`+
    `<p class="tip-action">${_predioAcao(bd.id)}</p>`+
    `<p class="tip-click">${t(isDng ? 'ui.cidade.clique_entrar' : 'ui.cidade.clique_abrir')}</p>`;
  tip.style.display='block';
  tip.style.borderColor=isDng?'rgba(255,50,50,.7)':'rgba(var(--gold-rgb),.5)';
  _cityMoveTooltip(e);
}
function _cityMoveTooltip(e){
  const tip=document.getElementById('city-bldg-tooltip'); if(!tip||tip.style.display==='none') return;
  const tw=tip.offsetWidth||200, th=tip.offsetHeight||80;
  tip.style.left=Math.min(e.clientX+18,window.innerWidth-tw-8)+'px';
  tip.style.top=Math.max(0,Math.min(e.clientY-10,window.innerHeight-th-8))+'px';
}
function _cityHideTooltip(){
  const tip=document.getElementById('city-bldg-tooltip'); if(tip) tip.style.display='none';
}

function _updateCityHeroBar(msg){
  const bar=document.getElementById('city-hero-bar'); if(!bar||!msg) return;
  const gold=msg.players.reduce((s,p)=>s+(p.gold||0),0);
  bar.innerHTML=msg.players.map(p=>{
    const isMe=p.id===GS.myPid;
    const hpPct=p.max_hp>0?p.hp/p.max_hp*100:0;
    const st=p.hp<=0?'dead':(hpPct<40?'wounded':'');
    const foto=HERO_PORTRAIT_PATHS[p.class_id]||'';
    // Foto 3:4 recortada no rosto; cai para emoji se faltar/erro de carregamento.
    const face = foto
      ? `<img class="city-hcard-face" src="${foto}" alt=""
            onerror="this.style.display='none';this.nextElementSibling.style.display='flex'"/>
         <span class="city-hcard-face-fallback" style="display:none">${p.emoji}</span>`
      : `<span class="city-hcard-face-fallback">${p.emoji}</span>`;
    return `<div class="city-hcard${isMe?' me':''}" data-pid="${p.id}"
                 title="Clique para ver a ficha" style="cursor:pointer">
      ${face}
      <div><div class="city-hcard-name">${p.name}</div>
           <div class="city-hcard-hp ${st}">${p.hp}/${p.max_hp} HP</div></div>
    </div>`;
  }).join('')+`<div class="city-gold-badge">${t('ui.cidade.badge_ouro', {n: gold})}</div>`;
  bar.querySelectorAll('.city-hcard[data-pid]').forEach(card => {
    card.onclick = () => abrirFichaCidade(card.getAttribute('data-pid'));
  });
}

function _updateCityTimeBadge(){
  const b=document.getElementById('city-time-badge'); if(!b) return;
  const tod=_cityTOD;
  b.textContent=tod<0.15||tod>0.88?t('ui.cidade.noite_profunda'):
                tod<0.30?'🌅 Amanhecer':
                tod<0.55?t('ui.cidade.pleno_dia'):
                tod<0.70?'🌇 Entardecer':'🌆 Anoitecer';
}

function destroyCity3D(){
  if(!_city3) return;
  cancelAnimationFrame(_city3.animFrame);
  _city3.renderer.domElement.removeEventListener('mousemove',_cityMouseMove);
  _city3.renderer.domElement.removeEventListener('click',_cityClick);
  window.removeEventListener('resize', _cityOnResize);
  _city3.renderer.dispose();
  _city3=null;
  _cityHideTooltip();
  const fo=document.getElementById('city-fade-overlay');
  if(fo) fo.remove();
}

// ■  CITY SCREEN (modo imagem) — overlay em DOM sobre #screen-city

function initCityImage(){
  if(_cityImg) return;
  const host = document.getElementById('screen-city');
  if(!host) return;

  const stage = document.createElement('div');
  stage.id = 'city-stage';

  // Moldura 3:2 que define a caixa renderizada da imagem; imagem, hotspots,
  // vida e selo são posicionados DENTRO dela em % → alinhamento garantido.
  const frame = document.createElement('div');
  frame.id = 'city-frame';
  stage.appendChild(frame);

  const img = document.createElement('img');
  img.id = 'city-img';
  img.src = 'assets/city/alva_e_luz.jpg?v=' + (window.ASSET_VER || '1');
  img.alt = t('ui.cidade.cidade_de_alva_e_luz');
  img.draggable = false;
  frame.appendChild(img);

  const life = document.createElement('div');
  life.id = 'city-life';
  // Vida sutil: névoa nas bordas + brilhos piscando (tochas/janelas) + pulsar do portão.
  life.innerHTML =
    '<div class="city-fog"></div>' +
    '<div class="city-flicker" style="left:32%;top:46%"></div>' +
    '<div class="city-flicker" style="left:50%;top:40%;animation-delay:.7s"></div>' +
    '<div class="city-flicker" style="left:83%;top:38%;animation-delay:1.1s"></div>' +
    '<div class="city-flicker" style="left:60%;top:55%;animation-delay:.4s"></div>' +
    '<div class="city-gateglow" style="left:23%;top:84%"></div>';
  frame.appendChild(life);

  const hotWrap = document.createElement('div');
  hotWrap.id = 'city-hotspots';
  for(const bd of _CTY_BLDGS){
    if(bd.hx == null) continue;
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'city-hotspot city-building city-map-point' + (bd.hero ? ' hero' : '') + (bd.id==='dungeon' ? ' dungeon' : '');
    btn.style.left = bd.hx + '%';
    btn.style.top  = bd.hy + '%';
    btn.dataset.cityBuilding = bd.id;
    btn.dataset.cityPoint = bd.id;
    const _rot = _predioNome(bd.id) + ' — ' + _predioAcao(bd.id);
    btn.setAttribute('aria-label', _rot);
    btn.title = _rot;
    const label = bd.id==='dungeon' ? t('ui.cidade.ir_aventura') : _predioNome(bd.id);
    btn.innerHTML =
      '<span class="ch-glow" aria-hidden="true"></span>' +
      '<span class="ch-pin"><span class="ch-emoji">' + bd.emoji + '</span>' +
      '<span class="ch-name">' + label + '</span></span>';
    btn.addEventListener('click', () => _cityHotspotClick(bd.id, bd.id));
    hotWrap.appendChild(btn);
  }
  const caravan = document.createElement('button');
  caravan.type = 'button'; caravan.className = 'city-hotspot city-caravan city-map-point';
  caravan.dataset.cityCaravan = 'true';
  caravan.dataset.cityPoint = 'caravana';
  caravan.style.left = '42%'; caravan.style.top = '63%';
  caravan.setAttribute('aria-label', t('ui.cidade.caravana_titulo'));
  caravan.title = t('ui.cidade.caravana_titulo');
  caravan.innerHTML = '<span class="ch-glow" aria-hidden="true"></span><span class="ch-pin"><span class="ch-emoji">🧭</span><span class="ch-name">' + t('ui.cidade.ponto.caravana') + '</span></span>';
  caravan.addEventListener('click', showWorldMap);
  hotWrap.appendChild(caravan);
  hotWrap.addEventListener('pointerdown', e => {
    if(!_cityPointDraft) return;
    const marker = e.target.closest('[data-city-point]');
    if(!marker || marker.style.display === 'none') return;
    const pointId = marker.dataset.cityPoint;
    const point = _cityPointDraft[pointId];
    if(!point) return;
    const rect = hotWrap.getBoundingClientRect();
    _cityPointDraggingId = pointId;
    _cityPointDragOffset = {
      x: ((e.clientX - rect.left) / rect.width) * 100 - point.x,
      y: ((e.clientY - rect.top) / rect.height) * 100 - point.y,
    };
    marker.setPointerCapture?.(e.pointerId);
    e.preventDefault(); e.stopPropagation();
  });
  hotWrap.addEventListener('pointermove', e => {
    if(!_cityPointDraft || !_cityPointDraggingId) return;
    const rect = hotWrap.getBoundingClientRect();
    const x = Math.max(0, Math.min(100, ((e.clientX - rect.left) / rect.width) * 100 - _cityPointDragOffset.x));
    const y = Math.max(0, Math.min(100, ((e.clientY - rect.top) / rect.height) * 100 - _cityPointDragOffset.y));
    _cityPointDraft[_cityPointDraggingId] = {x:Math.round(x * 100) / 100, y:Math.round(y * 100) / 100};
    const marker = hotWrap.querySelector('[data-city-point="' + _cityPointDraggingId + '"]');
    if(marker){ marker.style.left = x + '%'; marker.style.top = y + '%'; }
  });
  ['pointerup','pointercancel'].forEach(eventName => hotWrap.addEventListener(eventName, () => { _cityPointDraggingId = null; }));
  frame.appendChild(hotWrap);
  host.appendChild(stage);

  const tb = document.getElementById('city-time-badge');
  if(tb) tb.style.display = 'none';

  _cityImg = { stage, frame, img, life, hotWrap, raf:0 };
  _gamepadFocusMapPoint('#city-hotspots .city-hotspot');
}

function _cityHotspotClick(pointId, type){
  // NÃO chamar esta variável de `t`: o tradutor global tem esse nome.
  const tipo = type || pointId;
  // Destinos com tela própria despacham pelo tipo, antes da resolução de
  // cena/loja. O editor não oferece esses pontos no vínculo de cena.
  if(tipo === 'dungeon'){
    const st = GS.cityState;
    const loc = st && st.world && st.world.location;
    const ponto = ((st && st.city_map_points || {})[loc] || {})[pointId];
    const adventure = (((st && st.world && st.world.adventures) || [])
      .find(a => ponto && a.id === ponto.aventura));
    if(!adventure){ toast(t('ui.cidade.entrada_sem_destino'),'var(--red)'); return; }
    abrirEntradaMasmorra(adventure, (ponto && ponto.name) || adventure.nome);
    return;
  }
  if(tipo === 'caravana'){ showWorldMap(); return; }
  if(tipo === 'guilda'){ openGuild(); return; }
  if(tipo === 'refugio'){
    const st=GS.cityState, loc=st && st.world && st.world.location;
    const ponto=((st && st.city_map_points || {})[loc] || {})[pointId];
    if(ponto && ponto.locked){ toast(t('ui.cidade.refugio_bloqueado'),'var(--gold)'); return; }
    const cenaExterna=ponto && (ponto.scene_externo || ponto.scene);
    if(cenaExterna && GS.scenes()[cenaExterna]){ openShop(pointId, tipo, cenaExterna); return; }
    GS.openRefugio(); return;
  }
  // openShop espera o id do prédio cru (ex.: 'mercador'); é o que o servidor usa
  // como chave da loja ('mercado' apontaria p/ loja vazia).
  openShop(pointId, tipo);
}

let _refugioState = null, _quartoState = null;
// Qual baú abrir direto na janela dividida quando o estado chegar do servidor.
// O painel-lista (`_renderRefugioPainel`) continua sendo o hub de quartos/ouro
// para quem chega ao Refúgio sem pedir um baú específico.
let _bauDireto = null;
function _abrirBauDireto(scope){
  _bauDireto = scope;
  if(scope === 'room') GS.openQuarto(); else GS.openRefugio();
}
function _fecharRefugio(){ document.getElementById('refugio-overlay')?.remove(); document.getElementById('quarto-overlay')?.remove(); }
function _heroCityMe(){ const st=GS.cityState||{}; return (st.players||[]).find(p=>p.id===GS.myPid) || null; }
function _itemLabel(it){ return `${it?.emoji||'📦'} ${it?.name||it?.id||'Item'}${it?.ammo_count!=null?' ×'+it.ammo_count:''}`; }
function _renderBauSlots(container, items, limit, action){
  if(!container) return;
  container.classList.add('bau-slot-grid'); container.innerHTML='';
  const total=Math.max(1,Number(limit)||10);
  for(let i=0;i<total;i++){
    const slot=document.createElement('button'); slot.type='button'; slot.className='bau-slot'+(items[i]?' occupied':'');
    if(items[i]){ slot.innerHTML='<span class="bau-slot-item">'+_esc(_itemLabel(items[i]))+'</span>'; slot.title=t(action==='take'?'ui.refugio.retirar_do_bau':'ui.refugio.guardar_no_bau'); slot.onclick=()=>action==='take'?GS.refugioTake(container.dataset.bauScope,i):GS.refugioStore(container.dataset.bauScope,'bag',i); }
    else { slot.disabled=true; slot.innerHTML='<span class="bau-slot-empty">+</span>'; }
    container.appendChild(slot);
  }
}
function _renderRefugioPainel(msg){
  _refugioState=msg; _quartoState=null; _fecharRefugio();
  const ov=document.createElement('div'); ov.id='refugio-overlay'; ov.className='refugio-overlay';
  const sh=msg.shared||{}, me=_heroCityMe(), bag=me?.bag||[], gear=me?.gear||{};
  const rooms=(msg.rooms||[]).map(r=>`<button class="ref-room" data-ref-room="${_esc(r.owner)}"${r.can_edit?' data-ref-mine="1"':''}>🛏️ ${_esc(r.class_id||r.owner)}${r.can_edit?' '+t('ui.refugio.seu_quarto'):''}</button>`).join('')||`<small>${t('ui.refugio.sem_quartos')}</small>`;
  ov.innerHTML=`<section class="refugio-box"><header><div><h2>${t('ui.refugio.titulo')}</h2><small>${t('ui.refugio.subtitulo', {n:sh.items?.length||0, max:sh.slot_limit||10, ouro:sh.gold||0})}</small></div><button data-ref-close>✕</button></header><div class="refugio-grid"><div><h3>${t('ui.refugio.bau_compartilhado')}</h3><div class="ref-list">${(sh.items||[]).map((it,i)=>`<div class="ref-item"><span>${_esc(_itemLabel(it))}</span><button data-ref-take="${i}">${t('ui.refugio.retirar')}</button></div>`).join('')||`<small>${t('ui.refugio.vazio')}</small>`}</div><div class="ref-gold"><input id="ref-shared-gold" type="number" min="0" value="0"><button data-ref-gold="deposit">${t('ui.refugio.depositar_ouro')}</button><button data-ref-gold="withdraw">${t('ui.refugio.retirar_ouro')}</button></div></div><div><h3>${t('ui.refugio.guardar_itens')}</h3><div class="ref-list">${bag.map((it,i)=>`<div class="ref-item"><span>${_esc(_itemLabel(it))}</span><button data-ref-store="${i}">${t('ui.refugio.guardar')}</button></div>`).join('')||`<small>${t('ui.refugio.bolsa_vazia')}</small>`}</div><h3>${t('ui.refugio.quartos_privados')}</h3><div class="ref-rooms">${rooms}</div></div></div><footer><button data-ref-close>${t('ui.refugio.voltar_cidade')}</button></footer></section>`;
  document.body.appendChild(ov);
  // Os dois baús entram como botão no topo: o pessoal só pela lista de quartos era
  // fácil demais de ler como "visitar o quarto de alguém" em vez de "abrir meu baú".
  if(typeof InventoryModal!=='undefined'){
    const box=ov.querySelector('.refugio-box'), antes=ov.querySelector('.refugio-grid');
    const botao=(txt,fn)=>{const b=document.createElement('button');b.className='ref-chest-open';b.textContent=txt;b.onclick=fn;box?.insertBefore(b,antes);};
    botao(t('ui.cena.bau_compartilhado'),()=>InventoryModal.openStorage('shared',msg));
    if((msg.rooms||[]).some(r=>r.can_edit)) botao(t('ui.refugio.abrir_bau_heroi'),()=>_abrirBauDireto('room'));
  }
  ov.querySelectorAll('[data-ref-close]').forEach(b=>b.onclick=_fecharRefugio);
  const lists=ov.querySelectorAll('.ref-list'); if(lists[0]){lists[0].dataset.bauScope='shared';_renderBauSlots(lists[0],sh.items||[],Number(sh.slot_limit)||10,'take');} if(lists[1]){lists[1].dataset.bauScope='shared';_renderBauSlots(lists[1],bag,Math.max(6,bag.length),'store');}
  const refBox=ov.querySelector('.refugio-box'); if(refBox && (msg.shared?.background_external || msg.shared?.background_common)){ refBox.style.backgroundImage=`linear-gradient(#0005,#0008),url('${_assetURL(msg.shared.background_external || msg.shared.background_common)}')`; const common=refBox.querySelector('.refugio-grid > div:first-child'); if(common && msg.shared.background_common) common.style.backgroundImage=`linear-gradient(#0005,#0008),url('${_assetURL(msg.shared.background_common)}')`; }
  const refTitle=ov.querySelector('h2'); if(refTitle) refTitle.textContent=t('ui.cena.bau_compartilhado_titulo');
  ov.querySelectorAll('[data-ref-store]').forEach(b=>b.onclick=()=>GS.refugioStore('shared','bag',Number(b.dataset.refStore)));
  ov.querySelectorAll('[data-ref-take]').forEach(b=>b.onclick=()=>GS.refugioTake('shared',Number(b.dataset.refTake)));
  ov.querySelectorAll('.ref-item').forEach(row=>row.onclick=e=>{if(e.target.closest('button'))return; const take=row.querySelector('[data-ref-take]'), store=row.querySelector('[data-ref-store]'); if(take)GS.refugioTake('shared',Number(take.dataset.refTake)); else if(store)GS.refugioStore('shared','bag',Number(store.dataset.refStore));});
  // O SEU quarto abre direto o baú pessoal (mesma janela dividida do compartilhado);
  // o quarto alheio abre o painel de visita, que não traz os itens.
  ov.querySelectorAll('[data-ref-room]').forEach(b=>b.onclick=()=>b.dataset.refMine?_abrirBauDireto('room'):GS.openQuarto(b.dataset.refRoom));
  ov.querySelectorAll('[data-ref-gold]').forEach(b=>b.onclick=()=>{const n=Number(ov.querySelector('#ref-shared-gold')?.value||0);GS.refugioGold('shared',b.dataset.refGold,n);});
}
function _renderQuartoPainel(msg){
  _quartoState=msg; document.getElementById('quarto-overlay')?.remove();
  const ov=document.createElement('div'); ov.id='quarto-overlay'; ov.className='refugio-overlay';
  const editable=!!msg.can_edit, items=msg.items||[];
  const options=(msg.backgrounds||[]).map(x=>`<option value="${_esc(x)}"${x===msg.background?' selected':''}>${_esc(x)}</option>`).join('');
  ov.innerHTML=`<section class="refugio-box quarto-box" style="${msg.background?`background-image:linear-gradient(#0005,#0008),url('${_assetURL(msg.background)}')`:''}"><header><div><h2>${t('ui.refugio.quarto_de', {nome:_esc(msg.class_id||msg.owner||t('ui.refugio.aventureiro'))})}</h2><small>${t(editable?'ui.refugio.espaco_privado':'ui.refugio.somente_visual')} · ${t('ui.refugio.renome_individual', {n:msg.renome_individual||0})}</small></div><button data-q-close>✕</button></header><div class="refugio-grid"><div><h3>${t('ui.refugio.bau_privado')} ${editable?`(${items.length}/${msg.slot_limit||3})`:''}</h3>${editable?`<small>${t('ui.refugio.bau_privado_desc', {n:msg.slot_limit||3, ouro:msg.gold||0})}</small>`:`<small>${t('ui.refugio.bau_privado_alheio')}</small>`}</div><div><h3>${t('ui.refugio.trofeus')}</h3><div class="ref-trophies">${(msg.trophies||[]).map(tr=>`<span title="${_esc(tr.id||'')}">${_esc(tr.emoji||'🏆')}</span>`).join('')||`<small>${t('ui.refugio.sem_trofeu')}</small>`}</div>${editable&&options?`<label>${t('ui.refugio.fundo_quarto')}<select id="q-bg">${options}</select></label><button data-q-bg>${t('ui.refugio.aplicar_fundo')}</button>`:''}</div></div><footer><button data-q-close>${t('ui.refugio.voltar_refugio')}</button></footer></section>`;
  document.body.appendChild(ov);
  if(typeof InventoryModal!=='undefined' && editable){ const chest=document.createElement('button'); chest.className='ref-chest-open'; chest.textContent=t('ui.refugio.abrir_bau_heroi'); chest.onclick=()=>InventoryModal.openStorage('room',msg); ov.querySelector('.refugio-box')?.insertBefore(chest,ov.querySelector('.refugio-grid')); }
  // O baú pessoal (itens + ouro) mora na janela dividida — aqui ficam só troféus
  // e o fundo do quarto. Duas telas para os mesmos 3 espaços era o que confundia.
  ov.querySelectorAll('[data-q-close]').forEach(b=>b.onclick=()=>{ov.remove(); if(_refugioState)_renderRefugioPainel(_refugioState);});
  if(editable){ const bg=ov.querySelector('[data-q-bg]'); if(bg)bg.onclick=()=>GS.quartoCustomize(ov.querySelector('#q-bg').value,msg.trophies); }
}

let _cdeFechar = null; // fecha (e limpa o listener de Esc) do quadro atualmente aberto, se houver

// Ponto único de fechamento: usado tanto pelo próprio quadro (botão/backdrop/Esc)
// quanto por quem precisa fechá-lo de fora (novo city_state, entrar na masmorra).
// Sempre passar por aqui em vez de remover o elemento direto — senão o listener
// de Esc do quadro fica pendurado no documento até a próxima reabertura.
function _fecharEntradaMasmorra(){
  if(_cdeFechar) _cdeFechar();
  else document.getElementById('city-dungeon-entry')?.remove();
}

// Quadro de confirmação da entrada de masmorra colocada na ilustração da cidade.
// Mostra o mesmo conteúdo do painel do mapa-múndi (custo, etapa, requisito) sem
// precisar abrir o mapa; o "Entrar" é o mesmo botão, restrito ao anfitrião.
function abrirEntradaMasmorra(adventure, titulo){
  _fecharEntradaMasmorra();
  const info = _adventureInfo(adventure);
  const wrap = document.createElement('div'); wrap.id = 'city-dungeon-entry';
  const box = document.createElement('div'); box.className = 'cde-box';
  const h = document.createElement('h3'); h.textContent = '🚪 ' + (titulo || adventure.nome);
  box.appendChild(h);
  const panel = document.createElement('div'); panel.className = 'worldmap-location-info';
  panel.innerHTML = info.html;
  // _adventureGoButton PRECISA do bloco `world`: ele monta a transição visual a
  // partir da cidade atual. Chamar sem ele estoura dentro do onclick, depois de
  // o botão já ter virado "Iniciando expedição…" — trava mudo, sem enviar nada.
  if(!info.completed) panel.appendChild(_adventureGoButton(adventure, _worldOfCityState()));
  box.appendChild(panel);
  const back = document.createElement('button'); back.className = 'btn-cancel';
  back.textContent = t('ui.mundo.voltar');
  box.appendChild(back);
  wrap.appendChild(box);
  document.body.appendChild(wrap);
  _gamepadFocusMapPoint('#city-dungeon-entry .worldmap-travel:not([disabled])', '#city-dungeon-entry .btn-cancel');
  const fechar = () => { document.removeEventListener('keydown', onKey); wrap.remove(); if(_cdeFechar === fechar) _cdeFechar = null; };
  const onKey = e => { if(e.key === 'Escape') fechar(); };
  document.addEventListener('keydown', onKey);
  back.onclick = fechar;
  wrap.addEventListener('click', e => { if(e.target === wrap) fechar(); });
  _cdeFechar = fechar;
}

function destroyCityImage(){
  if(_cityImg){
    if(_cityImg.raf) cancelAnimationFrame(_cityImg.raf);
    if(_cityImg.stage && _cityImg.stage.parentNode) _cityImg.stage.parentNode.removeChild(_cityImg.stage);
    _cityImg = null;
  }
  const tb = document.getElementById('city-time-badge');
  if(tb) tb.style.display = '';
  // Remove o overlay preto de transição (senão fica cobrindo a masmorra — o
  // destroyCity3D fazia isso; o modo imagem precisa fazer o mesmo).
  const fo = document.getElementById('city-fade-overlay');
  if(fo) fo.remove();
}

// ── Mapa-múndi / viagem entre cidades ─────────────────────────────────────
let _worldMapEl = null;

function _worldOfCityState(){ return (GS.cityState && GS.cityState.world) || null; }

function _refreshCityLocation(msg){
  if(!_cityImg) return;
  const world = msg && msg.world;
  const location = world && (world.locations || []).find(l => l.id === world.location);
  if(!location) return;
  // O quadro da entrada de masmorra é montado a partir de um snapshot do
  // destino; um city_state novo pode mudar progresso, requisito ou anfitrião,
  // então ele fecha e o jogador reabre com os dados frescos.
  _fecharEntradaMasmorra();
  const isAlva = location.id === 'alva_e_luz';
  if(_worldMapEl && _worldMapEl.dataset.location && _worldMapEl.dataset.location !== location.id) hideWorldMap();
  _cityImg.img.src = location.imagem + '?v=' + (window.ASSET_VER || '1');
  _cityImg.img.alt = location.nome;
  _cityImg.hotWrap.style.display = '';
  const localShops = (msg.city_shops || {})[location.id] || {};
  const hasShopPoint = id => id === 'ferreiro'
    ? ['ferreiro_weapon','ferreiro_armor','ferreiro_ammo'].some(key => Array.isArray(localShops[key]))
    : Array.isArray(localShops[id]);
  _cityImg.life.style.display = isAlva ? '' : 'none';
  const cityPoints = (msg.city_map_points || {})[location.id] || {};
  const cityScenes = (msg.scenes) || GS.scenes() || {};
  // `cena` não depende de loja alguma existir na cidade — mas depende da cena.
  // Um ponto de cena SEM cena vinculada (a cena foi excluída no editor e o ponto
  // ficou) abriria um modal sem nenhuma aba: nem cena, nem loja. Botão morto na
  // ilustração — melhor não desenhar o marcador.
  // O ponto de masmorra depende do destino vinculado — o servidor já omite do
  // payload o destino oculto/inexistente, então aqui é só a checagem final.
  const worldAdventures = (world.adventures || []);
  const pointAllowed = (type, point) => type === 'caravana' || type === 'guilda' || type === 'refugio'
    || (type === 'dungeon'
      ? !!(point && point.aventura && worldAdventures.some(a => a.id === point.aventura))
      : type === 'cena'
        ? !!(point && point.scene && cityScenes[point.scene])
        : (isAlva || hasShopPoint(type)));
  // CITY_MAP_POINTS é a fonte ÚNICA do que aparece na ilustração: o marcador
  // nativo só é exibido se existir um ponto com o mesmo id. Sem isso ele
  // duplicava o ponto equivalente criado no editor — e ficava num lugar que o
  // editor não tinha como listar nem reposicionar. O servidor semeia os pontos
  // implícitos (Caravana + prédio de cada loja), então nada some por falta deles.
  _cityImg.hotWrap.querySelectorAll('[data-city-point]').forEach(marker => {
    const point = cityPoints[marker.dataset.cityPoint];
    if(!point){
      if(marker.dataset.cityExtra) marker.remove(); else marker.style.display = 'none';
      return;
    }
    const type = point.type || marker.dataset.cityBuilding || marker.dataset.cityPoint;
    marker.style.display = pointAllowed(type, point) ? '' : 'none';
    if(Number.isFinite(Number(point.x)) && Number.isFinite(Number(point.y))){
      marker.style.left = point.x + '%'; marker.style.top = point.y + '%';
    }
  });
  // Pontos criados no editor de cidades. Os prédios nativos continuam usando
  // seus hotspots; estes adicionais podem apontar para qualquer loja existente.
  const pointMeta = {
    ferreiro:{emoji:'⚒'}, mercador:{emoji:'🛒'}, templo:{emoji:'⛪'},
    taverna:{emoji:'🍺'}, guilda:{emoji:'⚔'}, caravana:{emoji:'🧭'},
    dungeon:{emoji:'🚪'}, cena:{emoji:'💬'}, refugio:{emoji:'🏰'}
  };
  Object.entries(cityPoints).forEach(([id, point]) => {
    if (_cityImg.hotWrap.querySelector('[data-city-point="' + id + '"]') || !point || !point.type) return;
    const meta = pointMeta[point.type]; if(!meta) return;
    if(!pointAllowed(point.type, point)) return;
    const btn = document.createElement('button'); btn.type='button';
    btn.className='city-hotspot city-building city-map-point' + (point.type === 'dungeon' ? ' dungeon' : '');
    btn.dataset.cityBuilding=point.type; btn.dataset.cityPoint=id; btn.dataset.cityExtra='1'; btn.style.left=point.x+'%'; btn.style.top=point.y+'%';
    // `point.name` é do AUTOR (editor de cidades) e vence — conteúdo autoral
    // não é traduzido. Sem ele, cai no rótulo do tipo.
    const label=point.name || _rotulo(point.type, 'ui.cidade.ponto', point.type);
    if(point.name) btn.dataset.cityNomeAutoral = '1';
    btn.title=label; btn.setAttribute('aria-label',label);
    // O emoji do próprio ponto (escolhido no editor) manda sobre o do tipo.
    const emoji = point.emoji || meta.emoji;
    btn.innerHTML='<span class="ch-glow" aria-hidden="true"></span><span class="ch-pin"><span class="ch-emoji">'+emoji+'</span><span class="ch-name">'+label+'</span></span>';
    btn.addEventListener('click',()=>_cityHotspotClick(id, point.type)); _cityImg.hotWrap.appendChild(btn);
  });
  const cityHost = _cityImg.stage.parentElement;
  let nav = cityHost.querySelector('#city-world-nav');
  if(!nav){
    nav = document.createElement('button'); nav.id = 'city-world-nav'; nav.type = 'button';
    nav.textContent = t('ui.cidade.mapa_mundi'); nav.onclick = showWorldMap;
    cityHost.appendChild(nav);
  }
  nav.style.display = 'none';
  let caravanEdit = cityHost.querySelector('#city-caravan-edit');
  if(!caravanEdit){
    caravanEdit = document.createElement('button'); caravanEdit.id = 'city-caravan-edit'; caravanEdit.type = 'button';
    caravanEdit.onclick = () => {
      if(_cityPointDraft){
        _cityPointDraft = null; _cityPointDraggingId = null;
        _cityImg.hotWrap.classList.remove('editing');
        caravanEdit.textContent = t('ui.cidade.ajustar_pontos');
        document.getElementById('city-points-save')?.remove();
        _refreshCityLocation(GS.cityState);
        return;
      }
      _cityPointDraft = {};
      _cityImg.hotWrap.querySelectorAll('[data-city-point]').forEach(marker => {
        if(marker.style.display !== 'none') _cityPointDraft[marker.dataset.cityPoint] = {
          x: parseFloat(marker.style.left), y: parseFloat(marker.style.top),
        };
      });
      _cityImg.hotWrap.classList.add('editing');
      caravanEdit.textContent = t('ui.cidade.cancelar_ajuste');
      const save = document.createElement('button'); save.id = 'city-points-save'; save.type = 'button'; save.textContent = t('ui.cidade.salvar_pontos');
      save.onclick = () => {
        GS.saveCityMapPoints(location.id, _cityPointDraft);
        _cityPointDraft = null; _cityPointDraggingId = null;
        _cityImg.hotWrap.classList.remove('editing');
        save.remove(); caravanEdit.textContent = t('ui.cidade.ajustar_pontos');
      };
      cityHost.appendChild(save);
      toast(t('ui.cidade.arraste_pontos'));
    };
    cityHost.appendChild(caravanEdit);
  }
  caravanEdit.textContent = t(_cityPointDraft ? 'ui.cidade.cancelar_ajuste' : 'ui.cidade.ajustar_pontos');
  // O posicionamento dos pontos é autoral e ocorre somente no Editor.
  // Remove também qualquer botão deixado por uma versão anterior.
  caravanEdit.remove();
  const seal = document.getElementById('city-seal');
  if(seal) seal.textContent = location.nome;
}

function hideWorldMap(){ if(_worldMapEl) _worldMapEl.style.display = 'none'; }

function _worldRouteCost(world, from, to){
  return (world.routes || []).find(r => (r.from === from && r.to === to) || (r.from === to && r.to === from));
}

let _worldMapEditPoints = null;
let _cityTravelTransition = null;

function _preloadImage(path){
  return new Promise(resolve => { const img=new Image(); img.onload=img.onerror=resolve; img.src=_assetURL(path); });
}

function _showCityTravelTransition(world, destination, durationMs=3000){
  const images=(world.transition_images || []);
  const art=images.length ? images[Math.floor(Math.random()*images.length)] : '';
  const destinationImage=destination && destination.imagem || '';
  const destinationName=destination && destination.nome || '';
  const duration=Math.max(0, Number(durationMs) || 3000);
  let overlay=document.getElementById('city-travel-transition');
  if(!overlay){ overlay=document.createElement('div'); overlay.id='city-travel-transition'; document.body.appendChild(overlay); }
  overlay.innerHTML=`<div class="city-travel-art"></div><div class="city-travel-shade"></div><div class="city-travel-copy"><b>${t('ui.mundo.em_viagem')}</b><span>${t('ui.mundo.rumo_a', {nome:destinationName})}</span></div>`;
  const artEl=overlay.querySelector('.city-travel-art');
  artEl.style.backgroundImage=art ? 'url("'+_assetURL(art)+'")' : 'none';
  artEl.style.animationDuration=duration+'ms';
  overlay.classList.add('open');
  const token={}; _cityTravelTransition=token;
  Promise.all([destinationImage ? _preloadImage(destinationImage) : Promise.resolve(), new Promise(resolve=>setTimeout(resolve,duration))]).then(()=>{
    if(_cityTravelTransition!==token) return;
    overlay.classList.remove('open');
    // Zerar o token mora DENTRO do timeout. O elemento é reaproveitado por id,
    // então a comparação existe para não arrancar da tela uma transição nova que
    // tenha começado durante estes 350 ms de fade. Zerando antes, a comparação
    // nunca batia: o overlay saía de vista mas ficava no DOM, um nó por viagem.
    setTimeout(() => {
      if(_cityTravelTransition !== token) return;
      overlay.remove();
      _cityTravelTransition = null;
    }, 350);
  });
}

function showWorldLocationPreview(world, loc){
  if(!_worldMapEl) return;
  const route = _worldRouteCost(world, world.location, loc.id);
  _worldMapEl.innerHTML = '';
  const frame = document.createElement('div'); frame.id = 'worldmap-location-frame';
  const img = document.createElement('img'); img.src = loc.imagem; img.alt = loc.nome; frame.appendChild(img);
  const title = document.createElement('div'); title.className = 'worldmap-location-title'; title.textContent = loc.nome; frame.appendChild(title);
  const back = document.createElement('button'); back.className = 'worldmap-back'; back.textContent = t('ui.mundo.voltar_mapa'); back.onclick = showWorldMap; frame.appendChild(back);
  const panel = document.createElement('div'); panel.className = 'worldmap-location-info';
  if(loc.id === world.location){
    panel.innerHTML = `<b>${t('ui.mundo.local_atual')}</b><small>${t('ui.mundo.local_atual_desc')}</small>`;
  } else if(route){
    panel.innerHTML = `<b>${t('ui.mundo.rota_disponivel')}</b><small>${t('ui.mundo.rota_disponivel_desc', {fome:route.fome, sede:route.sede})}</small>`;
    const go = document.createElement('button'); go.className = 'worldmap-travel'; go.textContent = t('ui.mundo.viajar_para', {nome:loc.nome});
    go.disabled = GS.myPid !== GS.cityState.host;
    go.title = go.disabled ? t('ui.mundo.so_anfitriao_viagem') : '';
    go.onclick = () => {
      go.disabled=true; _showCityTravelTransition(world, loc); GS.worldTravel(loc.id);
    };
    panel.appendChild(go);
  } else {
    panel.innerHTML = `<b>${t('ui.mundo.local_distante')}</b><small>${t('ui.mundo.local_distante_desc')}</small>`;
  }
  frame.appendChild(panel);
  _worldMapEl.appendChild(frame);
  _gamepadFocusMapPoint('.worldmap-travel:not([disabled])', '.worldmap-back');
}

// Fragmentos de requisito ("renome 3", "informação: …"), compartilhados pelo
// destino de aventura e pela conversa de NPC — as duas telas mostravam a mesma
// lista com uma diferença boba ("nível de grupo" × "nível do grupo"). O id
// autoral (item/fato/rota) segue CRU: é conteúdo do autor, fora da etapa 5.
function _requisitoPartes(req){
  req = req || {};
  return [
    Number(req.renome_min) > 0      ? t('ui.mundo.req_renome', {n:req.renome_min})      : '',
    Number(req.nivel_grupo_min) > 0 ? t('ui.mundo.req_nivel', {n:req.nivel_grupo_min})  : '',
    req.item_id                     ? t('ui.mundo.req_item', {id:req.item_id})          : '',
    req.fato                        ? t('ui.mundo.req_info', {id:req.fato})             : '',
    req.aventura_id                 ? t('ui.mundo.req_rota', {id:req.aventura_id})      : '',
  ].filter(Boolean);
}

// Regras de exibição de um destino de masmorra — compartilhadas pelo painel do
// mapa-múndi e pelo quadro da entrada colocada na ilustração da cidade. As duas
// telas leem daqui para nunca divergirem em custo/etapa/requisito.
function _adventureInfo(adventure){
  const count = (adventure.dungeons || []).length;
  const progress = Math.max(0, Number(adventure.progresso || 0));
  const completed = count > 0 && progress >= count;
  const req = adventure.requisito || {};
  const reqText = _requisitoPartes(req);
  const html = completed
    ? `<b>${t('ui.mundo.rota_concluida')}</b><small>${t('ui.mundo.rota_concluida_desc', {n:count})}</small>`
    : `<b>${t('ui.mundo.entrada_masmorra')}</b><small>${t('ui.mundo.entrada_masmorra_desc', {fome:adventure.fome || 0, sede:adventure.sede || 0})}${count > 1 ? ' ' + t('ui.mundo.proxima_etapa', {atual:progress + 1, total:count}) : ''}${reqText.length ? ' ' + t('ui.mundo.requisito', {lista:reqText.join(' · ')}) : ''}</small>`;
  return {count, progress, completed, html};
}

function _adventureGoButton(adventure, world){
  const go = document.createElement('button');
  go.className = 'worldmap-travel';
  go.textContent = t('ui.mundo.entrar_em', {nome: adventure.nome});
  go.disabled = GS.myPid !== GS.cityState.host;
  go.title = go.disabled ? t('ui.mundo.so_anfitriao_expedicao') : '';
  go.onclick = () => {
    go.disabled = true; go.textContent = t('ui.mundo.iniciando_expedicao');
    // Quando a etapa não tem uma cena narrativa válida, reaproveita a mesma
    // transição visual usada nas viagens entre cidades. A decisão sobre a
    // existência da cena vem do servidor; a cena, quando existe, abre antes
    // da troca para a tela da masmorra.
    if(adventure.entry_scene_available !== true){
      const current=(world.locations||[]).find(loc=>loc.id===world.location) || {};
      _showCityTravelTransition(world, Object.assign({}, current, {nome:adventure.nome}));
    }
    GS.worldAdventure(adventure.id);
  };
  return go;
}

function showWorldAdventurePreview(world, adventure){
  if(!_worldMapEl) return;
  _worldMapEl.innerHTML = '';
  const frame = document.createElement('div'); frame.id = 'worldmap-location-frame';
  const img = document.createElement('img'); img.src = world.map_image; img.alt = t('ui.mundo.alt_mapa_simples'); frame.appendChild(img);
  const title = document.createElement('div'); title.className = 'worldmap-location-title'; title.textContent = '⚔ ' + adventure.nome; frame.appendChild(title);
  const back = document.createElement('button'); back.className = 'worldmap-back'; back.textContent = t('ui.mundo.voltar_mapa'); back.onclick = showWorldMap; frame.appendChild(back);
  const panel = document.createElement('div'); panel.className = 'worldmap-location-info';
  const info = _adventureInfo(adventure);
  panel.innerHTML = info.html;
  if(!info.completed) panel.appendChild(_adventureGoButton(adventure, world));
  frame.appendChild(panel); _worldMapEl.appendChild(frame);
  _gamepadFocusMapPoint('.worldmap-travel:not([disabled])', '.worldmap-back');
}

function showWorldMap(){
  const world = _worldOfCityState();
  if(!world) return;
  // Marcadores do mapa-múndi só podem ser reposicionados no Editor.
  _worldMapEditPoints = null;
  const editing = false;
  if(!_worldMapEl){
    _worldMapEl = document.createElement('div'); _worldMapEl.id = 'worldmap-overlay';
    document.getElementById('screen-city').appendChild(_worldMapEl);
  }
  _worldMapEl.style.display = 'block';
  _worldMapEl.dataset.location = world.location;
  _worldMapEl.innerHTML = '';
  const frame = document.createElement('div'); frame.id = 'worldmap-frame';
  const img = document.createElement('img'); img.src = world.map_image; img.alt = t('ui.mundo.alt_mapa');
  frame.appendChild(img);
  const title = document.createElement('div'); title.className = 'worldmap-title'; title.textContent = t('ui.mundo.titulo'); frame.appendChild(title);
  const back = document.createElement('button'); back.className = 'worldmap-back'; back.textContent = t('ui.mundo.voltar_cidade'); back.onclick = hideWorldMap; frame.appendChild(back);
  if(false && GS.myPid === GS.cityState.host){
    const edit = document.createElement('button'); edit.className = 'worldmap-edit';
    edit.textContent = editing ? t('ui.mundo.cancelar_ajuste') : t('ui.mundo.ajustar_pontos');
    edit.onclick = () => {
      _worldMapEditPoints = editing ? null : Object.fromEntries((world.locations || []).map(l => [l.id, {x:l.x, y:l.y}]));
      showWorldMap();
    };
    frame.appendChild(edit);
  }
  const info = document.createElement('div'); info.className = 'worldmap-info';
  const current = (world.locations || []).find(l => l.id === world.location);
  info.innerHTML = editing
    ? `<b>${t('ui.mundo.ajuste_pontos')}</b><small>${t('ui.mundo.ajuste_pontos_desc')}</small>`
    : `<b>${current ? current.nome : t('ui.mundo.local_atual')}</b><small>${t('ui.mundo.escolha_destino_desc')}</small>`;
  if(editing){
    const save = document.createElement('button'); save.className = 'worldmap-travel'; save.textContent = t('ui.mundo.salvar_posicoes');
    save.onclick = () => { GS.saveWorldMapPoints(_worldMapEditPoints); _worldMapEditPoints = null; showWorldMap(); };
    info.appendChild(save);
  }
  frame.appendChild(info);
  let draggingId = null, dragOffsetX = 0, dragOffsetY = 0;
  const setPointFromEvent = e => {
    if(!draggingId) return;
    const rect = frame.getBoundingClientRect();
    const pointerX = ((e.clientX - rect.left) / rect.width) * 100;
    const pointerY = ((e.clientY - rect.top) / rect.height) * 100;
    const x = Math.max(0, Math.min(100, pointerX - dragOffsetX));
    const y = Math.max(0, Math.min(100, pointerY - dragOffsetY));
    _worldMapEditPoints[draggingId] = {x:Math.round(x * 100) / 100, y:Math.round(y * 100) / 100};
    const marker = frame.querySelector('[data-world-location="' + draggingId + '"]');
    if(marker){ marker.style.left = x + '%'; marker.style.top = y + '%'; marker.title = `${marker.dataset.worldName}: ${x.toFixed(1)}%, ${y.toFixed(1)}%`; }
  };
  frame.addEventListener('pointermove', setPointFromEvent);
  frame.addEventListener('pointerup', () => { draggingId = null; });
  frame.addEventListener('pointercancel', () => { draggingId = null; });
  (world.locations || []).forEach(loc => {
    const route = _worldRouteCost(world, world.location, loc.id);
    const marker = document.createElement('button'); marker.type = 'button';
    const point = editing ? _worldMapEditPoints[loc.id] : loc;
    marker.className = 'worldmap-marker' + (loc.id === world.location ? ' current' : '') + (!editing && !route && loc.id !== world.location ? ' locked' : '') + (editing ? ' editing' : '');
    marker.style.left = point.x + '%'; marker.style.top = point.y + '%';
    marker.disabled = false;
    marker.dataset.worldLocation = loc.id; marker.dataset.worldName = loc.nome;
    marker.setAttribute('aria-label', loc.nome);
    marker.title = editing ? `${loc.nome}: ${point.x.toFixed(1)}%, ${point.y.toFixed(1)}%` : loc.nome;
    marker.innerHTML = '<span class="wm-rose">✦</span><span class="wm-name">' + loc.nome + '</span>';
    if(editing){
      marker.onpointerdown = e => {
        const rect = frame.getBoundingClientRect();
        draggingId = loc.id;
        dragOffsetX = ((e.clientX - rect.left) / rect.width) * 100 - point.x;
        dragOffsetY = ((e.clientY - rect.top) / rect.height) * 100 - point.y;
        marker.setPointerCapture?.(e.pointerId);
        e.preventDefault();
      };
      frame.appendChild(marker);
      return;
    }
    marker.onclick = () => showWorldLocationPreview(world, loc);
    frame.appendChild(marker);
  });
  if(!editing) (world.adventures || []).forEach(adventure => {
    const marker = document.createElement('button'); marker.type = 'button';
    marker.className = 'worldmap-marker adventure'; marker.style.left = adventure.x + '%'; marker.style.top = adventure.y + '%';
    marker.dataset.worldName = adventure.nome; marker.setAttribute('aria-label', adventure.nome); marker.title = adventure.nome;
    marker.innerHTML = '<span class="wm-rose">⚔</span><span class="wm-name">' + adventure.nome + '</span>';
    marker.onclick = () => showWorldAdventurePreview(world, adventure); frame.appendChild(marker);
  });
  _worldMapEl.appendChild(frame);
  _gamepadFocusMapPoint('.worldmap-marker.current', '.worldmap-marker');
}

// ── Fase 4b (história): overlay de história da campanha ───────────────────────
// Slideshow de história (layout A): imagem de fundo + texto sobreposto + áudio
// em loop. Cada cliente navega seus próprios slides; "Continuar" no último marca
// o beat como visto (de-dup por key em gameState.js).
let _storyIdx = 0;
let _storyMuted = false;
let _storyAudioEl = null;
const DEFEAT_MUSIC = 'assets/music/derrota.mp3';
let _defeatAudioEl = null;
let _defeatMusicActive = false;

function _defeatAudioStop() {
  if (_defeatAudioEl) {
    try { _defeatAudioEl.pause(); _defeatAudioEl.currentTime = 0; } catch (e) {}
    _defeatAudioEl.src = '';
    _defeatAudioEl = null;
  }
}

function _defeatAudioStart() {
  _defeatAudioStop();
  const audio = new Audio(DEFEAT_MUSIC);
  audio.loop = true;
  audio.preload = 'auto';
  audio.volume = _mmVol;
  _defeatAudioEl = audio;
  audio.play().catch(() => {});
}

function _storyAudioStop() {
  if (_storyAudioEl) { try { _storyAudioEl.pause(); } catch (e) {} _storyAudioEl.src = ''; _storyAudioEl = null; }
}

function _storyPaintMute() {
  const ov = document.getElementById('story-overlay');
  if (ov) ov.querySelector('#story-mute').textContent = _storyMuted ? '🔇' : '🔊';
}

function _storyPaint() {
  const beat = GS.pendingStory && GS.pendingStory();
  const ov = document.getElementById('story-overlay');
  if (!beat || !ov) return;
  const slide = beat.slides[_storyIdx] || {};
  const img = ov.querySelector('#story-img');
  if (slide.image) {
    img.style.backgroundImage = 'url("' + slide.image + '")';
    img.style.backgroundSize = (slide.fit === 'contain') ? 'contain' : 'cover';
  } else {
    img.style.backgroundImage = 'none';
  }
  const txtEl = ov.querySelector('#story-text');
  txtEl.textContent = slide.text || '';
  txtEl.style.display = slide.text ? 'block' : 'none';
  const dots = ov.querySelector('#story-dots');
  dots.innerHTML = '';
  beat.slides.forEach((_, i) => {
    const d = document.createElement('span');
    d.className = 'story-dot' + (i === _storyIdx ? ' on' : '');
    dots.appendChild(d);
  });
  ov.querySelector('#story-prev').style.visibility = _storyIdx > 0 ? 'visible' : 'hidden';
  ov.querySelector('#story-continue').textContent =
    (_storyIdx < beat.slides.length - 1) ? t('ui.hud.continuar') : t('ui.hud.concluir');
  _storyPaintMute();
}

function renderStory() {
  const beat = GS.pendingStory && GS.pendingStory();
  let ov = document.getElementById('story-overlay');
  if (!beat || !beat.slides || !beat.slides.length) {
    if (ov) ov.style.display = 'none';
    _storyAudioStop();
    return;
  }
  if (!ov) {
    ov = document.createElement('div'); ov.id = 'story-overlay';
    ov.innerHTML =
      '<div id="story-img"></div>'
      + '<div id="story-scrim"></div>'
      + '<button id="story-mute" title="Som">🔊</button>'
      + '<div id="story-box">'
      +   '<div id="story-text"></div>'
      +   '<div id="story-nav">'
      +     '<button id="story-prev">' + t('ui.hud.voltar_slide') + '</button>'
      +     '<div id="story-dots"></div>'
      +     '<button id="story-continue">' + t('ui.hud.continuar') + '</button>'
      +   '</div>'
      + '</div>';
    document.body.appendChild(ov);
    ov.querySelector('#story-prev').onclick = () => {
      if (_storyIdx > 0) { _storyIdx--; _storyPaint(); }
    };
    ov.querySelector('#story-continue').onclick = () => {
      const b = GS.pendingStory && GS.pendingStory();
      if (!b) return;
      if (_storyIdx < b.slides.length - 1) { _storyIdx++; _storyPaint(); }
      else {
        GS.marcarStoryVista(b.key);
        _storyAudioStop();
        _defeatMusicActive = false;
        _defeatAudioStop();
        ov.style.display = 'none';
      }
    };
    ov.querySelector('#story-mute').onclick = () => {
      _storyMuted = !_storyMuted;
      if (_storyAudioEl) _storyAudioEl.muted = _storyMuted;
      _storyPaintMute();
    };
  }
  // (Re)inicializa só quando o beat muda — evita resetar o índice/áudio a cada
  // broadcast de game_state (que reenvia a história enquanto ela está aberta).
  if (ov.dataset.key !== beat.key) {
    ov.dataset.key = beat.key;
    _storyIdx = 0;
    beat.slides.forEach(s => { if (s.image) { const im = new Image(); im.src = s.image; } });
    _storyAudioStop();
    if (beat.audio && !_defeatMusicActive) {
      _storyAudioEl = new Audio(beat.audio);
      _storyAudioEl.loop = true; _storyAudioEl.muted = _storyMuted; _storyAudioEl.volume = _mmVol;
      _storyAudioEl.play().catch(() => {});
    }
  }
  ov.style.display = 'block';
  _storyPaint();
}

// ── Cenas da campanha (Visual Novel) ──────────────────────────────────────
// A timeline é reproduzida localmente para cada jogador ler no próprio ritmo.
// Somente escolhas/ramificações vão ao servidor, que aceita a primeira decisão.
let _sceneRun = null;
function _sceneEvent(id){ return _sceneRun && (_sceneRun.scene.events||[]).find(e=>e.id===id); }
function _sceneStart(payload){
  if(!payload || !payload.scene) return;
  const s=payload.scene;
  // game_state/city_state repetem a cena ativa para reconexão. Não reiniciar a
  // timeline de quem já está assistindo cada vez que chega uma atualização.
  if(_sceneRun && _sceneRun.scene && _sceneRun.scene.id===s.id) return;
  _sceneRun={scene:s, id:s.start || ((s.events||[])[0]||{}).id, chars:{}};
  let ov=document.getElementById('campaign-scene-overlay');
  if(!ov){ ov=document.createElement('div'); ov.id='campaign-scene-overlay'; document.body.appendChild(ov); }
  ov.style.display='flex'; _scenePaint();
}
function _sceneApplyVisual(ev){
  if(!ev) return;
  // Cada evento pode ter seu próprio fundo. Ele permanece até outro slide
  // escolher um novo, permitindo cenários diferentes na mesma cena.
  if(ev.data && ev.data.background) _sceneRun.scene.background=ev.data.background;
  if(ev.type==='show_character' && ev.data && ev.data.slot) _sceneRun.chars[ev.data.slot]=ev.data;
  if(ev.type==='hide_character' && ev.data && ev.data.slot) delete _sceneRun.chars[ev.data.slot];
  // Compatibilidade com as primeiras cenas criadas: uma imagem de personagem
  // adicionada por engano a um evento de fundo (mas com slot) não troca o fundo.
  if(ev.type==='background' && ev.data && ev.data.image){
    if(ev.data.slot && /assets\/cenas\/personagens\//.test(ev.data.image)) _sceneRun.chars[ev.data.slot]=ev.data;
    else _sceneRun.scene.background=ev.data.image;
  }
  // Também é permitido associar uma imagem à própria fala; ela entra no slot
  // escolhido (Centro é o padrão), sem apagar o fundo.
  if(ev.type==='dialogue' && ev.data && ev.data.image) _sceneRun.chars[ev.data.slot||'Center']=ev.data;
}
function _sceneAdvance(){
  if(!_sceneRun)return;
  let ev=_sceneEvent(_sceneRun.id), guard=0;
  // Eventos visuais também são slides: não os pule apenas por não serem um
  // diálogo. Assim uma troca de fundo ou imagem aparece antes do próximo.
  while(ev && guard++<40 && !['dialogue','choice','test_cd','end'].includes(ev.type)
    && !(ev.data && (ev.data.image || ev.data.background))){
    _sceneApplyVisual(ev); _sceneRun.id=ev.next; ev=_sceneEvent(_sceneRun.id);
  }
  _scenePaint();
}
function _scenePaint(){
  const ov=document.getElementById('campaign-scene-overlay'); if(!_sceneRun||!ov)return;
  let ev=_sceneEvent(_sceneRun.id);
  // Um diálogo sem "Próximo" também é um fim válido. Antes ele apenas sumia
  // localmente e deixava a sessão autoritativa pausando a masmorra.
  if(!ev){
    ov.innerHTML=`<div class="cscene-shade"></div><div class="cscene-dialog"><div class="cscene-name">${t('ui.cena.fim_titulo')}</div><div class="cscene-text">${t('ui.cena.fim_texto')}</div><div class="cscene-actions"><button class="cscene-finish">${t('ui.cena.fim_botao')}</button></div></div>`;
    ov.querySelector('.cscene-finish').onclick=()=>GS.sceneEnd(false);
    ov.style.display='flex'; return;
  }
  GS.sceneVisit(_sceneRun.scene.id, ev.id);
  _sceneApplyVisual(ev);
  const sceneTransition=['fade','slide_left','slide_right','slide_up','slide_down','zoom','dissolve'].includes((ev.data||{}).transition) ? ev.data.transition : 'fade';
  ov.className='scene-transition-'+sceneTransition;
  ov.innerHTML='<div class="cscene-bg"><img alt=""></div><div class="cscene-shade"></div><div class="cscene-slots"></div><div class="cscene-dialog"><div class="cscene-name"></div><div class="cscene-text"></div><div class="cscene-actions"></div></div><button class="cscene-skip" data-i18n="ui.hud.pular_cena">Pular cena</button>';
  // Imagem real, em vez de somente background-image: é mais confiável no
  // início da cena e torna falhas de carregamento visíveis no navegador.
  const bg=ov.querySelector('.cscene-bg img'); if(_sceneRun.scene.background) bg.src=_sceneRun.scene.background;
  const slots=ov.querySelector('.cscene-slots'); Object.entries(_sceneRun.chars).forEach(([slot,c])=>{const im=document.createElement('img');im.className='cscene-char '+slot+((c.x!=null||c.y!=null||c.w!=null||c.h!=null)?' manual':'');im.src=c.image||'';im.alt=c.name||'';const scale=Math.max(.2,Math.min(2,Number(c.scale)||100)/100);im.style.transform='scale('+scale+')'+(c.flipped?' scaleX(-1)':'');im.style.opacity=Math.max(0,Math.min(1,Number(c.opacity??100)/100));if(c.x!=null)im.style.left=Number(c.x)+'%';if(c.y!=null)im.style.top=Number(c.y)+'%';if(c.w!=null)im.style.width=Number(c.w)+'%';if(c.h!=null)im.style.height=Number(c.h)+'%';if(c.x!=null||c.y!=null){im.style.bottom='auto';im.style.right='auto';}slots.appendChild(im);});
  const name=ov.querySelector('.cscene-name'),text=ov.querySelector('.cscene-text'),actions=ov.querySelector('.cscene-actions');
  name.textContent=ev.speaker||(_sceneRun.scene.name||'Narrador'); text.textContent=ev.text||'';
  if(ev.type==='choice'){
    (ev.data||[]).forEach(o=>{const b=document.createElement('button');b.textContent=o.text||o.id;b.onclick=()=>GS.sceneChoice(_sceneRun.scene.id,ev.id,o.id);actions.appendChild(b);});
  }else if(ev.type==='test_cd'){
    const b=document.createElement('button');b.textContent=t('ui.hud.realizar_teste');b.onclick=()=>GS.sceneTest(_sceneRun.scene.id,ev.id);actions.appendChild(b);
  }else if(ev.type==='end'){
    const b=document.createElement('button');b.textContent=t('ui.hud.concluir');b.onclick=()=>GS.sceneEnd(false);actions.appendChild(b);
  }else{
    const b=document.createElement('button');b.textContent=ev.next?t('ui.hud.continuar_2'):t('ui.hud.concluir_cena');b.onclick=()=>{if(ev.next){_sceneRun.id=ev.next;_sceneAdvance();}else GS.sceneEnd(false);};actions.appendChild(b);
  }
  ov.querySelector('.cscene-skip').onclick=()=>{if(confirm(t('ui.cena.pular_confirm')))GS.sceneEnd(true);};
}
function _sceneBranch(msg){ if(!_sceneRun || msg.scene_id!==_sceneRun.scene.id)return; _sceneRun.id=msg.next; _sceneAdvance(); }
function _sceneEnd(){ const ov=document.getElementById('campaign-scene-overlay');if(ov)ov.style.display='none';_sceneRun=null; }

function handleCityState(msg){
  // O HUD do Mestre (#hud-mestre) só faz sentido dentro da masmorra — some ao
  // voltar pra cidade (senão fica flutuando por cima da tela da cidade, já
  // que o elemento persiste no DOM entre telas até o próximo renderMyPanel).
  const hudM = document.getElementById('hud-mestre');
  if(hudM) hudM.classList.remove('aberto');
  if(window._mpRelogioTimer){ clearInterval(window._mpRelogioTimer); window._mpRelogioTimer = null; }
  _updateCityHeroBar(msg);
  // Legacy player bar (used by shop modal gold display)
  const lbar=$('city-players-bar');
  if(lbar) lbar.innerHTML=msg.players.map(p=>{
    const isMe=p.id===GS.myPid;
    return `<div class="city-pcard${isMe?' me':''}">
      <span>${p.emoji}</span><span class="city-pcard-name">${p.name}</span>
      <span style="color:var(--text2);font-size:.75rem;">${_classeNome(p)}</span>
      <span class="city-pcard-gold">💰 ${p.gold}</span></div>`;
  }).join('');
  // Shop
  if(GS.activeShop) _renderShopItems();
  if(GS.pendingShopOpen){ const s=GS.pendingShopOpen; GS.pendingShopOpen=null; openShop(s); }
  // Monta a cidade conforme o modo (imagem por padrão; 3D como fallback).
  if(CITY_MODE==='image'){
    if(!_cityImg) initCityImage();
    _refreshCityLocation(msg);
  }
  else if(!_city3&&window.THREE){ initCity3D(); }
  // Clear fade overlay if returning from dungeon
  const fo=document.getElementById('city-fade-overlay');
  if(fo){ fo.classList.remove('on'); setTimeout(()=>{ if(fo.parentNode) fo.remove(); },1200); }
  renderStory();   // Fase 4b: encerramento da fase (mostrado na cidade)
}

// Um ponto da ilustração resolve DUAS coisas independentes: uma cena (se o
// ponto tem `scene`) e uma loja (se o tipo do ponto é uma loja que a cidade
// tem). As abas do modal são [aba de cena] + [abas de loja].
function openShop(pointId, type, sceneOverride){
  if(!GS.cityState){
    // city_state not yet received — request it and retry when it arrives
    GS.pendingShopOpen = pointId;
    send({type:'get_city_state'});
    toast(t('ui.loja.carregando'), 'var(--blue)');
    return;
  }
  GS.pendingShopOpen = null;
  const shopId  = type || pointId;
  const sceneId = sceneOverride || GS.sceneIdOfPoint(pointId);
  const scene   = sceneId ? (GS.scenes()[sceneId] || null) : null;
  GS.activeShop = shopId;
  GS.activeScene = scene ? sceneId : null;
  GS.shopTabIdx = 0;
  const modal=$('shop-modal'); if(!modal) return;
  modal.classList.toggle('shop-mercador', shopId==='mercador');
  modal.classList.toggle('shop-taverna', shopId==='taverna');
  modal.classList.add('open');
  // Ponto sem loja (tipo `cena`): título/subtítulo vêm da própria cena.
  $('shop-title').textContent = _rotulo(shopId, 'ui.loja.titulo', '💬 ' + (scene ? (scene.nome || '') : ''));
  $('shop-subtitle').textContent = _rotulo(shopId, 'ui.loja.subtitulo', '');
  // Tabs
  const tabsEl=$('shop-tabs'); tabsEl.innerHTML='';
  // A ORDEM das abas é índice de lógica (GS.shopTabIdx) — traduzir o rótulo é
  // seguro; trocar a ordem não seria.
  const shopTabs = (shopId==='ferreiro'
    ? ['armas','armaduras','municao','reparar','vender']
    : shopId==='mercador'
    ? ['comprar','instrumentos','venenos','pergaminhos','vender']
    : shopId==='taverna'
    ? ['alimentos']
    : []).map(k => t('ui.loja.aba.' + k));
  const tabDefs = (scene ? ['💬 ' + (scene.nome || t('ui.loja.aba.conversas'))] : []).concat(shopTabs);
  tabDefs.forEach((t,i)=>{
    const btn=document.createElement('button');
    btn.className='shop-tab'+(i===GS.shopTabIdx?' active':'');
    btn.textContent=t;
    btn.onclick=()=>{ GS.shopTabIdx=i; _updateShopTabs(); _renderShopItems(); };
    tabsEl.appendChild(btn);
  });
  _renderShopItems();
}

function _updateShopTabs(){
  document.querySelectorAll('.shop-tab').forEach((el,i)=>
    el.classList.toggle('active',i===GS.shopTabIdx));
}

function _gamepadCycleShopTab(direction){
  const modal = $('shop-modal');
  if(!modal?.classList.contains('open') || !GS.activeShop) return false;
  const tabs = [...modal.querySelectorAll('.shop-tab')];
  if(tabs.length < 2) return false;
  const current = Math.max(0, Math.min(tabs.length - 1, Number(GS.shopTabIdx) || 0));
  GS.shopTabIdx = (current + direction + tabs.length) % tabs.length;
  _updateShopTabs();
  _renderShopItems();
  // A troca de aba recria a lista. Dar foco ao primeiro botão acionável evita
  // que Confirmar continue preso em uma compra que acabou de desaparecer.
  requestAnimationFrame(() => {
    const firstAction = modal.querySelector('#shop-items-list .btn-buy:not([disabled]), #shop-items-list .cena-npc, #shop-items-list .cena-back, .shop-tab.active');
    _gamepadSetUiFocus(firstAction || tabs[GS.shopTabIdx] || null);
  });
  _gamepadRumble('target');
  return true;
}

let _openCenaNpcId = null;
function _renderCenaConversas(){
  const list=$('shop-items-list'); if(!list) return;
  const cena = GS.scenes()[GS.activeScene];
  if(!cena){
    list.innerHTML=`<div class="cena-vazia">${t('ui.cena.sem_frequentadores')}</div>`;
    return;
  }
  // A conversa é a única "loja" que vira CENA: o modal ocupa a tela
  // inteira e todo o cromo (voltar, renome, dica, diálogo) flutua por cima da
  // arte, dentro do próprio palco. Sem isso o palco 3:2 disputava altura com o
  // cromo empilhado e a ilustração ficava pequena. Quem tira a classe é o
  // _renderShopItems, no topo, antes de despachar qualquer aba.
  const modal=$('shop-modal'); if(modal) modal.classList.add('modo-cena');
  const scene=document.createElement('div'); scene.className='cena-palco';
  // O palco é 3:2 e o fundo é `object-fit:cover`, exatamente como a prévia do
  // editor (.cityed-tavern-preview). Os slots vão em % crus, sem correção
  // alguma — qualquer transformação aqui sem contraparte no editor faz a
  // máscara/NPC cair fora do lugar em relação ao que o autor posicionou.
  const base=document.createElement('img'); base.className='cena-bg'; base.src=_assetURL(cena.background); base.alt=t('ui.cena.alt_fundo'); scene.appendChild(base);
  // A máscara inteira acompanha o fundo, mantendo a composição original em
  // qualquer tamanho. Os slots seguem acima dela apenas para clique/hover.
  if(cena.mask && cena.mode !== 'individual'){
    const mask=document.createElement('img');
    mask.className='cena-mask-layer'; mask.src=_assetURL(cena.mask); mask.alt='';
    scene.appendChild(mask);
  }
  (cena.slots||[]).forEach(slot=>{
    if(slot.removed || !slot.image) return;
    const npc=document.createElement('button'); npc.type='button'; npc.className='cena-npc';
    npc.style.left=slot.x+'%'; npc.style.top=slot.y+'%';
    npc.style.width=slot.w+'%'; npc.style.height=slot.h+'%';
    npc.style.zIndex=String(10 + Number(slot.z || 1));
    npc.title=slot.name; npc.setAttribute('aria-label',t('ui.cena.conversar_com', {nome:slot.name}));
    if(cena.mask && cena.mode !== 'individual'){
      const maskStyle='width:'+(10000/slot.w)+'%;height:'+(10000/slot.h)+'%;left:'+(-slot.x*100/slot.w)+'%;top:'+(-slot.y*100/slot.h)+'%;';
      npc.innerHTML='<img class="cena-mask" style="'+maskStyle+'" src="'+_assetURL(cena.mask)+'" alt=""><span>'+slot.name+'</span>';
    } else {
      npc.innerHTML='<img src="'+_assetURL(slot.image)+'" alt=""><span>'+slot.name+'</span>';
    }
    npc.onclick=()=>_showCenaDialogo(slot, scene);
    scene.appendChild(npc);
  });
  list.innerHTML='';
  list.appendChild(scene);
  // Barra flutuante no topo da arte: voltar à esquerda, renome à direita.
  const hud=document.createElement('div'); hud.className='cena-hud';
  const back=document.createElement('button');
  back.type='button'; back.className='cena-back'; back.textContent=t('ui.mundo.voltar_cidade');
  back.onclick=closeShop;
  const rep=document.createElement('p'); rep.className='cena-hint'; rep.textContent=t('ui.cena.renome_grupo', {n:Number(((GS.cityState||{}).reputacao||{}).renome||0)});
  hud.appendChild(back); hud.appendChild(rep); scene.appendChild(hud);
  // Refúgio: as cenas formam um caminho — externa → área comum → quarto do herói.
  // Cada cena mostra o baú que existe nela MAIS a porta para a próxima; sem isso a
  // área comum era um beco (só o baú coletivo, nenhuma forma de chegar ao quarto).
  // Cena não vinculada no editor nunca deixa o botão sem resposta: o baú abre direto.
  if(GS.activeShop==='refugio'){
    const refugePoint=Object.values(GS.cityPoints()||{}).find(p=>p.type==='refugio')||{};
    const cenaDe=key=>{const sid=refugePoint[key]; return (sid && GS.scenes()[sid]) ? sid : null;};
    const irPara=(key,semCena)=>{const sid=cenaDe(key); if(sid) openShop('refugio','refugio',sid); else semCena();};
    const isCommon=GS.activeScene===refugePoint.scene_comum, isRoom=GS.activeScene===refugePoint.scene_quarto;
    const acoes=isRoom
      ? [[t('ui.cena.bau_heroi'), ()=>_abrirBauDireto('room')],
         ...(cenaDe('scene_comum') ? [[t('ui.cena.voltar_area_comum'), ()=>irPara('scene_comum',GS.openRefugio)]] : [])]
      : isCommon
        ? [[t('ui.cena.bau_compartilhado'), ()=>_abrirBauDireto('shared')],
           [t('ui.cena.entrar_quarto'), ()=>irPara('scene_quarto',()=>_abrirBauDireto('room'))]]
        : [[t('ui.cena.entrar_refugio'), ()=>irPara('scene_comum',GS.openRefugio)]];
    const baus=document.createElement('div'); baus.className='refugio-scene-baus';
    acoes.forEach(([txt,fn])=>{const b=document.createElement('button'); b.type='button'; b.textContent=txt; b.onclick=fn; baus.appendChild(b);});
    scene.appendChild(baus);
  }
  const hint=document.createElement('p'); hint.className='cena-hint'; hint.textContent=t('ui.cena.dica_clique'); scene.appendChild(hint);
  const keepOpen=(cena.slots||[]).find(slot=>slot.id===_openCenaNpcId && !slot.removed && slot.image);
  if(keepOpen) _showCenaDialogo(keepOpen, scene);
}

// `host` é o palco (.cena-palco): o painel de diálogo é uma camada sobre a
// arte, não um bloco abaixo dela.
function _showCenaDialogo(slot, host){
  _openCenaNpcId=slot.id;
  let panel=host.querySelector('.cena-dialogo');
  if(!panel){ panel=document.createElement('div'); panel.className='cena-dialogo'; host.appendChild(panel); }
  panel.innerHTML='';
  const title=document.createElement('b'); title.textContent=slot.name; panel.appendChild(title);
  // O painel cobre parte da arte: dá para fechá-lo sem sair da cena.
  const fechar=document.createElement('button');
  fechar.type='button'; fechar.className='cena-dialogo-fechar'; fechar.textContent='✕';
  fechar.title=t('ui.cena.fechar_conversa'); fechar.setAttribute('aria-label',t('ui.cena.fechar_conversa'));
  fechar.onclick=()=>{ _openCenaNpcId=null; panel.remove(); };
  panel.appendChild(fechar);
  const reputation=(GS.cityState&&GS.cityState.reputacao)||{renome:0,fatos:[]};
  // O servidor já normaliza: um NPC que só tem `dialog` chega aqui com uma
  // conversa "inicial" de verdade, e `conversations: []` significa que não
  // sobrou nada que este jogador possa escolher. Sintetizar uma opção aqui
  // ressuscitaria justamente o que o servidor omitiu — e o botão daria erro.
  const conversations = slot.conversations || [];
  const requirementText=_requisitoPartes;
  // O servidor já omite conversa bloqueada ou de uso único resolvida — o que
  // chega aqui é exatamente o que o jogador pode escolher.
  const discovered = conversations;
  if(!discovered.length){
    const waiting=document.createElement('p'); waiting.textContent=t('ui.cena.nada_novo'); panel.appendChild(waiting);
  }
  discovered.forEach(conv=>{
    const block=document.createElement('div'); block.className='cena-dialogo-opcao';
    const reqs=requirementText(conv.requisito);
    const action=document.createElement('button'); action.type='button'; action.className='cena-dialogo-texto'; action.textContent=conv.texto;
    action.title=reqs.length?t('ui.cena.requer', {lista:reqs.join(', ')}):'';
    action.onclick=()=>{ action.disabled=true; action.textContent=t('ui.cena.conversando'); GS.talkSceneNpc(GS.activeScene,slot.id,conv.id); };
    block.appendChild(action);
    const effect=conv.efeito||{}; if(effect.renome||effect.fato||effect.item_id){const effectEl=document.createElement('small');effectEl.className='cena-dialogo-efeito';effectEl.textContent=t('ui.cena.ao_concluir', {lista:[effect.renome?t('ui.mundo.req_renome', {n:(Number(effect.renome)>0?'+':'')+effect.renome}):'',effect.fato?t('ui.mundo.req_info', {id:effect.fato}):'',effect.item_id?t('ui.mundo.req_item', {id:effect.item_id}):''].filter(Boolean).join(' · ')});block.appendChild(effectEl);}
    panel.appendChild(block);
  });
}

// Ícone de item: PNG em assets/itens/<id>.png se existir, senão cai no emoji.
// Pergaminhos têm id dinâmico por magia (pergaminho_<spellId>) — usam sempre
// o mesmo ícone genérico. onerror troca a <img> pelo texto do emoji (sem
// innerHTML, então o emoji nunca é interpretado como HTML).
function itemIconHTML(item, fallbackEmoji){
  const emoji = (item && item.emoji) || fallbackEmoji || '📦';
  if(!item || !item.id) return emoji;
  // Instrumentos do bardo: uma foto por BASE (harpa/tambor/sino/alaude…), que
  // vale para todas as qualidades E para o instrumento equipado (id genérico
  // "instrumento"). Sem isso, o jogo procuraria pelo id do SKU
  // (instrumento_harpa_velho.png) e o Alaúde inicial nunca acharia foto.
  const fileId = item.effect === 'scroll' ? 'pergaminho'
    : (item.tipo_item === 'instrumento' && item.base) ? item.base
    : item.id;
  const src = _assetURL(`assets/itens/${fileId}.png`);
  return `<img src="${src}" alt="" class="item-icon-img" data-fallback="${emoji}" onerror="this.replaceWith(this.dataset.fallback)">`;
}

function _guardarSelecaoLoja(itemId){
  const modal = $('shop-modal');
  const list = $('shop-items-list');
  if(!modal?.classList.contains('open') || !list) return;
  const rows = [...list.querySelectorAll('.shop-item')];
  const focusedRow = _gamepadUi?.focusEl?.closest?.('.shop-item')
    || document.activeElement?.closest?.('.shop-item')
    || rows.find(row => row.dataset.shopItemId === String(itemId));
  const rowIndex = focusedRow ? rows.indexOf(focusedRow) : -1;
  window._shopSelectionRestore = {
    shopId: GS.activeShop,
    tabIdx: GS.shopTabIdx,
    itemId: String(itemId),
    rowIndex,
    scrollTop: list.scrollTop,
    relativeTop: focusedRow ? focusedRow.offsetTop - list.scrollTop : null
  };
}

function _restaurarSelecaoLoja(){
  const restore = window._shopSelectionRestore;
  if(!restore) return;
  const modal = $('shop-modal');
  const list = $('shop-items-list');
  if(!modal?.classList.contains('open') || !list){
    window._shopSelectionRestore = null;
    return;
  }
  if(GS.activeShop !== restore.shopId || GS.shopTabIdx !== restore.tabIdx){
    window._shopSelectionRestore = null;
    return;
  }

  requestAnimationFrame(() => {
    if(window._shopSelectionRestore !== restore) return;
    const rows = [...list.querySelectorAll('.shop-item')];
    const row = rows.find(item => item.dataset.shopItemId === restore.itemId)
      || (restore.rowIndex >= 0 ? rows[restore.rowIndex] : null);
    if(!row){ window._shopSelectionRestore = null; return; }

    // Repõe a mesma linha no mesmo ponto da lista, sem fazer a tela saltar
    // para o topo quando o city_state atualiza ouro/inventário.
    list.scrollTop = restore.relativeTop == null
      ? restore.scrollTop
      : Math.max(0, row.offsetTop - restore.relativeTop);
    const button = [...row.querySelectorAll('.btn-buy')]
      .find(candidate => !candidate.disabled) || row.querySelector('.btn-buy');
    if(button){
      button.focus?.({preventScroll:true});
      if(typeof _gamepadInput !== 'undefined' && _gamepadInput.active)
        _gamepadSetUiFocus(button);
    }
    window._shopSelectionRestore = null;
  });
}

function _renderShopItems(){
  if(!GS.cityState||!GS.activeShop) return;
  // A cena em tela cheia vale só para a aba de conversas (e só quando ela tem
  // arte); quem religa é o próprio _renderCenaConversas.
  const shopModal=$('shop-modal'); if(shopModal) shopModal.classList.remove('modo-cena');
  // A aba de cena, quando existe, ocupa o índice 0; as abas de loja vêm depois.
  // `aba` é o índice RELATIVO à loja — use-o em toda comparação de aba de loja.
  const temCena = !!GS.activeScene;
  if(temCena && GS.shopTabIdx===0){ _renderCenaConversas(); return; }
  const aba = GS.shopTabIdx - (temCena ? 1 : 0);
  // Route sell tabs
  if(GS.activeShop==='ferreiro'&&aba===3){ _renderRepairItems(); return; }
  // Todas as abas de venda exibem o inventário completo: equipamento e bolsa.
  // A venda continua autoritativa no servidor, independentemente da loja.
  if(GS.activeShop==='ferreiro'&&aba===4){ _renderSellItems('all'); return; }
  if(GS.activeShop==='mercador'&&aba===4){ _renderSellItems('all'); return; }

  const myP=GS.cityState.players.find(p=>p.id===GS.myPid);
  const gold=myP?myP.gold:0;
  const goldEl=$('shop-gold-val'); if(goldEl) goldEl.textContent=gold;

  const shops=GS.cityState.shops;
  let items=[], shopKey=GS.activeShop;
  if(GS.activeShop==='ferreiro'){
    if(aba===0)      { items=shops.ferreiro.weapons; shopKey='ferreiro_weapon'; }
    else if(aba===1) { items=shops.ferreiro.armors;  shopKey='ferreiro_armor';  }
    else                       { items=shops.ferreiro.ammo;    shopKey='ferreiro_ammo';   }
  } else if(GS.activeShop==='mercador') {
    const mercadorItems=shops.mercador||[];
    if(aba===1) {
      items=mercadorItems.filter(item=>item.tipo_item==='instrumento');
    } else if(aba===2) {
      items=mercadorItems.filter(item=>item.effect==='coat_poison');
    } else if(aba===3) {
      items=mercadorItems.filter(item=>item.effect==='scroll');
    } else {
      // Itens gerais: mantém o mercado normal sem duplicar as categorias próprias.
      items=mercadorItems.filter(item=>item.tipo_item!=='instrumento'
        && item.effect!=='coat_poison' && item.effect!=='scroll');
    }
  } else {
    items=shops[GS.activeShop]||[];
  }

  const myClass = myP?myP.class_id:null;
  const list=$('shop-items-list'); if(!list) return;
  list.innerHTML=items.map(item=>{
    // Restrição de classe: allowed_classes ausente = todas as classes.
    const classRestrita = item.allowed_classes && myClass && !item.allowed_classes.includes(myClass);
    // Refeição de balcão (1×/visita): bloqueia se o herói já a pediu nesta visita.
    const jaUsada = item.effect==='meal_survival'
      && myP && (myP.taverna_refeicoes||[]).includes(item.id);
    const jaConhecida = item.effect==='learn_spell'
      && myP && (myP.magias_conhecidas||[]).includes(item.magia_id);
    const canBuy=gold>=item.price && !classRestrita && !jaUsada && !jaConhecida;
    const desc=_itemDesc(item);
    const kindTag=item.kind==='shield'?`<span style="color:var(--blue);font-size:.68rem;"> [${t('ui.loja.escudo')}]</span>`:'';
    const restritaTag=classRestrita?`<span style="color:var(--danger,#ff4136);font-size:.68rem;"> 🚫 ${t('ui.loja.classe_restrita')}</span>`:'';
    const usadaTag=jaUsada?`<span style="color:var(--muted,#888);font-size:.68rem;"> ✔ ${t('ui.loja.ja_usada')}</span>`:'';
    const conhecidaTag=jaConhecida?`<span style="color:var(--muted,#888);font-size:.68rem;"> ✔ ${t('ui.loja.ja_conhecida')}</span>`:'';
    return `<div class="shop-item" data-shop-item-id="${item.id}"${(classRestrita||jaUsada||jaConhecida)?' style="opacity:.5;"':''}>
      <span class="shop-item-emoji">${itemIconHTML(item)}</span>
      <div class="shop-item-info">
        <div class="shop-item-name">${item.name}${kindTag}${restritaTag}${usadaTag}${conhecidaTag}</div>
        <div class="shop-item-desc">${desc}</div>
      </div>
      <span class="shop-item-price">💰 ${item.price}</span>
      <button class="btn-buy" ${canBuy?'':'disabled'}
        title="${classRestrita?t('ui.loja.title_classe_restrita'):jaUsada?t('ui.loja.title_ja_usada'):jaConhecida?t('ui.loja.title_ja_conhecida'):''}"
        onclick="buyItem('${shopKey}','${item.id}')">${classRestrita?'🚫 '+t('ui.loja.restrito'):jaUsada?'✔ '+t('ui.loja.usada'):jaConhecida?'✔ '+t('ui.loja.conhecida'):t('ui.loja.comprar')}</button>
    </div>`;
  }).join('');
  // Tooltip de pergaminho (hover) — a loja usa innerHTML, então anexa por índice.
  const rows = list.querySelectorAll('.shop-item');
  items.forEach((item, idx) => {
    if(!rows[idx]) return;
    if(item.effect === 'scroll') aplicarTooltipPergaminho(rows[idx], item);
    else aplicarTooltipAoItemDados(rows[idx], item);
  });
  if(shopKey === 'templo' && myP && (myP.maldicoes||[]).length){
    // Os nomes das maldições saíram do mapa {id: 'texto'} e viraram chaves
    // ui.maldicao.<id> — maldição não é família de catálogo (ver CLAUDE.md,
    // etapa 4c), então não há cat.* e o caminho é o _rotulo.
    const precos={leve:150,media:400,grave:800};
    list.insertAdjacentHTML('beforeend',(myP.maldicoes||[]).map(m=>`<div class="shop-item"><span class="shop-item-emoji">☠️</span><div class="shop-item-info"><div class="shop-item-name">${t('ui.loja.remover_maldicao',{nome:_rotulo(m.id,'ui.maldicao',m.id)})}</div><div class="shop-item-desc">${t('ui.loja.desc_remover_maldicao')}</div></div><button class="btn-buy" onclick="removerMaldicaoTemplo('${m.id}')">${t('ui.loja.curar')}</button></div>`).join(''));
  }
}

function _renderSellItems(mode){
  const myP=GS.cityState&&GS.cityState.players.find(p=>p.id===GS.myPid);
  const gold=myP?myP.gold:0;
  const goldEl=$('shop-gold-val'); if(goldEl) goldEl.textContent=gold;
  const list=$('shop-items-list'); if(!list) return;
  if(!myP){ list.innerHTML=''; return; }

  const sellable=[];
  if(mode==='gear'||mode==='all'){
    const w=myP.gear&&myP.gear.weapon;
    if(w&&w.id!=='unarmed'){
      const bp=w.buy_price||0;
      sellable.push({slot:'weapon',item:w,sp:Math.max(1,Math.floor(bp/3)),tag:t('ui.loja.tag.arma_equipada')});
    }
    const a=myP.gear&&myP.gear.armor;
    if(a&&a.id&&a.id!=='cloak'){
      const bp=a.buy_price||0;
      sellable.push({slot:'armor',item:a,sp:Math.max(1,Math.floor(bp/3)),tag:t('ui.loja.tag.armadura_equipada')});
    }
    for(const slot of ['off_hand','head','boots','ring1','ring2','item1','item2']){
      const acc=myP.gear&&myP.gear[slot];
      if(acc){
        const bp=acc.buy_price||0;
        sellable.push({slot,item:acc,sp:Math.max(1,Math.floor(bp/3)),tag:_rotulo(slot, 'ui.loja.tag', t('ui.loja.tag.acessorio'))});
      }
    }
  }
  if(mode==='bag'||mode==='all'){
    (myP.bag||[]).forEach((bagItem,i)=>{
      const bp=bagItem.buy_price||bagItem.price||0;
      sellable.push({slot:`bag_${i}`,item:bagItem,sp:Math.max(1,Math.floor(bp/3)),tag:t('ui.loja.tag.mochila')});
    });
  }

  if(sellable.length===0){
    list.innerHTML='<div style="color:var(--text2);padding:20px;text-align:center;font-size:.82rem;">'+t('ui.loja.nenhum_item_para_vender')+'</div>';
    return;
  }
  list.innerHTML=sellable.map(({slot,item,sp,tag})=>`
    <div class="shop-item" data-shop-item-id="${slot}">
      <span class="shop-item-emoji">${itemIconHTML(item)}</span>
      <div class="shop-item-info">
        <div class="shop-item-name">${item.name}</div>
        <div class="shop-item-desc">${_itemDesc(item)} • <span style="color:var(--text3)">${tag}</span></div>
      </div>
      <span class="shop-item-price" style="color:var(--green);">+💰 ${sp}</span>
      <button class="btn-buy" style="background:var(--green);color:#000;"
        onclick="sellItem('${slot}')" data-i18n="ui.item.vender">Vender</button>
    </div>`).join('');
  list.querySelectorAll('.shop-item').forEach((row, idx) => {
    const entry = sellable[idx];
    if(entry) aplicarTooltipAoItemDados(row, entry.item);
  });
}

function _renderRepairItems(){
  const myP=GS.cityState&&GS.cityState.players.find(p=>p.id===GS.myPid);
  const gold=myP?Number(myP.gold||0):0;
  const goldEl=$('shop-gold-val'); if(goldEl) goldEl.textContent=gold;
  const list=$('shop-items-list'); if(!list) return;
  const options=(myP&&Array.isArray(myP.repair_options))?myP.repair_options:[];
  if(!options.length){
    list.innerHTML=`<div style="color:var(--text2);padding:20px;text-align:center;font-size:.82rem;">${t('ui.loja.reparo.vazio')}</div>`;
    return;
  }
  list.innerHTML=options.map(entry=>{
    const item=entry.item||{};
    const canRepair=gold>=Number(entry.cost||0);
    const local=entry.location==='bag'?t('ui.loja.reparo.bolsa'):t('ui.loja.reparo.equipado');
    const desc=[
      _itemDesc(item),
      t('ui.loja.reparo.nivel',{n:entry.levels}),
      t('ui.loja.reparo.custo_nivel',{n:entry.cost_per_level}),
      local
    ].filter(Boolean).join(' • ');
    const bagArg=entry.bag_index==null?'null':String(entry.bag_index);
    return `<div class="shop-item${canRepair?'':' shop-item-disabled'}" data-shop-item-id="${entry.slot}"${canRepair?'':' style="opacity:.58;"'}>
      <span class="shop-item-emoji">${itemIconHTML(item)}</span>
      <div class="shop-item-info">
        <div class="shop-item-name">${item.name||entry.name}</div>
        <div class="shop-item-desc">${desc}</div>
      </div>
      <span class="shop-item-price">💰 ${entry.cost}</span>
      <button class="btn-buy" ${canRepair?'':'disabled'}
        title="${canRepair?'':t('erro.ouro_insuficiente_2')}"
        onclick="repairItem('${entry.slot}',${bagArg})">${t('ui.loja.reparo.botao')}</button>
    </div>`;
  }).join('');
  list.querySelectorAll('.shop-item').forEach((row, idx)=>{
    const entry=options[idx];
    if(entry&&entry.item) aplicarTooltipAoItemDados(row, entry.item);
  });
}

function _itemDesc(item){
  if(item.effect === 'learn_spell'){
    const mg = (typeof GRIMORIO_CLIENT !== 'undefined') ? GRIMORIO_CLIENT[item.magia_id] : null;
    return item.descricao || (mg ? `${mg.nome} • ${mg.descricao || ''}` : item.name || '');
  }
  if(item.effect === 'scroll'){
    const pv = item.preview || {};
    const mg = (typeof GRIMORIO_CLIENT !== 'undefined') ? GRIMORIO_CLIENT[item.magia_id] : null;
    const partes = [t('ui.item.desc.nivel', {n: item.nivel_conjurador||1})];
    if(item.int_bonus) partes.push(`INT+${item.int_bonus}`);
    if(pv.dano) partes.push(pv.dano + (pv.talento_dano ? ' ×1.5' : ''));
    else if(pv.alcance === 0) partes.push(t('ui.item.desc.area_no_conjurador'));
    return `${(mg&&mg.nome)||item.magia_id} • ${partes.join(' • ')}`;
  }
  if(item.die){
    const range=item.reach==='lanca' ? ' • '+t('ui.item.desc.alcance_lanca')
              : item.reach==='cajado' ? ' • '+t('ui.item.desc.alcance_adjacentes')
              : item.reach==='mangual' ? ' • '+t('ui.item.desc.alcance_mangual')
              : ['besta','hand_crossbow'].includes(item.id) ? ' • '+t('ui.item.desc.alcance_reto', {n: item.range})
              : ['arco_curto','longbow'].includes(item.id) ? ' • '+t('ui.item.desc.alcance_reto_diag', {n: item.range, d: Math.ceil(item.range / 2)})
              : item.range ? ' • '+t('ui.item.desc.alcance', {n: item.range}) : '';
    const sub=item.categoria?' • '+_rotulo(item.categoria, 'ui.item.subtipo', item.categoria):'';
    const duas=item.two_handed?' • '+t('ui.item.desc.duas_maos'):'';
    const arr=item.throw_range?' • '+t('ui.item.desc.arremesso', {n: item.throw_range}):'';
    const municao=['besta','hand_crossbow'].includes(item.id) ? ' • '+t('ui.item.desc.virotes')
      : ['arco_curto','longbow'].includes(item.id) ? ' • '+t('ui.item.desc.flechas') : '';
    const ehAdaga=item.id==='dagger'||/adaga/i.test(item.name||'');
    const ehChicote=item.id==='chicote'||/chicote/i.test(item.name||'');
    const ehMarteloGuerra=item.id==='warhammer'||item.id==='martelo'||/martelo de guerra/i.test(item.name||'');
    const ehMachadoOrc=item.id==='machado_orc'||/machado de guerra [óo]rquico/i.test(item.name||'');
    const ehMaca=item.id==='maca'||/maça/i.test(item.name||'');
    const ehMangual=item.id==='mangual'||/mangual/i.test(item.name||'');
    const ehEspadaCritica=['shortsword','longsword','bastsword','espada2m'].includes(item.id)
      || /espada curta|espada longa|espada bastarda|espada de 2/i.test(item.name||'');
    const ehMachadoDuplo=item.id==='machado_duplo'||/machado duplo/i.test(item.name||'');
    const finesse=item.finesse?t('ui.item.desc.for_des'):(item.stat==='dex'?t('ui.item.desc.des'):t('ui.item.desc.for'));
    const segMao=(ehAdaga||ehChicote)?' • '+t('ui.item.desc.segunda_mao'):'';
    const critico=ehMarteloGuerra||ehMaca||ehMachadoOrc?' • '+t('ui.item.desc.crit_triplo')
      :ehMangual?' • '+t('ui.item.desc.crit_2_5')
      :ehEspadaCritica?' • '+t('ui.item.desc.crit_19_20')
      :ehMachadoDuplo?' • '+t('ui.item.desc.crit_segundo_ataque'):'';
    const bonus=item.dmg_bonus?' • '+t('ui.item.desc.mais_dano', {n: item.dmg_bonus}):'';
    const resistente=item.corrosao_resistente?' • '+t('ui.item.desc.resiste_corrosao'):'';
    const prata=item.silver?' • '+t('ui.item.desc.prata_arma'):'';
    const resumo = `${t('ui.item.desc.dano_arma', {die: item.die, stat: finesse})}${sub}${bonus}${range}${municao}${duas}${arr}${segMao}${critico}${resistente}${prata}`;
    return item.descricao || resumo;
  }
  if(item.effect==='ammo'){
    const detalhes=[`×${item.ammo_count ?? 0}`];
    if(item.damage_bonus) detalhes.push(t('ui.item.desc.mais_dano', {n: item.damage_bonus}));
    if(item.silver) detalhes.push(t('ui.item.desc.prata'));
    return detalhes.join(' • ');
  }
  if(item.ac_bonus!=null){
    const kindTxt=item.kind==='shield'?t('ui.item.desc.escudo_soma'):t('ui.item.desc.armadura');
    if(item.kind==='armor'){
      const cat=_rotulo(item.armor_category, 'ui.item.armadura_cat', '');
      const mats=(item.corrosion_materials||[]).map(m=>_rotulo(m, 'ui.item.material', m));
      const tags=[cat, mats.length ? mats.join(' + ') : ''].filter(Boolean);
      return `${kindTxt} • ${t('ui.item.desc.ca_mais',{n:item.ac_bonus})}${tags.length ? ' • '+tags.join(' • ') : ''}`;
    }
    return `${kindTxt} • ${t('ui.item.desc.ca_mais',{n:item.ac_bonus})}`;
  }
  // Comida/bebida da taverna: fome/sede vêm nos campos item.fome / item.sede.
  if(item.effect==='food'||item.effect==='meal_survival'){
    const partes=[];
    if(item.fome) partes.push(t('ui.item.desc.mais_fome', {n: item.fome}));
    if(item.sede) partes.push(t('ui.item.desc.mais_sede', {n: item.sede}));
    let txt=partes.join(' / ');
    if(item.effect==='meal_survival') txt+=' • '+t('ui.item.desc.uma_por_visita');
    return txt;
  }
  if(item.effect==='ale')
    return t('ui.item.desc.cerveja', {n: item.value||0});
  if(item.effect==='wine')
    return t('ui.item.desc.vinho', {n: item.value||0});
  if(item.effect==='ration')
    return t('ui.item.desc.racao', {n: item.value||0});
  if(item.effect==='regeneration')
    return t('ui.item.desc.regeneracao', {n: item.value||0});
  if(item.effect==='heal')
    return t('ui.item.desc.cura_hp', {n: item.value ?? item.valor ?? 0});
  if(item.effect==='full_heal')
    return t('ui.item.desc.cura_total');
  if(item.effect==='veil_shadow')
    return item.descricao || t('ui.item.acao_bonus_fica_oculto_ate_o_fim_do_turno');
  const v=item.value?` ${item.value}`:'';
  return _rotulo(item.effect, 'ui.item.efeito', item.effect||'')+v;
}

function buyItem(shop, itemId){
  _guardarSelecaoLoja(itemId);
  send({type:'shop_buy', shop, item_id:itemId});
}
function removerMaldicaoTemplo(maldicaoId){
  send({type:'temple_remove_curse', maldicao_id:maldicaoId});
}

function sellItem(slot){
  _guardarSelecaoLoja(slot);
  send({type:'sell_item', item_slot:slot});
}

function repairItem(slot, bagIndex=null){
  _guardarSelecaoLoja(slot);
  GS.repairItem(slot, bagIndex);
}

function closeShop(){
  GS.activeShop=null;
  GS.activeScene=null;
  GS.shopTabIdx=0;
  window._shopSelectionRestore = null;
  _openCenaNpcId=null;
  const m=$('shop-modal'); if(m) m.classList.remove('open');
}

// A loja pode conter uma cena/conversa antes das abas comerciais. No controle,
// Cancelar percorre essa hierarquia sem obrigar o jogador a focalizar o botão
// "Voltar ao Mapa": conversa → cena principal → cidade.
function _gamepadBackFromShop(){
  const modal = $('shop-modal');
  if(!modal?.classList.contains('open')) return false;
  const dialog = modal.querySelector('.cena-dialogo');
  if(dialog){
    _openCenaNpcId = null;
    dialog.remove();
    _gamepadFocusMapPoint('#shop-modal .cena-npc, #shop-modal .cena-back');
    return true;
  }
  if(GS.activeScene && GS.shopTabIdx > 0){
    GS.shopTabIdx = 0;
    _updateShopTabs();
    _renderShopItems();
    _gamepadFocusMapPoint('#shop-modal .cena-npc, #shop-modal .cena-back');
    return true;
  }
  closeShop();
  _gamepadSetUiFocus(null);
  return true;
}

// ═══════════════════════════════════════════════════════════════════════════
// ■  GUILDA DOS HERÓIS (Fase 0) — compra de especializações e técnicas
//    Overlay próprio (#guild-modal) criado sob demanda. A compra vai pelo
//    servidor (GS.guildBuy → guild_buy) e o city_state re-broadcast reabre/
//    re-renderiza o painel. Equipar técnica é feito na FICHA (não aqui).
// ═══════════════════════════════════════════════════════════════════════════
// Especializações que compartilham uma `linha` grande (ex.: as ~30 Lendas do
// Bardo, todas com linha "bardo_lendas") viram um grupo colapsável para não
// afogar a aba. Ícones conhecidos por linha; o rótulo vem de ui.guilda.linha.<key>
// (resolvido no render, nunca num const de módulo — t() ainda não existe no boot).
const GUILD_LINE_ICONS = { bardo_lendas: '📖' };
const GUILD_GROUP_THRESHOLD = 6;  // linhas com mais itens que isso colapsam
const _guildOpenGroups = new Set();  // linhas expandidas pelo usuário (persiste re-render)

function _guildToggleGroup(linha, open){
  if(open) _guildOpenGroups.add(linha); else _guildOpenGroups.delete(linha);
}

function _guildLineLabel(key){
  const seg = String(key).split('_').slice(1).join(' ') || String(key);
  const fallback = seg.charAt(0).toUpperCase() + seg.slice(1);
  return { icon: GUILD_LINE_ICONS[key] || '📚', label: _rotulo(key, 'ui.guilda.linha', fallback) };
}

function _guildItemRow(i, owned, me){
  const lista = i.categoria === 'tecnica' ? (owned.tecnicas || []) : (owned.especializacoes || []);
  const has   = lista.includes(i.id);
  const reqOk = !i.requer || lista.includes(i.requer);
  const gold  = (me && me.gold) || 0;
  const custo = i.categoria === 'tecnica'
    ? ` · 🍖${i.custo_fome} 💧${i.custo_sede} · ⏱️${i.recarga_rodadas}r` : '';
  const exclusivaBadge = i.exclusiva
    ? ` <b style="color:var(--gold);font-size:.7rem;">${t('ui.guilda.exclusiva_badge')}</b>` : '';
  let action;
  if(has){
    action = `<span class="guild-owned">${t('ui.guilda.possuido')}</span>`;
  } else if(!reqOk){
    const reqNome = (GS.guildCatalogFor(me.class_id).find(x=>x.id===i.requer)||{}).nome || i.requer;
    action = `<span class="guild-locked">${t('ui.guilda.requer', {nome:reqNome})}</span>`;
  } else {
    const can = gold >= i.preco;
    action = `<button class="guild-buy" ${can?'':'disabled'}
                title="${can?'':t('ui.item.ouro_insuficiente')}"
                onclick="GS.guildBuy('${i.id}')">${t('ui.guilda.comprar_preco', {preco: i.preco})}</button>`;
  }
  return `<div class="guild-item${has?' is-owned':''}">
    <span class="gi-icon">${abilityIconHtml(i, i.icon||'✨')}</span>
    <div class="gi-body"><b>${i.nome}</b>${exclusivaBadge}<br><small>${i.desc||''}${custo}</small></div>
    ${action}</div>`;
}

// Renderiza as especializações agrupando por `linha`: grupos pequenos ficam
// planos (aparência atual das outras classes intacta); grupos grandes viram um
// <details> colapsável, ordenado por preço (tier) e depois nome.
function _guildSpecHtml(specs, owned, me){
  if(!specs.length) return `<div class="guild-empty">— em breve —</div>`;
  const order = [];
  const groups = new Map();
  for(const i of specs){
    const key = i.linha || i.id;
    if(!groups.has(key)){ groups.set(key, []); order.push(key); }
    groups.get(key).push(i);
  }
  const ownedSpecs = owned.especializacoes || [];
  let html = '';
  for(const key of order){
    const items = groups.get(key);
    if(items.length <= GUILD_GROUP_THRESHOLD){
      html += items.map(i => _guildItemRow(i, owned, me)).join('');
      continue;
    }
    const meta = _guildLineLabel(key);
    const ownedCount = items.filter(i => ownedSpecs.includes(i.id)).length;
    const sorted = items.slice().sort((a, b) =>
      (a.preco - b.preco) || String(a.nome).localeCompare(String(b.nome)));
    const open = _guildOpenGroups.has(key) ? ' open' : '';
    html += `<details class="guild-group"${open} ontoggle="_guildToggleGroup('${key}', this.open)">
      <summary class="guild-group-sum">
        <span class="ggl-icon">${meta.icon}</span>
        <span class="ggl-label">${meta.label}</span>
        <span class="ggl-count">${ownedCount}/${items.length}</span>
      </summary>
      <div class="guild-group-body">${sorted.map(i => _guildItemRow(i, owned, me)).join('')}</div>
    </details>`;
  }
  return html;
}

function _renderGuild(){
  const modal = $('guild-modal'); if(!modal) return;
  const me = GS.me || ((GS.cityState && GS.cityState.players) || []).find(p => p.id === GS.myPid);
  if(!me) return;
  const owned   = GS.guildOwnedOf(GS.myPid);
  const catalog = GS.guildCatalogFor(me.class_id);
  const specs = catalog.filter(i => i.categoria === 'especializacao');
  const tecs  = catalog.filter(i => i.categoria === 'tecnica');
  const goldEl = $('guild-gold'); if(goldEl) goldEl.textContent = me.gold || 0;
  const sec = (arr) => arr.length
    ? arr.map(i => _guildItemRow(i, owned, me)).join('')
    : `<div class="guild-empty">— em breve —</div>`;
  const specEl = $('guild-list-spec'); if(specEl) specEl.innerHTML = _guildSpecHtml(specs, owned, me);
  // Técnicas agrupadas por faixa de recarga (3/5/8/10 rodadas) — quanto maior a
  // recarga, mais forte a técnica; deixa o trade-off recarga×poder×preço visível.
  const _faixaLabel = { 3:t('ui.hud.recarga_curta_3_rodadas'), 5:t('ui.guilda.recarga_media'),
                        8:t('ui.hud.recarga_longa_8_rodadas'), 10:t('ui.hud.recarga_muito_longa_10_rodadas') };
  const _secTecnicas = (arr) => {
    if(!arr.length) return `<div class="guild-empty">— em breve —</div>`;
    const porFaixa = {};
    arr.forEach(t => { (porFaixa[t.recarga_rodadas] = porFaixa[t.recarga_rodadas] || []).push(t); });
    return Object.keys(porFaixa).sort((a,b)=>a-b).map(rec =>
      `<div class="guild-faixa"><h4 class="guild-faixa-tit">${_faixaLabel[rec] || t('ui.guilda.recarga_n_rodadas', {n: rec})}</h4>`
      + porFaixa[rec].map(i => _guildItemRow(i, owned, me)).join('')
      + `</div>`
    ).join('');
  };
  const tecEl  = $('guild-list-tec');  if(tecEl)  tecEl.innerHTML  = _secTecnicas(tecs);
}

function openGuild(){
  if(!GS.cityState){ toast(t('ui.hud.carregando_guilda'),'var(--blue)'); return; }
  const me = GS.me || (GS.cityState.players || []).find(p => p.id === GS.myPid);
  if(!me){ toast(t('ui.guilda.indisponivel'),'var(--danger)'); return; }
  let modal = $('guild-modal');
  if(!modal){
    modal = document.createElement('div');
    modal.id = 'guild-modal';
    modal.className = 'guild-modal';
    modal.innerHTML =
      `<div class="guild-box">
         <div class="guild-head">
           <h2>${t('ui.guilda.titulo')}</h2>
           <button class="guild-close" onclick="closeGuild()" aria-label="${t('ui.geral.fechar')}">✕</button>
         </div>
         <div class="guild-sub">${t('ui.guilda.subtitulo')} 💰 <span id="guild-gold">0</span></div>
         <div class="guild-sections">
           <section class="guild-sec"><h3>${t('ui.guilda.especializacoes')}</h3><div class="guild-list" id="guild-list-spec"></div></section>
           <section class="guild-sec"><h3>${t('ui.guilda.tecnicas')}</h3><div class="guild-list" id="guild-list-tec"></div></section>
         </div>
       </div>`;
    modal.addEventListener('click', (e) => { if(e.target === modal) closeGuild(); });
    document.body.appendChild(modal);
  }
  modal.classList.add('open');
  _renderGuild();
}

function closeGuild(){
  const m = $('guild-modal'); if(m) m.classList.remove('open');
}

// ═══════════════════════════════════════════════════════════════════════════
// LOJA REUTILIZÁVEL (overlay) — lê GS.CATALOGO_ITENS, opera no herói ativo
// (modelo client-side de GS.getHeroiAtivo). NOTA: compras aqui ainda NÃO são
// autoritativas no servidor — para tornar autoritativo, trocar a mutação em
// comprarItem() por send({type:'shop_buy', shop, item_id}) (ver VISUAL_CONTRACT).
// Funções globais (usadas por onclick inline). Estas tocam o DOM, por isso
// vivem em game.js (gameState.js é livre de DOM).
// ═══════════════════════════════════════════════════════════════════════════
function renderDescricaoItem(item){
  switch(item.tipo){
    case 'arma': {
      // O alcance especial é texto do CATALOGO_ITENS (chicote/lança) — traduzido
      // por chave do PRÓPRIO item, já que o objeto aninhado não tem id.
      const alcance = item.alcanceEspecial
        ? _rotulo(item.id, 'ui.item.alcance_especial', item.alcanceEspecial.descricao)
        : t('ui.item.desc.adjacente');
      const modos = item.modosDuasMaos
        ? t('ui.item.desc.modos_duas_maos', {uma:item.danoUmaMao, duas:item.danoDuasMaos})
        : t('ui.item.desc.dano', {dano:item.dano});
      return `${modos} | ${_rotulo(item.atributo, 'ui.atributo', item.atributo)} | ${t('ui.item.desc.alcance_txt', {alcance})}`;
    }
    case 'armaDistancia':
      return `${t('ui.item.desc.dano', {dano:item.dano + '+' + t('ui.item.desc.des')})} | ${t('ui.item.desc.alcance_quad', {n:item.alcance})} | ${item.slotSecundario === 'flechas' ? t('ui.item.desc.requer_flechas') : t('ui.item.desc.slot_sec_livre')}`;
    case 'armadura':
    case 'escudo':
      return t('ui.item.desc.bonus_ca', {n:item.bonusCA});
    case 'secundario':
      return `${t('ui.item.desc.bonus_visao', {n:item.bonusVisao})} | ${t('ui.item.desc.duracao_rodadas', {n:item.duracao})}`;
    case 'consumivel': {
      const partes = [];
      if(item.fome > 0) partes.push('🍖 ' + t('ui.item.desc.mais_fome', {n:item.fome}));
      if(item.sede > 0) partes.push('💧 ' + t('ui.item.desc.mais_sede', {n:item.sede}));
      return partes.join(' | ');
    }
    case 'municao': {
      const danoExtra = item.danoExtra
        ? ` | +${item.danoExtra} ${_rotulo(item.tipoDano, 'ui.dano_tipo', item.tipoDano)}`
        : '';
      return t('ui.item.desc.unidades', {n:item.quantidade}) + danoExtra;
    }
    case 'varinha':
      return `${t('ui.item.desc.slots_magia', {n:item.slotsMagia})} | ${t('ui.item.desc.dano', {dano:item.dano})} | ${t('ui.item.desc.magia_acao_bonus')}`;
    case 'itemMagico':
      return `${t('ui.item.desc.slots_inventario', {n:item.slotsExtras})} | ${t('ui.item.desc.ocupa_slot_magico')}`;
    default:
      return '';
  }
}

// ── Animação do D100 (Animar Mortos) — dois d10 temáticos (PASSO 3) ──────────
// Renderer puro: monta um overlay full-screen, anima a rolagem e chama
// onConclucao() ao fechar. Consome o objeto `resultado` retornado por
// handle_animar_mortos no servidor (PASSO 2): { d10_dezena, d10_unidade,
// rolagem, chance, zona_hostil, resultado }.
function animarRolagemD100(resultado, onConclucao) {
  const overlay = document.createElement('div')
  overlay.id = 'overlay-d100'
  overlay.style.cssText = `
    position: fixed; inset: 0;
    background: rgba(0,0,0,0.88);
    z-index: 500;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    font-family: 'Cinzel', serif;
  `

  overlay.innerHTML = `
    <!-- Título -->
    <div style="
      color: #cc44ff;
      font-family: 'Cinzel Decorative', serif;
      font-size: 18px;
      letter-spacing: 4px;
      margin-bottom: 32px;
    " data-i18n="ui.animar.animar_mortos">💀 ANIMAR MORTOS</div>

    <!-- Os dois D10 -->
    <div style="display: flex; gap: 24px; margin-bottom: 32px;">

      <!-- D10 dezena -->
      <div style="text-align: center;">
        <div style="
          color: #8a7a5a;
          font-size: 9px;
          letter-spacing: 3px;
          margin-bottom: 8px;
        " data-i18n="ui.hud.dezena">DEZENA</div>
        <div id="d10-dezena" style="
          width: 72px; height: 72px;
          background: rgba(150,0,200,0.15);
          border: 2px solid #9900cc;
          display: flex;
          align-items: center;
          justify-content: center;
          font-size: 32px;
          color: #cc44ff;
          font-weight: bold;
        ">?</div>
      </div>

      <!-- D10 unidade -->
      <div style="text-align: center;">
        <div style="
          color: #8a7a5a;
          font-size: 9px;
          letter-spacing: 3px;
          margin-bottom: 8px;
        " data-i18n="ui.hud.unidade">UNIDADE</div>
        <div id="d10-unidade" style="
          width: 72px; height: 72px;
          background: rgba(150,0,200,0.15);
          border: 2px solid #9900cc;
          display: flex;
          align-items: center;
          justify-content: center;
          font-size: 32px;
          color: #cc44ff;
          font-weight: bold;
        ">?</div>
      </div>
    </div>

    <!-- Total -->
    <div id="total-d100" style="
      color: #ffffff;
      font-size: 42px;
      font-weight: bold;
      margin-bottom: 16px;
      opacity: 0;
      transition: opacity 0.4s ease;
    ">00</div>

    <!-- Faixas de resultado -->
    <div id="faixas-resultado" style="
      display: flex;
      gap: 8px;
      margin-bottom: 24px;
      font-size: 10px;
      letter-spacing: 1px;
    ">
      <span style="color:#ff4136;">
        ${t('ui.animar.faixa_hostil', {ate: resultado.zona_hostil || 0})}
      </span>
      <span style="color:#8a7a5a;">|</span>
      <span style="color:#2ecc40;">
        ${t('ui.animar.faixa_sucesso', {de: (resultado.zona_hostil || 0) + 1, ate: resultado.chance})}
      </span>
      <span style="color:#8a7a5a;">|</span>
      <span style="color:#ff851b;">
        ${t('ui.animar.faixa_falha', {de: resultado.chance + 1})}
      </span>
    </div>

    <!-- Resultado final -->
    <div id="resultado-d100" style="
      font-family: 'Cinzel Decorative', serif;
      font-size: 20px;
      opacity: 0;
      transition: opacity 0.5s ease;
      min-height: 32px;
    "></div>
  `

  document.body.appendChild(overlay)

  // Animação de rolagem
  const dezenaEl = document.getElementById('d10-dezena')
  const unidadeEl = document.getElementById('d10-unidade')
  const totalEl = document.getElementById('total-d100')
  const resultEl = document.getElementById('resultado-d100')

  let frame = 0
  const totalFrames = 24
  const intervalo = setInterval(() => {
    frame++
    dezenaEl.textContent  = Math.floor(Math.random() * 10)
    unidadeEl.textContent = Math.floor(Math.random() * 10)

    if (frame >= totalFrames) {
      clearInterval(intervalo)

      // Mostra resultado real
      const dezena  = resultado.d10_dezena
      const unidade = resultado.d10_unidade
      const total   = resultado.rolagem

      dezenaEl.textContent  = dezena
      unidadeEl.textContent = unidade

      setTimeout(() => {
        totalEl.textContent = total.toString().padStart(2, '0')
        totalEl.style.opacity = '1'

        setTimeout(() => {
          const cores = {
            sucesso: '#2ecc40',
            hostil:  '#ff4136',
            falha:   '#ff851b'
          }
          const textos = {
            sucesso: t('ui.hud.sucesso_criatura_animada'),
            hostil:  t('ui.animar.falha_catastrofica'),
            falha:   t('ui.animar.falha')
          }

          resultEl.textContent  = textos[resultado.resultado]
          resultEl.style.color  = cores[resultado.resultado]
          resultEl.style.opacity = '1'

          // Fecha após 2.5 segundos
          setTimeout(() => {
            overlay.style.opacity = '0'
            overlay.style.transition = 'opacity 0.4s ease'
            setTimeout(() => {
              overlay.remove()
              if (onConclucao) onConclucao()
            }, 400)
          }, 2500)
        }, 600)
      }, 300)
    }
  }, 60)
}

function renderAbaMagiasPedro(heroi) {
  const nivel      = heroi.nivel || 1
  const hab        = heroi.habilidadeClasse
  const slots      = hab.calcularSlots(nivel, heroi.statsModificados.inteligencia)
  const animados   = heroi.animados || []
  const slotsUsados = animados.reduce((s, a) => s + a.slots, 0)
  const guildPedro = GS.guildOwnedOf?.(GS.myPid) || {};
  const senhorDaMorte = (guildPedro.especializacoes || []).includes('mago_reviver_4');
  const usados     = heroi.magiasUsadasHoje || { primeiro:0, segundo:0, terceiro:0 }

  const config = {
    1: { primeiro:2, segundo:0, terceiro:0 },
    2: { primeiro:3, segundo:0, terceiro:0 },
    3: { primeiro:3, segundo:1, terceiro:0 },
    4: { primeiro:3, segundo:2, terceiro:0 },
    5: { primeiro:3, segundo:2, terceiro:1 }
  }[Math.min(nivel, 5)]

  return `
    <!-- HABILIDADE DE CLASSE -->
    <div style="margin-bottom:20px;">
      <div style="
        color:#8a7a5a; font-size:9px;
        letter-spacing:3px; margin-bottom:10px;
      ">${t('ui.ficha.habilidade_classe')}</div>

      <div
        onmouseenter="mostrarTooltipAnimarMortos(event)"
        onmouseleave="ocultarTooltipMagia()"
        onclick="usarAnimarMortos()"
        title="${t('ui.animar.clique_titulo')}"
        style="
          display:flex; align-items:center; gap:12px;
          padding:12px;
          background:rgba(150,0,200,0.08);
          border:1px solid #9900cc66;
          cursor:pointer;
        "
      >
        <img src="assets/habilidades/animar_mortos_vivos.png" alt=""
          style="width:38px;height:38px;object-fit:cover;border-radius:3px;flex:none;"
          onerror="this.replaceWith(document.createTextNode('💀'))">
        <div style="flex:1;">
          <div style="
            color:#cc44ff;
            font-family:'Cinzel Decorative',serif;
            font-size:13px; margin-bottom:3px;
          ">${t('ui.animar.nome_curto')}</div>
          <div style="
            color:#8a7a5a; font-size:10px; letter-spacing:1px;
          ">${t('ui.animar.classe_acao')}</div>
          <div style="color:#ff4444; font-size:10px; margin-top:3px;">
            ${t('ui.animar.custo_por_uso', {n:20})}
          </div>
        </div>
      </div>
      ${senhorDaMorte ? `
      <div
        onclick="usarAnimarMortos('senhor_da_morte')"
        style="
          display:flex; align-items:center; gap:12px; margin-top:8px;
          padding:12px; background:rgba(70,0,0,0.12);
          border:1px solid #8f303066; cursor:pointer;
        "
      >
        <div style="width:38px;height:38px;display:flex;align-items:center;justify-content:center;font-size:30px;">☠️</div>
        <div style="flex:1;">
          <div style="color:#e06b6b;font-family:'Cinzel Decorative',serif;font-size:13px;margin-bottom:3px;" data-i18n="ui.animar.senhor_da_morte">Senhor da Morte</div>
          <div style="color:#b78a8a;font-size:10px;letter-spacing:1px;" data-i18n="ui.magia.versao_alternativa_ficha_completa_nd_2_slo">Versão alternativa · ficha completa · ND + 2 slots</div>
          <div style="color:#ff7777;font-size:10px;margin-top:3px;" data-i18n="ui.animar.senhor_da_morte_penalidades">−20% sucesso · +10% hostilidade · morto-vivo</div>
        </div>
      </div>` : ''}
    </div>

    <!-- EXÉRCITO ANIMADO -->
    <div style="margin-bottom:20px;">
      <div style="
        display:flex; justify-content:space-between;
        color:#8a7a5a; font-size:9px;
        letter-spacing:3px; margin-bottom:10px;
      ">
        <span>${t('ui.animar.exercito')}</span>
        <span style="color:${slotsUsados >= slots ? '#ff4136' : '#2ecc40'}">
          ${t('ui.animar.slots_x_y', {usados:slotsUsados, total:slots})}
        </span>
      </div>

      <!-- Barra de slots -->
      <div style="display:flex; gap:3px; margin-bottom:12px;">
        ${Array.from({length: slots}).map((_, i) => `
          <div style="
            flex:1; height:6px;
            background:${i < slotsUsados ? '#cc44ff' : '#1a1a1a'};
            border:1px solid ${i < slotsUsados ? '#cc44ff' : '#2a2a2a'};
            transition:all 0.3s ease;
          "></div>
        `).join('')}
      </div>

      <!-- Comandar — só aparece no turno dos servos -->
      ${animados.length > 0 && GS.gameState?.animados_turn === GS.myPid ? `
        <button onclick="usarComandarAnimados()" style="
          width:100%; margin-bottom:10px; padding:7px;
          background:rgba(150,0,200,0.22); border:1px solid #9900ccaa;
          color:#cc44ff; font-family:'Cinzel',serif; font-size:10px;
          letter-spacing:2px; cursor:pointer;
        " data-i18n="ui.magia.auto_comandar_todos_os_servos">⚔️ AUTO-COMANDAR TODOS OS SERVOS</button>
      ` : ''}

      <!-- Animados -->
      ${animados.length > 0
        ? animados.map(a => `
          <div
            onmouseenter="mostrarTooltipAnimado(event, '${a.id}', ${JSON.stringify(a).replace(/"/g, '&quot;')})"
            onmouseleave="esconderTooltip()"
            style="
              display:flex; align-items:center; gap:10px;
              padding:10px 12px; margin-bottom:6px;
              background:rgba(150,0,200,0.05);
              border:1px solid #9900cc33;
              cursor:help;
            "
          >
            <div style="font-size:22px; min-width:28px; text-align:center;">
              ${a.icone}
            </div>
            <div style="flex:1;">
              <div style="
                color:#c8b89a; font-family:'Cinzel',serif;
                font-size:11px; margin-bottom:4px;
              ">${a.nome}</div>
              ${a.dominado_por_monstro ? `
                <div style="color:#ff4136; font-size:9px; margin-bottom:3px;" data-i18n="ui.magia.roubado_por_necromante">
                  ⛓️ Roubado por necromante!
                </div>` : (a.por_dominacao ? `
                <div style="color:#cc44ff; font-size:9px; margin-bottom:3px;">
                  ${t('ui.magia.controle_rotulo')} ${a.dominacao?.permanente ? t('ui.magia.permanente')
                    : t('ui.magia.controle_progresso', {n: (a.dominacao?.rodada || 2) - 1})}
                </div>` : '')}
              <div style="
                height:4px; background:#1a1a1a;
                border:1px solid #2a2a2a; margin-bottom:3px;
              ">
                <div style="
                  width:${(a.vida_atual/a.vida_max)*100}%;
                  height:100%;
                  background:${(a.vida_atual/a.vida_max) > 0.6
                    ? '#2ecc40' : (a.vida_atual/a.vida_max) > 0.3
                    ? '#ff851b' : '#ff4136'};
                "></div>
              </div>
              <div style="color:#8a7a5a; font-size:9px;">
                ❤️ ${a.vida_atual}/${a.vida_max}
              </div>
            </div>
            <div style="
              color:#cc44ff; font-size:9px;
              letter-spacing:1px; text-align:right;
            ">Nv.${a.nivel}<br>${a.slots} slot${a.slots > 1 ? 's' : ''}</div>
          </div>
        `).join('')
        : `<div style="
            color:#4a4a4a; font-size:11px;
            font-family:'Cinzel',serif;
            text-align:center; padding:16px;
            border:1px dashed #2a2a2a;
          " data-i18n="ui.magia.nenhuma_criatura_animada">Nenhuma criatura animada</div>`
      }
    </div>

    <!-- MAGIAS DO DIA (cartas do grimório) -->
    <div>
      <div style="
        color:#8a7a5a; font-size:9px;
        letter-spacing:3px; margin-bottom:12px;
      " data-i18n="ui.magia.magias_do_dia">📜 MAGIAS DO DIA</div>
      ${renderMagiasFichaEmJogo(heroi, 'mage')}
    </div>
  `
}

// ── Tooltips da habilidade e dos animados (PASSO 5) ──────────────────────────
// Dependências PRESENTES e funcionais: renderLinhaTooltip (linha ~1767),
// elemento #item-tooltip (linha ~1722), esconderTooltip, GS.getHeroiAtivo.
//
// MISMATCH conhecido (reconciliação futura): GS.getHeroiAtivo() devolve o
// herói do MODELO DE EQUIPAMENTO (gameState.js → inicializarHeroi), que tem
// key/equipado/inventario/fome/sede mas NÃO tem habilidadeClasse nem
// statsModificados — esses campos vivem em HERO_DATA[heroKey] (game.js, PASSO 1).
// Como getHeroiAtivo() nunca retorna falsy (default victorCoiceBravo), o
// fallback `|| HERO_DATA['pedro']` NÃO dispara em jogo, então
// mostrarTooltipHabilidade lançaria TypeError (hab indefinido) até unificarmos
// os dois modelos de herói (ou lermos a habilidade de HERO_DATA[heroKey]).
// mostrarTooltipAnimado é autossuficiente (usa o objeto recebido) e funciona já.
function mostrarTooltipHabilidade(event, id) {
  if (id !== 'animar_mortos') return
  _marcarDonoTooltip(event && (event.currentTarget || event.target))
  // Tooltip é específico do Pedro: usa o registro COMPLETO (habilidadeClasse +
  // statsModificados). GS.getHeroiAtivo() devolveria o modelo de equipamento
  // (sem esses campos), por isso preferimos HERO_DATA.pedro / GS.HERO_DATA.pedro.
  const heroi  = HERO_DATA?.pedro || GS.HERO_DATA?.pedro
  const nivel  = heroi.nivel || 1
  const hab    = heroi.habilidadeClasse
  const slots  = hab.calcularSlots(nivel, heroi.statsModificados.inteligencia)
  const tip      = document.getElementById('item-tooltip')

  tip.innerHTML = `
    <div style="padding:10px 14px 8px; border-bottom:1px solid #9900cc33;">
      <div style="
        font-family:'Cinzel Decorative',serif;
        color:#cc44ff; font-size:13px; margin-bottom:2px;
      ">${t('ui.animar.nome')}</div>
      <div style="color:#8a7a5a; font-size:9px; letter-spacing:3px;">
        ${t('ui.animar.sempre_disponivel')}
      </div>
    </div>

    <div style="padding:10px 14px;">
      ${renderLinhaTooltip('⚡', t('ui.tooltip.acao'), t('ui.tooltip.principal'))}
      ${renderLinhaTooltip('📏', t('ui.pergaminho.alcance'), t('ui.animar.alcance_valor'))}
      ${renderLinhaTooltip('🍖', t('ui.animar.custo_fome'), t('ui.animar.por_uso', {n:20}))}
      ${renderLinhaTooltip('💧', t('ui.animar.custo_sede'), t('ui.animar.por_uso', {n:20}))}
      ${renderLinhaTooltip('🔮', t('ui.animar.slots_disponiveis'), slots)}
      ${renderLinhaTooltip('📊', t('ui.animar.slots_nivel'), t('ui.animar.do_monstro'))}
    </div>

    <div style="
      padding:8px 14px;
      border-top:1px solid #9900cc33;
      border-bottom:1px solid #9900cc33;
      background:rgba(150,0,200,0.05);
    ">
      <div style="
        color:#cc44ff; font-size:9px;
        letter-spacing:3px; margin-bottom:8px;
      ">${t('ui.animar.chance_titulo')}</div>
      ${renderLinhaTooltip('✅', t('ui.animar.nivel_igual'), '90%')}
      ${renderLinhaTooltip('⬇️', t('ui.animar.nivel_abaixo', {n:1}), '95%')}
      ${renderLinhaTooltip('⬇️', t('ui.animar.nivel_abaixo_mais'), t('ui.animar.max_pct', {n:99}))}
      ${renderLinhaTooltip('⬆️', t('ui.animar.nivel_acima', {n:1}), t('ui.animar.pct_hostil', {p:80, h:10}))}
      ${renderLinhaTooltip('⬆️', t('ui.animar.nivel_acima', {n:2}), t('ui.animar.pct_hostil', {p:70, h:20}))}
      ${renderLinhaTooltip('⬆️', t('ui.animar.nivel_acima', {n:3}), t('ui.animar.pct_hostil', {p:60, h:30}))}
      ${renderLinhaTooltip('⬆️', t('ui.animar.nivel_acima', {n:4}), t('ui.animar.pct_hostil', {p:50, h:40}))}
    </div>

    <div style="
      padding:8px 14px;
      border-top:1px solid #9900cc33;
      border-bottom:1px solid #9900cc33;
      background:rgba(150,0,200,0.05);
    ">
      <div style="
        color:#cc44ff; font-size:9px;
        letter-spacing:3px; margin-bottom:8px;
      ">${t('ui.animar.regras_titulo')}</div>
      <div style="color:#c8b89a; font-size:10px; line-height:1.8;">
        ${['acao_bonus','sem_cura','persistem','sem_recuperar','viram_po','sem_reanimar','morte_pedro','hostis']
            .map(k => '→ ' + t('ui.animar.regra.' + k)).join('<br>')}
      </div>
    </div>

    <div style="
      padding:8px 14px; color:#c8b89a;
      font-size:10px; line-height:1.6; font-style:italic;
    ">
      ${t('ui.animar.lore')}
    </div>
  `

  tip.style.borderColor = '#9900cc'
  t.style.opacity = '1'
}

function mostrarTooltipAnimado(event, id, dadosAnimado) {
  _marcarDonoTooltip(event && (event.currentTarget || event.target))
  const a = typeof dadosAnimado === 'string'
    ? JSON.parse(dadosAnimado)
    : dadosAnimado
  const tip = document.getElementById('item-tooltip')
  const pctVida = (a.vida_atual / a.vida_max) * 100
  const corVida = pctVida > 60 ? '#2ecc40' :
                  pctVida > 30 ? '#ff851b' : '#ff4136'
  const ataques = Array.isArray(a.attacks) ? a.attacks : []
  const habilidades = Array.isArray(a.special_abilities) ? a.special_abilities : []
  const listaAtaques = ataques.length
    ? ataques.map(at => `${at.name || t('ui.animar.ataque')}: +${at.atk_bonus ?? 0}, ${at.damage || a.dano}${at.num_attacks > 1 ? ` ×${at.num_attacks}` : ''}`).join('<br>')
    : a.dano
  const listaHabilidades = habilidades.length
    ? habilidades.map(h => h.name || h.id).join(' • ')
    : t('ui.animar.nenhuma')
  const alcanceAtaques = ataques.length
    ? ataques.map(at => at.range
        ? `${at.range}q${at.range_shape ? ' em linha' : ''}`
        : 'adjacente').join(' • ')
    : 'adjacente'

  tip.innerHTML = `
    <div style="padding:10px 14px 8px; border-bottom:1px solid #9900cc33;">
      <div style="display:flex; align-items:center; gap:8px; margin-bottom:4px;">
        <span style="font-size:20px;">${a.icone}</span>
        <div>
          <div style="
            font-family:'Cinzel Decorative',serif;
            color:#cc44ff; font-size:12px;
          ">${a.nome}</div>
          <div style="color:#8a7a5a; font-size:9px; letter-spacing:2px;">
            ${t('ui.animar.servo_linha', {nivel:a.nivel, slots:a.slots})}
          </div>
        </div>
      </div>
    </div>

    <div style="padding:10px 14px;">
      <div style="margin-bottom:8px;">
        <div style="
          display:flex; justify-content:space-between; margin-bottom:3px;
        ">
          <span style="color:#8a7a5a; font-size:10px;" data-i18n="ui.animar.vida">❤️ Vida</span>
          <span style="color:${corVida}; font-size:11px; font-weight:bold;">
            ${a.vida_atual}/${a.vida_max}
          </span>
        </div>
        <div style="height:4px; background:#1a1a1a; border:1px solid #2a2a2a;">
          <div style="
            width:${pctVida}%; height:100%; background:${corVida};
          "></div>
        </div>
      </div>
      ${renderLinhaTooltip('🛡️', t('ui.animar.classe_de_armadura'), a.ca)}
      ${renderLinhaTooltip('🎲', t('ui.animar.ataques'), listaAtaques)}
      ${renderLinhaTooltip('👣', t('ui.cancao.atributo.movimento'), t('ui.animar.n_casas', {n:a.movimento}))}
      ${renderLinhaTooltip('⚔️', t('ui.animar.alcance_ataque'), alcanceAtaques)}
      ${renderLinhaTooltip('✨', t('ui.mestre.habilidades_titulo'), listaHabilidades)}
    </div>

    <div style="
      padding:8px 14px;
      border-top:1px solid #9900cc33;
      text-align:center;
    ">
      <div style="color:#ff4136; font-size:9px; letter-spacing:1px;">
        ${t('ui.animar.servo_imune')}
      </div>
      <div style="color:#4a4a4a; font-size:9px; margin-top:3px;">
        ${t('ui.animar.servo_po')}
      </div>
    </div>
  `

  tip.style.borderColor = '#9900cc'
  t.style.opacity = '1'

  // Mostra alcance de ataque no mapa enquanto o cursor está sobre a ficha.
  window._animadoHover = a;
  if(GS.gameState) renderMap(GS.gameState);
}

// ── Aba ATRIBUTOS da ficha do Pedro (PASSO C) ────────────────────────────────
// IMPORTANTE: usa heroi.statsModificados/stats + calcularVidaMaxima. Por isso o
// herói passado precisa ser o registro COMPLETO (HERO_DATA de game.js), não o
// modelo de equipamento de GS.HERO_DATA — ver nota em trocarAbaFicha/_injetarFichaPedro.
function renderConteudoAtributosPedro(heroi) {
  // O rótulo vem de ui.atributo.<key> (as mesmas chaves da ficha do jogo).
  const ATRIBUTOS = [
    { key: 'forca',        icone: '⚔️' },
    { key: 'destreza',     icone: '🏃' },
    { key: 'inteligencia', icone: '📖' },
    { key: 'constituicao', icone: '🛡️' }
  ]

  const vidaMax = calcularVidaMaxima(
    'pedro',
    heroi.nivel || 1,
    heroi.statsModificados?.constituicao || heroi.stats?.constituicao
  )

  // Espelha GameRoom.initiative_value: DES + mod(INT). Aqui só há a ficha
  // estática (sem equipamento), então não há initiative_bonus a somar.
  const iniciativa = _iniciativaDeStatsHeroi(heroi)

  return `
    <!-- VIDA -->
    <div style="
      margin-bottom:14px; padding:10px 12px;
      background:rgba(255,65,54,0.08);
      border:1px solid #ff413644;
      display:flex; justify-content:space-between; align-items:center;
    ">
      <span style="color:#8a7a5a; font-size:11px; letter-spacing:2px;">
        ${t('ui.ficha.pontos_de_vida')}
      </span>
      <div style="text-align:right;">
        <span style="color:#ff4136; font-size:18px; font-weight:bold;">
          ${heroi.vidaAtual || vidaMax}
        </span>
        <span style="color:#4a4a4a; font-size:13px;"> / ${vidaMax}</span>
      </div>
    </div>

    <!-- ATRIBUTOS -->
    ${ATRIBUTOS.map(attr => {
      const valorAtual = heroi.statsModificados?.[attr.key] || heroi.stats?.[attr.key] || 10
      const valorBase  = heroi.stats?.[attr.key] || 10
      const pct        = (valorAtual / 25) * 100
      const cor        = valorAtual > valorBase ? '#2ecc40' :
                         valorAtual < valorBase ? '#ff4136' : '#c8a951'
      return `
        <div style="margin-bottom:12px;">
          <div style="
            display:flex; justify-content:space-between;
            align-items:center; margin-bottom:4px;
          ">
            <span style="
              color:#8a7a5a; font-family:'Cinzel',serif;
              font-size:11px; letter-spacing:2px;
            ">${attr.icone} ${_rotulo(attr.key, 'ui.atributo', attr.key)}</span>
            <span style="color:${cor}; font-size:13px; font-weight:bold;">
              ${valorAtual}
            </span>
          </div>
          <div style="height:6px; background:#1a1a1a; border:1px solid #2a2a2a;">
            <div style="
              width:${pct}%; height:100%; background:${cor};
              transition:width 0.6s ease;
            "></div>
          </div>
        </div>
      `
    }).join('')}

    <!-- NÍVEL -->
    <div style="
      margin-top:14px; padding:8px 12px;
      background:rgba(200,169,81,0.06);
      border:1px solid #c8a95133;
      display:flex; justify-content:space-between;
    ">
      <span style="color:#8a7a5a; font-size:11px; letter-spacing:2px;">${t('ui.ficha.nivel')}</span>
      <span style="color:#c8a951; font-size:14px; font-weight:bold;">
        ${heroi.nivel || 1}
      </span>
    </div>

    <!-- INICIATIVA -->
    ${_iniciativaBox(iniciativa)}
  `
}

// ── Troca de aba na ficha do Pedro (PASSO D) ─────────────────────────────────
// Fonte do herói: PREFERE HERO_DATA[heroiKey] (game.js, registro COMPLETO com
// stats/statsModificados) e cai para GS.HERO_DATA como fallback. Isto é uma
// correção deliberada do spec (que preferia GS): GS.HERO_DATA.pedro tem
// habilidadeClasse mas NÃO tem stats/statsModificados, e ambas as abas precisam
// deles (renderAbaMagiasPedro lê heroi.statsModificados.inteligencia).
function trocarAbaFicha(aba, heroiKey) {
  const conteudo = document.getElementById('conteudo-ficha-pedro')
  if (!conteudo) return

  const heroi = HERO_DATA?.[heroiKey] || GS.HERO_DATA?.[heroiKey]
  if (!heroi) return

  const btnAtributos = document.getElementById('aba-atributos')
  const btnMagias    = document.getElementById('aba-magias')
  if (!btnAtributos || !btnMagias) return

  const ativo   = '#c8a951'
  const inativo = '#8a7a5a'

  btnAtributos.style.borderBottomColor = aba === 'atributos' ? ativo : 'transparent'
  btnAtributos.style.color             = aba === 'atributos' ? ativo : inativo
  btnMagias.style.borderBottomColor    = aba === 'magias'    ? ativo : 'transparent'
  btnMagias.style.color                = aba === 'magias'    ? ativo : inativo

  conteudo.innerHTML = aba === 'atributos'
    ? renderConteudoAtributosPedro(heroi)
    : renderAbaMagiasPedro(heroi)
}

// Exposição global (PASSO F). _injetarFichaPedro / _classIdParaHeroiKey são
// declarações de função hoisted (definidas mais abaixo, junto de _csfShowPanel),
// portanto já existem aqui no momento desta atribuição.
window.trocarAbaFicha                = trocarAbaFicha
window.animarRolagemD100             = animarRolagemD100
window.mostrarTooltipHabilidade      = mostrarTooltipHabilidade
window.mostrarTooltipAnimado         = mostrarTooltipAnimado
window.renderAbaMagiasPedro          = renderAbaMagiasPedro
window.renderConteudoAtributosPedro  = renderConteudoAtributosPedro
window._injetarFichaPedro            = _injetarFichaPedro
window._classIdParaHeroiKey          = _classIdParaHeroiKey

// ── Ficha completa do herói DURANTE o jogo (overlay) ─────────────────────────
// Abre um overlay com a ficha do herói ativo. Para Pedro inclui as abas
// ATRIBUTOS e MAGIAS (Animar Mortos). Dispara via gatilho do HUD (a ligar).
//
// DEPENDÊNCIAS / DESVIOS (documentados):
//   • GS.me — adicionado em gameState.js (getter): jogador local autoritativo.
//     Quando presente (combate), HP/atributos/CA/nível vêm do servidor.
//   • Fonte do herói: a spec usava `GS.HERO_DATA || HERO_DATA`. CORRIGIDO para
//     `HERO_DATA || GS.HERO_DATA` (registro COMPLETO primeiro) — GS.HERO_DATA.pedro
//     NÃO tem stats/statsModificados/portrait, e renderAbaMagiasPedro lê
//     heroi.statsModificados.inteligencia (lançaria TypeError na aba MAGIAS).
//     Mesma correção aceita no _injetarFichaPedro da tela de seleção.
//   • Fome/Sede: a spec lê estadoServidor.hunger/thirst (/100); o servidor usa
//     fome/sede (0–10) via GS.getSurvival. Como hunger/thirst não existem, esse
//     bloco simplesmente NÃO renderiza (degradação graciosa) — sem erro.
function abrirFichaEmJogo(heroiKey) {
  // Remove overlay anterior se existir
  const anterior = document.getElementById('ficha-overlay-jogo')
  if (anterior) anterior.remove()

  // Obtém dados do herói — registro COMPLETO primeiro (stats/statsModificados/portrait)
  const heroi = HERO_DATA?.[heroiKey]
            || GS.HERO_DATA?.[heroiKey]
  if (!heroi) return

  // Obtém estado autoritativo do servidor para HP e stats
  const estadoServidor = GS.me || {}

  // Overlay escurecido
  const overlay = document.createElement('div')
  overlay.id = 'ficha-overlay-jogo'
  overlay.style.cssText = `
    position: fixed; inset: 0;
    background: rgba(0,0,0,0.80);
    z-index: 300;
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0;
    transition: opacity 0.3s ease;
  `

  // Container da ficha
  const container = document.createElement('div')
  container.style.cssText = `
    width: 320px;
    max-height: 88vh;
    overflow-y: auto;
    background: rgba(10,8,5,0.98);
    border: 1px solid #c8a951;
    position: relative;
  `

  // Cabeçalho com retrato e nome
  const cabecalho = document.createElement('div')
  cabecalho.style.cssText = `
    padding: 16px 20px 12px;
    border-bottom: 1px solid #c8a95133;
    display: flex;
    align-items: center;
    gap: 12px;
  `
  cabecalho.innerHTML = `
    <img
      src="${heroi.portrait || ''}"
      style="
        width:52px; height:52px;
        object-fit:cover; object-position:top;
        border:1px solid #c8a95166;
      "
      onerror="this.style.display='none'"
    />
    <div style="flex:1;">
      <div style="
        font-family:'Cinzel Decorative',serif;
        color:#c8a951; font-size:14px;
      ">${heroi.name || heroi.nome}</div>
      <div style="
        color:#8a7a5a; font-size:10px;
        letter-spacing:3px; margin-top:2px;
      ">${_rotulo(heroiKey, 'ui.heroi.classe', '')}</div>
      <div style="
        color:#c8b89a; font-size:10px; margin-top:4px;
      ">${t('ui.ficha.nivel_caixa', {n: estadoServidor.level || heroi.nivel || 1})}</div>
    </div>
    <button
      onclick="document.getElementById('ficha-overlay-jogo').remove()"
      style="
        background:transparent; border:1px solid #4a4a4a;
        color:#8a7a5a; font-family:'Cinzel',serif;
        font-size:11px; padding:4px 10px; cursor:pointer;
        align-self:flex-start;
      "
    >✕</button>
  `

  // Área de conteúdo — abas para Pedro, padrão para os outros
  const conteudoArea = document.createElement('div')
  conteudoArea.style.cssText = 'padding: 16px 20px;'

  if (heroiKey === 'pedro') {
    // Pedro — com abas ATRIBUTOS e MAGIAS
    conteudoArea.innerHTML = `
      <div style="
        display:flex;
        border-bottom:1px solid #c8a95133;
        margin-bottom:16px;
      ">
        <button
          onclick="trocarAbaFichaJogo('atributos','pedro')"
          id="aba-jogo-atributos"
          style="
            flex:1; padding:9px; background:transparent;
            border:none; border-bottom:2px solid #c8a951;
            color:#c8a951; font-family:'Cinzel',serif;
            font-size:10px; letter-spacing:2px; cursor:pointer;
          "
         data-i18n="ui.ficha.atributos">📊 ATRIBUTOS</button>
        <button
          onclick="trocarAbaFichaJogo('magias','pedro')"
          id="aba-jogo-magias"
          style="
            flex:1; padding:9px; background:transparent;
            border:none; border-bottom:2px solid transparent;
            color:#8a7a5a; font-family:'Cinzel',serif;
            font-size:10px; letter-spacing:2px; cursor:pointer;
          "
         data-i18n="ui.ficha.magias">💀 MAGIAS</button>
      </div>
      <div id="conteudo-ficha-jogo-pedro">
        ${renderConteudoAtributosFichaJogo(heroi, estadoServidor)}
      </div>
    `
  } else {
    // Outros heróis — só atributos
    conteudoArea.innerHTML = renderConteudoAtributosFichaJogo(heroi, estadoServidor)
  }

  // Botão fechar inferior
  const btnFechar = document.createElement('button')
  btnFechar.textContent = t('ui.ficha.fechar')
  btnFechar.style.cssText = `
    width:100%; padding:11px;
    background:transparent;
    border:none; border-top:1px solid #1a1a1a;
    color:#8a7a5a; font-family:'Cinzel',serif;
    font-size:11px; letter-spacing:3px; cursor:pointer;
    transition:background 0.2s;
  `
  btnFechar.onmouseover = () => btnFechar.style.background = 'rgba(255,255,255,0.03)'
  btnFechar.onmouseout  = () => btnFechar.style.background = 'transparent'
  btnFechar.onclick     = () => {
    overlay.style.opacity = '0'
    setTimeout(() => overlay.remove(), 300)
  }

  // Clicar fora fecha
  overlay.onclick = (e) => {
    if (e.target === overlay) btnFechar.onclick()
  }

  container.appendChild(cabecalho)
  container.appendChild(conteudoArea)
  container.appendChild(btnFechar)
  overlay.appendChild(container)
  document.body.appendChild(overlay)

  // Fade in
  requestAnimationFrame(() => { overlay.style.opacity = '1' })
}

// Troca abas dentro da ficha em jogo — separado do trocarAbaFicha da seleção
function trocarAbaFichaJogo(aba, heroiKey) {
  const conteudo = document.getElementById('conteudo-ficha-jogo-pedro')
  if (!conteudo) return

  const heroi         = HERO_DATA?.[heroiKey] || GS.HERO_DATA?.[heroiKey]
  const estadoServidor = GS.me || {}
  if (!heroi) return

  const btnAtrib = document.getElementById('aba-jogo-atributos')
  const btnMagia = document.getElementById('aba-jogo-magias')
  if (!btnAtrib || !btnMagia) return

  const ativo   = '#c8a951'
  const inativo = '#8a7a5a'

  btnAtrib.style.borderBottomColor = aba === 'atributos' ? ativo : 'transparent'
  btnAtrib.style.color             = aba === 'atributos' ? ativo : inativo
  btnMagia.style.borderBottomColor = aba === 'magias'    ? ativo : 'transparent'
  btnMagia.style.color             = aba === 'magias'    ? ativo : inativo

  conteudo.innerHTML = aba === 'atributos'
    ? renderConteudoAtributosFichaJogo(heroi, estadoServidor)
    : renderAbaMagiasPedro(heroi)
}

// Raio de visão exibido na ficha. O servidor é a fonte autoritativa; o cálculo
// local é apenas um fallback enquanto uma atualização de estado não chega.
function obterRaioVisaoCliente(personagem){
  const recebido = Number(personagem && personagem.vision_radius);
  if(Number.isFinite(recebido)) return recebido;
  const dex = Number(personagem && personagem.dex != null ? personagem.dex : 10);
  const intel = Number(personagem && personagem.int_ != null ? personagem.int_ : 10);
  const modDex = Math.floor((dex - 10) / 2);
  const modInt = Math.floor((intel - 10) / 2);
  const classe = personagem && (personagem.class_id || personagem.key || personagem.id);
  const base = Math.max(1, Number(personagem && personagem.spd != null ? personagem.spd : 5));
  const bonusLuz = classe === 'paladin' && personagem && personagem.guerreiro_luz_ativo
    ? Number((personagem.guerreiro_luz_bonus || {}).visao || 0) : 0;
  return Math.max(1, base + Math.floor((modInt + modDex) / 2) + bonusLuz);
}

function obterPercepcaoCliente(personagem, raioVisao){
  const recebido = Number(personagem && personagem.percepcao);
  if(Number.isFinite(recebido)) return recebido;
  return Math.max(1, 10 + Math.floor(Number(raioVisao || 1) / 2));
}

// Iniciativa exibida na ficha. O servidor é a fonte autoritativa (campo
// `initiative`, presente no game_state e no city_state); o cálculo local
// espelha GameRoom.initiative_value e serve de fallback enquanto uma
// atualização de estado não chega.
function obterIniciativaCliente(personagem){
  const recebido = Number(personagem && personagem.initiative);
  if(Number.isFinite(recebido)) return recebido;
  const dex   = Number(personagem && personagem.dex  != null ? personagem.dex  : 10);
  const intel = Number(personagem && personagem.int_ != null ? personagem.int_ : 10);
  const bonus = Number(personagem && personagem.initiative_bonus || 0);
  return dex + Math.floor((intel - 10) / 2) + bonus;
}

// Mesma conta, mas a partir dos stats em português do HERO_DATA (tela de
// seleção / ficha estática do Pedro, onde não há registro do servidor).
function _iniciativaDeStats(stats){
  const dex   = Number((stats || {}).destreza      != null ? stats.destreza      : 10);
  const intel = Number((stats || {}).inteligencia  != null ? stats.inteligencia  : 10);
  return dex + Math.floor((intel - 10) / 2);
}

function _iniciativaDeStatsHeroi(heroi){
  return _iniciativaDeStats({
    destreza:     heroi?.statsModificados?.destreza     ?? heroi?.stats?.destreza     ?? 10,
    inteligencia: heroi?.statsModificados?.inteligencia ?? heroi?.stats?.inteligencia ?? 10
  });
}

// Caixa da iniciativa na ficha — mesmo formato das de Raio de Visão/Percepção.
// É uma FUNÇÃO (não um const com t() no nível de módulo, que rodaria antes de
// `t` existir e abortaria o carregamento do game.js).
function _iniciativaBox(valor){
  return `
    <div style="margin-top:8px; padding:8px 12px; background:rgba(255,190,80,0.06); border:1px solid #ffbe5044; display:flex; justify-content:space-between;">
      <span style="color:#8a7a5a; font-size:10px; letter-spacing:2px;">${t('ui.ficha.iniciativa')}</span>
      <span style="color:#ffd27a; font-size:14px; font-weight:bold;">⚡ ${valor}</span>
    </div>
  `
}

// Renderiza atributos usando dados do servidor quando disponíveis
function renderConteudoAtributosFichaJogo(heroi, estadoServidor) {
  const ATRIBUTOS = [
    { key: 'forca',        serverKey: 'str_', icone: '⚔️' },
    { key: 'destreza',     serverKey: 'dex',  icone: '🏃' },
    { key: 'inteligencia', serverKey: 'int_', icone: '📖' },
    { key: 'constituicao', serverKey: 'con_', icone: '🛡️' }
  ]

  // Prioriza dados do servidor — fallback para HERO_DATA
  const nivel   = estadoServidor.level  || heroi.nivel  || 1
  const hpAtual = estadoServidor.hp     || heroi.vidaAtual || '?'
  const hpMax   = estadoServidor.max_hp || calcularVidaMaxima?.(
    heroi.key, nivel,
    heroi.statsModificados?.constituicao || heroi.stats?.constituicao
  ) || '?'
  const raioVisao = obterRaioVisaoCliente(estadoServidor)
  const percepcao = obterPercepcaoCliente(estadoServidor, raioVisao)
  const iniciativa = obterIniciativaCliente(estadoServidor)
  // Nome e efeito de cada maldição vêm de ui.maldicao.<id> / ui.maldicao.<id>.ef —
  // o nome é a MESMA chave que o templo usa em _renderShopItems.
  const maldicoes = (estadoServidor.maldicoes||[]).map(m=>`<li>☠️ <b>${_rotulo(m.id,'ui.maldicao',m.id)}</b> — ${_rotulo(m.id+'.ef','ui.maldicao',t('ui.maldicao.ativa'))}${m.aventuras!=null&&['fome_eterna','sede_infinita','tocado_morte','licantropia','corrupcao_crescente'].includes(m.id)?` ${t('ui.maldicao.estagio',{n:Math.min(5,1+Math.floor(m.aventuras/2))})}`:''}</li>`).join('')
  const doenca = estadoServidor.doente ? `<li>🦠 <b>${t('ui.ficha.doenca',{tipo:estadoServidor.doenca_tipo||''})}</b> — ${((estadoServidor.doenca||{}).sintomas||[]).join(', ')}</li>` : ''
  const modificadores = (maldicoes||doenca) ? `<div style="margin-top:14px;padding:10px;border:1px solid #a34a4a;background:rgba(120,20,25,.14)"><div style="color:#e8a0a0;font:10px Cinzel,serif;letter-spacing:1px;margin-bottom:5px">${t('ui.ficha.modificadores_males')}</div><ul style="margin:0;padding-left:16px;color:#e8d4d4;font-size:11px;line-height:1.5">${doenca}${maldicoes}</ul></div>` : ''

  return `
    <!-- VIDA -->
    <div style="
      margin-bottom:14px; padding:10px 12px;
      background:rgba(255,65,54,0.08);
      border:1px solid #ff413644;
      display:flex; justify-content:space-between; align-items:center;
    ">
      <span style="color:#8a7a5a; font-size:11px; letter-spacing:2px;">
        ❤️ ${t('ui.ficha.pontos_de_vida')}
      </span>
      <div>
        <span style="color:#ff4136; font-size:18px; font-weight:bold;">
          ${hpAtual}
        </span>
        <span style="color:#4a4a4a; font-size:13px;"> / ${hpMax}</span>
      </div>
    </div>

    <!-- FOME E SEDE -->
    ${estadoServidor.hunger !== undefined ? `
      <div style="
        display:flex; gap:8px; margin-bottom:14px;
      ">
        <div style="
          flex:1; padding:8px 10px;
          background:rgba(255,133,27,0.08);
          border:1px solid #ff851b44;
        ">
          <div style="color:#8a7a5a; font-size:9px; letter-spacing:2px; margin-bottom:4px;">
            🍖 ${t('ui.ficha.fome')}
          </div>
          <div style="height:5px; background:#1a1a1a; border:1px solid #2a2a2a;">
            <div style="
              width:${estadoServidor.hunger}%;
              height:100%; background:#ff851b;
            "></div>
          </div>
          <div style="color:#ff851b; font-size:10px; margin-top:3px;">
            ${estadoServidor.hunger}/100
          </div>
        </div>
        <div style="
          flex:1; padding:8px 10px;
          background:rgba(68,136,255,0.08);
          border:1px solid #4488ff44;
        ">
          <div style="color:#8a7a5a; font-size:9px; letter-spacing:2px; margin-bottom:4px;">
            💧 ${t('ui.ficha.sede')}
          </div>
          <div style="height:5px; background:#1a1a1a; border:1px solid #2a2a2a;">
            <div style="
              width:${estadoServidor.thirst}%;
              height:100%; background:#4488ff;
            "></div>
          </div>
          <div style="color:#4488ff; font-size:10px; margin-top:3px;">
            ${estadoServidor.thirst}/100
          </div>
        </div>
      </div>
    ` : ''}

    <!-- ATRIBUTOS -->
    ${ATRIBUTOS.map(attr => {
      const valor = estadoServidor[attr.serverKey]
            || heroi.statsModificados?.[attr.key]
            || heroi.stats?.[attr.key]
            || 10
      const pct = (valor / 25) * 100
      return `
        <div style="margin-bottom:12px;">
          <div style="
            display:flex; justify-content:space-between;
            align-items:center; margin-bottom:4px;
          ">
            <span style="
              color:#8a7a5a; font-family:'Cinzel',serif;
              font-size:11px; letter-spacing:2px;
            ">${attr.icone} ${_rotulo(attr.key, 'ui.atributo', attr.key)}</span>
            <span style="color:#c8a951; font-size:13px; font-weight:bold;">
              ${valor}
            </span>
          </div>
          <div style="height:5px; background:#1a1a1a; border:1px solid #2a2a2a;">
            <div style="
              width:${pct}%; height:100%; background:#c8a951;
              transition:width 0.5s ease;
            "></div>
          </div>
        </div>
      `
    }).join('')}

    <!-- CA e NÍVEL -->
    <div style="
      display:flex; gap:8px; margin-top:14px;
    ">
      <div style="
        flex:1; padding:8px 12px;
        background:rgba(200,169,81,0.06);
        border:1px solid #c8a95133;
        display:flex; justify-content:space-between;
      ">
        <span style="color:#8a7a5a; font-size:10px; letter-spacing:2px;">${t('ui.ficha.nivel')}</span>
        <span style="color:#c8a951; font-size:14px; font-weight:bold;">${nivel}</span>
      </div>
      ${estadoServidor.ac ? `
        <div style="
          flex:1; padding:8px 12px;
          background:rgba(200,169,81,0.06);
          border:1px solid #c8a95133;
          display:flex; justify-content:space-between;
        ">
          <span style="color:#8a7a5a; font-size:10px; letter-spacing:2px;">${t('ui.bau.stat_ca')}</span>
          <span style="color:#c8a951; font-size:14px; font-weight:bold;">
            ${estadoServidor.ac}${(estadoServidor.buffs_cancao && estadoServidor.buffs_cancao.bonus_ca) ? ` <span style="color:#4db8ff;font-size:.78em;" title="${t('ui.hud.cancao_de_henrique')}">🎵+${estadoServidor.buffs_cancao.bonus_ca}</span>` : ''}
          </span>
        </div>
      ` : ''}
      <div style="
        flex:1; padding:8px 12px;
        background:rgba(100,180,255,0.06);
        border:1px solid #64b4ff44;
        display:flex; justify-content:space-between;
      ">
        <span style="color:#8a7a5a; font-size:10px; letter-spacing:2px;">${t('ui.ficha.raio_visao')}</span>
        <span style="color:#8ed0ff; font-size:14px; font-weight:bold;">👁 ${raioVisao}</span>
      </div>
    </div>
    <div style="margin-top:8px; padding:8px 12px; background:rgba(170,130,255,0.06); border:1px solid #aa82ff44; display:flex; justify-content:space-between;">
      <span style="color:#8a7a5a; font-size:10px; letter-spacing:2px;">${t('ui.ficha.percepcao')}</span>
      <span style="color:#c4a7ff; font-size:14px; font-weight:bold;">👁‍🗨 ${percepcao}</span>
    </div>
    ${_iniciativaBox(iniciativa)}
    ${modificadores}
  `
}

// Arma a mira de Animar Mortos: escolha um cadáver a até 3 casas de Pedro.
function usarAnimarMortos(versao = 'animar_mortos') {
  const estado = GS.gameState;
  const me = estado?.players?.find(p => p.id === GS.myPid && p.alive);
  const cadaveres = (estado?.corpses || []).filter(c => me &&
    Math.max(Math.abs(me.pos[0] - c.pos[0]), Math.abs(me.pos[1] - c.pos[1])) <= 3);
  if (!cadaveres.length) { toast(t('ui.animar.sem_cadaver')); return; }
  const ov = document.getElementById('ficha-overlay-jogo')
  if (ov) ov.remove()
  _iniciarModoAnimarMortos(cadaveres, versao)
}

// Comanda os animados (ação bônus). Fecha a ficha para ver o tabuleiro/ações.
function usarComandarAnimados() {
  const ov = document.getElementById('ficha-overlay-jogo')
  if (ov) ov.remove()
  GS.comandarAnimados()
}

// Exposição global
window.abrirFichaEmJogo             = abrirFichaEmJogo
window.trocarAbaFichaJogo           = trocarAbaFichaJogo
window.renderConteudoAtributosFichaJogo = renderConteudoAtributosFichaJogo
window.usarAnimarMortos             = usarAnimarMortos
window.usarComandarAnimados         = usarComandarAnimados

// ── Atalho de teclado: ESC fecha o overlay de ficha (visualização de outro herói).
// A ficha do Pedro agora é o painel principal (#my-stats com abas), então não há
// mais atalho/​botão para abrir a "ficha completa" do próprio Pedro.
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') {
    const aberta = document.getElementById('ficha-overlay-jogo')
    if (aberta) {
      aberta.style.opacity = '0'
      setTimeout(() => aberta.remove(), 300)
      e.preventDefault()
    }
  }
})

function abrirLoja(nomeLocal, heroiAtivo){
  window._lojaAtualAberta  = nomeLocal;  // loja atualmente aberta (limpa ao fechar)
  window._lojaUltimaAberta = nomeLocal;  // última loja (persiste p/ reabrir após compra)
  // Remove qualquer overlay anterior imediatamente (evita IDs duplicados
  // durante o fade de 300ms quando comprarItem reabre a loja).
  const stale = document.getElementById('loja-overlay');
  if(stale) stale.remove();

  const itensDaLoja = Object.values(GS.CATALOGO_ITENS).filter(
    item => item.loja === nomeLocal
  );

  const overlay = document.createElement('div');
  overlay.id = 'loja-overlay';
  overlay.style.cssText = `
    position: fixed; inset: 0;
    background: rgba(0,0,0,0.85);
    z-index: 200;
    display: flex; align-items: center; justify-content: center;
    opacity: 0; transition: opacity 0.3s ease;
  `;

  const nomesLojas = {
    ferreiro: t('ui.loja.ferreiro'),
    taverna:  t('ui.loja.taverna'),
    mercado:  t('ui.loja.mercado')
  };

  overlay.innerHTML = `
    <div style="width: 700px; max-height: 85vh; background: rgba(10,8,5,0.98);
      border: 1px solid #c8a951; display: flex; flex-direction: column;
      font-family: 'Cinzel', serif;">
      <div style="padding: 20px 24px; border-bottom: 1px solid #c8a95133;
        display: flex; justify-content: space-between; align-items: center;">
        <span style="font-family: 'Cinzel Decorative', serif; color: #c8a951; font-size: 20px;">${nomesLojas[nomeLocal]}</span>
        <div style="display:flex; align-items:center; gap:20px;">
          <span style="color:#c8b89a; font-size:13px;">${t('ui.loja.moedas_n', {n: heroiAtivo.moedas})}</span>
          <button onclick="fecharLoja()" style="background: transparent; border: 1px solid #4a4a4a;
            color: #8a7a5a; font-family: 'Cinzel', serif; font-size: 11px; padding: 6px 12px; cursor: pointer;" data-i18n="ui.ficha.fechar">✕ FECHAR</button>
        </div>
      </div>
      <div data-shop-scroll style="overflow-y: auto; padding: 16px 24px; display: flex; flex-direction: column; gap: 8px;">
        ${itensDaLoja.map(item => {
          const podeComprar = item.permitidoPara.includes('todos') ||
            item.permitidoPara.includes(heroiAtivo.key);
          const semDinheiro = heroiAtivo.moedas < item.preco;
          const inventarioCheio = heroiAtivo.inventario.filter(Boolean).length >= 6;
          return `
            <div data-item-id="${item.id}" style="display: flex; justify-content: space-between; align-items: center;
              padding: 12px 16px; background: rgba(255,255,255,0.02);
              border: 1px solid ${podeComprar ? '#c8a95122' : '#ff413622'};
              opacity: ${podeComprar ? '1' : '0.4'};">
              <div>
                <div style="color:#c8b89a; font-size:13px; margin-bottom:3px;">${item.nome}</div>
                <div style="color:#8a7a5a; font-size:10px; letter-spacing:1px;">${renderDescricaoItem(item)}</div>
              </div>
              <div style="display:flex; align-items:center; gap:12px;">
                <span style="color:#c8a951; font-size:14px; font-weight:bold;">${item.preco} 🪙</span>
                <button onclick="comprarItem('${item.id}')"
                  ${!podeComprar || semDinheiro || inventarioCheio ? 'disabled' : ''}
                  style="background: transparent;
                    border: 1px solid ${!podeComprar || semDinheiro || inventarioCheio ? '#4a4a4a' : '#c8a951'};
                    color: ${!podeComprar || semDinheiro || inventarioCheio ? '#4a4a4a' : '#c8a951'};
                    font-family: 'Cinzel', serif; font-size: 10px; letter-spacing: 2px;
                    padding: 6px 14px; cursor: pointer;">${!podeComprar ? t('ui.loja.restrito_2') : semDinheiro ? t('ui.loja.sem_ouro') : inventarioCheio ? t('ui.loja.cheio') : t('ui.loja.comprar_2')}</button>
              </div>
            </div>
          `;
        }).join('')}
      </div>
    </div>
  `;

  document.body.appendChild(overlay);
  // Aplica tooltip a cada item da loja.
  overlay.querySelectorAll('[data-item-id]').forEach(el => {
    const item = GS.CATALOGO_ITENS[el.dataset.itemId];
    aplicarTooltipAoItemDados(el, item || {id: el.dataset.itemId});
  });
  requestAnimationFrame(() => {
    overlay.style.opacity = '1';
    const restore = window._legacyShopSelectionRestore;
    if(!restore) return;
    if(restore.shopId !== nomeLocal){ window._legacyShopSelectionRestore = null; return; }
    const scroll = overlay.querySelector('[data-shop-scroll]');
    const rows = [...overlay.querySelectorAll('[data-item-id]')];
    const row = rows.find(item => item.dataset.itemId === restore.itemId)
      || (restore.rowIndex >= 0 ? rows[restore.rowIndex] : null);
    if(!scroll || !row){ window._legacyShopSelectionRestore = null; return; }
    scroll.scrollTop = restore.relativeTop == null
      ? restore.scrollTop
      : Math.max(0, row.offsetTop - restore.relativeTop);
    const button = row.querySelector('button:not([disabled])') || row.querySelector('button');
    if(button){
      button.focus?.({preventScroll:true});
      if(typeof _gamepadInput !== 'undefined' && _gamepadInput.active)
        _gamepadSetUiFocus(button);
    }
    window._legacyShopSelectionRestore = null;
  });
}

// Resolve o `shop` exato do servidor a partir do item.
// Ferreiro é dividido em ferreiro_weapon / ferreiro_armor (por tipo de item).
function _resolverShopServidor(item){
  switch(item.loja){
    case 'taverna': return 'taverna';
    case 'mercado': return 'mercador';
    case 'ferreiro':
      return (item.tipo === 'armadura' || item.tipo === 'escudo')
        ? 'ferreiro_armor' : 'ferreiro_weapon';
    default: return null;
  }
}

// Compra AUTORITATIVA: envia ao servidor pelo mesmo caminho do buyItem
// (mensagem shop_buy). O servidor revalida e atualiza bag/gear/gold; o cliente
// reflete via city_state/game_state. (Validações locais = só feedback rápido.)
function comprarItem(itemId){
  const heroi = GS.getHeroiAtivo();
  const item  = GS.CATALOGO_ITENS[itemId];
  if(!item){ console.error('Item não encontrado:', itemId); return; }

  // Feedback rápido (o servidor é a fonte da verdade e revalida)
  if(heroi.moedas < item.preco){
    GS.adicionarLog(t('ui.loja.log_ouro_insuficiente', {nome:heroi.name}));
    return;
  }
  const slotsLivres = heroi.inventario ? heroi.inventario.filter(s => s === null).length : 0;
  if(slotsLivres === 0){
    GS.adicionarLog(t('ui.loja.log_inventario_cheio', {nome:heroi.name}));
    return;
  }

  const shopKey = _resolverShopServidor(item);
  if(!shopKey){
    console.error('Shop não mapeado para loja:', item.loja);
    return;
  }

  // Mesmo formato do buyItem existente — caminho autoritativo do servidor.
  const legacyOverlay = document.getElementById('loja-overlay');
  const legacyScroll = legacyOverlay?.querySelector('[data-shop-scroll]');
  const legacyRows = legacyOverlay ? [...legacyOverlay.querySelectorAll('[data-item-id]')] : [];
  const legacyRow = legacyRows.find(row => row.dataset.itemId === String(itemId));
  window._legacyShopSelectionRestore = {
    shopId: window._lojaUltimaAberta,
    itemId: String(itemId),
    rowIndex: legacyRow ? legacyRows.indexOf(legacyRow) : -1,
    scrollTop: legacyScroll?.scrollTop || 0,
    relativeTop: legacyRow && legacyScroll ? legacyRow.offsetTop - legacyScroll.scrollTop : null
  };
  window._comprando = true;                       // compra em andamento
  send({ type: 'shop_buy', shop: shopKey, item_id: itemId });

  fecharLoja();   // reabre quando o servidor responder (city_state/erro)
  GS.adicionarLog(`🛒 Comprando ${item.nome}...`);
}

// Converte o bag[] do servidor para o inventario[] de tamanho fixo do cliente.
// Tenta casar o id no CATALOGO_ITENS; senão usa os dados do servidor (fallback).
function _converterBagParaInventario(bag, bagSize){
  const size = bagSize || 6;
  const inv  = new Array(size).fill(null);
  (bag || []).forEach((it, i) => {
    if(i >= size || !it) return;
    const cat = GS.CATALOGO_ITENS[it.id];
    // O dado do servidor é a autoridade sobre o NOME (mesma regra que
    // normalizarItemTooltip já usa). Sem isto, um id que exista também no
    // catálogo do cliente descartava o item do servidor inteiro e o nome
    // voltava ao português. Só o nome é sobreposto de propósito: `tipo`,
    // `preco` e os demais campos do catálogo do cliente seguem valendo.
    inv[i] = cat ? { ...cat, nome: it.name || cat.nome }
                 : { id: it.id, nome: it.name || it.id, tipo: it.tipo || it.type || 'item', ...it };
  });
  return inv;
}

// Sincroniza o herói do overlay (client-side) com o estado AUTORITATIVO do
// servidor (gold→moedas, bag→inventario). Chamado quando chega city_state.
function _sincronizarHeroiComServidor(serverPlayer){
  if(!serverPlayer || !GS.getHeroiAtivo) return;
  const heroi = GS.getHeroiAtivo();
  if(typeof serverPlayer.gold === 'number') heroi.moedas = serverPlayer.gold;
  if(Array.isArray(serverPlayer.bag))
    heroi.inventario = _converterBagParaInventario(serverPlayer.bag, serverPlayer.bag_size);
}

function fecharLoja(){
  window._lojaAtualAberta = null;   // limpa ao fechar
  if(!window._comprando) window._legacyShopSelectionRestore = null;
  const overlay = document.getElementById('loja-overlay');
  if(!overlay) return;
  overlay.style.opacity = '0';
  setTimeout(() => overlay.remove(), 300);
}

// ═══════════════════════════════════════════════════════════════════════════
// TOOLTIP DE ITEM — sistema global reutilizável (loja, inventário, HUD).
// Lê GS.CATALOGO_ITENS. Aplicar em qualquer elemento de item via
// aplicarTooltipAoItem(elemento, itemId). (DOM → vive em game.js.)
// ═══════════════════════════════════════════════════════════════════════════
let _itemTooltipReady = false;
// Elemento que abriu o quadro. Remover (ou ocultar) um elemento que está sob o
// cursor NÃO dispara mouseleave — é o caso de pegar um item do baú, que
// re-renderiza a lista e destrói a linha em hover. Sem esse registro o quadro
// ficava preso na tela até outro item receber mouseenter+mouseleave.
let _itemTooltipDono = null;
function _marcarDonoTooltip(el){ _itemTooltipDono = el || null; }
function _initItemTooltip(){
  if(_itemTooltipReady) return;
  _itemTooltipReady = true;
  let tooltip = document.getElementById('item-tooltip');
  if(!tooltip){
    tooltip = document.createElement('div');
    tooltip.id = 'item-tooltip';
    tooltip.style.cssText = `
      position: fixed; z-index: 1200; width: 240px;
      background: rgba(8, 6, 4, 0.97);
      border: 1px solid #c8a951;
      font-family: 'Cinzel', serif;
      pointer-events: none; opacity: 0;
      transition: opacity 0.15s ease;
      box-shadow: 0 4px 24px rgba(0,0,0,0.8);
    `;
    document.body.appendChild(tooltip);
  }
  // Posiciona o tooltip perto do cursor (evita sair da tela).
  document.addEventListener('mousemove', (e) => {
    const t = document.getElementById('item-tooltip');
    if(!t || t.style.opacity === '0') return;
    // Dono sumiu da tela (ou o cursor já saiu dele) sem que mouseleave ocorresse.
    if(_itemTooltipDono && !_itemTooltipDono.contains(e.target)){ esconderTooltip(); return; }
    const margin = 16;
    const rect = t.getBoundingClientRect();
    let x = e.clientX + margin;
    if(x + rect.width > window.innerWidth) x = e.clientX - rect.width - margin;
    let y = e.clientY + margin;
    if(y + rect.height > window.innerHeight) y = e.clientY - rect.height - margin;
    t.style.left = x + 'px';
    t.style.top  = y + 'px';
  });
}

function esconderTooltip(){
  const t = document.getElementById('item-tooltip');
  if(t) t.style.opacity = '0';
  _itemTooltipDono = null;
  if(window._animadoHover){ window._animadoHover = null; if(GS.gameState) renderMap(GS.gameState); }
}

function fecharQuadrosFlutuantes(){
  esconderTooltip();
  ocultarTooltipMagia();
  const quadroMapa = document.getElementById('tooltip');
  if(quadroMapa) quadroMapa.style.display = 'none';
}

function renderLinhaTooltip(icone, label, valor){
  return `<div style="display:flex; justify-content:space-between; align-items:flex-start; margin-bottom:5px; gap:8px;">
    <span style="color:#8a7a5a; font-size:10px; white-space:nowrap;">${icone} ${label}</span>
    <span style="color:#c8b89a; font-size:10px; text-align:right;">${valor}</span>
  </div>`;
}

function normalizarItemTooltip(item){
  const bruto = item || {};
  const catalogado = (typeof GS !== 'undefined' && GS.CATALOGO_ITENS && bruto.id)
    ? (GS.CATALOGO_ITENS[bruto.id] || {}) : {};
  const porSlot = { weapon:'arma', armor:'armadura', shield:'escudo', ammo:'municao', bag:'consumivel', instrumento:'instrumento' };
  const tipo = bruto.tipo || catalogado.tipo
    || (bruto.tipo_item === 'instrumento' ? 'instrumento' : null)
    || porSlot[bruto.item_slot] || porSlot[bruto.kind]
    || (bruto.kind === 'armor' ? 'armadura' : bruto.kind === 'shield' ? 'escudo' : 'item');
  const permitido = bruto.permitidoPara || catalogado.permitidoPara || bruto.allowed_classes || ['todos'];
  return {
    ...catalogado, ...bruto, tipo,
    nome: bruto.nome || bruto.name || catalogado.nome || catalogado.name || 'Item',
    preco: bruto.preco ?? bruto.price ?? catalogado.preco ?? catalogado.price ?? 0,
    dano: bruto.dano || bruto.die || catalogado.dano,
    tipoDano: bruto.tipoDano || bruto.elemento || (bruto.extra_damage_types || []).join(', ') || catalogado.tipoDano,
    categoria: bruto.categoria || catalogado.categoria,
    alcance: bruto.alcance ?? bruto.range ?? catalogado.alcance,
    areaRaio: bruto.areaRaio ?? bruto.area_raio ?? catalogado.areaRaio,
    bonusCA: bruto.bonusCA ?? bruto.ac_bonus ?? (bruto.effect === 'def_' ? bruto.value : catalogado.bonusCA),
    reducaoDano: bruto.reducaoDano ?? bruto.damage_reduction ?? catalogado.reducaoDano,
    quantidade: bruto.ammo_count ?? bruto.quantidade ?? catalogado.quantidade,
    danoExtra: bruto.danoExtra ?? bruto.damage_bonus ?? bruto.extra_damage ?? catalogado.danoExtra,
    arremesso: bruto.arremesso ?? catalogado.arremesso ?? (bruto.throw_range != null),
    arremessavel: bruto.arremessavel ?? catalogado.arremessavel ?? bruto.effect === 'throwable',
    alcanceArremesso: bruto.alcanceArremesso ?? bruto.throw_range ?? catalogado.alcanceArremesso,
    saveTipo: bruto.save?.tipo || bruto.save || bruto.save_type || catalogado.saveTipo,
    saveCD: bruto.save?.cd ?? bruto.dificuldade ?? bruto.save_dc ?? catalogado.saveCD,
    efeito: bruto.efeito || catalogado.efeito,
    controle: bruto.controle || catalogado.controle,
    zona: bruto.zona || catalogado.zona,
    duracao: bruto.duracao ?? bruto.duration ?? catalogado.duracao,
    descricao: bruto.descricao || bruto.description || catalogado.descricao,
    permitidoPara: Array.isArray(permitido) ? permitido : ['todos'],
  };
}

function gerarConteudoTooltip(item){
  item = normalizarItemTooltip(item);
  // Só a COR fica no mapa; o rótulo vem de ui.item.tipo_label.<tipo>.
  const coresTipo = {
    arma:'#c8a951', armaDistancia:'#c8a951', armadura:'#4a9eff', escudo:'#4a9eff',
    secundario:'#aaaaaa', consumivel:'#2ecc40', municao:'#ff851b', instrumento:'#4db8ff',
    varinha:'#cc44ff', itemMagico:'#cc44ff'
  };
  const tipoInfo = {
    cor:   coresTipo[item.tipo] || '#c8b89a',
    label: _rotulo(item.tipo, 'ui.item.tipo_label', t('ui.item.tipo_label.padrao')),
  };
  const linhas = [];

  // Instrumentos têm catálogo procedural (base + qualidade + origem), então
  // usam o quadro específico mesmo quando aparecem na bolsa, loja, venda ou
  // em um baú e não apenas no botão de habilidade do bardo.
  if(item.tipo === 'instrumento' && typeof _tooltipInstrumentoHTML === 'function')
    return _tooltipInstrumentoHTML(item);

  const itemAcao = _itemAcaoMeta(item);
  if(itemAcao)
    linhas.push(renderLinhaTooltip('⚡', t('ui.acoes.uso'), _esc(t(itemAcao.label))));

  if(item.dano && item.dano !== '—') linhas.push(renderLinhaTooltip('🎲',t('ui.tooltip.dano'),item.dano));
  if(item.danoUmaMao){
    linhas.push(renderLinhaTooltip('🎲',t('ui.tooltip.uma_mao'),item.danoUmaMao));
    linhas.push(renderLinhaTooltip('🎲',t('ui.tooltip.duas_maos'),item.danoDuasMaos));
  }
  if(item.atributo) linhas.push(renderLinhaTooltip('📊',t('ui.tooltip.atributo'),_rotulo(item.atributo,'ui.atributo',item.atributo)));
  if(item.tipoDano) linhas.push(renderLinhaTooltip('💠',t('ui.tooltip.tipo_dano'),_rotulo(String(item.tipoDano).toLowerCase(),'ui.dano_tipo',item.tipoDano)));
  if(item.categoria) linhas.push(renderLinhaTooltip('⚔️',t('ui.tooltip.categoria'),_rotulo(item.categoria,'ui.item.categoria',item.categoria)));
  if(item.bonusCA) linhas.push(renderLinhaTooltip('🛡️',t('ui.tooltip.bonus_ca'),`+${item.bonusCA}`));
  if(item.reducaoDano) linhas.push(renderLinhaTooltip('🛡️',t('ui.tooltip.reducao_dano'),t('ui.tooltip.reducao_dano_val',{n:item.reducaoDano})));
  if(item.tipo === 'armadura' || item.kind === 'armor'){
    const cat = item.armor_category ? _rotulo(item.armor_category,'ui.item.armadura_cat',item.armor_category) : '';
    const mats = (item.corrosion_materials || []).map(m => _rotulo(m,'ui.item.material',m));
    if(cat) linhas.push(renderLinhaTooltip('🧱',t('ui.tooltip.categoria'),cat));
    if(mats.length) linhas.push(renderLinhaTooltip('🧪',t('ui.tooltip.materiais'),mats.join(' + ')));
    if(item.corrosao_resistente) linhas.push(renderLinhaTooltip('🛡️',t('ui.tooltip.resistencia'),t('ui.tooltip.resistente_corrosao')));
  }
  if(item.silver && (item.tipo === 'arma' || item.item_slot === 'weapon' || item.kind === 'weapon'))
    linhas.push(renderLinhaTooltip('✨',t('ui.tooltip.efeito'),t('ui.item.desc.prata_arma')));
  if(item.alcance) linhas.push(renderLinhaTooltip('📏',t('ui.tooltip.alcance'),t('ui.tooltip.quadrados',{n:item.alcance})));
  if(item.alcanceEspecial) linhas.push(renderLinhaTooltip('📏',t('ui.tooltip.alcance'),item.alcanceEspecial.descricao));
  // O servidor envia a Lança com `reach: "lanca"`; transforme esse campo
  // numa descrição explícita também no tooltip detalhado.
  if(!item.alcanceEspecial && item.reach === 'lanca')
    linhas.push(renderLinhaTooltip('📏',t('ui.tooltip.alcance'),t('ui.item.desc.alcance_lanca')));
  if(item.alcanceArremesso) linhas.push(renderLinhaTooltip('🎯',t('ui.tooltip.arremesso'),t('ui.tooltip.quad_diagonais',{n:item.alcanceArremesso})));
  if(item.arremessavel && item.alvo === 'area' && item.areaRaio != null)
    linhas.push(renderLinhaTooltip('💥',t('ui.tooltip.area'),`raio ${item.areaRaio}`));
  if(item.saveTipo && item.saveCD != null)
    linhas.push(renderLinhaTooltip('🛡️',t('ui.tooltip.resistencia'),`${String(item.saveTipo).replace(/^./, c => c.toUpperCase())} CD ${item.saveCD}`));
  if(item.arremesso || item.arremessavel) linhas.push(renderLinhaTooltip('⚠️',t('ui.tooltip.risco'),t('ui.tooltip.risco_val')));
  if(item.linhaVisao) linhas.push(renderLinhaTooltip('👁️',t('ui.tooltip.linha_visao'),t('ui.tooltip.linha_visao_val')));
  if(item.tipo === 'arma') linhas.push(renderLinhaTooltip('🛡️',t('ui.tooltip.escudo'), item.escudo ? t('ui.tooltip.permitido') : t('ui.tooltip.nao_permitido')));
  if(item.duasMaos && !item.modosDuasMaos) linhas.push(renderLinhaTooltip('✋',t('ui.tooltip.uso'),t('ui.tooltip.requer_duas_maos')));
  if(item.modosDuasMaos) linhas.push(renderLinhaTooltip('✋',t('ui.tooltip.uso'),t('ui.tooltip.uma_ou_duas')));
  if(item.slotSecundario === 'flechas') linhas.push(renderLinhaTooltip('🏹',t('ui.tooltip.municao'),t('ui.tooltip.requer_flechas')));
  if(item.fome > 0) linhas.push(renderLinhaTooltip('🍖',t('ui.tooltip.fome'),`+${item.fome}`));
  if(item.sede > 0) linhas.push(renderLinhaTooltip('💧',t('ui.tooltip.sede'),`+${item.sede}`));
  if(item.effect === 'heal')
    linhas.push(renderLinhaTooltip('❤️',t('ui.tooltip.cura_por_uso'),`+${item.value ?? item.valor ?? 0} HP`));
  if(item.effect === 'full_heal')
    linhas.push(renderLinhaTooltip('❤️',t('ui.tooltip.cura_por_uso'),t('ui.item.desc.cura_total')));
  if(item.duracao) linhas.push(renderLinhaTooltip('⏱️',t('ui.tooltip.duracao'),t('ui.tooltip.rodadas',{n:item.duracao})));
  if(item.bonusVisao) linhas.push(renderLinhaTooltip('👁️',t('ui.tooltip.visao'),t('ui.tooltip.mais_quadrado',{n:item.bonusVisao})));
  if(item.quantidade && item.effect !== 'ammo' && item.tipo !== 'municao') linhas.push(renderLinhaTooltip('📦',t('ui.tooltip.quantidade'),t('ui.tooltip.unidades_slot',{n:item.quantidade})));
  if(item.effect === 'ammo' || item.tipo === 'municao') {
    linhas.push(renderLinhaTooltip('🏹',t('ui.tooltip.restantes'),t('ui.tooltip.projeteis',{n:item.quantidade ?? 0})));
    if(item.danoExtra) linhas.push(renderLinhaTooltip('💥',t('ui.tooltip.dano_adicional'),`+${item.danoExtra}${item.tipoDano ? ` (${item.tipoDano})` : ''}`));
  }
  if(item.tipo === 'veneno' || item.effect === 'coat_poison') {
    const e = item.efeito || {};
    if(e.operacao === 'dano' && e.dano != null)
      linhas.push(renderLinhaTooltip('☠️',t('ui.tooltip.dano'),t('ui.tooltip.n_por_rodada', {n: e.dano})));
    if(e.operacao === 'reduzir' && e.atributo && e.valor != null)
      linhas.push(renderLinhaTooltip('☠️',t('ui.tooltip.efeito'),t('ui.tooltip.reduz_atributo_em', {atributo: e.atributo, valor: e.valor})));
    if(e.operacao === 'penalidade' && Array.isArray(e.atributo))
      linhas.push(renderLinhaTooltip('☠️',t('ui.tooltip.efeito'),e.atributo.map((a,i)=>`${a} ${e.valor?.[i] ?? ''}`).join(', ')));
    if(e.operacao === 'status' || e.operacao === 'petrificar' || e.operacao === 'cegar')
      linhas.push(renderLinhaTooltip('☠️',t('ui.tooltip.efeito'),e.atributo || e.operacao));
    if(e.duracao != null) linhas.push(renderLinhaTooltip('⏳',t('ui.tooltip.duracao'),`${e.duracao} rodada(s)`));
    if(e.duracaoFalha != null) linhas.push(renderLinhaTooltip('⚠️',t('ui.tooltip.falha_parcial'),`${e.duracaoFalha} rodada(s)`));
    if(item.descricao) linhas.push(renderLinhaTooltip('📜',t('ui.tooltip.efeito'),item.descricao));
    if(e.save && e.dificuldade != null) {
      const anula = e.anula === false ? t('ui.tooltip.efeito_parcial') : t('ui.tooltip.anula');
      linhas.push(renderLinhaTooltip('🛡️',t('ui.tooltip.resistencia'),t('ui.tooltip.resistencia_val',{save:String(e.save).replace(/^./, c => c.toUpperCase()), cd:e.dificuldade, anula})));
    }
  } else if(item.effect === 'ale') {
    linhas.push(renderLinhaTooltip('🍺',t('ui.tooltip.efeito'),t('ui.item.desc.cerveja',{n:item.value||0})));
  } else if(item.effect === 'wine') {
    linhas.push(renderLinhaTooltip('🍷',t('ui.tooltip.efeito'),t('ui.item.desc.vinho',{n:item.value||0})));
  } else if(item.descricao) {
    linhas.push(renderLinhaTooltip('✨',t('ui.tooltip.efeito'),item.descricao));
  }
  if(item.slotsMagia) linhas.push(renderLinhaTooltip('✨',t('ui.tooltip.slots_magia'),`${item.slotsMagia}`));
  if(item.slotsExtras) linhas.push(renderLinhaTooltip('🎒',t('ui.tooltip.slots_extras'),t('ui.tooltip.slots_extras_val',{n:item.slotsExtras})));

  const especiais = gerarHabilidadesEspeciais(item);
  const nomesHerois = { victorCoiceBravo:'Victor', richardCavaleiro:'Richard', lewis:'Lewis', luccas:'Luccas', henrique:'Henrique', pedro:'Pedro' };
  const usuariosTexto = item.permitidoPara.includes('todos')
    ? t('ui.tooltip.todos_herois')
    : item.permitidoPara.map(k => nomesHerois[k] || k).join(', ');

  return `
    <div style="padding:10px 14px 8px; border-bottom:1px solid #c8a95133;">
      <div style="font-family:'Cinzel Decorative',serif; color:${tipoInfo.cor}; font-size:13px; margin-bottom:2px;">${item.nome}</div>
      <div style="color:${tipoInfo.cor}88; font-size:9px; letter-spacing:3px;">${tipoInfo.label}</div>
    </div>
    <div style="padding:10px 14px;">${linhas.join('')}</div>
    ${especiais ? `
      <div style="padding:8px 14px; border-top:1px solid #c8a95133; border-bottom:1px solid #c8a95133; background:rgba(200,169,81,0.05);">
        <div style="color:#c8a951; font-size:9px; letter-spacing:3px; margin-bottom:6px;">${t('ui.tooltip.habilidade_especial')}</div>
        ${especiais}
      </div>
    ` : ''}
    <div style="padding:8px 14px; border-top:1px solid #c8a95133;">
      <div style="color:#8a7a5a; font-size:9px; letter-spacing:2px; margin-bottom:3px;">${t('ui.tooltip.pode_usar')}</div>
      <div style="color:#c8b89a; font-size:10px;">${usuariosTexto}</div>
    </div>
    <div style="padding:8px 14px; border-top:1px solid #c8a95133; display:flex; justify-content:space-between; align-items:center;">
      <span style="color:#8a7a5a; font-size:9px; letter-spacing:2px;">${t('ui.tooltip.preco')}</span>
      <span style="color:#c8a951; font-size:14px; font-weight:bold;">${item.preco} 🪙</span>
    </div>
  `;
}

function gerarHabilidadesEspeciais(item){
  const especiais = [];
  const L = (txt) => `<div style="color:#c8b89a; font-size:10px; line-height:1.6; margin-bottom:6px;">${txt}</div>`;

  if(item.arremesso && item.id !== 'lanca_curta')   // lança tem bloco próprio (usa Força, não Destreza)
    especiais.push(L(t('ui.habilidade.arremesso', {p1: item.alcanceArremesso})));
  if(item.id === 'chicote')
    especiais.push(L(t('ui.habilidade.alcance_chicote')));
  if(item.id === 'warhammer' || item.id === 'martelo' || /martelo de guerra/i.test(item.name || ''))
    especiais.push(L(t('ui.habilidade.impacto_martelo')));
  if(item.id === 'machado_orc' || /machado de guerra [óo]rquico/i.test(item.name || ''))
    especiais.push(L(t('ui.habilidade.impacto_machado_orc')));
  if(item.id === 'maca' || /maça/i.test(item.name || ''))
    especiais.push(L(t('ui.habilidade.impacto_maca')));
  if(item.id === 'mangual' || /mangual/i.test(item.name || ''))
    especiais.push(L(t('ui.habilidade.impacto_mangual')));
  if(['shortsword','longsword','bastsword','espada2m'].includes(item.id)
      || /espada curta|espada longa|espada bastarda|espada de 2/i.test(item.name || ''))
    especiais.push(L(t('ui.habilidade.critico_espada')));
  if(item.id === 'machado_duplo' || /machado duplo/i.test(item.name || ''))
    especiais.push(L(`🪓 <strong style="color:#c8a951" data-i18n="ui.hud.ataque_duplo">Ataque Duplo:</strong> Ao obter 19 ou 20 natural no d20, ganha um segundo ataque manual no mesmo turno.`));
  if(item.id === 'lanca_curta'){
    especiais.push(t('ui.habilidade.arremesso_lanca'));
  }
  if(item.id === 'bordao')
    especiais.push(L(t('ui.habilidade.impacto_bordao')));
  if(item.id === 'staff')
    especiais.push(L(t('ui.habilidade.cajado_arcano')));
  if(item.id === 'lanca' || item.reach === 'lanca')
    especiais.push(L(t('ui.habilidade.alcance_lanca')));
  if(item.id === 'lanca_longa' || item.id === 'alabarda')
    especiais.push(L(t('ui.habilidade.alcance_cajado')));
  if(item.id === 'espada_bastarda')
    especiais.push(L(t('ui.habilidade.versatil')));
  if(item.danoExtra)
    especiais.push(L(t('ui.habilidade.incendiario', {p1: item.danoExtra})));
  if(item.id === 'tocha')
    especiais.push(L(t('ui.habilidade.iluminacao', {p1: item.duracao})));
  if(item.tipo === 'varinha')
    especiais.push(L(t('ui.habilidade.armazenamento_magia', {p1: item.slotsMagia})));
  if(item.tipo === 'itemMagico' && item.slotsExtras)
    especiais.push(L(t('ui.habilidade.expansao_inventario', {p1: item.slotsExtras})));
  if(item.duasMaos && !item.modosDuasMaos && item.tipo === 'arma')
    especiais.push(L(t('ui.habilidade.duas_maos')));
  if (item.tipo === 'veneno') {
    const e = item.efeito || {};
    especiais.push(t('ui.habilidade.veneno', {p1: item.descricao, p2: e.dificuldade, p3: e.anula ? t('ui.hud.anula_completamente') : t('ui.hud.efeito_parcial_no_sucesso')}));
  }
  if (typeof GS !== 'undefined' && GS.isDagger && GS.isDagger(item)) {
    especiais.push(t('ui.habilidade.ataque_bonus_secundaria'))
  }
  if (typeof GS !== 'undefined' && GS.isOffhandWeapon && GS.isOffhandWeapon(item)
      && !(GS.isDagger && GS.isDagger(item))) {
    especiais.push(t('ui.habilidade.ataque_extra_secundaria'))
  }

  return especiais.length > 0 ? especiais.join('') : null;
}

// Itens vindos de baús/decorações chegam como instâncias do servidor e nem
// sempre estão no catálogo local. Normaliza os nomes para reutilizar o mesmo
// quadro detalhado exibido ao passar o mouse sobre uma magia.
function aplicarTooltipAoItemDados(elemento, item){
  if(!elemento || !item) return;
  elemento.addEventListener('mouseenter', () => {
    _initItemTooltip();
    _marcarDonoTooltip(elemento);
    const catalogado = GS.CATALOGO_ITENS[item.id] || {};
    const dados = { ...catalogado, ...item,
      nome: item.nome || item.name || catalogado.nome || catalogado.name || 'Item',
      preco: item.preco ?? item.price ?? catalogado.preco ?? catalogado.price ?? 0 };
    const t = document.getElementById('item-tooltip');
    if(!t) return;
    t.innerHTML = gerarConteudoTooltip(dados);
    t.style.borderColor = corBordaPorPreco(dados.preco);
    t.style.opacity = '1';
  });
  elemento.addEventListener('mouseleave', () => esconderTooltip());
}

// ── Tooltip de PERGAMINHO: nível de conjurador, dano/alcance/CD no nível e a
// chance de falha para o personagem ATUAL. Usa item.preview (vindo do servidor).
const _saveLabelCli = tipo => _rotulo(tipo, 'ui.resistencia', tipo);
function _chanceFalhaPergaminhoCli(item){
  const me = GS.me;
  if(!me) return null;
  if(me.class_id !== 'mage' && me.class_id !== 'cleric') return { naoPode:true };
  const nivel = item.nivel_conjurador || 1;
  const lvlPct = Math.min(95, Math.max(0, (nivel - (me.level||1))) * 15);
  const mg = (typeof GRIMORIO_CLIENT !== 'undefined') ? GRIMORIO_CLIENT[item.magia_id] : null;
  const classes = (mg && mg.classe) || [];
  const cross = classes.length > 0 && !classes.includes(me.class_id);
  return { lvlPct, cross };
}
function _tooltipPergaminhoHTML(item){
  const pv = item.preview || {};
  const mg = (typeof GRIMORIO_CLIENT !== 'undefined') ? GRIMORIO_CLIENT[item.magia_id] : null;
  const nomeMagia = (mg && mg.nome) || item.magia_id;
  const icone = (mg && mg.icone) || '📜';
  // Ordinal por chave: "1º" vira "1st" em inglês, e um ternário com o texto
  // cravado sairia em português no meio da frase traduzida.
  const circ = _rotulo(item.circulo, 'ui.magia.ordinal', t('ui.magia.ordinal.terceiro'));
  const linhas = [];
  linhas.push(renderLinhaTooltip('🧙',t('ui.pergaminho.conjurador'), t('ui.pergaminho.nivel', {n:pv.nivel || item.nivel_conjurador || 1})));
  if(item.int_bonus) linhas.push(renderLinhaTooltip('🧠','INT', t('ui.pergaminho.int_bonus', {n:item.int_bonus})));
  if(pv.dano) linhas.push(renderLinhaTooltip('🎲',t('ui.pergaminho.dano'), pv.dano + (pv.talento_dano ? ' ×1.5' : '')));
  if(pv.alcance != null)
    linhas.push(renderLinhaTooltip('📏',t('ui.pergaminho.alcance'), pv.alcance === 0 ? t('ui.pergaminho.no_conjurador') : t('ui.pergaminho.quadrados', {n:pv.alcance})));
  if(pv.area_raio) linhas.push(renderLinhaTooltip('💥',t('ui.pergaminho.area'), t('ui.pergaminho.raio', {n:pv.area_raio})));
  if(pv.cd != null) linhas.push(renderLinhaTooltip('🛡️',t('ui.pergaminho.cd_save'),
      `${pv.cd} (${_saveLabelCli(pv.save)})${pv.talento_cd ? ' ⬆' : ''}`));
  if(!pv.dano && pv.efeito) linhas.push(renderLinhaTooltip('✨',t('ui.pergaminho.efeito'), pv.efeito));
  else if(pv.duracao) linhas.push(renderLinhaTooltip('⏳',t('ui.pergaminho.duracao'),
      `${t('ui.pergaminho.rodadas', {n:pv.duracao})}${pv.talento_duracao ? ' +1' : ''}`));
  // Talentos do Pedro gravados no pergaminho.
  const tals = [];
  if(pv.talento_dano)    tals.push(t('ui.pergaminho.talento_dano'));
  if(pv.talento_cd)      tals.push(t('ui.pergaminho.talento_cd'));
  if(pv.talento_duracao) tals.push(t('ui.pergaminho.talento_duracao'));
  if(tals.length) linhas.push(renderLinhaTooltip('✦',t('ui.pergaminho.talentos'), tals.join(', ')));
  // Chance de falha para o personagem atual.
  const cf = _chanceFalhaPergaminhoCli(item);
  let falhaTxt;
  if(!cf) falhaTxt = '—';
  else if(cf.naoPode) falhaTxt = `<span style="color:#ff6b6b">${t('ui.pergaminho.so_conjurador')}</span>`;
  else {
    falhaTxt = (cf.lvlPct > 0 ? `${cf.lvlPct}%` : t('ui.pergaminho.falha_nenhuma'));
    if(cf.cross) falhaTxt += ` <span style="color:#ff6b6b">${t('ui.pergaminho.falha_classe')}</span>`;
  }
  linhas.push(renderLinhaTooltip('🎯',t('ui.pergaminho.falha'), falhaTxt));
  if(item.price != null) linhas.push(renderLinhaTooltip('💰',t('ui.pergaminho.preco'), t('ui.pergaminho.moedas', {n:item.price})));
  return `
    <div style="padding:10px 12px;">
      <div style="color:#c8a951;font-size:13px;font-weight:700;margin-bottom:3px;">${icone} ${nomeMagia}</div>
      <div style="color:#8a7a5a;font-size:9px;letter-spacing:1px;margin-bottom:8px;">${t('ui.pergaminho.rodape', {circulo:circ})}</div>
      ${linhas.join('')}
    </div>`;
}
function aplicarTooltipPergaminho(elemento, item){
  if(!elemento || !item) return;
  elemento.addEventListener('mouseenter', () => {
    _initItemTooltip();
    _marcarDonoTooltip(elemento);
    const t = document.getElementById('item-tooltip');
    if(!t) return;
    t.innerHTML = _tooltipPergaminhoHTML(item);
    t.style.borderColor = corBordaPorPreco(item.price || 0);
    t.style.opacity = '1';
  });
  elemento.addEventListener('mouseleave', () => esconderTooltip());
}

// ── Tooltip de Instrumento do Bardo (Fase 1) ────────────────────────────────
// Instrumentos não vivem em GS.CATALOGO_ITENS, então têm seu próprio quadro de
// hover (espelha aplicarTooltipPergaminho): mostra a habilidade, o que ela faz e
// o custo. Lê os metadados de GS.instrumentoBase + os stats derivados de
// GS.instrumentoStatsClient.
function _tooltipInstrumentoHTML(inst){
  const b  = (typeof GS !== 'undefined' && GS.instrumentoBase) ? GS.instrumentoBase(inst.base) : null;
  const st = (typeof GS !== 'undefined' && GS.instrumentoStatsClient) ? GS.instrumentoStatsClient(inst) : null;
  if(!b) return `<div style="padding:12px 14px;color:#c8b89a;font-size:11px;">${inst.name || t('ui.instrumento.instrumento')}</div>`;
  const passiva = b.modo === 'passiva';
  const maosTxt = t(b.maos === 2 ? 'ui.instrumento.duas_maos' : 'ui.instrumento.uma_mao');
  const linhas = [];
  if(st){
    if(st.alcance != null) linhas.push(renderLinhaTooltip('🎯', t('ui.pergaminho.alcance'), t('ui.instrumento.quadrados', {n:st.alcance})));
    if(st.raio    != null) linhas.push(renderLinhaTooltip('💥', t('ui.instrumento.raio'),      t('ui.instrumento.quadrados', {n:st.raio})));
    if(st.cone    != null) linhas.push(renderLinhaTooltip('🔻', t('ui.tooltip.cone'),          t('ui.instrumento.quadrados', {n:st.cone})));
    if(st.dano    != null) linhas.push(renderLinhaTooltip('🎵', t('ui.pergaminho.dano'),       t('ui.instrumento.dano_sonoro', {dano:st.dano})));
    if(st.dado    != null) linhas.push(renderLinhaTooltip('🎲', t('ui.pergaminho.dano'),       st.dado));
    if(st.duracao != null) linhas.push(renderLinhaTooltip('⏳', t('ui.pergaminho.duracao'),    t('ui.instrumento.rodadas', {n:st.duracao})));
    if(st.medo    != null) linhas.push(renderLinhaTooltip('😨', t('ui.tooltip.medo'),           `${st.medo} rodada(s)`));
    if(st.push    != null) linhas.push(renderLinhaTooltip('↗️', t('ui.tooltip.empurrao'),       `${st.push} quadrado(s)`));
    if(st.fracao  != null) linhas.push(renderLinhaTooltip('⚔️', t('ui.tooltip.dano_repetido'),  `${st.fracao}%`));
    if(Array.isArray(st.atributos) && st.atributos.length)
      linhas.push(renderLinhaTooltip('✨', t('ui.tooltip.efeito'), st.atributos.join(', ')));
  }
  if(b.efeito?.save) linhas.push(renderLinhaTooltip('🛡️', t('ui.tooltip.resistencia'), String(b.efeito.save).replace(/^./, c => c.toUpperCase())));
  const custoLinha = passiva
    ? renderLinhaTooltip('🎼', t('ui.instrumento.custo'), t('ui.instrumento.custo_cancao'))
    : renderLinhaTooltip('🍖', t('ui.instrumento.custo'), `🍖${(st && st.custo_fome) ?? 0}  💧${(st && st.custo_sede) ?? 0}`);
  const qualidade = inst.qualidade ? _rotulo(inst.qualidade, 'ui.item.qualidade', inst.qualidade) : '';
  const origem = inst.origem && inst.origem !== 'humana' ? _rotulo(inst.origem, 'ui.item.origem', inst.origem) : '';
  const encantamento = inst.encantamento === 'runico' ? t('ui.tooltip.runico') : '';
  const detalhes = [qualidade, origem, encantamento].filter(Boolean).join(' · ');
  return `
    <div style="padding:10px 14px;border-bottom:1px solid #c8a95133;">
      <div style="color:#e8cf7e;font-weight:bold;font-size:13px;">${b.icon} ${inst.name || b.nome}</div>
      <div style="color:#8a7a5a;font-size:9px;letter-spacing:2px;margin-top:2px;">${t('ui.instrumento.rotulo_tipo')}${passiva ? t('ui.instrumento.passivo_sufixo') : ''}</div>
      ${detalhes ? `<div style="color:#b8a888;font-size:9px;margin-top:5px;">${detalhes}</div>` : ''}
    </div>
    <div style="padding:10px 14px;">
      <div style="color:#c8a951;font-size:11px;font-weight:bold;margin-bottom:4px;">${passiva ? '✨' : '♪'} ${b.habilidade_nome}</div>
      <div style="color:#b8a888;font-size:10px;line-height:1.45;margin-bottom:8px;">${b.desc || ''}</div>
      ${linhas.join('')}
      ${custoLinha}
      <div style="color:#7a6a4a;font-size:9px;margin-top:6px;font-style:italic;">${maosTxt}</div>
    </div>`;
}

function aplicarTooltipInstrumento(elemento, inst){
  if(!elemento || !inst) return;
  elemento.addEventListener('mouseenter', () => {
    _initItemTooltip();
    _marcarDonoTooltip(elemento);
    const t = document.getElementById('item-tooltip');
    if(!t) return;
    t.innerHTML = _tooltipInstrumentoHTML(inst);
    t.style.borderColor = '#4db8ff';   // azul — instrumento (mão do escudo)
    t.style.opacity = '1';
  });
  elemento.addEventListener('mouseleave', () => esconderTooltip());
}

// Cor da borda do tooltip por raridade (faixa de preço).
function corBordaPorPreco(preco){
  if(preco >= 300) return '#cc44ff'; // roxo — lendário
  if(preco >= 100) return '#4a9eff'; // azul — raro
  if(preco >= 40)  return '#2ecc40'; // verde — incomum
  return '#c8a951';                  // dourado — comum
}

function enterDungeon(){
  if(!GS.ws || GS.ws.readyState !== 1){
    toast(t('ui.conexao.sem_servidor_reinicie'), 'var(--red)');
    return;
  }
  send({type:'enter_dungeon'});
}

function _atualizarBotaoEncerrarTurno(state){
  const btn = document.getElementById('btn-end-turn');
  if(!btn) return;
  const me = (state?.players || []).find(p => p.id === GS.myPid);
  const podeEncerrar = !!(me && me.alive !== false && state?.phase === 'playing'
    && (GS.isMyTurn || state.current_turn === GS.myPid
        || state.last_stand_pid === GS.myPid
        || state.animados_turn === GS.myPid));
  btn.disabled = !podeEncerrar;

  // Rótulo dinâmico durante a janela dos servos: "⏭ Encerrar servo (2/3)".
  // `_i18nApply` sobrescreve o textContent de todo [data-i18n], então o atributo
  // SAI enquanto o texto é calculado e VOLTA quando não é mais. Esta função roda
  // a cada game_state, e a troca de idioma reenvia o estado — então o rótulo
  // acompanha o idioma sozinho, sem entrar na lista do _setLang.
  const span = btn.querySelector('span');
  if(!span) return;
  // Dict por pid: cada jogador lê a própria entrada.
  const atual = state?.animados_atual?.[GS.myPid] ?? null;
  const naFila = state?.animados_turn === GS.myPid && atual !== null;
  if(naFila){
    const ordem = state.animados_order || [];
    const total = ordem.length + (_temPrisioneiroNaFila(state) ? 1 : 0);
    // A posição é o índice do servo da vez na ordem de iniciativa. O prisioneiro
    // não está em `animados_order`: ele é sempre o último da fila.
    const idx = ordem.indexOf(atual);
    const pos = (idx >= 0) ? idx + 1 : total;
    span.removeAttribute('data-i18n');
    span.textContent = atual === 'prisoner'
      ? t('ui.hud.encerrar_prisioneiro')
      : t('ui.hud.encerrar_servo', {pos, total});
  } else if(!span.hasAttribute('data-i18n')){
    span.setAttribute('data-i18n', 'ui.hud.encerrar_turno');
    span.textContent = t('ui.hud.encerrar_turno');
  }
}

// O prisioneiro liberto ocupa a última posição da fila da janela pós-turno.
function _temPrisioneiroNaFila(state){
  const pr = state?.prisoner;
  return !!(pr && pr.alive && pr.freed && pr.rescuer_pid === GS.myPid);
}

function handleGameState(msg){
  // GS._handle already updated GS.gameState, GS.isMyTurn, GS.pendingSkill
  // Atualiza antes do restante do HUD: um erro em qualquer painel opcional não
  // pode deixar o botão preso no estado desabilitado do turno anterior.
  _reconciliarEfeitosVisuaisLocais(msg);
  if(!GS.isMyTurn) {
    _clearGamepadEndTurnConfirm();
    _aimEnd({silent:true, reason:'turn_changed'});
  }
  // Mesmo se o estado recebido chegar no meio de uma animação de passo, o loop
  // 3D deve reconciliar os ícones no frame seguinte.
  if(g3) g3._activeEffectsDirty = true;
  _atualizarBotaoEncerrarTurno(msg);
  syncDiceCanvas();
  renderMap(msg);
  centerOnPlayer(msg);
  renderPlayers(msg);
  renderMyPanel(msg);
  _renderAtalhos();
  _renderGamepadHud(msg);
  _renderEfeitosAtivos(msg);
  renderGMLog(msg.gm_log);
  updateTurnBadge(msg);
  updateMoveButtons(msg);
  renderObjectivesHUD(msg);
  _start2DHighlightLoop();
  renderStory();   // Fase 4b: abertura da fase (sobre o tabuleiro; não bloqueia)
  if(typeof InventoryModal !== 'undefined') InventoryModal.refresh();
}

// ── Fase 3: HUD de objetivos + botão "Libertar" (só em masmorra autorada) ─────
// Lê GS.objectives / GS.prisioneiroLibertavel (decisores em gameState.js).
function _objIcon(status){
  return status === 'done' ? '✅' : status === 'failed' ? '❌' : '⬜';
}
function _objRow(o){
  let label = _rotulo(o && o.type, 'ui.objetivo', (o && o.type) || t('ui.hud.objetivo'));
  if(o && o.progresso) label += ` (${o.progresso.feitas}/${o.progresso.total} salas)`;
  return `<div class="obj-row"><span class="obj-ic">${_objIcon(o && o.status)}</span><span class="obj-lbl">${label}</span></div>`;
}
// Confirmação antes de encerrar a missão (itens largados podem ficar para trás).
// Usa um overlay próprio em vez de window.confirm(): o confirm nativo pode ser
// silenciosamente suprimido pelo navegador ("não permitir mais diálogos"),
// fazendo o botão parecer que "não funciona".
function encerrarMissaoConfirm(){
  if (document.getElementById('encerrar-missao-overlay')) return;   // já aberto
  const ov = document.createElement('div');
  ov.id = 'encerrar-missao-overlay';
  ov.style.cssText = 'position:fixed;inset:0;background:#000a;display:flex;'
    + 'align-items:center;justify-content:center;z-index:500;';
  ov.innerHTML =
    '<div style="background:rgba(28,20,6,0.98);border:1px solid var(--gold,#ffcc44);'
    + 'border-radius:12px;padding:22px 24px;max-width:340px;text-align:center;'
    + 'box-shadow:0 8px 30px #000b;">'
    + '<div style="color:var(--gold,#ffcc44);font-weight:700;font-size:1rem;margin-bottom:8px;">' + t('ui.missao.encerrar_titulo') + '</div>'
    + '<div style="color:#e8dcc0;font-size:.82rem;line-height:1.4;margin-bottom:16px;">'
    + t('ui.missao.encerrar_aviso') + '</div>'
    + '<div style="display:flex;gap:10px;">'
    + '<button id="em-cancel" data-gamepad-cancel style="flex:1;padding:8px;border-radius:8px;border:1px solid #6a5a3a;'
    + 'background:rgba(40,32,16,0.9);color:#cbbe9c;font-weight:700;font-size:.78rem;cursor:pointer;">' + t('ui.geral.cancelar') + '</button>'
    + '<button id="em-ok" style="flex:1;padding:8px;border-radius:8px;border:1px solid var(--gold,#ffcc44);'
    + 'background:rgba(60,45,12,0.96);color:var(--gold,#ffcc44);font-weight:700;font-size:.78rem;cursor:pointer;">'+t('ui.objetivo.encerrar_btn')+'</button>'
    + '</div></div>';
  const close = () => { if (ov.parentNode) ov.parentNode.removeChild(ov); };
  ov.addEventListener('click', e => { if (e.target === ov) close(); });
  document.body.appendChild(ov);
  document.getElementById('em-cancel').onclick = close;
  document.getElementById('em-ok').onclick = () => { close(); GS.encerrarMissao(); };
}
window.encerrarMissaoConfirm = encerrarMissaoConfirm;

// A confirmação de saída precisa ser HTML do jogo, não window.confirm():
// diálogos nativos não permitem foco/click pela Gamepad API.
function confirmarSaidaMasmorra(custo, espera){
  if(document.getElementById('exit-dungeon-overlay')) return;
  const ov = document.createElement('div');
  ov.id = 'exit-dungeon-overlay';
  ov.className = 'open';
  ov.style.cssText = 'position:fixed;inset:0;background:#000a;display:flex;'
    + 'align-items:center;justify-content:center;z-index:500;';
  const aviso = t('ui.tabuleiro.confirmar_saida', {f:custo.fome, s:custo.sede, n:espera});
  ov.innerHTML = '<div style="background:rgba(28,20,6,.98);border:1px solid var(--gold,#ffcc44);'
    + 'border-radius:12px;padding:22px 24px;max-width:340px;text-align:center;box-shadow:0 8px 30px #000b;">'
    + '<div style="color:var(--gold,#ffcc44);font-weight:700;font-size:1rem;margin-bottom:8px;">🪜 ' + t('ui.tabuleiro.escada_saida') + '</div>'
    + '<div style="color:#e8dcc0;font-size:.82rem;line-height:1.4;margin-bottom:16px;">' + aviso + '</div>'
    + '<div style="display:flex;gap:10px;">'
    + '<button data-gamepad-cancel style="flex:1;padding:8px;border-radius:8px;border:1px solid #6a5a3a;background:rgba(40,32,16,.9);color:#cbbe9c;font-weight:700;cursor:pointer;">' + t('ui.geral.cancelar') + '</button>'
    + '<button data-gamepad-exit style="flex:1;padding:8px;border-radius:8px;border:1px solid var(--gold,#ffcc44);background:rgba(60,45,12,.96);color:var(--gold,#ffcc44);font-weight:700;cursor:pointer;">' + t('ui.tabuleiro.clique_voltar_cidade') + '</button>'
    + '</div></div>';
  const close = () => { if(ov.parentNode) ov.parentNode.removeChild(ov); };
  ov.addEventListener('click', event => { if(event.target === ov) close(); });
  ov.querySelector('[data-gamepad-cancel]').onclick = close;
  ov.querySelector('[data-gamepad-exit]').onclick = () => {
    close();
    fecharQuadrosFlutuantes();
    send({type:'exit_dungeon'});
  };
  document.body.appendChild(ov);
  _gamepadFocusMapPoint('#exit-dungeon-overlay [data-gamepad-exit]', '#exit-dungeon-overlay [data-gamepad-cancel]');
}

function renderObjectivesHUD(msg){
  const hud = $('objectives-hud');
  const btn = $('btn-libertar');
  if(!hud) return;
  const obj = GS.objectives;   // null no procedural
  if(!obj){
    hud.style.display = 'none';
    if(btn) btn.style.display = 'none';
    return;
  }
  let html = '';
  const camp = GS.campaign;   // {name, phase, total} em campanha; null caso contrário
  if(camp){
    html += `<div class="obj-campaign">${t('ui.objetivo.fase_de', {atual: camp.phase, total: camp.total, nome: camp.name})}</div>`;
  }
  html += '<div class="obj-title">'+t('ui.objetivo.titulo')+'</div>';
  if(obj.primary) html += `<div class="obj-primary">${_objRow(obj.primary)}</div>`;
  const secs = obj.secondary || [];
  if(secs.length){
    html += `<div class="obj-sec-label">${t('ui.objetivo.secundarios')}</div>`;
    for(const s of secs) html += _objRow(s);
  }
  if (GS.missionCompletePending) {
    html += `<button class="btn-encerrar-missao" onclick="encerrarMissaoConfirm()">${t('ui.missao.encerrar_botao')}</button>`;
  }
  hud.innerHTML = html;
  hud.style.display = '';
  // Botão "Libertar": só quando há prisioneiro cativo adjacente no meu turno.
  if(btn) btn.style.display = GS.prisioneiroLibertavel ? '' : 'none';
}

function _start2DHighlightLoop(){
  if(_2dHighlightFrame || mode3D) return;
  function step(){
    const st = GS.gameState;
    const me = st && st.players.find(p => p.id === GS.myPid && p.alive);
    const hasAnimatedTerrain = !!(st && Object.values(st.materiais || {}).some(mid =>
      mid === 'lava' || mid === 'pantano' || mid === 'agua' || mid === 'agua_profunda'
      || mid === 'rodamoinho' || mid === 'rodamoinho_profundo'));
    const animateHighlights = GS.isMyTurn && me && me.moves_left > 0;
    const animateGamepadCursor = !!_gamepadCursorTile(st);
    if(!mode3D && st && (animateHighlights || hasAnimatedTerrain || animateGamepadCursor)){
      _movePulse = 0.5 + 0.5 * Math.sin(Date.now() / 420);
      renderMap(st);
      _2dHighlightFrame = _scheduleVisualFrame(step);
    } else {
      _movePulse = 0.5;
      _2dHighlightFrame = null;
    }
  }
  _2dHighlightFrame = _scheduleVisualFrame(step);
}

function updateTurnBadge(msg){
  $('round-badge').textContent = t('ui.hud.badge_rodada', {n: msg.round});
  if(msg.test_mode){
    $('turn-badge').textContent = t('ui.hud.badge_teste_livre');
    $('turn-badge').style.background = '#237a4b';
    $('turn-badge').style.color = '#fff';
    updateTurnTimer(msg);
    return;
  }
  // Turno dos servos (logo após o mago): destaca em roxo.
  if(msg.animados_turn){
    const owner = msg.players.find(p=>p.id===msg.animados_turn);
    $('turn-badge').textContent = owner ? t('ui.hud.servos_de', {nome: owner.name}) : t('ui.hud.servos');
    $('turn-badge').style.background = '#9900cc';
    $('turn-badge').style.color = '#fff';
    return;
  }
  const cur = msg.players.find(p=>p.id===msg.current_turn);
  // Deixa explícito de quem o grupo está esperando — antes só o nome aparecia
  // e novatos não sabiam se era a vez deles.
  if(cur && cur.id === GS.myPid){
    $('turn-badge').textContent = t('ui.hud.badge_sua_vez', {emoji: cur.emoji, nome: cur.name});
  } else {
    $('turn-badge').textContent = cur ? t('ui.hud.aguardando_heroi', {emoji: cur.emoji, nome: cur.name}) : '—';
  }
  $('turn-badge').style.background = cur ? cur.color : 'var(--gold)';
  $('turn-badge').style.color = '#fff';
  updateTurnTimer(msg);
}

// ── Timer de 30s por turno ──────────────────────────────────────────────────
// O servidor é autoridade (encerra o turno aos 30s). Aqui só exibimos a contagem
// regressiva. Detectamos um turno NOVO pela mudança de `turn_timer_started`
// (epoch do servidor) e contamos localmente — assim evitamos desvio de relógio
// e não reiniciamos a cada push de estado dentro do mesmo turno.
let _ttState = { key:null, remaining:0, interval:null };
function _ttClear(){ if(_ttState.interval){ clearInterval(_ttState.interval); _ttState.interval=null; } }
function _ttRender(){
  const b = document.getElementById('turn-timer-badge'); if(!b) return;
  const s = _ttState.remaining;
  b.textContent = `⏳ ${s}s`;
  b.style.background = s<=10 ? '#c0392b' : '#2a2a2a';
  b.style.color = '#fff';
}
function updateTurnTimer(msg){
  const b = document.getElementById('turn-timer-badge'); if(!b) return;
  const active = msg.turn_timer_enabled !== false && msg.phase === 'playing' && msg.current_turn && msg.turn_timer_started;
  if(!active){ _ttClear(); _ttState.key=null; b.style.display='none'; return; }
  const limit = msg.turn_timer_limit || 30;
  if(msg.turn_timer_started !== _ttState.key){   // turno novo → reinicia a contagem
    _ttState.key = msg.turn_timer_started;
    _ttState.remaining = limit;
    _ttClear();
    _ttState.interval = setInterval(()=>{
      _ttState.remaining = Math.max(0, _ttState.remaining - 1);
      _ttRender();
      if(_ttState.remaining <= 0) _ttClear();
    }, 1000);
  }
  b.style.display = '';
  _ttRender();
}

function updateMoveButtons(msg){
  // Arrow buttons removed — movement is click-to-move only
}

// BFS helpers live in GS (gameState.js) — alias for brevity in render code
const bfsReachable = (...a) => GS.bfsReachable(...a);
const findPath     = (...a) => GS.findPath(...a);

// Center the map wrap on the player — runs inside rAF so canvas resize never beats it
function centerOnPlayer(state){
  const me=state.players.find(p=>p.id===GS.myPid&&p.alive);
  if(!me) return;
  if(mode3D){
    // Após um passo pelo controle, a câmera volta a enquadrar o próprio peão.
    if(_gamepadInput.active && _gamepadInput.followPawn && !configCamera.seguindoPeao)
      centralizarCamera3DNoPeao(me.pos);
    return;
  }
  const wrap=$('map-wrap');
  const tl=Math.max(0, me.pos[0]*CELL+CELL/2 - wrap.clientWidth/2);
  const tt=Math.max(0, me.pos[1]*CELL+CELL/2 - wrap.clientHeight/2);
  requestAnimationFrame(()=>{ wrap.scrollLeft=tl; wrap.scrollTop=tt; });
}

// ══ SPRITE ENGINE ══════════════════════════════════════════════════════════

function _cl(hex, f) {
  const r=parseInt(hex.slice(1,3),16), g=parseInt(hex.slice(3,5),16), b=parseInt(hex.slice(5,7),16);
  return `rgb(${Math.min(255,r*f|0)},${Math.min(255,g*f|0)},${Math.min(255,b*f|0)})`;
}

function rr(ctx,x,y,w,h,r=3){
  ctx.beginPath(); ctx.moveTo(x+r,y); ctx.arcTo(x+w,y,x+w,y+h,r);
  ctx.arcTo(x+w,y+h,x,y+h,r); ctx.arcTo(x,y+h,x,y,r); ctx.arcTo(x,y,x+w,y,r); ctx.closePath();
}

function drawFace(ctx, hx, hy, skin){
  // Head oval
  ctx.fillStyle=skin;
  ctx.beginPath(); ctx.ellipse(hx,hy,7.5,8.5,0,0,Math.PI*2); ctx.fill();
  // Face shading gradient
  const fg=ctx.createLinearGradient(hx-6,hy-8,hx+5,hy+9);
  fg.addColorStop(0,'rgba(255,255,255,0.25)'); fg.addColorStop(0.5,'rgba(0,0,0,0)'); fg.addColorStop(1,'rgba(0,0,0,0.28)');
  ctx.fillStyle=fg; ctx.beginPath(); ctx.ellipse(hx,hy,7.5,8.5,0,0,Math.PI*2); ctx.fill();
  // Outline
  ctx.strokeStyle='rgba(0,0,0,0.30)'; ctx.lineWidth=0.7; ctx.stroke();
  // Eye whites
  ctx.fillStyle='#faf4ee'; ctx.fillRect(hx-4.2,hy-2.2,3.2,2.4); ctx.fillRect(hx+1,hy-2.2,3.2,2.4);
  // Pupils
  ctx.fillStyle='#181820';
  ctx.beginPath(); ctx.arc(hx-2.7,hy-0.9,1.2,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.arc(hx+2.5,hy-0.9,1.2,0,Math.PI*2); ctx.fill();
  // Specular highlight
  ctx.fillStyle='rgba(255,255,255,0.92)';
  ctx.beginPath(); ctx.arc(hx-3.2,hy-1.4,0.55,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.arc(hx+2.0,hy-1.4,0.55,0,Math.PI*2); ctx.fill();
  // Nose shadow
  ctx.fillStyle='rgba(0,0,0,0.13)'; ctx.beginPath(); ctx.arc(hx,hy+1.8,1.5,0,Math.PI*2); ctx.fill();
}

// ── Hero class sprites (drawn at origin = tile center) ─────────────────────

function drawWarrior(ctx, color){
  // ── Plate greaves (legs hidden by skirt of armor)
  ctx.fillStyle='#8898b2'; rr(ctx,-7,9,5,11,2); ctx.fill(); rr(ctx,2,9,5,11,2); ctx.fill();
  const lgG=ctx.createLinearGradient(-7,9,2,20); lgG.addColorStop(0,'rgba(255,255,255,0.22)'); lgG.addColorStop(1,'rgba(0,0,0,0)');
  ctx.fillStyle=lgG; ctx.fillRect(-6.5,10,2,9); ctx.fillRect(2.5,10,2,9);
  // Sabatons
  ctx.fillStyle='#5a6878'; ctx.fillRect(-8,18,7,3); ctx.fillRect(1,18,7,3);

  // ── Blue surcoat split halves (tabard — class colour)
  ctx.fillStyle=color;
  ctx.beginPath(); ctx.moveTo(-9,5); ctx.lineTo(-9,18); ctx.lineTo(-3,18); ctx.lineTo(-3,5); ctx.closePath(); ctx.fill();
  ctx.beginPath(); ctx.moveTo(3,5); ctx.lineTo(3,18); ctx.lineTo(9,18); ctx.lineTo(9,5); ctx.closePath(); ctx.fill();
  ctx.strokeStyle='#d4a820'; ctx.lineWidth=0.9;
  ctx.beginPath(); ctx.moveTo(-9,5); ctx.lineTo(-9,18); ctx.lineTo(-3,18); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(9,5); ctx.lineTo(9,18); ctx.lineTo(3,18); ctx.stroke();

  // ── Breastplate
  ctx.fillStyle='#96a8be'; rr(ctx,-10,-8,20,15,3); ctx.fill();
  const bpG=ctx.createLinearGradient(-10,-8,8,7); bpG.addColorStop(0,'rgba(255,255,255,0.30)'); bpG.addColorStop(0.5,'rgba(0,0,0,0)'); bpG.addColorStop(1,'rgba(0,0,0,0.20)');
  ctx.fillStyle=bpG; rr(ctx,-10,-8,20,15,3); ctx.fill();
  ctx.strokeStyle='#b8c8d8'; ctx.lineWidth=0.9; rr(ctx,-10,-8,20,15,3); ctx.stroke();
  // Surcoat centre strip
  ctx.fillStyle=color; rr(ctx,-4,-6,8,12,2); ctx.fill();
  ctx.strokeStyle='#d4a820'; ctx.lineWidth=0.8; rr(ctx,-4,-6,8,12,2); ctx.stroke();
  // Gold cross on surcoat
  ctx.strokeStyle='#f0c840'; ctx.lineWidth=1.6; ctx.lineCap='round';
  ctx.beginPath(); ctx.moveTo(0,-3); ctx.lineTo(0,4); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(-2.5,0); ctx.lineTo(2.5,0); ctx.stroke();
  ctx.lineCap='butt';
  // Gold belt
  ctx.fillStyle='#c89818'; ctx.fillRect(-10,5,20,2.5);
  ctx.fillStyle='#f0c840'; ctx.beginPath(); ctx.ellipse(0,6.2,3,2,0,0,Math.PI*2); ctx.fill();

  // ── Pauldrons
  ctx.fillStyle='#8898b2';
  ctx.beginPath(); ctx.ellipse(-11,-3,6,4,0.25,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(11,-3,6,4,-0.25,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='rgba(255,255,255,0.22)';
  ctx.beginPath(); ctx.ellipse(-11,-4.5,3.5,2,0.25,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(11,-4.5,3.5,2,-0.25,0,Math.PI*2); ctx.fill();

  // ── Right arm (gauntlet reaching toward hammer)
  ctx.fillStyle='#8090a8'; rr(ctx,9,-2,4,12,2); ctx.fill();
  ctx.fillStyle='rgba(255,255,255,0.14)'; ctx.fillRect(9.5,-1,1.5,9);

  // ── Left arm raised (upper, swinging hammer)
  ctx.fillStyle='#8090a8'; rr(ctx,-13,-14,4,12,2); ctx.fill();
  ctx.fillStyle='rgba(255,255,255,0.14)'; ctx.fillRect(-12.5,-13,1.5,9);

  // ── War hammer (angled — swinging pose)
  ctx.save(); ctx.translate(11,-2); ctx.rotate(-0.38);
  // Handle
  ctx.fillStyle='#7a5030'; ctx.fillRect(-1.5,-24,3,28);
  ctx.strokeStyle='#a07848'; ctx.lineWidth=0.5; ctx.strokeRect(-1.5,-24,3,28);
  // Handle bindings
  ctx.strokeStyle='#d4a820'; ctx.lineWidth=1.2;
  for(let i=0;i<3;i++){ ctx.beginPath(); ctx.moveTo(-1.5,-2+i*2.8); ctx.lineTo(1.5,-2+i*2.8); ctx.stroke(); }
  // Hammer head (large, flat face + spike)
  ctx.fillStyle='#7a8090'; ctx.fillRect(-7,-33,15,11);
  const hmG=ctx.createLinearGradient(-7,-33,7,-22); hmG.addColorStop(0,'rgba(255,255,255,0.32)'); hmG.addColorStop(1,'rgba(0,0,0,0.15)');
  ctx.fillStyle=hmG; ctx.fillRect(-7,-33,15,11);
  ctx.strokeStyle='#a0a8b8'; ctx.lineWidth=0.8; ctx.strokeRect(-7,-33,15,11);
  // Spike on top
  ctx.fillStyle='#9098a8';
  ctx.beginPath(); ctx.moveTo(-2,-33); ctx.lineTo(0,-39); ctx.lineTo(2,-33); ctx.closePath(); ctx.fill();
  // Rivets
  ctx.fillStyle='#c8ccd8'; for(let r=0;r<2;r++) for(let c=0;c<3;c++){ctx.beginPath(); ctx.arc(-5+c*4.5,-29+r*3,0.9,0,Math.PI*2); ctx.fill();}
  ctx.restore();

  // ── Closed helmet with gold visor
  ctx.fillStyle='#8898b2'; ctx.beginPath(); ctx.ellipse(0,-19,10,11,0,0,Math.PI*2); ctx.fill();
  const hlG=ctx.createLinearGradient(-10,-30,8,-8); hlG.addColorStop(0,'rgba(255,255,255,0.32)'); hlG.addColorStop(0.5,'rgba(0,0,0,0)'); hlG.addColorStop(1,'rgba(0,0,0,0.28)');
  ctx.fillStyle=hlG; ctx.beginPath(); ctx.ellipse(0,-19,10,11,0,0,Math.PI*2); ctx.fill();
  ctx.strokeStyle='#b0bac8'; ctx.lineWidth=0.8; ctx.stroke();
  // Gold visor frame
  ctx.fillStyle='#c89818'; ctx.fillRect(-8,-23,16,1.8); ctx.fillRect(-8,-14.5,16,1.8);
  // Visor grille bars
  ctx.strokeStyle='#d4a820'; ctx.lineWidth=0.9;
  for(let i=0;i<5;i++){ctx.beginPath(); ctx.moveTo(-7.5+i*3.5,-23); ctx.lineTo(-7.5+i*3.5,-14.5); ctx.stroke();}
  // Dark inside visor + warm eye glow
  ctx.fillStyle='rgba(0,0,0,0.42)'; ctx.fillRect(-7,-22.5,14,8);
  ctx.fillStyle='rgba(255,140,30,0.55)'; ctx.fillRect(-5,-20.5,4,2.5); ctx.fillRect(1,-20.5,4,2.5);
  // Helmet ridge on top
  ctx.fillStyle='#7888a0'; ctx.fillRect(-9,-30,18,4);
  ctx.fillStyle='rgba(255,255,255,0.18)'; ctx.fillRect(-8,-29.5,16,1.5);
  // Red plume
  ctx.strokeStyle='#c82020'; ctx.lineWidth=2.2; ctx.lineCap='round';
  ctx.beginPath(); ctx.moveTo(-1,-30); ctx.quadraticCurveTo(-4,-38,0,-41); ctx.stroke();
  ctx.strokeStyle='#e84040'; ctx.lineWidth=1;
  ctx.beginPath(); ctx.moveTo(2,-30); ctx.quadraticCurveTo(5,-36,2,-40); ctx.stroke();
  ctx.lineCap='butt';

  // ── Dwarf beard (brown, thick — visible below visor)
  ctx.fillStyle='#7a3e10';
  ctx.beginPath(); ctx.moveTo(-8,-12); ctx.lineTo(-11,0); ctx.lineTo(-9,8); ctx.lineTo(-5,11); ctx.lineTo(5,11); ctx.lineTo(9,8); ctx.lineTo(11,0); ctx.lineTo(8,-12); ctx.closePath(); ctx.fill();
  // Mid-tone
  ctx.fillStyle='#b06020';
  ctx.beginPath(); ctx.moveTo(-5,-12); ctx.lineTo(-7,-2); ctx.lineTo(-5,7); ctx.lineTo(5,7); ctx.lineTo(7,-2); ctx.lineTo(5,-12); ctx.closePath(); ctx.fill();
  // Highlight streak
  ctx.fillStyle='rgba(210,140,60,0.35)';
  ctx.beginPath(); ctx.moveTo(-2,-12); ctx.lineTo(-3,1); ctx.lineTo(3,1); ctx.lineTo(2,-12); ctx.closePath(); ctx.fill();
}

function drawMage(ctx, color){
  // ── Long flowing robe (gray-blue, like photo wizard)
  const robeBase='#8890a0';
  ctx.fillStyle=robeBase;
  ctx.beginPath(); ctx.moveTo(-10,-8); ctx.lineTo(-14,20); ctx.lineTo(14,20); ctx.lineTo(10,-8); ctx.closePath(); ctx.fill();
  // Robe shading
  const robeG=ctx.createLinearGradient(-12,-8,10,20); robeG.addColorStop(0,'rgba(255,255,255,0.18)'); robeG.addColorStop(0.5,'rgba(0,0,0,0)'); robeG.addColorStop(1,'rgba(0,0,0,0.25)');
  ctx.fillStyle=robeG; ctx.beginPath(); ctx.moveTo(-10,-8); ctx.lineTo(-14,20); ctx.lineTo(14,20); ctx.lineTo(10,-8); ctx.closePath(); ctx.fill();
  // Colour trim stripe down robe front
  ctx.fillStyle=color; rr(ctx,-3,-6,6,26,2); ctx.fill();
  ctx.strokeStyle=_cl(color,1.4); ctx.lineWidth=0.7; rr(ctx,-3,-6,6,26,2); ctx.stroke();
  // Orange sash / belt
  ctx.fillStyle='#c06010'; ctx.fillRect(-10,-1,20,3);
  ctx.strokeStyle='#e08020'; ctx.lineWidth=0.6; ctx.strokeRect(-10,-1,20,3);

  // ── Torso (robe body)
  ctx.fillStyle=robeBase; rr(ctx,-9,-8,18,14,3); ctx.fill();
  ctx.fillStyle=robeG; rr(ctx,-9,-8,18,14,3); ctx.fill();
  ctx.strokeStyle='rgba(255,255,255,0.14)'; ctx.lineWidth=1; rr(ctx,-9,-8,18,14,3); ctx.stroke();

  // ── Arms in sleeves
  ctx.fillStyle=robeBase; rr(ctx,-13,-7,4,10,2); ctx.fill(); rr(ctx,9,-7,4,10,2); ctx.fill();

  // ── Staff — held in left hand (orange flame, like photo)
  ctx.strokeStyle='#7a5020'; ctx.lineWidth=3; ctx.lineCap='round';
  ctx.beginPath(); ctx.moveTo(-13,-26); ctx.lineTo(-14,14); ctx.stroke();
  ctx.lineCap='butt';
  // Staff rings
  ctx.strokeStyle='#c89020'; ctx.lineWidth=1.4;
  for(let r=0;r<3;r++){ctx.beginPath(); ctx.moveTo(-15,-8+r*4); ctx.lineTo(-11,-8+r*4); ctx.stroke();}
  // Staff head (glowing orb + flame like photo)
  const staffOrbG=ctx.createRadialGradient(-13,-32,1,-13,-32,9);
  staffOrbG.addColorStop(0,'#fff8e0'); staffOrbG.addColorStop(0.3,'#ffb030'); staffOrbG.addColorStop(0.7,'#e06010'); staffOrbG.addColorStop(1,'rgba(200,80,0,0)');
  ctx.fillStyle=staffOrbG; ctx.beginPath(); ctx.arc(-13,-32,9,0,Math.PI*2); ctx.fill();
  // Flame spikes
  ctx.fillStyle='#ffca40';
  ctx.beginPath(); ctx.moveTo(-14,-36); ctx.quadraticCurveTo(-16,-44,-13,-42); ctx.quadraticCurveTo(-10,-44,-12,-36); ctx.closePath(); ctx.fill();
  ctx.fillStyle='#ff8820';
  ctx.beginPath(); ctx.moveTo(-14,-36); ctx.quadraticCurveTo(-15,-41,-13,-40); ctx.quadraticCurveTo(-11,-41,-12,-36); ctx.closePath(); ctx.fill();

  // ── Tall pointed wizard hat (like photo — gray with brim)
  const hatCol='#545a6a';
  // Brim
  ctx.fillStyle=hatCol; rr(ctx,-13,-22,26,4,2); ctx.fill();
  ctx.fillStyle='rgba(255,255,255,0.15)'; rr(ctx,-13,-22,26,2,2); ctx.fill();
  ctx.strokeStyle=_cl(hatCol,0.7); ctx.lineWidth=0.7; rr(ctx,-13,-22,26,4,2); ctx.stroke();
  // Hat cone
  ctx.fillStyle=hatCol;
  ctx.beginPath(); ctx.moveTo(0,-43); ctx.lineTo(-11,-22); ctx.lineTo(11,-22); ctx.closePath(); ctx.fill();
  const hatG=ctx.createLinearGradient(-11,-43,9,-22); hatG.addColorStop(0,'rgba(255,255,255,0.22)'); hatG.addColorStop(1,'rgba(0,0,0,0.30)');
  ctx.fillStyle=hatG; ctx.beginPath(); ctx.moveTo(0,-43); ctx.lineTo(-11,-22); ctx.lineTo(11,-22); ctx.closePath(); ctx.fill();
  ctx.strokeStyle=_cl(hatCol,0.75); ctx.lineWidth=0.8; ctx.stroke();
  // Star/rune symbol on hat
  ctx.fillStyle='#f0e060'; ctx.font='bold 7px serif'; ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillText('✦',0,-32);
  // Hat band (colour accent)
  ctx.strokeStyle=color; ctx.lineWidth=1.8;
  ctx.beginPath(); ctx.moveTo(-9,-23.5); ctx.lineTo(9,-23.5); ctx.stroke();

  // ── Face (visible below hat brim)
  drawFace(ctx,0,-15,'#d4c8b8');
  // White beard (like photo wizard)
  ctx.fillStyle='#e0dcd0';
  ctx.beginPath(); ctx.moveTo(-7,-8); ctx.lineTo(-9,2); ctx.lineTo(-7,12); ctx.lineTo(-4,14); ctx.lineTo(4,14); ctx.lineTo(7,12); ctx.lineTo(9,2); ctx.lineTo(7,-8); ctx.closePath(); ctx.fill();
  ctx.fillStyle='rgba(255,255,255,0.4)';
  ctx.beginPath(); ctx.moveTo(-3,-8); ctx.lineTo(-4,3); ctx.lineTo(0,11); ctx.lineTo(4,3); ctx.lineTo(3,-8); ctx.closePath(); ctx.fill();
}

function drawRogue(ctx, color){
  // ── Long red cape (signature! — like photo rogue — drawn first, behind body)
  const capeRed='#9e1510'; // dark red base
  ctx.fillStyle=capeRed;
  ctx.beginPath(); ctx.moveTo(-9,-7); ctx.lineTo(-15,8); ctx.lineTo(-13,22); ctx.lineTo(-7,22); ctx.lineTo(-3,12); ctx.lineTo(3,12); ctx.lineTo(7,22); ctx.lineTo(13,22); ctx.lineTo(15,8); ctx.lineTo(9,-7); ctx.closePath(); ctx.fill();
  // Cape shading (left darker, right lighter — light from right)
  const capeG=ctx.createLinearGradient(-15,0,15,20); capeG.addColorStop(0,'rgba(0,0,0,0.30)'); capeG.addColorStop(0.5,'rgba(0,0,0,0)'); capeG.addColorStop(1,'rgba(255,255,255,0.12)');
  ctx.fillStyle=capeG; ctx.beginPath(); ctx.moveTo(-9,-7); ctx.lineTo(-15,8); ctx.lineTo(-13,22); ctx.lineTo(-7,22); ctx.lineTo(-3,12); ctx.lineTo(3,12); ctx.lineTo(7,22); ctx.lineTo(13,22); ctx.lineTo(15,8); ctx.lineTo(9,-7); ctx.closePath(); ctx.fill();
  // Cape highlight fold lines
  ctx.strokeStyle='rgba(220,60,40,0.45)'; ctx.lineWidth=1;
  ctx.beginPath(); ctx.moveTo(-12,2); ctx.quadraticCurveTo(-11,14,-9,21); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(12,2); ctx.quadraticCurveTo(11,14,9,21); ctx.stroke();
  ctx.strokeStyle='rgba(0,0,0,0.25)'; ctx.lineWidth=0.8;
  ctx.beginPath(); ctx.moveTo(-3,12); ctx.lineTo(0,22); ctx.lineTo(3,12); ctx.stroke(); // center split line

  // ── Dark leather legs
  ctx.fillStyle='#281e18'; rr(ctx,-7,7,5,13,2); ctx.fill(); rr(ctx,2,7,5,13,2); ctx.fill();
  ctx.fillStyle='rgba(255,255,255,0.10)'; ctx.fillRect(-6.5,8,2,11); ctx.fillRect(2.5,8,2,11);
  // Boots
  ctx.fillStyle='#1a1210'; ctx.fillRect(-8,18,7,3); ctx.fillRect(1,18,7,3);

  // ── Leather torso (brown, like photo)
  ctx.fillStyle='#5a3a20'; rr(ctx,-9,-8,18,16,3); ctx.fill();
  const tG=ctx.createLinearGradient(-9,-8,7,8); tG.addColorStop(0,'rgba(255,255,255,0.18)'); tG.addColorStop(1,'rgba(0,0,0,0.22)');
  ctx.fillStyle=tG; rr(ctx,-9,-8,18,16,3); ctx.fill();
  ctx.strokeStyle='#7a5030'; ctx.lineWidth=0.8; rr(ctx,-9,-8,18,16,3); ctx.stroke();
  // Buckle / centre strap
  ctx.fillStyle='#c89820'; ctx.fillRect(-2,-8,4,14);
  ctx.strokeStyle='#e0b030'; ctx.lineWidth=0.7; ctx.strokeRect(-2,-8,4,14);
  // Gold buckle
  ctx.fillStyle='#d4a020'; ctx.fillRect(-3,3,6,3.5); ctx.strokeStyle='#f0c030'; ctx.lineWidth=0.7; ctx.strokeRect(-3,3,6,3.5);

  // ── Belt with pouches (leather, dark brown)
  ctx.fillStyle='#3a2010'; ctx.fillRect(-10,3,20,2.8);
  ctx.fillStyle='#5a3820'; ctx.fillRect(-9,3,5,5); ctx.fillRect(5,3,5,5); // pouches
  ctx.strokeStyle='#8a5828'; ctx.lineWidth=0.6; ctx.strokeRect(-9,3,5,5); ctx.strokeRect(5,3,5,5);

  // ── Arm (left — holding dagger)
  ctx.fillStyle='#5a3a20'; rr(ctx,-13,-7,4,10,2); ctx.fill();
  // ── Arm (right — holding dagger up)
  ctx.fillStyle='#5a3a20'; rr(ctx,9,-9,4,10,2); ctx.fill();

  // ── Left dagger (held forward)
  ctx.save(); ctx.translate(-14,0); ctx.rotate(0.45);
  ctx.fillStyle='#b8bec8'; ctx.beginPath(); ctx.moveTo(0,-12); ctx.lineTo(-2.5,2); ctx.lineTo(2.5,2); ctx.closePath(); ctx.fill();
  ctx.strokeStyle='rgba(255,255,255,0.30)'; ctx.lineWidth=0.8;
  ctx.beginPath(); ctx.moveTo(0,-10); ctx.lineTo(0,1); ctx.stroke();
  ctx.fillStyle='#7a7880'; ctx.fillRect(-4,1,8,2); // guard
  ctx.fillStyle='#4a2810'; ctx.fillRect(-1.5,3,3,6); // grip
  ctx.restore();
  // ── Right dagger (raised)
  ctx.save(); ctx.translate(12,-8); ctx.rotate(-0.55);
  ctx.fillStyle='#b8bec8'; ctx.beginPath(); ctx.moveTo(0,-12); ctx.lineTo(-2.5,2); ctx.lineTo(2.5,2); ctx.closePath(); ctx.fill();
  ctx.strokeStyle='rgba(255,255,255,0.30)'; ctx.lineWidth=0.8;
  ctx.beginPath(); ctx.moveTo(0,-10); ctx.lineTo(0,1); ctx.stroke();
  ctx.fillStyle='#7a7880'; ctx.fillRect(-4,1,8,2);
  ctx.fillStyle='#4a2810'; ctx.fillRect(-1.5,3,3,6);
  ctx.restore();

  // ── Dark hood (like photo assassin)
  ctx.fillStyle='#1e1820'; ctx.beginPath(); ctx.ellipse(0,-20,10,10,0,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='#2e2430'; ctx.beginPath(); ctx.ellipse(0,-20,8,7,0,Math.PI,0); ctx.fill();
  // Hood shadow under brow
  ctx.fillStyle='rgba(0,0,0,0.50)'; ctx.beginPath(); ctx.ellipse(0,-21.5,7,4,0,0,Math.PI); ctx.fill();
  // Colour accent on hood rim (class colour)
  ctx.strokeStyle=color; ctx.lineWidth=1.2;
  ctx.beginPath(); ctx.ellipse(0,-20,10,10,0,Math.PI*1.1,Math.PI*1.9); ctx.stroke();
  // Face visible (just eyes under hood shadow)
  drawFace(ctx,0,-21,'#c8a870');
}

function drawCleric(ctx, color){
  // ── White flowing robes (behind body)
  ctx.fillStyle='#ece8d8';
  ctx.beginPath(); ctx.moveTo(-8,-6); ctx.lineTo(-14,4); ctx.lineTo(-14,22); ctx.lineTo(-5,22); ctx.lineTo(-3,11); ctx.lineTo(0,22); ctx.lineTo(8,22); ctx.lineTo(10,4); ctx.lineTo(8,-6); ctx.closePath(); ctx.fill();
  const robeG=ctx.createLinearGradient(-14,0,10,20);
  robeG.addColorStop(0,'rgba(0,0,0,0.20)'); robeG.addColorStop(0.4,'rgba(0,0,0,0)'); robeG.addColorStop(1,'rgba(255,255,255,0.14)');
  ctx.fillStyle=robeG; ctx.beginPath(); ctx.moveTo(-8,-6); ctx.lineTo(-14,4); ctx.lineTo(-14,22); ctx.lineTo(-5,22); ctx.lineTo(-3,11); ctx.lineTo(0,22); ctx.lineTo(8,22); ctx.lineTo(10,4); ctx.lineTo(8,-6); ctx.closePath(); ctx.fill();
  ctx.strokeStyle='rgba(155,142,118,0.38)'; ctx.lineWidth=0.8;
  ctx.beginPath(); ctx.moveTo(-11,2); ctx.quadraticCurveTo(-10,12,-9,21); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(-3,11); ctx.lineTo(-2,22); ctx.stroke();
  ctx.strokeStyle='rgba(200,160,20,0.5)'; ctx.lineWidth=1;
  ctx.beginPath(); ctx.moveTo(-14,22); ctx.lineTo(10,22); ctx.stroke();

  // ── Chain mail legs
  ctx.fillStyle='#909898'; rr(ctx,-8,6,5,13,2); ctx.fill(); rr(ctx,3,6,5,13,2); ctx.fill();
  const legG=ctx.createLinearGradient(-8,6,-3,19);
  legG.addColorStop(0,'rgba(255,255,255,0.22)'); legG.addColorStop(1,'rgba(0,0,0,0.18)');
  ctx.fillStyle=legG; ctx.fillRect(-7.5,7,2,11); ctx.fillRect(3.5,7,2,11);
  ctx.strokeStyle='rgba(60,72,72,0.38)'; ctx.lineWidth=0.55;
  for(let y=8;y<19;y+=2.2){ ctx.beginPath(); ctx.moveTo(-8,y); ctx.lineTo(-3,y); ctx.stroke(); ctx.beginPath(); ctx.moveTo(3,y); ctx.lineTo(8,y); ctx.stroke(); }
  ctx.fillStyle='#4a3018'; ctx.fillRect(-9,17,7,5); ctx.fillRect(2,17,7,5);
  ctx.fillStyle='rgba(255,255,255,0.14)'; ctx.fillRect(-8.5,17,5,1.5); ctx.fillRect(2.5,17,5,1.5);

  // ── White surcoat with gold border and holy cross
  ctx.fillStyle='#f2eedf';
  ctx.beginPath(); ctx.moveTo(-6,-8); ctx.lineTo(-7,19); ctx.lineTo(7,19); ctx.lineTo(6,-8); ctx.closePath(); ctx.fill();
  const surG=ctx.createLinearGradient(-6,-8,6,16);
  surG.addColorStop(0,'rgba(255,255,255,0.35)'); surG.addColorStop(1,'rgba(0,0,0,0.12)');
  ctx.fillStyle=surG; ctx.beginPath(); ctx.moveTo(-6,-8); ctx.lineTo(-7,19); ctx.lineTo(7,19); ctx.lineTo(6,-8); ctx.closePath(); ctx.fill();
  ctx.strokeStyle='#c8a020'; ctx.lineWidth=1.4;
  ctx.beginPath(); ctx.moveTo(-6,-8); ctx.lineTo(-7,19); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(6,-8); ctx.lineTo(7,19); ctx.stroke();
  ctx.strokeStyle=color; ctx.lineWidth=2.4; ctx.lineCap='round';
  ctx.beginPath(); ctx.moveTo(0,-4); ctx.lineTo(0,12); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(-5,1); ctx.lineTo(5,1); ctx.stroke();
  ctx.lineCap='butt';

  // ── Chain mail breastplate
  ctx.fillStyle='#a8b0b8'; rr(ctx,-10,-8,20,16,3); ctx.fill();
  ctx.strokeStyle='rgba(60,75,82,0.36)'; ctx.lineWidth=0.55;
  for(let y=-7;y<8;y+=2.4){ ctx.beginPath(); ctx.moveTo(-9,y); ctx.lineTo(9,y); ctx.stroke(); }
  const bpG=ctx.createLinearGradient(-10,-8,8,8);
  bpG.addColorStop(0,'rgba(255,255,255,0.26)'); bpG.addColorStop(0.4,'rgba(0,0,0,0)'); bpG.addColorStop(1,'rgba(0,0,0,0.20)');
  ctx.fillStyle=bpG; rr(ctx,-10,-8,20,16,3); ctx.fill();
  ctx.strokeStyle='#d4a020'; ctx.lineWidth=1.6; rr(ctx,-10,-8,20,16,3); ctx.stroke();

  // ── Pauldrons
  ctx.fillStyle='#9aa0a8';
  ctx.beginPath(); ctx.ellipse(-12,-5,6,4,0.3,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(12,-5,6,4,-0.3,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='rgba(255,255,255,0.22)';
  ctx.beginPath(); ctx.ellipse(-13,-7,4,2,0.3,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(11,-7,4,2,-0.3,0,Math.PI*2); ctx.fill();
  ctx.strokeStyle='#c8a020'; ctx.lineWidth=1;
  ctx.beginPath(); ctx.ellipse(-12,-5,6,4,0.3,0,Math.PI*2); ctx.stroke();
  ctx.beginPath(); ctx.ellipse(12,-5,6,4,-0.3,0,Math.PI*2); ctx.stroke();

  // ── Left arm (chain) + flanged mace
  ctx.fillStyle='#909898'; rr(ctx,-15,-7,5,11,2); ctx.fill();
  ctx.strokeStyle='#5a3a18'; ctx.lineWidth=2.5; ctx.lineCap='round';
  ctx.beginPath(); ctx.moveTo(-20,-4); ctx.lineTo(-19,9); ctx.stroke();
  ctx.strokeStyle='#7a5028'; ctx.lineWidth=1;
  for(let i=0;i<3;i++){ ctx.beginPath(); ctx.moveTo(-20.5,-1+i*3.5); ctx.lineTo(-17.5,-2+i*3.5); ctx.stroke(); }
  const mhG=ctx.createRadialGradient(-19,-9,1,-19,-9,7);
  mhG.addColorStop(0,'#d8c0a0'); mhG.addColorStop(0.55,'#9a7040'); mhG.addColorStop(1,'#503010');
  ctx.fillStyle=mhG; ctx.beginPath(); ctx.arc(-19,-9,5.5,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='#b08048';
  for(let a=0;a<6;a++){
    ctx.save(); ctx.translate(-19,-9); ctx.rotate(a*Math.PI/3+0.25);
    ctx.beginPath(); ctx.moveTo(0,-5); ctx.lineTo(-2,-8.5); ctx.lineTo(2,-8.5); ctx.closePath(); ctx.fill();
    ctx.restore();
  }
  ctx.lineCap='butt';

  // ── Right arm (chain) + round holy shield
  ctx.fillStyle='#909898'; rr(ctx,10,-7,5,11,2); ctx.fill();
  ctx.save(); ctx.translate(21,1);
  const shG=ctx.createRadialGradient(0,0,1,0,0,9);
  shG.addColorStop(0,'#c8a868'); shG.addColorStop(0.65,'#9a7840'); shG.addColorStop(1,'#6a4820');
  ctx.fillStyle=shG; ctx.beginPath(); ctx.arc(0,0,9,0,Math.PI*2); ctx.fill();
  ctx.strokeStyle='rgba(80,48,8,0.3)'; ctx.lineWidth=0.7;
  for(let i=-8;i<=8;i+=3.5){ const h=Math.sqrt(Math.max(0,81-i*i)); ctx.beginPath(); ctx.moveTo(i,-h); ctx.lineTo(i,h); ctx.stroke(); }
  ctx.strokeStyle='#7a8898'; ctx.lineWidth=2.2; ctx.beginPath(); ctx.arc(0,0,8,0,Math.PI*2); ctx.stroke();
  ctx.strokeStyle='#5a6878'; ctx.lineWidth=2;
  ctx.beginPath(); ctx.moveTo(0,-6); ctx.lineTo(0,6); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(-6,0); ctx.lineTo(6,0); ctx.stroke();
  ctx.fillStyle='#808898'; ctx.beginPath(); ctx.arc(0,0,2.5,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='rgba(255,255,255,0.4)'; ctx.beginPath(); ctx.arc(-0.5,-0.5,1,0,Math.PI*2); ctx.fill();
  ctx.restore();

  // ── Divine halo (drawn behind helm)
  const haloG=ctx.createRadialGradient(0,-24,9,0,-24,17);
  haloG.addColorStop(0,'rgba(255,210,50,0.18)'); haloG.addColorStop(1,'rgba(255,200,0,0)');
  ctx.fillStyle=haloG; ctx.beginPath(); ctx.arc(0,-24,17,0,Math.PI*2); ctx.fill();
  ctx.strokeStyle='rgba(255,215,50,0.65)'; ctx.lineWidth=2.5;
  ctx.beginPath(); ctx.arc(0,-24,12,0,Math.PI*2); ctx.stroke();

  // ── White/silver closed helm
  ctx.fillStyle='#d8d4c8'; ctx.beginPath(); ctx.ellipse(0,-23,10,11,0,Math.PI,0); ctx.fill();
  ctx.fillStyle='#e8e4d8'; rr(ctx,-10,-27,20,7,2); ctx.fill();
  const helmHG=ctx.createLinearGradient(-10,-30,8,-20);
  helmHG.addColorStop(0,'rgba(255,255,255,0.42)'); helmHG.addColorStop(0.5,'rgba(0,0,0,0)'); helmHG.addColorStop(1,'rgba(0,0,0,0.18)');
  ctx.fillStyle=helmHG; ctx.beginPath(); ctx.ellipse(0,-23,10,11,0,Math.PI,0); ctx.fill(); rr(ctx,-10,-27,20,7,2); ctx.fill();
  ctx.strokeStyle='#d4a020'; ctx.lineWidth=1.6; ctx.lineCap='round';
  ctx.beginPath(); ctx.moveTo(0,-32); ctx.lineTo(0,-25); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(-3.5,-29); ctx.lineTo(3.5,-29); ctx.stroke();
  ctx.lineCap='butt';
  ctx.fillStyle='rgba(15,12,8,0.78)'; ctx.beginPath(); ctx.ellipse(0,-23,7.5,3,0,0,Math.PI); ctx.fill();
  ctx.fillStyle='rgba(255,218,50,0.75)'; ctx.beginPath(); ctx.arc(-2.5,-23,1.3,0,Math.PI*2); ctx.fill(); ctx.beginPath(); ctx.arc(2.5,-23,1.3,0,Math.PI*2); ctx.fill();
  ctx.strokeStyle='#c8a020'; ctx.lineWidth=1.4;
  ctx.beginPath(); ctx.moveTo(-10,-20); ctx.lineTo(10,-20); ctx.stroke();
}

function drawPaladin(ctx, color){
  // ── Green flowing cape (drawn first — behind body, like photo)
  const capeGreen = color; // class colour = green for paladin
  ctx.fillStyle=capeGreen;
  ctx.beginPath(); ctx.moveTo(-9,-6); ctx.lineTo(-16,4); ctx.lineTo(-14,22); ctx.lineTo(-7,22); ctx.lineTo(-5,10); ctx.lineTo(-2,22); ctx.lineTo(6,22); ctx.lineTo(8,6); ctx.lineTo(9,-6); ctx.closePath(); ctx.fill();
  const cpG=ctx.createLinearGradient(-16,0,8,20); cpG.addColorStop(0,'rgba(0,0,0,0.28)'); cpG.addColorStop(0.5,'rgba(0,0,0,0)'); cpG.addColorStop(1,'rgba(255,255,255,0.15)');
  ctx.fillStyle=cpG; ctx.beginPath(); ctx.moveTo(-9,-6); ctx.lineTo(-16,4); ctx.lineTo(-14,22); ctx.lineTo(-7,22); ctx.lineTo(-5,10); ctx.lineTo(-2,22); ctx.lineTo(6,22); ctx.lineTo(8,6); ctx.lineTo(9,-6); ctx.closePath(); ctx.fill();
  // Cape folds
  ctx.strokeStyle=_cl(capeGreen,0.7); ctx.lineWidth=0.9;
  ctx.beginPath(); ctx.moveTo(-13,2); ctx.quadraticCurveTo(-12,14,-10,21); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(-5,10); ctx.lineTo(-3,22); ctx.stroke();
  // Cape collar
  ctx.fillStyle=_cl(capeGreen,1.3); ctx.beginPath(); ctx.ellipse(0,-9,8,3,0,Math.PI,0); ctx.fill();

  // ── Full plate leg armour
  ctx.fillStyle='#8090a8'; rr(ctx,-8,6,5,13,2); ctx.fill(); rr(ctx,3,6,5,13,2); ctx.fill();
  const lgG=ctx.createLinearGradient(-8,6,2,19); lgG.addColorStop(0,'rgba(255,255,255,0.25)'); lgG.addColorStop(1,'rgba(0,0,0,0.15)');
  ctx.fillStyle=lgG; ctx.fillRect(-7.5,7,2,11); ctx.fillRect(3.5,7,2,11);
  // Plate foot
  ctx.fillStyle='#6a7888'; ctx.fillRect(-9,17,7,4); ctx.fillRect(2,17,7,4);
  ctx.fillStyle='rgba(255,255,255,0.15)'; ctx.fillRect(-8.5,17,5,1.5); ctx.fillRect(2.5,17,5,1.5);

  // ── Breastplate (full plate — silver/blue)
  ctx.fillStyle='#8898b8'; rr(ctx,-10,-8,20,16,3); ctx.fill();
  const bpG=ctx.createLinearGradient(-10,-8,8,8); bpG.addColorStop(0,'rgba(255,255,255,0.35)'); bpG.addColorStop(0.45,'rgba(0,0,0,0)'); bpG.addColorStop(1,'rgba(0,0,0,0.22)');
  ctx.fillStyle=bpG; rr(ctx,-10,-8,20,16,3); ctx.fill();
  ctx.strokeStyle='#c8d0d8'; ctx.lineWidth=1; rr(ctx,-10,-8,20,16,3); ctx.stroke();
  // Gold trim on breastplate
  ctx.strokeStyle='#c8a020'; ctx.lineWidth=1.4; rr(ctx,-10,-8,20,16,3); ctx.stroke();
  // Fleur cross on chest
  ctx.strokeStyle='#d4b030'; ctx.lineWidth=1.6; ctx.lineCap='round';
  ctx.beginPath(); ctx.moveTo(2,-5); ctx.lineTo(2,5); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(-2,0); ctx.lineTo(6,0); ctx.stroke();
  ctx.lineCap='butt';
  // Gold belt
  ctx.fillStyle='#c8a020'; ctx.fillRect(-10,7,20,2.5);
  ctx.fillStyle='#f0c830'; ctx.beginPath(); ctx.ellipse(2,8.2,3,2,0,0,Math.PI*2); ctx.fill();

  // ── Pauldrons
  ctx.fillStyle='#8090a8';
  ctx.beginPath(); ctx.ellipse(-11,-3,6,4.5,0.2,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(11,-3,6,4.5,-0.2,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='rgba(255,255,255,0.22)';
  ctx.beginPath(); ctx.ellipse(-11,-4.5,3.5,2.2,0.2,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(11,-4.5,3.5,2.2,-0.2,0,Math.PI*2); ctx.fill();
  ctx.strokeStyle='#c8a020'; ctx.lineWidth=0.8;
  ctx.beginPath(); ctx.ellipse(-11,-3,6,4.5,0.2,0,Math.PI*2); ctx.stroke();
  ctx.beginPath(); ctx.ellipse(11,-3,6,4.5,-0.2,0,Math.PI*2); ctx.stroke();

  // ── SHIELD (left arm — wood+iron like photo: round, wood grain, iron rim+cross)
  ctx.save(); ctx.translate(-17,0);
  // Shield body (oval)
  ctx.fillStyle='#7a4820'; ctx.beginPath(); ctx.ellipse(0,0,8,11,0.15,0,Math.PI*2); ctx.fill();
  // Wood grain streaks
  ctx.strokeStyle='rgba(0,0,0,0.30)'; ctx.lineWidth=0.8;
  for(let i=-2;i<=2;i++){ctx.beginPath(); ctx.moveTo(i*2.5,-10); ctx.lineTo(i*2.5+1,10); ctx.stroke();}
  // Iron rim
  ctx.strokeStyle='#7a8898'; ctx.lineWidth=2.5; ctx.beginPath(); ctx.ellipse(0,0,8,11,0.15,0,Math.PI*2); ctx.stroke();
  ctx.strokeStyle='rgba(255,255,255,0.22)'; ctx.lineWidth=1;
  ctx.beginPath(); ctx.ellipse(-1,-1,6,8,0.15,Math.PI*1.2,Math.PI*1.8); ctx.stroke();
  // Iron cross on shield
  ctx.strokeStyle='#8898a8'; ctx.lineWidth=2; ctx.lineCap='round';
  ctx.beginPath(); ctx.moveTo(0,-7); ctx.lineTo(0,7); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(-6,0); ctx.lineTo(6,0); ctx.stroke();
  ctx.lineCap='butt';
  // Centre boss
  ctx.fillStyle='#a0a8b8'; ctx.beginPath(); ctx.arc(0,0,2.5,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='rgba(255,255,255,0.45)'; ctx.beginPath(); ctx.arc(-0.5,-0.5,1,0,Math.PI*2); ctx.fill();
  ctx.restore();

  // ── Right arm + sword
  ctx.fillStyle='#8090a8'; rr(ctx,9,-8,4,12,2); ctx.fill();
  ctx.fillStyle='rgba(255,255,255,0.18)'; ctx.fillRect(9.5,-7,1.5,10);
  // Sword blade (raised)
  ctx.strokeStyle='#c8d0e0'; ctx.lineWidth=2.8;
  ctx.beginPath(); ctx.moveTo(14,-24); ctx.lineTo(14,4); ctx.stroke();
  // Blade groove
  ctx.strokeStyle='rgba(255,255,255,0.40)'; ctx.lineWidth=0.9;
  ctx.beginPath(); ctx.moveTo(14,-22); ctx.lineTo(14,2); ctx.stroke();
  // Crossguard
  ctx.fillStyle='#c8a020'; ctx.fillRect(10,-5,8,2.5);
  ctx.fillStyle='rgba(255,255,255,0.30)'; ctx.fillRect(10,-4.5,8,1);
  // Grip
  ctx.fillStyle='#6a3a10'; ctx.fillRect(12.5,3,3.5,7);
  ctx.strokeStyle='#c8a020'; ctx.lineWidth=0.9;
  for(let i=0;i<3;i++){ctx.beginPath(); ctx.moveTo(12.5,5+i*2.2); ctx.lineTo(16,5+i*2.2); ctx.stroke();}
  // Pommel
  ctx.fillStyle='#c8a020'; ctx.beginPath(); ctx.ellipse(14,12,3.5,2.5,0,0,Math.PI*2); ctx.fill();

  // ── Winged helmet (like photo paladin — gold wings on sides)
  ctx.fillStyle='#8090a8'; ctx.beginPath(); ctx.ellipse(0,-19,10,11,0,0,Math.PI*2); ctx.fill();
  const helG=ctx.createLinearGradient(-10,-30,8,-8); helG.addColorStop(0,'rgba(255,255,255,0.35)'); helG.addColorStop(0.5,'rgba(0,0,0,0)'); helG.addColorStop(1,'rgba(0,0,0,0.28)');
  ctx.fillStyle=helG; ctx.beginPath(); ctx.ellipse(0,-19,10,11,0,0,Math.PI*2); ctx.fill();
  ctx.strokeStyle='#c8a020'; ctx.lineWidth=1.2; ctx.stroke(); // gold trim on helmet
  // Visor grille
  ctx.fillStyle='#c8a020'; ctx.fillRect(-8,-22,16,1.5); ctx.fillRect(-8,-14,16,1.5);
  ctx.strokeStyle='#c8a020'; ctx.lineWidth=0.9;
  for(let i=0;i<5;i++){ctx.beginPath(); ctx.moveTo(-7.5+i*3.5,-22); ctx.lineTo(-7.5+i*3.5,-14); ctx.stroke();}
  ctx.fillStyle='rgba(0,0,0,0.40)'; ctx.fillRect(-7,-21.5,14,7);
  ctx.fillStyle='rgba(200,220,255,0.50)'; ctx.fillRect(-5,-19.5,10,2.5); // blue eye glow
  // Helmet top ridge
  ctx.fillStyle='#7888a0'; ctx.fillRect(-9,-30,18,4);
  ctx.fillStyle='rgba(255,255,255,0.20)'; ctx.fillRect(-8,-29.5,16,1.5);
  // GOLD WINGS on sides (like photo paladin)
  ctx.fillStyle='#d4a818';
  ctx.beginPath(); ctx.moveTo(-10,-22); ctx.lineTo(-20,-32); ctx.lineTo(-16,-26); ctx.lineTo(-14,-20); ctx.closePath(); ctx.fill();
  ctx.beginPath(); ctx.moveTo(10,-22); ctx.lineTo(20,-32); ctx.lineTo(16,-26); ctx.lineTo(14,-20); ctx.closePath(); ctx.fill();
  // Wing highlight
  ctx.fillStyle='rgba(255,220,80,0.45)';
  ctx.beginPath(); ctx.moveTo(-10,-22); ctx.lineTo(-18,-30); ctx.lineTo(-15,-25); ctx.closePath(); ctx.fill();
  ctx.beginPath(); ctx.moveTo(10,-22); ctx.lineTo(18,-30); ctx.lineTo(15,-25); ctx.closePath(); ctx.fill();
  // Wing shadow outline
  ctx.strokeStyle='#a87810'; ctx.lineWidth=0.7;
  ctx.beginPath(); ctx.moveTo(-10,-22); ctx.lineTo(-20,-32); ctx.lineTo(-16,-26); ctx.lineTo(-14,-20); ctx.closePath(); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(10,-22); ctx.lineTo(20,-32); ctx.lineTo(16,-26); ctx.lineTo(14,-20); ctx.closePath(); ctx.stroke();
  // Face (visible)
  drawFace(ctx,0,-20,'#d0c0a8');
}

function drawBard(ctx, color){
  const boot='#6a3010';
  ctx.fillStyle=boot; rr(ctx,-9,14,6,16,2); ctx.fill(); rr(ctx,3,14,6,16,2); ctx.fill();
  // Fold cuff
  ctx.fillStyle='#8a4520'; ctx.fillRect(-9,13,6,4); ctx.fillRect(3,13,6,4);
  ctx.fillStyle='#161a40';
  ctx.beginPath(); ctx.ellipse(-6,8,5.5,7,0,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(6,8,5.5,7,0,0,Math.PI*2); ctx.fill();
  const stripeW=2.8;
  for(let i=0;i<7;i++){
    ctx.fillStyle=i%2===0?'#0c0c0c':'#eceae0';
    ctx.fillRect(-11+i*stripeW,-11,stripeW,22);
  }
  // Round coat silhouette via clip then fill is complex — draw outline over stripes
  ctx.strokeStyle='#0c0c0c'; ctx.lineWidth=1.2;
  ctx.strokeRect(-11,-11,19.6,22);
  // Gold trim borders
  ctx.strokeStyle='#d4a820'; ctx.lineWidth=1.4;
  ctx.beginPath(); ctx.moveTo(-11,11); ctx.lineTo(8.6,11); ctx.stroke();   // hem
  ctx.beginPath(); ctx.moveTo(-11,-11); ctx.lineTo(8.6,-11); ctx.stroke(); // top
  ctx.beginPath(); ctx.moveTo(-11,-11); ctx.lineTo(-11,11); ctx.stroke();  // left edge
  ctx.beginPath(); ctx.moveTo(8.6,-11); ctx.lineTo(8.6,11); ctx.stroke(); // right edge
  // Front opening gold strip
  ctx.beginPath(); ctx.moveTo(-0.5,-11); ctx.lineTo(-0.5,11); ctx.stroke();
  ctx.fillStyle='#eceae4';
  ctx.beginPath(); ctx.ellipse(0,-10,8,4,0,0,Math.PI*2); ctx.fill();
  ctx.strokeStyle='rgba(0,0,0,0.18)'; ctx.lineWidth=0.6; ctx.stroke();
  ctx.fillStyle='#0c0c0c'; ctx.fillRect(-16,-5,6,12); ctx.fillRect(11,-5,6,12); // sleeve
  ctx.fillStyle='#d4a070'; ctx.beginPath(); ctx.ellipse(-13,8,3.5,3,0,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(14,8,3.5,3,0,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='#9a5422';  // light wood
  ctx.beginPath(); ctx.ellipse(0,3,9,11,-0.15,0,Math.PI*2); ctx.fill();
  const luteG=ctx.createRadialGradient(-2,1,1,-2,1,9);
  luteG.addColorStop(0,'rgba(255,200,120,0.28)'); luteG.addColorStop(1,'rgba(0,0,0,0.18)');
  ctx.fillStyle=luteG; ctx.beginPath(); ctx.ellipse(0,3,9,11,-0.15,0,Math.PI*2); ctx.fill();
  ctx.strokeStyle='#5c2818'; ctx.lineWidth=1.0; ctx.beginPath(); ctx.ellipse(0,3,9,11,-0.15,0,Math.PI*2); ctx.stroke();
  // Sound hole
  ctx.fillStyle='#0a0806'; ctx.beginPath(); ctx.arc(0,4,2.5,0,Math.PI*2); ctx.fill();
  ctx.strokeStyle='#d4a820'; ctx.lineWidth=0.8; ctx.beginPath(); ctx.arc(0,4,2.5,0,Math.PI*2); ctx.stroke();
  // Neck (pointing upper-left)
  ctx.fillStyle='#3e1c0a'; ctx.strokeStyle='#0a0806'; ctx.lineWidth=0.7;
  ctx.beginPath(); ctx.moveTo(-5,-7); ctx.lineTo(-8,-8.5); ctx.lineTo(-14,-26); ctx.lineTo(-11,-26.5); ctx.closePath(); ctx.fill(); ctx.stroke();
  // Frets
  ctx.strokeStyle='#b0a080'; ctx.lineWidth=0.9;
  for(let i=0;i<4;i++){ const t=i/4; ctx.beginPath(); ctx.moveTo(-8-t*6,-8.5-t*18); ctx.lineTo(-6-t*5,-8-t*18.5); ctx.stroke(); }
  // Strings
  ctx.strokeStyle='rgba(220,210,160,0.9)'; ctx.lineWidth=0.6;
  for(let i=0;i<4;i++){ const ox=-0.5+i*1.5; ctx.beginPath(); ctx.moveTo(ox+1,13); ctx.lineTo(-7+ox-i*1.5,-26); ctx.stroke(); }
  ctx.fillStyle='#b04418';  // auburn hair (sides/back)
  ctx.beginPath(); ctx.ellipse(0,-20,10,12,0,0,Math.PI*2); ctx.fill();
  // Long hair strands falling
  ctx.fillStyle='#a03c14';
  rr(ctx,-12,-24,4,18,2); ctx.fill();  // left strand
  rr(ctx, 9,-24,4,16,2); ctx.fill();  // right strand
  drawFace(ctx,0,-20,'#d4a070');
  // Wide bard smile overlay
  ctx.strokeStyle='rgba(0,0,0,0.5)'; ctx.lineWidth=1.4;
  ctx.beginPath(); ctx.arc(0,-18,4,0.1,Math.PI-0.1,false); ctx.stroke();
  ctx.save(); ctx.translate(-2,-28); ctx.rotate(-0.30);
  ctx.fillStyle='#c81818';
  ctx.beginPath(); ctx.ellipse(0,0,10,5,0,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(0,-1,8,4,0,0,Math.PI); ctx.fill();  // dome
  ctx.strokeStyle='#7c1010'; ctx.lineWidth=1.0; ctx.beginPath(); ctx.ellipse(0,0,10,5,0,0,Math.PI*2); ctx.stroke();
  // Small button
  ctx.fillStyle='#d4a820'; ctx.beginPath(); ctx.arc(0,-4.5,1.5,0,Math.PI*2); ctx.fill();
  ctx.restore();
}

function drawGoblin(ctx){
  ctx.fillStyle='#3a5820'; rr(ctx,-6,3,4,11,2); ctx.fill(); rr(ctx,2,3,4,11,2); ctx.fill();
  ctx.fillStyle='#4a7428'; rr(ctx,-7,-5,14,10,2); ctx.fill();
  ctx.fillStyle='rgba(255,255,255,0.1)'; ctx.fillRect(-5,-4,4,5);
  ctx.fillStyle='#4a7428'; rr(ctx,-10,-4,4,13,2); ctx.fill(); rr(ctx,6,-4,4,13,2); ctx.fill();
  ctx.fillStyle='#2a3810';
  for(let i=0;i<3;i++){ctx.beginPath(); ctx.ellipse(-8+i*1.5,9,1,3,0.3,0,Math.PI*2); ctx.fill();}
  for(let i=0;i<3;i++){ctx.beginPath(); ctx.ellipse(7+i*1.5,9,1,3,-0.3,0,Math.PI*2); ctx.fill();}
  ctx.fillStyle='#4a7428'; ctx.beginPath(); ctx.ellipse(0,-10,9,8,0,0,Math.PI*2); ctx.fill();
  ctx.strokeStyle='#3a6020'; ctx.lineWidth=0.8; ctx.stroke();
  ctx.fillStyle='#4a7428';
  ctx.beginPath(); ctx.moveTo(-9,-7); ctx.lineTo(-15,-17); ctx.lineTo(-5,-11); ctx.closePath(); ctx.fill();
  ctx.beginPath(); ctx.moveTo(9,-7); ctx.lineTo(15,-17); ctx.lineTo(5,-11); ctx.closePath(); ctx.fill();
  ctx.fillStyle='#ff7700'; ctx.beginPath(); ctx.ellipse(-3.5,-11,3,2.5,0,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(3.5,-11,3,2.5,0,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='#1a0800'; ctx.beginPath(); ctx.arc(-3.5,-11,1.3,0,Math.PI*2); ctx.fill(); ctx.beginPath(); ctx.arc(3.5,-11,1.3,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='rgba(255,255,255,0.7)'; ctx.fillRect(-3,-11,0.8,0.8); ctx.fillRect(3.8,-11,0.8,0.8);
  ctx.fillStyle='#d0c080'; ctx.fillRect(-5,-4,2.5,2); ctx.fillRect(-1.5,-4,3,2); ctx.fillRect(2.5,-4,2,2);
  ctx.strokeStyle='#5a3a10'; ctx.lineWidth=2; ctx.beginPath(); ctx.moveTo(9,0); ctx.lineTo(16,-9); ctx.stroke();
  ctx.fillStyle='#7a5030'; ctx.beginPath(); ctx.ellipse(17,-10,4,3,0.5,0,Math.PI*2); ctx.fill();
}

function drawSkeleton(ctx){
  const bone='#e0d8b8';
  ctx.fillStyle=bone; ctx.fillRect(-5.5,5,3,14); ctx.fillRect(2.5,5,3,14);
  ctx.beginPath(); ctx.arc(-4,11,3,0,Math.PI*2); ctx.fill(); ctx.beginPath(); ctx.arc(4,11,3,0,Math.PI*2); ctx.fill();
  ctx.fillRect(-7,17,5,3); ctx.fillRect(2,17,5,3);
  ctx.beginPath(); ctx.ellipse(0,3,8,4,0,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(0,-5,7,9,0,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='rgba(0,0,0,0.4)';
  for(let i=0;i<4;i++){ctx.fillRect(-6,-1+i*3,3,1.5); ctx.fillRect(3,-1+i*3,3,1.5);}
  ctx.fillStyle=bone; ctx.fillRect(-13,-6,3,12); ctx.fillRect(10,-6,3,12);
  ctx.beginPath(); ctx.arc(-11.5,2,3,0,Math.PI*2); ctx.fill(); ctx.beginPath(); ctx.arc(11.5,2,3,0,Math.PI*2); ctx.fill();
  for(let i=0;i<3;i++){ctx.fillRect(-15+i*1.5,7,1.5,5); ctx.fillRect(10+i*1.5,7,1.5,5);}
  ctx.beginPath(); ctx.ellipse(0,-17,9,9,0,0,Math.PI*2); ctx.fill();
  ctx.strokeStyle='rgba(0,0,0,0.2)'; ctx.lineWidth=0.7; ctx.stroke();
  ctx.fillStyle='#100800'; ctx.beginPath(); ctx.ellipse(-3.5,-18,3.5,3,0,0,Math.PI*2); ctx.fill(); ctx.beginPath(); ctx.ellipse(3.5,-18,3.5,3,0,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='rgba(60,220,100,0.95)'; ctx.beginPath(); ctx.arc(-3.5,-18,1.5,0,Math.PI*2); ctx.fill(); ctx.beginPath(); ctx.arc(3.5,-18,1.5,0,Math.PI*2); ctx.fill();
  ctx.fillStyle=bone; ctx.beginPath(); ctx.ellipse(0,-11,6,4,0,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='rgba(0,0,0,0.45)'; ctx.fillRect(-4,-12.5,2.5,2); ctx.fillRect(-0.5,-12.5,2.5,2); ctx.fillRect(2.5,-12.5,2,2);
  ctx.strokeStyle='#8090a8'; ctx.lineWidth=2;
  ctx.beginPath(); ctx.moveTo(-13,-16); ctx.lineTo(-13,4); ctx.stroke();
  ctx.fillStyle='#8090a8'; ctx.fillRect(-16,-5,6,2);
}

function drawOrc(ctx){
  const skin='#48a838'; // bright vivid green like painted miniature
  const bone='#d8c890'; // bone/ivory armour

  // ── Thick leather legs + wrapped boots
  ctx.fillStyle='#3a2010'; rr(ctx,-9,5,7,14,2); ctx.fill(); rr(ctx,2,5,7,14,2); ctx.fill();
  ctx.strokeStyle='#5a3010'; ctx.lineWidth=1;
  for(let y=8;y<18;y+=3.5){ ctx.beginPath(); ctx.moveTo(-9,y); ctx.lineTo(-2,y); ctx.stroke(); ctx.beginPath(); ctx.moveTo(2,y); ctx.lineTo(9,y); ctx.stroke(); }
  ctx.fillStyle='#281808'; ctx.fillRect(-10,17,8,5); ctx.fillRect(2,17,8,5);
  ctx.fillStyle='rgba(255,255,255,0.08)'; ctx.fillRect(-9.5,17,6,1.5); ctx.fillRect(2.5,17,6,1.5);

  // ── Leather chest with bone plate armour
  ctx.fillStyle='#5a3818'; rr(ctx,-11,-8,22,14,3); ctx.fill();
  const chG=ctx.createLinearGradient(-11,-8,9,6);
  chG.addColorStop(0,'rgba(255,255,255,0.12)'); chG.addColorStop(0.5,'rgba(0,0,0,0)'); chG.addColorStop(1,'rgba(0,0,0,0.28)');
  ctx.fillStyle=chG; rr(ctx,-11,-8,22,14,3); ctx.fill();
  // Bone plate left
  ctx.fillStyle=bone; rr(ctx,-10,-7,8,10,2); ctx.fill();
  ctx.fillStyle='rgba(0,0,0,0.18)'; rr(ctx,-10,-7,8,10,2); ctx.fill();
  ctx.fillStyle='rgba(255,255,255,0.28)'; ctx.fillRect(-9,-6,3,4);
  ctx.strokeStyle='rgba(80,60,20,0.5)'; ctx.lineWidth=0.8; rr(ctx,-10,-7,8,10,2); ctx.stroke();
  // Bone plate right
  ctx.fillStyle=bone; rr(ctx,2,-7,8,10,2); ctx.fill();
  ctx.fillStyle='rgba(0,0,0,0.18)'; rr(ctx,2,-7,8,10,2); ctx.fill();
  ctx.fillStyle='rgba(255,255,255,0.28)'; ctx.fillRect(3,-6,3,4);
  ctx.strokeStyle='rgba(80,60,20,0.5)'; ctx.lineWidth=0.8; rr(ctx,2,-7,8,10,2); ctx.stroke();
  // Sinew bindings between plates
  ctx.strokeStyle='#8a6030'; ctx.lineWidth=1.5;
  ctx.beginPath(); ctx.moveTo(-2,-4); ctx.lineTo(2,-4); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(-2,0); ctx.lineTo(2,0); ctx.stroke();
  // Belt
  ctx.fillStyle='#3a2010'; ctx.fillRect(-11,4,22,4);
  ctx.fillStyle='rgba(255,255,255,0.08)'; ctx.fillRect(-11,4,22,1.5);
  // Trophy skull on belt
  ctx.fillStyle='#e0d4a8'; ctx.beginPath(); ctx.ellipse(0,6,3.5,3,0,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='rgba(0,0,0,0.38)'; ctx.beginPath(); ctx.arc(-1.2,5.5,1,0,Math.PI*2); ctx.fill(); ctx.beginPath(); ctx.arc(1.2,5.5,1,0,Math.PI*2); ctx.fill();
  ctx.strokeStyle='rgba(80,60,20,0.5)'; ctx.lineWidth=0.7; ctx.beginPath(); ctx.ellipse(0,6,3.5,3,0,0,Math.PI*2); ctx.stroke();

  // ── Thick muscular arms (green skin)
  ctx.fillStyle=skin; rr(ctx,-16,-6,6,16,3); ctx.fill(); rr(ctx,10,-6,6,16,3); ctx.fill();
  const armG=ctx.createLinearGradient(-16,-6,-10,10);
  armG.addColorStop(0,'rgba(255,255,255,0.15)'); armG.addColorStop(0.6,'rgba(0,0,0,0)'); armG.addColorStop(1,'rgba(0,0,0,0.22)');
  ctx.fillStyle=armG; rr(ctx,-16,-6,6,16,3); ctx.fill();
  const armG2=ctx.createLinearGradient(16,-6,10,10);
  armG2.addColorStop(0,'rgba(255,255,255,0.15)'); armG2.addColorStop(0.6,'rgba(0,0,0,0)'); armG2.addColorStop(1,'rgba(0,0,0,0.22)');
  ctx.fillStyle=armG2; rr(ctx,10,-6,6,16,3); ctx.fill();
  // Bone forearm bands
  ctx.fillStyle=bone; ctx.fillRect(-17,5,8,3); ctx.fillRect(9,5,8,3);
  ctx.fillStyle='rgba(0,0,0,0.2)'; ctx.fillRect(-17,5,8,3); ctx.fillRect(9,5,8,3);
  ctx.strokeStyle='rgba(80,60,20,0.5)'; ctx.lineWidth=0.7; ctx.strokeRect(-17,5,8,3); ctx.strokeRect(9,5,8,3);
  // Heavy fists
  ctx.fillStyle=_cl(skin,0.85); ctx.beginPath(); ctx.ellipse(-13,12,5,4,0.4,0,Math.PI*2); ctx.fill(); ctx.beginPath(); ctx.ellipse(13,12,5,4,-0.4,0,Math.PI*2); ctx.fill();

  // ── Large battle axe (right hand)
  ctx.strokeStyle='#5a3010'; ctx.lineWidth=3.5; ctx.lineCap='round';
  ctx.beginPath(); ctx.moveTo(14,5); ctx.lineTo(22,-20); ctx.stroke();
  ctx.strokeStyle='#8a4820'; ctx.lineWidth=1.5;
  for(let i=0;i<5;i++){ const t=i/4; ctx.beginPath(); ctx.arc(14+(22-14)*t,5+(-20-5)*t,1.8,0,Math.PI*2); ctx.stroke(); }
  ctx.save(); ctx.translate(24,-22); ctx.rotate(0.7);
  ctx.fillStyle='#808898';
  ctx.beginPath(); ctx.moveTo(-3,-10); ctx.bezierCurveTo(4,-14,12,-10,10,0); ctx.bezierCurveTo(12,10,4,10,-3,8); ctx.closePath(); ctx.fill();
  const blG=ctx.createLinearGradient(-3,-10,10,5);
  blG.addColorStop(0,'rgba(255,255,255,0.42)'); blG.addColorStop(0.35,'rgba(255,255,255,0.1)'); blG.addColorStop(0.65,'rgba(0,0,0,0)'); blG.addColorStop(1,'rgba(0,0,0,0.30)');
  ctx.fillStyle=blG; ctx.beginPath(); ctx.moveTo(-3,-10); ctx.bezierCurveTo(4,-14,12,-10,10,0); ctx.bezierCurveTo(12,10,4,10,-3,8); ctx.closePath(); ctx.fill();
  ctx.strokeStyle='#c8ccd8'; ctx.lineWidth=1.2; ctx.lineCap='round';
  ctx.beginPath(); ctx.moveTo(-3,-10); ctx.bezierCurveTo(4,-14,12,-10,10,0); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(-3,8); ctx.bezierCurveTo(4,10,12,10,10,0); ctx.stroke();
  ctx.fillStyle='#9098a8'; ctx.beginPath(); ctx.moveTo(-3,-10); ctx.lineTo(-1,-16); ctx.lineTo(2,-10); ctx.closePath(); ctx.fill();
  ctx.fillStyle='rgba(255,255,255,0.3)'; ctx.beginPath(); ctx.moveTo(-3,-10); ctx.lineTo(-1,-16); ctx.lineTo(-1,-10); ctx.closePath(); ctx.fill();
  ctx.fillStyle='#505868'; for(const [rx,ry] of [[0,-4],[0,2],[-2,-1]]){ ctx.beginPath(); ctx.arc(rx,ry,0.9,0,Math.PI*2); ctx.fill(); }
  ctx.restore(); ctx.lineCap='butt';

  // ── Orc head (large, brutish)
  ctx.fillStyle=skin; ctx.beginPath(); ctx.ellipse(0,-18,11,10,0,0,Math.PI*2); ctx.fill();
  ctx.strokeStyle=_cl(skin,0.72); ctx.lineWidth=0.8; ctx.stroke();
  // Heavy brow ridge
  ctx.fillStyle=_cl(skin,0.80); ctx.beginPath(); ctx.arc(-4,-22,3.5,0,Math.PI*2); ctx.fill(); ctx.beginPath(); ctx.arc(4,-22,3.5,0,Math.PI*2); ctx.fill(); ctx.beginPath(); ctx.arc(0,-24,3,0,Math.PI*2); ctx.fill();
  // Bone crown/headband
  ctx.fillStyle=bone; ctx.fillRect(-10,-27,20,4);
  ctx.fillStyle='rgba(0,0,0,0.2)'; ctx.fillRect(-10,-27,20,4);
  ctx.fillStyle='rgba(255,255,255,0.18)'; ctx.fillRect(-10,-27,20,1.5);
  ctx.strokeStyle='rgba(80,60,20,0.5)'; ctx.lineWidth=0.7; ctx.strokeRect(-10,-27,20,4);
  // Bone spikes on crown
  ctx.fillStyle=bone;
  for(const [sx] of [[-7],[0],[7]]){ ctx.beginPath(); ctx.moveTo(sx-2,-27); ctx.lineTo(sx+2,-27); ctx.lineTo(sx,-32); ctx.closePath(); ctx.fill(); ctx.strokeStyle='rgba(80,60,20,0.45)'; ctx.lineWidth=0.6; ctx.beginPath(); ctx.moveTo(sx-2,-27); ctx.lineTo(sx+2,-27); ctx.lineTo(sx,-32); ctx.closePath(); ctx.stroke(); }
  // Fierce red eyes
  ctx.fillStyle='#cc1800'; ctx.beginPath(); ctx.ellipse(-4,-19,3.2,2.8,0,0,Math.PI*2); ctx.fill(); ctx.beginPath(); ctx.ellipse(4,-19,3.2,2.8,0,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='#1a0000'; ctx.beginPath(); ctx.arc(-4,-19,1.4,0,Math.PI*2); ctx.fill(); ctx.beginPath(); ctx.arc(4,-19,1.4,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='rgba(255,255,255,0.7)'; ctx.fillRect(-3.5,-19.5,0.8,0.8); ctx.fillRect(4.5,-19.5,0.8,0.8);
  // Thick nose
  ctx.fillStyle=_cl(skin,0.78); ctx.beginPath(); ctx.ellipse(0,-15,3.5,2.5,0,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='rgba(0,0,0,0.45)'; ctx.beginPath(); ctx.arc(-1.5,-15,1,0,Math.PI*2); ctx.fill(); ctx.beginPath(); ctx.arc(1.5,-15,1,0,Math.PI*2); ctx.fill();
  // Ivory tusks
  ctx.fillStyle='#e8d898';
  ctx.beginPath(); ctx.moveTo(-5,-11); ctx.lineTo(-8,-7); ctx.lineTo(-4,-9); ctx.closePath(); ctx.fill();
  ctx.beginPath(); ctx.moveTo(5,-11); ctx.lineTo(8,-7); ctx.lineTo(4,-9); ctx.closePath(); ctx.fill();
  ctx.strokeStyle='rgba(140,110,30,0.5)'; ctx.lineWidth=0.6;
  ctx.beginPath(); ctx.moveTo(-5,-11); ctx.lineTo(-8,-7); ctx.lineTo(-4,-9); ctx.closePath(); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(5,-11); ctx.lineTo(8,-7); ctx.lineTo(4,-9); ctx.closePath(); ctx.stroke();
  // Grimacing mouth
  ctx.strokeStyle='rgba(0,0,0,0.55)'; ctx.lineWidth=1.5;
  ctx.beginPath(); ctx.moveTo(-4,-12); ctx.quadraticCurveTo(0,-10,4,-12); ctx.stroke();
}

function drawDarkMage(ctx){
  const robe='#1a0830';
  ctx.fillStyle=robe; ctx.beginPath(); ctx.moveTo(-8,-8); ctx.lineTo(-13,19); ctx.lineTo(13,19); ctx.lineTo(8,-8); ctx.closePath(); ctx.fill();
  ctx.fillStyle='#250d45'; rr(ctx,-9,-8,18,14,3); ctx.fill();
  ctx.fillStyle='rgba(160,50,220,0.3)'; ctx.fillRect(-6,-7,5,11);
  ctx.fillStyle='rgba(180,50,230,0.85)'; ctx.font='5px serif'; ctx.textAlign='center'; ctx.textBaseline='middle';
  ctx.fillText('ᚱ',-4,2); ctx.fillText('ᚦ',4,2);
  ctx.fillStyle='#250d45'; rr(ctx,-13,-7,5,10,2); ctx.fill(); rr(ctx,8,-7,5,10,2); ctx.fill();
  const og=ctx.createRadialGradient(-12,2,1,-12,2,5);
  og.addColorStop(0,'#ff80ff'); og.addColorStop(1,'#600080');
  ctx.fillStyle=og; ctx.beginPath(); ctx.arc(-12,3,5,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='#c8c0b0'; for(let i=0;i<3;i++){ctx.fillRect(9+i*1.5,4,1.5,6);}
  ctx.fillStyle='#0d0420'; ctx.beginPath(); ctx.ellipse(0,-19,10,11,0,Math.PI,0); ctx.fill();
  ctx.fillStyle='#180830'; ctx.beginPath(); ctx.ellipse(0,-18,8,7.5,0,Math.PI,0); ctx.fill();
  ctx.fillStyle='rgba(0,0,0,0.65)'; ctx.beginPath(); ctx.ellipse(0,-21,8,6,0,0,Math.PI); ctx.fill();
  ctx.fillStyle='rgba(160,0,255,0.95)'; ctx.beginPath(); ctx.arc(-3,-20,2,0,Math.PI*2); ctx.fill(); ctx.beginPath(); ctx.arc(3,-20,2,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='rgba(255,180,255,0.6)'; ctx.beginPath(); ctx.arc(-3,-20,0.8,0,Math.PI*2); ctx.fill(); ctx.beginPath(); ctx.arc(3,-20,0.8,0,Math.PI*2); ctx.fill();
}

function drawTroll(ctx){
  const skin='#6a7050';
  ctx.fillStyle='#4a4830'; rr(ctx,-10,5,8,13,2); ctx.fill(); rr(ctx,2,5,8,13,2); ctx.fill();
  ctx.fillStyle='rgba(255,255,255,0.08)'; ctx.fillRect(-9,6,3,10); ctx.fillRect(3,6,3,10);
  ctx.fillStyle=skin; rr(ctx,-13,-8,26,15,3); ctx.fill();
  ctx.fillStyle='rgba(255,255,255,0.07)'; ctx.fillRect(-11,-7,8,10);
  ctx.fillStyle=_cl(skin,0.82);
  for(const [bx,by,br] of [[-5,-4,2.5],[3,2,2],[7,-6,2],[-8,1,1.5],[0,-6,1.5]]){ctx.beginPath(); ctx.arc(bx,by,br,0,Math.PI*2); ctx.fill();}
  ctx.fillStyle=skin; rr(ctx,-18,-6,6,18,3); ctx.fill(); rr(ctx,12,-6,6,18,3); ctx.fill();
  ctx.fillStyle=_cl(skin,0.8); ctx.beginPath(); ctx.ellipse(-15,13,5,4,0.4,0,Math.PI*2); ctx.fill(); ctx.beginPath(); ctx.ellipse(15,13,5,4,-0.4,0,Math.PI*2); ctx.fill();
  ctx.fillStyle=skin; ctx.beginPath(); ctx.ellipse(0,-15,12,8,0,0,Math.PI*2); ctx.fill();
  ctx.strokeStyle=_cl(skin,0.7); ctx.lineWidth=0.8; ctx.stroke();
  ctx.fillStyle=_cl(skin,0.72); ctx.beginPath(); ctx.arc(-5,-20,4,0,Math.PI*2); ctx.fill(); ctx.beginPath(); ctx.arc(5,-20,4,0,Math.PI*2); ctx.fill(); ctx.beginPath(); ctx.arc(0,-22,3,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='#e04000'; ctx.beginPath(); ctx.ellipse(-4,-16,3,2.5,0,0,Math.PI*2); ctx.fill(); ctx.beginPath(); ctx.ellipse(4,-16,3,2.5,0,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='#400'; ctx.beginPath(); ctx.arc(-4,-16,1.2,0,Math.PI*2); ctx.fill(); ctx.beginPath(); ctx.arc(4,-16,1.2,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='#2a1a10'; ctx.beginPath(); ctx.moveTo(-7,-10); ctx.quadraticCurveTo(0,-7,7,-10); ctx.fill();
  ctx.fillStyle='#d0c090'; for(let i=0;i<5;i++){ctx.beginPath(); ctx.moveTo(-6+i*3,-10); ctx.lineTo(-5+i*3,-7); ctx.lineTo(-4+i*3,-10); ctx.closePath(); ctx.fill();}
}

function drawDragon(ctx){
  ctx.fillStyle='rgba(180,20,0,0.65)';
  ctx.beginPath(); ctx.moveTo(-8,-8); ctx.lineTo(-26,-26); ctx.lineTo(-20,-4); ctx.lineTo(-14,10); ctx.closePath(); ctx.fill();
  ctx.beginPath(); ctx.moveTo(8,-8); ctx.lineTo(26,-26); ctx.lineTo(20,-4); ctx.lineTo(14,10); ctx.closePath(); ctx.fill();
  ctx.strokeStyle='rgba(255,80,0,0.45)'; ctx.lineWidth=1;
  ctx.beginPath(); ctx.moveTo(-8,-8); ctx.lineTo(-24,-20); ctx.stroke(); ctx.beginPath(); ctx.moveTo(-8,-6); ctx.lineTo(-20,-4); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(8,-8); ctx.lineTo(24,-20); ctx.stroke(); ctx.beginPath(); ctx.moveTo(8,-6); ctx.lineTo(20,-4); ctx.stroke();
  ctx.strokeStyle='#8a1500'; ctx.lineWidth=5; ctx.lineCap='round';
  ctx.beginPath(); ctx.moveTo(8,8); ctx.bezierCurveTo(20,15,28,5,32,12); ctx.stroke();
  const bg=ctx.createRadialGradient(-3,-5,2,0,0,16);
  bg.addColorStop(0,'#d03000'); bg.addColorStop(1,'#600a00');
  ctx.fillStyle=bg; ctx.beginPath(); ctx.ellipse(0,0,14,18,0,0,Math.PI*2); ctx.fill();
  ctx.strokeStyle='#ff4000'; ctx.lineWidth=1; ctx.stroke();
  ctx.fillStyle='rgba(255,100,0,0.3)'; for(let i=0;i<4;i++){ctx.beginPath(); ctx.ellipse(0,-5+i*5,8-i,3,0,0,Math.PI*2); ctx.fill();}
  ctx.fillStyle='#7a1000'; rr(ctx,-10,12,7,10,3); ctx.fill(); rr(ctx,3,12,7,10,3); ctx.fill();
  ctx.fillStyle='#1a0800';
  for(let i=0;i<3;i++){ctx.beginPath(); ctx.ellipse(-8+i*1.8,22,1.5,4,0.4,0,Math.PI*2); ctx.fill();}
  for(let i=0;i<3;i++){ctx.beginPath(); ctx.ellipse(4+i*1.8,22,1.5,4,-0.4,0,Math.PI*2); ctx.fill();}
  ctx.fillStyle='#9a1800'; rr(ctx,-5,-18,10,11,3); ctx.fill();
  ctx.fillStyle='#b02000'; ctx.beginPath(); ctx.ellipse(0,-25,11,9,0,0,Math.PI*2); ctx.fill();
  ctx.strokeStyle='#e03000'; ctx.lineWidth=0.8; ctx.stroke();
  ctx.fillStyle='#3a0a00'; ctx.beginPath(); ctx.moveTo(-7,-31); ctx.lineTo(-13,-40); ctx.lineTo(-5,-32); ctx.closePath(); ctx.fill(); ctx.beginPath(); ctx.moveTo(7,-31); ctx.lineTo(13,-40); ctx.lineTo(5,-32); ctx.closePath(); ctx.fill();
  ctx.fillStyle='#ffcc00'; ctx.beginPath(); ctx.ellipse(-4.5,-26,4,3,0,0,Math.PI*2); ctx.fill(); ctx.beginPath(); ctx.ellipse(4.5,-26,4,3,0,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='#1a0000'; ctx.beginPath(); ctx.ellipse(-4.5,-26,1.5,2.5,0.2,0,Math.PI*2); ctx.fill(); ctx.beginPath(); ctx.ellipse(4.5,-26,1.5,2.5,-0.2,0,Math.PI*2); ctx.fill();
  const fg=ctx.createLinearGradient(11,-28,26,-18);
  fg.addColorStop(0,'rgba(255,200,0,0.9)'); fg.addColorStop(1,'rgba(255,50,0,0)');
  ctx.fillStyle=fg; ctx.beginPath(); ctx.moveTo(10,-25); ctx.lineTo(28,-18); ctx.lineTo(26,-14); ctx.lineTo(8,-22); ctx.closePath(); ctx.fill();
}

// ── Miniaturas 2D dos heróis (frente.png) para o modo canvas ────────────────
// Antes o modo 2D desenhava heróis proceduralmente (drawWarrior, …) e NUNCA
// usava as PNGs. Agora usa as mesmas imagens do 3D. Carrega lazy; enquanto não
// carrega, drawHeroSprite cai no sprite procedural. Ao carregar, redesenha.
const _hero2DImg = {};
function _rerender2DAfterAssetLoad(){
  // GS é um `const` global lexical vindo de gameState.js, não window.GS. No
  // teste livre não há broadcasts contínuos para redesenhar PNGs recém-carregados.
  if(!mode3D && GS.gameState){
    try { renderMap(GS.gameState); } catch(_) {}
  }
}
function _getHero2DImg(classId){
  if(!classId) return null;
  let img = _hero2DImg[classId];
  if(img === undefined){
    img = new Image();
    img.onload = _rerender2DAfterAssetLoad;
    img.src = _assetURL(`assets/pawns/${classId}/frente.png`);
    _hero2DImg[classId] = img;
  }
  return img;
}

// Mesma ideia para os monstros: usa assets/pawns/monstros/<image>/<image>.png.
const _mon2DImg = {};
const _MONSTER_TYPE_DEFAULT_IMAGE = Object.freeze({
  goblin: 'goblinCombatente',
  skeleton: 'esqueletoHumano',
  orc: 'orcGuerreiro',
  dark_mage: 'necromante',
  troll: 'troll',
  medusa: 'medusa',
  grande_medusa: 'medusa',
  grande_gorgona: 'medusa',
});
function _monsterImageName(monster){
  const formaAtiva = _metamorfoseVisualName(monster);
  return monster && (formaAtiva || monster.image || _MONSTER_TYPE_DEFAULT_IMAGE[monster.type]) || null;
}
function _metamorfoseVisualName(entity){
  if(!entity) return null;
  return (entity.metamorfose_ativa && entity.metamorfose_forma_type)
    || entity.pawn_override || null;
}
function _getMonster2DImg(imageName){
  if(!imageName) return null;
  let img = _mon2DImg[imageName];
  if(img === undefined){
    img = new Image();
    img.onload = _rerender2DAfterAssetLoad;
    img.src = _assetURL(`assets/pawns/monstros/${imageName}/${imageName}.png`);
    _mon2DImg[imageName] = img;
  }
  return img;
}

// Miniatura 2D do prisioneiro (imagem editável). url completa em assets/pawns/prisioneiros/.
const _pris2DImg = {};
function _getPrisoner2DImg(imageName){
  if(!imageName) return null;
  let img = _pris2DImg[imageName];
  if(img === undefined){
    img = new Image();
    img.onload = _rerender2DAfterAssetLoad;
    img.src = _assetURL(`assets/pawns/prisioneiros/${imageName}`);
    _pris2DImg[imageName] = img;
  }
  return img;
}

// Miniatura 2D de objeto de decoração (PNG editável em assets/objetos/).
const _obj2DImg = {};
function _getObjeto2DImg(imageName){
  if(!imageName) return null;
  let img = _obj2DImg[imageName];
  if(img === undefined){
    img = new Image();
    img.onload = _rerender2DAfterAssetLoad;
    img.src = _assetURL(`assets/objetos/${imageName}`);
    _obj2DImg[imageName] = img;
  }
  return (img.complete && img.naturalWidth) ? img : null;
}
const _wallObj2DImg = {};
function _getWallObjeto2DImg(imageName){
  const src = _getObjeto2DImg(imageName); if(!src) return null;
  if(_wallObj2DImg[imageName]) return _wallObj2DImg[imageName];
  const cv=document.createElement('canvas'); cv.width=src.naturalWidth; cv.height=src.naturalHeight;
  const c=cv.getContext('2d', {willReadFrequently:true}); c.drawImage(src,0,0);
  const data=c.getImageData(0,0,cv.width,cv.height);
  for(let i=0;i<data.data.length;i+=4){ const hi=Math.max(data.data[i],data.data[i+1],data.data[i+2]); if(hi<=10)data.data[i+3]=0; else if(hi<32)data.data[i+3]=Math.round(data.data[i+3]*(hi-10)/22); }
  c.putImageData(data,0,0); _wallObj2DImg[imageName]=cv; return cv;
}

// Rotação de objetos (decorações): facing → ângulo. O facing canônico [0,1] é 0°;
// cada giro de 90° avança no sentido [0,1]→[1,0]→[0,-1]→[-1,0]. Usado no 2D (canvas)
// e no 3D (rotation.y), para a imagem do objeto realmente girar.
const DECOR_FACING_OFFSETS = Object.freeze({
  prisao: Math.PI,
  estante_livros: Math.PI,
  fonte_de_parede: Math.PI,
  'fonte_de_parede.png': Math.PI,
  'fontedecanto.png': Math.PI,
});
function _decorFacingOffset(type, imageName, glbPath){
  if (DECOR_FACING_OFFSETS[type] !== undefined) return DECOR_FACING_OFFSETS[type];
  if (DECOR_FACING_OFFSETS[imageName] !== undefined) return DECOR_FACING_OFFSETS[imageName];
  const file = (glbPath || '').split('/').pop();
  return DECOR_FACING_OFFSETS[file ? file.replace(/\.glb$/, '') : ''] || 0;
}
function _facingAngle2D(f, type, imageName){
  let angle = 0;
  if(f && f[0]===1  && f[1]===0)  angle = Math.PI/2;
  else if(f && f[0]===0  && f[1]===-1) angle = Math.PI;
  else if(f && f[0]===-1 && f[1]===0)  angle = -Math.PI/2;
  return angle + _decorFacingOffset(type, imageName);
}
function _facingAngleY3D(f, type, imageName, glbPath){
  // Eixo Y do mundo 3D: sinal oposto ao 2D para o giro casar visualmente com o topo.
  let angle = 0;
  if(f && f[0]===1  && f[1]===0)  angle = -Math.PI/2;
  else if(f && f[0]===0  && f[1]===-1) angle = Math.PI;
  else if(f && f[0]===-1 && f[1]===0)  angle = Math.PI/2;
  return angle + _decorFacingOffset(type, imageName, glbPath);
}

// Visibilidade de uma armadilha colocável para o jogador local:
//  • aliada (colocada por um jogador): visível a todos (para não pisarem);
//  • so_luccas (oculta de masmorra/kobold): só o Luccas (rogue) enxerga;
//  • hostil autorada: ESCONDIDA até ser revelada (detecção do Luccas/Clarividência →
//    visivel) ou disparada (ativada). Antes disso não aparece no mapa.
function _armadilhaVisivelParaMim(arm, me){
  if(GS.isMaster()) return true;   // o mestre enxerga TODA a masmorra, incl. armadilhas ocultas
  if(arm.aliada) return true;
  if(arm.so_luccas) return !!(me && me.class_id === 'rogue');
  return !!(arm.visivel || arm.ativada);
}
// Cache 2D do PNG de uma armadilha (mesma pasta dos objetos de decoração).
function _getArmadilha2DImg(imageName){ return _getObjeto2DImg(imageName); }

// Escala da miniatura por PORTE (categoria de tamanho da ficha do monstro, vinda
// do servidor em m.porte). Guia a geração do sprite no 2D e no 3D. Ausente/
// desconhecido = "medio" (1.0). Ex.: kobolds são "pequeno".
const _PORTE_FATOR = { minusculo: 0.5, pequeno: 0.68, medio: 1.0, grande: 1.35, enorme: 1.7 };
function _pawnScaleFactor(porte){
  return _PORTE_FATOR[porte] || 1.0;
}

// Pombo e rato são formas MINÚSCULAS de ND 0: sua arte deve ocupar só cerca
// de um terço do quadrado, mesmo com o enquadramento normal dos GLBs de
// monstros. O gato usa uma escala própria, ligeiramente maior que a do pombo;
// a ovelha (médio) usa o enquadramento comum.
const _TINY_3D_PAWNS = new Set(['pombo', 'rato']);
const _TINY_3D_PAWN_FRAC = 0.34;
// O rato da Metamorfose deve ter presença visual semelhante à do pombo.
const _RATO_3D_PAWN_FRAC = _TINY_3D_PAWN_FRAC;
const _GATO_3D_PAWN_FRAC = 0.40;
// A ovelha é uma forma média, mas o modelo é largo; reduzimos um pouco o
// enquadramento para ela não dominar visualmente o quadrado.
const _OVELHA_3D_PAWN_FRAC = 1.20;

// Minis cujo PNG já traz a criatura enrolada sobre um pedestal redondo (cobras).
// Diferente das figuras "altas, pés na base", elas devem caber INTEIRAS no tile
// (largura E altura ≤ 1 quadrado), sem estourar para os tiles vizinhos. Tratadas
// à parte no 2D (drawMonsterSprite) e no 3D (_makeMonsterBillboard). Chaveadas
// pelo nome da imagem (m.image). _FIT_TILE_FRAC = lado-alvo como fração do tile.
const _FIT_TILE_PAWNS = new Set(['cobraConstritora', 'cobraVenenosa']);
const _FIT_TILE_FRAC  = 0.94;

// Minis grandes e largas (ogros) que devem PREENCHER a largura do tile (borda a
// borda) sem invadir os vizinhos: largura = _FILL_WIDTH_FRAC do tile; a altura
// segue a proporção real da arte (sem cap → mini imponente, bem maior em volume
// que as dos heróis), ancorada na base. Tratadas no 2D e no 3D, por m.image.
const _FILL_WIDTH_PAWNS = new Set(['ogroClava', 'ogroLanca']);
const _FILL_WIDTH_FRAC  = 0.98;

// Tom de estátua do status "petrificado". O tom mora em VC.feedback.petrificacao
// (fonte única com o material de pedra do 3D); aqui ele vira filtro de canvas.
// É função, e não const de módulo, porque o VC é lido no momento do desenho.
function _petrificadoFiltro2D(){
  return VC.feedback?.petrificacao?.filtro2D ?? 'grayscale(1) sepia(0.60) brightness(0.88)';
}

function drawHeroSprite(ctx, cx, cy, classId, color, isMe, isCur, petrificado=false, facing=null, extraRotation=0){
  ctx.save(); ctx.translate(cx,cy);
  const r=CELL/2-2;
  // Drop shadow (ellipse at feet)
  ctx.fillStyle='rgba(0,0,0,0.48)';
  ctx.beginPath(); ctx.ellipse(0,r*0.78,r*0.65,r*0.22,0,0,Math.PI*2); ctx.fill();
  // Active glow ring
  if(isCur){
    ctx.save(); ctx.shadowColor=color; ctx.shadowBlur=22;
    ctx.strokeStyle=color+'cc'; ctx.lineWidth=2.5;
    ctx.beginPath(); ctx.arc(0,-2,r+5,0,Math.PI*2); ctx.stroke(); ctx.restore();
  }
  // As PNGs dos heróis têm a frente voltada para Sul no mapa 2D, mesma
  // convenção do peão 3D. Gira somente o corpo: sombra, aro e identificação
  // permanecem legíveis e independentes da direção do ataque.
  ctx.save();
  ctx.rotate(_facingAngle2D(facing) + (Number(extraRotation) || 0));
  if(petrificado) ctx.filter=_petrificadoFiltro2D();
  // Class sprite — usa a miniatura PNG (frente.png), igual ao 3D; enquanto a
  // imagem não carrega, cai no sprite procedural (drawWarrior, …).
  const heroImg = _getHero2DImg(classId);
  if(heroImg && heroImg.complete && heroImg.naturalWidth){
    const feetY = r*0.82;                  // pés logo acima da sombra
    let h = CELL*1.55;                      // altura alvo (mini mais alta que o tile)
    let w = h * (heroImg.naturalWidth / heroImg.naturalHeight);
    const wMax = CELL*1.28;                 // limita largura (ex.: anão com machado+escudo)
    if(w > wMax){ h *= wMax/w; w = wMax; }
    ctx.drawImage(heroImg, -w/2, feetY - h, w, h);
  } else {
    ctx.save();
    ctx.scale(SPR_SCALE, SPR_SCALE);
    ctx.textAlign='center'; ctx.textBaseline='middle';
    switch(classId){
      case 'warrior': drawWarrior(ctx,color); break;
      case 'mage':    drawMage(ctx,color); break;
      case 'rogue':   drawRogue(ctx,color); break;
      case 'cleric':  drawCleric(ctx,color); break;
      case 'paladin': drawPaladin(ctx,color); break;
      case 'bard':    drawBard(ctx,color);   break;
      default:
        ctx.fillStyle=color; ctx.beginPath(); ctx.arc(0,0,r/SPR_SCALE,0,Math.PI*2); ctx.fill();
    }
    ctx.restore();
  }
  ctx.restore();
  // Gold ring for me
  if(isMe){
    ctx.strokeStyle='#f0c040'; ctx.lineWidth=2.5;
    ctx.beginPath(); ctx.arc(0,-2,r+2,0,Math.PI*2); ctx.stroke();
  }
  // Name tag
  if(isMe||isCur){
    const tagFs=Math.round(CELL*0.14); ctx.font=`bold ${tagFs}px monospace`; ctx.textAlign='center';
    // (name drawn in renderMap loop below)
  }
  ctx.restore();
}

// Footprint visual do monstro. O servidor mantém m.pos como a casa-âncora
// (frente, nos monstros orientados), mas a arte deve ser desenhada no centro
// geométrico de todas as casas ocupadas.
function _monsterFootprintSize(m){
  const raw = Array.isArray(m?.size) ? m.size : [1, 1];
  const w = Math.max(1, Math.min(4, Number(raw[0]) || 1));
  const h = Math.max(1, Math.min(4, Number(raw[1]) || 1));
  if(m?.oriented){
    // A âncora é a primeira fileira da frente. [N,1] é o formato legado
    // longitudinal; [W,H] usa W faixas laterais e H fileiras para trás.
    const width = h === 1 ? 1 : w;
    const length = h === 1 ? w : h;
    const f = Array.isArray(m.facing) && m.facing.length === 2 ? m.facing : [-1, 0];
    const horizontal = f[0] !== 0;
    return { w: horizontal ? length : width, h: horizontal ? width : length,
      logicalW: horizontal ? length : width, logicalH: horizontal ? width : length,
      naturalW:w, naturalH:h, width, length };
  }
  return { w, h, logicalW:w, logicalH:h, naturalW:w, naturalH:h, width:w, length:h };
}

function _monsterVisualCenterOffset(m){
  const fp = _monsterFootprintSize(m);
  if(!m?.oriented){ return [(fp.logicalW - 1) / 2, (fp.logicalH - 1) / 2]; }
  const length = fp.length;
  const width  = fp.width;
  const f = Array.isArray(m.facing) && m.facing.length === 2 ? m.facing : [-1, 0];
  const px = -f[1], py = f[0];
  return [
    -f[0] * (length - 1) / 2 + px * (width - 1) / 2,
    -f[1] * (length - 1) / 2 + py * (width - 1) / 2,
  ];
}

function _monsterIs2x2(m){
  const fp = _monsterFootprintSize(m);
  return fp.logicalW === 2 && fp.logicalH === 2;
}

// Monstro ORIENTADO de 2 casas (croc/lagarto), EM PÉ cobrindo as duas casas.
// A BASE alongada (no eixo cabeça→cauda) indica a direção; a criatura fica ereta
// na orientação natural da arte (cabeça à ESQUERDA) e é espelhada quando encara
// leste. Norte/sul ficam em pé centralizados — a base mostra a direção. hcx,hcy =
// centro de tela da casa-cabeça (frente = m.pos).
function drawOrientedMonster2D(ctx, m, hcx, hcy, attackTargeted=false){
  const f = m.facing || [-1,0];
  const [offX, offY] = _monsterVisualCenterOffset(m);
  // Centro geométrico do footprint (inclui a segunda linha do 2x2).
  const mcx = hcx + offX*CELL, mcy = hcy + offY*CELL;
  const fp = _monsterFootprintSize(m);
  const is2x2 = _monsterIs2x2(m);
  const isWideOriented = !!m?.oriented && fp.width > 1;
  // Ângulo da BASE (segue o eixo do corpo, indicando a direção).
  const angBase = (f[0]===1) ? Math.PI : (f[1]===-1) ? Math.PI/2 : (f[1]===1) ? -Math.PI/2 : 0;
  // A mira do joystick realça a própria criatura sem mudar sua posição lógica.
  const attackScale = attackTargeted ? 1.05 : 1;
  const attackLift = attackTargeted ? CELL * .055 : 0;
  ctx.save(); ctx.translate(mcx, mcy - attackLift); ctx.scale(attackScale, attackScale); ctx.rotate(angBase);
  const baseLongRadius = is2x2 ? 0.86 : (isWideOriented ? fp.length * 0.46 : 0.95);
  const baseWidthRadius = is2x2 ? 0.72 : (isWideOriented ? fp.width * 0.42 : 0.40);
  ctx.fillStyle='rgba(0,0,0,0.40)';
  ctx.beginPath(); ctx.ellipse(0, 0, CELL*baseLongRadius, CELL*baseWidthRadius, 0, 0, Math.PI*2); ctx.fill();
  ctx.fillStyle='#2a241c';
  ctx.beginPath(); ctx.ellipse(0, 0, CELL*(is2x2 ? 0.82 : (isWideOriented ? fp.length * 0.43 : 0.90)), CELL*(is2x2 ? 0.68 : (isWideOriented ? fp.width * 0.38 : 0.36)), 0, 0, Math.PI*2); ctx.fill();
  ctx.strokeStyle='rgba(0,0,0,0.55)'; ctx.lineWidth=1.5; ctx.stroke();
  ctx.restore();
  // Criatura: a arte natural aponta para Oeste (a cabeça fica à esquerda),
  // portanto o mesmo ângulo usado pela base aponta corpo e frente para a casa
  // atacada. A rotação também cobre Norte/Sul, que antes permaneciam de lado.
  const imageName = _monsterImageName(m);
  const img = imageName ? _getMonster2DImg(imageName) : null;
  ctx.save(); ctx.translate(mcx, mcy - attackLift); ctx.scale(attackScale, attackScale);
  ctx.rotate(angBase);
  if(img && img.complete && img.naturalWidth){
    if(m.petrificado) ctx.filter=_petrificadoFiltro2D();
    const ar = img.naturalWidth/img.naturalHeight;
    const visualSpan = isWideOriented && !is2x2 ? Math.max(fp.w, fp.h) : 1;
    let w = CELL*(is2x2 ? 1.80 : (visualSpan > 1 ? visualSpan * 0.90 : 1.9)), h = w/ar;
    const hMax = CELL*(is2x2 ? 1.72 : (visualSpan > 1 ? visualSpan * 0.86 : 1.7));
    if(h > hMax){ h = hMax; w = h*ar; }
    ctx.drawImage(img, -w/2, CELL*(is2x2 ? 0.72 : 0.34) - h, w, h);
  } else {
    ctx.fillStyle='#3a2e1e'; ctx.font=`${CELL*0.7}px serif`;
    ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillText(m.emoji||'🦎',0,0);
  }
  ctx.restore();
}

// Indicadores de dano contínuo no canto superior direito da casa.
// (X,Y) = canto superior esquerdo da casa em pixels.
function _drawStatusIcons2D(ctx, X, Y, entity){
  const fs = Math.round(CELL*0.34);
  ctx.save();
  ctx.font = `${fs}px serif`;
  ctx.textAlign = 'right'; ctx.textBaseline = 'top';
  let x = X + CELL - 1;
  const sangNivel = Math.max(0, Math.min(3, Number(entity.sangramento_nivel) || 0));
  if(sangNivel > 0){
    ctx.globalAlpha = 0.86 + 0.14*Math.abs(Math.sin(performance.now()/260));
    ctx.fillStyle = '#e62e42';
    ctx.fillText('🩸'.repeat(sangNivel), x, Y + 1);
    x -= fs * (0.72 * sangNivel);
  }
  if(entity.ferida_aberta){
    ctx.globalAlpha = 0.95;
    ctx.fillStyle = '#f0c36b';
    ctx.fillText('🩹', x, Y + 1);
    x -= fs * 0.72;
  }
  if(entity.hemorragia){
    ctx.globalAlpha = 0.90 + 0.10*Math.abs(Math.sin(performance.now()/150));
    ctx.fillStyle = '#ff2038';
    ctx.fillText('⚠️', x, Y + 1);
    x -= fs * 0.72;
  }
  if(entity.em_chamas_rodadas > 0){
    ctx.globalAlpha = 0.74 + 0.26*Math.abs(Math.sin(performance.now()/170));
    ctx.fillText('🔥', x, Y + 1);
    x -= fs * 0.72;
  }
  const drops = [
    [entity.acido_residual > 0, '#55df74'],
    [Array.isArray(entity.efeitos_veneno) && entity.efeitos_veneno.length > 0, '#a85cff'],
  ];
  for(const [active, color] of drops){
    if(!active) continue;
    ctx.globalAlpha = 0.95;
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(x - fs*0.20, Y + fs*0.05);
    ctx.bezierCurveTo(x - fs*0.38, Y + fs*0.32, x - fs*0.38, Y + fs*0.58, x - fs*0.20, Y + fs*0.68);
    ctx.bezierCurveTo(x, Y + fs*0.58, x, Y + fs*0.32, x - fs*0.20, Y + fs*0.05);
    ctx.fill();
    x -= fs * 0.70;
  }
  // Contadores persistentes ficam junto da miniatura, enquanto o efeito
  // pulsante é reservado ao instante em que a condição foi aplicada.
  const poisonRounds = Array.isArray(entity.efeitos_veneno)
    ? Math.max(0, ...entity.efeitos_veneno.map(e => Number(e?.duracao || e?.rodadas || 0))) : 0;
  const durations = [];
  if(entity.dormindo && Number(entity.dormindo_rodadas) > 0)
    durations.push([t('ui.tabuleiro.sono'), Number(entity.dormindo_rodadas), '#b99cff']);
  if(poisonRounds > 0)
    durations.push([t('ui.tabuleiro.veneno'), poisonRounds, '#d18aff']);
  if(Number(entity.paralisado_rodadas) > 0)
    durations.push([t('ui.tabuleiro.paralisia'), Number(entity.paralisado_rodadas), '#75d7ff']);
  if(Number(entity.cego_rodadas) > 0)
    durations.push([t('ui.tabuleiro.cegueira'), Number(entity.cego_rodadas), '#d5d5d5']);
  if(Number(entity.petrificacao_marcas) > 0)
    durations.push([t('ui.tabuleiro.petrificacao'), `${Math.min(3, Number(entity.petrificacao_marcas))}/3`, '#c8c8c8']);
  if(durations.length){
    const small = Math.max(9, Math.round(CELL * 0.115));
    ctx.font = `900 ${small}px Arial, sans-serif`;
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    let by = Y + CELL * 0.075;
    for(const [label, rounds, color] of durations){
      const text = `${label} ${rounds} rodadas`;
      const width = ctx.measureText(text).width + 8;
      ctx.fillStyle = 'rgba(9,5,18,0.82)';
      ctx.strokeStyle = color; ctx.lineWidth = 1.2;
      ctx.beginPath(); ctx.roundRect(X + CELL/2 - width/2, by, width, small + 5, 4); ctx.fill(); ctx.stroke();
      ctx.fillStyle = color; ctx.fillText(text, X + CELL/2, by + (small + 5)/2);
      by += small + 7;
    }
  }
  ctx.restore();
}

function _drawProvocacaoBadge2D(ctx, cx, cy, footprint, now){
  const altura = CELL * (1.10 + Math.max(0, (footprint?.logicalH || 1) - 1) * 0.62);
  const y = cy - altura + Math.sin(now / 250) * CELL * 0.025;
  const r = Math.max(11, CELL * 0.21);
  const pulse = 0.78 + 0.22 * (0.5 + 0.5 * Math.sin(now / 180));
  ctx.save();
  ctx.globalAlpha = pulse;
  ctx.beginPath(); ctx.arc(cx, y, r, 0, Math.PI * 2);
  ctx.fillStyle = 'rgba(45,8,8,0.92)'; ctx.fill();
  ctx.lineWidth = Math.max(1.5, CELL * 0.035);
  ctx.strokeStyle = '#ff6254'; ctx.shadowColor = '#ff3024'; ctx.shadowBlur = CELL * 0.18; ctx.stroke();
  ctx.font = `${Math.max(18, CELL * 0.37)}px serif`;
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.shadowColor = '#ff3024'; ctx.shadowBlur = CELL * 0.10;
  ctx.fillText('😠', cx, y + 1);
  ctx.restore();
}

function drawMonsterSprite(ctx, cx, cy, m, attackTargeted=false){
  ctx.save(); ctx.translate(cx,cy);
  const r=CELL/2-3;
  const _mfp = _monsterFootprintSize(m);
  const _m2x2 = _monsterIs2x2(m);
  // Escala por instância definida no editor; não muda a casa nem a colisão.
  const _mvs = Array.isArray(m.vscale) ? m.vscale : [1, 1];
  const _msx = Math.max(0.2, Math.min(4, Number(_mvs[0]) || 1));
  const _msy = Math.max(0.2, Math.min(4, Number(_mvs[1]) || 1));
  // Mantém os pés na base da miniatura ao crescer para cima.
  const attackScale = attackTargeted ? 1.05 : 1;
  const attackLift = attackTargeted ? CELL * .055 : 0;
  ctx.translate(0, -attackLift);
  ctx.translate(0, r * 0.82); ctx.scale(_msx * attackScale, _msy * attackScale); ctx.translate(0, -r * 0.82);
  // A frente natural das miniaturas comuns aponta para Sul no mapa 2D. Gira o
  // peão inteiro para que ataques laterais também mostrem a frente correta.
  const _facing2D = Array.isArray(m.facing) ? m.facing : null;
  ctx.rotate(_facingAngle2D(_facing2D));
  // Drop shadow
  ctx.fillStyle='rgba(0,0,0,0.45)';
  ctx.beginPath(); ctx.ellipse(0,r*0.78,r*0.65,r*0.22,0,0,Math.PI*2); ctx.fill();
  // Red ambient glow
  ctx.save(); ctx.shadowColor='#c01010'; ctx.shadowBlur=16;
  ctx.strokeStyle='rgba(200,30,30,0.40)'; ctx.lineWidth=2.5;
  ctx.beginPath(); ctx.arc(0,0,r+4,0,Math.PI*2); ctx.stroke(); ctx.restore();

  // Billboard PNG (assets/pawns/monstros/<image>) — igual aos heróis: alto, pés
  // na base, SEM recorte circular. Sem imagem (ex.: servos animados) → procedural.
  const imageName = _monsterImageName(m);
  const mImg = imageName ? _getMonster2DImg(imageName) : null;
  if(m.petrificado) ctx.filter=_petrificadoFiltro2D();
  if(mImg && mImg.complete && mImg.naturalWidth){
    const ar = mImg.naturalWidth / mImg.naturalHeight;
    if(_m2x2){
      // A âncora 2x2 fica no canto do footprint; o renderer chama esta
      // função já no centro geométrico. Ajusta a arte ao retângulo inteiro,
      // respeitando a proporção do PNG e o vscale definido no editor.
      const maxW = CELL * _mfp.logicalW * 0.92;
      const maxH = CELL * _mfp.logicalH * 0.92;
      let w = maxW, h = w / ar;
      if(h > maxH){ h = maxH; w = h * ar; }
      const feetY = CELL * _mfp.logicalH / 2;
      ctx.drawImage(mImg, -w/2, feetY - h, w, h);
    } else if(_FIT_TILE_PAWNS.has(imageName)){
      // Cobra + pedestal cabem INTEIROS no quadrado: largura e altura ≤ tile.
      // Ancorada na base (perto da sombra), sem ultrapassar o topo do tile.
      const alvo = CELL*_FIT_TILE_FRAC;
      let w = alvo, h = alvo;
      if(ar >= 1) h = alvo/ar; else w = alvo*ar;
      const bottomY = CELL*0.47;            // base assenta perto da borda inferior
      ctx.drawImage(mImg, -w/2, bottomY - h, w, h);
    } else if(_FILL_WIDTH_PAWNS.has(imageName)){
      // Ogro: preenche a LARGURA do quadrado (sem invadir vizinhos); a altura
      // segue a proporção (mini imponente). Ancorado na base, como os demais.
      const feetY = r*0.82;
      const w = CELL*_FILL_WIDTH_FRAC;
      const h = w/ar;
      ctx.drawImage(mImg, -w/2, feetY - h, w, h);
    } else {
      const feetY = r*0.82;
      const sf = _pawnScaleFactor(m.porte);  // porte da ficha (kobolds = pequeno)
      let h = CELL*1.55*sf;
      let w = h * ar;
      const wMax = CELL*1.5*sf;              // criaturas largas (aranha, lobo) podem ser largas
      if(w > wMax){ h *= wMax/w; w = wMax; }
      ctx.drawImage(mImg, -w/2, feetY - h, w, h);
    }
  } else {
    // Clip to circle + sprite procedural
    ctx.save(); ctx.beginPath(); ctx.arc(0,0,r+2,0,Math.PI*2); ctx.clip();
    ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.scale(SPR_SCALE, SPR_SCALE);
    switch(m.type){
      case 'goblin':    drawGoblin(ctx); break;
      case 'skeleton':  drawSkeleton(ctx); break;
      case 'orc':       drawOrc(ctx); break;
      case 'dark_mage': drawDarkMage(ctx); break;
      case 'troll':     drawTroll(ctx); break;
      case 'dragon':    drawDragon(ctx); break;
      default:
        ctx.fillStyle='#2a0808'; ctx.beginPath(); ctx.arc(0,0,r/SPR_SCALE,0,Math.PI*2); ctx.fill();
        ctx.font=`${(CELL-14)/SPR_SCALE}px serif`; ctx.fillText(m.emoji,0,0);
    }
    ctx.restore();
  }
  ctx.restore();
}

// ══ END SPRITE ENGINE ═══════════════════════════════════════════════════════

// ══ 3D DIORAMA MAP ═══════════════════════════════════════════════════════════

const WALL_RISE = Math.round(CELL * 0.50); // visible wall-face height — taller = more 3D depth
// Escala visual da altura autoritativa: cada ponto de voo sobe um pouco acima
// do piso, mantendo a sombra/base no tabuleiro para que a posição continue legível.
const FLIGHT_ALTITUDE_STEP = 0.24;
const FLIGHT_FALL_DURATION_MS = 760;
const FLIGHT_FALL_IMPACT_MS = 680;
const _flightFallAnims = [];

function _flightFallFigure(targetId){
  if(!g3?.entityGroup || targetId == null) return null;
  const wanted = String(targetId);
  return g3.entityGroup.children.find(fig => {
    const u = fig.userData || {};
    return [u.pid, u.monId, u.animadoId].some(id => id != null && String(id) === wanted)
      || (u.prisoner && wanted === 'prisoner');
  }) || null;
}

function _buildFlightFallImpact3D(anim){
  if(!g3?.scene || !window.THREE || anim.impactGroup) return;
  const T = g3.T;
  const group = new T.Group();
  group.name = 'flight-fall-impact';
  const figure = _flightFallFigure(anim.targetId);
  group.position.set(figure?.position.x ?? anim.pos[0], 0,
    figure?.position.z ?? anim.pos[1]);

  const ringMat = new T.MeshBasicMaterial({
    color: 0xffb45b, transparent: true, opacity: 0,
    depthWrite: false, depthTest: false,
  });
  const ring = new T.Mesh(new T.TorusGeometry(.18, .026, 8, 32), ringMat);
  ring.rotation.x = Math.PI / 2;
  ring.position.y = .285;
  ring.renderOrder = 124;
  group.add(ring);

  const dustMat = new T.MeshBasicMaterial({
    color: 0xd9b58a, transparent: true, opacity: 0,
    depthWrite: false, depthTest: false,
  });
  const particles = [];
  for(let i = 0; i < 12; i++){
    const particle = new T.Mesh(new T.SphereGeometry(.035 + (i % 3) * .012, 6, 5), dustMat);
    particle.userData.fallAngle = i * Math.PI * 2 / 12;
    particle.userData.fallPhase = (i * 17) % 11 / 11;
    particle.position.y = .285;
    group.add(particle);
    particles.push(particle);
  }
  g3.scene.add(group);
  anim.impactGroup = group;
  anim.impactRing = ring;
  anim.impactParticles = particles;
  anim.impactRingMat = ringMat;
  anim.impactDustMat = dustMat;
}

function _disposeFlightFallImpact3D(anim){
  if(!anim?.impactGroup) return;
  if(anim.impactGroup.parent) anim.impactGroup.parent.remove(anim.impactGroup);
  anim.impactGroup.traverse(obj => { if(obj.geometry) obj.geometry.dispose(); });
  anim.impactRingMat?.dispose();
  anim.impactDustMat?.dispose();
  anim.impactGroup = null;
}

function _updateFlightFallAnimations3D(now){
  for(let i = _flightFallAnims.length - 1; i >= 0; i--){
    const anim = _flightFallAnims[i];
    const elapsed = now - anim.start;
    const p = Math.max(0, Math.min(1, elapsed / anim.duration));
    const fig = _flightFallFigure(anim.targetId);
    const body = fig?.userData?.flightBody;
    if(body){
      if(anim.body !== body){
        anim.body = body;
        anim.baseRotationX = body.rotation.x || 0;
        anim.baseRotationZ = body.rotation.z || 0;
      }
      // Começa controlada e acelera perto do impacto, como uma queda real.
      const heightFactor = 1 - p * p;
      body.position.y = anim.fromAltitude * FLIGHT_ALTITUDE_STEP * heightFactor;
      const wobble = Math.sin(p * Math.PI * 3.2 + anim.seed) * .13 * Math.sin(p * Math.PI);
      body.rotation.x = anim.baseRotationX + wobble * .42;
      body.rotation.z = anim.baseRotationZ + wobble;
      if(p >= 1){
        body.position.y = 0;
        body.rotation.x = anim.baseRotationX;
        body.rotation.z = anim.baseRotationZ;
      }
    }

    if(elapsed >= anim.duration && elapsed <= anim.duration + FLIGHT_FALL_IMPACT_MS){
      if(anim.impactGroup && anim.impactGroup.parent !== g3?.scene)
        _disposeFlightFallImpact3D(anim);
      if(!anim.impactGroup) _buildFlightFallImpact3D(anim);
      if(anim.impactGroup){
        if(fig) anim.impactGroup.position.set(fig.position.x, 0, fig.position.z);
        const q = Math.max(0, Math.min(1, (elapsed - anim.duration) / FLIGHT_FALL_IMPACT_MS));
        const pulse = Math.sin(Math.PI * q);
        anim.impactRing.scale.setScalar(.8 + q * 2.15);
        anim.impactRing.material.opacity = .88 * (1 - q) * (.72 + pulse * .28);
        for(const particle of anim.impactParticles){
          const angle = particle.userData.fallAngle;
          const radius = .08 + q * (.42 + particle.userData.fallPhase * .24);
          particle.position.set(Math.cos(angle) * radius,
            .29 + q * (.12 + particle.userData.fallPhase * .22),
            Math.sin(angle) * radius);
          particle.material.opacity = .68 * (1 - q);
        }
      }
    }

    if(elapsed > anim.duration + FLIGHT_FALL_IMPACT_MS){
      _disposeFlightFallImpact3D(anim);
      _flightFallAnims.splice(i, 1);
    }
  }
}

function _receiveFlightFall(msg){
  if(!msg || msg.target_id == null || !Array.isArray(msg.pos)) return;
  const fromAltitude = Math.max(0, Math.min(10, Math.trunc(Number(msg.altura) || 0)));
  if(fromAltitude <= 0) return;
  for(let i = _flightFallAnims.length - 1; i >= 0; i--){
    if(String(_flightFallAnims[i].targetId) !== String(msg.target_id)) continue;
    _disposeFlightFallImpact3D(_flightFallAnims[i]);
    _flightFallAnims.splice(i, 1);
  }
  _flightFallAnims.push({
    targetId: msg.target_id,
    pos: [Number(msg.pos[0]) || 0, Number(msg.pos[1]) || 0],
    fromAltitude,
    start: performance.now(),
    duration: FLIGHT_FALL_DURATION_MS,
    seed: Math.random() * Math.PI * 2,
    body: null,
    impactGroup: null,
  });
  if(mode3D && g3) _updateFlightFallAnimations3D(performance.now());
}

// ── Vision set: tiles currently visible to the local player ──────────────────
// Enemies outside this set are hidden (fog of war). Floor/walls keep using
// exploredSet so already-discovered tiles remain permanently visible.
// Uses Chebyshev distance (max of |dx|, |dy|) — square radius = torch lantern.
// Raio de detecção (Chebyshev) do jogador local: base 6 + bônus de Visão do
// Guerreiro da Luz (Richard). Espelha _get_raio_visao(p) no servidor (base 3),
// mas aqui a base é maior pois governa a visibilidade AO VIVO de inimigos.
function getSightRadius(me){
  return obterRaioVisaoCliente(me);
}

function computeVisionSet(state, me){
  const set = new Set();
  // Tiles revelados por magia (Clarividência) são visíveis ao vivo — mesmo
  // longe e através de portas fechadas — para mostrar o conteúdo da sala.
  if(state && state.revealed)
    for(const [rx,ry] of state.revealed) set.add(`${rx},${ry}`);
  // Mestre: sem névoa de guerra — enxerga todo o terreno já conhecido pelo
  // grupo (state.explored) e a posição de TODOS os monstros vivos, mesmo em
  // salas que os heróis ainda não exploraram (visão total do Mestre). O
  // Mestre não tem `me` (não é um herói em state.players), então sem este
  // ramo cairia no `if(!me) return set` logo abaixo e ficaria com a mesma
  // névoa total de um herói recém-chegado.
  if(GS.isMaster() || (state && state.test_mode)){
    if(state && state.explored) for(const [ex,ey] of state.explored) set.add(`${ex},${ey}`);
    if(state && state.monsters) for(const m of state.monsters) if(m && m.pos) set.add(`${m.pos[0]},${m.pos[1]}`);
    return set;
  }
  if(!me) return set;
  const [px,py] = me.pos;
  const SIGHT   = getSightRadius(me);   // dinâmico: 6, 7 ou 8 conforme o bônus de Richard
  for(const [ex,ey] of state.explored){
    if(Math.max(Math.abs(ex-px), Math.abs(ey-py)) <= SIGHT
        && GS.hasLineOfSight(state, px, py, ex, ey))
      set.add(`${ex},${ey}`);
  }
  return set;
}

function _alvoNoAlcanceArmaClient(me, tx, ty, targetAltitude = 0) {
  return GS.weaponCanReachTile(me, tx, ty, targetAltitude);
}

function _computeWeaponRangeTiles(state, me) {
  const tiles = state.tiles;
  const H = tiles.length, W = tiles[0].length;
  const [px, py] = me.pos;
  const wRng = me.weapon?.range ?? null;
  const exploredSet = new Set(state.explored.map(([x,y])=>`${x},${y}`));
  const result = new Set();
  for(let y = 0; y < H; y++) for(let x = 0; x < W; x++) {
    if(tiles[y][x] !== TILE_FLOOR) continue;
    if(!exploredSet.has(`${x},${y}`)) continue;
    const dx = Math.abs(px - x), dy = Math.abs(py - y);
    if(dx === 0 && dy === 0) continue;
    const inR = _alvoNoAlcanceArmaClient(me, x, y)
      && (me.weapon?.range != null || GS.hasLineOfSight(state, px, py, x, y));
    if(inR) result.add(`${x},${y}`);
  }
  return result;
}

// Área visual das técnicas de giro. A resolução autoritativa em server.py
// varre somente os quatro quadrados ortogonais adjacentes; armas de alcance
// (lança/alabarda/chicote) continuam usando esse mesmo anel, enquanto armas
// de projétil não podem usar a técnica. O cliente apenas antecipa essa área
// para o jogador — nenhum alvo ou dano é decidido aqui.
function _armaDistanciaAtaqueGiratorio(me){
  const weapon = me?.weapon || {};
  const weaponId = String(weapon.id || '').toLowerCase();
  const rangedIds = new Set(['arco_curto', 'longbow', 'besta', 'hand_crossbow', 'besta_mao', 'besta_leve', 'arco_longo']);
  return Boolean(rangedIds.has(weaponId) || weapon.projectile || weapon.ammo || weapon.ammo_type
    || weapon.tipo === 'armaDistancia' || weapon.tipo === 'ranged');
}

function _ataqueGiratorioPreviewTiles(state, me){
  const result = new Set();
  if(!state || !me?.pos || _armaDistanciaAtaqueGiratorio(me)) return result;
  const [px, py] = me.pos;
  const tiles = state.tiles || [];
  const H = tiles.length, W = tiles[0]?.length || 0;
  for(const [dx, dy] of [[1,0],[-1,0],[0,1],[0,-1]]){
    const x = px + dx, y = py + dy;
    if(x < 0 || y < 0 || x >= W || y >= H) continue;
    const tile = tiles[y]?.[x];
    if(tile === TILE_FLOOR || tile === TILE_DOOR) result.add(`${x},${y}`);
  }
  return result;
}

function _ativarPreviewAtaqueGiratorio(tid){
  window._ataqueGiratorioPreview = {tid: String(tid || '')};
}

function _limparPreviewAtaqueGiratorio(render = true){
  window._ataqueGiratorioPreview = null;
  if(render && GS.gameState) renderMap(GS.gameState);
}

// Camada estática do mapa 2D. Pisos, paredes, portas e névoa não mudam a cada
// quadro; renderizá-los novamente durante a animação da lava/pântano era o
// principal custo do loop. O canvas fora da tela preserva a mesma qualidade,
// enquanto o canvas visível recebe apenas os efeitos e entidades dinâmicas.
let _dungeonStatic2D = {
  canvas: null, tiles: null, materiais: null, elevacoes: null, transicao: null, explorado: null, revelado: null,
  rooms: null, secretPassages: null, animatedTiles: [], master: null, W: 0, H: 0,
};

function _collectWhirlpoolAreas(state, terrainSet){
  const mats = state.materiais || {};
  const cells = new Set(Object.entries(mats)
    .filter(([key, mid]) => (mid === 'rodamoinho' || mid === 'rodamoinho_profundo')
      && (!terrainSet || terrainSet.has(key)))
    .map(([key]) => key));
  const seen = new Set();
  const areas = [];
  for(const start of cells){
    if(seen.has(start)) continue;
    const mid = mats[start], queue = [start], tiles = [];
    seen.add(start);
    for(let qi=0; qi<queue.length; qi++){
      const key = queue[qi], [x,y] = key.split(',').map(Number);
      tiles.push({x,y,key});
      for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){
        const next = `${x+dx},${y+dy}`;
        if(!seen.has(next) && cells.has(next) && mats[next] === mid){
          seen.add(next); queue.push(next);
        }
      }
    }
    areas.push({mid, tiles,
      x0: Math.min(...tiles.map(t => t.x)), x1: Math.max(...tiles.map(t => t.x)),
      y0: Math.min(...tiles.map(t => t.y)), y1: Math.max(...tiles.map(t => t.y))});
  }
  return areas;
}

function _drawWhirlpoolArea2D(ctx, area, now){
  const x = area.x0 * CELL, y = area.y0 * CELL;
  const w = (area.x1 - area.x0 + 1) * CELL;
  const h = (area.y1 - area.y0 + 1) * CELL;
  const cx = x + w * .5, cy = y + h * .5;
  const deep = area.mid === 'rodamoinho_profundo';
  const flow = now / 115;
  ctx.save();
  ctx.beginPath(); ctx.rect(x + 1, y + 1, w - 2, h - 2); ctx.clip();
  for(let i=0; i<8; i++){
    const rx = Math.max(CELL * .10, w * (.075 + i * .052));
    const ry = Math.max(CELL * .08, h * (.075 + i * .052)) * .70;
    ctx.strokeStyle = deep
      ? (i % 2 ? 'rgba(139,207,255,.50)' : 'rgba(45,117,224,.64)')
      : (i % 2 ? 'rgba(208,251,255,.68)' : 'rgba(61,190,239,.74)');
    ctx.lineWidth = Math.max(1, CELL * (i === 0 ? .026 : .014));
    ctx.beginPath();
    for(let a=.14; a<=Math.PI*2.1; a+=.09){
      const aa = a + flow * (i % 2 ? -1.10 : 1.24) + .12 * Math.sin(flow * 2.1 + i);
      const wobble = 1 + .14 * Math.sin(a * 4 + i) + .05 * Math.sin(a * 9 - flow * 1.5);
      const px = cx + Math.cos(aa) * rx * wobble;
      const py = cy + Math.sin(aa) * ry * wobble;
      if(a === .14) ctx.moveTo(px, py); else ctx.lineTo(px, py);
    }
    ctx.stroke();
  }
  const hole = ctx.createRadialGradient(cx, cy, 0, cx, cy, Math.min(w,h) * .25);
  hole.addColorStop(0, deep ? 'rgba(0,5,22,.90)' : 'rgba(2,32,83,.82)');
  hole.addColorStop(.64, deep ? 'rgba(3,31,91,.70)' : 'rgba(4,72,137,.56)');
  hole.addColorStop(1, deep ? 'rgba(14,75,151,0)' : 'rgba(4,115,183,0)');
  ctx.fillStyle = hole; ctx.beginPath();
  ctx.ellipse(cx, cy, Math.min(w,h)*.21, Math.min(w,h)*.15, 0, 0, Math.PI*2); ctx.fill();
  ctx.restore();
}

function _bridgeTiles2D(bridge){
  const a = bridge?.inicio || bridge?.start, b = bridge?.fim || bridge?.end;
  const width = Math.max(1, Math.min(3, Number(bridge?.largura ?? bridge?.width ?? 1) | 0));
  if(!Array.isArray(a) || !Array.isArray(b) || (a[0] !== b[0] && a[1] !== b[1])) return [];
  const out = [];
  if(a[1] === b[1]){
    const x0=Math.min(a[0],b[0]), x1=Math.max(a[0],b[0]), y0=a[1]-Math.floor(width/2);
    for(let y=y0;y<y0+width;y++) for(let x=x0;x<=x1;x++) out.push([x,y]);
  }else{
    const y0=Math.min(a[1],b[1]), y1=Math.max(a[1],b[1]), x0=a[0]-Math.floor(width/2);
    for(let x=x0;x<x0+width;x++) for(let y=y0;y<=y1;y++) out.push([x,y]);
  }
  return out;
}
function _drawBridges2D(ctx, state, terrainSet){
  for(const bridge of (state.pontes || [])){
    const tiles = _bridgeTiles2D(bridge);
    if(!tiles.length) continue;
    const horizontal = bridge.inicio[1] === bridge.fim[1];
    const minX=Math.min(...tiles.map(t=>t[0])), maxX=Math.max(...tiles.map(t=>t[0]));
    const minY=Math.min(...tiles.map(t=>t[1])), maxY=Math.max(...tiles.map(t=>t[1]));
    const visible = key => !terrainSet || terrainSet.has(key);
    const pedraRustica = String(bridge.material || 'madeira').toLowerCase() === 'pedra_rustica';
    const woodBase = pedraRustica ? 'rgba(50,47,43,.97)' : 'rgba(55,28,12,.95)';
    const woodDeck = pedraRustica ? 'rgba(123,113,101,.98)' : 'rgba(154,91,40,.96)';
    // Base contínua: duas longarinas longitudinais, como trilhos sob o deck.
    ctx.save();
    ctx.fillStyle=woodBase;
    if(horizontal){
      for(const yy of [minY*CELL+CELL*.18, (maxY+1)*CELL-CELL*.28])
        ctx.fillRect(minX*CELL+2, yy, (maxX-minX+1)*CELL-4, Math.max(3,CELL*.10));
    }else{
      for(const xx of [minX*CELL+CELL*.18, (maxX+1)*CELL-CELL*.28])
        ctx.fillRect(xx, minY*CELL+2, Math.max(3,CELL*.10), (maxY-minY+1)*CELL-4);
    }
    // Tábuas transversais, com intervalo discreto entre cada uma.
    const first = horizontal ? minX : minY, last = horizontal ? maxX : maxY;
    for(let step=first; step<=last; step++){
      const sampleKey = horizontal ? `${step},${Math.floor((minY+maxY)/2)}` : `${Math.floor((minX+maxX)/2)},${step}`;
      if(!visible(sampleKey)) continue;
      const pad=2, gap=Math.max(2,CELL*.055);
      ctx.fillStyle=woodDeck;
      if(horizontal) ctx.fillRect(step*CELL+pad, minY*CELL+pad, CELL-2*pad, (maxY-minY+1)*CELL-2*pad);
      else ctx.fillRect(minX*CELL+pad, step*CELL+pad, (maxX-minX+1)*CELL-2*pad, CELL-2*pad);
      ctx.strokeStyle = pedraRustica ? 'rgba(42,39,36,.94)' : 'rgba(64,31,12,.9)';
      ctx.lineWidth=Math.max(1,CELL*.035);
      ctx.strokeRect(
        horizontal ? step*CELL+gap : minX*CELL+gap,
        horizontal ? minY*CELL+gap : step*CELL+gap,
        horizontal ? CELL-2*gap : (maxX-minX+1)*CELL-2*gap,
        horizontal ? (maxY-minY+1)*CELL-2*gap : CELL-2*gap
      );
      ctx.strokeStyle = pedraRustica ? 'rgba(214,202,184,.24)' : 'rgba(224,157,78,.38)';
      ctx.lineWidth=1;
      ctx.beginPath();
      if(horizontal){
        const cx=step*CELL+CELL*.24;
        ctx.moveTo(cx,minY*CELL+5); ctx.lineTo(cx,(maxY+1)*CELL-5);
      }else{
        const cy=step*CELL+CELL*.24;
        ctx.moveTo(minX*CELL+5,cy); ctx.lineTo((maxX+1)*CELL-5,cy);
      }
      ctx.stroke();
    }
    ctx.restore();
  }
}

function _staticDungeon2D(state, terrainSet, doorClosed, W, H){
  const master = !!(GS.isMaster() || state.test_mode);
  const cache = _dungeonStatic2D;
  // _estadoComMortosVisuais pode criar uma cópia do estado por alguns frames;
  // comparar os arrays internos evita invalidar a camada por causa dessa cópia.
  const mesmaBase = cache.canvas && cache.tiles === state.tiles
    && cache.materiais === state.materiais
    && cache.elevacoes === state.elevacoes
    && cache.transicao === (state.transicao_altura || 'rampa')
    && cache.explorado === state.explored
    && cache.revelado === state.revealed
    && cache.rooms === state.rooms
    && cache.secretPassages === state.secret_passages
    && cache.pontes === state.pontes
    && cache.master === master && cache.W === W && cache.H === H;
  if(mesmaBase) return cache.canvas;

  const canvas = cache.canvas || document.createElement('canvas');
  applyDPR(canvas, W * CELL, H * CELL);
  const ctx = canvas.getContext('2d');
  const animatedTiles = [];
  for(const [key, mid] of Object.entries(state.materiais || {})){
    if(mid !== 'lava' && mid !== 'pantano' && mid !== 'agua' && mid !== 'agua_profunda'
        && mid !== 'rodamoinho' && mid !== 'rodamoinho_profundo'
        || !terrainSet.has(key)) continue;
    const [x, y] = key.split(',').map(Number);
    if(Number.isInteger(x) && Number.isInteger(y)) animatedTiles.push({x, y, mid});
  }
  ctx.fillStyle = '#040308';
  ctx.fillRect(0, 0, W * CELL, H * CELL);

  // Piso estático. Os realces de movimento/ataque ficam no primeiro plano.
  for(let y=0; y<H; y++) for(let x=0; x<W; x++){
    const key = `${x},${y}`;
    if(!terrainSet.has(key)) continue;
    const tile = state.tiles[y][x];
    if(tile !== TILE_FLOOR && tile !== TILE_DOOR) continue;
    const mid = matDaCasa(state, x, y);
    drawFloor3D(ctx, x, y, false, false, false, mid);
    drawElevacao2D(ctx, state, x, y);
    if(mid === 'entulho') drawEntulho2D(ctx, x, y);
  }

  // Faces e topos de paredes.
  for(let y=0; y<H; y++) for(let x=0; x<W; x++){
    const key = `${x},${y}`;
    if(!terrainSet.has(key) || state.tiles[y][x] !== TILE_WALL) continue;
    const sy = y + 1;
    if(sy < H && state.tiles[sy][x] === TILE_FLOOR && terrainSet.has(`${x},${sy}`))
      drawWallSouthFace(ctx, x, y, matDaCasa(state, x, y));
    drawWallTop3D(ctx, x, y, matDaCasa(state, x, y));
  }

  // Portas fazem parte da base, pois só mudam junto com um novo game_state.
  for(let y=0; y<H; y++) for(let x=0; x<W; x++){
    if(state.tiles[y][x] !== TILE_DOOR || !terrainSet.has(`${x},${y}`)) continue;
    drawDoor2D(ctx, state, x, y, doorClosed.has(`${x},${y}`));
  }

  // A ponte é uma superfície independente: sua madeira cobre visualmente o
  // piso/abismo inferior sem alterar tiles, materiais ou elevações.
  _drawBridges2D(ctx, state, terrainSet);

  // Névoa também é estática até a próxima atualização autoritativa.
  ctx.fillStyle = 'rgba(4,3,8,0.96)';
  for(let y=0; y<H; y++) for(let x=0; x<W; x++){
    if(!terrainSet.has(`${x},${y}`)) ctx.fillRect(x * CELL, y * CELL, CELL, CELL);
  }

  const whirlpoolAreas = _collectWhirlpoolAreas(state, terrainSet);
  const whirlpoolAreaByKey = {};
  for(const area of whirlpoolAreas) for(const tile of area.tiles)
    whirlpoolAreaByKey[tile.key] = area;
  _dungeonStatic2D = {
    canvas, tiles: state.tiles, materiais: state.materiais,
    elevacoes: state.elevacoes, transicao: state.transicao_altura || 'rampa',
    explorado: state.explored, revelado: state.revealed, rooms: state.rooms,
    secretPassages: state.secret_passages,
    pontes: state.pontes,
    animatedTiles, whirlpoolAreas, whirlpoolAreaByKey, master, W, H,
  };
  return canvas;
}

// Só os traços móveis de lava/água, os vortexes e as ondulações do pântano são recalculados.
// A pintura base permanece na camada estática acima.
function _drawAnimatedTerrain2D(ctx, state, terrainSet, now){
  const flowLava = now / 520;
  const flowWater = now / 680;
  const flowDeepWater = now / 1180;
  const flowSwamp = now / 900;
  const bridgeKeys = new Set();
  for(const bridge of (state.pontes || []))
    for(const [x, y] of _bridgeTiles2D(bridge)) bridgeKeys.add(`${x},${y}`);
  const tiles = _dungeonStatic2D.materiais === state.materiais
    ? _dungeonStatic2D.animatedTiles : [];
  const whirlpoolDrawn = new Set();
  for(const {x, y, mid} of tiles){
    // A ponte é a superfície superior; os efeitos animados do piso inferior
    // não devem ser desenhados por cima dela.
    if(bridgeKeys.has(`${x},${y}`)) continue;
    const X = x * CELL, Y = y * CELL;
    if(mid === 'lava'){
      for(let row=0; row<4; row++){
        const yy = Y + CELL * (.16 + row * .22)
          + Math.sin(flowLava + row * 1.7 + x * .35) * CELL * .035;
        ctx.strokeStyle = row % 2 ? 'rgba(255,184,48,.78)' : 'rgba(255,90,18,.70)';
        ctx.lineWidth = Math.max(1, CELL / 46);
        ctx.beginPath();
        ctx.moveTo(X - CELL * .08, yy);
        ctx.bezierCurveTo(X + CELL * .24, yy - CELL * .06,
          X + CELL * .54, yy + CELL * .06, X + CELL * 1.08, yy - CELL * .025);
        ctx.stroke();
      }
      const bubbles = _rng((x * 9199 ^ y * 3761 ^ 0xBABB1E) >>> 0);
      for(let i=0; i<2; i++){
        const bx = X + CELL * (.18 + bubbles() * .64);
        const by = Y + CELL * (.20 + bubbles() * .60);
        const q = .5 + .5 * Math.sin(flowLava * 1.7 + i * 2.4 + x * .6 + y * .35);
        const br = CELL * (.018 + bubbles() * .027) * (.72 + q * .42);
        ctx.fillStyle = `rgba(255,196,54,${(.30 + q * .34).toFixed(2)})`;
        ctx.beginPath(); ctx.arc(bx, by - q * CELL * .025, br, 0, Math.PI * 2); ctx.fill();
        ctx.strokeStyle = `rgba(255,116,18,${(.26 + q * .26).toFixed(2)})`;
        ctx.lineWidth = Math.max(1, CELL / 70); ctx.stroke();
      }
    } else if(mid === 'rodamoinho' || mid === 'rodamoinho_profundo'){
      const area = _dungeonStatic2D.whirlpoolAreaByKey
        && _dungeonStatic2D.whirlpoolAreaByKey[`${x},${y}`];
      if(area && !whirlpoolDrawn.has(area)){
        whirlpoolDrawn.add(area);
        _drawWhirlpoolArea2D(ctx, area, now);
      }
    } else if(mid === 'agua' || mid === 'agua_profunda'){
      const profunda = mid === 'agua_profunda';
      const flow = profunda ? flowDeepWater : flowWater;
      const waves = _rng((x * 7331 ^ y * 4129 ^ (profunda ? 0xD33F : 0xA91C)) >>> 0);
      for(let row=0; row<3; row++){
        const phase = flow + row * 1.8 + x * .21 + y * .13;
        const yy = Y + CELL * (.20 + row * .28)
          + Math.sin(phase) * CELL * (profunda ? .022 : .032);
        ctx.strokeStyle = profunda
          ? (row % 2 ? 'rgba(82,159,231,.22)' : 'rgba(28,91,171,.30)')
          : (row % 2 ? 'rgba(190,247,255,.46)' : 'rgba(62,188,240,.38)');
        ctx.lineWidth = Math.max(1, CELL / (profunda ? 60 : 52));
        ctx.beginPath();
        ctx.moveTo(X - CELL * .08, yy);
        ctx.bezierCurveTo(X + CELL * .20, yy - CELL * .045,
          X + CELL * .48, yy + CELL * .045, X + CELL * 1.08, yy);
        ctx.stroke();
      }
      for(let i=0; i<2; i++){
        const px = X + CELL * (.18 + waves() * .64);
        const py = Y + CELL * (.22 + waves() * .58);
        const q = .5 + .5 * Math.sin(flow * 1.35 + i * 2.7 + x * .37 + y * .29);
        const rx = CELL * (profunda ? .07 : .06) * (.75 + q * .38);
        const ry = rx * (profunda ? .34 : .28);
        ctx.strokeStyle = profunda
          ? `rgba(101,181,255,${(.13 + q * .13).toFixed(2)})`
          : `rgba(221,253,255,${(.24 + q * .22).toFixed(2)})`;
        ctx.lineWidth = Math.max(1, CELL / 76);
        ctx.beginPath();
        ctx.ellipse(px + Math.sin(flow + i) * CELL * .025,
          py + Math.cos(flow * .8 + i) * CELL * .018,
          rx, ry, Math.sin(flow + i) * .12, 0, Math.PI * 2);
        ctx.stroke();
      }
    } else {
      for(let row=0; row<2; row++){
        const phase = flowSwamp + row * 2.3 + x * .41 + y * .27;
        const cx = X + CELL * (.28 + row * .38) + Math.sin(phase) * CELL * .035;
        const cy = Y + CELL * (.34 + row * .29) + Math.cos(phase * .8) * CELL * .025;
        const rr = CELL * (.10 + row * .025);
        ctx.strokeStyle = row ? 'rgba(158,185,124,.24)' : 'rgba(101,139,91,.30)';
        ctx.lineWidth = Math.max(1, CELL / 72);
        ctx.beginPath();
        ctx.ellipse(cx, cy, rr * (.9 + .12 * Math.sin(phase)), rr * .34,
          Math.sin(phase) * .18, 0, Math.PI * 2);
        ctx.stroke();
      }
    }
  }
}

function _drawGamepadCursor2D(ctx, state, terrainSet, now){
  const cursor = _gamepadCursorTile(state);
  if(!cursor) return;
  const [x, y] = cursor, key = `${x},${y}`;
  if(!terrainSet.has(key)) return; // o controle não revela a névoa
  const X = x * CELL, Y = y * CELL;
  const pulse = 0.5 + 0.5 * Math.sin(now / 260);
  const tone = _gamepadCursorTone(state);
  const selecionandoAtaque = !!_gamepadInput.attackMode;
  ctx.save();
  ctx.fillStyle = `rgba(${tone.fill},${(tone.fillAlpha + pulse * .08).toFixed(3)})`;
  ctx.fillRect(X + 2, Y + 2, CELL - 4, CELL - 4);
  ctx.shadowColor = selecionandoAtaque ? 'rgba(255,232,103,.98)' : `rgba(${tone.stroke},.65)`;
  ctx.shadowBlur = selecionandoAtaque ? CELL * (.15 + pulse * .13) : 0;
  ctx.strokeStyle = `rgba(${tone.stroke},${(selecionandoAtaque ? .82 + pulse * .18 : .58 + pulse * .36).toFixed(3)})`;
  ctx.lineWidth = Math.max(selecionandoAtaque ? 2.6 : 1.5, CELL / (selecionandoAtaque ? 25 : 42));
  if(!selecionandoAtaque) ctx.setLineDash([Math.max(3, CELL / 7), Math.max(2, CELL / 12)]);
  else ctx.setLineDash([]);
  ctx.lineDashOffset = -now / 28;
  ctx.strokeRect(X + 3, Y + 3, CELL - 6, CELL - 6);
  ctx.setLineDash([]);
  if(selecionandoAtaque){
    // Retículo central: não se confunde com os quadrados vermelhos de alcance.
    const cx = X + CELL / 2, cy = Y + CELL / 2, arm = CELL * .19;
    ctx.beginPath();
    ctx.moveTo(cx - arm, cy); ctx.lineTo(cx + arm, cy);
    ctx.moveTo(cx, cy - arm); ctx.lineTo(cx, cy + arm);
    ctx.stroke();
  }
  ctx.restore();
}

// Realces de interação pertencem ao primeiro plano. Eles são desenhados
// separadamente porque a camada estática não deve mudar só para pulsar azul ou
// vermelho durante o turno.
function _drawFloorHighlights2D(ctx, x, y, isReachable, isAttackable, isWeaponPreview){
  if(!isReachable && !isAttackable && !isWeaponPreview) return;
  const X = x * CELL, Y = y * CELL;
  if(isReachable){
    const pa = 0.70 + 0.30 * _movePulse;
    const fa = 0.26 + 0.26 * _movePulse;
    const da = 0.65 + 0.35 * _movePulse;
    ctx.strokeStyle = `rgba(60,140,255,${pa.toFixed(2)})`; ctx.lineWidth = 2;
    ctx.strokeRect(X+2, Y+2, CELL-4, CELL-4);
    ctx.fillStyle = `rgba(30,107,255,${fa.toFixed(2)})`;
    ctx.fillRect(X+2, Y+2, CELL-4, CELL-4);
    ctx.fillStyle = `rgba(150,195,255,${da.toFixed(2)})`;
    const d = 4;
    for(const [cx, cy] of [[X+d,Y+d],[X+CELL-d,Y+d],[X+d,Y+CELL-d],[X+CELL-d,Y+CELL-d]]){
      ctx.beginPath(); ctx.arc(cx, cy, 1.8, 0, Math.PI*2); ctx.fill();
    }
  }
  if(isAttackable){
    ctx.strokeStyle='rgba(255,60,60,0.78)'; ctx.lineWidth=2;
    ctx.strokeRect(X+2,Y+2,CELL-4,CELL-4);
    ctx.fillStyle='rgba(255,30,30,0.13)'; ctx.fillRect(X+2,Y+2,CELL-4,CELL-4);
    ctx.fillStyle='rgba(255,120,120,0.68)';
    const d=4;
    for(const [cx,cy] of [[X+d,Y+d],[X+CELL-d,Y+d],[X+d,Y+CELL-d],[X+CELL-d,Y+CELL-d]]){
      ctx.beginPath(); ctx.arc(cx,cy,1.8,0,Math.PI*2); ctx.fill();
    }
  }
  if(isWeaponPreview){
    ctx.fillStyle='rgba(220,0,0,0.52)'; ctx.fillRect(X+1,Y+1,CELL-2,CELL-2);
    ctx.strokeStyle='rgba(255,0,0,0.98)'; ctx.lineWidth=2.5;
    ctx.strokeRect(X+2,Y+2,CELL-4,CELL-4);
    ctx.strokeStyle='rgba(255,120,80,0.55)'; ctx.lineWidth=1;
    ctx.strokeRect(X+4,Y+4,CELL-8,CELL-8);
    ctx.fillStyle='rgba(255,80,40,1.0)';
    const d=4;
    for(const [cx,cy] of [[X+d,Y+d],[X+CELL-d,Y+d],[X+d,Y+CELL-d],[X+CELL-d,Y+CELL-d]]){
      ctx.beginPath(); ctx.arc(cx,cy,2.5,0,Math.PI*2); ctx.fill();
    }
  }
}

function _drawMovePreview2D(ctx, state, terrainSet){
  const preview = GS.pendingMove;
  const me = preview?.testHeroId != null
    ? state?.players?.find(p => String(p.id) === String(preview.testHeroId) && p.alive)
    : state?.players?.find(p => p.id === GS.myPid && p.alive);
  if(!preview?.path?.length || !me) return;
  const origin = Array.isArray(preview.origin) ? preview.origin : me.pos;
  let x = origin[0], y = origin[1];
  const points = [];
  if(terrainSet.has(`${x},${y}`)) points.push([x * CELL + CELL / 2, y * CELL + CELL / 2]);
  for(const step of preview.path){
    x += step[0]; y += step[1];
    if(!terrainSet.has(`${x},${y}`)) break;
    points.push([x * CELL + CELL / 2, y * CELL + CELL / 2]);
  }
  if(points.length < 2) return;

  ctx.save();
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  ctx.shadowColor = 'rgba(255, 194, 48, .9)';
  ctx.shadowBlur = Math.max(5, CELL * .16);
  ctx.strokeStyle = 'rgba(255, 194, 48, .82)';
  ctx.lineWidth = Math.max(4, CELL * .13);
  ctx.beginPath();
  ctx.moveTo(points[0][0], points[0][1]);
  for(let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
  ctx.stroke();
  ctx.shadowBlur = 0;
  ctx.strokeStyle = 'rgba(255, 245, 170, .98)';
  ctx.lineWidth = Math.max(1.5, CELL * .045);
  ctx.stroke();

  // Pequenos nós deixam explícito por quais casas o peão passará.
  ctx.fillStyle = 'rgba(255, 223, 92, .96)';
  for(let i = 1; i < points.length; i++){
    ctx.beginPath();
    ctx.arc(points[i][0], points[i][1], Math.max(2.5, CELL * .065), 0, Math.PI * 2);
    ctx.fill();
  }

  const tip = points[points.length - 1];
  const prev = points[points.length - 2];
  const angle = Math.atan2(tip[1] - prev[1], tip[0] - prev[0]);
  ctx.translate(tip[0], tip[1]);
  ctx.rotate(angle);
  ctx.fillStyle = 'rgba(255, 246, 176, .98)';
  ctx.beginPath();
  ctx.moveTo(CELL * .24, 0);
  ctx.lineTo(-CELL * .16, -CELL * .16);
  ctx.lineTo(-CELL * .16, CELL * .16);
  ctx.closePath();
  ctx.fill();
  ctx.restore();
}

function _drawMasterMonsterMovePreview2D(ctx, state, terrainSet){
  const preview = _masterMonsterMovePreviewAtual(state);
  if(!preview?.path?.length) return;
  let x = preview.origin[0], y = preview.origin[1];
  const points = [];
  if(terrainSet.has(`${x},${y}`)) points.push([x * CELL + CELL / 2, y * CELL + CELL / 2]);
  for(const step of preview.path){
    x += step[0]; y += step[1];
    if(!terrainSet.has(`${x},${y}`)) break;
    points.push([x * CELL + CELL / 2, y * CELL + CELL / 2]);
  }
  if(points.length < 2) return;
  ctx.save();
  ctx.lineCap = 'round'; ctx.lineJoin = 'round';
  ctx.shadowColor = 'rgba(255, 145, 36, .95)';
  ctx.shadowBlur = Math.max(5, CELL * .18);
  ctx.strokeStyle = 'rgba(255, 156, 48, .88)';
  ctx.lineWidth = Math.max(4, CELL * .13);
  ctx.beginPath(); ctx.moveTo(points[0][0], points[0][1]);
  for(let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
  ctx.stroke();
  ctx.shadowBlur = 0;
  ctx.strokeStyle = 'rgba(255, 235, 150, .98)';
  ctx.lineWidth = Math.max(1.5, CELL * .045); ctx.stroke();
  ctx.fillStyle = 'rgba(255, 184, 68, .98)';
  for(const [px, py] of points.slice(1)){
    ctx.beginPath(); ctx.arc(px, py, Math.max(2.5, CELL * .065), 0, Math.PI * 2); ctx.fill();
  }
  const tip = points[points.length - 1], prev = points[points.length - 2];
  const angle = Math.atan2(tip[1] - prev[1], tip[0] - prev[0]);
  ctx.translate(tip[0], tip[1]); ctx.rotate(angle);
  ctx.fillStyle = 'rgba(255, 240, 168, .99)';
  ctx.beginPath(); ctx.moveTo(CELL * .24, 0);
  ctx.lineTo(-CELL * .16, -CELL * .16); ctx.lineTo(-CELL * .16, CELL * .16);
  ctx.closePath(); ctx.fill(); ctx.restore();
}

// ── Animações visuais das armadilhas ───────────────────────────────────────
// Armadilhas são resolvidas no servidor. Este bloco apenas interpreta o
// trap_result privado recebido pelo jogador afetado e desenha a antecipação,
// o disparo e o impacto, sem alterar dano, saves ou estado da partida.
const _armadilhaAnims = [];
let _armadilha2DRaf = null;

function _armadilhaId(msg){
  return String(msg?.tipo_id || msg?.tipo || '').toLowerCase();
}

function _armadilhaStyle(msg){
  const id = _armadilhaId(msg);
  if(id.includes('pendulo') || id.includes('guilhotina') || id.includes('lamina') || id.includes('dardo'))
    return {kind:'blade', color:'#e4edf5', hot:'#ff435f', dark:'#721b31', icon:'⚔'};
  if(id.includes('gelo') || id.includes('congel') || id.includes('frio'))
    return {kind:'ice', color:'#baf6ff', hot:'#39cfff', dark:'#1d4d8f', icon:'❄'};
  if(id.includes('rede'))
    return {kind:'net', color:'#d9b6ff', hot:'#9d5dff', dark:'#342062', icon:'🕸'};
  if(id.includes('teto') || id.includes('esmag') || id.includes('prensa'))
    return {kind:'crush', color:'#d6ae89', hot:'#ff7147', dark:'#4b2c24', icon:'⬇'};
  if(id.includes('venen') || id.includes('poison'))
    return {kind:'poison', color:'#b7ff55', hot:'#d8ff36', dark:'#3e214f', icon:'☠'};
  if(id.includes('gas') || id.includes('fumaca') || id.includes('nuvem'))
    return {kind:'gas', color:'#d7ed58', hot:'#ffe36a', dark:'#4c5e24', icon:'☁'};
  if(id.includes('mina') || id.includes('explos') || id.includes('fogo') || id.includes('incend'))
    return {kind:'mine', color:'#ffb347', hot:'#ff3c20', dark:'#722211', icon:'✹'};
  if(id.includes('teleport') || id.includes('teletrans'))
    return {kind:'teleport', color:'#b88cff', hot:'#5ad7ff', dark:'#38206e', icon:'🌀'};
  if(id.includes('acido') || id.includes('ácido'))
    return {kind:'acid', color:'#efff68', hot:'#91ff35', dark:'#52651f', icon:'☣'};
  return {kind:'generic', color:'#ffcb62', hot:'#ff5a38', dark:'#54253b', icon:'⚠'};
}

function _armadilhaPos(msg, state=GS.gameState){
  const raw = msg?.pos || msg?.target_pos || msg?.alvo_pos;
  if(Array.isArray(raw) && raw.length >= 2 && raw.every(Number.isFinite)) return [raw[0], raw[1]];
  const id = msg?.target_id ?? msg?.alvo_id ?? GS.myPid;
  const alvo = (state?.players || []).find(p => String(p.id) === String(id) && p.pos)
    || (state?.players || []).find(p => String(p.id) === String(GS.myPid) && p.pos);
  return alvo?.pos ? [alvo.pos[0], alvo.pos[1]] : null;
}

function _armadilhaProgress(anim, now){
  return Math.max(0, Math.min(1, (now - anim.startedAt) / anim.duration));
}

function _armadilhaDraw2D(ctx, state, anim, now){
  const p = _armadilhaProgress(anim, now);
  const style = anim.style;
  const [tx, ty] = anim.pos;
  const cx = tx * CELL + CELL / 2, cy = ty * CELL + CELL / 2;
  const q = p < .30 ? p / .30 : 1;
  const impact = Math.max(0, Math.min(1, (p - .23) / .50));
  const fade = p > .67 ? Math.max(0, 1 - (p - .67) / .33) : 1;
  const intensity = anim.msg?.sucesso ? (anim.msg?.metade ? .78 : .58) : 1;
  const pulse = .55 + .45 * Math.sin(now / 65 + anim.seed);
  const radius = CELL * (.27 + q * .52);
  const rgba = (hex, a) => {
    const n = parseInt(hex.slice(1), 16);
    return `rgba(${n >> 16},${(n >> 8) & 255},${n & 255},${Math.max(0, a * fade * intensity).toFixed(3)})`;
  };
  ctx.save();
  ctx.translate(cx, cy);
  ctx.globalCompositeOperation = 'lighter';
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  // Marca no chão: todo disparo nasce de uma pulsação curta antes do impacto.
  ctx.strokeStyle = rgba(style.hot, .72 + .18 * pulse);
  ctx.lineWidth = 2.5;
  ctx.beginPath(); ctx.arc(0, 0, radius, 0, Math.PI * 2); ctx.stroke();
  ctx.strokeStyle = rgba(style.color, .26);
  ctx.lineWidth = 1.2;
  ctx.beginPath(); ctx.arc(0, 0, radius * (.66 + .10 * pulse), 0, Math.PI * 2); ctx.stroke();

  const drawRay = (angle, length, width=2) => {
    ctx.save(); ctx.rotate(angle);
    ctx.strokeStyle = rgba(style.hot, .65 + .30 * impact);
    ctx.lineWidth = width;
    ctx.beginPath(); ctx.moveTo(CELL * .08, 0); ctx.lineTo(length, 0); ctx.stroke();
    ctx.restore();
  };
  const drawShard = (angle, dist, size) => {
    ctx.save(); ctx.rotate(angle); ctx.translate(dist, 0);
    ctx.fillStyle = rgba(style.color, .80);
    ctx.strokeStyle = rgba(style.hot, .92); ctx.lineWidth = 1.2;
    ctx.beginPath(); ctx.moveTo(size, 0); ctx.lineTo(-size * .45, size * .52);
    ctx.lineTo(-size * .38, -size * .52); ctx.closePath(); ctx.fill(); ctx.stroke(); ctx.restore();
  };

  if(style.kind === 'blade'){
    const sweep = -1.0 + Math.min(1, impact * 2.4);
    ctx.save(); ctx.rotate(sweep);
    ctx.strokeStyle = rgba(style.color, .95); ctx.lineWidth = CELL * .12;
    ctx.beginPath(); ctx.moveTo(-CELL * .72, -CELL * .58); ctx.lineTo(CELL * .72, CELL * .58); ctx.stroke();
    ctx.strokeStyle = rgba(style.hot, .95); ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(-CELL * .78, -CELL * .64); ctx.lineTo(CELL * .78, CELL * .64); ctx.stroke(); ctx.restore();
    drawRay(-Math.PI * .25, CELL * (.56 + impact * .58), 1.5);
    drawRay(Math.PI * .75, CELL * (.56 + impact * .58), 1.5);
  } else if(style.kind === 'ice'){
    for(let i=0;i<8;i++) drawShard(i * Math.PI / 4 + .2, radius * (.42 + impact * .48), CELL * (.10 + .06 * impact));
    for(let i=0;i<4;i++) drawRay(i * Math.PI / 2 + Math.PI / 4, CELL * (.35 + impact * .54), 1.5);
  } else if(style.kind === 'net'){
    ctx.strokeStyle = rgba(style.color, .88); ctx.lineWidth = 2;
    for(let i=0;i<8;i++){
      const a = i * Math.PI / 4 + now / 1800;
      ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(Math.cos(a)*radius, Math.sin(a)*radius); ctx.stroke();
    }
    ctx.beginPath(); ctx.arc(0,0,radius*.52,0,Math.PI*2); ctx.stroke();
    ctx.beginPath(); ctx.arc(0,0,radius*.80,0,Math.PI*2); ctx.stroke();
  } else if(style.kind === 'crush'){
    const down = Math.min(1, impact * 1.35);
    ctx.fillStyle = rgba(style.dark, .70); ctx.fillRect(-CELL*.57, -CELL*.92 + down*CELL*.70, CELL*1.14, CELL*.30);
    ctx.fillStyle = rgba(style.hot, .58); ctx.fillRect(-CELL*.52, -CELL*.92 + down*CELL*.70, CELL*1.04, CELL*.07);
    for(let i=0;i<5;i++) drawRay((i-2)*.45, CELL * (.34 + impact*.40), 1.5);
  } else if(style.kind === 'poison' || style.kind === 'gas'){
    const spread = radius * (1.0 + impact * .42);
    for(let i=0;i<7;i++){
      const a = i * 2.399 + anim.seed;
      const rr = spread * (.24 + (i%3)*.18);
      ctx.fillStyle = rgba(style.color, .15 + .07 * pulse);
      ctx.beginPath(); ctx.arc(Math.cos(a)*rr, Math.sin(a)*rr, CELL*(.18 + (i%2)*.06), 0, Math.PI*2); ctx.fill();
    }
    ctx.strokeStyle = rgba(style.hot, .62); ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(0,0,spread*.78,0,Math.PI*2); ctx.stroke();
  } else if(style.kind === 'mine'){
    for(let i=0;i<10;i++) drawRay(i * Math.PI / 5, CELL * (.38 + impact*.68), i%2 ? 2 : 3);
    ctx.fillStyle = rgba(style.hot, .52 + .25 * pulse);
    ctx.beginPath(); ctx.arc(0,0,CELL*(.18 + impact*.24),0,Math.PI*2); ctx.fill();
  } else if(style.kind === 'teleport'){
    ctx.strokeStyle = rgba(style.color, .85); ctx.lineWidth = 3;
    ctx.beginPath(); ctx.arc(0,0,radius*.68, -now/300, Math.PI*1.35-now/300); ctx.stroke();
    ctx.strokeStyle = rgba(style.hot, .78); ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(0,0,radius*.46, now/250, Math.PI*1.55+now/250); ctx.stroke();
  } else if(style.kind === 'acid'){
    for(let i=0;i<7;i++){
      const a = i * 1.83 + anim.seed;
      const rr = CELL * (.20 + impact*.55) * (i%2 ? .7 : 1);
      ctx.fillStyle = rgba(style.color, .75);
      ctx.beginPath(); ctx.arc(Math.cos(a)*rr, Math.sin(a)*rr, CELL*(.045 + .025*(i%3)), 0, Math.PI*2); ctx.fill();
    }
    for(let i=0;i<4;i++) drawRay(i*Math.PI/2+.35, CELL*(.38+impact*.46), 1.5);
  } else {
    for(let i=0;i<8;i++) drawRay(i*Math.PI/4, CELL*(.35+impact*.48), 2);
  }

  if(impact > 0){
    ctx.fillStyle = rgba(style.hot, .20 * (1-impact));
    ctx.beginPath(); ctx.arc(0,0,CELL*(.18+impact*.42),0,Math.PI*2); ctx.fill();
  }
  ctx.globalCompositeOperation = 'source-over';
  ctx.font = `bold ${Math.max(12, CELL * .32)}px sans-serif`;
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.fillStyle = rgba(style.color, .90);
  ctx.shadowColor = rgba(style.hot, .90); ctx.shadowBlur = 7;
  ctx.fillText(style.icon, 0, -CELL*.67 - Math.sin(now/130)*2);
  ctx.font = `bold ${Math.max(10, CELL * .22)}px sans-serif`;
  ctx.fillStyle = rgba(anim.msg?.sucesso ? '#9dffbc' : '#ff9b78', .95);
  ctx.fillText(anim.msg?.sucesso ? '✓' : '!', CELL*.34, CELL*.48);
  ctx.restore();
}

function _disposeArmadilhaGroup(group){
  if(!group) return;
  group.traverse(obj => {
    if(obj.geometry?.dispose) obj.geometry.dispose();
    const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
    for(const mat of mats) if(mat?.dispose) mat.dispose();
  });
  if(group.parent) group.parent.remove(group);
}

function _buildArmadilha3D(anim){
  if(!g3?.scene || !g3.T || anim.group) return;
  const T = g3.T, s = anim.style, group = new T.Group();
  group.name = `trap-fx-${_armadilhaId(anim.msg)}`;
  const mat = (color, opacity=.75, emissive=true) => new T.MeshBasicMaterial({
    color, transparent:true, opacity, depthWrite:false,
    blending:T.AdditiveBlending
  });
  const ringMat = mat(s.hot, .80);
  const ring = new T.Mesh(new T.TorusGeometry(.38, .026, 8, 36), ringMat);
  ring.rotation.x = Math.PI/2; ring.userData.trapRing = 1; group.add(ring);
  const ring2 = new T.Mesh(new T.TorusGeometry(.64, .014, 6, 36), mat(s.color, .55));
  ring2.rotation.x = Math.PI/2; ring2.userData.trapRing = 2; group.add(ring2);
  const core = new T.Mesh(new T.SphereGeometry(.12, 10, 8), mat(s.hot, .82));
  core.userData.trapCore = 1; group.add(core);

  const addLine = (points, opacity=.8) => {
    const geo = new T.BufferGeometry().setFromPoints(points);
    const line = new T.Line(geo, new T.LineBasicMaterial({color:s.color, transparent:true, opacity, depthWrite:false, blending:T.AdditiveBlending}));
    line.userData.trapLine = 1; group.add(line); return line;
  };
  for(let i=0;i<8;i++){
    const a = i*Math.PI/4;
    addLine([new T.Vector3(Math.cos(a)*.12,.07,Math.sin(a)*.12), new T.Vector3(Math.cos(a)*.82,.07,Math.sin(a)*.82)], .62);
  }
  if(s.kind === 'blade'){
    const blade = new T.Mesh(new T.BoxGeometry(1.25,.055,.09), mat(s.color,.92));
    blade.rotation.y = -.55; blade.position.y = .58; blade.userData.trapBlade = 1; group.add(blade);
  } else if(s.kind === 'crush'){
    const block = new T.Mesh(new T.BoxGeometry(1.08,.25,1.08), mat(s.dark,.84));
    block.position.y = 1.35; block.userData.trapCrush = 1; group.add(block);
  } else if(s.kind === 'ice'){
    for(let i=0;i<6;i++){
      const a=i*Math.PI/3, shard=new T.Mesh(new T.ConeGeometry(.075,.36,5),mat(s.color,.82));
      shard.position.set(Math.cos(a)*.46,.18,Math.sin(a)*.46); shard.userData.trapShard = 1; group.add(shard);
    }
  } else if(s.kind === 'net'){
    for(let i=0;i<3;i++){
      const netRing = new T.Mesh(new T.TorusGeometry(.25+i*.16,.012,5,28),mat(s.color,.66));
      netRing.rotation.x=Math.PI/2; netRing.rotation.z=i*.25; netRing.userData.trapNet=i; group.add(netRing);
    }
  } else if(s.kind === 'poison' || s.kind === 'gas'){
    for(let i=0;i<7;i++){
      const a=i*2.399, puff=new T.Mesh(new T.SphereGeometry(.13+(i%3)*.035,8,6),mat(s.color,.25));
      puff.position.set(Math.cos(a)*(.25+(i%2)*.22),.16+(i%3)*.08,Math.sin(a)*(.25+(i%2)*.22));
      puff.userData.trapPuff = 1; puff.userData.trapAngle = a; group.add(puff);
    }
  } else if(s.kind === 'mine'){
    for(let i=0;i<8;i++){
      const a=i*Math.PI/4, shard=new T.Mesh(new T.ConeGeometry(.035,.28,5),mat(s.hot,.75));
      shard.position.set(Math.cos(a)*.28,.18,Math.sin(a)*.28); shard.userData.trapShard=1; shard.userData.trapAngle=a; group.add(shard);
    }
  } else if(s.kind === 'acid'){
    for(let i=0;i<6;i++){
      const a=i*1.83, drop=new T.Mesh(new T.SphereGeometry(.045,7,6),mat(s.color,.82));
      drop.position.set(Math.cos(a)*.25,.65+(i%3)*.11,Math.sin(a)*.25); drop.userData.trapDrop=1; drop.userData.trapAngle=a; group.add(drop);
      drop.userData.trapBaseX = drop.position.x;
      drop.userData.trapBaseY = drop.position.y;
      drop.userData.trapBaseZ = drop.position.z;
    }
  }
  const w = casaParaMundo(anim.pos[0], anim.pos[1]);
  group.position.set(w.x, .03, w.z);
  group.userData.trapAnim = anim;
  g3.scene.add(group); anim.group = group;
}

function _updateArmadilhas3D(now){
  if(!g3?.scene) return;
  for(const anim of _armadilhaAnims){
    if(anim.group && anim.group.parent !== g3.scene){ _disposeArmadilhaGroup(anim.group); anim.group = null; }
    if(!anim.group) _buildArmadilha3D(anim);
    const group = anim.group; if(!group) continue;
    const p = _armadilhaProgress(anim, now), q = Math.min(1, p/.30), impact = Math.max(0, Math.min(1,(p-.23)/.50));
    const pulse = .5 + .5*Math.sin(now/65 + anim.seed);
    group.children.forEach(obj => {
      const u=obj.userData||{};
      if(u.trapRing){ const base = u.trapRing === 1 ? .38 : .64; const sc=base*(.55+q*.55)*(u.trapRing===2?1+impact*.28:1); obj.scale.setScalar(sc/base); obj.rotation.z += u.trapRing === 1 ? .022 : -.015; if(obj.material) obj.material.opacity=(u.trapRing===1?.76:.45)*(1-Math.max(0,p-.68)/.32); }
      if(u.trapCore){ obj.scale.setScalar(.55+impact*.9+pulse*.22); if(obj.material) obj.material.opacity=.72*(1-Math.max(0,p-.65)/.35); }
      if(u.trapLine){ const sc=.5+impact*.72; obj.scale.set(sc,1,sc); if(obj.material) obj.material.opacity=.48+.34*impact; }
      if(u.trapBlade){ obj.rotation.y = -.55 + Math.min(1,impact*1.6)*1.9; obj.position.y=.72-impact*.62; if(obj.material) obj.material.opacity=.92*(1-Math.max(0,p-.70)/.30); }
      if(u.trapCrush){ obj.position.y=1.35-Math.min(1,impact*1.45)*1.20; if(obj.material) obj.material.opacity=.84*(1-Math.max(0,p-.72)/.28); }
      if(u.trapShard){ const a=u.trapAngle ?? 0, rr=.30+impact*.48; obj.position.x=Math.cos(a)*rr; obj.position.z=Math.sin(a)*rr; obj.position.y=.12+impact*.18; obj.rotation.z += .04; }
      if(u.trapNet!=null){ obj.scale.setScalar(.55+impact*.70); obj.rotation.z += .018*(u.trapNet%2?-1:1); }
      if(u.trapPuff){ obj.scale.setScalar(.75+impact*.85+pulse*.10); if(obj.material) obj.material.opacity=.20*(1-Math.max(0,p-.60)/.40); }
      if(u.trapDrop){ const a = u.trapAngle || 0; obj.position.y=Math.max(.08,(u.trapBaseY ?? .65)+Math.sin(now/180+a)*.08-impact*.55); obj.position.x=(u.trapBaseX ?? 0)*(1+impact*.8); obj.position.z=(u.trapBaseZ ?? 0)*(1+impact*.8); }
    });
    group.visible = p < 1;
  }
  for(let i=_armadilhaAnims.length-1;i>=0;i--){
    if(_armadilhaProgress(_armadilhaAnims[i],now)>=1){ _disposeArmadilhaGroup(_armadilhaAnims[i].group); _armadilhaAnims.splice(i,1); }
  }
}

function _tickArmadilhas2D(now){
  _armadilha2DRaf = null;
  if(mode3D && g3) return;
  if(!GS.gameState || !_armadilhaAnims.length) return;
  renderMap(GS.gameState);
  for(let i=_armadilhaAnims.length-1;i>=0;i--)
    if(_armadilhaProgress(_armadilhaAnims[i],now)>=1) _armadilhaAnims.splice(i,1);
  if(_armadilhaAnims.length) _armadilha2DRaf = _scheduleVisualFrame(_tickArmadilhas2D);
}

// ═══════════════════════════════════════════════════════════════════════════
// BOMBA DE FUMAÇA — nuvem guiada pela zona (zonas_especiais, visual_id "fumaca_*")
// ═══════════════════════════════════════════════════════════════════════════
// A mecânica é a zona de escuridão de sempre; só o VISUAL é outro: em vez da
// névoa roxa do Manto, uma nuvem de fumaça que (1) nasce quando o frasco chega
// — anel rente ao chão + novelos que incham, com "puff" e chiado —, (2) fica
// viva enquanto a zona existe, (3) afina na última rodada e (4) se desfaz para
// cima quando a zona some. Vale para o herói e para o Soldado (mesma zona).
const FUMACA_NASCER_MS = 1100, FUMACA_SAIR_MS = 1600, FUMACA_ANEL_MS = 450;
// Opacidade medida no render (2026-09-24): com 0,5 e textura rala a nuvem só escurecia
// o piso claro em ~13 níveis de cor — existia, mas não se via.
const FUMACA_NOVELOS = 16, FUMACA_OPACIDADE = 0.85, FUMACA_OPACIDADE_FIM = 0.45;
const FUMACA_CORES = [0x8a8f99, 0x9aa0a8, 0x7c828c, 0xa3a7ae];
const _fumacaNuvens = new Map();       // visual_id -> nuvem
let _fumacaBaseline = true;            // 1º estado após reset: zonas antigas nascem prontas e mudas
let _fumaca2DRaf = null;
let _fumacaTextura = null;             // textura de novelo (canvas), reusada

function _ehZonaFumaca(z){ return !!(z && z.tipo === 'escuridao' && String(z.visual_id || '').startsWith('fumaca_')); }

function _fumacaReset(){
  for(const n of _fumacaNuvens.values()) _fumacaDispose3D(n);
  _fumacaNuvens.clear();
  _fumacaBaseline = true;
}

function _fumacaSync(state){
  if(!state) return;
  const now = performance.now();
  const rodada = Number(state.round ?? state.round_num ?? 0) || 0;
  const vivas = new Set();
  for(const z of (state.zonas_especiais || [])){
    if(!z.ativa || !_ehZonaFumaca(z)) continue;
    const id = String(z.visual_id);
    vivas.add(id);
    let n = _fumacaNuvens.get(id);
    if(!n){
      const partes = id.split('_');
      const rodadaCriada = Number(partes[partes.length - 3]);
      const nova = !_fumacaBaseline && !GS.isPreview && rodadaCriada === rodada;
      const pos = [Number(z.cx), Number(z.cy)];
      const chegada = (nova && window.CombatScene && CombatScene.areaImpactAt) ? CombatScene.areaImpactAt(pos, now) : null;
      let semente = (pos[0] * 73856093) ^ (pos[1] * 19349663) ^ (rodadaCriada * 83492791);
      const rnd = () => { semente = (semente * 1103515245 + 12345) & 0x7fffffff; return semente / 0x7fffffff; };
      const r = Math.max(1, Number(z.raio) || 1);
      n = { id, cx: pos[0], cy: pos[1], raio: r,
        nasceEm: nova ? Math.max(now, chegada || now) : now - FUMACA_NASCER_MS - FUMACA_ANEL_MS,
        saiEm: null, ultima: false, group: null, somTocado: !nova,
        novelos: Array.from({length: FUMACA_NOVELOS}, (_, i) => ({
          dx: (rnd() * 2 - 1) * (r + 0.1), dz: (rnd() * 2 - 1) * (r + 0.1),
          y: 0.15 + rnd() * 0.75, esc: 1.6 + rnd() * 0.9, giro: (rnd() * 2 - 1) * 0.35,
          fase: rnd() * Math.PI * 2, atraso: i * 45, cor: FUMACA_CORES[i % FUMACA_CORES.length] })) };
      _fumacaNuvens.set(id, n);
    }
    n.ultima = Number(z.duracao) <= 1;
  }
  for(const n of _fumacaNuvens.values())
    if(!vivas.has(n.id) && n.saiEm == null) n.saiEm = now;
  _fumacaBaseline = false;
  if(!(mode3D && g3) && _fumacaNuvens.size && !_fumaca2DRaf) _fumaca2DRaf = _scheduleVisualFrame(_tickFumaca2D);
}

// Sons e limpeza são comuns a 2D e 3D (chamados pelo tick de cada modo).
function _fumacaAvancar(now){
  for(const [id, n] of _fumacaNuvens){
    if(!n.somTocado && now >= n.nasceEm){
      n.somTocado = true;
      const pos = [n.cx, n.cy];
      try{ sfx('fumaca_puff', {pos}); setTimeout(() => sfx('fumaca_chiado', {pos}), 120); }catch(e){}
    }
    if(n.saiEm != null && now - n.saiEm >= FUMACA_SAIR_MS){ _fumacaDispose3D(n); _fumacaNuvens.delete(id); }
  }
}

// Estado de um instante: nascimento (0→1), opacidade-alvo e saída (0→1).
function _fumacaFase(n, now){
  const nasc = Math.max(0, Math.min(1, (now - n.nasceEm) / FUMACA_NASCER_MS));
  const anel = Math.max(0, Math.min(1, (now - n.nasceEm) / FUMACA_ANEL_MS));
  const saida = n.saiEm == null ? 0 : Math.max(0, Math.min(1, (now - n.saiEm) / FUMACA_SAIR_MS));
  const alvo = n.ultima ? FUMACA_OPACIDADE_FIM : FUMACA_OPACIDADE;
  return { antes: now < n.nasceEm, nasc, anel, saida, alvo };
}

function _fumacaTexturaNovelo(T){
  if(_fumacaTextura) return _fumacaTextura;
  const c = document.createElement('canvas'); c.width = c.height = 128;
  const x = c.getContext('2d');
  // Várias manchas macias sobrepostas: borda irregular, miolo mais denso.
  const bolhas = [[64,64,54,.85],[46,56,36,.6],[82,54,34,.6],[58,80,32,.55],[80,78,30,.55],[64,44,28,.5]];
  for(const [bx, by, br, a] of bolhas){
    const g = x.createRadialGradient(bx, by, 0, bx, by, br);
    g.addColorStop(0, `rgba(255,255,255,${a})`); g.addColorStop(.6, `rgba(255,255,255,${a * .45})`);
    g.addColorStop(1, 'rgba(255,255,255,0)');
    x.fillStyle = g; x.fillRect(0, 0, 128, 128);
  }
  _fumacaTextura = new T.CanvasTexture(c);
  return _fumacaTextura;
}

function _fumacaBuild3D(n){
  if(!g3?.scene || !g3.T || n.group) return;
  const T = g3.T, group = new T.Group();
  group.name = 'fumaca-' + n.id;
  const tex = _fumacaTexturaNovelo(T);
  for(const nv of n.novelos){
    const mat = new T.SpriteMaterial({ map: tex, color: nv.cor, transparent: true, opacity: 0, depthWrite: false });
    const sp = new T.Sprite(mat);
    sp.userData.fumacaNovelo = nv;
    group.add(sp);
  }
  const anel = new T.Mesh(new T.RingGeometry(0.2, 0.32, 40),
    new T.MeshBasicMaterial({ color: 0xa9adb4, transparent: true, opacity: 0, depthWrite: false, side: T.DoubleSide }));
  anel.rotation.x = -Math.PI / 2; anel.position.y = 0.05;
  anel.userData.fumacaAnel = true;
  group.add(anel);
  const w = casaParaMundo(n.cx, n.cy);
  group.position.set(w.x, 0, w.z);
  g3.scene.add(group); n.group = group;
}

function _fumacaDispose3D(n){
  const g = n && n.group; if(!g) return;
  if(g.parent) g.parent.remove(g);
  g.traverse(o => { if(o.geometry) o.geometry.dispose(); if(o.material) o.material.dispose(); });   // a textura é compartilhada: fica
  n.group = null;
}

function _updateFumaca3D(now){
  _fumacaAvancar(now);
  if(!g3?.scene) return;
  const vis = g3.spellVisibleSet;
  for(const n of _fumacaNuvens.values()){
    if(n.group && n.group.parent !== g3.scene){ _fumacaDispose3D(n); }
    if(!n.group) _fumacaBuild3D(n);
    const g = n.group; if(!g) continue;
    const f = _fumacaFase(n, now);
    g.visible = !f.antes && (!vis || vis.has(`${n.cx},${n.cy}`));
    if(!g.visible) continue;
    const easeNasc = 1 - Math.pow(1 - f.nasc, 3);
    for(const o of g.children){
      if(o.userData.fumacaAnel){
        const s = 1 + f.anel * ((n.raio + 0.6) / 0.26 - 1);
        o.scale.set(s, s, 1);
        o.material.opacity = 0.6 * (1 - f.anel);
        continue;
      }
      const nv = o.userData.fumacaNovelo; if(!nv) continue;
      const loc = Math.max(0, Math.min(1, (now - n.nasceEm - nv.atraso) / FUMACA_NASCER_MS));
      const eLoc = 1 - Math.pow(1 - loc, 3);
      const resp = 1 + 0.06 * Math.sin(now / 900 + nv.fase);
      const esc = nv.esc * (0.25 + 0.75 * eLoc) * resp * (1 + 0.3 * f.saida);
      o.scale.set(esc, esc, 1);
      o.position.set(nv.dx + Math.sin(now / 2600 + nv.fase) * 0.08,
                     nv.y * (0.6 + 0.4 * easeNasc) + f.saida * 0.6,
                     nv.dz + Math.cos(now / 2900 + nv.fase) * 0.08);
      o.material.rotation = nv.fase + now / 1000 * nv.giro;
      o.material.opacity = f.alvo * eLoc * (1 - f.saida);
    }
  }
}

// 2D: disco de fumaça por casa com borda esfumaçada; pulsa devagar enquanto
// dura, nasce/some com a mesma linha do tempo do 3D.
function _fumacaDraw2D(ctx, state, now){
  if(!_fumacaNuvens.size) return;
  for(const n of _fumacaNuvens.values()){
    const f = _fumacaFase(n, now);
    if(f.antes) continue;
    const a = f.alvo * (1 - Math.pow(1 - f.nasc, 3)) * (1 - f.saida);
    const puls = 1 + 0.05 * Math.sin(now / 900 + n.cx);
    const cx = (n.cx + 0.5) * CELL, cy = (n.cy + 0.5) * CELL;
    const r = (n.raio + 0.55) * CELL * puls * (0.35 + 0.65 * f.nasc) * (1 + 0.2 * f.saida);
    ctx.save();
    const grad = ctx.createRadialGradient(cx, cy, r * 0.15, cx, cy, r);
    // Máx. ~65% no miolo: o peão por baixo fica meio encoberto, não some.
    grad.addColorStop(0, `rgba(150,156,166,${a * 0.75})`);
    grad.addColorStop(0.65, `rgba(130,136,146,${a * 0.6})`);
    grad.addColorStop(1, 'rgba(120,126,136,0)');
    ctx.fillStyle = grad;
    ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2); ctx.fill();
    if(f.anel < 1){
      ctx.strokeStyle = `rgba(175,180,188,${0.6 * (1 - f.anel)})`;
      ctx.lineWidth = CELL * 0.12;
      ctx.beginPath(); ctx.arc(cx, cy, (0.3 + f.anel * (n.raio + 0.5)) * CELL, 0, Math.PI * 2); ctx.stroke();
    }
    ctx.restore();
  }
}

function _tickFumaca2D(now){
  _fumaca2DRaf = null;
  _fumacaAvancar(now);
  if(mode3D && g3) return;
  if(!GS.gameState || !_fumacaNuvens.size) return;
  renderMap(GS.gameState);
  if(!_fumacaNuvens.size || _fumaca2DRaf) return;
  // Nascendo/saindo: quadro a quadro. Parada: o pulsar é lento — ~8 quadros/s
  // bastam, e redesenhar o mapa 2D a 60 fps por 2 rodadas seria caro à toa.
  const animando = [..._fumacaNuvens.values()].some(n => {
    const f = _fumacaFase(n, now); return f.antes || f.nasc < 1 || f.saida > 0 || !n.somTocado;
  });
  if(animando) _fumaca2DRaf = _scheduleVisualFrame(_tickFumaca2D);
  else _fumaca2DRaf = setTimeout(() => { _fumaca2DRaf = _scheduleVisualFrame(_tickFumaca2D); }, 120);
}

function _receberAnimacaoArmadilha(msg){
  // Outros popups também usam trap_result; condições e quedas já possuem seus
  // próprios efeitos e não devem receber uma segunda animação de armadilha.
  if(!msg || msg._condition || msg._fall || msg.condition_id || msg.tipo === 'queda') return;
  const pos = _armadilhaPos(msg);
  if(!pos) return;
  const anim = {msg, pos, style:_armadilhaStyle(msg), startedAt:performance.now(), duration:msg.tick ? 720 : 1050, seed:Math.random()*Math.PI*2, group:null};
  _armadilhaAnims.push(anim);
  if(mode3D && g3) _buildArmadilha3D(anim);
  else if(!_armadilha2DRaf) _armadilha2DRaf = _scheduleVisualFrame(_tickArmadilhas2D);
}

// ═══════════════════════════════════════════════════════════════════════════
// PROTETOR — vínculo dourado entre Richard e o aliado protegido
// ═══════════════════════════════════════════════════════════════════════════
// O efeito é derivado do estado autoritativo recebido do servidor. Assim, a
// animação acompanha também desligamento, morte e perda de alcance do alvo.
const _protetorVisuals = new Map();
let _protetorVisualRaf = null;
const PROTETOR_FX_FADE_MS = 900;

function _protetorFind(state, id){
  if(String(id) === '__prisioneiro__') return state?.prisoner || null;
  return (state?.players || []).find(p => String(p.id) === String(id)) || null;
}

function _protetorVisible2D(state, p, visionSet){
  if(!p || !p.alive || !Array.isArray(p.pos)) return false;
  if(p.connected === false || p.engolido || p.bau_engolido || p.fosso_oculto) return false;
  if(p.id === GS.myPid || GS.isMaster?.() || state.test_mode) return true;
  return visionSet.has(`${p.pos[0]},${p.pos[1]}`);
}

function _protetorNeedsRaf(){
  if(!_protetorVisuals.size) return false;
  if(!mode3D) return true;
  return [..._protetorVisuals.values()].some(fx => fx.endingAt != null);
}

function _protetorEnsureRaf(){
  if(_protetorNeedsRaf() && !_protetorVisualRaf)
    _protetorVisualRaf = _scheduleVisualFrame(_tickProtetorVisual);
}

function _syncProtetorVisualState(state){
  if(!state) return;
  const now = performance.now(), seen = new Set();
  for(const richard of (state.players || [])){
    if(!richard.alive || !richard.protetor_ativo || richard.protetor_alvo == null) continue;
    const target = _protetorFind(state, richard.protetor_alvo);
    if(!target || !target.alive) continue;
    const targetKey = target === state.prisoner ? '__prisioneiro__' : target.id;
    const key = `${richard.id}:${targetKey}`;
    seen.add(key);
    let fx = _protetorVisuals.get(key);
    if(!fx){
      fx = {
        // Use a chave especial também no efeito visual: o prisioneiro não é
        // um peão comum e precisa ser resolvido por getPrisonerMesh() no 3D.
        key, richardId:String(richard.id), targetId:String(targetKey),
        startedAt:now, endingAt:null, seed:Math.random()*Math.PI*2,
        group:null, shield:null, core:null, rings:[], sourceCore:null,
        sourceRings:[], linkGlow:null, linkCore:null, chainLinks:[], orb:null,
        sparks:[]
      };
      _protetorVisuals.set(key, fx);
    } else {
      fx.endingAt = null;
    }
    fx.lastSeen = now;
  }
  for(const fx of _protetorVisuals.values()){
    if(!seen.has(fx.key) && fx.endingAt == null) fx.endingAt = now;
  }
  _protetorEnsureRaf();
}

function _protetorFade(fx, now){
  return fx.endingAt == null ? 1 : Math.max(0, 1 - (now - fx.endingAt) / PROTETOR_FX_FADE_MS);
}

function _protetorDraw2D(ctx, state, visionSet, foreground, now){
  if(!ctx || !_protetorVisuals.size) return;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for(const fx of _protetorVisuals.values()){
    const richard = _protetorFind(state, fx.richardId), target = _protetorFind(state, fx.targetId);
    if(!_protetorVisible2D(state, target, visionSet)) continue;
    const fade = _protetorFade(fx, now);
    if(fade <= 0) continue;
    const tx = target.pos[0]*CELL + CELL/2, ty = target.pos[1]*CELL + CELL/2;
    const pulse = .5 + .5*Math.sin(now/260 + fx.seed);
    if(!foreground){
      // Aura de origem: deixa claro que a proteção nasce no paladino, antes
      // de alcançar o aliado. A onda se expande toda vez que o vínculo surge.
      if(_protetorVisible2D(state, richard, visionSet)){
        const rx = richard.pos[0]*CELL + CELL/2, ry = richard.pos[1]*CELL + CELL/2;
        const aura = ctx.createRadialGradient(rx, ry, CELL*.08, rx, ry, CELL*.92);
        aura.addColorStop(0, `rgba(255,248,194,${(.24+.10*pulse)*fade})`);
        aura.addColorStop(.36, `rgba(255,197,54,${(.16+.07*pulse)*fade})`);
        aura.addColorStop(1, 'rgba(255,178,35,0)');
        ctx.fillStyle=aura;ctx.beginPath();ctx.arc(rx,ry,CELL*.92,0,Math.PI*2);ctx.fill();
        const onda=((now-fx.startedAt)%1300)/1300;
        ctx.strokeStyle=`rgba(255,222,110,${(.56*(1-onda)*fade).toFixed(3)})`;
        ctx.lineWidth=Math.max(1.5,CELL*.025);ctx.beginPath();ctx.arc(rx,ry,CELL*(.25+.60*onda),0,Math.PI*2);ctx.stroke();

        // Corrente reta: além do brilho de base, cada elo dourado é desenhado
        // individualmente, alternando a inclinação para parecer uma corrente.
        const dx=tx-rx,dy=ty-ry,dist=Math.hypot(dx,dy),angle=Math.atan2(dy,dx);
        const link = ctx.createLinearGradient(rx, ry, tx, ty);
        link.addColorStop(0, `rgba(255,204,68,${(.38+.15*pulse)*fade})`);
        link.addColorStop(1, `rgba(255,245,180,${(.70+.16*pulse)*fade})`);
        ctx.shadowColor='#ffd45c';ctx.shadowBlur=CELL*.18;ctx.strokeStyle=link;
        ctx.lineWidth=Math.max(2,CELL*.045);ctx.lineCap='round';ctx.beginPath();ctx.moveTo(rx,ry);ctx.lineTo(tx,ty);ctx.stroke();
        const links=Math.max(2,Math.floor(dist/Math.max(8,CELL*.18)));
        ctx.shadowBlur=CELL*.10;ctx.strokeStyle=`rgba(255,239,151,${(.88*fade).toFixed(3)})`;
        ctx.lineWidth=Math.max(1.4,CELL*.026);
        for(let i=0;i<links;i++){
          const u=(i+.5)/links,x=rx+dx*u,y=ry+dy*u;
          ctx.save();ctx.translate(x,y);ctx.rotate(angle+(i%2?Math.PI/2:0));
          ctx.beginPath();ctx.ellipse(0,0,CELL*.090,CELL*.042,0,0,Math.PI*2);ctx.stroke();ctx.restore();
        }
        ctx.shadowBlur=0;
        const travel=Math.min(1,Math.max(0,(now-fx.startedAt)/720));
        if(travel<1){
          const ox=rx+dx*travel,oy=ry+dy*travel;
          ctx.shadowColor='#fff0a6';ctx.shadowBlur=CELL*.24;ctx.fillStyle=`rgba(255,250,194,${(.94*fade).toFixed(3)})`;
          ctx.beginPath();ctx.arc(ox,oy,CELL*(.075+.025*pulse),0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;
        }
      }
      const glow=ctx.createRadialGradient(tx,ty,0,tx,ty,CELL*.92);
      glow.addColorStop(0,`rgba(255,240,156,${(.22+.09*pulse)*fade})`);
      glow.addColorStop(.48,`rgba(255,195,48,${(.15+.06*pulse)*fade})`);
      glow.addColorStop(1,'rgba(255,178,35,0)');
      ctx.fillStyle=glow;ctx.beginPath();ctx.arc(tx,ty,CELL*.92,0,Math.PI*2);ctx.fill();
      continue;
    }
    // Casulo: uma película oval cobre o protegido inteiro, enquanto o selo
    // hexagonal e os anéis dão a leitura de escudo mágico em movimento.
    ctx.save();ctx.translate(tx,ty-CELL*.04);ctx.scale(.78,1.16);
    const shell=ctx.createRadialGradient(0,-CELL*.16,0,0,0,CELL*.64);
    shell.addColorStop(0,`rgba(255,255,220,${(.16+.08*pulse)*fade})`);
    shell.addColorStop(.56,`rgba(255,205,66,${(.08+.045*pulse)*fade})`);
    shell.addColorStop(1,'rgba(255,183,28,0)');
    ctx.fillStyle=shell;ctx.beginPath();ctx.ellipse(0,0,CELL*.54,CELL*.62,0,0,Math.PI*2);ctx.fill();
    ctx.shadowColor='#ffd45c';ctx.shadowBlur=CELL*.18;ctx.strokeStyle=`rgba(255,231,130,${(.74+.16*pulse)*fade})`;
    ctx.lineWidth=Math.max(1.5,CELL*.030);ctx.beginPath();ctx.ellipse(0,0,CELL*.53,CELL*.61,0,0,Math.PI*2);ctx.stroke();
    ctx.shadowBlur=0;ctx.restore();
    const rot = now/1200 + fx.seed, rr = CELL*(.43 + .025*pulse);
    ctx.translate(tx, ty); ctx.rotate(Math.sin(now/900 + fx.seed)*.04);
    ctx.beginPath();
    for(let i=0;i<6;i++){ const a=-Math.PI/2+i*Math.PI/3, x=Math.cos(a)*rr, y=Math.sin(a)*rr*1.16; i?ctx.lineTo(x,y):ctx.moveTo(x,y); }
    ctx.closePath();
    ctx.fillStyle = `rgba(255,195,48,${(.055*fade).toFixed(3)})`; ctx.fill();
    ctx.shadowColor = '#ffd45c'; ctx.shadowBlur = CELL*.13;
    ctx.strokeStyle = `rgba(255,218,103,${(.56 + .18*pulse)*fade})`; ctx.lineWidth = Math.max(2, CELL*.034); ctx.stroke();
    ctx.shadowBlur = 0; ctx.strokeStyle = `rgba(255,249,202,${(.74*fade).toFixed(3)})`;
    ctx.lineWidth = Math.max(1, CELL*.016); ctx.stroke();
    ctx.beginPath(); ctx.arc(0, 0, rr*1.18, rot, rot + Math.PI*1.22); ctx.stroke();
    for(let i=0;i<8;i++){
      const a = rot + i*Math.PI/4, x=Math.cos(a)*CELL*.58, y=Math.sin(a)*CELL*.58;
      ctx.fillStyle = `rgba(255,239,149,${(.48 + .30*Math.sin(now/180+i)**2)*fade})`;
      ctx.beginPath(); ctx.arc(x, y, CELL*(.025 + .012*pulse), 0, Math.PI*2); ctx.fill();
    }
    ctx.restore(); ctx.save(); ctx.globalCompositeOperation='lighter';
  }
  ctx.restore();
}

function _protetorCylinderBetween(mesh, a, b, T){
  const dx=b.x-a.x, dy=b.y-a.y, dz=b.z-a.z, len=Math.sqrt(dx*dx+dy*dy+dz*dz);
  if(!mesh || len < .001) return;
  mesh.position.set((a.x+b.x)/2, (a.y+b.y)/2, (a.z+b.z)/2);
  mesh.scale.set(1, len, 1);
  mesh.quaternion.setFromUnitVectors(new T.Vector3(0,1,0), new T.Vector3(dx,dy,dz).normalize());
}

function _buildProtetor3D(fx){
  if(!g3?.protetorEffectGroup || !window.THREE) return false;
  const T=window.THREE, group=new T.Group(); group.name='protetor-animation';
  const mat=(color, opacity=0) => new T.MeshBasicMaterial({color, transparent:true, opacity,
    depthWrite:false, depthTest:false, blending:T.AdditiveBlending, side:T.DoubleSide});
  // Casulo de luz: núcleo translúcido + malha externa, ambos grandes o
  // bastante para envolver o peão protegido, não apenas um anel no chão.
  const shield=new T.Mesh(new T.IcosahedronGeometry(.78,2), mat(0xffd35a)); shield.material.wireframe=true;
  const core=new T.Mesh(new T.SphereGeometry(.64,20,14), mat(0xffd96a));
  shield.renderOrder=89; core.renderOrder=88; group.add(core,shield);
  fx.shield=shield; fx.core=core;
  for(let i=0;i<3;i++){
    const ring=new T.Mesh(new T.TorusGeometry(.78+i*.052,.016+i*.004,7,32),mat(i===1?0xffffe0:0xffc53d));
    ring.renderOrder=90; group.add(ring); fx.rings.push(ring);
  }
  // Aura de origem no próprio Richard. Ela pulsa antes de alimentar a
  // corrente, deixando explícito quem sustenta a proteção.
  const sourceCore=new T.Mesh(new T.SphereGeometry(.22,14,10),mat(0xffffca));sourceCore.renderOrder=90;group.add(sourceCore);fx.sourceCore=sourceCore;
  for(let i=0;i<3;i++){
    const sourceRing=new T.Mesh(new T.TorusGeometry(.34+i*.11,.018,7,28),mat(i===1?0xffffcc:0xffc13b));
    sourceRing.renderOrder=90;group.add(sourceRing);fx.sourceRings.push(sourceRing);
  }
  const linkMat=mat(0xffc83d), coreMat=mat(0xffffdf);
  const linkGlow=new T.Mesh(new T.CylinderGeometry(.074,.074,1,8,1,true),linkMat);
  const linkCore=new T.Mesh(new T.CylinderGeometry(.022,.022,1,6,1,true),coreMat);
  linkGlow.renderOrder=86; linkCore.renderOrder=87; group.add(linkGlow,linkCore); fx.linkGlow=linkGlow; fx.linkCore=linkCore;
  // Elos físicos da corrente. Mantemos uma reserva e apenas ocultamos os que
  // excedem a distância atual para não recriar geometria a cada movimento.
  for(let i=0;i<28;i++){
    const elo=new T.Mesh(new T.TorusGeometry(.085,.017,6,12),mat(i%2?0xffffd5:0xffca45));
    elo.renderOrder=91;group.add(elo);fx.chainLinks.push(elo);
  }
  const orb=new T.Mesh(new T.SphereGeometry(.105,12,8),mat(0xffffdc)); orb.renderOrder=91; group.add(orb); fx.orb=orb;
  for(let i=0;i<8;i++){const spark=new T.Mesh(new T.SphereGeometry(.035,8,6),mat(0xffffaa));spark.userData.index=i;spark.renderOrder=91;group.add(spark);fx.sparks.push(spark);}
  g3.protetorEffectGroup.add(group); fx.group=group; return true;
}

function _disposeProtetor3D(fx){
  if(!fx?.group) return;
  if(fx.group.parent) fx.group.parent.remove(fx.group);
  fx.group.traverse(o=>{if(o.geometry)o.geometry.dispose();if(o.material)(Array.isArray(o.material)?o.material:[o.material]).forEach(m=>m.dispose());});
  fx.group=null; fx.shield=fx.core=fx.sourceCore=fx.linkGlow=fx.linkCore=fx.orb=null;
  fx.rings=[]; fx.sourceRings=[]; fx.chainLinks=[]; fx.sparks=[];
}

function _atualizarProtetor3D(now){
  if(!g3?.protetorEffectGroup || !window.THREE) return;
  const T=window.THREE;
  for(const fx of _protetorVisuals.values()){
    if(fx.group && fx.group.parent!==g3.protetorEffectGroup) _disposeProtetor3D(fx);
    if(!fx.group && !_buildProtetor3D(fx)) continue;
    const richard=getPeaoMesh(fx.richardId);
    const target=String(fx.targetId)==='__prisioneiro__' ? getPrisonerMesh() : getPeaoMesh(fx.targetId);
    if(!richard || !target){fx.group.visible=false;continue;}
    fx.group.visible=true;
    const a=new T.Vector3(), b=new T.Vector3(); richard.getWorldPosition(a); target.getWorldPosition(b);
    a.y+=.78; b.y+=.72;
    const fade=_protetorFade(fx,now), appear=Math.min(1,Math.max(0,(now-fx.startedAt)/560)), pulse=.5+.5*Math.sin(now/250+fx.seed);
    fx.group.visible=fade>0; if(!fx.group.visible) continue;
    _protetorCylinderBetween(fx.linkGlow,a,b,T); _protetorCylinderBetween(fx.linkCore,a,b,T);
    fx.linkGlow.material.opacity=(.27+.13*pulse)*fade*appear;
    fx.linkCore.material.opacity=(.70+.20*pulse)*fade*appear;
    // Corrente reta de elos dourados, alternando a orientação. A linha de
    // energia continua por baixo para a conexão nunca desaparecer à distância.
    const delta=b.clone().sub(a),dist=delta.length(),dir=delta.normalize();
    const up=new T.Vector3(0,1,0),normal=new T.Vector3().crossVectors(dir,up);
    if(normal.lengthSq()<.001) normal.set(1,0,0); else normal.normalize();
    const eloQ=new T.Quaternion().setFromUnitVectors(new T.Vector3(0,0,1),normal);
    const eloStep=.19,elosAtivos=Math.min(fx.chainLinks.length,Math.max(2,Math.floor(dist/eloStep)));
    for(let i=0;i<fx.chainLinks.length;i++){
      const elo=fx.chainLinks[i];
      if(i>=elosAtivos){elo.visible=false;continue;}
      const u=(i+.5)/elosAtivos;
      elo.visible=true;elo.position.copy(a).lerp(b,u);
      elo.quaternion.copy(eloQ);
      elo.rotateZ(i%2?Math.PI/2:0);
      const eloPulse=.78+.22*Math.sin(now/130+i*.9);
      elo.scale.setScalar((.88+.10*eloPulse)*appear);
      elo.material.opacity=(.58+.27*eloPulse)*fade*appear;
    }
    const chargePos=a.clone().lerp(b,Math.min(1,Math.max(0,(now-fx.startedAt)/720)));
    fx.orb.position.copy(chargePos); fx.orb.scale.setScalar(.75+.35*pulse); fx.orb.material.opacity=.90*fade*appear;
    fx.shield.position.copy(b); fx.core.position.copy(b);
    fx.shield.scale.set(.88+.06*pulse,1.18+.10*pulse,.88+.06*pulse); fx.core.scale.set(.88+.08*pulse,1.16+.10*pulse,.88+.08*pulse);
    fx.shield.rotation.y=now/1200+fx.seed; fx.shield.rotation.x=.10*Math.sin(now/800+fx.seed);
    fx.shield.material.opacity=(.45+.18*pulse)*fade*appear; fx.core.material.opacity=(.11+.06*pulse)*fade*appear;
    for(let i=0;i<fx.rings.length;i++){const ring=fx.rings[i];ring.position.copy(b);ring.rotation.x=i===1?0:Math.PI/2;ring.rotation.y=i===1?now/980:0;ring.rotation.z=now/(720+i*120)+i;ring.material.opacity=(.34+.18*pulse)*(i===1?.72:1)*fade*appear;}
    fx.sourceCore.position.copy(a);fx.sourceCore.scale.setScalar(.82+.30*pulse);fx.sourceCore.material.opacity=(.42+.24*pulse)*fade*appear;
    for(let i=0;i<fx.sourceRings.length;i++){
      const ring=fx.sourceRings[i];ring.position.copy(a);ring.position.y-=.42;
      ring.rotation.x=Math.PI/2;ring.rotation.z=now/(510+i*160)*(i%2?1:-1);
      ring.scale.setScalar(.84+.18*pulse+i*.035);ring.material.opacity=(.38+.20*pulse)*(1-i*.12)*fade*appear;
    }
    for(const spark of fx.sparks){const i=spark.userData.index,a0=now/(430+(i%3)*90)+i*Math.PI/4,r=.70+.08*Math.sin(now/370+i);spark.position.set(b.x+Math.cos(a0)*r,b.y-.05+.16*Math.sin(now/300+i),b.z+Math.sin(a0)*r);spark.scale.setScalar(.75+.35*pulse);spark.material.opacity=(.35+.40*Math.sin(now/115+i)**2)*fade*appear;}
  }
}

function _tickProtetorVisual(now){
  _syncProtetorVisualState(GS.gameState);
  for(const [key,fx] of _protetorVisuals){
    if(fx.endingAt!=null && now-fx.endingAt>PROTETOR_FX_FADE_MS){_disposeProtetor3D(fx);_protetorVisuals.delete(key);}
  }
  if(mode3D&&g3) _atualizarProtetor3D(now);
  if(!mode3D&&GS.gameState&&_protetorVisuals.size) renderMap(GS.gameState);
  _protetorVisualRaf=_protetorNeedsRaf()?_scheduleVisualFrame(_tickProtetorVisual):null;
}

function renderMap(state){
  if(!state.tiles) return;
  state = _estadoComMortosVisuais(state);
  if(!mode3D) _ensureCancaoHeroicaAura2D(state);
  _guardaMaximaSyncState(state);
  _syncInvisibilidadeState(state);
  _syncProtecaoEnergiaState(state);
  _syncProtetorVisualState(state);
  _tempestadeSyncFromState(state);
  _fumacaSync(state);
  _requiemFinalSyncFromState(state);
  _atualizarZonasMagia(state);   // zonas persistentes (Bola de Fogo) — vale p/ 2D e 3D
  if(mode3D){ renderMap3D(state); return; }
  if(_armadilhaAnims.length && !_armadilha2DRaf)
    _armadilha2DRaf = _scheduleVisualFrame(_tickArmadilhas2D);
  const canvas=$('dungeon-canvas');
  const W=state.tiles[0].length, H=state.tiles.length;
  applyDPR(canvas, W*CELL, H*CELL);
  const ctx=canvas.getContext('2d');

  let exploredSet=new Set(state.explored.map(([x,y])=>`${x},${y}`));
  // Terreno visível AO VIVO: explorado (permanente) + revelado (Clarividência e
  // visão dos minions). Tiles só-revelados revertem à névoa sozinhos quando o
  // minion sai (state.revealed encolhe no próximo broadcast). exploredSet segue
  // governando lógica (BFS/alcance) — terrainSet governa só o desenho do mapa.
  const revealedSet=new Set((state.revealed||[]).map(([x,y])=>`${x},${y}`));
  let terrainSet = revealedSet.size
    ? new Set([...exploredSet, ...revealedSet]) : exploredSet;
  // Mestre: sem névoa — trata o mapa inteiro como "explorado/revelado", o que
  // também libera de graça baús/armadilhas/escadas/marcadores de sala (todos
  // gateados por exploredSet mais abaixo). BFS/alcance não usam isto para o
  // Mestre pois `me` é undefined (ele não é um herói em state.players).
  if(GS.isMaster() || state.test_mode){
    const full = new Set();
    for(let y=0;y<H;y++) for(let x=0;x<W;x++) full.add(`${x},${y}`);
    exploredSet = full;
    terrainSet  = full;
  }
  const me=state.players.find(p=>p.id===GS.myPid&&p.alive);
  const testeHeroiAtivo = state.test_mode ? _testeHeroiAtivoNoMapa(state) : null;
  const testeHeroiSelecionado = state.test_mode ? _testeHeroiSelecionado(state) : null;
  const testeHeroiControlado = testeHeroiSelecionado && testeHeroiAtivo
    && String(testeHeroiSelecionado.id) === String(testeHeroiAtivo.id)
    ? testeHeroiSelecionado : null;
  let visionSet=computeVisionSet(state, me);
  if(GS.isMaster() || state.test_mode) visionSet = new Set(exploredSet);
  const {closed:doorClosed} = GS.doorSets(state);

  const isAnimadosTurn2D = state.animados_turn === GS.myPid;
  const meAnimados2D = (state.players.find(p=>p.id===GS.myPid)?.animados||[]).filter(a=>a.vida_atual>0);
  const selAnimado2D = isAnimadosTurn2D && _animadoSel
    ? meAnimados2D.find(a=>a.id===_animadoSel) : null;
  const meuPris2D = state.prisoner && state.prisoner.alive && state.prisoner.freed
    && state.prisoner.rescuer_pid === GS.myPid;
  const selPris2D = isAnimadosTurn2D && _prisSel && meuPris2D ? state.prisoner : null;

  const reachable=new Set();
  if(selAnimado2D && selAnimado2D.moves_left>0)
    bfsReachable(state.tiles,exploredSet,selAnimado2D.pos[0],selAnimado2D.pos[1],selAnimado2D.moves_left,reachable);
  else if(selPris2D && (selPris2D.moves_left||0)>0)
    bfsReachable(state.tiles,exploredSet,selPris2D.pos[0],selPris2D.pos[1],selPris2D.moves_left,reachable);
  else if(!isAnimadosTurn2D&&GS.isMyTurn&&me&&me.moves_left>0)
    bfsReachable(state.tiles,exploredSet,me.pos[0],me.pos[1],me.moves_left,reachable);
  if(testeHeroiControlado && (testeHeroiControlado.moves_left || 0) > 0){
    bfsReachable(state.tiles, exploredSet, testeHeroiControlado.pos[0], testeHeroiControlado.pos[1],
      testeHeroiControlado.moves_left, reachable,
      {state, materiais: state.materiais, actor: testeHeroiControlado});
  }

  if(GS.isMaster()){
    _masterReachSet(state).forEach(k => reachable.add(k));
  }

  const attackable=new Set();
  // Ataque do jogador (apenas no próprio turno, fora do turno dos servos)
  if(!isAnimadosTurn2D&&GS.isMyTurn&&me&&!me.action_done){
    const wRng=me.weapon?.range??null;
    for(const m of state.monsters){
      if(!m||m.hp<=0||m._morteVisualPendente) continue;
      const dx=Math.abs(me.pos[0]-m.pos[0]), dy=Math.abs(me.pos[1]-m.pos[1]);
      const inR=_alvoNoAlcanceArmaClient(me, m.pos[0], m.pos[1], m.altura)
        && (wRng == null || GS.hasLineOfSight(state, me.pos[0],me.pos[1], m.pos[0],m.pos[1]));
      if(inR) attackable.add(`${m.pos[0]},${m.pos[1]}`);
    }
  }
  if(testeHeroiControlado && !testeHeroiControlado.action_done){
    for(const m of state.monsters || []){
      if(!m || m.hp <= 0 || m._morteVisualPendente) continue;
      for(const [tx,ty] of GS.monsterTiles(m)){
        if(GS.weaponCanReachTile(testeHeroiControlado, tx, ty, m.altura)
          && (testeHeroiControlado.weapon?.range == null
            || GS.hasLineOfSight(state, testeHeroiControlado.pos[0], testeHeroiControlado.pos[1], tx, ty, testeHeroiControlado)))
          attackable.add(`${tx},${ty}`);
      }
    }
  }
  // Alcance de ataque do animado selecionado (turno dos servos) ou em hover — aditivo
  // Regra unica em GS.animadoAttackTargetTiles — esta copia cravava
  // "cardinal, alcance 1 (ou 3)" e mentia para servos elementais de alcance maior.
  const atkRefAnimado2D = selAnimado2D || window._animadoHover;
  for(const alvo of GS.animadoAttackTargetTiles(atkRefAnimado2D))
    attackable.add(`${alvo.x},${alvo.y}`);
  for(const tile of GS.animadoAttackRangeTiles(atkRefAnimado2D))
    attackable.add(`${tile.x},${tile.y}`);
  if(GS.isMaster()){
    _masterAttackSet(state).forEach(k => attackable.add(k));
  }

  const weaponRangeTiles = ((window._weaponRangePreview || window._gamepadAttackRangePreview) && me && !isAnimadosTurn2D)
    ? _computeWeaponRangeTiles(state, me) : new Set();
  const ataqueGiratorioTiles = (window._ataqueGiratorioPreview && me && !isAnimadosTurn2D)
    ? _ataqueGiratorioPreviewTiles(state, me) : new Set();

  // Durante a mira de magia/arremesso, oculta realces de movimento/ataque (mostra alcance/área).
  if(_aimSessionIs() || window._modoMagia || window._modoMestreMira || window._modoThrowItem || window._modoAnimarMortos){ reachable.clear(); attackable.clear(); }

  // A base pesada do tabuleiro é restaurada de um canvas em cache. Os
  // realces, efeitos e peões continuam no canvas visível para preservar a
  // ordem correta de profundidade.
  const staticDungeon = _staticDungeon2D(state, terrainSet, doorClosed, W, H);
  ctx.drawImage(staticDungeon, 0, 0, W * CELL, H * CELL);

  // Lava e pântano ficam acima do piso, mas abaixo das entidades e dos
  // efeitos de combate. Somente estes detalhes são recalculados por quadro.
  _drawAnimatedTerrain2D(ctx, state, terrainSet, performance.now());

  const highlightTiles = new Set([...reachable, ...attackable, ...weaponRangeTiles, ...ataqueGiratorioTiles]);
  const bridgeTiles2D = new Set();
  for(const bridge of (state.pontes || []))
    for(const [bx, by] of _bridgeTiles2D(bridge)) bridgeTiles2D.add(`${bx},${by}`);
  for(const key of highlightTiles){
    if(!terrainSet.has(key)) continue;
    const [x, y] = key.split(',').map(Number);
    if(!Number.isInteger(x) || !Number.isInteger(y)) continue;
    const tile = state.tiles[y]?.[x];
    if(tile !== TILE_FLOOR && tile !== TILE_DOOR && !bridgeTiles2D.has(key)) continue;
    _drawFloorHighlights2D(ctx, x, y,
      reachable.has(key), attackable.has(key),
      weaponRangeTiles.has(key) || ataqueGiratorioTiles.has(key));
  }
  _drawGamepadCursor2D(ctx, state, terrainSet, performance.now());

  // ── PASS 1.5: Realce de mira — alcance (azul), zona (laranja), alvo/área (verde)
  _desenharSpellHL2D(ctx, exploredSet);
  _desenharSpellTargetPreview2D(ctx, state, exploredSet);
  _desenharSpellDirection2D(ctx, state);
  for(const _animSenhorAguas of _senhorAguasAnims)
    _senhorAguasDraw2D(ctx, state, _animSenhorAguas, performance.now());
  for(const _animIraRocha of _iraRochaAnims)
    _iraRochaDraw2D(ctx, state, _animIraRocha, performance.now());
  for(const _animTempestade of _tempestadeAnims)
    _tempestadeDraw2D(ctx, state, _animTempestade, performance.now());
  for(const _animTurbilhao of _turbilhaoElementalAnims)
    _turbilhaoElementalDraw2D(ctx, state, _animTurbilhao, performance.now());
  for(const _animPrivacao of _privacaoAnims)
    _privacaoDraw2D(ctx, state, _animPrivacao, performance.now());
  for(const _animPrisaoChamas of _prisaoChamasAnims)
    _prisaoChamasDraw2D(ctx, state, _animPrisaoChamas, performance.now());
  for(const _animMantoEsc of _mantoEscuridaoAnims)
    _mantoEscuridaoDraw2D(ctx, state, _animMantoEsc, performance.now());
  for(const _animClarividencia of _clarividenciaAnims)
    _clarividenciaDraw2D(ctx, state, _animClarividencia, performance.now());
  for(const _animRegeneracao of _regeneracaoAnims)
    _regeneracaoDraw2D(ctx, state, _animRegeneracao, performance.now());
  for(const _animLentidao of _lentidaoAnims)
    _lentidaoDraw2D(ctx, state, _animLentidao, performance.now());
  for(const _animVelocidade of _velocidadeAnims)
    _velocidadeDraw2D(ctx, state, _animVelocidade, performance.now());
  for(const _animSilencio of _silencioAnims)
    _silencioDraw2D(ctx, state, _animSilencio, performance.now());
  for(const _animMedo of _medoAnims)
    _medoDraw2D(ctx, state, _animMedo, performance.now());
  for(const _animBarreira of _barreiraAnims)
    _barreiraDraw2D(ctx, state, _animBarreira, performance.now());
  for(const _animMaldicao of _maldicaoAnims)
    _maldicaoDraw2D(ctx, state, _animMaldicao, performance.now());
  for(const _animRaioDivino of _raioDivinoAnims)
    _raioDivinoDraw2D(ctx, state, _animRaioDivino, performance.now());
  for(const _animProtecao of _protecaoEnergiaAnims)
    _protecaoEnergiaDraw2D(ctx, state, _animProtecao, performance.now());

  // ── PASS 1.6: Explosão do Elemental de Fogo — overlay vermelho pulsante
  if(_explosionTiles && _explosionTiles.size){
    const pulse = 0.55 + 0.40 * (0.5 + 0.5 * Math.sin(performance.now() / 80));
    ctx.save();
    ctx.fillStyle = `rgba(255,60,0,${(0.38 * pulse).toFixed(3)})`;
    ctx.strokeStyle = `rgba(255,120,0,${(0.90 * pulse).toFixed(3)})`;
    ctx.lineWidth = 2.5;
    for(const key of _explosionTiles){
      const [ex,ey] = key.split(',').map(Number);
      if(!exploredSet.has(key)) continue;
      const EX=ex*CELL, EY=ey*CELL;
      ctx.fillRect(EX+1,EY+1,CELL-2,CELL-2);
      ctx.strokeRect(EX+2,EY+2,CELL-4,CELL-4);
    }
    ctx.restore();
  }

  // Fogo residual da Bola de Fogo: fica no chão, sob os peões, e pulsa
  // enquanto a zona autoritativa permanecer ativa.
  _desenharFogoPersistente2D(ctx, exploredSet, performance.now());

  // ── PASS 4: Impenetrable fog on unexplored tiles (Diablo-style pitch-black)
  // (no-op for the Mestre — terrainSet is the full map, see above)
  ctx.fillStyle='rgba(4,3,8,0.96)';
  for(let y=0;y<H;y++) for(let x=0;x<W;x++){
    if(!terrainSet.has(`${x},${y}`))
      ctx.fillRect(x*CELL, y*CELL, CELL, CELL);
  }
  _desenharAimHover2D(ctx);   // cursor da mira por cima da névoa — ver a função

  // ── PASS 5: Dramatic Diablo torchlight (multi-layer, orange-red inferno glow)
  if(me){
    const lcx=me.pos[0]*CELL+CELL/2, lcy=me.pos[1]*CELL+CELL/2;
    // Hot spot (intense orange-white at player)
    const g1=ctx.createRadialGradient(lcx,lcy,0,lcx,lcy,CELL*2.2);
    g1.addColorStop(0,   'rgba(255,230,120,0.32)');
    g1.addColorStop(0.35,'rgba(255,160,40,0.18)');
    g1.addColorStop(1,   'rgba(0,0,0,0)');
    ctx.fillStyle=g1; ctx.fillRect(0,0,W*CELL,H*CELL);
    // Mid-range warm amber
    const g2=ctx.createRadialGradient(lcx,lcy,0,lcx,lcy,CELL*5);
    g2.addColorStop(0,   'rgba(255,130,20,0.14)');
    g2.addColorStop(0.50,'rgba(220,80,10,0.08)');
    g2.addColorStop(1,   'rgba(0,0,0,0)');
    ctx.fillStyle=g2; ctx.fillRect(0,0,W*CELL,H*CELL);
    // Long-range atmospheric red (hellish dungeon ambience)
    const g3=ctx.createRadialGradient(lcx,lcy,0,lcx,lcy,CELL*8);
    g3.addColorStop(0,   'rgba(180,50,10,0.08)');
    g3.addColorStop(0.60,'rgba(100,20,5,0.04)');
    g3.addColorStop(1,   'rgba(0,0,0,0)');
    ctx.fillStyle=g3; ctx.fillRect(0,0,W*CELL,H*CELL);
  }
  // Static wall torch sconces — small orange glow on explored wall tiles
  for(let ty=0;ty<H;ty++) for(let tx=0;tx<W;tx++){
    if(!exploredSet.has(`${tx},${ty}`)) continue;
    if(state.tiles[ty][tx]!==TILE_WALL) continue;
    // Only occasional wall tiles get a torch (deterministic by position)
    const th=((tx*3761)^(ty*2399))&0xFF;
    if(th%7!==0) continue;
    // Check that a floor tile is adjacent (torches on walls near walkable areas)
    const hasFloorNear=[[0,1],[0,-1],[1,0],[-1,0]].some(([dx,dy])=>{
      const nx=tx+dx, ny=ty+dy;
      return nx>=0&&ny>=0&&nx<W&&ny<H && state.tiles[ny][nx]===TILE_FLOOR && exploredSet.has(`${nx},${ny}`);
    });
    if(!hasFloorNear) continue;
    const tcx=tx*CELL+CELL/2, tcy=ty*CELL+CELL/2;
    const tG=ctx.createRadialGradient(tcx,tcy,0,tcx,tcy,CELL*2.5);
    tG.addColorStop(0,   'rgba(255,180,50,0.18)');
    tG.addColorStop(0.35,'rgba(255,110,20,0.09)');
    tG.addColorStop(1,   'rgba(0,0,0,0)');
    ctx.fillStyle=tG; ctx.fillRect(0,0,W*CELL,H*CELL);
    // Small torch flame dot on the wall
    ctx.fillStyle='rgba(255,200,80,0.85)';
    ctx.beginPath(); ctx.arc(tcx,tcy,3,0,Math.PI*2); ctx.fill();
    ctx.fillStyle='rgba(255,255,200,0.6)';
    ctx.beginPath(); ctx.arc(tcx,tcy,1.2,0,Math.PI*2); ctx.fill();
  }

  // ── PASS 6: Edge vignette (dark corners — claustrophobic dungeon feel)
  const vW=W*CELL, vH=H*CELL;
  const vig=ctx.createRadialGradient(vW/2,vH/2,Math.min(vW,vH)*0.28,vW/2,vH/2,Math.max(vW,vH)*0.85);
  vig.addColorStop(0,'rgba(0,0,0,0)');
  vig.addColorStop(0.65,'rgba(0,0,0,0.10)');
  vig.addColorStop(1,'rgba(0,0,0,0.72)');
  ctx.fillStyle=vig; ctx.fillRect(0,0,vW,vH);

  // ── Canção Heroica: anel dourado de raio 5 ───────────────────────────────
  // O bardo já usava este indicador. No modo de teste, os Xamãs controlados
  // pelo Mestre usam exatamente a mesma leitura visual, sem criar buffs locais
  // no cliente (os bônus continuam autoritativos no servidor).
  const _cantores = state.players
    .filter(p => p.class_id === 'bard' && p.alive && p.cancao_ativa)
    .concat(state.test_mode ? (state.monsters || []).filter(m =>
      m && m.hp > 0 && m.cancao_ativa && Array.isArray(m.pos)) : []);
  for(const _cantor of _cantores){
    if(!_cantor.pos || !exploredSet.has(`${_cantor.pos[0]},${_cantor.pos[1]}`)) continue;
    const cx = _cantor.pos[0] * CELL + CELL / 2;
    const cy = _cantor.pos[1] * CELL + CELL / 2;
    const r = (CANCAO_RAIO_CLIENT + 0.5) * CELL;
    const pulso = 0.62 + 0.20 * (0.5 + 0.5 * Math.sin(performance.now() / 520));
    ctx.save();
    ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(229,190,83,0.105)'; ctx.fill();
    ctx.lineWidth = Math.max(3, CELL * 0.055);
    ctx.strokeStyle = `rgba(255,211,104,${pulso.toFixed(3)})`;
    ctx.shadowColor = 'rgba(255,196,73,0.95)'; ctx.shadowBlur = Math.max(8, CELL * 0.22);
    ctx.stroke();
    ctx.setLineDash([Math.max(5, CELL * 0.16), Math.max(4, CELL * 0.12)]);
    ctx.lineWidth = Math.max(1.3, CELL * 0.025);
    ctx.strokeStyle = `rgba(255,247,202,${(pulso * 0.72).toFixed(3)})`;
    ctx.beginPath(); ctx.arc(cx, cy, r - Math.max(4, CELL * 0.07), -performance.now()/2400, Math.PI*2 - performance.now()/2400); ctx.stroke();
    ctx.setLineDash([]);
    ctx.restore();
  }

  // ── Room markers (chest / boss / trap icons)
  ctx.textAlign='center'; ctx.textBaseline='middle';
  for(const room of state.rooms){
    if(room.cleared||!exploredSet.has(`${room.cx},${room.cy}`)) continue;
    const icon={chest:'🎁',boss:'☠️',trap:'⚠'}[room.role];
    if(!icon) continue;
    const X=room.cx*CELL, Y=room.cy*CELL;
    ctx.fillStyle='rgba(0,0,0,0.55)'; ctx.fillRect(X+8,Y+8,CELL-16,CELL-16);
    ctx.font=`${Math.round(CELL*0.62)}px serif`; ctx.fillText(icon,X+CELL/2,Y+CELL/2);
  }

  // ── Traps
  for(const trap of state.traps){
    const [tx,ty]=trap.pos;
    if(!exploredSet.has(`${tx},${ty}`)) continue;
    const X=tx*CELL, Y=ty*CELL;
    ctx.fillStyle='rgba(200,30,30,0.22)'; ctx.fillRect(X+4,Y+4,CELL-8,CELL-8);
    ctx.font=`${Math.round(CELL*0.55)}px serif`; ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.fillText('⚠',X+CELL/2,Y+CELL/2);
  }

  // ── Armadilhas colocáveis (Passo 2) — borda verde = aliada; vermelha = ativada
  {
  const _meArm = state.players.find(p=>p.id===GS.myPid);
  for(const arm of (state.armadilhas||[])){
    const [ax,ay]=arm.pos;
    if(!exploredSet.has(`${ax},${ay}`)) continue;
    if(!_armadilhaVisivelParaMim(arm, _meArm)) continue;   // escondida até ser revelada
    const X=ax*CELL, Y=ay*CELL;
    ctx.fillStyle = arm.ativada ? 'rgba(255,70,55,0.28)' : 'rgba(110,200,120,0.18)';
    ctx.fillRect(X+4,Y+4,CELL-8,CELL-8);
    ctx.lineWidth=2;
    ctx.strokeStyle = arm.ativada ? 'rgba(255,70,55,0.85)'
                    : arm.aliada ? 'rgba(110,210,120,0.75)' : 'rgba(255,150,40,0.75)';
    ctx.strokeRect(X+4.5,Y+4.5,CELL-9,CELL-9);
    // Imagem (PNG de assets/objetos) cobre o tile, mantendo proporção; senão, o ícone.
    const _aImg = arm.image ? _getArmadilha2DImg(arm.image) : null;
    if(_aImg){
      const ar = _aImg.naturalWidth / _aImg.naturalHeight;
      let dw = CELL-8, dh = (CELL-8)/ar;
      if(dh > CELL-8){ dh = CELL-8; dw = (CELL-8)*ar; }
      ctx.drawImage(_aImg, X+(CELL-dw)/2, Y+(CELL-dh)/2, dw, dh);
    } else {
      ctx.font=`${Math.round(CELL*0.5)}px serif`; ctx.textAlign='center'; ctx.textBaseline='middle';
      ctx.fillText(arm.icone||'🪤',X+CELL/2,Y+CELL/2);
    }
  }
  }

  // ── Stairs (dungeon entrance / exit)
  if(state.stairs_pos){
    const [sx,sy]=state.stairs_pos;
    if(exploredSet.has(`${sx},${sy}`)){
      const X=sx*CELL, Y2=sy*CELL;
      // Stone step tones
      ctx.fillStyle='rgba(60,42,18,0.72)'; ctx.fillRect(X+3,Y2+3,CELL-6,CELL-6);
      ctx.strokeStyle='rgba(180,130,40,0.55)'; ctx.lineWidth=1;
      const steps=4, sh=(CELL-14)/steps;
      for(let s=0;s<steps;s++){
        const sy2=Y2+7+s*sh;
        ctx.fillStyle=`rgba(${90+s*12},${65+s*9},${28+s*7},0.65)`;
        ctx.fillRect(X+6+s*3,sy2,CELL-14-s*6,sh-1);
        ctx.strokeRect(X+6+s*3+0.5,sy2+0.5,CELL-15-s*6,sh-2);
      }
      // Persistent gold glow (staircase is always interactive)
      const gst=ctx.createRadialGradient(X+CELL/2,Y2+CELL/2,0,X+CELL/2,Y2+CELL/2,CELL*0.75);
      gst.addColorStop(0,'rgba(255,210,60,0.28)');
      gst.addColorStop(1,'rgba(0,0,0,0)');
      ctx.fillStyle=gst; ctx.fillRect(X-CELL/4,Y2-CELL/4,CELL*1.5,CELL*1.5);
      // Icon
      ctx.font=`${Math.round(CELL*0.45)}px serif`; ctx.textAlign='center'; ctx.textBaseline='middle';
      ctx.fillText('🪜',X+CELL/2,Y2+CELL/2);
      // Small label
      ctx.font=`bold ${Math.round(CELL*0.16)}px monospace`; ctx.textAlign='center'; ctx.textBaseline='top';
      ctx.fillStyle='rgba(255,220,80,0.90)';
      ctx.fillText(t('ui.tabuleiro.saida'),X+CELL/2,Y2+CELL-14);
    }
  }

  if(state.start_mode === 'hero_spawns'){
    // Só o EMOJI mora aqui; o nome curto da classe vem de ui.classe_curta.*
    // (o nome de catálogo, "Guerreiro Anão", não cabe no rótulo da casa).
    const spawnEmoji = {
      warrior:'⚔️', mage:'🔮', rogue:'🗡️', cleric:'✚', bard:'🎻', paladin:'🛡️'
    };
    for(const hs of (state.hero_spawns||[])){
      const [hx,hy]=hs.pos||[];
      if(!Number.isInteger(hx)||!Number.isInteger(hy)||!exploredSet.has(`${hx},${hy}`)) continue;
      const X=hx*CELL, Y2=hy*CELL;
      const meta=[spawnEmoji[hs.class_id]||'⚔️',
                  _rotulo(hs.class_id, 'ui.classe_curta', hs.class_id||t('ui.tabuleiro.heroi'))];
      const hgl=ctx.createRadialGradient(X+CELL/2,Y2+CELL/2,0,X+CELL/2,Y2+CELL/2,CELL*0.72);
      hgl.addColorStop(0,'rgba(150,110,255,0.34)'); hgl.addColorStop(1,'rgba(0,0,0,0)');
      ctx.fillStyle=hgl; ctx.fillRect(X-CELL/4,Y2-CELL/4,CELL*1.5,CELL*1.5);
      ctx.font=`${Math.round(CELL*0.43)}px serif`; ctx.textAlign='center'; ctx.textBaseline='middle';
      ctx.fillText(meta[0],X+CELL/2,Y2+CELL/2);
      ctx.font=`bold ${Math.round(CELL*0.14)}px monospace`; ctx.textBaseline='top';
      ctx.fillStyle='rgba(205,180,255,0.95)'; ctx.fillText(t('ui.tabuleiro.inicio', {classe:meta[1].toUpperCase()}),X+CELL/2,Y2+CELL-13);
    }
  }

  // ── Exit tile (Fase 3 — masmorra autorada): bandeira de chegada 🏁
  if(GS.exitPos){
    const [ex,ey]=GS.exitPos;
    if(exploredSet.has(`${ex},${ey}`)){
      const X=ex*CELL, Y2=ey*CELL;
      // Glow azul-esverdeado (distinto do dourado da escada)
      const egl=ctx.createRadialGradient(X+CELL/2,Y2+CELL/2,0,X+CELL/2,Y2+CELL/2,CELL*0.78);
      egl.addColorStop(0,'rgba(60,220,180,0.32)');
      egl.addColorStop(1,'rgba(0,0,0,0)');
      ctx.fillStyle=egl; ctx.fillRect(X-CELL/4,Y2-CELL/4,CELL*1.5,CELL*1.5);
      ctx.font=`${Math.round(CELL*0.5)}px serif`; ctx.textAlign='center'; ctx.textBaseline='middle';
      ctx.fillText('🏁',X+CELL/2,Y2+CELL/2);
      ctx.font=`bold ${Math.round(CELL*0.16)}px monospace`; ctx.textAlign='center'; ctx.textBaseline='top';
      ctx.fillStyle='rgba(80,230,190,0.92)';
      ctx.fillText('CHEGADA',X+CELL/2,Y2+CELL-14);
    }
  }

  // ── Physical chests (2D overlay — gold glow + icon)
  ctx.textAlign='center'; ctx.textBaseline='middle';
  for(const chest of (state.chests||[])){
    const [cx2,cy2]=chest.pos;
    if(!exploredSet.has(`${cx2},${cy2}`)) continue;
    const X=cx2*CELL, Y=cy2*CELL;
    // Gold glow halo
    const cglow=ctx.createRadialGradient(X+CELL/2,Y+CELL/2,0,X+CELL/2,Y+CELL/2,CELL*0.82);
    cglow.addColorStop(0,'rgba(255,200,40,0.38)');
    cglow.addColorStop(1,'rgba(0,0,0,0)');
    ctx.fillStyle=cglow; ctx.fillRect(X,Y,CELL,CELL);
    // Imagem do baú (mesma arte da Arca de Tesouros). O emoji só aparece
    // enquanto o PNG não carregou (ou se o arquivo faltar).
    const chestImg=_getObjeto2DImg('bau.png');
    if(chestImg){
      const S=CELL*0.86;
      ctx.drawImage(chestImg,X+(CELL-S)/2,Y+(CELL-S)/2,S,S);
    } else {
      ctx.font=`${Math.round(CELL*0.58)}px serif`;
      ctx.fillText('🎁',X+CELL/2,Y+CELL/2);
    }
    // Item count badge
    const total=(chest.items||[]).length+(chest.gold>0?1:0);
    if(total>0){
      ctx.font=`bold ${Math.round(CELL*0.18)}px monospace`;
      ctx.fillStyle='#ffe060'; ctx.fillText(`×${total}`,X+CELL/2,Y+CELL-10);
    }
  }

  // ── Itens largados no chão (2D — brilho verde suave + emoji do item)
  for(const gi of (state.ground_items||[])){
    const [gx,gy]=gi.pos;
    if(!exploredSet.has(`${gx},${gy}`)) continue;
    const X=gx*CELL, Y=gy*CELL;
    const gglow=ctx.createRadialGradient(X+CELL/2,Y+CELL/2,0,X+CELL/2,Y+CELL/2,CELL*0.55);
    gglow.addColorStop(0,gi.kind==='gold'?'rgba(255,198,64,0.34)':'rgba(140,220,140,0.30)');
    gglow.addColorStop(1,'rgba(0,0,0,0)');
    ctx.fillStyle=gglow; ctx.fillRect(X,Y,CELL,CELL);
    ctx.font=`${Math.round(CELL*0.5)}px serif`;
    ctx.fillStyle='#fff';
    ctx.fillText((gi.item&&gi.item.emoji)||'📦',X+CELL/2,Y+CELL/2);
  }

  // Segredos: o ladino os vê com Encontrar Armadilhas; Clarividência também os
  // revela temporariamente para todo o grupo, sem abrir mecanismos.
  const _detectSecrets = !!(me && me.class_id === 'rogue' && me.detectar_ativo);
  const _secretKeyIds = new Set((state.secret_passages || []).filter(sp => !sp.opened && sp.type === 'mechanism')
    .flatMap(sp => sp.key_decor_ids || []));
  for (const sp of (state.secret_passages || [])) {
    const [sx, sy] = sp.pos;
    const revealedByMagic = !!sp.revealed_by_clarividencia;
    if ((!_detectSecrets && !revealedByMagic) || !exploredSet.has(`${sx},${sy}`) || sp.opened) continue;
    ctx.save();
    ctx.fillStyle = sp.type === 'illusion' ? 'rgba(70,210,255,.30)' : 'rgba(185,90,255,.24)';
    ctx.strokeStyle = sp.type === 'illusion' ? 'rgba(150,245,255,.9)' : 'rgba(235,170,255,.95)';
    ctx.fillRect(sx * CELL, sy * CELL, CELL, CELL);
    ctx.setLineDash([4, 3]); ctx.lineWidth = 2;
    ctx.strokeRect(sx * CELL + 2, sy * CELL + 2, CELL - 4, CELL - 4);
    ctx.restore();
  }
  // ── Decorations (2D overlay — emoji at footprint center + subtle fill)
  {
    const decors = GS.decorations;
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    // Chão (special:floor) primeiro → fica EMBAIXO; objetos empilhados desenham por cima.
    const decorsDrawOrder = [...decors].sort((a, b) => ((a.special === 'floor') ? 0 : 1) - ((b.special === 'floor') ? 0 : 1));
    for (const d of decorsDrawOrder) {
      const tiles = GS.decorTilesOf(d);
      // Only draw if at least one tile in the footprint has been explored
      if (!tiles.some(([tx2, ty2]) => exploredSet.has(`${tx2},${ty2}`))) continue;
      if (_detectSecrets && _secretKeyIds.has(d.id)) {
        ctx.save(); ctx.strokeStyle = 'rgba(235,170,255,.95)'; ctx.lineWidth = 2; ctx.setLineDash([3, 2]);
        for (const [tx2, ty2] of tiles) ctx.strokeRect(tx2 * CELL + 2, ty2 * CELL + 2, CELL - 4, CELL - 4);
        ctx.restore();
      }
      // Subtle fill on all occupied tiles
      ctx.fillStyle = 'rgba(120,200,160,0.12)';
      for (const [tx2, ty2] of tiles) ctx.fillRect(tx2 * CELL, ty2 * CELL, CELL, CELL);
      // Image or emoji at footprint center
      const avgX = tiles.reduce((s, t) => s + t[0], 0) / tiles.length;
      const avgY = tiles.reduce((s, t) => s + t[1], 0) / tiles.length;
      const _vo = Array.isArray(d.voffset) ? d.voffset : [0, 0];
      const _ox = Math.max(-.45, Math.min(.45, Number(_vo[0]) || 0)) * CELL;
      const _oy = Math.max(-.45, Math.min(.45, Number(_vo[1]) || 0)) * CELL;
      const ecx = (avgX + 0.5) * CELL + _ox;
      const ecy = (avgY + 0.5) * CELL + _oy;
      // Escala visual (vscale): largura ×sx, altura ×sy (cresce p/ cima, base ancorada).
      const _vs = Array.isArray(d.vscale) ? d.vscale : [1, 1];
      const _sx = _vs[0] || 1, _sy = _vs[1] || 1;
      const _oImg = d.image ? (d.special === 'wall' ? _getWallObjeto2DImg(d.image) : _getObjeto2DImg(d.image)) : null;
      if (_oImg && d.special === 'floor') {
        // Chão: preenche cada casa do footprint borda-a-borda (sem manter proporção).
        for (const [tx2, ty2] of tiles) ctx.drawImage(_oImg, tx2 * CELL, ty2 * CELL, CELL, CELL);
      } else if (_oImg) {
        const minX = Math.min(...tiles.map(t => t[0])), maxX = Math.max(...tiles.map(t => t[0]));
        const minY = Math.min(...tiles.map(t => t[1])), maxY = Math.max(...tiles.map(t => t[1]));
        const px = minX * CELL + _ox, py = minY * CELL + _oy;
        const pw = (maxX - minX + 1) * CELL, ph = (maxY - minY + 1) * CELL;
        const ar = _oImg.naturalWidth / _oImg.naturalHeight;
        const _ang = _facingAngle2D(d.facing, d.type, d.image);
        if (_ang === 0) {
          // ajusta mantendo proporção, ancorado embaixo (caminho original)
          let dw = pw, dh = pw / ar;
          if (dh > ph) { dh = ph; dw = ph * ar; }
          dw *= _sx; dh *= _sy;
          ctx.drawImage(_oImg, px + (pw - dw) / 2, py + (ph - dh), dw, dh);
        } else {
          // girado: encaixa no frame local (caixa possivelmente trocada p/ 90°/270°)
          // e gira sobre o centro do footprint.
          const _rot90 = (_ang === Math.PI / 2 || _ang === -Math.PI / 2);
          const boxW = _rot90 ? ph : pw, boxH = _rot90 ? pw : ph;
          let dw = boxW, dh = boxW / ar;
          if (dh > boxH) { dh = boxH; dw = boxH * ar; }
          dw *= _sx; dh *= _sy;
          ctx.save();
          ctx.translate(px + pw / 2, py + ph / 2);
          ctx.rotate(_ang);
          ctx.drawImage(_oImg, -dw / 2, -dh / 2, dw, dh);
          ctx.restore();
        }
      } else if (_sx === 1 && _sy === 1) {
        ctx.font = `${Math.floor(CELL * 0.8)}px serif`;
        ctx.fillText(d.emoji || '🪑', ecx, ecy);
      } else {
        // emoji escalado: ancorado na base do footprint, crescendo p/ cima
        const baseY = (Math.max(...tiles.map(t => t[1])) + 1) * CELL + _oy;
        ctx.font = `${Math.floor(CELL * 0.8 * Math.max(_sx, _sy))}px serif`;
        ctx.textBaseline = 'alphabetic';
        ctx.fillText(d.emoji || '🪑', ecx, baseY - 2);
        ctx.textBaseline = 'middle';
      }
      // Encontrar Armadilhas revelou o mecanismo escondido no objeto.
      if ((d.trap || d.chest_trap) && d.trap_revealed) {
        ctx.font = `bold ${Math.round(CELL * 0.22)}px monospace`;
        ctx.fillStyle = '#ff6b52';
        ctx.fillText('⚠', ecx - CELL * 0.30, ecy - CELL * 0.29);
      }
      // Loot indicator badge
      if (d.tem_loot) {
        ctx.font = `bold ${Math.round(CELL * 0.18)}px monospace`;
        ctx.fillStyle = '#ffe060';
        ctx.fillText('💰', ecx + CELL * 0.28, ecy - CELL * 0.28);
      }
    }
    // O chão (special:floor) é PISO e foi desenhado por cima do realce de movimento
    // (PASS 1). Re-aplica o destaque azul/vermelho nas casas de chão para que a
    // indicação de movimentação/ataque apareça sobre a grama, como em piso normal.
    for (const d of decors) {
      if (d.special !== 'floor') continue;
      for (const [tx2, ty2] of GS.decorTilesOf(d)) {
        if (!exploredSet.has(`${tx2},${ty2}`)) continue;
        const k = `${tx2},${ty2}`, X = tx2 * CELL, Y = ty2 * CELL;
        if (reachable.has(k)) {
          const fa = 0.26 + 0.26 * _movePulse, pa = 0.70 + 0.30 * _movePulse;
          ctx.fillStyle = `rgba(30,107,255,${fa.toFixed(2)})`; ctx.fillRect(X + 2, Y + 2, CELL - 4, CELL - 4);
          ctx.strokeStyle = `rgba(60,140,255,${pa.toFixed(2)})`; ctx.lineWidth = 2; ctx.strokeRect(X + 2, Y + 2, CELL - 4, CELL - 4);
        } else if (attackable.has(k)) {
          ctx.fillStyle = 'rgba(255,30,30,0.13)'; ctx.fillRect(X + 2, Y + 2, CELL - 4, CELL - 4);
          ctx.strokeStyle = 'rgba(255,60,60,0.78)'; ctx.lineWidth = 2; ctx.strokeRect(X + 2, Y + 2, CELL - 4, CELL - 4);
        }
      }
    }
  }

  // Sorrateiro: o círculo mostra o alcance que a IA do monstro pode enxergar.
  // A oclusão por paredes/objetos continua sendo aplicada pelo servidor; o aro
  // comunica o raio máximo sem revelar informação de monstros na névoa.
  if(GS.sorrateiroAtivo()){
    ctx.save();
    ctx.setLineDash([Math.max(3, CELL*.16), Math.max(2, CELL*.10)]);
    ctx.lineWidth = Math.max(1, CELL*.045);
    for(const m of state.monsters){
      if(!m || m.hp<=0 || m._morteVisualPendente || !visionSet.has(`${m.pos[0]},${m.pos[1]}`)) continue;
      const raio = Math.max(1, Number(m.vision_radius || 6));
      ctx.beginPath();
      ctx.arc(m.pos[0]*CELL+CELL/2, m.pos[1]*CELL+CELL/2, raio*CELL, 0, Math.PI*2);
      ctx.strokeStyle='rgba(108,210,255,0.72)'; ctx.stroke();
    }
    ctx.restore();
  }

  // Prévia do alcance do monstro sob o cursor — fica atrás da miniatura para
  // que o Mestre veja a região vermelha sem perder a leitura da criatura.
  _drawMasterMonsterSelection2D(ctx, state, terrainSet);
  _drawMasterMonsterAttackPreview2D(ctx, state, terrainSet);
  _drawMasterHistoryFocus2D(ctx, state, terrainSet);
  _drawMovePreview2D(ctx, state, terrainSet);
  _drawMasterMonsterMovePreview2D(ctx, state, terrainSet);

  // ── Monsters: only visible within player's vision radius
  const _vortexSpin2D = performance.now() / 260;
  const gamepadAttackTarget2D = _gamepadSelectedAttackTarget(state);
  for(const m of state.monsters){
    const [mtx,mty]=m.pos;
    if(!visionSet.has(`${mtx},${mty}`)) continue;
    // Deslize fiel (entity_step): interpola a posição durante a animação.
    const _mStep = _serverStepPos(m.id);
    const mx = _mStep ? _mStep.x : mtx;
    const my = _mStep ? _mStep.y : mty;
    const [offX, offY] = _monsterVisualCenterOffset(m);
    const [hitX, hitY] = _hitReaction2D(`m:${m.id}`);
    const cx=(mx+offX)*CELL+CELL/2+hitX, cy=(my+offY)*CELL+CELL/2+hitY;
    const fp = _monsterFootprintSize(m);
    const attackTargeted = gamepadAttackTarget2D?.targetId === m.id;
    if(attackTargeted) _drawGamepadAttackTargetFocus2D(ctx, m, mx, my, performance.now());
    const _monVortexPreso = !!(m.rodamoinho_preso || m.rodamoinho_profundo_preso);
    if(_monVortexPreso){
      ctx.save(); ctx.translate(cx, cy); ctx.rotate(_vortexSpin2D); ctx.translate(-cx, -cy);
    }
    if(m.oriented){
      // A função recebe a casa-âncora e calcula internamente o centro do
      // corpo; isso preserva a direção mesmo no footprint orientado 2x2.
      drawOrientedMonster2D(ctx, m, mx*CELL+CELL/2+hitX, my*CELL+CELL/2+hitY, attackTargeted);
    } else {
      drawMiniBase(ctx, cx, cy, '#c02020', false, fp.logicalW, fp.logicalH);
      drawMonsterSprite(ctx, cx, cy-3, m, attackTargeted);
    }
    if(_monVortexPreso) ctx.restore();
    // HP bar
    const pct=_combatHpRatio(`m:${m.id}`, m.hp, m.max_hp);
    const barH=Math.max(4,Math.round(CELL*0.08));
    const barX = (fp.logicalW > 1 ? (mx + offX - fp.logicalW/2 + 0.5)*CELL + 3 : mx*CELL + 3) + hitX;
    const barY = (fp.logicalH > 1 ? (my + offY - fp.logicalH/2 + 0.5)*CELL + 2 : my*CELL + 2) + hitY;
    const barW = fp.logicalW > 1 ? fp.logicalW*CELL - 6 : CELL - 6;
    ctx.fillStyle='rgba(0,0,0,0.75)'; ctx.fillRect(barX,barY,barW,barH);
    ctx.fillStyle=pct>.5?'#27ae60':pct>.25?'#e67e22':'#e74c3c';
    ctx.fillRect(barX,barY,barW*pct,barH);
    ctx.strokeStyle='rgba(0,0,0,0.55)'; ctx.lineWidth=0.6;
    ctx.strokeRect(barX,barY,barW,barH);
    const mNameFs=Math.round(CELL*0.125);
    ctx.fillStyle='rgba(255,90,90,0.95)'; ctx.font=`bold ${mNameFs}px monospace`;
    ctx.textAlign='center'; ctx.textBaseline='top';
    const alturaVisivel = Number.isFinite(Number(m.altura)) ? Math.max(0, Math.min(10, Math.trunc(Number(m.altura)))) : 0;
    const nomeVisivel = `${alturaVisivel > 0 ? `↑${alturaVisivel} ` : ''}${m.name}`.slice(0,10);
    ctx.fillText(nomeVisivel, cx, barY+barH+3);
    _drawStatusIcons2D(ctx, barX-3, barY, m);
    if(m.provocado && Number(m.provocado_turnos) > 0)
      _drawProvocacaoBadge2D(ctx, cx, cy, fp, performance.now());
    // Ícones de magias em monstros são exclusivos do simulador do mestre.
    // O jogo normal continua exibindo somente os indicadores de condição
    // existentes acima, sem expor efeitos fora do modo de teste.
    if(state.test_mode && GS.isMaster?.())
      _drawEfeitosAtivos2D(ctx, state, m, cx, cy, _coletarEfeitosMagicosMonstro(state, m));
  }

  // ── Corpses (cadáveres): alvos de Animar Mortos — ícone esmaecido roxo ──────
  for(const c of (state.corpses||[])){
    const [cxp,cyp]=c.pos;
    if(!visionSet.has(`${cxp},${cyp}`)) continue;
    const cx=cxp*CELL+CELL/2, cy=cyp*CELL+CELL/2;
    ctx.save();
    ctx.globalAlpha=0.55;
    ctx.font=`${Math.round(CELL*0.5)}px serif`;
    ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.fillText(c.icone||'💀', cx, cy);
    ctx.restore();
  }

  // Lápides dos heróis derrotados. O registro é separado dos cadáveres de
  // monstros, pois a Ressurreição remove esta marca antes de devolver o peão.
  for(const c of (state.hero_corpses||[])){
    const [cxp,cyp] = c.pos || [];
    if(!Number.isFinite(cxp) || !Number.isFinite(cyp) || !visionSet.has(`${cxp},${cyp}`)) continue;
    const img = _getObjeto2DImg('lapide.png');
    const cx = cxp*CELL + CELL/2;
    const baseY = cyp*CELL + CELL*0.90;
    ctx.save();
    if(img && img.complete && img.naturalWidth){
      const ar = img.naturalWidth / img.naturalHeight;
      let dw = CELL*0.72, dh = dw/ar;
      if(dh > CELL*1.12){ dh = CELL*1.12; dw = dh*ar; }
      ctx.drawImage(img, cx-dw/2, baseY-dh, dw, dh);
    } else {
      ctx.globalAlpha = 0.85;
      ctx.font = `${Math.round(CELL*0.52)}px serif`;
      ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.fillText(c.icone || '🪦', cx, cyp*CELL + CELL/2);
    }
    ctx.restore();
  }

  // ── Prisioneiro (Fase 3): cativo (acorrentado) vs. seguindo; barra de HP ──────
  const _pris = GS.prisoner;
  if(_pris && _pris.alive){
    const [pxr,pyr]=_pris.pos;
    // Interpola a posição visual durante a animação de passo (igual aos minions):
    // desliza casa a casa pelo caminho enquanto _mininoAnimState['prisoner'] existir.
    let drawX = pxr, drawY = pyr;
    const _pVis = _mininoAnimState.get('prisoner');
    if(_pVis && _pVis.pathPts){
      const segs = Math.max(1, _pVis.pathPts.length - 1);
      const tAll = Math.min((performance.now() - _pVis.startTime) / _pVis.dur, 1);
      const f  = tAll * segs;
      const si = Math.min(Math.floor(f), segs - 1);
      const st = easeInOut(f - si);
      const [x0,y0] = _pVis.pathPts[si];
      const [x1,y1] = _pVis.pathPts[si+1];
      drawX = x0 + (x1 - x0) * st;
      drawY = y0 + (y1 - y0) * st;
    }
    const _visPathP = _pVis && _pVis.pathPts
      ? _pVis.pathPts.some(([px,py]) => visionSet.has(`${px},${py}`) || exploredSet.has(`${px},${py}`))
      : false;
    if(visionSet.has(`${pxr},${pyr}`) || exploredSet.has(`${pxr},${pyr}`) || _visPathP){
      const [hitX, hitY] = _hitReaction2D('pr:singleton');
      const cx=drawX*CELL+CELL/2+hitX, cy=drawY*CELL+CELL/2+hitY;
      const _prisVortexPreso = !!(_pris.rodamoinho_preso || _pris.rodamoinho_profundo_preso);
      // Anel de seleção quando o controlador o selecionou (janela pós-turno).
      if(_prisSel && _pris.freed && _pris.rescuer_pid===GS.myPid && state.animados_turn===GS.myPid){
        ctx.save();
        ctx.strokeStyle='#ffffff'; ctx.lineWidth=3;
        ctx.beginPath(); ctx.arc(cx, cy, CELL*0.42, 0, Math.PI*2); ctx.stroke();
        ctx.restore();
      }
      // Base do peão: tom amarelado se aliado/seguindo, acinzentado se cativo.
      if(_prisVortexPreso){
        ctx.save(); ctx.translate(cx, cy); ctx.rotate(_vortexSpin2D); ctx.translate(-cx, -cy);
      }
      drawMiniBase(ctx, cx, cy, _pris.freed?'#2e90c0':'#8a6d3b', false);
      const _pImg = _getPrisoner2DImg(_pris.image);
      if(_pImg && _pImg.complete && _pImg.naturalWidth){
        const sz = Math.round(CELL*0.78);
        ctx.drawImage(_pImg, cx - sz/2, cy - sz/2 - 3, sz, sz);
      } else {
        ctx.font=`${Math.round(CELL*0.46)}px serif`;
        ctx.textAlign='center'; ctx.textBaseline='middle';
        ctx.fillText(_pris.freed?'🧍':'⛓️', cx, cy-3);
      }
      if(_prisVortexPreso) ctx.restore();
      // Barra de HP simples
      const max=_pris.max_hp||_pris.hp||1;
      const pct=Math.max(0,Math.min(1,_pris.hp/max));
      const barH=Math.max(4,Math.round(CELL*0.08));
      const bx=drawX*CELL+hitX, by=drawY*CELL+hitY;
      ctx.fillStyle='rgba(0,0,0,0.75)'; ctx.fillRect(bx+3,by+2,CELL-6,barH);
      ctx.fillStyle=pct>.5?'#27ae60':pct>.25?'#e67e22':'#e74c3c';
      ctx.fillRect(bx+3,by+2,(CELL-6)*pct,barH);
      ctx.strokeStyle='rgba(0,0,0,0.55)'; ctx.lineWidth=0.6;
      ctx.strokeRect(bx+3,by+2,CELL-6,barH);
      const fs=Math.round(CELL*0.125);
      ctx.fillStyle='rgba(255,210,120,0.95)'; ctx.font=`bold ${fs}px monospace`;
      ctx.textAlign='center'; ctx.textBaseline='top';
      ctx.fillText(I18N.t('ui.hud.prisioneiro'), cx, by+barH+3);
    }
  }

  // ── Animados (servos do Pedro / elementais): peão do MONSTRO ORIGINAL, aliado ──
  for(const pl of state.players){
    for(const a of (pl.animados||[])){
      if(!a.pos) continue;
      const [ax,ay]=a.pos;
      // Interpola posição visual durante animação 2D de passo (lerp easeInOut).
      // Enquanto _mininoAnimState tiver entrada para este animado, desenhamos na
      // posição interpolada; ao final a posição real do servidor já foi atualizada.
      let drawX = ax, drawY = ay;
      const _aStep = _serverStepPos(a.id);   // deslize fiel (servo auto-comandado)
      const _aVis = _mininoAnimState.get(a.id);
      if(_aStep){
        drawX = _aStep.x; drawY = _aStep.y;
      } else if(_aVis && _aVis.pathPts){
        // Caminho contínuo: encontra o segmento atual pelo tempo decorrido.
        const segs = Math.max(1, _aVis.pathPts.length - 1);
        const tAll = Math.min((performance.now() - _aVis.startTime) / _aVis.dur, 1);
        const f  = tAll * segs;
        const si = Math.min(Math.floor(f), segs - 1);
        const st = easeInOut(f - si);
        const [x0,y0] = _aVis.pathPts[si];
        const [x1,y1] = _aVis.pathPts[si+1];
        drawX = x0 + (x1 - x0) * st;
        drawY = y0 + (y1 - y0) * st;
      } else if(_aVis){
        const t = easeInOut(Math.min((performance.now() - _aVis.startTime) / _aVis.dur, 1));
        drawX = _aVis.fromX + (_aVis.toX - _aVis.fromX) * t;
        drawY = _aVis.fromY + (_aVis.toY - _aVis.fromY) * t;
      }
      // Durante o deslocamento, o facing autoritativo pode já apontar para a
      // última casa do caminho. A miniatura acompanha o segmento percorrido.
      let _aFacing = a.facing;
      if(_aStep){
        const _aEnt = _serverStepAnim.get(a.id);
        _aFacing = _movementFacingFromPath(_aEnt && _aEnt.pts,
          _aEnt ? (performance.now() - _aEnt.startTime) / _aEnt.segDur : 0)
          || _aFacing;
      } else if(_aVis && _aVis.pathPts){
        const _aSegs = Math.max(1, _aVis.pathPts.length - 1);
        const _aFrac = Math.min((performance.now() - _aVis.startTime) / _aVis.dur, 1) * _aSegs;
        _aFacing = _movementFacingFromPath(_aVis.pathPts, _aFrac) || _aFacing;
      }
      // Visibilidade: a casa atual OU algum ponto do caminho devem estar à vista.
      const _visPath = _aVis && _aVis.pathPts
        ? _aVis.pathPts.some(([px,py]) => visionSet.has(`${px},${py}`))
        : (_aVis && visionSet.has(`${_aVis.toX},${_aVis.toY}`));
      if(!visionSet.has(`${ax},${ay}`) && !_visPath) continue;
      const [hitX, hitY] = _hitReaction2D(`a:${a.id}`);
      const cx=drawX*CELL+CELL/2+hitX, cy=drawY*CELL+CELL/2+hitY;
      const _animVortexPreso = !!(a.rodamoinho_preso || a.rodamoinho_profundo_preso);
      if(_animVortexPreso){
        ctx.save(); ctx.translate(cx, cy); ctx.rotate(_vortexSpin2D); ctx.translate(-cx, -cy);
      }
      drawMiniBase(ctx, cx, cy, '#9900cc', false);
      // Sprite original do monstro (goblin/orc/etc.) — fallback p/ ícone via emoji.
      drawMonsterSprite(ctx, cx, cy-3, {
        type:a.tipo, image:a.image, porte:a.porte, emoji:a.icone, name:a.nome,
        facing:_aFacing
      });
      // Anel roxo de "animado aliado"; branco e grosso se selecionado.
      ctx.save();
      ctx.strokeStyle = (_animadoSel===a.id) ? '#ffffff' : '#cc44ff';
      ctx.lineWidth   = (_animadoSel===a.id) ? 3 : 2;
      ctx.beginPath(); ctx.arc(cx, cy-3, CELL/2-2, 0, Math.PI*2); ctx.stroke();
      ctx.restore();
      if(_animVortexPreso) ctx.restore();
      // Barra de vida (usa posição visual drawX/drawY)
      const pct=Math.max(0, (a.vida_atual||0)/(a.vida_max||1));
      const barH=Math.max(4,Math.round(CELL*0.08));
      ctx.fillStyle='rgba(0,0,0,0.75)'; ctx.fillRect(drawX*CELL+3+hitX,drawY*CELL+2+hitY,CELL-6,barH);
      ctx.fillStyle='#cc44ff'; ctx.fillRect(drawX*CELL+3+hitX,drawY*CELL+2+hitY,(CELL-6)*pct,barH);
    }
  }

  _protetorDraw2D(ctx, state, visionSet, false, performance.now());

  // ── Players: base disc then hero sprite
  ctx.textAlign='center'; ctx.textBaseline='middle';
  for(const p of state.players){
    if(!p.alive) continue;
    if(p.engolido || p.bau_engolido || p.fosso_oculto) continue;
    if(p.connected === false) continue;   // desconectado: deixou a masmorra, não desenha
    const [px,py]=p.pos;
    if(p.id !== GS.myPid && !visionSet.has(`${px},${py}`)) continue;
    const [hitX, hitY] = _hitReaction2D(`p:${p.id}`);
    const [holyX,holyY]=_holyStrikeLunge(p.id,performance.now());
    const X=px*CELL+hitX+holyX, Y=py*CELL+hitY+holyY, cx=X+CELL/2, cy=Y+CELL/2;
    const isCur=p.id===state.current_turn, isMe=p.id===GS.myPid;
    const isTesteSel = !!(state.test_mode && testeHeroiSelecionado
      && String(p.id) === String(testeHeroiSelecionado.id));
    const formaVisual = _metamorfoseVisualName(p);
    const _invisP = !!p.invisivel_magico || _invisibilidadeAnimAtiva(p.id);
    const _playerVortexPreso = !!(p.rodamoinho_preso || p.rodamoinho_profundo_preso);
    const _spinAngle2D = _spinAttackAngle2D(p.id, performance.now());
    if(_invisP) ctx.save(), ctx.globalAlpha=.18;
    if(_playerVortexPreso){
      ctx.save(); ctx.translate(cx, cy); ctx.rotate(_vortexSpin2D); ctx.translate(-cx, -cy);
    }
    drawMiniBase(ctx, cx, cy, p.color, isCur||isMe||isTesteSel);
    if(formaVisual){
      const wolf = _getMonster2DImg(formaVisual);
      if(wolf && wolf.complete && wolf.naturalWidth){
        const h=CELL*1.42, w=Math.min(CELL*1.20,h*(wolf.naturalWidth/wolf.naturalHeight));
        ctx.save();
        ctx.translate(cx, cy-3);
        ctx.rotate(_facingAngle2D(p.facing) + _spinAngle2D);
        ctx.translate(-cx, -(cy-3));
        if(p.petrificado) ctx.filter=_petrificadoFiltro2D();
        ctx.drawImage(wolf,cx-w/2,cy-3+(CELL*.41)-h,w,h);
        ctx.restore();
      } else drawHeroSprite(ctx, cx, cy-3, p.class_id, p.color, isMe, isCur, !!p.petrificado, p.facing, _spinAngle2D);
    } else drawHeroSprite(ctx, cx, cy-3, p.class_id, p.color, isMe, isCur, !!p.petrificado, p.facing, _spinAngle2D);
    if(_playerVortexPreso) ctx.restore();
    if(_invisP) ctx.restore();
    _drawStatusIcons2D(ctx, X, Y, p);
    _drawEfeitosAtivos2D(ctx, state, p, cx, cy);
    if(isMe||isCur||isTesteSel){
      const label=p.name.slice(0,9);
      const tagFs=Math.round(CELL*0.14);
      ctx.font=`bold ${tagFs}px monospace`; ctx.textAlign='center';
      const tw=ctx.measureText(label).width;
      ctx.fillStyle='rgba(0,0,0,0.88)';
      ctx.fillRect(cx-tw/2-4,Y+CELL-tagFs-4,tw+8,tagFs+2);
      ctx.fillStyle=isMe?'#f0c040':isTesteSel?'#ffd04a':'#ffffff';
      ctx.textBaseline='top'; ctx.fillText(label,cx,Y+CELL-tagFs-3);
      ctx.textBaseline='middle';
    }
  }
  _desenharNotasCancao2D(ctx, state, performance.now(), exploredSet);
  _drawSpinAttack2D(ctx, state, performance.now());
  _protetorDraw2D(ctx, state, visionSet, true, performance.now());
  // O relâmpago fica por cima das miniaturas para que a descarga seja legível
  // mesmo quando atravessa um peão ou um monstro.
  const _agoraRelampago = performance.now();
  for(const _animInvis of _invisibilidadeAnims)
    _invisibilidadeDraw2D(ctx, state, _animInvis, _agoraRelampago);
  for(const _animProtecao of _protecaoEnergiaAnims)
    _protecaoEnergiaDrawForeground2D(ctx, state, _animProtecao, _agoraRelampago);
  for(const _animOlhar of _olharPetrificanteAnims)
    _olharPetrificanteDraw2D(ctx, state, _animOlhar, _agoraRelampago);
  for(const _animVoo of _vooAnims)
    _vooDraw2D(ctx, state, _animVoo, _agoraRelampago);
  for(const _animCriarAlimentos of _criarAlimentosAnims)
    _criarAlimentosDraw2D(ctx, state, _animCriarAlimentos, _agoraRelampago);
  for(const _animCura of _curaAnims)
    _curaDraw2D(ctx, state, _animCura, _agoraRelampago);
  for(const _animPurificacao of _purificacaoAnims)
    _purificacaoDraw2D(ctx, state, _animPurificacao, _agoraRelampago);
  for(const _animRessurreicao of _ressurreicaoAnims)
    _ressurreicaoDraw2D(ctx, state, _animRessurreicao, _agoraRelampago);
  for(const _animMetamorfose of _metamorfoseAnims)
    _metamorfoseDraw2D(ctx, state, _animMetamorfose, _agoraRelampago);
  for(const _animTeleporte of _teleporteAnims)
    _teleporteDraw2D(ctx, state, _animTeleporte, _agoraRelampago);
  for(const _animGuerreiroLuz of _guerreiroLuzAnims)
    _guerreiroLuzDraw2D(ctx, state, _animGuerreiroLuz, _agoraRelampago);
  for(const _animCancaoHeroica of _cancaoHeroicaAnims)
    _cancaoHeroicaDraw2D(ctx, state, _animCancaoHeroica, _agoraRelampago);
  for(const _animSaciar of _saciarAnims)
    _saciarDraw2D(ctx, state, _animSaciar, _agoraRelampago);
  for(const _animContramagica of _contramagicaAnims)
    _contramagicaDraw2D(ctx, state, _animContramagica, _agoraRelampago);
  for(const _animElemental of _conjurarElementalAnims)
    _conjurarElementalDraw2D(ctx, state, _animElemental, _agoraRelampago);
  for(const _animRaioDivino of _raioDivinoAnims)
    _raioDivinoDrawForeground2D(ctx, state, _animRaioDivino, _agoraRelampago);
  for(const _animRelampago of _relampagoAnims)
    _relampagoDraw2D(ctx, state, _animRelampago, _agoraRelampago);
  for(const _animRaioElemental of _elementalRaioAnims)
    _elementalRaioDraw2D(ctx, state, _animRaioElemental, _agoraRelampago);
  for(const _animBolaFogo of _bolaFogoAnims)
    _bolaFogoDraw2D(ctx, state, _animBolaFogo, _agoraRelampago);
  for(const _animRaioGelo of _raioGeloAnims)
    _raioGeloDraw2D(ctx, state, _animRaioGelo, _agoraRelampago);
  for(const _animJatoAr of _jatoArAnims)
    _jatoArDraw2D(ctx, state, _animJatoAr, _agoraRelampago);
  for(const _animNotaCortante of _notaCortanteAnims)
    _notaCortanteDraw2D(ctx, state, _animNotaCortante, _agoraRelampago);
  for(const _animAcordeTrovejante of _acordeTrovejanteAnims)
    _acordeTrovejanteDraw2D(ctx, state, _animAcordeTrovejante, _agoraRelampago);
  for(const _animRequiem of _requiemFinalAnims)
    _requiemFinalDraw2D(ctx, state, _animRequiem, _agoraRelampago);
  for(const _animSopro of _soproDragaoAnims)
    _soproDragaoDraw2D(ctx, state, _animSopro, _agoraRelampago);
  for(const _animAcido of _cuspeAcidoAnims)
    _cuspeAcidoDraw2D(ctx, state, _animAcido, _agoraRelampago);
  for(const _animAbencoar of _abencoarAnims)
    _abencoarDraw2D(ctx, state, _animAbencoar, _agoraRelampago);
  for(const _animAbencoarArma of _abencoarArmaAnims)
    _abencoarArmaDraw2D(ctx, state, _animAbencoarArma, _agoraRelampago);
  for(const _animDominarMente of _dominarMenteAnims)
    _dominarMenteDraw2D(ctx, state, _animDominarMente, _agoraRelampago);
  for(const _animSono of _sonoAnims)
    _sonoDraw2D(ctx, state, _animSono, _agoraRelampago);
  for(const _animSilencio of _silencioAnims)
    _silencioDrawForeground2D(ctx, state, _animSilencio, _agoraRelampago);
  for(const _animMedo of _medoAnims)
    _medoDrawForeground2D(ctx, state, _animMedo, _agoraRelampago);
  for(const _animBarreira of _barreiraAnims)
    _barreiraDrawForeground2D(ctx, state, _animBarreira, _agoraRelampago);
  for(const _animGuarda of _guardaMaximaAnims)
    _guardaMaximaDraw2D(ctx, state, _animGuarda, _agoraRelampago);
  for(const _animMaldicao of _maldicaoAnims)
    _maldicaoDrawForeground2D(ctx, state, _animMaldicao, _agoraRelampago);
  for(const _animPrivacao of _privacaoAnims)
    _privacaoDrawForeground2D(ctx, state, _animPrivacao, _agoraRelampago);
  for(const _animMantoEsc of _mantoEscuridaoAnims)
    _mantoEscuridaoDrawForeground2D(ctx, state, _animMantoEsc, _agoraRelampago);
  for(const _animClarividencia of _clarividenciaAnims)
    _clarividenciaDrawForeground2D(ctx, state, _animClarividencia, _agoraRelampago);
  for(const _animRegeneracao of _regeneracaoAnims)
    _regeneracaoDrawForeground2D(ctx, state, _animRegeneracao, _agoraRelampago);
  for(const _animLentidao of _lentidaoAnims)
    _lentidaoDrawForeground2D(ctx, state, _animLentidao, _agoraRelampago);
  for(const _animVelocidade of _velocidadeAnims)
    _velocidadeDrawForeground2D(ctx, state, _animVelocidade, _agoraRelampago);
  for(const _animHabilidade of _habilidadeAtivacaoAnims)
    _habilidadeFxDraw2D(ctx, state, _animHabilidade, _agoraRelampago);
  for(const _animArmadilha of _armadilhaAnims)
    _armadilhaDraw2D(ctx, state, _animArmadilha, _agoraRelampago);
  _fumacaDraw2D(ctx, state, _agoraRelampago);   // por cima dos peões: eles ficam meio encobertos
  _drawAttackFeedback2D(ctx, state, _agoraRelampago);
  // Números de dano/cura e resultado de derrota ficam no primeiro plano para
  // permanecerem legíveis mesmo quando uma magia atravessa a miniatura.
  _drawCombatFeedback2D(ctx, state, _agoraRelampago);
  _drawResistanceFeedback2D(ctx, state, _agoraRelampago);
  _drawConditionPulses2D(ctx, state, _agoraRelampago);
  _drawPositiveBursts2D(ctx, state, _agoraRelampago);
  _drawDefeatVisuals2D(ctx, state, _agoraRelampago);
}

// ── Mortes visuais adiadas ──────────────────────────────────────────────────
// O servidor pode confirmar a morte de um monstro no mesmo pacote em que a
// magia ainda está viajando/impactando. A lógica autoritativa continua vendo
// HP=0 imediatamente; aqui mantemos somente uma cópia de renderização até a
// leitura visual do dano ou da magia terminar.
const _mortesVisuaisPendentes = new Map();
let _ultimoEstadoVisualMonstros = new Map();
let _ultimoEstadoVisualHerois = new Map();
let _ultimoEstadoVisualBaús = new Set();
const MORTE_VISUAL_MIN_MS = VC.feedback?.combat?.damageMs ?? 1050;
const MORTE_VISUAL_MAX_MS = 5200;
const MORTE_VISUAL_MAGIA_RECENTE_MS = 900;
let _ultimaMagiaVisualAt = -Infinity;
const _defeatVisuals = [];
let _defeatVisualRaf = null;

function _defeatVisualConfig(kind){
  const cfg = VC.feedback?.combat?.defeat || {};
  const colors = cfg.colors || {};
  const duration = kind === 'boss' ? (cfg.bossMs || 1750)
    : kind === 'explosion' ? (cfg.explosionMs || 1450)
    : kind === 'magic' ? (cfg.magicMs || 1150)
    : kind === 'revive' ? (cfg.reviveMs || 1200)
    : kind === 'hero' ? (cfg.commonMs || 1250)
    : (cfg.commonMs || 1250);
  return {duration, color: colors[kind] || (kind === 'hero' ? colors.hero : colors.common) || '#d6c29a'};
}

function _defeatVisualKind(entity, fallback='common'){
  const abilities = (entity?.special_abilities || []).map(a => a?.id);
  if(abilities.includes('morte_explosiva') || entity?.especial === 'explosao_6d6') return 'explosion';
  if(entity?.boss) return 'boss';
  if(fallback === 'magic') return 'magic';
  return fallback;
}

function _spawnDefeatVisual(entity, kind='common'){
  if(!entity || !Array.isArray(entity.pos)) return;
  const cfg = _defeatVisualConfig(kind);
  const v = {
    pos: [Number(entity.pos[0]), Number(entity.pos[1])],
    kind, color: cfg.color, start: performance.now(), duration: _animationProgressDuration(cfg.duration),
    seed: ((Number(entity.id) || 1) * 2654435761) ^ Date.now(),
    group: null, ring: null, particles: [],
  };
  _defeatVisuals.push(v);
  if(mode3D && g3) _buildDefeatVisual3D(v);
  _requestDefeatVisualFrame();
}

function _defeatColorHex(v){
  return Number(`0x${String(v.color || '#d6c29a').replace('#','')}`) || 0xd6c29a;
}

function _buildDefeatVisual3D(v){
  if(!g3 || !g3.scene || !window.THREE || v.group) return;
  const T = g3.T, group = new T.Group(); group.name = `defeat-${v.kind}`;
  const color = _defeatColorHex(v);
  const mat = new T.MeshBasicMaterial({color, transparent:true, opacity:0, depthWrite:false, depthTest:false, blending:T.AdditiveBlending, side:T.DoubleSide});
  v.ring = new T.Mesh(new T.TorusGeometry(v.kind === 'boss' ? .34 : .25, .028, 8, 32), mat);
  v.ring.rotation.x = Math.PI / 2; v.ring.renderOrder = 135; group.add(v.ring);
  for(let i=0;i<12;i++){
    const pm = new T.MeshBasicMaterial({color, transparent:true, opacity:0, depthWrite:false, depthTest:false, blending:T.AdditiveBlending});
    const particle = new T.Mesh(new T.OctahedronGeometry(.025 + (i%3)*.012, 0), pm);
    particle.userData.i = i; group.add(particle); v.particles.push(particle);
  }
  g3.scene.add(group); v.group = group;
}

function _disposeDefeatVisual3D(v){
  if(!v?.group) return;
  if(v.group.parent) v.group.parent.remove(v.group);
  v.group.traverse(o => { if(o.geometry) o.geometry.dispose(); if(o.material) o.material.dispose(); });
  v.group = null;
}

function _updateDefeatVisual3D(now){
  if(!g3) return;
  for(const v of _defeatVisuals){
    if(!v.group || v.group.parent !== g3.scene) _buildDefeatVisual3D(v);
    if(!v.group) continue;
    const p = Math.max(0, Math.min(1, (now - v.start) / v.duration));
    const fade = p < .58 ? 1 : Math.max(0, 1 - (p - .58) / .42);
    const expand = v.kind === 'explosion' ? 1 + p * 3.0 : v.kind === 'boss' ? 1 + p * 2.4 : 1 + p * 1.8;
    v.ring.position.set(v.pos[0], .32 + p * .18, v.pos[1]);
    v.ring.scale.setScalar(expand); v.ring.material.opacity = .82 * fade;
    for(const particle of v.particles){
      const i = particle.userData.i, a = i * Math.PI * 2 / v.particles.length + v.seed * .00001;
      const radius = (.10 + p * (v.kind === 'explosion' ? .75 : .48)) * (1 + (i % 3) * .12);
      particle.position.set(v.pos[0] + Math.cos(a) * radius, .35 + p * (.55 + (i%4)*.10), v.pos[1] + Math.sin(a) * radius);
      particle.rotation.y = now / 280 + i; particle.material.opacity = (.64 + .24 * Math.sin(now/120+i)**2) * fade;
    }
  }
}

function _drawDefeatVisuals2D(ctx, state, now){
  for(const v of _defeatVisuals){
    if(!_combatFeedbackVisible({pos:v.pos}, state)) continue;
    const p = Math.max(0, Math.min(1, (now - v.start) / v.duration));
    const fade = p < .58 ? 1 : Math.max(0, 1 - (p - .58) / .42);
    const x = v.pos[0] * CELL + CELL/2, y = v.pos[1] * CELL + CELL/2;
    const radius = CELL * (v.kind === 'explosion' ? (.16 + p * .80) : (.18 + p * .52));
    ctx.save(); ctx.globalAlpha = fade; ctx.globalCompositeOperation = 'lighter';
    ctx.strokeStyle = v.color; ctx.shadowColor = v.color; ctx.shadowBlur = CELL * .18;
    ctx.lineWidth = Math.max(2, CELL * .045); ctx.beginPath(); ctx.arc(x, y, radius, 0, Math.PI*2); ctx.stroke();
    for(let i=0;i<10;i++){
      const a = i * Math.PI * 2 / 10 + v.seed * .00001;
      const rr = CELL * (.12 + p * (v.kind === 'explosion' ? .72 : .48));
      const px = x + Math.cos(a) * rr, py = y + Math.sin(a) * rr - p * CELL * .40;
      ctx.fillStyle = v.color; ctx.beginPath(); ctx.arc(px, py, Math.max(1.5, CELL * (.025 + .018*(i%3))), 0, Math.PI*2); ctx.fill();
    }
    if(v.kind === 'magic'){
      ctx.font = `${Math.max(16, CELL*.28)}px serif`; ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillText('✦', x, y - CELL*(.22 + p*.48));
    } else if(v.kind === 'hero'){
      ctx.font = `900 ${Math.max(12, CELL*.16)}px Arial, sans-serif`; ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillText(t('ui.tabuleiro.caido'), x, y - CELL*(.28 + p*.42));
    }
    ctx.restore();
  }
}

function _requestDefeatVisualFrame(){
  if(_defeatVisualRaf) return;
  const tick = () => {
    _defeatVisualRaf = null; const now = performance.now();
    for(let i=_defeatVisuals.length-1;i>=0;i--){
      const v = _defeatVisuals[i];
      if(now - v.start < v.duration) continue;
      _disposeDefeatVisual3D(v); _defeatVisuals.splice(i,1);
    }
    if(mode3D && g3) _updateDefeatVisual3D(now); else if(!mode3D && GS.gameState) renderMap(GS.gameState);
    if(_defeatVisuals.length) _defeatVisualRaf = _scheduleVisualFrame(tick);
  };
  _defeatVisualRaf = _scheduleVisualFrame(tick);
}

function _visualTemAnimacaoDeMagia(){
  // Somente efeitos visuais de magia entram neste critério. Dados, números de
  // dano e o texto de derrota têm seus próprios tempos e não devem prolongar
  // a presença da miniatura em ataques normais.
  const animArrays = [
    _relampagoAnims, _bolaFogoAnims, _raioGeloAnims, _raioDivinoAnims,
    _jatoArAnims, _soproDragaoAnims, _cuspeAcidoAnims, _dominarMenteAnims, _lentidaoAnims, _sonoAnims,
    _silencioAnims, _medoAnims,
    _senhorAguasAnims,
    _requiemFinalAnims,
    _olharPetrificanteAnims,
    _conjurarElementalAnims,
    _iraRochaAnims,
    _prisaoChamasAnims,
    _vooAnims,
    _criarAlimentosAnims,
    _curaAnims,
    _purificacaoAnims,
    _ressurreicaoAnims,
    _metamorfoseAnims,
    _teleporteAnims,
    _guerreiroLuzAnims,
    _cancaoHeroicaAnims,
    _saciarAnims,
    _contramagicaAnims,
  ];
  return animArrays.some(arr => arr && arr.length > 0);
}

function _registrarInicioAnimacaoMagia(msg){
  if(!msg || !msg.spell_id) return;
  // `resolve` apenas entrega o resultado autoritativo; a animação já foi
  // iniciada pelo evento anterior. Fases persistentes/encerramento também
  // não devem reabrir a janela de espera de uma morte comum.
  const fase = msg.phase;
  if(['resolve', 'expire', 'tick', 'refresh', 'break'].includes(fase)) return;
  _ultimaMagiaVisualAt = performance.now();
}

function _renderizarEstadoAtual(){
  const atual = GS.gameState;
  if(!atual || !atual.tiles) return;
  if(mode3D && g3) renderMap3D(atual); else renderMap(atual);
}

function _agendarFimMorteVisual(id){
  const rec = _mortesVisuaisPendentes.get(String(id));
  if(!rec) return;
  const verificar = () => {
    const atual = _mortesVisuaisPendentes.get(String(id));
    if(!atual) return;
    const agora = performance.now();
    const aguardarMinimo = agora < atual.minAte;
    const aguardarAnimacao = atual.aguardarMagia
      && (_visualTemAnimacaoDeMagia() || agora < atual.magiaAte)
      && agora < atual.maxAte;
    const aguardarCena = !!(window.CombatScene && CombatScene.isDying(`m:${id}`)) && agora < atual.maxAte;
    if(aguardarMinimo || aguardarAnimacao || aguardarCena){
      atual.timer = setTimeout(verificar, 100);
      return;
    }
    if(!atual.confirmado){
      atual.confirmado = true;
      const titulo = atual.monster.boss ? `👑 ${atual.monster.name} derrotado` : `✅ ${atual.monster.name} derrotado`;
      toast(titulo, atual.monster.boss ? 'var(--gold)' : 'var(--green)');
      if(atual.xpGain > 0 || atual.lootAvailable){
        const recompensa = [atual.xpGain > 0 ? `✨ +${atual.xpGain} XP` : '', atual.lootAvailable ? t('ui.hud.bau_de_saque_disponivel') : '']
          .filter(Boolean).join('  •  ');
        toast(recompensa, 'var(--gold)');
      }
    }
    _mortesVisuaisPendentes.delete(String(id));
    _renderizarEstadoAtual();
  };
  // O `end` da cena de combate (tombo terminado) conclui na hora — ver o ramo
  // 'end' de _executarComandoCena, que zera minAte/aguardarMagia antes de chamar.
  rec.concluir = verificar;
  rec.timer = setTimeout(verificar, MORTE_VISUAL_MIN_MS);
}

function _capturarMortesVisuais(state){
  const anteriores = _ultimoEstadoVisualMonstros;
  const proximos = new Map((state.monsters || []).map(m => [String(m.id), m]));
  const agora = performance.now();
  const xpAnterior = _ultimoEstadoVisualHerois;
  const novosBaus = new Set((state.chests || []).map(c => String(c.id)));
  const mortesPotenciais = [...anteriores].filter(([id, anterior]) => {
    const proximo = proximos.get(id);
    return anterior && anterior.hp > 0 && (!proximo || proximo.hp <= 0);
  }).length;
  let morteSequenceIndex = 0;
  const aguardarMagia = _visualTemAnimacaoDeMagia()
    || agora < _ultimaMagiaVisualAt + MORTE_VISUAL_MAGIA_RECENTE_MS;

  for(const [id, anterior] of anteriores){
    const proximo = proximos.get(id);
    const morreu = anterior && anterior.hp > 0
      && (!proximo || proximo.hp <= 0);
    if(!morreu) continue;
    const existente = _mortesVisuaisPendentes.get(id);
    if(existente) continue;
    const morteIndex = morteSequenceIndex++;
    const copia = JSON.parse(JSON.stringify(anterior));
    const kind = _defeatVisualKind(anterior,
      _visualTemAnimacaoDeMagia() ? 'magic' : 'common');
    const chaveCena = `m:${id}`;
    const comCena = _cenaAtiva() && !!CombatScene.pendingFor(chaveCena, agora);
    if(!comCena){
      _spawnDefeatVisual(anterior, kind);
      _somMorteMonstro(anterior, kind);
    }
    const minhaAntes = xpAnterior.get(String(GS.myPid));
    const minhaAgora = (state.players || []).find(p => String(p.id) === String(GS.myPid));
    const xpGain = minhaAntes != null && minhaAgora ? Math.max(0, Number(minhaAgora.xp || 0) - Number(minhaAntes.xp || 0)) : 0;
    const lootAvailable = (state.chests || []).some(c => ! _ultimoEstadoVisualBaús.has(String(c.id))
      && Array.isArray(c.pos) && Math.max(Math.abs(c.pos[0] - anterior.pos[0]), Math.abs(c.pos[1] - anterior.pos[1])) <= 1);
    // Mantém a miniatura, mas deixa a barra no mínimo visual enquanto o
    // impacto termina — a cópia não pode parecer um alvo vivo.
    copia.hp = 1;
    copia._morteVisualPendente = true;
    _mortesVisuaisPendentes.set(id, {
      monster: copia,
      minAte: agora + MORTE_VISUAL_MIN_MS,
      maxAte: agora + (comCena ? (VC.feedback?.combat?.scene?.expireMs ?? 6000)
        : aguardarMagia ? MORTE_VISUAL_MAX_MS : MORTE_VISUAL_MIN_MS),
      magiaAte: agora + MORTE_VISUAL_MAGIA_RECENTE_MS,
      aguardarMagia, xpGain, lootAvailable, confirmado: false,
      timer: null,
    });
    if(comCena){
      // A cena solta texto, anel e som no golpe (sincronizados com o d20) e
      // segura a cópia visual até o tombo terminar (ver _agendarFimMorteVisual).
      const cmd = CombatScene.handoff(chaveCena, {
        feedback: {entry: anterior, text: t('ui.hud.derrotado'), kind: 'death', damageType: null, options: {}},
        death: true,
        onImpact: [() => { _spawnDefeatVisual(anterior, kind); _somMorteMonstro(anterior, kind); }],
      }, agora);
      if(cmd) _executarComandoCena(cmd);
    } else {
      _spawnCombatFeedback(
        anterior, t('ui.hud.derrotado'), 'death',
        (() => {
          const inicio = _bolaFogoFeedbackStartAt(anterior);
          return inicio != null ? inicio + (mortesPotenciais > 1 ? morteIndex * 120 : 0)
            : (mortesPotenciais > 1 ? agora + morteIndex * 120 : null);
        })()
      );
    }
    _agendarFimMorteVisual(id);
  }

  // Se um monstro reaparecer de fato (ressurreição/reinício), o estado vivo
  // autoritativo vence e a cópia visual antiga deixa de ser necessária.
  for(const [id, monstro] of proximos){
    if(monstro && monstro.hp > 0){
      const pendente = _mortesVisuaisPendentes.get(id);
      if(pendente){
        _spawnDefeatVisual(monstro, 'revive');
        _playDefeatSound('magic');
      }
      _mortesVisuaisPendentes.delete(id);
    }
  }
  _ultimoEstadoVisualMonstros = new Map(
    [...proximos.entries()].filter(([, m]) => m && m.hp > 0)
  );
  _ultimoEstadoVisualBaús = novosBaus;
  _ultimoEstadoVisualHerois = new Map((state.players || []).map(p => [String(p.id), {xp:p.xp, alive:p.alive, pos:p.pos}]));
}

function _capturarDerrotasERessurreicoes(state){
  const anteriores = _ultimoEstadoVisualHerois;
  const atuais = new Map((state.players || []).map(p => [String(p.id), p]));
  for(const [id, anterior] of anteriores){
    const atual = atuais.get(id);
    if(!atual || !Array.isArray(atual.pos)) continue;
    if(anterior.alive && !atual.alive){
      const chaveCena = `p:${id}`;
      if(_cenaAtiva() && CombatScene.pendingFor(chaveCena, performance.now())){
        const cmd = CombatScene.handoff(chaveCena, {
          feedback: {entry: {pos: atual.pos}, text: t('ui.hud.morte_definitiva'), kind: 'death', damageType: null, options: {}},
          death: true,
          onImpact: [() => { _spawnDefeatVisual(atual, 'hero'); _playDefeatSound('hero'); }],
        }, performance.now());
        if(cmd) _executarComandoCena(cmd);
      } else {
        _spawnDefeatVisual(atual, 'hero');
        _playDefeatSound('hero');
        _spawnCombatFeedback({pos:atual.pos}, t('ui.hud.morte_definitiva'), 'death', performance.now());
      }
    } else if(!anterior.alive && atual.alive){
      _spawnDefeatVisual(atual, 'revive');
      _playDefeatSound('magic');
    }
  }
}

function _estadoComMortosVisuais(state){
  if(!state) return state;
  let out = state;
  // Herói: enquanto a cena o faz tombar, o peão vivo precisa continuar
  // existindo (renderMap3D pula !p.alive). Cópia rasa com alive:true.
  if(window.CombatScene && Array.isArray(state.players)){
    let mudou = false;
    const players = state.players.map(p => {
      if(p && p.alive === false && CombatScene.isDying(`p:${p.id}`)){ mudou = true; return {...p, alive: true, hp: 1}; }
      return p;
    });
    if(mudou) out = { ...out, players };
  }
  if(!Array.isArray(state.monsters) || !_mortesVisuaisPendentes.size)
    return out;
  const agora = performance.now();
  const vivos = state.monsters.filter(m => m && m.hp > 0);
  const presentes = new Set(vivos.map(m => String(m.id)));
  const pendentes = [];
  for(const [id, rec] of _mortesVisuaisPendentes){
    if(agora >= rec.maxAte){
      _mortesVisuaisPendentes.delete(id);
      continue;
    }
    if(!presentes.has(id)) pendentes.push(rec.monster);
  }
  if(!pendentes.length) return out;
  return { ...out, monsters: vivos.concat(pendentes) };
}

function _limparMortesVisuais(){
  if(window.CombatScene) CombatScene.reset();
  for(const rec of _mortesVisuaisPendentes.values())
    if(rec.timer) clearTimeout(rec.timer);
  _mortesVisuaisPendentes.clear();
  _ultimoEstadoVisualMonstros = new Map();
  _ultimoEstadoVisualHerois = new Map();
  _ultimoEstadoVisualBaús = new Set();
}

// ── PAINTERS PROCEDURAIS DE MATERIAL (compartilhados 2D tile + 3D textura) ────
// Cada painter desenha UMA superfície preenchendo [ox,oy, ox+size, oy+size].
// r = função RNG determinística (0..1). Usados pelo 2D (size=CELL) e pelo 3D
// (size=256, textura cacheada) para a aparência ser idêntica nas duas vistas.
function _rng(seed){ let s=(seed>>>0)||1; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }

function paintGrass(ctx, ox, oy, size, r){
  const g=ctx.createLinearGradient(ox,oy,ox,oy+size);
  g.addColorStop(0,'#3f7a35'); g.addColorStop(1,'#2c5a26');
  ctx.fillStyle=g; ctx.fillRect(ox,oy,size,size);
  for(let n=0;n<Math.round(size*0.36);n++){ const px=ox+r()*size,py=oy+r()*size,rr=size*(0.05+r()*0.13);
    ctx.fillStyle = r()<0.5 ? 'rgba(58,110,44,0.5)' : 'rgba(96,150,60,0.4)';
    ctx.beginPath(); ctx.ellipse(px,py,rr,rr*0.7,r()*3,0,Math.PI*2); ctx.fill(); }
  const blades=Math.round(size*1.15);
  for(let n=0;n<blades;n++){ const px=ox+r()*size,py=oy+size*0.06+r()*size*0.94,h=size*(0.06+r()*0.14),lean=(r()-0.5)*size*0.08;
    const sh=70+r()*70; ctx.strokeStyle=`rgb(${(sh*0.45)|0},${sh|0},${(sh*0.35)|0})`;
    ctx.lineWidth=Math.max(1,size/64); ctx.beginPath(); ctx.moveTo(px,py); ctx.lineTo(px+lean,py-h); ctx.stroke(); }
}

function paintDirt(ctx, ox, oy, size, r){
  ctx.fillStyle='#6b4a2e'; ctx.fillRect(ox,oy,size,size);
  for(let n=0;n<Math.round(size*0.47);n++){ const px=ox+r()*size,py=oy+r()*size,rr=size*(0.06+r()*0.18);
    ctx.fillStyle = r()<0.5 ? 'rgba(60,40,24,0.5)' : 'rgba(120,88,54,0.45)';
    ctx.beginPath(); ctx.ellipse(px,py,rr,rr*0.8,r()*3,0,Math.PI*2); ctx.fill(); }
  for(let n=0;n<Math.round(size*0.2);n++){ const px=ox+r()*size,py=oy+r()*size,rr=size*(0.012+r()*0.025);
    const s=80+r()*60; ctx.fillStyle=`rgb(${s|0},${(s*0.85)|0},${(s*0.7)|0})`;
    ctx.beginPath(); ctx.ellipse(px,py,rr,rr*0.8,0,0,Math.PI*2); ctx.fill();
    ctx.fillStyle='rgba(0,0,0,0.3)'; ctx.beginPath(); ctx.ellipse(px+rr*0.4,py+rr*0.4,rr,rr*0.7,0,0,Math.PI*2); ctx.fill(); }
}

function paintSand(ctx, ox, oy, size, r){
  const grad=ctx.createLinearGradient(ox,oy,ox+size,oy+size);
  grad.addColorStop(0,'#d7b66f'); grad.addColorStop(.5,'#c7a15a'); grad.addColorStop(1,'#aa7e3e');
  ctx.fillStyle=grad; ctx.fillRect(ox,oy,size,size);
  // Ondulações de vento e pequenos grãos dão à casa o aspecto de areia desértica.
  for(let row=0; row<5; row++){
    const yy=oy+size*(.12+row*.19)+(r()-.5)*size*.06;
    ctx.strokeStyle=row%2 ? 'rgba(245,220,155,.34)' : 'rgba(111,72,27,.28)';
    ctx.lineWidth=Math.max(1,size/90); ctx.beginPath();
    ctx.moveTo(ox-size*.04,yy);
    ctx.bezierCurveTo(ox+size*.22,yy-size*.045,ox+size*.42,yy+size*.045,ox+size*.68,yy);
    ctx.bezierCurveTo(ox+size*.82,yy-size*.035,ox+size*1.02,yy+size*.035,ox+size*1.05,yy-size*.01);
    ctx.stroke();
  }
  for(let n=0;n<Math.round(size*.22);n++){
    const px=ox+r()*size, py=oy+r()*size, rr=size*(.008+r()*.022);
    ctx.fillStyle=r()<.55 ? 'rgba(91,58,24,.28)' : 'rgba(255,231,166,.35)';
    ctx.beginPath(); ctx.ellipse(px,py,rr,rr*.55,r()*Math.PI,0,Math.PI*2); ctx.fill();
  }
}

function paintLava(ctx, ox, oy, size, r){
  const grad=ctx.createLinearGradient(ox,oy,ox+size,oy+size);
  grad.addColorStop(0,'#ff8a20'); grad.addColorStop(.38,'#df3b12');
  grad.addColorStop(.72,'#8e160d'); grad.addColorStop(1,'#300b0b');
  ctx.fillStyle=grad; ctx.fillRect(ox,oy,size,size);
  // Crosta escura irregular entre veios de magma; o fluxo animado é aplicado
  // por drawFloor3D, enquanto esta textura fornece o relevo/base no 3D.
  for(let n=0;n<Math.round(size*.11);n++){
    const px=ox+r()*size, py=oy+r()*size, rw=size*(.04+r()*.12), rh=size*(.02+r()*.07);
    ctx.fillStyle='rgba(24,5,5,.62)';
    ctx.beginPath(); ctx.ellipse(px,py,rw,rh,r()*Math.PI,0,Math.PI*2); ctx.fill();
  }
  for(let n=0;n<Math.round(size*.08);n++){
    const px=ox+r()*size, py=oy+r()*size;
    ctx.fillStyle='rgba(255,183,45,.82)';
    ctx.beginPath(); ctx.arc(px,py,size*(.008+r()*.018),0,Math.PI*2); ctx.fill();
  }
}

function paintSwamp(ctx, ox, oy, size, r){
  const grad=ctx.createLinearGradient(ox,oy,ox+size,oy+size);
  grad.addColorStop(0,'#3f5b35'); grad.addColorStop(.48,'#293d2a');
  grad.addColorStop(1,'#17261d');
  ctx.fillStyle=grad; ctx.fillRect(ox,oy,size,size);
  // Lama irregular, folhas e pequenas poças; as ondulações móveis são
  // desenhadas em drawFloor3D para a superfície parecer viva.
  for(let n=0;n<Math.round(size*.18);n++){
    const px=ox+r()*size, py=oy+r()*size, rw=size*(.035+r()*.13), rh=size*(.018+r()*.065);
    ctx.fillStyle=r()<.55 ? 'rgba(9,20,15,.52)' : 'rgba(74,96,56,.34)';
    ctx.beginPath(); ctx.ellipse(px,py,rw,rh,r()*Math.PI,0,Math.PI*2); ctx.fill();
  }
  for(let n=0;n<Math.round(size*.07);n++){
    const px=ox+r()*size, py=oy+r()*size, rr=size*(.018+r()*.035);
    ctx.fillStyle='rgba(112,133,78,.38)'; ctx.beginPath(); ctx.arc(px,py,rr,0,Math.PI*2); ctx.fill();
    ctx.strokeStyle='rgba(141,164,102,.30)'; ctx.lineWidth=Math.max(1,size/85);
    ctx.beginPath(); ctx.ellipse(px,py,rr*1.8,rr*.72,r()*Math.PI,0,Math.PI*2); ctx.stroke();
  }
}

function paintWhirlpool(ctx, ox, oy, size, r, deep=false){
  // Base azul contínua igual à água, com espirais concêntricas turbulentas.
  // A textura é estática no tile, mas a rotação/ondulação é atualizada no
  // renderizador 3D; no canvas ela também é redesenhada com uma fase rápida.
  ctx.fillStyle=deep ? '#06173f' : '#0078c6'; ctx.fillRect(ox,oy,size,size);
  const cx=ox+size*.5, cy=oy+size*.5, t=Date.now()/170;
  for(let i=0;i<7;i++){
    const rr=size*(.075+i*.067+.020*Math.sin(t*1.7+i));
    ctx.strokeStyle=deep
      ? (i%2 ? 'rgba(139,207,255,.48)' : 'rgba(45,117,224,.62)')
      : (i%2 ? 'rgba(208,251,255,.66)' : 'rgba(61,190,239,.72)');
    ctx.lineWidth=Math.max(1,size*(i===0?.028:.015));
    ctx.beginPath();
    for(let a=.18;a<=Math.PI*2.08;a+=.105){
      const aa=a+t*(i%2 ? -1.02 : 1.14)+.10*Math.sin(t*2.4+i);
      const rad=rr*(1+.15*Math.sin(a*4+i*.8)+.045*Math.sin(a*9-t*1.6));
      const x=cx+Math.cos(aa)*rad, y=cy+Math.sin(aa)*rad*.68;
      if(a===.18) ctx.moveTo(x,y); else ctx.lineTo(x,y);
    }
    ctx.stroke();
  }
  // Espuma curta perto do ralo central, para quebrar o aspecto de simples
  // círculos e reforçar a sensação de água sendo sugada com violência.
  for(let i=0;i<8;i++){
    const aa=t*(i%2 ? -1.15 : 1.25)+i*.78;
    const rad=size*(.19+(i%3)*.025);
    ctx.strokeStyle=deep ? 'rgba(151,218,255,.42)' : 'rgba(224,255,255,.58)';
    ctx.lineWidth=Math.max(1,size*.010);
    ctx.beginPath();
    ctx.arc(cx+Math.cos(aa)*rad,cy+Math.sin(aa)*rad*.68,size*(.035+(i%2)*.012),aa+.5,aa+2.0);
    ctx.stroke();
  }
  const hole=ctx.createRadialGradient(cx,cy,0,cx,cy,size*.21);
  hole.addColorStop(0,deep ? 'rgba(0,5,22,.88)' : 'rgba(2,32,83,.78)');
  hole.addColorStop(.65,deep ? 'rgba(3,31,91,.72)' : 'rgba(4,72,137,.58)');
  hole.addColorStop(1,deep ? 'rgba(14,75,151,0)' : 'rgba(4,115,183,0)');
  ctx.fillStyle=hole; ctx.beginPath(); ctx.ellipse(cx,cy,size*.16,size*.11,0,0,Math.PI*2); ctx.fill();
}

function paintIce(ctx, ox, oy, size, r){
  // Lago congelado: azul frio, saturado e com reflexos mais nítidos que a
  // neve. O ruído é determinístico por casa na chamada do painter.
  const grad=ctx.createLinearGradient(ox,oy,ox+size,oy+size);
  grad.addColorStop(0,'#e3fbff'); grad.addColorStop(.24,'#86e0f5');
  grad.addColorStop(.58,'#2ca8d7'); grad.addColorStop(1,'#075d96');
  ctx.fillStyle=grad; ctx.fillRect(ox,oy,size,size);
  ctx.fillStyle='rgba(240,255,255,.30)';
  ctx.fillRect(ox,oy,size,size*.08);
  for(let i=0;i<3;i++){
    const px=ox+size*(.08+r()*.78), py=oy+size*(.14+r()*.72);
    const len=size*(.20+r()*.34);
    ctx.strokeStyle=i===0 ? 'rgba(255,255,255,.90)' : 'rgba(178,244,255,.70)';
    ctx.lineWidth=Math.max(1,size*(i===0?.012:.007));
    ctx.beginPath(); ctx.moveTo(px,py);
    ctx.lineTo(px+len*(.35+r()*.35),py+size*(r()-.5)*.10);
    ctx.lineTo(px+len,py+size*(r()-.5)*.17); ctx.stroke();
  }
  for(let i=0;i<5;i++){
    const px=ox+size*(.08+r()*.84), py=oy+size*(.08+r()*.84);
    ctx.fillStyle=`rgba(255,255,255,${(.28+r()*.42).toFixed(2)})`;
    ctx.beginPath(); ctx.ellipse(px,py,size*(.025+r()*.045),size*(.007+r()*.014),r()*Math.PI,0,Math.PI*2); ctx.fill();
  }
  ctx.strokeStyle='rgba(4,66,112,.42)'; ctx.lineWidth=Math.max(1,size*.012);
  ctx.beginPath(); ctx.moveTo(ox+size*.02,oy+size*.78);
  ctx.bezierCurveTo(ox+size*.28,oy+size*.66,ox+size*.57,oy+size*.91,ox+size*1.02,oy+size*.72); ctx.stroke();
}

function paintSnowPlain(ctx, ox, oy, size, r){
  // Banco de neve: branco e opaco, com sombras cinza muito suaves. Não deve
  // ter o brilho azul nem o contraste de uma superfície de gelo.
  const grad=ctx.createLinearGradient(ox,oy,ox+size,oy+size);
  grad.addColorStop(0,'#ffffff'); grad.addColorStop(.42,'#f6f8f7');
  grad.addColorStop(.75,'#e9eeee'); grad.addColorStop(1,'#d3dddd');
  ctx.fillStyle=grad; ctx.fillRect(ox,oy,size,size);
  // Ondulações suaves de neve acumulada, sem rejunte de pedra.
  for(let row=0;row<4;row++){
    const yy=oy+size*(.18+row*.20)+(r()-.5)*size*.06;
    ctx.strokeStyle=row%2 ? 'rgba(126,145,148,.18)' : 'rgba(255,255,255,.72)';
    ctx.lineWidth=Math.max(1,size/42); ctx.beginPath(); ctx.moveTo(ox-size*.04,yy);
    ctx.bezierCurveTo(ox+size*.22,yy-size*.06,ox+size*.47,yy+size*.06,ox+size*.72,yy);
    ctx.bezierCurveTo(ox+size*.85,yy-size*.04,ox+size*1.02,yy+size*.04,ox+size*1.05,yy-size*.01); ctx.stroke();
  }
  for(let i=0;i<7;i++){
    const px=ox+size*(.05+r()*.90), py=oy+size*(.05+r()*.90);
    ctx.fillStyle=`rgba(255,255,255,${(.22+r()*.34).toFixed(2)})`;
    ctx.beginPath(); ctx.ellipse(px,py,size*(.018+r()*.035),size*(.006+r()*.012),r()*Math.PI,0,Math.PI*2); ctx.fill();
  }
}

function paintDuneWallTop(ctx, ox, oy, size, r){
  ctx.fillStyle='#68401f'; ctx.fillRect(ox,oy,size,size);
  const cx=ox+size*(.48+(r()-.5)*.08), cy=oy+size*(.53+(r()-.5)*.08);
  const rx=size*(.52+r()*.05), ry=size*(.52+r()*.05);
  ctx.save();
  ctx.beginPath(); ctx.ellipse(cx,cy,rx,ry,0,0,Math.PI*2); ctx.clip();
  paintSand(ctx,ox,oy,size,r);
  ctx.restore();
  ctx.strokeStyle='rgba(255,226,154,.52)'; ctx.lineWidth=Math.max(1,size/22);
  ctx.beginPath(); ctx.arc(cx-size*.08,cy-size*.08,size*.31,.25*Math.PI,1.22*Math.PI); ctx.stroke();
  ctx.strokeStyle='rgba(83,48,18,.50)'; ctx.lineWidth=Math.max(1,size/18);
  ctx.beginPath(); ctx.arc(cx+size*.05,cy+size*.10,size*.38,.18*Math.PI,.88*Math.PI); ctx.stroke();
}

function paintRock(ctx, ox, oy, size, r, brown=false){
  const grad=ctx.createLinearGradient(ox,oy,ox+size,oy+size);
  grad.addColorStop(0, brown ? '#9a6b46' : '#77726e');
  grad.addColorStop(.42, brown ? '#65452f' : '#4c4949');
  grad.addColorStop(1, brown ? '#302016' : '#252527');
  ctx.fillStyle=brown ? '#21150f' : '#171719'; ctx.fillRect(ox,oy,size,size);
  // Silhueta quebrada, com faces grandes e assimétricas em vez de uma parede
  // de tijolos regular.
  const pts=[];
  const n=9;
  for(let i=0;i<n;i++){
    const a=i/n*Math.PI*2, rr=size*(.43+r()*.10);
    pts.push([ox+size*.5+Math.cos(a)*rr, oy+size*.52+Math.sin(a)*rr]);
  }
  ctx.save(); ctx.beginPath(); pts.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1])); ctx.closePath(); ctx.clip();
  ctx.fillStyle=grad; ctx.fillRect(ox,oy,size,size);
  for(let i=0;i<7;i++){
    const cx=ox+size*(.18+r()*.64), cy=oy+size*(.16+r()*.68);
    const rw=size*(.12+r()*.25), rh=size*(.09+r()*.25);
    ctx.fillStyle=brown
      ? (i%3===0 ? 'rgba(190,137,91,.25)' : i%3===1 ? 'rgba(34,20,13,.36)' : 'rgba(119,76,48,.28)')
      : (i%3===0 ? 'rgba(142,136,128,.26)' : i%3===1 ? 'rgba(22,22,25,.34)' : 'rgba(92,87,86,.26)');
    ctx.beginPath(); ctx.ellipse(cx,cy,rw,rh,r()*Math.PI,0,Math.PI*2); ctx.fill();
  }
  ctx.restore();
  ctx.strokeStyle='rgba(10,10,12,.78)'; ctx.lineWidth=Math.max(1,size/26);
  ctx.beginPath(); pts.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1])); ctx.closePath(); ctx.stroke();
  // Fissuras e veios minerais quebram a superfície sem sugerir alvenaria.
  for(let i=0;i<4;i++){
    const px=ox+size*(.22+r()*.55), py=oy+size*(.18+r()*.58);
    ctx.strokeStyle=brown
      ? (i%2 ? 'rgba(225,173,119,.24)' : 'rgba(20,11,7,.46)')
      : (i%2 ? 'rgba(207,201,187,.22)' : 'rgba(4,4,7,.42)');
    ctx.lineWidth=Math.max(1,size/75); ctx.beginPath(); ctx.moveTo(px,py);
    ctx.lineTo(px+size*(r()-.5)*.24,py+size*(.12+r()*.24));
    ctx.lineTo(px+size*(r()-.5)*.34,py+size*(.22+r()*.22)); ctx.stroke();
  }
}

function paintFrozenCaveWall(ctx, ox, oy, size, r){
  const grad=ctx.createLinearGradient(ox,oy,ox+size,oy+size);
  grad.addColorStop(0,'#88d9e8'); grad.addColorStop(.34,'#3d8ba5');
  grad.addColorStop(.72,'#20516b'); grad.addColorStop(1,'#102c43');
  ctx.fillStyle='#0b2032'; ctx.fillRect(ox,oy,size,size);
  const pts=[], n=9;
  for(let i=0;i<n;i++){
    const a=i/n*Math.PI*2, rr=size*(.42+r()*.11);
    pts.push([ox+size*.5+Math.cos(a)*rr,oy+size*.51+Math.sin(a)*rr]);
  }
  ctx.save(); ctx.beginPath(); pts.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1])); ctx.closePath(); ctx.clip();
  ctx.fillStyle=grad; ctx.fillRect(ox,oy,size,size);
  for(let i=0;i<8;i++){
    const px=ox+size*(.12+r()*.72), py=oy+size*(.10+r()*.72);
    const rw=size*(.09+r()*.17), rh=size*(.07+r()*.18);
    ctx.fillStyle=i%3===0 ? 'rgba(210,250,255,.34)' : i%3===1 ? 'rgba(5,30,48,.34)' : 'rgba(80,170,193,.30)';
    ctx.beginPath(); ctx.ellipse(px,py,rw,rh,r()*Math.PI,0,Math.PI*2); ctx.fill();
  }
  ctx.restore();
  ctx.strokeStyle='rgba(5,25,39,.80)'; ctx.lineWidth=Math.max(1,size/25);
  ctx.beginPath(); pts.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1])); ctx.closePath(); ctx.stroke();
  for(let i=0;i<5;i++){
    const px=ox+size*(.18+r()*.58), py=oy+size*(.12+r()*.66);
    ctx.strokeStyle=i%2 ? 'rgba(190,247,255,.55)' : 'rgba(8,39,61,.62)';
    ctx.lineWidth=Math.max(1,size/78); ctx.beginPath(); ctx.moveTo(px,py);
    ctx.lineTo(px+size*(r()-.5)*.18,py+size*(.10+r()*.15));
    ctx.lineTo(px+size*(r()-.5)*.24,py+size*(.22+r()*.17)); ctx.stroke();
  }
  for(let i=0;i<4;i++){
    const px=ox+size*(.12+r()*.76), py=oy+size*(.12+r()*.70);
    ctx.fillStyle='rgba(238,255,255,.72)'; ctx.beginPath(); ctx.arc(px,py,size*(.012+r()*.022),0,Math.PI*2); ctx.fill();
  }
}

function paintSnowDuneWall(ctx, ox, oy, size, r){
  // A duna de neve acompanha a leitura irregular da duna de areia: vários
  // picos assimétricos, encostas sobrepostas e sulcos, em vez de uma única
  // rampa diagonal. A neve continua clara e fria, sem brilho de gelo.
  const grad=ctx.createLinearGradient(ox,oy,ox,oy+size);
  grad.addColorStop(0,'#ffffff'); grad.addColorStop(.34,'#f2f6f6');
  grad.addColorStop(.72,'#d5e0e0'); grad.addColorStop(1,'#aebfc1');
  ctx.fillStyle='#80999d'; ctx.fillRect(ox,oy,size,size);

  const ridge = [
    [0.00,.86], [0.10,.62+r()*.08], [0.20,.38+r()*.10],
    [0.31,.50+r()*.08], [0.43,.25+r()*.10], [0.55,.18+r()*.08],
    [0.66,.39+r()*.10], [0.77,.31+r()*.08], [0.88,.49+r()*.09],
    [1.00,.22+r()*.08],
  ];
  ctx.fillStyle=grad;
  ctx.beginPath();
  ctx.moveTo(ox,oy+size);
  ctx.lineTo(ox,oy+size*ridge[0][1]);
  for(let i=1;i<ridge.length;i++){
    const prev=ridge[i-1], cur=ridge[i];
    const mx=ox+size*(prev[0]+(cur[0]-prev[0])*.5);
    ctx.quadraticCurveTo(mx,oy+size*(Math.min(prev[1],cur[1])-.10-r()*.05),ox+size*cur[0],oy+size*cur[1]);
  }
  ctx.lineTo(ox+size,oy+size); ctx.closePath(); ctx.fill();

  // Crista de neve iluminada e uma sombra quebrada logo abaixo, como nas
  // ondulações da areia, para destacar os vários volumes da duna.
  ctx.strokeStyle='rgba(255,255,255,.90)'; ctx.lineWidth=Math.max(1,size/25);
  ctx.beginPath(); ctx.moveTo(ox+size*.01,oy+size*(ridge[0][1]-.01));
  for(let i=1;i<ridge.length;i++){
    const prev=ridge[i-1], cur=ridge[i];
    const mx=ox+size*(prev[0]+(cur[0]-prev[0])*.5);
    ctx.quadraticCurveTo(mx,oy+size*(Math.min(prev[1],cur[1])-.11),ox+size*cur[0],oy+size*(cur[1]-.01));
  }
  ctx.stroke();
  for(let row=0;row<4;row++){
    const yy=oy+size*(.48+row*.12)+(r()-.5)*size*.05;
    ctx.strokeStyle=row%2 ? 'rgba(111,137,141,.24)' : 'rgba(255,255,255,.42)';
    ctx.lineWidth=Math.max(1,size/78); ctx.beginPath();
    ctx.moveTo(ox+size*(.04+r()*.05),yy);
    ctx.bezierCurveTo(ox+size*.25,yy-size*(.06+r()*.025),ox+size*.49,yy+size*(.06+r()*.025),ox+size*.70,yy-size*.01);
    ctx.bezierCurveTo(ox+size*.82,yy-size*.05,ox+size*.94,yy+size*.04,ox+size*.98,yy-size*.02); ctx.stroke();
  }
  for(let i=0;i<5;i++){
    const px=ox+size*(.08+r()*.82), py=oy+size*(.16+r()*.36);
    ctx.fillStyle=`rgba(255,255,255,${(.30+r()*.34).toFixed(2)})`;
    ctx.beginPath(); ctx.ellipse(px,py,size*(.025+r()*.045),size*(.008+r()*.014),r()*Math.PI,0,Math.PI*2); ctx.fill();
  }
}

function paintBrick(ctx, ox, oy, size, r, base, mortar){
  ctx.fillStyle=mortar; ctx.fillRect(ox,oy,size,size);
  const rh=size*0.17, bw=size*0.5; let row=0;
  for(let by=oy; by<oy+size; by+=rh){ const off=(row%2)?bw*0.5:0;
    for(let bx=ox-off; bx<ox+size; bx+=bw){ const v=(r()*16-8)|0;
      ctx.fillStyle=`rgb(${Math.max(0,base[0]+v)},${Math.max(0,base[1]+v)},${Math.max(0,base[2]+v)})`;
      ctx.fillRect(bx+1.5, by+1.5, bw-3, rh-3);
      ctx.fillStyle='rgba(255,255,255,0.05)'; ctx.fillRect(bx+1.5, by+1.5, bw-3, Math.max(1,size/40)); }
    row++; }
}

function paintCave(ctx, ox, oy, size, r){
  ctx.fillStyle='#241509'; ctx.fillRect(ox,oy,size,size);   // fundo marrom escuro (fendas)
  const step=size*0.22, pts=[];
  for(let gy=0;gy<5;gy++) for(let gx=0;gx<5;gx++)
    pts.push([ox+gx*step+step*0.3+(r()-0.5)*step*0.72, oy+gy*step+step*0.3+(r()-0.5)*step*0.72]);
  for(const p of pts){ const rad=size*(0.09+r()*0.10), nv=7+(r()*4|0), b=95+r()*60;
    // marrom forte: muito vermelho, pouco azul
    const R=Math.min(255,b*1.2|0), G=Math.min(255,b*0.72|0), B=Math.min(255,b*0.42|0);
    ctx.fillStyle=`rgb(${R},${G},${B})`;
    ctx.beginPath();
    for(let k=0;k<nv;k++){ const a=k/nv*Math.PI*2, rr=rad*(0.55+r()*0.75);  // contorno bem irregular
      const xx=p[0]+Math.cos(a)*rr, yy=p[1]+Math.sin(a)*rr; k?ctx.lineTo(xx,yy):ctx.moveTo(xx,yy); }
    ctx.closePath(); ctx.fill();
    ctx.strokeStyle='rgba(0,0,0,0.6)'; ctx.lineWidth=Math.max(1,size/40); ctx.stroke();
    // sombra/fenda (relevo rugoso) e realce de tocha
    ctx.fillStyle='rgba(0,0,0,0.30)';
    ctx.beginPath(); ctx.ellipse(p[0]+rad*0.28,p[1]+rad*0.32,rad*0.5,rad*0.34,0,0,Math.PI*2); ctx.fill();
    ctx.fillStyle='rgba(255,200,130,0.16)';
    ctx.beginPath(); ctx.ellipse(p[0]-rad*0.32,p[1]-rad*0.36,rad*0.42,rad*0.28,0,0,Math.PI*2); ctx.fill(); }
}

// Lajota de pedra (textura 3D) numa cor-base — usada para pedra_negra (preta forte).
function paintStone(ctx, ox, oy, size, r, base){
  ctx.fillStyle='#06050a'; ctx.fillRect(ox,oy,size,size);
  const sub=2, sp=size/sub, grt=size*0.03;
  for(let sy=0;sy<sub;sy++) for(let sx=0;sx<sub;sx++){
    const v=(r()*22-11)|0, bx=ox+sx*sp+grt, by=oy+sy*sp+grt, bw=sp-grt*1.6, bh=sp-grt*1.6;
    const r0=Math.max(0,base[0]+v), g0=Math.max(0,base[1]+v), b0=Math.max(0,base[2]+Math.floor(v*0.7));
    const g=ctx.createLinearGradient(bx,by,bx+bw,by+bh);
    g.addColorStop(0,`rgb(${r0+26},${g0+24},${b0+24})`);
    g.addColorStop(0.5,`rgb(${r0},${g0},${b0})`);
    g.addColorStop(1,`rgb(${Math.max(0,r0-18)},${Math.max(0,g0-16)},${Math.max(0,b0-14)})`);
    ctx.fillStyle=g; ctx.fillRect(bx,by,bw,bh);
    ctx.fillStyle='rgba(0,0,0,0.42)'; ctx.fillRect(bx,by+bh-2,bw,2); ctx.fillRect(bx+bw-2,by,2,bh);
    if(r()<0.3){ ctx.strokeStyle='rgba(0,0,0,0.5)'; ctx.lineWidth=Math.max(1,size/120);
      const cx=bx+r()*bw, cy=by+r()*bh; ctx.beginPath(); ctx.moveTo(cx,cy); ctx.lineTo(cx+size*0.06,cy+size*0.04); ctx.stroke(); }
  }
}

function paintRubble(ctx, ox, oy, size, r){
  ctx.fillStyle='#2b2620'; ctx.fillRect(ox,oy,size,size);
  for(let n=0;n<Math.round(size*0.13);n++){ const px=ox+size*0.06+r()*size*0.88,py=oy+size*0.06+r()*size*0.88,
      rw=size*(0.06+r()*0.13),rh=size*(0.05+r()*0.10), t=60+r()*55;
    ctx.fillStyle=`rgb(${t|0},${(t-7)|0},${(t-16)|0})`;
    ctx.beginPath(); ctx.ellipse(px,py,rw,rh,(r()-0.5)*3,0,Math.PI*2); ctx.fill();
    ctx.strokeStyle='rgba(0,0,0,0.5)'; ctx.lineWidth=Math.max(1,size/64); ctx.stroke();
    ctx.fillStyle='rgba(255,235,200,0.10)'; ctx.fillRect(px-rw*0.5,py-rh*0.7,rw,Math.max(1.5,size/40)); }
}

// ── PALETAS 2D DOS MATERIAIS ─────────────────────────────────────────────────
// base [r,g,b] da pedra/superfície; accent decide os detalhes procedurais.
// Espelha os ids de server.MATERIAIS. Pisos coloridos são cosméticos.
const MAT_PALETTE_2D = {
  // pisos
  pedra_cinza: { base: [44, 42, 50],  accent: 'stone' },
  terra:       { base: [74, 56, 38],  accent: 'dirt'  },
  areia_deserto: { base: [196, 154, 83], accent: 'sand' },
  grama:       { base: [46, 78, 40],  accent: 'grass' },
  agua:        { base: [0, 120, 202], accent: 'water' },
  agua_profunda: { base: [6, 23, 63], accent: 'deepWater' },
  rodamoinho:  { base: [0, 120, 202], accent: 'whirlpool' },
  rodamoinho_profundo: { base: [6, 23, 63], accent: 'deepWhirlpool' },
  piso_congelado: { base: [48, 169, 221], accent: 'ice' },
  planicie_nevada: { base: [232, 239, 239], accent: 'snowPlain' },
  lava:        { base: [214, 59, 19], accent: 'lava' },
  pantano:     { base: [53, 78, 49], accent: 'swamp' },
  pedra_negra: { base: [20, 19, 24],  accent: 'stone' },
  madeira_escura: { base: [59, 32, 15], accent: 'woodFloor' },
  entulho:     { base: [70, 66, 58],  accent: 'rubble' },
  // paredes (topo)
  pedra_normal:  { base: [132, 130, 140], accent: 'wallStone' },
  enegrecida:    { base: [24, 23, 28],   accent: 'blackbrick' },
  pedra_caverna: { base: [120, 82, 46],  accent: 'cave' },
  caverna_congelada: { base: [75, 143, 168], accent: 'frozenCave' },
  desmoronada:   { base: [96, 88, 76],   accent: 'wallRubble' },
  madeira:        { base: [74, 39, 15], accent: 'woodWall' },
  duna_deserto: { base: [190, 139, 67], accent: 'duneWall' },
  rocha:        { base: [72, 70, 70], accent: 'rockWall' },
  rocha_marrom: { base: [117, 75, 50], accent: 'brownRockWall' },
  duna_neve: { base: [201, 229, 239], accent: 'snowDune' },
};
// Resolve o material de uma casa para render (default por estrutura do tile).
function matDaCasa(state, x, y){
  const m = state && state.materiais;
  const secret = (state && state.secret_passages || []).find(sp =>
    sp && sp.pos && sp.pos[0] === x && sp.pos[1] === y);
  const secretId = secret && secret.wall_material;
  const id = secretId && MAT_PALETTE_2D[secretId] ? secretId : (m && m[`${x},${y}`]);
  if(id && MAT_PALETTE_2D[id]) return id;
  return (state.tiles[y][x] === TILE_WALL) ? 'pedra_normal' : 'pedra_cinza';
}

// Elevação visual do terreno autorado. Não confundir com `altura`, que é o
// eixo de voo das criaturas e continua sendo usado pelas regras de combate.
const TERRENO_ELEVACAO_STEP_3D = 0.24;
// Espelha ELEVACAO_TERRENO_MIN/MAX do server.py: o servidor já recusa fora
// disto, mas o cliente também desenha estado antigo (masmorra salva com outro
// teto) e não pode esticar a geometria por causa de um número solto.
const ELEVACAO_TERRENO_MIN = -1, ELEVACAO_TERRENO_MAX = 10;
function elevacaoTerreno(state, x, y){
  const n = Number(state?.elevacoes?.[`${x},${y}`]);
  return Number.isInteger(n)
    ? Math.max(ELEVACAO_TERRENO_MIN, Math.min(ELEVACAO_TERRENO_MAX, n)) : 0;
}
function topoTerreno3D(state, x, y, TH = 0.22){
  return TH + elevacaoTerreno(state, x, y) * TERRENO_ELEVACAO_STEP_3D;
}

// A ponte é uma superfície acima do material/terreno que está embaixo dela.
// O topo do tabuleiro fica 0,20 acima do topo da elevação usada como base
// (deck: centro +0,145, espessura 0,105). Não misturar este helper com
// topoTerreno3D: efeitos do material inferior, como lava e água, continuam
// precisando permanecer abaixo da ponte.
const PONTE_SUPERFICIE_OFFSET_3D = 0.20;
function ponteNaCasa3D(state, x, y){
  return (state?.pontes || []).find(ponte =>
    _bridgeTiles2D(ponte).some(([px, py]) => px === x && py === y)) || null;
}
function topoSuperficie3D(state, x, y, TH = 0.22){
  const ponte = ponteNaCasa3D(state, x, y);
  if(ponte){
    const nivel = Number(ponte.altura ?? ponte.height);
    const nivelValido = Number.isInteger(nivel)
      ? Math.max(ELEVACAO_TERRENO_MIN, Math.min(ELEVACAO_TERRENO_MAX, nivel))
      : elevacaoTerreno(state, x, y);
    return TH + nivelValido * TERRENO_ELEVACAO_STEP_3D + PONTE_SUPERFICIE_OFFSET_3D;
  }
  return topoTerreno3D(state, x, y, TH);
}

// Elevação da base visual de um peão (a raiz do grupo fica TH abaixo do topo
// da superfície). A ponte é uma camada própria: quando o peão entra nela, a
// altura visual precisa acompanhar o deck, mesmo que o piso abaixo seja lava,
// água ou uma parede.
function baseSuperficiePonte3D(state, x, y, TH = 0.22){
  if(!ponteNaCasa3D(state, x, y)) return null;
  return topoSuperficie3D(state, x, y, TH) - TH;
}

// Durante a animação de um passo o peão ocupa coordenadas fracionárias, então
// não é possível consultar a ponte apenas com um par inteiro. Interpolamos a
// base entre as casas do segmento quando uma das pontas é ponte; assim o peão
// sobe/desce suavemente e termina apoiado no deck.
function basePonteInterpolada3D(state, pontos, fracao, fallback, TH = 0.22){
  if(!Array.isArray(pontos) || pontos.length < 2) return null;
  const segmentos = pontos.length - 1;
  const f = Math.max(0, Math.min(segmentos, Number(fracao) || 0));
  const i = Math.min(Math.floor(f), segmentos - 1);
  const t = f >= segmentos ? 1 : f - i;
  const a = pontos[i], b = pontos[i + 1];
  const ya = baseSuperficiePonte3D(state, a[0], a[1], TH);
  const yb = baseSuperficiePonte3D(state, b[0], b[1], TH);
  if(ya === null && yb === null) return null;
  const inicio = ya === null ? fallback : ya;
  const fim = yb === null
    ? topoTerreno3D(state, b[0], b[1], TH) - TH
    : yb;
  return inicio + (fim - inicio) * easeInOut(t);
}

function drawElevacao2D(ctx, state, x, y){
  const level = elevacaoTerreno(state, x, y);
  if(!level) return;
  const X = x * CELL, Y = y * CELL;
  // Mesmo teto do editor: sem ele a borda de sombra de um nível alto engolia
  // metade da casa. Inerte de −1 a +7 nesta escala de CELL.
  const depth = Math.min(CELL * 0.4, 2 + Math.abs(level) * 3);
  const vizinho = (nx, ny) => elevacaoTerreno(state, nx, ny);
  ctx.save();
  if(level > 0){
    ctx.fillStyle = 'rgba(7, 7, 12, .38)';
    if(vizinho(x + 1, y) < level) ctx.fillRect(X + CELL - depth, Y + 1, depth, CELL - 1);
    if(vizinho(x, y + 1) < level) ctx.fillRect(X + 1, Y + CELL - depth, CELL - 1, depth);
    ctx.fillStyle = 'rgba(255, 255, 255, .16)';
    ctx.fillRect(X + 1, Y + 1, CELL - 2, 2);
    ctx.fillRect(X + 1, Y + 1, 2, CELL - 2);
    if(state.transicao_altura === 'rampa'){
      ctx.fillStyle = 'rgba(244, 217, 139, .13)';
      if(vizinho(x + 1, y) < level){
        ctx.beginPath(); ctx.moveTo(X + CELL - depth, Y + 2);
        ctx.lineTo(X + CELL - 2, Y + CELL - 2); ctx.lineTo(X + CELL - 2, Y + 2);
        ctx.closePath(); ctx.fill();
      }
      if(vizinho(x, y + 1) < level){
        ctx.beginPath(); ctx.moveTo(X + 2, Y + CELL - depth);
        ctx.lineTo(X + CELL - 2, Y + CELL - 2); ctx.lineTo(X + 2, Y + CELL - 2);
        ctx.closePath(); ctx.fill();
      }
    }
  }else{
    ctx.fillStyle = 'rgba(0, 0, 0, .26)';
    ctx.fillRect(X + 2, Y + 2, CELL - 4, CELL - 4);
    ctx.strokeStyle = 'rgba(100, 210, 255, .35)'; ctx.lineWidth = 1;
    ctx.strokeRect(X + 2, Y + 2, CELL - 4, CELL - 4);
  }
  ctx.restore();
}

// ── DIABLO-STYLE FLOOR TILE — dark charcoal flagstones with blood & bone details
function drawFloor3D(ctx, x, y, isReachable, isAttackable, isWeaponPreview, matId){
  const X=x*CELL, Y=y*CELL;
  const h=((x*7919)^(y*3467)^(x<<5)^(y>>2))&0xFFFF;
  const pal = MAT_PALETTE_2D[matId] || MAT_PALETTE_2D.pedra_cinza;
  const [BR, BG, BB] = pal.base;

  // Estilos não-pedra têm painter próprio (sem grade de lajota).
  if(pal.accent==='water' || pal.accent==='deepWater'){
    // Sem margem, rejunte ou ruído por casa: a água forma uma única massa.
    // As ondas usam coordenadas globais, portanto continuam naturalmente de
    // uma célula para a seguinte em vez de reiniciar em cada quadrado.
    const profunda = pal.accent==='deepWater';
    ctx.fillStyle=profunda ? '#06173f' : '#0078c6'; ctx.fillRect(X,Y,CELL,CELL);
    const firstWave=Math.floor(Y/14)*14;
    for(let yy=firstWave; yy<Y+CELL; yy+=14){
      const phase=((yy/14)*17)%19;
      ctx.strokeStyle=profunda ? 'rgba(68,133,214,0.22)' : 'rgba(155,235,255,0.30)'; ctx.lineWidth=1.35; ctx.beginPath();
      ctx.moveTo(X,yy);
      ctx.quadraticCurveTo(X+CELL*.25,yy-2.5+(phase%3),X+CELL*.5,yy);
      ctx.quadraticCurveTo(X+CELL*.75,yy+2.5-(phase%3),X+CELL,yy);
      ctx.stroke();
    }
  }
  else if(pal.accent==='grass'){ paintGrass(ctx, X, Y, CELL, _rng((x*53^y*97^7)>>>0)); }
  else if(pal.accent==='dirt'){ paintDirt(ctx, X, Y, CELL, _rng((x*29^y*71^3)>>>0)); }
  else if(pal.accent==='sand'){ paintSand(ctx, X, Y, CELL, _rng((x*43^y*83^11)>>>0)); }
  else if(pal.accent==='lava'){
    paintLava(ctx, X, Y, CELL, _rng((x*61^y*107^19)>>>0));
  }
  else if(pal.accent==='swamp'){
    paintSwamp(ctx, X, Y, CELL, _rng((x*67^y*131^23)>>>0));
  }
  else if(pal.accent==='whirlpool' || pal.accent==='deepWhirlpool'){
    // O vortex completo é desenhado uma única vez por área contínua em
    // _drawAnimatedTerrain2D; aqui fica apenas a base para não repetir um
    // pequeno redemoinho em cada casa.
    ctx.fillStyle = pal.accent === 'deepWhirlpool' ? '#06173f' : '#0078c6';
    ctx.fillRect(X, Y, CELL, CELL);
  }
  else if(pal.accent==='ice'){
    paintIce(ctx, X, Y, CELL, _rng((x*71^y*149^29)>>>0));
  }
  else if(pal.accent==='snowPlain'){
    paintSnowPlain(ctx, X, Y, CELL, _rng((x*79^y*163^31)>>>0));
  }
  else if(pal.accent==='woodFloor'){
    ctx.fillStyle='#241108'; ctx.fillRect(X,Y,CELL,CELL);
    const boards=4, bh=CELL/boards;
    for(let row=0;row<boards;row++){
      const yy=Y+row*bh, tone=((h>>(row*3))&11)-5;
      const grad=ctx.createLinearGradient(X,yy,X+CELL,yy+bh);
      grad.addColorStop(0,`rgb(${67+tone},${36+tone},${17+tone})`);
      grad.addColorStop(.55,`rgb(${49+tone},${24+tone},${10+tone})`);
      grad.addColorStop(1,`rgb(${31+tone},${14+tone},${6+tone})`);
      ctx.fillStyle=grad;ctx.fillRect(X+1,yy+1,CELL-2,bh-2);
      ctx.strokeStyle='rgba(6,2,1,.85)';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(X,yy+bh-1);ctx.lineTo(X+CELL,yy+bh-1);ctx.stroke();
      ctx.strokeStyle='rgba(183,110,47,.17)';ctx.lineWidth=.7;ctx.beginPath();ctx.moveTo(X+4,yy+bh*.47);ctx.bezierCurveTo(X+CELL*.32,yy+bh*.16,X+CELL*.72,yy+bh*.78,X+CELL-4,yy+bh*.42);ctx.stroke();
    }
  }
  else {
  // Deep mortar joints — near-black with faint blue-gray
  ctx.fillStyle='#06050a';
  ctx.fillRect(X,Y,CELL,CELL);

  // 2×2 flagstone slabs — dark charcoal Diablo palette
  const sub=2, sp=CELL/sub, grt=2;
  for(let sy=0;sy<sub;sy++) for(let sx=0;sx<sub;sx++){
    const sh=((h^(sx*37+sy*11))^(sx<<9)^(sy<<5))&0xFFFF;
    const v=(sh%24)-12;

    const bx=X+sx*sp+grt, by=Y+sy*sp+grt;
    const bw=sp-grt*1.5, bh=sp-grt*1.5;

    // Dark gray-charcoal stone — slight blue-purple undertone (cave feel)
    const r0=Math.min(255,BR+v), g0=Math.min(255,BG+v), b0=Math.min(255,BB+Math.floor(v*0.6));

    // Gradient: top-left torch-lit, bottom-right shadow
    const sg=ctx.createLinearGradient(bx,by,bx+bw,by+bh);
    sg.addColorStop(0,  `rgb(${Math.min(255,r0+32)},${Math.min(255,g0+28)},${Math.min(255,b0+24)})`);
    sg.addColorStop(0.5,`rgb(${r0},${g0},${b0})`);
    sg.addColorStop(1,  `rgb(${Math.max(0,r0-24)},${Math.max(0,g0-20)},${Math.max(0,b0-18)})`);
    ctx.fillStyle=sg; ctx.fillRect(bx,by,bw,bh);

    // Torch-warm bevel top/left
    ctx.fillStyle='rgba(255,180,60,0.07)';
    ctx.fillRect(bx,by,bw,2); ctx.fillRect(bx,by,2,bh);
    // Deep bevel bottom/right
    ctx.fillStyle='rgba(0,0,0,0.40)';
    ctx.fillRect(bx,by+bh-2,bw,2); ctx.fillRect(bx+bw-2,by,2,bh);

    // Fissure / crack
    if((sh%9)===0){
      ctx.strokeStyle='rgba(0,0,0,0.52)'; ctx.lineWidth=0.8;
      const cx2=bx+5+(sh%Math.max(1,bw-14|0)), cy2=by+5+((sh>>4)%Math.max(1,bh-14|0));
      ctx.beginPath(); ctx.moveTo(cx2,cy2); ctx.lineTo(cx2+4+(sh%6),cy2+3+(sh%5)); ctx.stroke();
    }
    // Blood pool
    if((sh%19)===3){
      ctx.fillStyle='rgba(95,6,4,0.22)';
      ctx.beginPath(); ctx.ellipse(
        bx+5+(sh%Math.max(1,bw-14|0)), by+5+((sh>>3)%Math.max(1,bh-14|0)),
        5+(sh%5), 3+(sh%3), (sh%8)*0.4, 0, Math.PI*2); ctx.fill();
    }
    // Bone shard
    if((sh%31)===7){
      ctx.fillStyle='rgba(155,145,115,0.20)';
      ctx.fillRect(bx+4+(sh%Math.max(1,bw-12|0)), by+4+((sh>>5)%Math.max(1,bh-12|0)),
                   Math.min(7+(sh%5),bw-8), Math.min(2+(sh%2),bh-8));
    }
    // Dark moss patch
    if((sh%23)===11){
      ctx.fillStyle='rgba(20,38,14,0.28)';
      ctx.fillRect(bx+3+(sh%Math.max(1,bw-12|0)), by+3+((sh>>6)%Math.max(1,bh-12|0)),
                   Math.min(9+(sh%6),bw-6), Math.min(6+(sh%4),bh-6));
    }
  }
  }

  // Reachable tile highlight (blue) — opacity driven by _movePulse for slow pulsing
  if(isReachable){
    const pa = 0.70 + 0.30 * _movePulse;   // stroke: 0.70 → 1.00
    const fa = 0.26 + 0.26 * _movePulse;   // fill:   0.26 → 0.52
    const da = 0.65 + 0.35 * _movePulse;   // corner dots: 0.65 → 1.00
    ctx.strokeStyle=`rgba(60,140,255,${pa.toFixed(2)})`; ctx.lineWidth=2;
    ctx.strokeRect(X+2,Y+2,CELL-4,CELL-4);
    ctx.fillStyle=`rgba(30,107,255,${fa.toFixed(2)})`;
    ctx.fillRect(X+2,Y+2,CELL-4,CELL-4);
    ctx.fillStyle=`rgba(150,195,255,${da.toFixed(2)})`;
    const d=4;
    for(const [cx3,cy3] of [[X+d,Y+d],[X+CELL-d,Y+d],[X+d,Y+CELL-d],[X+CELL-d,Y+CELL-d]]){
      ctx.beginPath(); ctx.arc(cx3,cy3,1.8,0,Math.PI*2); ctx.fill();
    }
  }
  // Attackable tile highlight (red)
  if(isAttackable){
    ctx.strokeStyle='rgba(255,60,60,0.78)'; ctx.lineWidth=2;
    ctx.strokeRect(X+2,Y+2,CELL-4,CELL-4);
    ctx.fillStyle='rgba(255,30,30,0.13)';
    ctx.fillRect(X+2,Y+2,CELL-4,CELL-4);
    ctx.fillStyle='rgba(255,120,120,0.68)';
    const d=4;
    for(const [cx3,cy3] of [[X+d,Y+d],[X+CELL-d,Y+d],[X+d,Y+CELL-d],[X+CELL-d,Y+CELL-d]]){
      ctx.beginPath(); ctx.arc(cx3,cy3,1.8,0,Math.PI*2); ctx.fill();
    }
  }
  // Weapon range preview — área de alcance da arma (vermelho forte, hover no ícone)
  if(isWeaponPreview){
    ctx.fillStyle='rgba(220,0,0,0.52)';
    ctx.fillRect(X+1,Y+1,CELL-2,CELL-2);
    ctx.strokeStyle='rgba(255,0,0,0.98)'; ctx.lineWidth=2.5;
    ctx.strokeRect(X+2,Y+2,CELL-4,CELL-4);
    // borda interna luminosa
    ctx.strokeStyle='rgba(255,120,80,0.55)'; ctx.lineWidth=1;
    ctx.strokeRect(X+4,Y+4,CELL-8,CELL-8);
    // pontos de canto marcados
    ctx.fillStyle='rgba(255,80,40,1.0)';
    const d=4;
    for(const [cx3,cy3] of [[X+d,Y+d],[X+CELL-d,Y+d],[X+d,Y+CELL-d],[X+CELL-d,Y+CELL-d]]){
      ctx.beginPath(); ctx.arc(cx3,cy3,2.5,0,Math.PI*2); ctx.fill();
    }
  }
}

// ── ENTULHO 2D — monte de pedras desmoronadas (bloqueia movimento e visão) ───
function drawEntulho2D(ctx, x, y){
  const X=x*CELL, Y=y*CELL, h=((x*8161)^(y*5101))&0xFFFF;
  // base sombreada sob o monte
  ctx.fillStyle='rgba(0,0,0,0.35)';
  ctx.fillRect(X+2, Y+2, CELL-4, CELL-4);
  // pedras empilhadas
  const pedras=6;
  for(let i=0;i<pedras;i++){
    const sh=(h^(i*2917))&0xFFFF;
    const px=X+4+(sh%Math.max(1,CELL-12)), py=Y+5+((sh>>4)%Math.max(1,CELL-12));
    const rw=5+(sh%6), rh=4+((sh>>3)%5);
    const tone=70+((sh>>6)%40);
    ctx.fillStyle=`rgb(${tone},${tone-6},${tone-14})`;
    ctx.beginPath(); ctx.ellipse(px,py,rw,rh,(sh%6)*0.3,0,Math.PI*2); ctx.fill();
    ctx.strokeStyle='rgba(0,0,0,0.5)'; ctx.lineWidth=1; ctx.stroke();
    ctx.fillStyle='rgba(255,235,200,0.10)';  // brilho de tocha no topo
    ctx.fillRect(px-rw*0.5, py-rh*0.7, rw, 1.5);
  }
}

// ── DOOR TILE — closed = heavy wooden leaf; open = stone frame with dark gap ──
// Orientation is inferred from neighbouring walls, then adjusted by the
// editor's optional door_orientations (90° clockwise per unit).
function drawDoor2D(ctx, state, x, y, closed){
  const X=x*CELL, Y=y*CELL, T=state.tiles, H=T.length, W=T[0].length;
  const isWall=(tx,ty)=> ty<0||tx<0||ty>=H||tx>=W || T[ty][tx]===TILE_WALL;
  // Eixo da passagem: paredes à esquerda E direita ⇒ corredor sobe/desce, então
  // a folha atravessa na horizontal (vertical=true). Senão, folha vertical.
  const vertical = isWall(x-1,y) && isWall(x+1,y);
  const extraTurns = GS.doorOrientation(state, x, y);
  const angle = (vertical ? 0 : Math.PI/2) + (extraTurns == null ? 0 : extraTurns * Math.PI/2);
  ctx.save();
  ctx.translate(X+CELL/2, Y+CELL/2); ctx.rotate(angle); ctx.translate(-(X+CELL/2), -(Y+CELL/2));
  if(closed){
    const m=8;                         // margem dentro da casa
    let dx, dy, dw, dh;
    if(vertical){ dx=X+2;   dy=Y+m;    dw=CELL-4;  dh=CELL-2*m; }   // folha horizontal
    else        { dx=X+m;   dy=Y+2;    dw=CELL-2*m; dh=CELL-4;  }   // folha vertical
    // moldura de pedra escura
    ctx.fillStyle='#15110c'; ctx.fillRect(X+1,Y+1,CELL-2,CELL-2);
    // madeira
    const grd=ctx.createLinearGradient(dx,dy,dx+dw,dy+dh);
    grd.addColorStop(0,'#5a3a1c'); grd.addColorStop(0.5,'#7a5028'); grd.addColorStop(1,'#4a2e16');
    ctx.fillStyle=grd; ctx.fillRect(dx,dy,dw,dh);
    // tábuas
    ctx.strokeStyle='rgba(20,12,6,0.8)'; ctx.lineWidth=2;
    const planks=3;
    for(let i=1;i<planks;i++){
      ctx.beginPath();
      if(vertical){ const px=dx+dw*i/planks; ctx.moveTo(px,dy); ctx.lineTo(px,dy+dh); }
      else        { const py=dy+dh*i/planks; ctx.moveTo(dx,py); ctx.lineTo(dx+dw,py); }
      ctx.stroke();
    }
    // bandas de ferro
    ctx.strokeStyle='#2a2a30'; ctx.lineWidth=3;
    if(vertical){
      for(const fy of [dy+dh*0.28, dy+dh*0.72]){ ctx.beginPath(); ctx.moveTo(dx,fy); ctx.lineTo(dx+dw,fy); ctx.stroke(); }
    } else {
      for(const fx of [dx+dw*0.28, dx+dw*0.72]){ ctx.beginPath(); ctx.moveTo(fx,dy); ctx.lineTo(fx,dy+dh); ctx.stroke(); }
    }
    // borda
    ctx.strokeStyle='#241608'; ctx.lineWidth=2; ctx.strokeRect(dx,dy,dw,dh);
    // argola/maçaneta
    ctx.strokeStyle='#d8c070'; ctx.lineWidth=2.5;
    ctx.beginPath(); ctx.arc(X+CELL/2, Y+CELL/2, 5, 0, Math.PI*2); ctx.stroke();
  } else {
    // Porta aberta: batentes de madeira nas laterais da passagem + vão escuro.
    ctx.fillStyle='rgba(8,6,4,0.45)';
    ctx.fillRect(X+CELL*0.18, Y+CELL*0.18, CELL*0.64, CELL*0.64);
    ctx.fillStyle='#5a3a1c';
    const jamb=6;
    if(vertical){   // batentes em cima e embaixo
      ctx.fillRect(X+2, Y+2, CELL-4, jamb);
      ctx.fillRect(X+2, Y+CELL-2-jamb, CELL-4, jamb);
    } else {        // batentes nas laterais
      ctx.fillRect(X+2, Y+2, jamb, CELL-4);
      ctx.fillRect(X+CELL-2-jamb, Y+2, jamb, CELL-4);
    }
  }
  ctx.restore();
}

// ── 3D WALL SOUTH FACE — visible stone masonry face (the wall's front face)
function drawWallSouthFace(ctx, x, y, matId){
  const X=x*CELL, Y=y*CELL;
  const faceH=WALL_RISE+6;  // height of visible stone face
  const faceY=Y+CELL-1;     // starts at bottom of wall top tile
  const h=((x*6131)^(y*4919))&0xFFFF;
  const pal = MAT_PALETTE_2D[matId] || MAT_PALETTE_2D.pedra_normal;
  const [BR, BG, BB] = pal.base;
  const cmix=(dr,dg,db,a)=>`rgba(${Math.max(0,Math.min(255,BR+dr))},${Math.max(0,Math.min(255,BG+dg))},${Math.max(0,Math.min(255,BB+db))},${a})`;

  if(pal.accent==='duneWall'){
    const grad=ctx.createLinearGradient(0,faceY,0,faceY+faceH);
    grad.addColorStop(0,'#d0a15a'); grad.addColorStop(.35,'#a87132'); grad.addColorStop(1,'rgba(55,29,12,0)');
    ctx.fillStyle=grad; ctx.beginPath(); ctx.moveTo(X+1,faceY+faceH);
    for(let i=0;i<=8;i++){
      const px=X+1+(CELL-2)*i/8;
      const py=faceY+faceH*.08+(((h>>(i%13))&7)-3);
      i ? ctx.lineTo(px,py) : ctx.lineTo(px,py);
    }
    ctx.lineTo(X+CELL-1,faceY+faceH); ctx.closePath(); ctx.fill();
    ctx.strokeStyle='rgba(255,222,145,.48)'; ctx.lineWidth=1.3;
    for(let row=0;row<3;row++){
      const yy=faceY+7+row*8; ctx.beginPath();
      ctx.moveTo(X+3,yy); ctx.bezierCurveTo(X+CELL*.32,yy-3,X+CELL*.68,yy+3,X+CELL-3,yy-1); ctx.stroke();
    }
    return;
  }

  if(pal.accent==='frozenCave'){
    const grad=ctx.createLinearGradient(0,faceY,0,faceY+faceH);
    grad.addColorStop(0,'#82d3e1'); grad.addColorStop(.30,'#3b829d');
    grad.addColorStop(.72,'#1c4b65'); grad.addColorStop(1,'rgba(12,31,48,0)');
    ctx.fillStyle=grad; ctx.fillRect(X+1,faceY,CELL-2,faceH);
    const rWall=(seed,n)=>(((seed*1664525+n*1013904223)>>>0)%1000)/1000;
    ctx.strokeStyle='rgba(6,33,51,.68)'; ctx.lineWidth=1.5;
    for(let i=0;i<4;i++){
      const px=X+CELL*(.12+rWall(h,i)), py=faceY+faceH*(.12+i*.18);
      ctx.beginPath(); ctx.moveTo(px,py); ctx.lineTo(px+CELL*(.12-rWall(h,i+4)*.20),py+faceH*.16); ctx.lineTo(px+CELL*(rWall(h,i+8)*.18-.06),py+faceH*.29); ctx.stroke();
    }
    ctx.fillStyle='rgba(220,252,255,.42)'; ctx.fillRect(X+2,faceY,CELL-4,2);
    return;
  }

  if(pal.accent==='snowDune'){
    const grad=ctx.createLinearGradient(0,faceY,0,faceY+faceH);
    grad.addColorStop(0,'#f6fdff'); grad.addColorStop(.35,'#c7e7f0');
    grad.addColorStop(.78,'#76aec4'); grad.addColorStop(1,'rgba(38,76,98,0)');
    ctx.fillStyle=grad; ctx.beginPath(); ctx.moveTo(X+1,faceY+faceH);
    for(let i=0;i<=8;i++){
      const px=X+1+(CELL-2)*i/8;
      const py=faceY+faceH*(.10+.14*Math.sin(i*.85))+(((h>>(i%13))&7)-3);
      ctx.lineTo(px,py);
    }
    ctx.lineTo(X+CELL-1,faceY+faceH); ctx.closePath(); ctx.fill();
    ctx.strokeStyle='rgba(255,255,255,.78)'; ctx.lineWidth=1.4;
    for(let row=0;row<3;row++){
      const yy=faceY+7+row*8; ctx.beginPath(); ctx.moveTo(X+3,yy);
      ctx.bezierCurveTo(X+CELL*.32,yy-3,X+CELL*.68,yy+3,X+CELL-3,yy-1); ctx.stroke();
    }
    return;
  }

  // Cabana: tábuas horizontais, juntas profundas e veios irregulares.
  if(pal.accent==='woodWall'){
    const plankH=Math.max(5, Math.floor(faceH/3));
    for(let py=0;py<faceH;py+=plankH){
      const shade=((h>>(py%11))&15)-7;
      const grad=ctx.createLinearGradient(X,faceY+py,X+CELL,faceY+py+plankH);
      grad.addColorStop(0,cmix(30+shade,16+shade,3,1)); grad.addColorStop(.5,cmix(shade,shade/2,-5,1)); grad.addColorStop(1,cmix(-25+shade,-18,-14,1));
      ctx.fillStyle=grad; ctx.fillRect(X+1,faceY+py,CELL-2,Math.min(plankH-1,faceH-py));
      ctx.strokeStyle='rgba(30,12,3,.72)';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(X+1,faceY+py+plankH-1);ctx.lineTo(X+CELL-1,faceY+py+plankH-1);ctx.stroke();
      ctx.strokeStyle='rgba(245,190,104,.16)';ctx.lineWidth=.7;
      for(let k=0;k<2;k++){const gy=faceY+py+2+((h>>(k*5))%Math.max(1,plankH-4));ctx.beginPath();ctx.moveTo(X+3,gy);ctx.bezierCurveTo(X+CELL*.35,gy-2,X+CELL*.68,gy+2,X+CELL-3,gy-1);ctx.stroke();}
    }
    ctx.fillStyle='rgba(255,220,150,.25)';ctx.fillRect(X+1,faceY,CELL-2,1); return;
  }

  // ── Base fill: stone wall FRONT FACE — medium gray castle stone, lit from above
  const wfG=ctx.createLinearGradient(0,faceY,0,faceY+faceH);
  wfG.addColorStop(0,    cmix(28, 26, 18, 0.99));  // top — lit face
  wfG.addColorStop(0.30, cmix(-6, -8, -14, 0.99)); // mid
  wfG.addColorStop(0.68, cmix(-50, -52, -54, 0.97)); // lower — shadow
  wfG.addColorStop(1,   'rgba(8,6,4,0)');
  ctx.fillStyle=wfG;
  ctx.fillRect(X+1,faceY,CELL-2,faceH);

  // ── Stone courses — horizontal mortar lines
  const courseH=Math.round(faceH*0.52);
  ctx.strokeStyle='rgba(0,0,0,0.55)'; ctx.lineWidth=1.8;
  if(courseH>4 && courseH<faceH-2){
    ctx.beginPath(); ctx.moveTo(X+1,faceY+courseH); ctx.lineTo(X+CELL-1,faceY+courseH); ctx.stroke();
  }
  // Light edge above mortar line (stone top edge)
  ctx.strokeStyle='rgba(180,172,158,0.55)'; ctx.lineWidth=0.8;
  if(courseH>4 && courseH<faceH-2){
    ctx.beginPath(); ctx.moveTo(X+2,faceY+courseH-1); ctx.lineTo(X+CELL-2,faceY+courseH-1); ctx.stroke();
  }

  // ── Vertical joints — alternating brick offset
  const q1=Math.round(CELL*0.27), q2=Math.round(CELL*0.73);
  ctx.strokeStyle='rgba(0,0,0,0.50)'; ctx.lineWidth=1.5;
  for(let row=0; row*courseH<faceH; row++){
    const jx=X+((row%2===0)?q1:q2);
    const jy=faceY+row*courseH;
    if(jx>X+4 && jx<X+CELL-4){
      ctx.beginPath();
      ctx.moveTo(jx, jy+2);
      ctx.lineTo(jx, Math.min(jy+courseH-2, faceY+faceH-4));
      ctx.stroke();
    }
  }

  // ── Top edge highlight — bright seam wall top → front face
  ctx.fillStyle='rgba(195,188,175,0.88)';
  ctx.fillRect(X+1,faceY,CELL-2,2);

  // ── Side-edge shadow (gives face an inset/depth look)
  const sL=ctx.createLinearGradient(X,0,X+9,0);
  sL.addColorStop(0,'rgba(0,0,0,0.55)'); sL.addColorStop(1,'rgba(0,0,0,0)');
  ctx.fillStyle=sL; ctx.fillRect(X+1,faceY,9,faceH);
  const sR=ctx.createLinearGradient(X+CELL-9,0,X+CELL,0);
  sR.addColorStop(0,'rgba(0,0,0,0)'); sR.addColorStop(1,'rgba(0,0,0,0.55)');
  ctx.fillStyle=sR; ctx.fillRect(X+CELL-9,faceY,8,faceH);

  // ── Subtle torch-glow tint on upper face (warm orange)
  const tG=ctx.createLinearGradient(0,faceY,0,faceY+faceH*0.4);
  tG.addColorStop(0,'rgba(255,140,30,0.08)');
  tG.addColorStop(1,'rgba(255,100,0,0)');
  ctx.fillStyle=tG; ctx.fillRect(X+1,faceY,CELL-2,faceH*0.4);
}

// ── DIABLO WALL TOP — dark menacing stone block viewed from above
function drawWallTop3D(ctx, x, y, matId){
  const X=x*CELL, Y=y*CELL;
  const h=((x*6271)^(y*2749)^(y<<4))&0xFFFF;
  const v=(h%18)-9;
  const pal = MAT_PALETTE_2D[matId] || MAT_PALETTE_2D.pedra_normal;
  const [BR, BG, BB] = pal.base;
  // Estilos próprios: caverna (pedra irregular) e enegrecida (tijolo preto).
  if(pal.accent==='duneWall'){ paintDuneWallTop(ctx, X, Y, CELL, _rng((x*47^y*31^17)>>>0)); return; }
  if(pal.accent==='frozenCave'){ paintFrozenCaveWall(ctx, X, Y, CELL, _rng((x*53^y*37^19)>>>0)); return; }
  if(pal.accent==='snowDune'){ paintSnowDuneWall(ctx, X, Y, CELL, _rng((x*67^y*41^23)>>>0)); return; }
  if(pal.accent==='rockWall'){ paintRock(ctx, X, Y, CELL, _rng((x*59^y*43^29)>>>0)); return; }
  if(pal.accent==='brownRockWall'){ paintRock(ctx, X, Y, CELL, _rng((x*61^y*47^31)>>>0), true); return; }
  if(pal.accent==='cave'){ paintCave(ctx, X, Y, CELL, _rng((x*41^y*23^9)>>>0)); return; }
  if(pal.accent==='blackbrick'){ paintBrick(ctx, X, Y, CELL, _rng((x*7^y*13)>>>0), [22,21,26], '#070709'); return; }
  if(pal.accent==='woodWall'){
    ctx.fillStyle='#3a1d0c'; ctx.fillRect(X,Y,CELL,CELL);
    const rows=4, ph=CELL/rows;
    for(let row=0;row<rows;row++){
      const yy=Y+row*ph, tone=((h>>(row*3))&15)-7;
      ctx.fillStyle=`rgb(${124+tone},${72+tone},${32+Math.floor(tone/2)})`;ctx.fillRect(X+2,yy+1,CELL-4,ph-2);
      ctx.strokeStyle='rgba(34,13,4,.78)';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(X+1,yy+ph-1);ctx.lineTo(X+CELL-1,yy+ph-1);ctx.stroke();
      ctx.strokeStyle='rgba(244,183,91,.18)';ctx.lineWidth=.8;ctx.beginPath();ctx.moveTo(X+4,yy+ph*.4);ctx.bezierCurveTo(X+CELL*.38,yy+ph*.2,X+CELL*.65,yy+ph*.72,X+CELL-4,yy+ph*.42);ctx.stroke();
    }
    ctx.strokeStyle='rgba(0,0,0,.6)';ctx.lineWidth=2;ctx.strokeRect(X+1,Y+1,CELL-2,CELL-2);return;
  }

  // Deep mortar — dark gray with faint blue tinge (grout between stones)
  ctx.fillStyle='#1a1c22';
  ctx.fillRect(X,Y,CELL,CELL);

  // Stone face — MEDIUM GRAY with cool blue tint (classic castle/dungeon stone wall)
  const r0=Math.min(255,BR+v), g0=Math.min(255,BG+v), b0=Math.min(255,BB+Math.floor(v*0.5));
  const wg=ctx.createLinearGradient(X,Y,X+CELL,Y+CELL);
  wg.addColorStop(0,  `rgb(${Math.min(255,r0+28)},${Math.min(255,g0+26)},${Math.min(255,b0+28)})`);
  wg.addColorStop(0.5,`rgb(${r0},${g0},${b0})`);
  wg.addColorStop(1,  `rgb(${Math.max(0,r0-30)},${Math.max(0,g0-28)},${Math.max(0,b0-26)})`);
  ctx.fillStyle=wg; ctx.fillRect(X+1,Y+1,CELL-2,CELL-2);

  // Mortar joints — brick offset pattern
  ctx.strokeStyle='rgba(0,0,0,0.62)'; ctx.lineWidth=1.8;
  const hOff=(y%2===0)?0:Math.floor(CELL/2);
  const vx=X+hOff;
  if(vx>X+3&&vx<X+CELL-3){ ctx.beginPath(); ctx.moveTo(vx,Y+2); ctx.lineTo(vx,Y+CELL-2); ctx.stroke(); }
  ctx.beginPath(); ctx.moveTo(X+2,Y+Math.floor(CELL/2)); ctx.lineTo(X+CELL-2,Y+Math.floor(CELL/2)); ctx.stroke();

  // Outer border — medium-dark seam between stones
  ctx.strokeStyle='rgba(0,0,0,0.70)'; ctx.lineWidth=2;
  ctx.strokeRect(X+1,Y+1,CELL-2,CELL-2);

  // Top-left subtle light edge (ambient vault lighting from above)
  ctx.fillStyle='rgba(255,255,255,0.10)';
  ctx.fillRect(X+1,Y+1,CELL-2,3);
  ctx.fillRect(X+1,Y+1,3,CELL-2);
  // Faint torch-warm tint
  ctx.fillStyle='rgba(255,170,50,0.05)';
  ctx.fillRect(X+1,Y+1,CELL-2,4);
  ctx.fillRect(X+1,Y+1,4,CELL-2);

  // Moisture/lichen dark patch
  if((h%7)===0){
    ctx.fillStyle='rgba(10,18,6,0.28)';
    const pw=Math.max(1,CELL-18)|0;
    ctx.fillRect(X+6+(h%pw), Y+6+((h>>3)%pw), 14+(h%10), 9+(h%7));
  }
  // Mineral vein (cold gray-white streak)
  if((h%11)===4){
    ctx.strokeStyle='rgba(190,195,210,0.16)'; ctx.lineWidth=1;
    ctx.beginPath();
    ctx.moveTo(X+5+(h%Math.max(1,CELL/2)|0), Y+4+(h%Math.max(1,CELL-14)|0));
    ctx.lineTo(X+CELL-5-(h%Math.max(1,CELL/3)|0), Y+CELL-4-(h%Math.max(1,CELL-20)|0));
    ctx.stroke();
  }
  // Crack
  if((h%9)===2){
    ctx.strokeStyle='rgba(0,0,0,0.36)'; ctx.lineWidth=0.8;
    ctx.beginPath();
    ctx.moveTo(X+4, Y+CELL/2+(h%10)-5);
    ctx.lineTo(X+CELL-4, Y+CELL/2-(h%7)+3);
    ctx.stroke();
  }
  // Rare iron ring/torch bracket hint
  if((h%17)===5){
    ctx.fillStyle='rgba(80,72,60,0.35)';
    ctx.beginPath(); ctx.arc(X+CELL/2,Y+CELL/2,5+(h%4),0,Math.PI*2); ctx.fill();
    ctx.strokeStyle='rgba(110,100,80,0.25)'; ctx.lineWidth=1;
    ctx.beginPath(); ctx.arc(X+CELL/2,Y+CELL/2,5+(h%4),0,Math.PI*2); ctx.stroke();
  }
  // Parede desmoronada: juntas extras quebradas sobre o bloco
  if(pal.accent==='wallRubble'){
    ctx.strokeStyle='rgba(0,0,0,0.45)'; ctx.lineWidth=1;
    for(let k=0;k<3;k++){
      const rx=X+4+((h>>(k*3))%Math.max(1,CELL-8)), ry=Y+4+((h>>(k*2))%Math.max(1,CELL-8));
      ctx.beginPath(); ctx.moveTo(rx,ry); ctx.lineTo(rx+5+(h%5), ry+3+(h%4)); ctx.stroke();
    }
  }
}

// ── MINIATURE BASE — black round base like real tabletop miniatures
function drawMiniBase(ctx, cx, cy, color, active, footprintW=1, footprintH=1){
  const fw = Math.max(1, Number(footprintW) || 1);
  const fh = Math.max(1, Number(footprintH) || 1);
  const by=cy+CELL*0.30*fh;
  const rx=CELL*0.42*fw, ry=CELL*0.145*fh;

  // Cast shadow on floor
  ctx.fillStyle='rgba(0,0,0,0.72)';
  ctx.beginPath(); ctx.ellipse(cx+3,by+4,rx*1.08,ry*1.1,0,0,Math.PI*2); ctx.fill();

  // Coloured outer rim — class colour (gold when active/current turn)
  const rimCol = active ? '#f0c020' : color;
  ctx.fillStyle = rimCol;
  ctx.beginPath(); ctx.ellipse(cx,by,rx+3,ry+1.4,0,0,Math.PI*2); ctx.fill();

  // Main base body — black with painted-miniature look (dark brown texture)
  const bg=ctx.createLinearGradient(cx-rx,by-ry*1.2,cx+rx*0.4,by+ry*2);
  bg.addColorStop(0,'#2e2820');
  bg.addColorStop(0.30,'#181410');
  bg.addColorStop(0.65,'#0e0c0a');
  bg.addColorStop(1,'#06050403');
  ctx.fillStyle=bg;
  ctx.beginPath(); ctx.ellipse(cx,by,rx,ry,0,0,Math.PI*2); ctx.fill();

  // Highlight arc — painted edge gloss (top-left)
  const hl=ctx.createLinearGradient(cx-rx,by-ry,cx,by);
  hl.addColorStop(0,'rgba(120,105,85,0.65)');
  hl.addColorStop(0.55,'rgba(70,60,48,0.25)');
  hl.addColorStop(1,'rgba(0,0,0,0)');
  ctx.fillStyle=hl;
  ctx.beginPath(); ctx.ellipse(cx-rx*0.1,by-ry*0.12,rx*0.82,ry*0.5,0,0,Math.PI); ctx.fill();

  // Specular arc (top)
  ctx.strokeStyle=active?'rgba(255,240,120,0.75)':'rgba(90,80,65,0.60)';
  ctx.lineWidth=1.8;
  ctx.beginPath(); ctx.ellipse(cx,by-ry*0.18,rx*0.68,ry*0.38,0,Math.PI*1.10,Math.PI*1.90); ctx.stroke();
}

// ══ 3D DICE ANIMATION SYSTEM — Resin Collectible RPG Dice ════════════════════
// MeshStandardMaterial: roughness 0.85, opaque matte plastic — vivid solid colors.
// Each face has a 256×256 CanvasTexture: solid color bg, white Arial Black number, black chamfer.
// Same CanvasTexture used as map + bumpMap (bumpScale 0.8) for tactile number relief.
// SpotLight from above ensures vivid hues stay bright regardless of dungeon ambience.

// Matte plastic die colors — body color per die type (user spec)
// Die colors and text settings come from VC (src/visualConfig.js)
const DIE_COLORS = VC.dice.colors;
const DIE_COLOR_VARIANTS = VC.dice.colorVariants || {};
const DIE_DAMAGE_COLOR_VARIANTS = VC.dice.damageTypeVariants || {};
const DIE_THEME_COLOR_VARIANTS = VC.dice.themeVariants || {};
// Cores reservadas para rolagens com atraso de entrada. Sem isso, dois dados
// disparados no mesmo frame escolheriam a mesma cor antes de aparecerem.
const _pendingDiceColors = new Set();

let _d3      = null;   // dice state (animFrame + cfr counter only — no separate scene)
const _dice3 = [];    // active die objects

/**
 * Bottom-right corner of the visible board near the active hero.
 * In the SW-225° isometric view, "bottom-right" = +X, +Z direction.
 * Falls back to board centre when game state is unavailable.
 */

// ══ DICE AUDIO — Web Audio API ═══════════════════════════════════════════════

let audioCtx = null;

// Unlock / create AudioContext — called on every user gesture so it stays
// running even if the browser suspended it after a tab-switch.
function _unlockAudio(){
  try{
    if(!audioCtx)
      audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    if(audioCtx.state === 'suspended') audioCtx.resume();
  } catch(e){}
}

// Register on every common gesture type (not just first click)
['click','keydown','pointerdown','touchstart'].forEach(ev =>
  document.addEventListener(ev, _unlockAudio, { passive:true })
);

function getAudioContext(){
  _unlockAudio();
  return audioCtx;
}

// Two layers: high-freq transient crack + low thud — sounds like real dice.
function playImpact(intensity){
  if(intensity === undefined) intensity = 1.0;
  const ctx = getAudioContext();
  if(!ctx || ctx.state !== 'running') return;
  try{
    const now = ctx.currentTime;
    const SR  = ctx.sampleRate;

    // Layer 1 — sharp transient crack (high-pass noise)
    const crackLen = Math.floor(SR * 0.055);
    const crackBuf = ctx.createBuffer(1, crackLen, SR);
    const cd = crackBuf.getChannelData(0);
    for(let i = 0; i < crackLen; i++){
      const t = i / crackLen;
      cd[i] = (Math.random()*2-1) * Math.exp(-t * 45) * intensity;
    }
    const crackSrc = ctx.createBufferSource();
    crackSrc.buffer = crackBuf;
    const hpf = ctx.createBiquadFilter();
    hpf.type = 'highpass'; hpf.frequency.value = 2200;
    const crackGain = ctx.createGain();
    crackGain.gain.value = 1.1;
    crackSrc.connect(hpf); hpf.connect(crackGain); crackGain.connect(_diceBus());
    crackSrc.start(now);

    // Layer 2 — low body thud (pitched sine)
    const thudOsc  = ctx.createOscillator();
    const thudGain = ctx.createGain();
    thudOsc.type = 'sine';
    thudOsc.frequency.setValueAtTime(160 * intensity, now);
    thudOsc.frequency.exponentialRampToValueAtTime(55, now + 0.07);
    thudGain.gain.setValueAtTime(0.40 * intensity, now);
    thudGain.gain.exponentialRampToValueAtTime(0.001, now + 0.09);
    thudOsc.connect(thudGain); thudGain.connect(_diceBus());
    thudOsc.start(now); thudOsc.stop(now + 0.09);
  } catch(e){}
}

// ── Roll sequence: rapid impacts that slow down (0 → 700 ms) ─────────────────
function playRollSound(){
  const ctx = getAudioContext();
  if(!ctx) return;
  // Staggered impacts — first few overlap for the initial scatter
  const times = [0, 80, 160, 255, 350, 440, 520, 590, 645, 690];
  times.forEach((ms, i) => {
    const intensity = 1.0 - (i / times.length) * 0.82;
    setTimeout(() => playImpact(intensity), ms);
  });
}

// ── Settle: satisfying "clunk" as die snaps to face ──────────────────────────
function playSettle(){
  const ctx = getAudioContext();
  if(!ctx || ctx.state !== 'running') return;
  try{
    const now = ctx.currentTime;
    const osc  = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(340, now);
    osc.frequency.exponentialRampToValueAtTime(110, now + 0.16);
    gain.gain.setValueAtTime(0.35, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.20);
    osc.connect(gain); gain.connect(_diceBus());
    osc.start(now); osc.stop(now + 0.20);
  } catch(e){}
}

// ══ DAMAGE / HEAL AUDIO — anuncia quando uma criatura perde ou ganha HP ═══════
// Som sintetizado (sem assets), roteado pelo _sfxBus() para respeitar o volume.

// MEU herói tomou dano — sting descendente de dois tons, mais alarmante.
function playHeroHurt(){
  const ctx = getAudioContext();
  if(!ctx || ctx.state !== 'running') return;
  try{
    const now = ctx.currentTime;
    const osc  = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(520, now);
    osc.frequency.exponentialRampToValueAtTime(180, now + 0.18);
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.exponentialRampToValueAtTime(0.85, now + 0.012);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.30);
    const lpf = ctx.createBiquadFilter();
    lpf.type = 'lowpass'; lpf.frequency.value = 1400;
    osc.connect(lpf); lpf.connect(gain); gain.connect(_sfxBus());
    osc.start(now); osc.stop(now + 0.28);
  } catch(e){}
}

// Outra criatura tomou dano — "thud" grave e suave, mais discreto.
function playCreatureHit(){
  const ctx = getAudioContext();
  if(!ctx || ctx.state !== 'running') return;
  try{
    const now = ctx.currentTime;
    const osc  = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(190, now);
    osc.frequency.exponentialRampToValueAtTime(70, now + 0.10);
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.exponentialRampToValueAtTime(0.50, now + 0.008);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.16);
    osc.connect(gain); gain.connect(_sfxBus());
    osc.start(now); osc.stop(now + 0.17);
  } catch(e){}
}

// Qualquer criatura curou HP — chime ascendente e suave.
function playHeal(){
  const ctx = getAudioContext();
  if(!ctx || ctx.state !== 'running') return;
  try{
    const now = ctx.currentTime;
    [523.25, 783.99].forEach((freq, i) => {  // C5 → G5
      const osc  = ctx.createOscillator();
      const gain = ctx.createGain();
      const t = now + i * 0.07;
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(freq, t);
      gain.gain.setValueAtTime(0.0001, t);
      gain.gain.exponentialRampToValueAtTime(0.45, t + 0.02);
      gain.gain.exponentialRampToValueAtTime(0.0001, t + 0.34);
      osc.connect(gain); gain.connect(_sfxBus());
      osc.start(t); osc.stop(t + 0.36);
    });
  } catch(e){}
}

// Sons de encerramento: mantêm a mesma identidade WebAudio do dano, mas cada
// resultado tem uma assinatura própria. O áudio da derrota do grupo continua
// sendo o arquivo assets/music/derrota.mp3; este pulso apenas o anuncia.
function _playDefeatSound(kind='common'){
  const ctx = getAudioContext(); if(!ctx || ctx.state !== 'running') return;
  try{
    const now = ctx.currentTime, bus = _sfxBus();
    const notes = kind === 'boss' ? [196, 147, 98] : kind === 'explosion' ? [92, 58] : kind === 'magic' ? [660, 440] : [220, 132];
    const strength = kind === 'boss' ? 1.45 : kind === 'explosion' ? 1.18 : 1;
    notes.forEach((freq, i) => {
      const osc = ctx.createOscillator(), gain = ctx.createGain();
      osc.type = kind === 'explosion' ? 'sawtooth' : kind === 'magic' ? 'sine' : 'triangle';
      const t = now + i * (kind === 'boss' ? .13 : .08);
      osc.frequency.setValueAtTime(freq, t);
      osc.frequency.exponentialRampToValueAtTime(Math.max(35, freq * .55), t + .34);
      gain.gain.setValueAtTime(.001, t); gain.gain.exponentialRampToValueAtTime((kind === 'boss' ? .16 : .10) * strength, t + .018);
      gain.gain.exponentialRampToValueAtTime(.001, t + .40);
      osc.connect(gain); gain.connect(bus); osc.start(t); osc.stop(t + .43);
    });
  }catch(e){}
}

function _playGroupDefeatSound(){
  const ctx = getAudioContext(); if(!ctx || ctx.state !== 'running') return;
  try{
    const now = ctx.currentTime, bus = _sfxBus(), osc = ctx.createOscillator(), gain = ctx.createGain();
    osc.type = 'sawtooth'; osc.frequency.setValueAtTime(180, now); osc.frequency.exponentialRampToValueAtTime(38, now + 1.05);
    gain.gain.setValueAtTime(.001, now); gain.gain.exponentialRampToValueAtTime(.38, now + .035); gain.gain.exponentialRampToValueAtTime(.001, now + 1.15);
    osc.connect(gain); gain.connect(bus); osc.start(now); osc.stop(now + 1.18);
  }catch(e){}
}

// ── Cues curtos de combate ─────────────────────────────────────────────────
// Todos os sinais rápidos passam por um limitador de repetição. Isso evita que
// ataques em área e efeitos por rodada virem uma parede sonora, sem esconder
// o primeiro impacto de cada evento.
const _combatCueLast = new Map();
function _playCombatCue(kind, opts={}){
  const ctx = getAudioContext();
  if(!ctx || ctx.state !== 'running') return;
  const damageType = _combatDamageTypeInfo(opts.damageType || '').key;
  const repeatKey = String(opts.repeatKey || `${kind}:${damageType || ''}`);
  const nowPerf = performance.now();
  const minGap = Number(opts.minGap ?? (kind === 'damage' ? 130 : 70));
  const last = _combatCueLast.get(repeatKey) || -Infinity;
  if(nowPerf - last < minGap) return;
  _combatCueLast.set(repeatKey, nowPerf);
  try{
    const now = ctx.currentTime, bus = _sfxBus();
    if(!bus) return;
    const profile = {
      attack:      {wave:'triangle', f1:180, f2:92,  dur:.14, gain:.075},
      error:       {wave:'sawtooth',f1:300, f2:72,  dur:.24, gain:.10},
      critical:    {wave:'triangle', f1:180, f2:920, dur:.34, gain:.18},
      resistance:  {wave:'sine',    f1:720, f2:1080,dur:.25, gain:.11},
      physical:    {wave:'sine',    f1:190, f2:70,  dur:.16, gain:.065},
      fire:        {wave:'sawtooth',f1:155, f2:58,  dur:.25, gain:.09},
      cold:        {wave:'triangle',f1:1040,f2:420, dur:.28, gain:.075},
      lightning:   {wave:'square',  f1:1240,f2:180, dur:.13, gain:.095},
      acid:        {wave:'sawtooth',f1:430, f2:90,  dur:.31, gain:.07},
      poison:      {wave:'square',  f1:280, f2:110, dur:.28, gain:.065},
      holy:        {wave:'sine',    f1:620, f2:980, dur:.34, gain:.10},
      magic:       {wave:'sine',    f1:460, f2:860, dur:.36, gain:.075},
      water:       {wave:'sine',    f1:380, f2:170, dur:.23, gain:.055},
    };
    const key = kind === 'damage' ? (damageType || 'physical') : kind;
    const p = profile[key] || profile.magic;
    const power = Number(opts.power || 1);
    const volume = Math.max(0, Number(opts.volume ?? 1));
    const osc = ctx.createOscillator(), gain = ctx.createGain();
    osc.type = p.wave;
    osc.frequency.setValueAtTime(Math.max(20, p.f1), now);
    if(p.f2 > p.f1) osc.frequency.exponentialRampToValueAtTime(p.f2, now + p.dur * .72);
    else osc.frequency.exponentialRampToValueAtTime(Math.max(20, p.f2), now + p.dur);
    gain.gain.setValueAtTime(.0001, now);
    gain.gain.exponentialRampToValueAtTime(Math.min(.34, p.gain * power * volume), now + .012);
    gain.gain.exponentialRampToValueAtTime(.0001, now + p.dur);
    osc.connect(gain); gain.connect(bus); osc.start(now); osc.stop(now + p.dur + .03);
    if(kind === 'critical' || key === 'lightning'){
      const o2 = ctx.createOscillator(), g2 = ctx.createGain(), t = now + .055;
      o2.type = 'sine'; o2.frequency.setValueAtTime(key === 'lightning' ? 1580 : 740, t);
      o2.frequency.exponentialRampToValueAtTime(key === 'lightning' ? 420 : 360, t + .16);
      g2.gain.setValueAtTime(.0001, t);
      g2.gain.exponentialRampToValueAtTime(Math.min(.20, p.gain * power * volume * .72), t + .008);
      g2.gain.exponentialRampToValueAtTime(.0001, t + .19);
      o2.connect(g2); g2.connect(bus); o2.start(t); o2.stop(t + .21);
    }
  }catch(e){}
}

function _spellHasDedicatedSound(id){
  return new Set([
    'relampago','bola_fogo','raio_congelante','raio_divino','jato_ar',
    'sopro_dragao','cuspe_acido','dominar_mente','sono','silencio','medo',
    'barreira','maldicao','invisibilidade','protecao_energia','manto_escuridao',
    'clarividencia','regeneracao','velocidade','lentidao','abencoar','abencoar_arma',
    'senhor_das_aguas','chamado_inverno','olhar_petrificante','conjurar_elemental','voo','criar_alimentos','cura','cura_area','purificacao','ressurreicao','metamorfose','guerreiro_luz','cancao_heroica','saciar','contramagica',
    'ira_rocha_ardente','prisao_chamas',
    'requiem_final',
  ]).has(String(id || '').toLowerCase());
}

function _playGenericSpellCue(msg){
  if(!msg || msg.phase !== 'start' || _spellHasDedicatedSound(msg.spell_id)) return;
  _playCombatCue('magic', {repeatKey:`spell:${msg.spell_id || 'magic'}`, volume:.78});
}

// ── Feedback visual de combate ─────────────────────────────────────────────
// O servidor continua sendo a fonte do dano. O cliente apenas anima a
// diferença entre dois game_states, o que mantém o efeito sincronizado para
// todos os jogadores sem criar uma segunda resolução de combate.
const _combatFeedbacks = [];
const _resistanceFeedbacks = [];
const _conditionPulses = [];
const _attackFeedbacks = [];
const _combatHpVisual = new Map();
let _combatFeedbackRaf = null;
let _resistanceFeedbackRaf = null;
let _attackFeedbackRaf = null;
let _combatVisualUntil = 0;
const COMBAT_FEEDBACK_DAMAGE_MS = VC.feedback?.combat?.damageMs ?? 1050;
const COMBAT_FEEDBACK_DEATH_MS = VC.feedback?.combat?.deathMs ?? 1500;
const COMBAT_FEEDBACK_DAMAGE_FONT_SCALE = VC.feedback?.combat?.damageFontScale ?? 1.5;
const ATTACK_FEEDBACK_PREP_MS = 240;
const ATTACK_FEEDBACK_RESULT_MS = 980;
const RESISTANCE_FEEDBACK_MS = VC.feedback?.combat?.resistance?.durationMs ?? 1450;
const SPIN_ATTACK_MS = 520;
const SPIN_ATTACK_GAP_MS = 105;
const _spinAttackAnims = [];
let _spinAttackRaf = null;
const HOLY_STRIKE_DURATION_MS = 420;
// O prenúncio do raio começa cedo; seu feixe atinge o alvo no meio do arco.
const HOLY_LEVEL3_RAY_DELAY_MS = HOLY_STRIKE_DURATION_MS * .2;
const HOLY_LEVEL3_RAY_TRAVEL_MS = HOLY_STRIKE_DURATION_MS * .3;

function _spinAttackColor(abilityId){
  return String(abilityId || '') === 'tecnica_redemoinho_morte' ? '#d64b70' : '#6fc7ff';
}

function _spinAttackProgress(anim, now){
  const p = Math.max(0, Math.min(1, (now - anim.start) / Math.max(1, anim.duration)));
  // Entrada rápida, giro constante no centro e desaceleração curta no fim.
  const u = Math.max(0, Math.min(1, (p - .14) / .70));
  const smooth = u * u * (3 - 2 * u);
  const eased = p < .14 ? (p / .14) * .08 : .08 + .92 * smooth;
  return {p, angle: Math.max(0, Math.min(1, eased)) * Math.PI * 2};
}

function _spinAttackEntityId(anim){
  return anim.attackerKey || `p:${anim.attackerId}`;
}

function _spinAttackAt(attackerKey, now){
  let chosen = null;
  for(const anim of _spinAttackAnims){
    if(_spinAttackEntityId(anim) !== attackerKey) continue;
    if(now < anim.start || now >= anim.end) continue;
    if(!chosen || anim.start > chosen.start) chosen = anim;
  }
  return chosen;
}

function _registrarGiroAtaque(msg, now){
  const spinId = String(msg.spin_id || `${msg.attack_id}:spin`);
  if(_spinAttackAnims.some(a => a.id === spinId)) return;
  const index = Math.max(1, Number(msg.spin_index) || 1);
  const count = Math.max(index, Number(msg.spin_count) || 1);
  const delay = (index - 1) * (SPIN_ATTACK_MS + SPIN_ATTACK_GAP_MS);
  const start = now + delay;
  const attackerKey = _entityKeyById(msg.attacker_id) || `p:${msg.attacker_id}`;
  _spinAttackAnims.push({
    id: spinId, attackerId: msg.attacker_id, attackerKey,
    attackerPos: Array.isArray(msg.attacker_pos) ? msg.attacker_pos.map(Number) : [0, 0],
    abilityId: msg.ability_id || 'tecnica_ataque_giratorio',
    index, count, start, duration: SPIN_ATTACK_MS, end: start + SPIN_ATTACK_MS,
    color: _spinAttackColor(msg.ability_id), group: null,
  });
  if(!_spinAttackRaf) _spinAttackRaf = _scheduleVisualFrame(_spinAttackTick);
}

function _spinAttackTick(now){
  _spinAttackRaf = null;
  for(let i = _spinAttackAnims.length - 1; i >= 0; i--){
    const anim = _spinAttackAnims[i];
    if(now >= anim.end){
      _spinAttackFxDispose3D(anim);
      _spinAttackAnims.splice(i, 1);
    }
  }
  if(!mode3D && GS.gameState) renderMap(GS.gameState);
  if(_spinAttackAnims.length) _spinAttackRaf = _scheduleVisualFrame(_spinAttackTick);
}

function _spinAttackFxDispose3D(anim){
  if(!anim?.group) return;
  if(anim.group.parent) anim.group.parent.remove(anim.group);
  anim.group.traverse(obj => {
    if(obj.geometry) obj.geometry.dispose();
    if(obj.material){
      const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
      mats.forEach(mat => mat.dispose());
    }
  });
  anim.group = null;
}

function _spinAttackFxBuild3D(anim){
  if(!g3 || !g3.scene || !window.THREE) return false;
  const T = window.THREE, group = new T.Group();
  group.name = anim.abilityId === 'tecnica_redemoinho_morte'
    ? 'redemoinho-da-morte-fx' : 'ataque-giratorio-fx';
  const color = new T.Color(anim.color);
  const mat = new T.MeshBasicMaterial({color, transparent:true, opacity:0,
    depthWrite:false, depthTest:false, blending:T.AdditiveBlending,
    side:T.DoubleSide});
  const ring = new T.Mesh(new T.TorusGeometry(.52, .025, 8, 40), mat);
  ring.rotation.x = Math.PI / 2; ring.position.y = .035; ring.renderOrder = 80;
  group.add(ring);
  const sweeps = [];
  for(let i = 0; i < 4; i++){
    const sweep = new T.Mesh(new T.BoxGeometry(.82, .018, .045), mat.clone());
    sweep.position.y = .07; sweep.rotation.y = i * Math.PI / 2 + Math.PI / 4;
    sweep.renderOrder = 81; group.add(sweep); sweeps.push(sweep);
  }
  if(anim.abilityId === 'tecnica_redemoinho_morte'){
    const aura = new T.Mesh(new T.TorusGeometry(.72, .018, 8, 40), mat.clone());
    aura.rotation.x = Math.PI / 2; aura.position.y = .09; aura.renderOrder = 79;
    group.add(aura); anim.aura = aura;
  }
  group.position.set(anim.attackerPos[0], 0, anim.attackerPos[1]);
  g3.scene.add(group);
  anim.group = group; anim.ring = ring; anim.sweeps = sweeps;
  return true;
}

function _spinAttackFxUpdate3D(anim, now){
  if(!g3 || !window.THREE) return;
  if(!anim.group || anim.group.parent !== g3.scene){
    _spinAttackFxDispose3D(anim);
    if(!_spinAttackFxBuild3D(anim)) return;
  }
  const q = _spinAttackProgress(anim, now), fade = Math.sin(Math.PI * q.p);
  const spin = q.angle;
  const live = (GS.gameState?.players || []).find(x => String(x.id) === String(anim.attackerId))
    || (GS.gameState?.monsters || []).find(x => String(x.id) === String(anim.attackerId));
  const pos = live?.pos || anim.attackerPos;
  anim.group.position.set(pos[0], 0, pos[1]);
  anim.group.rotation.y = spin * .35;
  anim.group.scale.setScalar(.72 + .38 * q.angle / (Math.PI * 2));
  anim.ring.rotation.z = spin;
  anim.ring.material.opacity = .80 * fade;
  anim.sweeps.forEach((sweep, i) => {
    sweep.rotation.y = i * Math.PI / 2 + Math.PI / 4 + spin * 1.15;
    sweep.scale.x = .60 + .70 * fade;
    sweep.material.opacity = (.42 + .35 * fade) * fade;
  });
  if(anim.aura){
    anim.aura.rotation.z = -spin * .72;
    anim.aura.scale.setScalar(1 + .20 * fade);
    anim.aura.material.opacity = .28 * fade;
  }
}

function _spinAttackFxUpdateAll3D(now){
  for(const anim of _spinAttackAnims){
    if(now < anim.start || now >= anim.end) continue;
    _spinAttackFxUpdate3D(anim, now);
  }
}

function _aplicarGiroAtaque3D(fig, now){
  const key = _figSceneKey(fig);
  if(!key) return;
  const anim = _spinAttackAt(key, now);
  if(!anim){
    if(fig.userData._spinAttackBaseRotationY != null){
      fig.rotation.y = fig.userData._spinAttackBaseRotationY;
      delete fig.userData._spinAttackBaseRotationY;
    }
    return;
  }
  if(fig.userData._spinAttackBaseRotationY == null)
    fig.userData._spinAttackBaseRotationY = fig.rotation.y || 0;
  fig.rotation.y = fig.userData._spinAttackBaseRotationY
    + _spinAttackProgress(anim, now).angle;
}

function _spinAttackAngle2D(playerId, now){
  const anim = _spinAttackAt(`p:${playerId}`, now);
  return anim ? _spinAttackProgress(anim, now).angle : 0;
}

function _drawSpinAttack2D(ctx, state, now){
  for(const anim of _spinAttackAnims){
    if(now < anim.start || now >= anim.end) continue;
    const p = state?.players?.find(x => String(x.id) === String(anim.attackerId));
    const pos = p?.pos || anim.attackerPos;
    if(!Array.isArray(pos)) continue;
    const q = _spinAttackProgress(anim, now), fade = Math.sin(Math.PI * q.p);
    const cx = (Number(pos[0]) + .5) * CELL, cy = (Number(pos[1]) + .5) * CELL;
    const col = anim.abilityId === 'tecnica_redemoinho_morte' ? [214,75,112] : [111,199,255];
    ctx.save(); ctx.translate(cx, cy); ctx.globalCompositeOperation = 'lighter';
    ctx.globalAlpha = fade;
    ctx.strokeStyle = `rgba(${col[0]},${col[1]},${col[2]},.78)`;
    ctx.lineWidth = Math.max(2, CELL * .035);
    ctx.beginPath(); ctx.arc(0, 0, CELL * (.34 + .13 * fade), q.angle * .8,
      q.angle * .8 + Math.PI * 1.45); ctx.stroke();
    ctx.strokeStyle = `rgba(${col[0]},${col[1]},${col[2]},.45)`;
    ctx.lineWidth = Math.max(1.5, CELL * .022);
    for(let i = 0; i < 4; i++){
      const a = i * Math.PI / 2 + Math.PI / 4 + q.angle;
      ctx.beginPath(); ctx.moveTo(Math.cos(a) * CELL * .18, Math.sin(a) * CELL * .18);
      ctx.lineTo(Math.cos(a) * CELL * (.66 + .16 * fade), Math.sin(a) * CELL * (.66 + .16 * fade));
      ctx.stroke();
    }
    if(anim.abilityId === 'tecnica_redemoinho_morte'){
      ctx.strokeStyle = `rgba(214,75,112,.34)`;
      ctx.beginPath(); ctx.arc(0, 0, CELL * (.58 + .10 * fade), -q.angle, -q.angle + Math.PI * 1.2); ctx.stroke();
    }
    ctx.restore();
  }
}

function _resistanceInfo(type){
  const key = String(type || '').toLowerCase();
  const table = VC.feedback?.combat?.resistance || {};
  return table[key] || {color:'#d9c7ff', icon:'🛡', label:key.toUpperCase() || t('ui.hud.resistencia')};
}

function _resistanceFeedbackVisible(f, state){
  if(!state || GS.isMaster() || state.test_mode) return true;
  const explored = new Set([...(state.explored||[]), ...(state.revealed||[])].map(([x,y])=>`${x},${y}`));
  return explored.has(`${f.pos[0]},${f.pos[1]}`);
}

function _resistanceOutcomeText(e){
  if(e.immune) return t('ui.hud.imune');
  if(e.poison && e.passed) return t('ui.hud.resistiu_ao_veneno');
  if(e.mitigation === 'half_damage') return e.passed
    ? t('ui.hud.passou_metade_do_dano') : t('ui.hud.falhou_efeito_completo');
  return e.passed ? t('ui.hud.passou') : t('ui.hud.falhou');
}

function _consumeResistanceEvents(state){
  for(const e of (state?.resistance_events || [])){
    if(!Array.isArray(e.pos)) continue;
    _playCombatCue('resistance', {repeatKey:'resistance', volume:.9});
    const info = _resistanceInfo(e.save_type);
    const f = {
      pos: [Number(e.pos[0]), Number(e.pos[1])],
      name: String(e.target_name || t('ui.hud.alvo')),
      type: info.label,
      icon: info.icon,
      color: info.color,
      dc: Number(e.dc) || 0,
      roll: Number(e.roll) || 0,
      modifier: Number(e.modifier) || 0,
      total: Number(e.total) || 0,
      outcome: _resistanceOutcomeText(e),
      // Cor por FLAG, não pelo texto: o rótulo é traduzido e comparar strings
      // quebraria em silêncio ao trocar o idioma.
      failed: !e.passed && !e.immune,
      start: performance.now(), duration: _animationProgressDuration(RESISTANCE_FEEDBACK_MS),
      mesh: null,
    };
    _resistanceFeedbacks.push(f);
    if(mode3D && g3) _buildResistanceFeedback3D(f);
  }
  if(_resistanceFeedbacks.length) _requestResistanceFeedbackFrame();
}

function _buildResistanceFeedback3D(f){
  if(!g3 || !g3.scene || !window.THREE || f.mesh) return;
  const T = g3.T, cv = document.createElement('canvas');
  cv.width = 640; cv.height = 150;
  const c = cv.getContext('2d');
  const line1 = `${f.icon} ${f.name} • ${f.type} • CD ${f.dc}`;
  const modText = f.modifier >= 0 ? `+ ${f.modifier}` : `− ${Math.abs(f.modifier)}`;
  const line2 = `d20 ${f.roll} ${modText} = ${f.total} — ${f.outcome}`;
  c.clearRect(0,0,cv.width,cv.height);
  c.textAlign = 'center'; c.textBaseline = 'middle'; c.lineJoin = 'round';
  let fontPx = 30;
  c.font = `900 ${fontPx}px Arial Black, sans-serif`;
  const widest = Math.max(c.measureText(line1).width, c.measureText(line2).width);
  if(widest > cv.width - 24){
    fontPx = Math.max(18, fontPx * (cv.width - 24) / widest);
    c.font = `900 ${fontPx}px Arial Black, sans-serif`;
  }
  c.strokeStyle = 'rgba(5,3,12,0.94)'; c.lineWidth = 11;
  c.strokeText(line1, cv.width/2, 48); c.strokeText(line2, cv.width/2, 105);
  c.fillStyle = f.color; c.fillText(line1, cv.width/2, 48);
  c.fillStyle = f.failed ? '#ff7474' : '#fff1b0';
  c.fillText(line2, cv.width/2, 105);
  const tex = new T.CanvasTexture(cv); tex._owned = true;
  const mat = new T.SpriteMaterial({map:tex, transparent:true, depthWrite:false, depthTest:false, opacity:0});
  const sp = new T.Sprite(mat);
  sp.position.set(f.pos[0], 1.10, f.pos[1]); sp.scale.set(1.72, 0.40, 1); sp.renderOrder = 128;
  g3.scene.add(sp); f.mesh = sp;
}

function _disposeResistanceFeedback3D(f){
  if(!f?.mesh) return;
  if(f.mesh.parent) f.mesh.parent.remove(f.mesh);
  const mat = f.mesh.material, tex = mat?.map;
  if(mat) mat.dispose(); if(tex?._owned) tex.dispose();
  f.mesh = null;
}

function _updateResistanceFeedback3D(now){
  if(!g3) return;
  for(const f of _resistanceFeedbacks){
    if(!f.mesh || f.mesh.parent !== g3.scene) _buildResistanceFeedback3D(f);
    if(!f.mesh) continue;
    const p = Math.max(0, Math.min(1, (now - f.start) / f.duration));
    f.mesh.position.set(f.pos[0], 1.10 + p * 0.28, f.pos[1]);
    f.mesh.material.opacity = p < 0.72 ? 1 : Math.max(0, 1 - (p - 0.72) / 0.28);
  }
}

function _requestResistanceFeedbackFrame(){
  if(_resistanceFeedbackRaf) return;
  const tick = () => {
    _resistanceFeedbackRaf = null;
    const now = performance.now();
    for(let i=_resistanceFeedbacks.length-1;i>=0;i--){
      const f = _resistanceFeedbacks[i];
      if(now - f.start < f.duration) continue;
      _disposeResistanceFeedback3D(f); _resistanceFeedbacks.splice(i,1);
    }
    if(mode3D && g3) _updateResistanceFeedback3D(now);
    else if(!mode3D && GS.gameState) renderMap(GS.gameState);
    if(_resistanceFeedbacks.length) _resistanceFeedbackRaf = _scheduleVisualFrame(tick);
  };
  _resistanceFeedbackRaf = _scheduleVisualFrame(tick);
}

function _conditionPulsePosition(msg){
  if(Array.isArray(msg?.pos)) return [Number(msg.pos[0]), Number(msg.pos[1])];
  const st = GS.gameState;
  const id = msg?.target_id;
  if(id == null || !st) return null;
  const found = [...(st.players||[]), ...(st.monsters||[]),
    ...(st.players||[]).flatMap(p => p.animados || [])]
    .find(e => String(e?.id) === String(id));
  return Array.isArray(found?.pos) ? [Number(found.pos[0]), Number(found.pos[1])] : null;
}

function _queueConditionPulse(msg){
  const pos = _conditionPulsePosition(msg);
  if(!pos || pos.some(v => !Number.isFinite(v))) return;
  const type = String(msg?.tipo || msg?.condition_id || '').toLowerCase();
  const icon = msg?.icone || ({
    sono:'🌙', veneno:'☠️', petrificado:'🗿', enfeiticado:'✨',
    sangramento:'🩸', hemorragia:'⚠️', doenca:'🦠', maldicao:'🔮',
  }[type] || '⚠️');
  const pulse = {pos, icon, start:performance.now(), duration:_animationProgressDuration(980), mesh:null};
  _conditionPulses.push(pulse);
  if(mode3D && g3) _buildConditionPulse3D(pulse);
  _requestConditionPulseFrame();
}

function _buildConditionPulse3D(p){
  if(!g3 || !g3.scene || !window.THREE || p.mesh) return;
  const T=g3.T, cv=document.createElement('canvas'); cv.width=128; cv.height=128;
  const c=cv.getContext('2d'); c.font='72px serif'; c.textAlign='center'; c.textBaseline='middle';
  c.fillText(p.icon,64,64);
  const tex=new T.CanvasTexture(cv); tex._owned=true;
  const mat=new T.SpriteMaterial({map:tex,transparent:true,depthWrite:false,depthTest:false,opacity:0});
  const sp=new T.Sprite(mat); sp.position.set(p.pos[0],1.18,p.pos[1]); sp.scale.set(.38,.38,1); sp.renderOrder=131;
  g3.scene.add(sp); p.mesh=sp;
}

function _disposeConditionPulse3D(p){
  if(!p?.mesh) return;
  if(p.mesh.parent) p.mesh.parent.remove(p.mesh);
  const mat=p.mesh.material, tex=mat?.map; if(mat) mat.dispose(); if(tex?._owned) tex.dispose(); p.mesh=null;
}

function _updateConditionPulses(now){
  for(const p of _conditionPulses){
    if(!p.mesh || p.mesh.parent !== g3?.scene) _buildConditionPulse3D(p);
    if(!p.mesh) continue;
    const q=Math.max(0,Math.min(1,(now-p.start)/p.duration));
    p.mesh.position.set(p.pos[0],1.18+q*.55,p.pos[1]);
    p.mesh.scale.setScalar(.30+q*.22); p.mesh.material.opacity=q<.58?1:Math.max(0,1-(q-.58)/.42);
  }
}

let _conditionPulseRaf=null;
function _requestConditionPulseFrame(){
  if(_conditionPulseRaf) return;
  const tick=()=>{
    _conditionPulseRaf=null; const now=performance.now();
    for(let i=_conditionPulses.length-1;i>=0;i--){
      if(now-_conditionPulses[i].start < _conditionPulses[i].duration) continue;
      _disposeConditionPulse3D(_conditionPulses[i]); _conditionPulses.splice(i,1);
    }
    if(mode3D && g3) _updateConditionPulses(now); else if(!mode3D && GS.gameState) renderMap(GS.gameState);
    if(_conditionPulses.length) _conditionPulseRaf=_scheduleVisualFrame(tick);
  };
  _conditionPulseRaf=_scheduleVisualFrame(tick);
}

function _attackFeedbackVisible(f, state){
  if(!state || GS.isMaster() || state.test_mode) return true;
  const explored = new Set([...(state.explored||[]), ...(state.revealed||[])].map(([x,y])=>`${x},${y}`));
  return explored.has(`${f.targetPos[0]},${f.targetPos[1]}`)
    || explored.has(`${f.attackerPos[0]},${f.attackerPos[1]}`);
}

function _attackFeedbackModeLabel(mode){
  return mode === 'advantage' ? t('ui.hud.vantagem') : mode === 'disadvantage' ? t('ui.hud.desvantagem') : 'NORMAL';
}

// Com cena de combate (3D), o result chega ~240 ms depois do d20 mas o GOLPE
// só acontece quando o dado assenta (1–3 s): até lá o banner não pode revelar
// acerto/erro. `resultAt === Infinity` é a marca "esperando o golpe" que
// _receiveAttackFeedback põe e o `impact` de _executarComandoCena tira.
function _attackFeedbackAguardaGolpe(f){ return !!f.result && f.resultAt === Infinity; }

// Arremesso de ÁREA (frente B): o start vem com alvo sintético (target_name vazio,
// target_pos = casa mirada) e o result não tem teste de ataque — o banner mostra a
// casa e "ÁREA" em vez de "Alvo • ACERTO".
function _attackFeedbackTargetName(msg){
  if(msg.target_name) return msg.target_name;
  if(msg.projectile && msg.projectile.area && Array.isArray(msg.target_pos))
    return t('ui.hud.alvo_area', {x: msg.target_pos[0], y: msg.target_pos[1]});
  return t('ui.hud.alvo');
}

function _attackFeedbackResultLabel(f){
  if(!f.result || _attackFeedbackAguardaGolpe(f)) return 'PREPARANDO';
  if(f.area) return t('ui.hud.resultado_area');
  if(f.natural_critical) return t('ui.hud.20_natural_critico');
  if(f.natural_fumble) return t('ui.hud.1_natural_falha');
  if(f.crit) return t('ui.hud.critico');
  return f.hit ? t('ui.hud.acerto') : t('ui.hud.erro');
}

function _attackFeedbackColor(f){
  if(!f.result || _attackFeedbackAguardaGolpe(f)) return '#ffe18a';
  if(f.natural_critical || f.crit) return '#ffd34d';
  if(f.natural_fumble) return '#d978ff';
  return f.hit ? '#7dffad' : '#ff7373';
}

function _attackFeedbackText(f){
  const mode = _attackFeedbackModeLabel(f.advantageMode);
  const result = _attackFeedbackResultLabel(f);
  return `${f.attackerName} → ${f.targetName} • ${f.attackName} • ${mode} • ${result}`;
}

function _attackFeedbackDirection(f, p){
  const ax = f.attackerPos[0] + .5, ay = f.attackerPos[1] + .5;
  const tx = f.targetPos[0] + .5, ty = f.targetPos[1] + .5;
  const q = Math.max(0, Math.min(1, p));
  return [ax + (tx-ax)*q, ay + (ty-ay)*q, tx, ty];
}

function _combatDamageTypeInfo(type){
  const c = VC.feedback?.combat || {};
  const table = c.damageTypes || {};
  const aliases = {
    fisico:'physical', físico:'physical', physical:'physical',
    fogo:'fire', fire:'fire', chamas:'fire',
    frio:'cold', frio_: 'cold', gelo:'cold', cold:'cold',
    eletricidade:'lightning', eletrico:'lightning', elétrico:'lightning', electric:'lightning',
    raio:'lightning', relampago:'lightning', relâmpago:'lightning', lightning:'lightning',
    acido:'acid', ácido:'acid', acid:'acid',
    veneno:'poison', poison:'poison',
    sagrado:'holy', holy:'holy', luz:'holy', light:'holy',
    magico:'magic', mágico:'magic', magic:'magic',
    agua:'water', água:'water', water:'water',
  };
  const key = aliases[String(type || '').trim().toLowerCase()] || String(type || '').trim().toLowerCase();
  return { key, ...(table[key] || table.physical || {color:'#f4eee2', icon:'⚔', label:t('ui.hud.fisico')}) };
}

function _combatPrimaryDamageType(types){
  const list = (Array.isArray(types) ? types : [types])
    .map(t => _combatDamageTypeInfo(t).key).filter(Boolean);
  if(!list.length) return 'physical';
  // Em um golpe misto (arma + sagrado, por exemplo), a cor energética vence
  // a cor física para que a propriedade especial fique imediatamente visível.
  const priority = ['fire','cold','lightning','acid','poison','holy','magic','water','physical'];
  return priority.find(t => list.includes(t)) || list[0];
}

function _combatFeedbackColor(kind, damageType){
  const c = VC.feedback?.combat || {};
  if(kind === 'heal') return c.healColor || '#69f59a';
  if(kind === 'death') return c.deathColor || '#f4d27a';
  if(damageType){
    const info = _combatDamageTypeInfo(damageType);
    if(_highContrast){
      const highContrastColors = {
        physical:'#ffffff', fire:'#ff9d00', cold:'#00eaff', lightning:'#fff500',
        acid:'#72ff3b', poison:'#ff65ff', holy:'#fff2a6', magic:'#eaa7ff', water:'#62dfff'
      };
      return highContrastColors[info.key] || '#ffffff';
    }
    // Golpes físicos contra heróis mantêm o vermelho já conhecido; os demais
    // usam a cor do elemento para não esconder fogo/frio/ácido no HUD.
    if(info.key !== 'physical' || kind !== 'hero_damage') return info.color;
  }
  return kind === 'hero_damage' ? (c.heroDamageColor || '#ff8d8d')
    : (c.damageColor || '#ff6262');
}

function _combatFeedbackDisplayText(f){
  if(!f || f.kind === 'death' || !f.damageType){
    if(f?.kind === 'heal' && f.status) return `${f.text} ${f.status}`;
    return f?.text || '';
  }
  const icon = _combatDamageTypeInfo(f.damageType).icon;
  const base = icon ? `${icon} ${f.text}` : f.text;
  return f.status ? `${base} ${f.status}` : base;
}

function _combatFeedbackVisible(f, state){
  if(!state || GS.isMaster() || state.test_mode) return true;
  const explored = new Set([...(state.explored||[]), ...(state.revealed||[])].map(([x,y])=>`${x},${y}`));
  return explored.has(`${f.pos[0]},${f.pos[1]}`);
}

function _buildCombatFeedback3D(f){
  if(!g3 || !g3.scene || !window.THREE || f.mesh) return;
  const T = g3.T, cv = document.createElement('canvas');
  cv.width = 384; cv.height = 112;
  const c = cv.getContext('2d');
  const color = _combatFeedbackColor(f.kind, f.damageType);
  const displayText = _combatFeedbackDisplayText(f);
  c.clearRect(0,0,cv.width,cv.height);
  const fontBase = (f.kind === 'death' ? 54
    : 64 * (f.critical ? (VC.feedback?.combat?.criticalFontScale ?? 1.32) : 1)) * _accessFontScale;
  c.font = `900 ${fontBase}px Arial Black, sans-serif`;
  // "☠ DERROTADO" é bem mais largo que um número. Reduzimos apenas a fonte
  // quando ela não cabe na textura, evitando que o CanvasTexture a corte nas
  // extremidades; o feedback continua centralizado no peão.
  const textWidth = c.measureText(displayText).width;
  const textLimit = cv.width - 36;
  const fontPx = textWidth > textLimit ? fontBase * textLimit / textWidth : fontBase;
  c.font = `900 ${fontPx}px Arial Black, sans-serif`;
  c.textAlign = 'center'; c.textBaseline = 'middle';
  c.lineJoin = 'round'; c.lineWidth = 15; c.strokeStyle = 'rgba(8,4,12,0.92)';
  c.strokeText(displayText, cv.width/2, cv.height/2 + 2);
  c.fillStyle = color; c.fillText(displayText, cv.width/2, cv.height/2 + 2);
  const tex = new T.CanvasTexture(cv); tex._owned = true;
  const mat = new T.SpriteMaterial({map:tex, transparent:true, depthWrite:false,
    depthTest:false, opacity:0});
  const sp = new T.Sprite(mat);
  sp.position.set(f.pos[0], 0.86, f.pos[1]);
  sp.scale.set(
    (f.kind === 'death' ? 1.18 : 0.74 * COMBAT_FEEDBACK_DAMAGE_FONT_SCALE * (f.critical ? 1.12 : 1)) * _accessFontScale,
    (f.kind === 'death' ? 0.34 : 0.27 * COMBAT_FEEDBACK_DAMAGE_FONT_SCALE * (f.critical ? 1.12 : 1)) * _accessFontScale,
    1
  );
  sp.renderOrder = 125;
  g3.scene.add(sp); f.mesh = sp;
}

function _disposeCombatFeedback3D(f){
  if(!f.mesh) return;
  const mesh = f.mesh;
  if(mesh.parent) mesh.parent.remove(mesh);
  const mat = mesh.material;
  const tex = mat && mat.map;
  if(mat) mat.dispose();
  if(tex && tex._owned) tex.dispose();
  f.mesh = null;
}

function _updateCombatFeedback3D(now){
  if(!g3) return;
  for(const f of _combatFeedbacks){
    if(!f.mesh || f.mesh.parent !== g3.scene) _buildCombatFeedback3D(f);
    if(!f.mesh) continue;
    // Alguns feedbacks podem estar agendados para depois de uma animação de
    // magia. Mantemos o sprite criado para não alterar o fluxo 3D, mas ele
    // permanece invisível até o instante autorizado.
    if(now < f.start){
      f.mesh.material.opacity = 0;
      continue;
    }
    const p = Math.max(0, Math.min(1, (now - f.start) / f.duration));
    const fade = p < 0.62 ? 1 : Math.max(0, 1 - (p - 0.62) / 0.38);
    f.mesh.position.set(f.pos[0], 0.86 + p * 0.62, f.pos[1]);
    f.mesh.material.opacity = fade;
    const s = 0.92 + 0.10 * Math.sin(Math.min(1, p / 0.22) * Math.PI);
    f.mesh.scale.set(
      (f.kind === 'death' ? 1.18 : 0.74 * COMBAT_FEEDBACK_DAMAGE_FONT_SCALE * (f.critical ? 1.12 : 1)) * _accessFontScale * s,
      (f.kind === 'death' ? 0.34 : 0.27 * COMBAT_FEEDBACK_DAMAGE_FONT_SCALE * (f.critical ? 1.12 : 1)) * _accessFontScale * s,
      1
    );
  }
}

function _attackFeedbackProgress(f, now){
  const elapsed = now - f.startedAt;
  if(!f.result || (f.resultAt && now < f.resultAt))
    return {p: Math.max(0, Math.min(1, elapsed / (f.prepDuration || _animationProgressDuration(ATTACK_FEEDBACK_PREP_MS)))), done:false, preparing:true};
  const p = Math.max(0, Math.min(1, (now - f.resultAt) / (f.resultDuration || _animationProgressDuration(ATTACK_FEEDBACK_RESULT_MS))));
  return {p, done:p >= 1, preparing:false};
}

function _holyStrikeProgress(f, now){
  if(!f?.holyStrike || !Number.isFinite(f.holyStrikeAt)) return null;
  // O arco atravessa o alvo junto com os ~110 ms da fase GOLPE; o restante é só o fade.
  const p=Math.max(0,Math.min(1,(now-f.holyStrikeAt)/HOLY_STRIKE_DURATION_MS));
  return {p,active:p<1};
}

function _holyStrikeLunge(playerId, now){
  if(mode3D) return [0,0]; // a cena de combate já move o peão 3D no golpe
  let chosen=null;
  for(const f of _attackFeedbacks){
    if(!f.holyStrike || String(f.attackerId)!==String(playerId)) continue;
    const q=_holyStrikeProgress(f,now);
    if(q?.active && (!chosen || f.holyStrikeAt>chosen.holyStrikeAt)) chosen=f;
  }
  if(!chosen) return [0,0];
  const q=_holyStrikeProgress(chosen,now), [ax,ay]=chosen.attackerPos, [tx,ty]=chosen.targetPos;
  const len=Math.max(.001,Math.hypot(tx-ax,ty-ay)), travel=Math.sin(Math.PI*Math.min(1,q.p/.72));
  return [((tx-ax)/len)*CELL*.18*travel,((ty-ay)/len)*CELL*.18*travel];
}

function _drawHolyStrike2D(ctx, f, now){
  const q=_holyStrikeProgress(f,now);
  if(!q?.active) return;
  const [ax,ay]=f.attackerPos,[tx,ty]=f.targetPos;
  const dx=tx-ax,dy=ty-ay,len=Math.max(.001,Math.hypot(dx,dy)),ux=dx/len,uy=dy/len,px=-uy,py=ux;
  const cx=(tx+.5)*CELL,cy=(ty+.5)*CELL,swipe=Math.max(0,Math.min(1,q.p/.28));
  const power=f.holyLevel>=3?1.4:f.holyLevel>=2?1.2:1;
  const fade=q.p<.28?Math.min(1,q.p/.05):Math.max(0,1-(q.p-.28)/.72);
  ctx.save(); ctx.globalCompositeOperation='lighter'; ctx.globalAlpha=fade;
  const sx=cx-ux*CELL*.38-px*CELL*.34,sy=cy-uy*CELL*.38-py*CELL*.34;
  const ex=cx+ux*CELL*.28+px*CELL*.34,ey=cy+uy*CELL*.28+py*CELL*.34;
  const mx=sx+(ex-sx)*swipe,my=sy+(ey-sy)*swipe;
  ctx.lineCap='round'; ctx.shadowColor='#ffe66e'; ctx.shadowBlur=CELL*.34*power;
  ctx.strokeStyle='rgba(255,205,63,.82)';ctx.lineWidth=Math.max(5,CELL*.16*power);
  ctx.beginPath();ctx.moveTo(sx,sy);ctx.quadraticCurveTo(cx+px*CELL*.3,cy+py*CELL*.3,mx,my);ctx.stroke();
  ctx.shadowColor='#fffbe0';ctx.shadowBlur=CELL*.16*power;ctx.strokeStyle='rgba(255,255,239,.98)';ctx.lineWidth=Math.max(2,CELL*.055*power);
  ctx.beginPath();ctx.moveTo(sx,sy);ctx.quadraticCurveTo(cx+px*CELL*.3,cy+py*CELL*.3,mx,my);ctx.stroke();
  if(f.hit && q.p>=.28){
    const pulse=Math.sin(Math.PI*Math.min(1,(q.p-.28)/.72)),r=CELL*(.13+.30*(1-pulse));
    ctx.globalAlpha=fade*pulse;ctx.strokeStyle='#fff0a0';ctx.lineWidth=Math.max(2,CELL*.035);ctx.shadowBlur=CELL*.14;
    ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);ctx.stroke();
    ctx.beginPath();ctx.moveTo(cx,cy-r*.62);ctx.lineTo(cx,cy+r*.62);ctx.moveTo(cx-r*.42,cy-r*.16);ctx.lineTo(cx+r*.42,cy-r*.16);ctx.stroke();
    ctx.beginPath();ctx.moveTo(cx,cy-CELL*.32);ctx.lineTo(cx+CELL*.07,cy-CELL*.13);ctx.lineTo(cx+CELL*.27,cy-CELL*.10);ctx.lineTo(cx+CELL*.12,cy+CELL*.04);ctx.lineTo(cx+CELL*.17,cy+CELL*.24);ctx.lineTo(cx,cy+CELL*.12);ctx.lineTo(cx-CELL*.17,cy+CELL*.24);ctx.lineTo(cx-CELL*.12,cy+CELL*.04);ctx.lineTo(cx-CELL*.27,cy-CELL*.10);ctx.lineTo(cx-CELL*.07,cy-CELL*.13);ctx.closePath();ctx.stroke();
  }
  ctx.restore();
}

function _drawAttackFeedback2D(ctx, state, now){
  for(const f of _attackFeedbacks){
    if(!_attackFeedbackVisible(f, state)) continue;
    _drawHolyStrike2D(ctx,f,now);
    const progress = _attackFeedbackProgress(f, now);
    if(progress.done) continue;
    const prep = progress.preparing;
    const travel = prep ? progress.p : 1;
    const [sx, sy, tx, ty] = _attackFeedbackDirection(f, travel);
    const x1=sx*CELL, y1=sy*CELL, x2=tx*CELL, y2=ty*CELL;
    const dx=x2-x1, dy=y2-y1, len=Math.max(1,Math.hypot(dx,dy));
    const ux=dx/len, uy=dy/len, px=-uy, py=ux;
    const color = _attackFeedbackColor(f);
    const alpha = f.result ? Math.max(0, 1-progress.p) : .88;
    ctx.save();
    ctx.globalAlpha=alpha;
    ctx.lineCap='round';
    ctx.shadowColor=color; ctx.shadowBlur=prep ? 10 : 15;
    ctx.strokeStyle=color; ctx.lineWidth=Math.max(2, CELL*.045);
    ctx.beginPath(); ctx.moveTo(x1,y1); ctx.lineTo(x2,y2); ctx.stroke();
    // Duas hastes formam uma ponta de seta sem depender de fonte/emoji.
    ctx.shadowBlur=0; ctx.lineWidth=Math.max(2, CELL*.035);
    ctx.beginPath();
    ctx.moveTo(x2-ux*CELL*.22+px*CELL*.12, y2-uy*CELL*.22+py*CELL*.12);
    ctx.lineTo(x2,y2);
    ctx.lineTo(x2-ux*CELL*.22-px*CELL*.12, y2-uy*CELL*.22-py*CELL*.12);
    ctx.stroke();
    if(prep){
      ctx.strokeStyle='#ffe18a'; ctx.lineWidth=Math.max(2,CELL*.025);
      ctx.beginPath(); ctx.arc(f.attackerPos[0]*CELL+CELL/2, f.attackerPos[1]*CELL+CELL/2,
        CELL*(.28+.18*Math.sin(progress.p*Math.PI)), 0, Math.PI*2); ctx.stroke();
    } else if(f.natural_critical || f.natural_fumble){
      // 20/1 natural recebe uma explosão própria, além da cor e do texto.
      const specialColor=f.natural_critical ? '#ffd34d' : '#d978ff';
      const bx=x2, by=y2, pulse=Math.max(0,1-progress.p);
      ctx.strokeStyle=specialColor; ctx.lineWidth=Math.max(2,CELL*.028);
      for(let i=0;i<8;i++){
        const a=i*Math.PI/4, r1=CELL*(.18+.10*(1-pulse)), r2=CELL*(.40+.18*(1-pulse));
        ctx.beginPath(); ctx.moveTo(bx+Math.cos(a)*r1,by+Math.sin(a)*r1);
        ctx.lineTo(bx+Math.cos(a)*r2,by+Math.sin(a)*r2); ctx.stroke();
      }
      ctx.fillStyle=specialColor; ctx.font=`900 ${Math.round(CELL*.32)}px Arial Black, sans-serif`;
      ctx.fillText(f.natural_critical?'✦':'!', bx, by-CELL*.32);
    }
    const midX=(x1+x2)/2, midY=(y1+y2)/2-CELL*.18;
    const label=_attackFeedbackText(f);
    ctx.font=`900 ${Math.max(11,Math.round(CELL*.145))}px Arial Black, sans-serif`;
    ctx.textAlign='center'; ctx.textBaseline='middle';
    const tw=ctx.measureText(label).width, pad=CELL*.08;
    ctx.fillStyle='rgba(8,4,12,.84)';
    ctx.fillRect(midX-tw/2-pad, midY-CELL*.12, tw+pad*2, CELL*.24);
    ctx.fillStyle=color; ctx.fillText(label, midX, midY);
    ctx.restore();
  }
}

function _buildAttackFeedback3D(f){
  if(!g3 || !g3.scene || !window.THREE || f.group) return;
  const T=g3.T, group=new T.Group(); group.name='attack-feedback';
  const lineMat=new T.LineBasicMaterial({color:0xffe18a,transparent:true,opacity:0,depthWrite:false,depthTest:false});
  const lineGeo=new T.BufferGeometry();
  const line=new T.Line(lineGeo,lineMat); group.add(line); f.line=line;
  const arrowMat=lineMat.clone();
  const arrowGeo=new T.BufferGeometry();
  const arrow=new T.Line(arrowGeo,arrowMat); group.add(arrow); f.arrow=arrow;
  const ring=new T.Mesh(new T.TorusGeometry(.32,.025,8,28),new T.MeshBasicMaterial({color:0xffe18a,transparent:true,opacity:0,depthWrite:false,depthTest:false}));
  ring.rotation.x=Math.PI/2; ring.renderOrder=118; group.add(ring); f.ring=ring;
  const cv=document.createElement('canvas'); cv.width=720; cv.height=92;
  const tex=new T.CanvasTexture(cv); tex._owned=true;
  const mat=new T.SpriteMaterial({map:tex,transparent:true,opacity:0,depthWrite:false,depthTest:false});
  const sprite=new T.Sprite(mat); sprite.scale.set(3.4,.43,1); sprite.renderOrder=120; group.add(sprite);
  if(f.holyStrike){
    const glow=new T.Mesh(_holyRibbonGeometry(T),new T.MeshBasicMaterial({color:0xffbd35,transparent:true,opacity:0,depthWrite:false,depthTest:false,blending:T.AdditiveBlending,side:T.DoubleSide,toneMapped:false}));
    const core=new T.Mesh(_holyRibbonGeometry(T),new T.MeshBasicMaterial({color:0xfffbe3,transparent:true,opacity:0,depthWrite:false,depthTest:false,blending:T.AdditiveBlending,side:T.DoubleSide,toneMapped:false}));
    glow.renderOrder=136; core.renderOrder=137; glow.frustumCulled=false; core.frustumCulled=false;
    group.add(glow,core); f.holyGlow=glow; f.holyCore=core;
    const runeMat=new T.LineBasicMaterial({color:0xffe37a,transparent:true,opacity:0,depthWrite:false,depthTest:false,blending:T.AdditiveBlending});
    const rune=new T.Line(new T.BufferGeometry(),runeMat), glyph=new T.LineSegments(new T.BufferGeometry(),runeMat.clone());
    rune.renderOrder=135; glyph.renderOrder=136; rune.frustumCulled=false; glyph.frustumCulled=false;
    group.add(rune,glyph); f.holyRune=rune; f.holyGlyph=glyph;
  }
  f.group=group; f.sprite=sprite; f.canvas=cv; f.texture=tex;
  g3.scene.add(group);
  _drawAttackFeedbackTexture3D(f);
}

function _drawAttackFeedbackTexture3D(f){
  if(!f.canvas) return;
  const c=f.canvas.getContext('2d'), color=_attackFeedbackColor(f);
  c.clearRect(0,0,f.canvas.width,f.canvas.height);
  c.font='900 30px Arial Black, sans-serif'; c.textAlign='center'; c.textBaseline='middle';
  const label=_attackFeedbackText(f);
  c.fillStyle='rgba(8,4,12,.90)'; c.fillRect(8,8,f.canvas.width-16,f.canvas.height-16);
  c.strokeStyle=color; c.lineWidth=4; c.strokeRect(8,8,f.canvas.width-16,f.canvas.height-16);
  c.fillStyle=color; c.fillText(label,f.canvas.width/2,f.canvas.height/2);
  if(f.texture) f.texture.needsUpdate=true;
}

function _holyRibbonGeometry(T){
  const segments=12, positions=new Float32Array((segments+1)*2*3), indices=[];
  for(let i=0;i<segments;i++){
    const a=i*2,b=a+1,c=a+2,d=a+3;
    indices.push(a,c,b,b,c,d);
  }
  const geometry=new T.BufferGeometry();
  geometry.setAttribute('position',new T.BufferAttribute(positions,3));
  geometry.setIndex(indices); geometry.setDrawRange(0,0);
  // A malha muda de lugar durante o golpe; não deixar uma esfera calculada
  // quando a malha estava vazia fazer o frustum culling escondê-la.
  return geometry;
}

function _updateHolyRibbon(mesh, start, control, end, perp, swipe, width){
  const geometry=mesh.geometry, positions=geometry.attributes.position.array, segments=12;
  for(let i=0;i<=segments;i++){
    const u=swipe*i/segments,v=1-u;
    const x=start[0]*v*v+control[0]*2*v*u+end[0]*u*u;
    const z=start[1]*v*v+control[1]*2*v*u+end[1]*u*u;
    const y=.25+Math.sin(Math.PI*u)*.8;
    const taper=.28+.72*Math.sin(Math.PI*u), half=width*taper;
    const k=i*6;
    positions[k]=x+perp[0]*half; positions[k+1]=y; positions[k+2]=z+perp[1]*half;
    positions[k+3]=x-perp[0]*half; positions[k+4]=y; positions[k+5]=z-perp[1]*half;
  }
  geometry.attributes.position.needsUpdate=true;
  geometry.setDrawRange(0,swipe>0?segments*6:0);
  geometry.computeBoundingSphere();
}

function _updateAttackFeedback3D(now){
  if(!g3) return;
  for(const f of _attackFeedbacks){
    // Dispara no mesmo frame em que a CombatScene começa a avançar o peão.
    if(f.holyStrike && !Number.isFinite(f.holyStrikeAt)
       && window.CombatScene?.phaseOf(f.id)==='GOLPE') f.holyStrikeAt=now;
    if(!f.group || f.group.parent!==g3.scene) _buildAttackFeedback3D(f);
    if(!f.group) continue;
    const q=_attackFeedbackProgress(f,now), prep=q.preparing;
    const ax=f.attackerPos[0]+.5, az=f.attackerPos[1]+.5;
    const tx=f.targetPos[0]+.5, tz=f.targetPos[1]+.5;
    const ex=prep ? ax+(tx-ax)*q.p : tx, ez=prep ? az+(tz-az)*q.p : tz;
    const opacity=prep ? .82 : Math.max(0,1-q.p);
    const color=new g3.T.Color(_attackFeedbackColor(f));
    const points=[new g3.T.Vector3(ax,.28,az),new g3.T.Vector3(ex,.28,ez)];
    f.line.geometry.setFromPoints(points); f.line.material.color.copy(color); f.line.material.opacity=opacity;
    const dx=tx-ex,dz=tz-ez,len=Math.max(.001,Math.hypot(dx,dz)),ux=dx/len,uz=dz/len,px=-uz,pz=ux;
    f.arrow.geometry.setFromPoints([
      new g3.T.Vector3(tx-ux*.25+px*.13,.28,tz-uz*.25+pz*.13),
      new g3.T.Vector3(tx,.28,tz),
      new g3.T.Vector3(tx-ux*.25-px*.13,.28,tz-uz*.25-pz*.13),
    ]); f.arrow.material.color.copy(color); f.arrow.material.opacity=opacity;
    f.ring.position.set(prep ? ax : tx,.29,prep ? az : tz); f.ring.material.color.copy(color);
    f.ring.material.opacity=prep ? opacity : (f.natural_critical || f.natural_fumble ? opacity*.9 : 0);
    f.sprite.position.set((ax+tx)/2,.64,(az+tz)/2); f.sprite.material.opacity=opacity;
    const holy=_holyStrikeProgress(f,now);
    if(holy && f.holyGlow && holy.active){
      const dx=tx-ax,dz=tz-az,len=Math.max(.001,Math.hypot(dx,dz)),ux=dx/len,uz=dz/len,px=-uz,pz=ux;
      const p=holy.p,swipe=Math.max(0,Math.min(1,p/.28)),fade=p<.28?Math.min(1,p/.05):Math.max(0,1-(p-.28)/.72);
      const power=f.holyLevel>=3?1.4:f.holyLevel>=2?1.2:1;
      const sx=tx-ux*.38-px*.34,sz=tz-uz*.38-pz*.34,ex=tx+ux*.28+px*.34,ez=tz+uz*.28+pz*.34;
      const start=[sx,sz],control=[tx+px*.30,tz+pz*.30],end=[sx+(ex-sx)*swipe,sz+(ez-sz)*swipe],perp=[px,pz];
      _updateHolyRibbon(f.holyGlow,start,control,end,perp,swipe,.105*power);
      _updateHolyRibbon(f.holyCore,start,control,end,perp,swipe,.034*power);
      f.holyGlow.material.opacity=.95*fade;f.holyCore.material.opacity=fade;
      if(f.holyRune){
        const rp=Math.max(0,Math.min(1,(p-.28)/.72)),pulse=Math.sin(Math.PI*rp),r=.12+.28*(1-pulse),pts=[],glyphPts=[];
        if(f.hit && p>=.28){
          for(let i=0;i<=40;i++){const a=i/40*Math.PI*2;pts.push(new g3.T.Vector3(tx+Math.cos(a)*r,.045,tz+Math.sin(a)*r));}
          // Cruz luminosa e pequenos raios formam um glifo reconhecível sem texto.
          for(const [x1,z1,x2,z2] of [[0,-r*.65,0,r*.65],[-r*.42,-r*.16,r*.42,-r*.16],[0,-.34,.07,-.13],[.07,-.13,.26,-.10],[.26,-.10,.11,.04],[.11,.04,.17,.24],[.17,.24,0,.12],[0,.12,-.17,.24],[-.17,.24,-.11,.04],[-.11,.04,-.26,-.10],[-.26,-.10,-.07,-.13],[-.07,-.13,0,-.34]]){
            glyphPts.push(new g3.T.Vector3(tx+x1,.05,tz+z1),new g3.T.Vector3(tx+x2,.05,tz+z2));
          }
        }
        f.holyRune.geometry.setFromPoints(pts);f.holyRune.geometry.boundingSphere=null;f.holyRune.material.opacity=f.hit?fade*pulse:0;
        f.holyGlyph.geometry.setFromPoints(glyphPts);f.holyGlyph.geometry.boundingSphere=null;f.holyGlyph.material.opacity=f.hit?fade*pulse:0;
      }
    }else if(f.holyGlow){f.holyGlow.material.opacity=0;f.holyCore.material.opacity=0;if(f.holyRune)f.holyRune.material.opacity=0;if(f.holyGlyph)f.holyGlyph.material.opacity=0;}
    if(prep) f.ring.scale.setScalar(.82+.28*Math.sin(q.p*Math.PI));
    else if(f.natural_critical || f.natural_fumble) f.ring.scale.setScalar(1.0+q.p*.9);
  }
}

function _disposeAttackFeedback(f){
  if(!f.group) return;
  if(f.group.parent) f.group.parent.remove(f.group);
  f.group.traverse(o=>{ if(o.geometry) o.geometry.dispose(); if(o.material){ const m=Array.isArray(o.material)?o.material:[o.material]; m.forEach(x=>x.dispose()); }});
  if(f.texture && f.texture._owned) f.texture.dispose();
  f.group=null;
}

function _holyStrikeMaybeStartLevel3Ray(f, now){
  if(!f?.holyStrike || f.holyLevel<3 || !f.hit || f.holyRayStarted
     || !Number.isFinite(f.holyStrikeAt)) return;
  // O prenúncio começa antes e o feixe vertical surge na metade do arco.
  if(now-f.holyStrikeAt<HOLY_LEVEL3_RAY_DELAY_MS) return;
  f.holyRayStarted=true;
  const anim=_raioDivinoAnimFromMessage({
    animation_id:`golpe_sagrado_${f.id}`, caster_id:f.attackerId, target_id:f.targetId,
    origin:f.attackerPos, target:f.targetPos,
    travel_ms:HOLY_LEVEL3_RAY_TRAVEL_MS, impact_ms:860,
  });
  // A animação genérica do Raio Divino tem viagem mínima de 420 ms; este
  // follow-up visual precisa chegar durante o arco de 420 ms do Golpe Sagrado.
  anim.travelMs=HOLY_LEVEL3_RAY_TRAVEL_MS;
  // É somente um follow-up visual do Golpe Sagrado: sem rolagem, dano, save
  // ou liberação de dados da magia Raio Divino.
  anim.holyTarget=true; anim.visualOnly=true;
  _raioDivinoAnims.push(anim); _tocarSomRaioDivino(anim);
  if(!_raioDivinoRaf) _raioDivinoRaf=_scheduleVisualFrame(_tickRaioDivino);
}

// ── Cena de combate (CombatScene) — fiação no cliente 3D ─────────────────────
// Os ids de attack_feedback vêm de new_id() (únicos entre heróis e monstros);
// a chave de entidade é a mesma dos _hitReactions / _gatherHpEntries.
function _entityKeyById(id){
  const st = GS.gameState;
  if(!st || id == null) return null;
  const sid = String(id);
  if((st.players || []).some(p => String(p.id) === sid)) return `p:${id}`;
  if((st.monsters || []).some(m => String(m.id) === sid)) return `m:${id}`;
  for(const p of (st.players || []))
    if((p.animados || []).some(a => String(a.id) === sid)) return `a:${id}`;
  if(st.prisoner && st.prisoner.id != null && String(st.prisoner.id) === sid) return 'pr:singleton';
  return null;
}

function _cenaAtiva(){ return !!(mode3D && g3 && window.CombatScene); }

// ── Projéteis (frente B) ───────────────────────────────────────────────────────
// Um voo por comando `launch` da CombatScene. Objeto de cena independente (não
// é filho do peão), materiais PRÓPRIOS (nunca os clones _sceneMats do peão),
// posições vindas do próprio comando (nunca de userData.gridX). Família dos
// efeitos _bolaFogo*: build/update/dispose + lista + tick no laço 3D.
const _projeteis = [];
let _projetilGeo = null;   // geometrias/materiais base por tipo, criados uma vez
const _PROJETIL_COR_ELEMENTO = { fogo: 0xff8a32, sagrado: 0xffd700, acido: 0x76e05a };

function _projetilCfg(){ return VC.feedback?.combat?.scene?.projectile || {}; }

function _projetilBases(T){
  if(_projetilGeo) return _projetilGeo;
  const madeira = new T.MeshStandardMaterial({ color: 0x5a3a1e, roughness: .8 });
  const aco     = new T.MeshStandardMaterial({ color: 0x9aa3ad, roughness: .35, metalness: .7 });
  const pena    = new T.MeshStandardMaterial({ color: 0xe8e2d0, roughness: .9, side: T.DoubleSide });
  const mk = (comp, raio, ponta, empenas) => {
    const g = new T.Group();
    const haste = new T.Mesh(new T.CylinderGeometry(raio, raio, comp, 6), madeira);
    haste.rotation.x = Math.PI / 2;                       // eixo Z = direção do voo
    g.add(haste);
    const tip = new T.Mesh(new T.ConeGeometry(raio * 2.4, ponta, 6), aco);
    tip.rotation.x = Math.PI / 2; tip.position.z = comp / 2 + ponta / 2; g.add(tip);
    for(let i = 0; i < empenas; i++){
      const e = new T.Mesh(new T.PlaneGeometry(0.08, 0.05), pena);
      // O plano da empena CONTÉM o eixo Z (haste), com o lado 0.08 ao longo dela —
      // no plano XY ficaria de perfil (invisível) de qualquer vista lateral.
      e.position.z = -comp / 2 + 0.05;
      if(i === 0) e.rotation.set(0, Math.PI / 2, 0); else e.rotation.set(Math.PI / 2, 0, Math.PI / 2);
      g.add(e);
    }
    g.userData.comp = comp;
    return g;
  };
  _projetilGeo = {
    arrow: mk(0.55, 0.012, 0.06, 2),
    bolt:  mk(0.35, 0.018, 0.06, 1),
    spear: mk(0.95, 0.016, 0.10, 0),
    mats: [madeira, aco, pena],
  };
  return _projetilGeo;
}

function _projetilSpriteItem(T, itemId, emoji){
  const cv = document.createElement('canvas'); cv.width = cv.height = 64;
  const c2 = cv.getContext('2d');
  c2.font = '48px serif'; c2.textAlign = 'center'; c2.textBaseline = 'middle';
  c2.fillText(emoji || '🧪', 32, 36);
  const tex = new T.CanvasTexture(cv); tex._owned = true;
  const mat = new T.SpriteMaterial({ map: tex, transparent: true, depthWrite: false });
  const spr = new T.Sprite(mat); spr.scale.set(0.35, 0.35, 0.35);
  if(itemId){
    // PNG real do item quando existe; falha (404/rede) mantém o emoji.
    new T.TextureLoader().load(_assetURL(`assets/itens/${itemId}.png`), png => {
      if(!spr.parent) { png.dispose(); return; }        // voo já acabou
      png._owned = true; mat.map = png; mat.needsUpdate = true; tex.dispose();
    }, undefined, () => {});
  }
  return spr;
}

function _projetilLancar(c){
  if(!g3 || !g3.scene || !window.THREE) return;
  const pc = _projetilCfg();
  if(pc.enabled === false) return;
  if(!(c.flightMs >= 20)) return;                       // instant/fast extremo: sem voo
  const T = g3.T;
  const kind = c.kind;
  let obj;
  if(kind === 'item') obj = _projetilSpriteItem(T, c.item_id, c.item_emoji);
  else obj = _projetilBases(T)[kind === 'bolt' ? 'bolt' : kind === 'spear' ? 'spear' : 'arrow'].clone();
  const dist = Math.max(1, Math.hypot(c.to[0] - c.from[0], c.to[1] - c.from[1]));
  const arcCfg = pc.arc || {};
  const arco = kind === 'arrow' ? (arcCfg.arrow ?? .25) + (arcCfg.arrowPerTile ?? .04) * dist
             : kind === 'bolt' ? (arcCfg.bolt ?? .08) : kind === 'spear' ? (arcCfg.spear ?? .35) : (arcCfg.item ?? .55);
  const anim = {
    id: c.id, kind, obj, hit: !!c.hit, fumble: !!c.fumble, area: !!c.area, area_raio: c.area_raio || 0,
    elemento: c.item_elemento || null,
    from: [c.from[0], c.from[1]], to: [c.to[0], c.to[1]],
    // Erro/fumble pousa no chão: seta cravada quase rente (0.02); o sprite do item
    // (0.35 de altura) fica a 0.15 para não ser cortado pelo piso.
    y0: pc.launchY ?? .45, y1: (!c.hit || c.fumble) ? (kind === 'item' ? 0.15 : 0.02) : (pc.landY ?? .35), arco,
    start: performance.now(), flightMs: c.flightMs, travelMs: c.travelMs,
    impactAt: performance.now() + c.travelMs,
    lingerMs: (!c.hit || c.fumble) ? (pc.stickMs ?? 900) : (pc.hitLingerMs ?? 300),
    spin: (pc.itemSpinPerSec ?? 2.5) * Math.PI * 2,
    pousado: false, quebrado: false, ring: null,
  };
  obj.position.set(anim.from[0], anim.y0, anim.from[1]);
  g3.scene.add(obj);
  _projeteis.push(anim);
}

function _projetilPos(anim, u){
  const x = anim.from[0] + (anim.to[0] - anim.from[0]) * u;
  const z = anim.from[1] + (anim.to[1] - anim.from[1]) * u;
  const y = anim.y0 + (anim.y1 - anim.y0) * u + 4 * anim.arco * u * (1 - u);
  return [x, y, z];
}

function _projetilQuebrar(anim, now){
  if(anim.quebrado || !g3) return;
  anim.quebrado = true;
  const T = g3.T, pc = _projetilCfg();
  const [x, y, z] = _projetilPos(anim, 1);
  // Cor do estilhaço pelo elemento do item (fogo/sagrado/ácido); sem elemento, vidro cinza.
  const cor = _PROJETIL_COR_ELEMENTO[anim.elemento] || 0xbfbfbf;
  let n = 14;
  if(anim.area){
    n = (pc.areaBurst?.base ?? 18) + (pc.areaBurst?.perRadius ?? 8) * anim.area_raio;
    // Anel no chão que expande e desvanece (como o anel de derrota).
    const mat = new T.MeshBasicMaterial({ color: 0xffb060, transparent: true, opacity: .8, depthWrite: false, blending: T.AdditiveBlending, side: T.DoubleSide });
    const ring = new T.Mesh(new T.TorusGeometry(.35, .03, 8, 32), mat);
    ring.rotation.x = Math.PI / 2; ring.position.set(x, .03, z); ring.renderOrder = 135;
    g3.scene.add(ring); anim.ring = { mesh: ring, start: now, raio: Math.max(1, anim.area_raio) };
  }
  _spawnBurstParticles(T, g3.scene, { x, y: Math.max(.1, y), z }, cor, n);
}

function _projetilUpdate3D(anim, now){
  const el = now - anim.start;
  const u = Math.min(1, el / Math.max(1, anim.flightMs));
  const [x, y, z] = _projetilPos(anim, u);
  const obj = anim.obj;
  if(u < 1){
    obj.position.set(x, y, z);
    if(anim.kind === 'item'){
      obj.material.rotation = (el / 1000) * anim.spin;
    } else {
      const [x2, y2, z2] = _projetilPos(anim, Math.min(1, u + 0.02));
      obj.lookAt(x2, y2, z2);                             // eixo Z do grupo = ponta
    }
    return;
  }
  if(!anim.pousado){
    anim.pousado = true; anim.pousoAt = now;
    obj.position.set(x, y, z);
    const acertou = anim.hit && !anim.fumble;             // área conta como acerto
    if(anim.kind === 'item' && acertou){
      _projetilQuebrar(anim, now);
      obj.visible = false;                                // o sprite some; ficam partículas/anel
      anim.quebradoVisual = true;
    } else {
      if(anim.kind !== 'item' && !acertou){
        // Cravada ~35°: guinada pela direção do voo (não pelo Euler que o lookAt
        // deixou) e ponta para baixo. R_x(θ)·(0,0,1) = (0, −sinθ, cosθ), logo
        // θ>0 leva a ponta (+Z local) para −Y, o chão. Sinal validado no navegador (Task 7).
        const yaw = Math.atan2(anim.to[0] - anim.from[0], anim.to[1] - anim.from[1]);
        obj.rotation.set(0, yaw, 0); obj.rotateX(Math.PI * 0.19);
      }
      // Item que errou fica caído no chão (spec §5.3): para de girar e desvanece no stickMs.
      // Materiais próprios UMA vez: o clone() do Object3D compartilha os do base,
      // e o desvanecer abaixo não pode tocar neles (outros voos os reusam). O sprite
      // do item já nasce com material próprio (e o loader do PNG escreve nele):
      // só recebe o marcador, sem clonar.
      obj.traverse(o => {
        if(!o.material || o.material.userData._projOwned) return;
        if(!o.isSprite){ o.material = o.material.clone(); o.material.transparent = true; }
        o.material.userData._projOwned = true;
      });
    }
  }
  // Cravada/caída: some no fim do linger (seta acertada some junto com a reação).
  const p = Math.min(1, (now - anim.pousoAt) / Math.max(1, anim.lingerMs));
  if(!anim.quebradoVisual) obj.traverse(o => { if(o.material && o.material.userData._projOwned) o.material.opacity = 1 - p; });
  if(anim.ring){
    const q = Math.min(1, (now - anim.ring.start) / 400);
    anim.ring.mesh.scale.setScalar(1 + q * anim.ring.raio * 2.2);
    anim.ring.mesh.material.opacity = .8 * (1 - q);
  }
  anim.fim = (p >= 1) && (!anim.ring || now - anim.ring.start >= 400);
}

function _projetilDispose3D(anim){
  if(anim.obj){
    if(anim.obj.parent) anim.obj.parent.remove(anim.obj);
    anim.obj.traverse(o => {
      if(!o.material) return;
      if(o.isSprite){ if(o.material.map && o.material.map._owned) o.material.map.dispose(); o.material.dispose(); return; }
      if(o.material.userData && o.material.userData._projOwned) o.material.dispose();
    });
  }
  if(anim.ring && anim.ring.mesh){
    if(anim.ring.mesh.parent) anim.ring.mesh.parent.remove(anim.ring.mesh);
    anim.ring.mesh.geometry.dispose(); anim.ring.mesh.material.dispose();
  }
}

function _projetilTickTodos(now){
  for(let i = _projeteis.length - 1; i >= 0; i--){
    const anim = _projeteis[i];
    _projetilUpdate3D(anim, now);
    if(anim.fim){ _projetilDispose3D(anim); _projeteis.splice(i, 1); }
  }
}

function _projetilLimparTodos(){
  for(const anim of _projeteis) _projetilDispose3D(anim);
  _projeteis.length = 0;
  if(_projetilGeo){
    for(const k of ['arrow', 'bolt', 'spear']) _projetilGeo[k].traverse(o => { if(o.geometry) o.geometry.dispose(); });
    for(const m of _projetilGeo.mats) m.dispose();
    _projetilGeo = null;
  }
}

// Executa um comando devolvido por CombatScene.tick/handoff. O `impact` é o
// único que desenha: número flutuante, cue de dano, callbacks (anel/som de
// derrota) e partículas de crítico/morte.
function _executarComandoCena(c){
  if(!c) return;
  if(c.cmd === 'launch'){ _projetilLancar(c); return; }
  if(c.cmd === 'end'){
    // Cena que expirou sem golpear deixaria o banner legado imortal
    // (resultAt=Infinity nunca passa → o tick de _receiveAttackFeedback nunca
    // o descarta): destrava aqui, revelando o resultado.
    const fEnd = _attackFeedbacks.find(x => x.id === c.id);
    if(fEnd && fEnd.resultAt === Infinity){
      fEnd.resultAt = performance.now();
      _drawAttackFeedbackTexture3D(fEnd);
      if(fEnd.cueAdiado){ _playCombatCue(fEnd.cueAdiado.kind, fEnd.cueAdiado.opts); fEnd.cueAdiado = null; }
    }
    if(!c.death) return;
    // O fim do tombo é AUTORITATIVO para a cópia visual do monstro: a cena
    // já saiu da lista (poseFor → null) e o laço deste mesmo frame restauraria
    // o peão em pé, opaco — enquanto a cópia hp=1 seguiria em
    // _mortesVisuaisPendentes até o próximo poll (≤100 ms) ou o minAte.
    // Concluir agora apaga a cópia e re-renderiza de forma síncrona, então a
    // fig é descartada ANTES da travessia por fig (_tickCombatScene roda antes
    // do entityGroup.children.forEach em startLoop3D).
    // EXCEÇÃO: renderMap3D retorna cedo enquanto uma miniatura anda
    // (estadoMovimento/estadoMininoMov.emMovimento) — o reconcile ficaria para
    // o próximo render e a fig do morto ressuscitaria em pé neste frame. Por
    // isso a fig é escondida AGORA; o reconcile a descarta depois.
    const tk = typeof c.targetKey === 'string' ? c.targetKey : '';
    const figMorto = tk.startsWith('m:') ? getMonsterMesh(tk.slice(2))
                   : tk.startsWith('p:') ? getPeaoMesh(tk.slice(2))
                   : tk.startsWith('a:') ? getAnimadoMesh(tk.slice(2)) : null;
    if(figMorto) figMorto.visible = false;
    const mid = tk.startsWith('m:') ? tk.slice(2) : null;
    const rec = mid != null ? _mortesVisuaisPendentes.get(String(mid)) : null;
    if(rec && typeof rec.concluir === 'function'){
      if(rec.timer) clearTimeout(rec.timer);
      rec.minAte = 0; rec.aguardarMagia = false;
      rec.concluir();
    } else {
      _renderizarEstadoAtual();
    }
    return;
  }
  if(c.cmd !== 'impact') return;
  const now = performance.now();
  const tocouGolpe = !c.tardio && _somGolpe(c);
  if(!c.tardio) try{ _somExplosaoItem(c.item_id, c.targetPos, c.area || c.hit); _somAtaqueElemental(c); }catch(e){}
  if(!c.tardio){
    // O golpe aconteceu: agora o banner legado pode mostrar ACERTO/ERRO/CRÍTICO
    // e o cue de crítico/erro (adiado em _receiveAttackFeedback) toca junto.
    const f = _attackFeedbacks.find(x => x.id === c.id);
    if(f?.holyStrike && !Number.isFinite(f.holyStrikeAt)) f.holyStrikeAt=now;
    if(f && f.result && !(f.resultAt < now)){   // ainda não revelado (Infinity ou futuro)
      f.resultAt = now;
      _drawAttackFeedbackTexture3D(f);
      if(f.cueAdiado){ if(!tocouGolpe) _playCombatCue(f.cueAdiado.kind, f.cueAdiado.opts); f.cueAdiado = null; }
    }
  }
  const feedbacks = Array.isArray(c.feedbacks) ? c.feedbacks : [];
  for(const fb of feedbacks){
    if(!fb) continue;
    if(fb.cue && !_somDor(c, fb)) _playCombatCue('damage', fb.cue);
    _spawnCombatFeedback(fb.entry, fb.text, fb.kind, now, fb.damageType, fb.options || {});
  }
  for(const fn of (c.onImpact || [])){
    try{ fn(); }catch(e){ console.warn('combatScene onImpact:', e); }
  }
  // `tardio` = hand-off que chegou DEPOIS do golpe: o burst do crítico já saiu no comando do golpe; só a morte (informação nova) ainda merece partículas.
  if(g3 && c.hit && Array.isArray(c.targetPos) && ((c.crit && !c.tardio) || c.death)){
    const fb = feedbacks.find(f => f && f.damageType) || null;
    const tipo = fb ? _combatPrimaryDamageType(fb.damageType) : 'physical';
    const corHex = (_combatDamageTypeInfo(tipo).color || '#f4eee2').replace('#', '');
    _spawnBurstParticles(g3.T, g3.scene,
      { x: c.targetPos[0], y: 0.35, z: c.targetPos[1] },
      parseInt(corHex, 16), VC.feedback?.combat?.scene?.crit?.particles ?? 18);
  }
}

function _tickCombatScene(now){
  if(!window.CombatScene) return;
  for(const c of CombatScene.tick(now)) _executarComandoCena(c);
  if(_projeteis.length) _projetilTickTodos(now);
}

function _receiveAttackFeedback(msg){
  if(!msg || !msg.attack_id) return;
  _registrarHistoricoAtaque(msg);
  const id=String(msg.attack_id), now=performance.now();
  if(_cenaAtiva()){
    const base = {attack_id:id, attacker_key:_entityKeyById(msg.attacker_id), target_key:_entityKeyById(msg.target_id),
      attacker_pos:msg.attacker_pos, target_pos:msg.target_pos, projectile: msg.projectile || null, impacto: msg.impacto || null};
    if(msg.phase==='start') CombatScene.start(base, now);
    else if(msg.phase==='result') CombatScene.result({...base, hit:!!msg.hit, crit:!!msg.crit,
      natural_critical:!!msg.natural_critical, natural_fumble:!!msg.natural_fumble}, now);
  }
  if(msg.phase==='start'){
    if(msg.spin_id) _registrarGiroAtaque(msg, now);
    _playCombatCue('attack', {repeatKey:'attack', volume:.9});
    try{ _somRugidoAoAgir(msg.attacker_id); }catch(e){}
    const f={id, attackerName:msg.attacker_name||'Atacante', targetName:_attackFeedbackTargetName(msg),
      attackerId:msg.attacker_id, targetId:msg.target_id, attackName:msg.attack_name||t('ui.hud.ataque'), attackerPos:(msg.attacker_pos||[0,0]).map(Number),
      targetPos:(msg.target_pos||[0,0]).map(Number), advantageMode:msg.advantage_mode||'normal',
      holyStrike:!!msg.holy_strike, holyLevel:Math.max(1,Math.min(3,Number(msg.holy_level)||1)), holyType:msg.holy_type||'holy', holyStrikeAt:msg.holy_strike&&!_cenaAtiva()?now+_animationProgressDuration(ATTACK_FEEDBACK_PREP_MS):null,
      area:!!(msg.projectile && msg.projectile.area), impacto: msg.impacto || null,
      itemId: (msg.projectile && msg.projectile.item_id) || null,
      result:false, startedAt:now, resultAt:now,
      prepDuration:_animationProgressDuration(ATTACK_FEEDBACK_PREP_MS),
      resultDuration:_animationProgressDuration(ATTACK_FEEDBACK_RESULT_MS), group:null};
    _attackFeedbacks.push(f);
  }else if(msg.phase==='result'){
    const f=_attackFeedbacks.find(x=>x.id===id);
    if(!f) return;
    Object.assign(f,{result:true,resultAt:now+f.prepDuration,roll:msg.roll,total:msg.total,hit:!!msg.hit,crit:!!msg.crit,
      natural:msg.natural,natural_critical:!!msg.natural_critical,natural_fumble:!!msg.natural_fumble});
    const cue = (msg.natural_critical || msg.crit)
      ? {kind:'critical', opts:{repeatKey:'critical', power:msg.natural_critical ? 1.3 : 1.1, volume:1}}
      : (!msg.hit || msg.natural_fumble) ? {kind:'error', opts:{repeatKey:'error', volume:.82}} : null;
    if(_cenaAtiva() && CombatScene.phaseOf(id)){
      // Há cena para este ataque: o banner e o cue de crítico/erro esperam o
      // GOLPE (comando `impact` em _executarComandoCena), que é quando o
      // resultado deixa de ser spoiler. `end` destrava se a cena expirar.
      f.resultAt = Infinity;
      f.cueAdiado = cue;
    } else {
      // Sem cena (2D ou cena desligada): o golpe soa no resultado.
      const tocou = _somGolpe({ hit: !!msg.hit, crit: !!(msg.crit || msg.natural_critical),
        fumble: !!msg.natural_fumble, impacto: f.impacto, area: f.area,
        targetPos: msg.target_pos, targetKey: _entityKeyById(msg.target_id) });
      try{ _somAtaqueElemental({ attackerKey: _entityKeyById(msg.attacker_id), targetPos: msg.target_pos }); }catch(e){}
      try{ _somExplosaoItem(f.itemId, msg.target_pos, f.area || !!msg.hit); }catch(e){}   // 2D: granada/incendiário
      if(!tocou && cue) _playCombatCue(cue.kind, cue.opts);
    }
    _drawAttackFeedbackTexture3D(f);
  }
  if(mode3D && g3) _buildAttackFeedback3D(_attackFeedbacks[_attackFeedbacks.length-1]);
  if(!_attackFeedbackRaf){
    const tick=()=>{_attackFeedbackRaf=null; const n=performance.now();
      for(let i=_attackFeedbacks.length-1;i>=0;i--){const f=_attackFeedbacks[i];
        // Esperando o golpe mas a cena sumiu sem `end` (CombatScene.reset em dispose3D/troca 2D): revela, senão o banner nunca morre.
        if(f.resultAt===Infinity && !(window.CombatScene && CombatScene.phaseOf(f.id))){ f.resultAt=n; _drawAttackFeedbackTexture3D(f); f.cueAdiado=null; }
        const q=_attackFeedbackProgress(f,n);if(f.result&&q.done){_disposeAttackFeedback(f);_attackFeedbacks.splice(i,1);}}
      if(mode3D&&g3) _updateAttackFeedback3D(n);
      for(const f of _attackFeedbacks) _holyStrikeMaybeStartLevel3Ray(f,n);
      if(!mode3D&&GS.gameState) renderMap(GS.gameState);
      if(_attackFeedbacks.length) _attackFeedbackRaf=_scheduleVisualFrame(tick);
    }; _attackFeedbackRaf=_scheduleVisualFrame(tick);
  }
}

function _drawCombatFeedback2D(ctx, state, now){
  for(const f of _combatFeedbacks){
    if(!_combatFeedbackVisible(f, state)) continue;
    if(now < f.start) continue;
    const p = Math.max(0, Math.min(1, (now - f.start) / f.duration));
    const fade = p < 0.62 ? 1 : Math.max(0, 1 - (p - 0.62) / 0.38);
    const x = f.pos[0] * CELL + CELL/2;
    const y = f.pos[1] * CELL + CELL * (0.30 - 0.42*p);
    const fsBase = Math.max(15, CELL * 0.19);
    const fs = (f.kind === 'death'
      ? Math.max(15, CELL * 0.22)
      : fsBase * COMBAT_FEEDBACK_DAMAGE_FONT_SCALE
        * (f.critical ? (VC.feedback?.combat?.criticalFontScale ?? 1.32) : 1)) * _accessFontScale;
    ctx.save();
    ctx.globalAlpha = fade;
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.font = `900 ${fs}px Arial Black, sans-serif`;
    ctx.lineJoin = 'round'; ctx.lineWidth = Math.max(3, fs * 0.16);
    // Em casas nas extremidades do mapa, o centro do peão não deixa espaço
    // suficiente para a palavra inteira. Clampar o ponto de desenho mantém o
    // texto dentro do canvas sem alterar a posição dos demais feedbacks.
    const displayText = _combatFeedbackDisplayText(f);
    const textWidth = ctx.measureText(displayText).width;
    const textPad = Math.max(4, ctx.lineWidth) + 2;
    const halfW = textWidth / 2 + textPad;
    const halfH = fs / 2 + textPad;
    const drawX = ctx.canvas.width > halfW * 2
      ? Math.max(halfW, Math.min(ctx.canvas.width - halfW, x))
      : ctx.canvas.width / 2;
    const drawY = ctx.canvas.height > halfH * 2
      ? Math.max(halfH, Math.min(ctx.canvas.height - halfH, y))
      : ctx.canvas.height / 2;
    if(f.critical){
      ctx.shadowColor = _combatFeedbackColor(f.kind, f.damageType);
      ctx.shadowBlur = Math.max(8, fs * 0.22);
    }
    ctx.strokeStyle = 'rgba(8,4,12,0.92)'; ctx.strokeText(displayText, drawX, drawY);
    ctx.fillStyle = _combatFeedbackColor(f.kind, f.damageType); ctx.fillText(displayText, drawX, drawY);
    ctx.restore();
  }
}

function _drawResistanceFeedback2D(ctx, state, now){
  for(const f of _resistanceFeedbacks){
    if(!_resistanceFeedbackVisible(f, state)) continue;
    const p = Math.max(0, Math.min(1, (now - f.start) / f.duration));
    const alpha = p < 0.72 ? 1 : Math.max(0, 1 - (p - 0.72) / 0.28);
    const x = f.pos[0] * CELL + CELL/2;
    const y = f.pos[1] * CELL + CELL * (0.12 - 0.34*p);
    const line1 = `${f.icon} ${f.name} • ${f.type} • CD ${f.dc}`;
    const modText = f.modifier >= 0 ? `+ ${f.modifier}` : `− ${Math.abs(f.modifier)}`;
    const line2 = `d20 ${f.roll} ${modText} = ${f.total} — ${f.outcome}`;
    const fs = Math.max(11, CELL * 0.115) * _accessFontScale;
    ctx.save(); ctx.globalAlpha = alpha; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.font = `900 ${fs}px Arial Black, sans-serif`;
    const w = Math.max(ctx.measureText(line1).width, ctx.measureText(line2).width) + 14;
    const h = fs * 2.65;
    const drawX = Math.max(w/2, Math.min(ctx.canvas.width - w/2, x));
    const drawY = Math.max(h/2, Math.min(ctx.canvas.height - h/2, y));
    ctx.fillStyle = 'rgba(8,5,18,0.88)';
    ctx.strokeStyle = f.color; ctx.lineWidth = Math.max(1.5, fs * 0.10);
    ctx.beginPath(); ctx.roundRect(drawX - w/2, drawY - h/2, w, h, fs * .35); ctx.fill(); ctx.stroke();
    ctx.fillStyle = f.color; ctx.fillText(line1, drawX, drawY - fs*.52);
    ctx.fillStyle = f.failed ? '#ff7474' : '#fff1b0';
    ctx.fillText(line2, drawX, drawY + fs*.52);
    ctx.restore();
  }
}

function _drawConditionPulses2D(ctx, state, now){
  for(const p of _conditionPulses){
    if(!_resistanceFeedbackVisible(p, state)) continue;
    const q=Math.max(0,Math.min(1,(now-p.start)/p.duration));
    const alpha=q<.58?1:Math.max(0,1-(q-.58)/.42);
    const x=p.pos[0]*CELL+CELL/2, y=p.pos[1]*CELL+CELL*(0.18-0.58*q);
    ctx.save(); ctx.globalAlpha=alpha; ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.font=`${Math.max(18,CELL*.34)}px serif`;
    ctx.shadowColor='#fff0a0'; ctx.shadowBlur=10+8*Math.sin(q*Math.PI);
    ctx.fillText(p.icon,x,y); ctx.restore();
  }
}

function _pruneCombatFeedbacks(now){
  for(let i=_combatFeedbacks.length-1; i>=0; i--){
    const f = _combatFeedbacks[i];
    if(now - f.start < f.duration) continue;
    _disposeCombatFeedback3D(f);
    _combatFeedbacks.splice(i,1);
  }
}

function _requestCombatFeedbackFrame(untilAt){
  const now = performance.now();
  _combatVisualUntil = Math.max(
    _combatVisualUntil,
    Number.isFinite(untilAt) ? untilAt : now + COMBAT_FEEDBACK_DAMAGE_MS
  );
  if(_combatFeedbackRaf) return;
  const tick = () => {
    _combatFeedbackRaf = null;
    const now = performance.now();
    _pruneCombatFeedbacks(now);
    if(mode3D && g3) _updateCombatFeedback3D(now);
    else if(!mode3D && GS.gameState) renderMap(GS.gameState);
    if(_combatFeedbacks.length || now < _combatVisualUntil){
      _combatFeedbackRaf = _scheduleVisualFrame(tick);
    }
  };
  _combatFeedbackRaf = _scheduleVisualFrame(tick);
}

function _spawnCombatFeedback(entry, text, kind, startAt, damageType, options={}){
  if(!entry || !Array.isArray(entry.pos)) return;
  const visualStart = Number.isFinite(startAt) ? startAt : performance.now();
  const f = {
    pos: [Number(entry.pos[0]), Number(entry.pos[1])],
    text: String(text), kind: kind || 'damage',
    damageType: damageType ? _combatPrimaryDamageType(damageType) : null,
    status: options.status ? String(options.status) : '',
    critical: !!options.critical,
    start: visualStart,
    duration: _animationProgressDuration(kind === 'death' ? COMBAT_FEEDBACK_DEATH_MS : COMBAT_FEEDBACK_DAMAGE_MS),
    mesh: null,
  };
  _combatFeedbacks.push(f);
  if(mode3D && g3) _buildCombatFeedback3D(f);
  _requestCombatFeedbackFrame(visualStart + f.duration);
}

// Reação visual de impacto. A chave é a mesma usada pelo snapshot de HP
// (p:id, m:id, a:id, pr:singleton), permitindo que 2D e 3D reajam ao mesmo
// dano sem tocar na posição autoritativa recebida do servidor.
const _hitReactions = new Map();

function _triggerHitReaction(entry, critical=false, startAt=null){
  if(!entry || !entry.key) return;
  const cfg = VC.feedback?.combat?.hitReaction || {};
  const duration = _animationProgressDuration(Number(cfg.durationMs) || 190);
  const now = Number.isFinite(startAt) ? startAt : performance.now();
  const old = _hitReactions.get(entry.key);
  // Vários componentes de dano no mesmo estado renovam a reação, mas não
  // acumulam amplitude indefinidamente.
  const seed = old?.seed ?? ((String(entry.key).split('').reduce((n,ch)=>n+ch.charCodeAt(0),0) % 100) / 100) * Math.PI;
  _hitReactions.set(entry.key, {
    start: now,
    end: now + duration,
    seed,
    critical: !!critical || !!old?.critical,
  });
}

function _hitReaction2D(key, now=performance.now()){
  const r = _hitReactions.get(key);
  if(!r) return [0, 0];
  if(now < r.start) return [0, 0];
  if(now >= r.end){ _hitReactions.delete(key); return [0, 0]; }
  const cfg = VC.feedback?.combat?.hitReaction || {};
  const p = Math.max(0, Math.min(1, (now - r.start) / Math.max(1, r.end - r.start)));
  const envelope = Math.pow(1 - p, 1.15);
  const cycles = Number(cfg.cycles) || 2.7;
  const amp = (Number(cfg.amplitude2D) || 2.4) * (r.critical ? (Number(cfg.criticalScale) || 1.3) : 1);
  const wave = Math.sin((p * cycles * Math.PI * 2) + r.seed);
  // Movimento elíptico pequeno, evitando o aspecto de um simples deslocamento.
  return [wave * amp * envelope, Math.cos((p * cycles * Math.PI * 2) + r.seed) * amp * 0.42 * envelope];
}

function _hitReaction3DAngle(key, now=performance.now()){
  const r = _hitReactions.get(key);
  if(!r) return 0;
  if(now < r.start) return 0;
  if(now >= r.end){ _hitReactions.delete(key); return 0; }
  const cfg = VC.feedback?.combat?.hitReaction || {};
  const p = Math.max(0, Math.min(1, (now - r.start) / Math.max(1, r.end - r.start)));
  const envelope = Math.pow(1 - p, 1.15);
  const cycles = Number(cfg.cycles) || 2.7;
  const amp = (Number(cfg.angle3D) || 0.055) * (r.critical ? (Number(cfg.criticalScale) || 1.3) : 1);
  return Math.sin((p * cycles * Math.PI * 2) + r.seed) * amp * envelope;
}

function _combatHpRatio(key, target, maxHp){
  const max = Math.max(1, Number(maxHp) || 1);
  const wanted = Math.max(0, Math.min(1, Number(target) / max));
  let current = _combatHpVisual.get(key);
  if(current == null) current = wanted;
  else {
    current += (wanted - current) * 0.24;
    if(Math.abs(wanted - current) < 0.004) current = wanted;
  }
  _combatHpVisual.set(key, current);
  return current;
}

// Compara o HP de cada criatura entre game_states e dispara som + feedback.
// Cobre heróis, monstros, servos (animados) de cada jogador e o prisioneiro.
let _hpSnapshot = new Map();   // entityId -> hp do último game_state
let _hpEntitySnapshot = new Map();

function _gatherHpEntries(st){
  const out = [];
  if(!st) return out;
  (st.players  || []).forEach(p => { if(p && p.id != null) out.push({key:`p:${p.id}`, hp:p.hp, isMine:p.id === GS.myPid, pos:p.pos, kind:'hero'}); });
  (st.monsters || []).forEach(m => { if(m && m.id != null) out.push({key:`m:${m.id}`, hp:m.hp, isMine:false, pos:m.pos, kind:'monster'}); });
  (st.players  || []).forEach(p => (p && p.animados || []).forEach(a => {
    if(a && a.id != null) out.push({key:`a:${a.id}`, hp:(a.vida_atual != null ? a.vida_atual : a.hp), isMine:false, pos:a.pos, kind:'animado'});
  }));
  const pr = st.prisoner;                       // singleton — sem id próprio
  if(pr && pr.hp != null) out.push({key:'pr:singleton', hp:pr.hp, isMine:false, pos:pr.pos, kind:'prisoner'});
  return out;
}

// Retorna o instante em que o feedback visual de um alvo atingido por Bola de
// Fogo pode aparecer. O dano continua autoritativo e imediato no servidor;
// somente os números/"derrotado" aguardam o término da explosão visual.
function _bolaFogoFeedbackStartAt(entry){
  if(!entry || !Array.isArray(entry.pos)) return null;
  const px = Number(entry.pos[0]), py = Number(entry.pos[1]);
  if(!Number.isFinite(px) || !Number.isFinite(py)) return null;
  let liberarEm = null;
  for(const anim of _bolaFogoAnims){
    const atingido = _bolaFogoAreaTiles(anim).some(([x, y]) => x === px && y === py);
    if(!atingido) continue;
    const fimExplosao = anim.start + anim.travelMs + anim.explosionMs;
    liberarEm = liberarEm == null ? fimExplosao : Math.max(liberarEm, fimExplosao);
  }
  return liberarEm;
}

// Irmã do portão da bola de fogo para a Ira da Rocha Ardente: o game_state
// com o HP já descontado chega junto do `start`, mas a rocha ainda vai
// carregar e viajar; o número só sai quando a onda de lava alcança a casa
// (o mesmo `dist*105` que revela a fissura em _iraRochaUpdate3D/_iraRochaDraw2D).
function _iraRochaFeedbackStartAt(entry){
  if(!entry || !Array.isArray(entry.pos)) return null;
  const px = Number(entry.pos[0]), py = Number(entry.pos[1]);
  if(!Number.isFinite(px) || !Number.isFinite(py)) return null;
  let liberarEm = null;
  for(const anim of _iraRochaAnims){
    if(anim.isFlames || !anim.tiles.some(([x, y]) => x === px && y === py)) continue;
    const dist = Math.hypot(px - anim.center[0], py - anim.center[1]);
    const chegada = anim.start + anim.chargeMs + anim.travelMs + dist * 105;
    liberarEm = liberarEm == null ? chegada : Math.max(liberarEm, chegada);
  }
  return liberarEm;
}

// Prisão de Chamas: o dano de impacto (2d8 na borda, 2d4 no calor a ≤1 casa —
// inclusive o interior) chega no game_state junto do `start`; o número só sai
// quando o projétil chega às chamas.
function _prisaoChamasFeedbackStartAt(entry){
  if(!entry || !Array.isArray(entry.pos)) return null;
  const px = Number(entry.pos[0]), py = Number(entry.pos[1]);
  if(!Number.isFinite(px) || !Number.isFinite(py)) return null;
  let liberarEm = null;
  for(const anim of _prisaoChamasAnims){
    const chamas = anim.flames || anim.tiles || [];
    const perto = chamas.some(([x, y]) => Math.max(Math.abs(x - px), Math.abs(y - py)) <= 1);
    if(!perto) continue;
    const chegada = anim.start + anim.travelMs;
    liberarEm = liberarEm == null ? chegada : Math.max(liberarEm, chegada);
  }
  return liberarEm;
}

// Irmã do portão da bola de fogo: quem está no raio de um arremesso de ÁREA em
// voo só mostra o número quando o frasco chega (os saves rolam durante o voo).
// Consulta a CENA além da lista de render: o game_state com o dano chega na
// mesma rajada do start, ANTES de o laço 3D emitir o `launch` que povoa
// `_projeteis` — só a cena sabe estimar a chegada (windup + travelMs).
function _projetilFeedbackStartAt(entry){
  if(!entry || !Array.isArray(entry.pos)) return null;
  const px = Number(entry.pos[0]), py = Number(entry.pos[1]);
  if(!Number.isFinite(px) || !Number.isFinite(py)) return null;
  let liberarEm = null;
  for(const anim of _projeteis){
    if(!anim.area) continue;
    const d = Math.max(Math.abs(anim.to[0] - px), Math.abs(anim.to[1] - py));
    if(d > anim.area_raio) continue;
    liberarEm = liberarEm == null ? anim.impactAt : Math.max(liberarEm, anim.impactAt);
  }
  const daCena = (window.CombatScene && typeof CombatScene.areaImpactAt === 'function')
    ? CombatScene.areaImpactAt([px, py], performance.now()) : null;
  if(daCena != null) liberarEm = liberarEm == null ? daCena : Math.max(liberarEm, daCena);
  return liberarEm;
}

function _detectHpChanges(st){
  const entries = _gatherHpEntries(st);
  const now = performance.now();
  const changedDamageEntries = entries.filter(entry => {
    const prev = _hpSnapshot.get(entry.key);
    return prev != null && entry.hp != null && entry.hp < prev;
  });
  const multipleTargets = changedDamageEntries.length > 1;
  const damageTypesByKey = new Map();
  const damageEventsByKey = new Map();
  const positiveEventsByKey = new Map();
  for(const event of (st?.combat_damage_events || [])){
    const key = event?.entity_key;
    if(!key) continue;
    const events = damageEventsByKey.get(key) || [];
    events.push(event);
    damageEventsByKey.set(key, events);
    const types = Array.isArray(event.damage_types)
      ? event.damage_types
      : [event.damage_type || 'physical'];
    const bucket = damageTypesByKey.get(key) || [];
    for(const type of types){
      const normalized = _combatDamageTypeInfo(type).key;
      if(normalized && !bucket.includes(normalized)) bucket.push(normalized);
    }
    damageTypesByKey.set(key, bucket);
  }
  for(const event of (st?.positive_effect_events || [])){
    const key = event?.entity_key;
    if(!key) continue;
    const events = positiveEventsByKey.get(key) || [];
    events.push(event);
    positiveEventsByKey.set(key, events);
  }
  let heroHurt = false, creatureHurt = false, healed = false;
  let damageSequenceIndex = 0;
  for(const entry of entries){
    const {key, hp, isMine} = entry;
    if(hp == null) continue;
    const prev = _hpSnapshot.get(key);
    if(prev != null){
      if(hp < prev){
        if(isMine) heroHurt = true; else creatureHurt = true;
        const amount = Math.max(1, Math.round(prev - hp));
        const damageEvents = damageEventsByKey.get(key) || [];
        const primaryDamageType = _combatPrimaryDamageType(damageTypesByKey.get(key) || ['physical']);
        const cue = {
          damageType: primaryDamageType,
          repeatKey: `damage:${primaryDamageType}`,
          volume: isMine ? .95 : .72,
        };
        const statuses = [...new Set(damageEvents.map(e => String(e.status || '').trim()).filter(Boolean))];
        const impact = damageEvents.find(e => Array.isArray(e.pos))?.pos;
        // Hand-off: se há uma cena de ataque pendente para este alvo, ela é a
        // dona do instante do impacto — número, cue e reação saem no golpe,
        // sincronizados com o d20. Sem cena (magia, armadilha, veneno…), o
        // comportamento abaixo segue intocado.
        if(_cenaAtiva() && CombatScene.pendingFor(key, now)){
          const cmd = CombatScene.handoff(key, {
            feedback: {
              entry: impact ? {...entry, pos: impact} : entry,
              text: `${amount}`, kind: isMine ? 'hero_damage' : 'damage',
              damageType: damageTypesByKey.get(key) || 'physical',
              options: {status: statuses.join(' • '), critical: damageEvents.some(e => e.critical)},
              cue,
            },
            death: false, onImpact: [],
          }, now);
          if(cmd) _executarComandoCena(cmd);
          continue;
        }
        if(!_somDor({hit:true, targetKey:key, targetPos: impact || entry.pos}, {damageType: primaryDamageType})) _playCombatCue('damage', cue);
        const damageIndex = damageSequenceIndex++;
        const fireStartCandidatos = [
          _bolaFogoFeedbackStartAt(entry), _projetilFeedbackStartAt(entry), _iraRochaFeedbackStartAt(entry),
          _prisaoChamasFeedbackStartAt(entry),
        ].filter(v => v != null);
        const fireStart = fireStartCandidatos.length ? Math.max(...fireStartCandidatos) : null;
        const startAt = fireStart != null
          ? fireStart + (multipleTargets ? damageIndex * 120 : 0)
          : (multipleTargets ? now + damageIndex * 120 : null);
        _triggerHitReaction(entry, damageEvents.some(e => e.critical), startAt);
        _spawnCombatFeedback(
          impact ? {...entry, pos: impact} : entry, `${amount}`, isMine ? 'hero_damage' : 'damage',
          startAt,
          damageTypesByKey.get(key) || 'physical',
          {status: statuses.join(' • '), critical: damageEvents.some(e => e.critical)}
        );
      } else if(hp > prev){
        healed = true;
        const amount = Math.max(1, Math.round(hp - prev));
        const positiveEvents = positiveEventsByKey.get(key) || [];
        const regen = positiveEvents.some(e => e.kind === 'regeneration');
        const source = positiveEvents.find(e => e.source)?.source || '';
        const positiveLabel = regen ? t('ui.hud.regeneracao') : '';
        _spawnCombatFeedback(entry, `+${amount} HP`, 'heal', now, null,
          {status: positiveLabel});
        _spawnPositiveBurst(entry, regen ? 'regeneration' : 'heal', amount, source);
      } else {
        // Imunidade e absorção não alteram HP, mas ainda aparecem no ponto do
        // impacto para explicar por que nenhum dano foi perdido.
        const damageEvents = damageEventsByKey.get(key) || [];
        const statuses = [...new Set(damageEvents.map(e => String(e.status || '').trim()).filter(Boolean))];
        const zeroDamage = damageEvents.some(e => Number(e.amount || 0) <= 0);
        if(statuses.length && zeroDamage){
          const impact = damageEvents.find(e => Array.isArray(e.pos))?.pos;
          _spawnCombatFeedback(
            impact ? {...entry, pos: impact} : entry, statuses.join(' • '), 'damage',
            performance.now(), damageTypesByKey.get(key) || 'physical',
            {critical: damageEvents.some(e => e.critical)}
          );
        }
      }
    }
  }
  // Reconstrói o snapshot só com as criaturas vistas neste estado.
  _hpSnapshot = new Map(entries.filter(e => e.hp != null).map(e => [e.key, e.hp]));
  _hpEntitySnapshot = new Map(entries.filter(e => e.hp != null).map(e => [e.key, e]));
  // O cue tipado acima substitui o antigo som genérico por entidade: fogo,
  // frio, ácido, eletricidade e magia agora têm identidade própria; dano físico
  // continua com um impacto grave e curto.
  if(healed) playHeal();
  if(multipleTargets){
    const fireStarts = changedDamageEntries
      .map(e => Math.max(_bolaFogoFeedbackStartAt(e) ?? -Infinity, _iraRochaFeedbackStartAt(e) ?? -Infinity,
                         _prisaoChamasFeedbackStartAt(e) ?? -Infinity))
      .filter(v => Number.isFinite(v));
    const firstImpact = fireStarts.length ? Math.max(...fireStarts) : now + 180;
    // A confirmação só aparece depois da pequena cascata de impactos, para
    // não competir com o primeiro número de dano.
    const resumoAt = firstImpact + Math.max(0, changedDamageEntries.length - 1) * 120 + 90;
    setTimeout(() => toast(t('ui.hud.n_alvos_atingidos', {n: changedDamageEntries.length}), '#ffd45a'),
      Math.max(180, resumoAt - now));
  }
}

// ── Feedback de cura, escudos e buffs positivos ────────────────────────────
// Cura/regen usam o mesmo ponto de impacto do número verde. Escudos e bônus
// de CA disparam o mesmo tipo de partículas quando o estado autoritativo passa
// a conter o efeito.
const _positiveBursts = [];
let _positiveBurstRaf = null;
const _positiveEffectsSnapshot = new Map();
const _POSITIVE_EFFECT_IDS = new Set([
  'cancao_heroica','esconder_sombras','detectar_armadilhas','regeneracao_divina',
  'guerreiro_luz','golpe_sagrado','protetor','brutalidade','tecnica_mira_perfeita',
  'tecnica_investida','tecnica_ataque_coordenado','tecnica_sangue_frio',
  'tecnica_golpe_decisivo','tecnica_tatica_defensiva','tecnica_defesa_impecavel',
  'tecnica_passo_fantasma','tecnica_resistencia_absoluta','tecnica_contra_ataque',
  'mira_certeira','golpe_devastador','furia_berserker','aprimorar_magia',
  'estender_magia','fortalecer_magia','barreira_arcana','protecao_energia',
  'invisibilidade','visao_escuro','manto_escuridao','velocidade',
  'regeneracao_magica','contramagica','abencoar','abencoar_arma',
  'aumento_ca_temporario',
]);

function _positiveEffectKind(id){
  const s = String(id || '').toLowerCase();
  if(s.includes('regeneracao') || s.includes('regen')) return 'regeneration';
  if(s.includes('barreira') || s.includes('protecao') || s.includes('protetor') || s.includes('escudo')) return 'shield';
  if(s.includes('defesa') || s.includes('resistencia') || s.includes('guerreiro_luz')
      || s.includes('aumento_ca') || s === 'abencoar') return 'armor';
  return 'buff';
}

function _positiveEffectColor(kind){
  return kind === 'regeneration' ? '#91ffbd'
    : kind === 'shield' ? '#76d8ff'
    : kind === 'armor' ? '#ffd76b' : '#f4d98b';
}

function _spawnPositiveBurst(entry, kind='heal', amount=0, source=''){
  if(!entry || !Array.isArray(entry.pos)) return;
  const burst = {
    pos:[Number(entry.pos[0]), Number(entry.pos[1])], kind, amount:Number(amount)||0,
    source:String(source || ''), start:performance.now(), duration:_animationProgressDuration(920),
    group:null, ring:null, particles:[],
  };
  _positiveBursts.push(burst);
  if(mode3D && g3) _buildPositiveBurst3D(burst);
  _requestPositiveBurstFrame();
}

function _buildPositiveBurst3D(b){
  if(!g3?.scene || !window.THREE || b.group) return;
  const T = g3.T, group = new T.Group(); group.name = `positive-${b.kind}`;
  const color = Number(`0x${_positiveEffectColor(b.kind).slice(1)}`);
  const mat = new T.MeshBasicMaterial({color, transparent:true, opacity:0, depthWrite:false, depthTest:false, blending:T.AdditiveBlending});
  b.ring = new T.Mesh(new T.TorusGeometry(.22, .025, 8, 28), mat);
  b.ring.rotation.x = Math.PI / 2; b.ring.renderOrder = 126; group.add(b.ring);
  for(let i=0;i<11;i++){
    const pm = new T.MeshBasicMaterial({color, transparent:true, opacity:0, depthWrite:false, depthTest:false, blending:T.AdditiveBlending});
    const mote = new T.Mesh(new T.SphereGeometry(.025 + (i%3)*.010, 7, 5), pm);
    mote.userData.i = i; group.add(mote); b.particles.push(mote);
  }
  g3.scene.add(group); b.group = group;
}

function _disposePositiveBurst3D(b){
  if(!b?.group) return;
  if(b.group.parent) b.group.parent.remove(b.group);
  b.group.traverse(o => { if(o.geometry) o.geometry.dispose(); if(o.material) o.material.dispose(); });
  b.group = null;
}

function _updatePositiveBursts3D(now){
  if(!g3) return;
  for(const b of _positiveBursts){
    if(!b.group || b.group.parent !== g3.scene) _buildPositiveBurst3D(b);
    if(!b.group) continue;
    const q = Math.max(0, Math.min(1, (now - b.start) / b.duration));
    const fade = q < .55 ? 1 : Math.max(0, 1 - (q - .55) / .45);
    const x = b.pos[0], z = b.pos[1];
    b.ring.position.set(x, .34 + q * .12, z);
    b.ring.scale.setScalar(.7 + q * 1.45); b.ring.material.opacity = .72 * fade;
    for(const mote of b.particles){
      const i = mote.userData.i, a = i * Math.PI * 2 / b.particles.length;
      const radius = .08 + q * (.30 + (i%3)*.05);
      mote.position.set(x + Math.cos(a) * radius, .40 + q * (0.82 + (i%4)*.11), z + Math.sin(a) * radius);
      mote.material.opacity = (.60 + .25 * Math.sin(now / 120 + i) ** 2) * fade;
    }
  }
}

function _drawPositiveBursts2D(ctx, state, now){
  for(const b of _positiveBursts){
    if(!_combatFeedbackVisible({pos:b.pos}, state)) continue;
    const q = Math.max(0, Math.min(1, (now - b.start) / b.duration));
    const fade = q < .55 ? 1 : Math.max(0, 1 - (q - .55) / .45);
    const x = b.pos[0] * CELL + CELL/2, y = b.pos[1] * CELL + CELL/2;
    const color = _positiveEffectColor(b.kind);
    ctx.save(); ctx.globalAlpha = fade; ctx.globalCompositeOperation = 'lighter';
    ctx.strokeStyle = color; ctx.shadowColor = color; ctx.shadowBlur = CELL * .16;
    ctx.lineWidth = Math.max(2, CELL * .035); ctx.beginPath();
    ctx.arc(x, y, CELL * (.18 + q * .34), 0, Math.PI * 2); ctx.stroke();
    for(let i=0;i<9;i++){
      const a = i * Math.PI * 2 / 9;
      const px = x + Math.cos(a) * CELL * (.12 + q * .38);
      const py = y - q * CELL * (.70 + (i%3)*.10) + Math.sin(a) * CELL * (.10 + q*.08);
      ctx.fillStyle = color; ctx.beginPath(); ctx.arc(px, py, Math.max(1.5, CELL*.025), 0, Math.PI*2); ctx.fill();
    }
    const label = b.kind === 'regeneration' ? '🌿' : b.kind === 'shield' ? '🛡' : b.kind === 'armor' ? '⬆ CA' : '+';
    ctx.font = `900 ${Math.max(14, CELL * .19)}px Arial, sans-serif`;
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle'; ctx.fillStyle = color;
    ctx.fillText(label, x, y - CELL * (.42 + q * .56));
    ctx.restore();
  }
}

function _requestPositiveBurstFrame(){
  if(_positiveBurstRaf) return;
  const tick = () => {
    _positiveBurstRaf = null; const now = performance.now();
    for(let i=_positiveBursts.length-1;i>=0;i--){
      const b = _positiveBursts[i];
      if(now - b.start < b.duration) continue;
      _disposePositiveBurst3D(b); _positiveBursts.splice(i,1);
    }
    if(mode3D && g3) _updatePositiveBursts3D(now);
    else if(!mode3D && GS.gameState) renderMap(GS.gameState);
    if(_positiveBursts.length) _positiveBurstRaf = _scheduleVisualFrame(tick);
  };
  _positiveBurstRaf = _scheduleVisualFrame(tick);
}

function _capturarPositiveEffectChanges(state){
  const atual = new Map();
  for(const p of (state?.players || [])){
    if(!p || p.is_master || p.alive === false) continue;
    const efeitos = _coletarEfeitosAtivos(state, p, false)
      .filter(e => _POSITIVE_EFFECT_IDS.has(e.id));
    const agora = new Map(efeitos.map(e => [e.id, e]));
    atual.set(String(p.id), agora);
    const anterior = _positiveEffectsSnapshot.get(String(p.id));
    if(!anterior){ continue; }
    for(const [id, efeito] of agora){
      const velho = anterior.get(id);
      if(!velho){
        _spawnPositiveBurst({pos:p.pos}, _positiveEffectKind(id), 0, efeito.nome);
        toast(t('ui.hud.buff_aplicado', {nome: efeito.nome}), _positiveEffectColor(_positiveEffectKind(id)));
      } else if(Number(efeito.rodadas || 0) > Number(velho.rodadas || 0)){
        _spawnPositiveBurst({pos:p.pos}, _positiveEffectKind(id), 0, efeito.nome);
        toast(`Buff renovado: ${efeito.nome}`, _positiveEffectColor(_positiveEffectKind(id)));
      }
    }
    for(const [id, velho] of anterior){
      if(agora.has(id)) continue;
      const expirou = Number(velho.rodadas || 0) > 0;
      toast(`${efeitoNomeSeguro(velho)} ${expirou ? 'expirou' : t('ui.hud.foi_removido')}`, '#c8b89a');
    }
  }
  _positiveEffectsSnapshot.clear();
  for(const [id, efeitos] of atual) _positiveEffectsSnapshot.set(id, efeitos);
}

function efeitoNomeSeguro(efeito){ return efeito?.nome || efeito?.id || t('ui.hud.efeito_positivo'); }
function _limparPositiveEffectSnapshot(){ _positiveEffectsSnapshot.clear(); }

// ── Keep 2D canvas sized (used only for label overlay) ──────────────────────
function syncDiceCanvas(){
  const wrap=$('map-wrap'), panel=$('map-panel'), dc=$('dice-canvas');
  if(!wrap||!panel||!dc) return;
  const wr=wrap.getBoundingClientRect(), pr=panel.getBoundingClientRect();
  dc.style.top=(wr.top-pr.top)+'px'; dc.style.left='0px';
  const cssW=Math.floor(wr.width), cssH=Math.floor(wr.height);
  dc._cssW=cssW; dc._cssH=cssH;
  applyDPR(dc, cssW, cssH);
}

const _particleSystems = [];

function _spawnBurstParticles(T, scene, pos, color, n){
  const N = Math.max(1, n | 0);
  const posArr = new Float32Array(N * 3);
  const vels   = [];
  for(let i = 0; i < N; i++){
    posArr[i*3]   = pos.x + (Math.random()-.5)*0.3;
    posArr[i*3+1] = pos.y;
    posArr[i*3+2] = pos.z + (Math.random()-.5)*0.3;
    vels.push({ x:(Math.random()-.5)*1.2, y:1.6+Math.random()*2.0, z:(Math.random()-.5)*1.2 });
  }
  const pGeo = new T.BufferGeometry();
  pGeo.setAttribute('position', new T.BufferAttribute(posArr, 3));
  const pMat = new T.PointsMaterial({
    color, size:0.10,
    transparent:true, opacity:1.0,
    sizeAttenuation:true, depthWrite:false,
  });
  const pts = new T.Points(pGeo, pMat);
  scene.add(pts);
  _particleSystems.push({ pts, pGeo, pMat, vels, N, elapsed:0, duration:800 });
}

// Dourado do dado: começa logo acima da face superior.
function _spawnGoldParticles(T, scene, pos){
  _spawnBurstParticles(T, scene, { x:pos.x, y:pos.y + 0.45, z:pos.z }, 0xffd700, 20);
}

function _updateParticles(dt){
  if(!g3) return;
  const s = dt/1000;
  for(let i=_particleSystems.length-1; i>=0; i--){
    const ps = _particleSystems[i];
    ps.elapsed += dt;
    const t = Math.min(ps.elapsed/ps.duration, 1.0);
    ps.pMat.opacity = Math.max(0, 1.0 - t*t);
    const pa = ps.pGeo.attributes.position.array;
    for(let j=0; j<ps.N; j++){
      pa[j*3]   += ps.vels[j].x * s;
      pa[j*3+1] += ps.vels[j].y * s;
      pa[j*3+2] += ps.vels[j].z * s;
      ps.vels[j].y -= 2.5*s;   // gentle gravity
    }
    ps.pGeo.attributes.position.needsUpdate = true;
    if(t>=1.0){
      g3.scene.remove(ps.pts);
      ps.pGeo.dispose(); ps.pMat.dispose();
      _particleSystems.splice(i,1);
    }
  }
}

// Assigns UV coordinates to every triangle so the texture centroid (0.5, 0.5)
// maps exactly to the visual centre of each face — number always readable.
// BoxGeometry already has correct per-face UVs, so d6 skips this step.
function _assignPerFaceUV(T, geo){
  // Work on a non-indexed copy so every 3 verts = 1 triangle
  const ng = geo.index ? geo.toNonIndexed() : geo;
  const vCount = ng.attributes.position.count;
  const faceCount = Math.floor(vCount / 3);
  const uvs = new Float32Array(vCount * 2);
  // Equilateral-triangle UV layout with centroid exactly at (0.5, 0.5)
  //   centroid = ((0.10+0.90+0.50)/3, (0.37+0.37+0.76)/3) = (0.50, 0.50) ✓
  const TU = [[0.10,0.37],[0.90,0.37],[0.50,0.76]];
  for(let i=0; i<faceCount; i++){
    const b=i*6;
    uvs[b+0]=TU[0][0]; uvs[b+1]=TU[0][1];
    uvs[b+2]=TU[1][0]; uvs[b+3]=TU[1][1];
    uvs[b+4]=TU[2][0]; uvs[b+5]=TU[2][1];
  }
  ng.setAttribute('uv', new T.BufferAttribute(uvs, 2));
  return ng;
}

function _buildDieGeo(T, type){
  switch(type){
    case 'd4':  return _assignPerFaceUV(T, new T.TetrahedronGeometry(0.60, 0));
    case 'd6':  return new T.BoxGeometry(0.78, 0.78, 0.78);  // Box UVs already correct
    case 'd8':  return _assignPerFaceUV(T, new T.OctahedronGeometry(0.62, 0));
    case 'd10': return _assignPerFaceUV(T, _buildD10Geo(T));
    case 'd12': return _assignPerFaceUV(T, new T.DodecahedronGeometry(0.62, 0));
    case 'd20': return _assignPerFaceUV(T, new T.IcosahedronGeometry(0.62, 0));
    default:    return _assignPerFaceUV(T, new T.IcosahedronGeometry(0.62, 0));
  }
}

// D10 — pentagonal trapezohedron via manual BufferGeometry (10 kite faces)
function _buildD10Geo(T){
  const h=0.72, r=0.62, y1=0.22, y2=-0.22;
  const TOP=[0,h,0], BOT=[0,-h,0], up=[], lo=[];
  for(let i=0;i<5;i++){
    const a1=i*2*Math.PI/5-Math.PI/2, a2=a1+Math.PI/5;
    up.push([r*Math.cos(a1),y1,r*Math.sin(a1)]);
    lo.push([r*Math.cos(a2),y2,r*Math.sin(a2)]);
  }
  const pos=[], nor=[];
  function tri(a,b,c){
    const ex=b[0]-a[0],ey=b[1]-a[1],ez=b[2]-a[2];
    const fx=c[0]-a[0],fy=c[1]-a[1],fz=c[2]-a[2];
    let nx=ey*fz-ez*fy,ny=ez*fx-ex*fz,nz=ex*fy-ey*fx;
    const l=Math.hypot(nx,ny,nz)||1; nx/=l;ny/=l;nz/=l;
    pos.push(...a,...b,...c);
    nor.push(nx,ny,nz, nx,ny,nz, nx,ny,nz);
  }
  for(let i=0;i<5;i++){
    const i1=(i+1)%5, ip=(i+4)%5;
    tri(TOP,up[i],lo[i]);   tri(TOP,lo[i],up[i1]);   // upper kite (2 tris)
    tri(BOT,lo[ip],up[i]);  tri(BOT,up[i],lo[i]);    // lower kite (2 tris)
  }
  const geo=new T.BufferGeometry();
  geo.setAttribute('position',new T.BufferAttribute(new Float32Array(pos),3));
  geo.setAttribute('normal',  new T.BufferAttribute(new Float32Array(nor),3));
  geo.computeBoundingSphere();
  return geo;
}

// ── Face texture — 256×256, matte-plastic body + contrasting number ──────────
// Fill and outline follow the face brightness so graphite dice keep legible numerals.
function _dieFaceTex(T, value, hexColor, dieType){
  const SZ=256, half=128;
  const cv=document.createElement('canvas'); cv.width=cv.height=SZ;
  const c=cv.getContext('2d');

  // ── Fundo na cor sólida do dado ────────────────────────────────────────────
  c.fillStyle = hexColor;
  c.fillRect(0, 0, SZ, SZ);

  // Vignette sutil: centro levemente claro → bordas mais escuras.
  // Material unlit (Basic) não recebe sombreamento da cena, então este gradiente
  // é o que separa visualmente as faces e dá volume de "dado de resina real".
  const vg = c.createRadialGradient(half, half, SZ*0.12, half, half, SZ*0.72);
  vg.addColorStop(0,   'rgba(255,255,255,0.16)');
  vg.addColorStop(0.55,'rgba(0,0,0,0)');
  vg.addColorStop(1,   'rgba(0,0,0,0.34)');
  c.fillStyle = vg;
  c.fillRect(0, 0, SZ, SZ);

  const bw = VC.dice.borderWidth;
  c.strokeStyle = VC.dice.strokeColor;
  c.lineWidth   = bw;
  c.strokeRect(bw/2, bw/2, SZ-bw, SZ-bw);

  // ── Number — contrasting fill/outline ─────────────────────────────────────
  const numStr = String(value);
  const baseFz = VC.dice.numberFontSize;
  const faceScale = (VC.dice.faceFontScale || {})[dieType] || 1;
  const fs = Math.round((numStr.length > 1 ? baseFz * 110/130 : baseFz) * faceScale);
  c.textAlign    = 'center';
  c.textBaseline = 'middle';
  c.font    = `900 ${fs}px 'Arial Black', Arial, sans-serif`;
  c.lineJoin   = 'round';
  c.miterLimit = 2;
  const ink = _diceNumberInk(hexColor);

  // Stroke BEFORE fill so the outline sits under the fill
  c.strokeStyle = ink.stroke;
  c.lineWidth   = VC.dice.numberStroke;
  c.strokeText(numStr, half, half);
  c.fillStyle = ink.fill;
  c.fillText(numStr,   half, half);

  return new T.CanvasTexture(cv);
}

// ── D20 face texture — triangular face needs clip + smaller font + shifted Y ──
// IcosahedronGeometry maps each face as a triangle inscribed in UV space.
// Without clipping, a large font overflows the triangle edges.
// The visual centroid of the triangle is at y≈155, NOT y=128 (canvas midpoint).
function _dieFaceTexD20(T, value, hexColor){
  const SZ = 256, cx = 128;
  const cv = document.createElement('canvas'); cv.width = cv.height = SZ;
  const c  = cv.getContext('2d');

  // Solid background — same as all other faces
  c.fillStyle = hexColor;
  c.fillRect(0, 0, SZ, SZ);

  // Vignette sutil (mesma técnica de _dieFaceTex) — volume sem luz de cena
  const vg = c.createRadialGradient(cx, cx, SZ*0.12, cx, cx, SZ*0.72);
  vg.addColorStop(0,   'rgba(255,255,255,0.16)');
  vg.addColorStop(0.55,'rgba(0,0,0,0)');
  vg.addColorStop(1,   'rgba(0,0,0,0.34)');
  c.fillStyle = vg;
  c.fillRect(0, 0, SZ, SZ);

  // Clip everything to the triangle so no pixels bleed past the face edges
  c.save();
  const pts = VC.dice.d20.clipPts;
  c.beginPath();
  c.moveTo(pts[0][0], pts[0][1]);   // apex  (128, 20)
  c.lineTo(pts[1][0], pts[1][1]);   // right (236, 210)
  c.lineTo(pts[2][0], pts[2][1]);   // left  ( 20, 210)
  c.closePath();
  c.clip();

  const numStr = String(value);
  // 1-digit: 90px, 2-digit (10–20): 68px — both fit inside the triangle
  const fs = numStr.length === 1 ? VC.dice.d20.fontSz1 : VC.dice.d20.fontSz2;
  const numY = VC.dice.d20.numY;   // 155 — visual centroid of triangle

  c.textAlign    = 'center';
  c.textBaseline = 'middle';
  c.font    = `900 ${fs}px 'Arial Black', Arial, sans-serif`;
  c.lineJoin   = 'round';
  c.miterLimit = 2;
  const ink = _diceNumberInk(hexColor);

  // Contorno e preenchimento se adaptam para manter contraste em dados escuros.
  c.strokeStyle = ink.stroke;
  c.lineWidth   = 14;
  c.strokeText(numStr, cx, numY);
  c.fillStyle = ink.fill;
  c.fillText(numStr,   cx, numY);

  c.restore();
  return new T.CanvasTexture(cv);
}

// ── Resina física: luz revela as faces, verniz e relevo leve dos números ──────
// MeshPhysicalMaterial deixa os dados mais próximos de peças reais sem perder
// a leitura do resultado; o CanvasTexture preserva número e cor em cada face.
function _buildDieMat(T, value, hexColor, dieType){
  const faceTex = dieType === 'd20'
    ? _dieFaceTexD20(T, value, hexColor)
    : _dieFaceTex(T, value, hexColor, dieType);
  return new T.MeshPhysicalMaterial({
    color:             0xffffff,                    // white so map texture hue shows unmodified
    map:               faceTex,
    bumpMap:           faceTex,
    bumpScale:         0.030,
    // Emissão fraca da própria textura: destaca a resina contra a masmorra sem
    // apagar os números, pois as áreas de tinta preta também ficam escuras.
    emissive:          new T.Color(hexColor),
    emissiveMap:       faceTex,
    emissiveIntensity: 0.16,
    roughness:         0.26,
    metalness:         0.03,
    clearcoat:         0.46,
    clearcoatRoughness:0.20,
    // Entra na fila final de transparências com opacidade total. Assim os dados
    // são compostos depois das áreas de movimento/alcance e nunca recebem suas
    // cores por cima, mas continuam com aparência física de resina.
    transparent:       true,
    opacity:           1.0,
    depthTest:         false,                       // always renders on top of all board geometry
    depthWrite:        true,                        // writes depth so dice occlude each other
  });
}

/** Random float in [a, b) */
function _rr(a, b){ return a + Math.random()*(b-a); }

/**
 * Compute unique flat face normals from a BufferGeometry (local space).
 * Handles both indexed and non-indexed geometries.
 */
function _getFlatNormals(geo){
  // Work on a non-indexed copy so every 3 positions = 1 triangle
  const g = geo.index ? geo.toNonIndexed() : geo;
  const pos = g.attributes.position;
  const cnt = pos.count;
  const normals = [];
  for(let i = 0; i < cnt; i += 3){
    const ax=pos.getX(i),   ay=pos.getY(i),   az=pos.getZ(i);
    const bx=pos.getX(i+1), by=pos.getY(i+1), bz=pos.getZ(i+1);
    const cx=pos.getX(i+2), cy=pos.getY(i+2), cz=pos.getZ(i+2);
    // Edge vectors
    const e1x=bx-ax, e1y=by-ay, e1z=bz-az;
    const e2x=cx-ax, e2y=cy-ay, e2z=cz-az;
    // Cross product → face normal
    const nx=e1y*e2z-e1z*e2y, ny=e1z*e2x-e1x*e2z, nz=e1x*e2y-e1y*e2x;
    const len=Math.hypot(nx,ny,nz);
    if(len<1e-6) continue;
    const nx2=nx/len, ny2=ny/len, nz2=nz/len;
    // Deduplicate: skip if very close to an existing normal
    let found=false;
    for(const n of normals){
      if(n.x*nx2+n.y*ny2+n.z*nz2 > 0.99){ found=true; break; }
    }
    if(!found) normals.push({x:nx2, y:ny2, z:nz2});
  }
  return normals.map(n => ({...n, groupIndex:_faceGroupIndex(geo, n)}));
}

function _prepareDieFaceGroups(geo){
  const existing = geo.groups.slice();
  geo.clearGroups();
  if(existing.length) existing.forEach((g, i) => geo.addGroup(g.start, g.count, i));
  else {
    const count = geo.index ? geo.index.count : geo.attributes.position.count;
    for(let start=0, i=0; start<count; start+=3, i++) geo.addGroup(start, 3, i);
  }
}

function _faceGroupIndex(geo, normal){
  const pos=geo.attributes.position, index=geo.index;
  for(const group of geo.groups){
    const at=i => index ? index.getX(group.start+i) : group.start+i;
    const ia=at(0), ib=at(1), ic=at(2);
    const ax=pos.getX(ia), ay=pos.getY(ia), az=pos.getZ(ia);
    const bx=pos.getX(ib), by=pos.getY(ib), bz=pos.getZ(ib);
    const cx=pos.getX(ic), cy=pos.getY(ic), cz=pos.getZ(ic);
    const ex=bx-ax, ey=by-ay, ez=bz-az, fx=cx-ax, fy=cy-ay, fz=cz-az;
    const nx=ey*fz-ez*fy, ny=ez*fx-ex*fz, nz=ex*fy-ey*fx;
    const len=Math.hypot(nx,ny,nz) || 1;
    if((nx/len)*normal.x + (ny/len)*normal.y + (nz/len)*normal.z > 0.999)
      return group.materialIndex;
  }
  return 0;
}

/**
 * Return the quaternion that rotates the mesh so its face most aligned with
 * world-up points exactly upward.  Uses local-space face normals.
 */
function _snapRotation(T, mesh, faceLocalNormals){
  if(!faceLocalNormals || faceLocalNormals.length===0){
    return { quaternion:mesh.quaternion.clone(), groupIndex:0 };
  }
  const up  = new T.Vector3(0,1,0);
  const mQ  = mesh.quaternion;
  let bestDot=-2, bestLocal=null;
  for(const fn of faceLocalNormals){
    // Transform local face normal to world space with current mesh quaternion
    const fWorld = new T.Vector3(fn.x, fn.y, fn.z).applyQuaternion(mQ);
    const d = fWorld.dot(up);
    if(d > bestDot){ bestDot=d; bestLocal=fn; }
  }
  if(!bestLocal) return { quaternion:mQ.clone(), groupIndex:0 };
  // Quaternion that rotates local bestFace → world up
  const fromV = new T.Vector3(bestLocal.x, bestLocal.y, bestLocal.z);
  return { quaternion:new T.Quaternion().setFromUnitVectors(fromV, up), groupIndex:bestLocal.groupIndex };
}

function _randomDieFaceValue(dieType, avoid){
  const max = _dieMax(dieType);
  let value = 1 + Math.floor(Math.random() * max);
  if(max > 1 && value === avoid) value = (value % max) + 1;
  return value;
}

function _disposeDieMaterials(mats){
  for(const mat of mats || []){
    if(mat && mat.map) mat.map.dispose();
    if(mat) mat.dispose();
  }
}

function _makeD20TopBadge(T, value){
  const cv=document.createElement('canvas'); cv.width=cv.height=256;
  const c=cv.getContext('2d'), text=String(value);
  c.textAlign='center'; c.textBaseline='middle';
  c.font=`900 ${text.length>1 ? 122 : 152}px 'Arial Black', Arial, sans-serif`;
  c.lineJoin='round'; c.strokeStyle='#fff7d6'; c.lineWidth=24;
  c.strokeText(text,128,132); c.fillStyle='#080808'; c.fillText(text,128,132);
  const map=new T.CanvasTexture(cv);
  const mat=new T.MeshBasicMaterial({map, transparent:true, side:T.DoubleSide,
    depthTest:false, depthWrite:false});
  const geo=new T.PlaneGeometry(0.46,0.46);
  return { mesh:new T.Mesh(geo,mat), geo, mat };
}

function _disposeTopBadge(badge){
  if(!badge) return;
  if(badge.mat.map) badge.mat.map.dispose();
  badge.geo.dispose(); badge.mat.dispose();
}

const _tweens = [];

function _addTween(mesh, fromQ, toQ, duration, onDone){
  _tweens.push({ mesh, fromQ:fromQ.clone(), toQ:toQ.clone(), duration, elapsed:0, onDone });
}

function _updateTweens(dt){
  for(let i=_tweens.length-1; i>=0; i--){
    const tw = _tweens[i];
    tw.elapsed += dt;
    const t = Math.min(tw.elapsed/tw.duration, 1.0);
    const ease = t*t*(3-2*t);   // smooth-step
    tw.mesh.quaternion.slerpQuaternions(tw.fromQ, tw.toQ, ease);
    if(t>=1.0){
      tw.mesh.quaternion.copy(tw.toQ);
      if(tw.onDone) tw.onDone();
      _tweens.splice(i,1);
    }
  }
}

function _spawnDie3D(dieType, value, label, hexColor, flags, meta){
  if(!g3) return;                         // game scene must be active
  flags = flags || {};
  _setDiceDismissable(true);
  const T = window.THREE;

  // One-time: create diceGroup that travels with the camera centre.
  // Material dos dados é unlit (MeshBasicMaterial) — não precisa de PointLights
  // dedicadas (eram 2 luzes a mais na cena, custo por frame sem efeito visual).
  if(_d3 && !_d3._diceGroup){
    const diceGroup = new T.Group();
    // Luz focada e quente: dá leitura e reflexos de resina sem transformar
    // o próprio material em um efeito luminoso de videogame.
    const diceLight = new T.PointLight(0xfff0cf, 2.6, 7.0, 2.0);
    diceLight.position.set(0, 2.4, 1.2);
    diceGroup.add(diceLight);
    // Posição atualizada a cada frame pelo loop principal 3D (segue a câmera)
    g3.scene.add(diceGroup);
    _d3._diceGroup = diceGroup;
  }

  const geo  = _buildDieGeo(T, dieType);
  _prepareDieFaceGroups(geo);
  // Cada face começa como um dado normal, com valor próprio aleatório. Ao parar,
  // apenas a face voltada para cima é trocada pelo resultado do servidor.
  const mats = geo.groups.map(() =>
    _buildDieMat(T, _randomDieFaceValue(dieType, value), hexColor, dieType));
  const mesh = new T.Mesh(geo, mats);
  mesh.castShadow=true; mesh.receiveShadow=true;
  mesh.scale.setScalar(VC.dice.scale);   // 30% larger for better board visibility

  // Dados em espaço LOCAL do diceGroup (grupo reposicionado cada frame).
  // floorY=0 → chão local coincide com o plano de flutuação do grupo no mundo.
  const floorY = 0;
  const dieRad = 0.42 * VC.dice.scale;

  // Dispersão relativa ao centro do grupo (±1.5 tiles)
  const spawnX = _rr(-1.5, 1.5);
  const spawnZ = _rr(-1.5, 1.5);
  // Cai de 2.5 unidades acima do chão local
  mesh.position.set(spawnX, floorY + 2.5, spawnZ);
  mesh.rotation.set(_rr(0,Math.PI*2), _rr(0,Math.PI*2), _rr(0,Math.PI*2));

  const faceNormals = _getFlatNormals(geo);

  mesh.renderOrder = 10000; // sempre acima do tabuleiro e dos overlays de movimento
  _d3._diceGroup.add(mesh);   // filho do grupo — move junto com ele
  _dice3.push({
    mesh, geo, mats,
    vel:    { x:_rr(-1,1), y:-8, z:_rr(-1,1) },
    angVel: { x:_rr(-15,15), y:_rr(-15,15), z:_rr(-15,15) },
    floorY, dieRad,
    area: { x:0, z:0 },   // relativo ao grupo — scatter contido em ±3 tiles locais
    bounces:0, phase:'rolling', alpha:1.0, settleT:0,
    value, label, dieType, faceNormals, color:_hexCss(hexColor), meta: meta || {},
    discarded: !!flags.discarded, kept: !!flags.kept, offhand: !!flags.offhand,
  });

  playRollSound();
}

function _diceVisibleColors(){
  const used = new Set(_pendingDiceColors);
  for(const die of _dice3) used.add(String(die.color || _hexCss(die.hexColor || DIE_COLORS[die.dieType])).toLowerCase());
  for(const die of _dice2) used.add(String(die.color).toLowerCase());
  return used;
}

function _nextDiceColor(dieType, msg){
  // Estados de vantagem/desvantagem e mão secundária mantêm semântica própria,
  // mas recebem variações para não repetir uma cor que ainda está em cena.
  // Regeneração tem uma identidade visual própria, independente do tipo físico
  // do dado (a Maré Viva é 1d6, mas não deve herdar o vermelho padrão do d6).
  const damageType = _diceDamageType(msg);
  const themeFallback = msg.dice_theme === 'regeneration'
    ? ['#27ae60','#2ecc71','#168a4b','#58d68d']
    : msg.dice_theme === 'sneak_attack'
      ? ['#ff1744','#e60033','#c11236','#a4133c','#800f2f','#5a0c2e'] : null;
  const semantic = DIE_THEME_COLOR_VARIANTS[msg.dice_theme] || themeFallback
    || (msg.discarded ? ['#c0392b','#e74c3c','#922b21','#ff6b6b']
    : msg.kept ? ['#27ae60','#2ecc71','#168a4b','#58d68d']
    : msg.offhand ? ['#e67e22','#f39c12','#d35400','#ffb347']
    : damageType ? (DIE_DAMAGE_COLOR_VARIANTS[damageType] || [])
    : (DIE_COLOR_VARIANTS[dieType] || [DIE_COLORS[dieType] || VC.dice.colors.d20]));
  const used = _diceVisibleColors();
  let color = semantic.find(c => !used.has(c.toLowerCase()));
  // Em uma rajada excepcional com mais dados que a paleta, cria outra tonalidade
  // ainda não usada. Assim uma nova jogada nunca reutiliza a cor de peça visível.
  if(!color){
    const themeHue = msg.dice_theme === 'sneak_attack' ? 348 : null;
    if(damageType || themeHue != null){
      const hue = themeHue ?? ({physical:220,fire:0,cold:208,acid:112,poison:278,lightning:51,holy:43})[damageType] ?? 25;
      const bloodTheme = msg.dice_theme === 'sneak_attack';
      for(let i=1; i<=48 && !color; i++){
        const lightness = bloodTheme ? 28 + (i % 7) * 7
          : damageType === 'physical' ? 16 + (i % 7) * 5 : 34 + (i % 7) * 7;
        const saturation = bloodTheme ? 82 : damageType === 'physical' ? 9 + (i % 4) * 4 : 76;
        const candidate = `hsl(${hue}, ${saturation}%, ${lightness}%)`;
        if(!used.has(candidate.toLowerCase())) color = candidate;
      }
    }
  }
  if(!color){
    const baseHue = ({d4:48,d6:0,d8:218,d10:145,d12:285,d20:25})[dieType] || 25;
    for(let i=1; i<=36 && !color; i++){
      const candidate = `hsl(${(baseHue + (used.size+i)*31) % 360}, 78%, 54%)`;
      if(!used.has(candidate.toLowerCase())) color = candidate;
    }
  }
  color = color || semantic[0];
  _pendingDiceColors.add(color.toLowerCase());
  return color;
}

function _diceDamageType(msg){
  const raw = msg?.damage_type ?? msg?.damageType
    ?? (Array.isArray(msg?.damage_types) ? _combatPrimaryDamageType(msg.damage_types) : '');
  if(!raw) return null;
  const key = _combatDamageTypeInfo(raw).key;
  return Object.prototype.hasOwnProperty.call(DIE_DAMAGE_COLOR_VARIANTS, key) ? key : null;
}

function _diceIsDarkColor(color){
  const value = String(color || '').trim();
  const hex = value.match(/^#([0-9a-f]{6})$/i);
  let r, g, b;
  if(hex){
    const n=parseInt(hex[1],16);r=(n>>16)&255;g=(n>>8)&255;b=n&255;
  }else{
    const hsl=value.match(/^hsl\(\s*([\d.-]+),\s*([\d.]+)%?,\s*([\d.]+)%?\s*\)$/i);
    if(!hsl) return false;
    const h=((Number(hsl[1])%360)+360)%360,s=Math.max(0,Math.min(1,Number(hsl[2])/100)),l=Math.max(0,Math.min(1,Number(hsl[3])/100));
    const f=n=>{const k=(n+h/30)%12,a=s*Math.min(l,1-l);return (l-a*Math.max(-1,Math.min(k-3,9-k,1)))*255;};
    r=f(0);g=f(8);b=f(4);
  }
  return (0.2126*r + 0.7152*g + 0.0722*b) < 132;
}

function _diceNumberInk(color){
  const dark = _diceIsDarkColor(color);
  return {
    fill: dark ? (VC.dice.darkFaceNumberColor || '#fffdf5') : VC.dice.numberColor,
    stroke: dark ? (VC.dice.darkFaceNumberStrokeColor || '#17191d') : VC.dice.strokeColor,
  };
}

function _diceLabelInk(color){
  return _diceIsDarkColor(color) ? (VC.dice.darkFaceNumberColor || '#fffdf5') : color;
}

// Metadados opcionais enviados pelo servidor. O dado continua sendo desenhado
// mesmo quando uma ação antiga ainda não fornece modificador/total.
function _diceFormula(msg, dieType){
  if(msg && msg.formula) return String(msg.formula);
  const value = Number(msg?.value);
  const modifier = Number(msg?.modifier);
  const total = Number(msg?.total);
  if(!Number.isFinite(value) || !Number.isFinite(modifier) || !Number.isFinite(total)) return '';
  const sign = modifier >= 0 ? '+' : '−';
  return `${msg?.expression || msg?.die || dieType} ${value} ${sign} ${Math.abs(modifier)} = ${total}`;
}

function _diceRollMeta(msg, dieType, label, flags){
  const formula = _diceFormula(msg, dieType);
  const status = flags.discarded ? t('ui.hud.descartado')
    : flags.kept ? t('ui.hud.escolhido')
    : flags.offhand ? t('ui.hud.mao_secundaria') : '';
  const context = [label, status].filter(Boolean).join(' • ');
  return { formula, status, context,
    modifier: Number.isFinite(Number(msg?.modifier)) ? Number(msg.modifier) : null,
    total: Number.isFinite(Number(msg?.total)) ? Number(msg.total) : null };
}

let _diceDismissHandlersReady = false;
function _ensureDiceDismissHandlers(){
  const dc = $('dice-canvas');
  if(!_diceDismissHandlersReady){
    document.addEventListener('keydown', e => {
      if(e.key !== 'Escape') return;
      const visible = _pendingDiceRollTimers.size || _dice2.length || _dice3.length;
      if(!visible) return;
      _clearDiceVisuals();
      e.preventDefault();
      e.stopPropagation();
    }, true);
    _diceDismissHandlersReady = true;
  }
  if(dc && !dc.dataset.dismissReady){
    dc.addEventListener('click', () => _clearDiceVisuals());
    dc.dataset.dismissReady = '1';
  }
}

function _setDiceDismissable(active){
  const dc = $('dice-canvas');
  if(!dc) return;
  dc.classList.toggle('dice-dismissable', !!active);
  dc.style.pointerEvents = active ? 'auto' : 'none';
}

function handleDiceRoll(msg){
  _ensureDiceDismissHandlers();
  const now = performance.now();
  // Vários dados emitidos em sequência pertencem à mesma ação. Quando a
  // janela termina, o próximo dado inicia um lançamento novo e limpa os
  // resultados antigos da mesa.
  if(now - _lastDiceRollAt > DICE_ROLL_BURST_MS) _clearDiceVisuals();
  _lastDiceRollAt = now;
  const dieType = String(msg.die || 'd20').toLowerCase().match(/d(?:4|6|8|10|12|20)/)?.[0] || 'd20';
  // Inclui os dados que ainda aguardam o timeout: várias mensagens de dano
  // podem chegar no mesmo frame (arma + Golpe Sagrado + d8 elemental). Sem
  // contar os pendentes, todas recebem delay zero e acabam sobrepostas.
  const dadosEmCena = _dice3.length + _dice2.length;
  const dadosPendentes = _pendingDiceRollTimers.size;
  const delay = (dadosEmCena + dadosPendentes) * (80 + Math.random()*70);
  // Cores especiais p/ dado de desvantagem (Provocação) e off-hand (dual-wield),
  // para o jogador distinguir os 3 cenários visualmente:
  //   • Descartado (vermelho)  : 2º dado da desvantagem que NÃO valeu
  //   • Mantido (verde)        : dado da desvantagem que ficou (o pior)
  //   • Off-hand (laranja)     : dado da mão secundária (dual-wield Henrique)
  //   • Normal (padrão)        : dourado/azul conforme o tipo do dado
  const hexColor = _nextDiceColor(dieType, msg);

  const flags = { discarded: !!msg.discarded, kept: !!msg.kept, offhand: !!msg.offhand };
  const label = msg.label || dieType;
  const meta = _diceRollMeta(msg, dieType, label, flags);
  const timer = setTimeout(()=>{
    _pendingDiceRollTimers.delete(timer);
    _pendingDiceColors.delete(_hexCss(hexColor).toLowerCase());
    // Decide 3D vs 2D no MOMENTO do spawn (o jogador pode alternar a visão).
    // Antes: sem cena 3D ativa o dado simplesmente não aparecia (só o número
    // na narração do Mestre) — agora a visão 2D tem dados animados próprios.
    if(mode3D && g3){
      if(!_d3) _d3 = { animFrame:null, _cfr:0 };
      _spawnDie3D(dieType, msg.value, label, hexColor, flags, meta);
    } else {
      _spawnDie2D(dieType, msg.value, label, hexColor, flags, meta);
    }
  }, delay);
  _pendingDiceRollTimers.add(timer);
}

// ══ 2D DICE — dados animados sobre o dice-canvas na visão 2D ═════════════════
// Mesma identidade visual dos dados 3D: cor vibrante por tipo, número preto
// com contorno branco, vignette de volume, label dourado/colorido, som de
// rolagem. Física simples top-down: deslizam com atrito, quicam nas bordas,
// param mostrando o resultado real, somem após 3 s.
const _dice2 = [];
let _d2Frame = null;
const _pendingDiceRollTimers = new Set();
let _lastDiceRollAt = -Infinity;
// Mensagens da mesma ação chegam praticamente juntas; uma nova sequência
// depois desta janela limpa imediatamente o resultado anterior.
const DICE_ROLL_BURST_MS = 220;

function _clearDiceVisuals(){
  for(const timer of _pendingDiceRollTimers) clearTimeout(timer);
  _pendingDiceRollTimers.clear();
  _pendingDiceColors.clear();

  if(_d2Frame){ _cancelVisualFrame(_d2Frame); _d2Frame = null; }
  _dice2.length = 0;
  _setDiceDismissable(false);
  const dc = $('dice-canvas');
  if(dc){
    const ctx = dc.getContext('2d');
    if(ctx){ ctx.setTransform(1,0,0,1,0,0); ctx.clearRect(0,0,dc.width,dc.height); }
  }

  if(_d3){
    if(_d3.animFrame) cancelAnimationFrame(_d3.animFrame);
    _d3.animFrame = null;
    _d3._lastT = 0;
    const diceMeshes = new Set(_dice3.map(d => d.mesh));
    for(let i=_tweens.length-1; i>=0; i--)
      if(diceMeshes.has(_tweens[i].mesh)) _tweens.splice(i,1);
    for(const die of _dice3){
      // d20 descartado no ar (rolling/snapping — nunca assentou): a cena de
      // combate que esperava ESTE dado ficaria em ESPERANDO_DADO até o
      // waitDieMs; libera-a agora, como se o dado tivesse assentado.
      if(die.dieType === 'd20' && die.phase !== 'settling' && die.phase !== 'fading' && window.CombatScene)
        CombatScene.dieSettled({die:'d20', value: die.value}, performance.now());
      if(_d3._diceGroup) _d3._diceGroup.remove(die.mesh);
      _disposeDieMaterials(die.mats);
      _disposeTopBadge(die.topBadge);
      die.geo.dispose();
    }
  }
  _dice3.length = 0;
  if(typeof _drawDiceLabels === 'function') _drawDiceLabels();
}

function _hexCss(h){
  return typeof h === 'string' ? h : '#' + h.toString(16).padStart(6, '0');
}

function _dieMax(t){ return ({d4:4, d6:6, d8:8, d10:10, d12:12, d20:20})[t] || 20; }

function _spawnDie2D(dieType, value, label, hexColor, flags, meta){
  syncDiceCanvas();   // garante tamanho/posição corretos do overlay
  const dc = $('dice-canvas');
  if(!dc) return;
  const W = dc._cssW || dc.clientWidth, H = dc._cssH || dc.clientHeight;
  if(!W || !H) return;
  _setDiceDismissable(true);
  const R = Math.max(26, Math.min(40, Math.min(W, H) * 0.055));
  _dice2.push({
    dieType, value, label, flags: flags || {}, meta: meta || {},
    color: _hexCss(hexColor),
    x: W * (VC.dice.screenAnchor?.x ?? 0.72)
      + _rr(-W * (VC.dice.screenScatter?.x ?? 0.10), W * (VC.dice.screenScatter?.x ?? 0.10)),
    y: H * (VC.dice.screenAnchor?.y ?? 0.68)
      + _rr(-H * (VC.dice.screenScatter?.y ?? 0.07), H * (VC.dice.screenScatter?.y ?? 0.07)),
    vx: _rr(-300, 300), vy: _rr(140, 340),
    rot: _rr(0, Math.PI * 2), vrot: _rr(-9, 9),
    R, t: 0, rollT: _rr(750, 1050),
    phase: 'rolling', alpha: 1, settleT: 0,
  });
  playRollSound();
  if(!_d2Frame) _startDiceLoop2D();
}

function _tickDie2(d, dt, W, H){
  if(d.phase === 'fading'){ d.alpha = Math.max(0, d.alpha - dt/_animationProgressDuration(VC.dice.fadeMs ?? 350)); return; }
  if(d.phase === 'settling'){
    d.settleT += dt;
    // endireita o dado suavemente para o resultado ficar legível
    d.vrot = 0;
    d.rot *= Math.pow(0.0035, dt/1000);
    if(d.settleT > _animationProgressDuration(VC.dice.settleMs ?? 1500)) d.phase = 'fading';
    return;
  }
  d.t += dt;
  const s = dt/1000;
  d.x += d.vx * s;  d.y += d.vy * s;  d.rot += d.vrot * s;
  const fr = Math.pow(0.16, s);            // atrito forte — para em ~1 s
  d.vx *= fr;  d.vy *= fr;  d.vrot *= Math.pow(0.28, s);
  const pad = d.R + 8;
  if(d.x < pad)     { d.x = pad;     d.vx =  Math.abs(d.vx) * 0.8; playImpact(0.5); }
  if(d.x > W - pad) { d.x = W - pad; d.vx = -Math.abs(d.vx) * 0.8; playImpact(0.5); }
  if(d.y < pad)     { d.y = pad;     d.vy =  Math.abs(d.vy) * 0.8; playImpact(0.5); }
  if(d.y > H - pad) { d.y = H - pad; d.vy = -Math.abs(d.vy) * 0.8; playImpact(0.5); }
  // normaliza rot para [-π, π] para o endireitamento girar pelo caminho curto
  if(d.t > d.rollT){
    d.rot = ((d.rot + Math.PI) % (Math.PI*2) + Math.PI*2) % (Math.PI*2) - Math.PI;
    d.phase = 'settling';
    playImpact(0.85);
  }
}

// Silhueta 2D por tipo de dado (triângulo, quadrado, losango, pentágono, hexágono)
function _dieShapePath2D(ctx, type, R){
  ctx.beginPath();
  const poly = (n) => {
    for(let i = 0; i < n; i++){
      const a = -Math.PI/2 + i * 2 * Math.PI / n;
      const px = R * Math.cos(a), py = R * Math.sin(a);
      i ? ctx.lineTo(px, py) : ctx.moveTo(px, py);
    }
    ctx.closePath();
  };
  switch(type){
    case 'd4':  poly(3); break;
    case 'd6': {            // quadrado de cantos arredondados
      const r = R * 0.84, rd = r * 0.26;
      ctx.moveTo(-r + rd, -r);
      ctx.arcTo( r, -r,  r,  r, rd);
      ctx.arcTo( r,  r, -r,  r, rd);
      ctx.arcTo(-r,  r, -r, -r, rd);
      ctx.arcTo(-r, -r,  r, -r, rd);
      ctx.closePath(); break;
    }
    case 'd8':
    case 'd10': poly(4); break;   // losango
    case 'd12': poly(5); break;
    case 'd20':
    default:    poly(6); break;
  }
}

function _drawDie2D(ctx, d){
  const { R } = d;
  ctx.save();
  ctx.globalAlpha = d.alpha;
  ctx.translate(d.x, d.y);

  // sombra blob no "chão" (sem rotação)
  ctx.fillStyle = 'rgba(0,0,0,0.32)';
  ctx.beginPath();
  ctx.ellipse(3, R * 0.82, R * 0.95, R * 0.36, 0, 0, Math.PI * 2);
  ctx.fill();

  ctx.rotate(d.rot);

  // corpo na cor vibrante do dado + vignette de volume + borda branca
  _dieShapePath2D(ctx, d.dieType, R);
  ctx.fillStyle = d.color;
  ctx.fill();
  const vg = ctx.createRadialGradient(0, 0, R * 0.15, 0, 0, R);
  vg.addColorStop(0,    'rgba(255,255,255,0.22)');
  vg.addColorStop(0.60, 'rgba(0,0,0,0)');
  vg.addColorStop(1,    'rgba(0,0,0,0.38)');
  _dieShapePath2D(ctx, d.dieType, R);
  ctx.fillStyle = vg;
  ctx.fill();
  _dieShapePath2D(ctx, d.dieType, R);
  ctx.lineWidth = 3;
  ctx.strokeStyle = '#FFFFFF';
  ctx.stroke();

  // número: cicla aleatório enquanto rola; resultado real ao parar
  const numStr = d.phase === 'rolling'
    ? String(1 + Math.floor(Math.random() * _dieMax(d.dieType)))
    : String(d.value);
  const faceScale = (VC.dice.faceFontScale || {})[d.dieType] || 1;
  const fs = Math.round(R * (numStr.length > 1 ? 0.66 : 0.85) * faceScale);
  ctx.font = `bold ${fs}px 'Arial Black', Arial, sans-serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.lineJoin = 'round';
  ctx.miterLimit = 2;
  const ny = d.dieType === 'd4' ? R * 0.18 : 0;   // centróide do triângulo é mais baixo
  const ink = _diceNumberInk(d.color);
  ctx.strokeStyle = ink.stroke;
  ctx.lineWidth = 5;
  ctx.strokeText(numStr, 0, ny);
  ctx.fillStyle = ink.fill;
  ctx.fillText(numStr, 0, ny);
  ctx.restore();

  // Halo discreto: verde destaca o d20 escolhido; vermelho/cinza mantém o
  // descartado visível para que a vantagem/desvantagem fique compreensível.
  if(d.flags?.kept || d.flags?.discarded){
    ctx.save();
    ctx.globalAlpha = Math.min(1, d.alpha) * (d.flags.kept ? 0.95 : 0.65);
    ctx.beginPath(); ctx.arc(d.x, d.y, d.R + 5, 0, Math.PI * 2);
    ctx.lineWidth = d.flags.kept ? 3 : 2;
    ctx.setLineDash(d.flags.kept ? [] : [5, 4]);
    ctx.strokeStyle = d.flags.kept ? '#6cff9b' : '#ff7a70';
    ctx.stroke(); ctx.restore();
  }

  // label acima do dado (sem rotação) — acompanha a variação da peça física
  if((d.label || d.meta?.formula) && d.phase !== 'rolling'){
    ctx.save();
    ctx.globalAlpha = Math.min(1, d.alpha) * 0.9;
    const color = _diceLabelInk(d.color || '#e8d180');
    const formula = d.meta?.formula || `${d.dieType} ${d.value}`;
    const context = d.meta?.context || d.label;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'bottom';
    ctx.font = `bold ${VC.dice.formulaFontSize || 14}px 'Cinzel', serif`;
    ctx.fillStyle = 'rgba(0,0,0,0.85)';
    ctx.fillText(formula, d.x + 1, d.y - d.R - 7 + 1);
    ctx.fillStyle = color;
    ctx.fillText(formula, d.x, d.y - d.R - 7);
    if(context){
      ctx.font = `bold ${VC.dice.statusFontSize || 10}px 'Cinzel', serif`;
      ctx.fillStyle = d.flags?.discarded ? '#ff9b91' : d.flags?.kept ? '#8dffb1' : '#f0d58b';
      ctx.fillText(context, d.x, d.y - d.R - 21);
    }
    ctx.restore();
  }
}

function _startDiceLoop2D(){
  const dc = $('dice-canvas');
  if(!dc) return;
  let last = performance.now();
  function frame(now){
    const dt = Math.min(now - last, 50); last = now;
    const ctx = dc.getContext('2d');
    const W = dc._cssW || dc.clientWidth, H = dc._cssH || dc.clientHeight;
    const dpr = window.devicePixelRatio || 1;
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.clearRect(0, 0, dc.width, dc.height);
    ctx.save();
    ctx.scale(dpr, dpr);
    for(let i = _dice2.length - 1; i >= 0; i--){
      const d = _dice2[i];
      _tickDie2(d, dt, W, H);
      if(d.alpha <= 0.01){ _dice2.splice(i, 1); continue; }
      _drawDie2D(ctx, d);
    }
    ctx.restore();
    if(_dice2.length){
      _d2Frame = _scheduleVisualFrame(frame);
    } else {
      _d2Frame = null;
      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.clearRect(0, 0, dc.width, dc.height);
    }
  }
  _d2Frame = _scheduleVisualFrame(frame);
}

// ── Per-frame die physics — Euler rotation, 60fps-normalised ─────────────────
function _tickDie3(obj, dt){
  const {mesh} = obj;

  // ── Fading out (0.5 s) ──
  if(obj.phase==='fading'){
    obj.alpha = Math.max(0, obj.alpha - dt/_animationProgressDuration(VC.dice.fadeMs ?? 350));
    for(const mat of obj.mats){ mat.opacity=obj.alpha; mat.transparent=true; }
    if(obj.topBadge) obj.topBadge.mat.opacity=obj.alpha;
    return;
  }
  // ── Resting on board for 3 s, then fade ──
  if(obj.phase==='settling'){
    obj.settleT+=dt;
    if(obj.settleT>_animationProgressDuration(VC.dice.settleMs ?? 1500)) obj.phase='fading';
    return;
  }
  // ── Waiting for snap tween to finish ──
  if(obj.phase==='snapping') return;

  // Normalise to 60 fps baseline so constants feel the same regardless of frame rate
  const s = dt/16.67;

  // ── Gravity: accumulate 0.4 velocity units per frame ──
  obj.vel.y -= 0.40*s;

  // ── Position integration (vel is units/s → divide by 60) ──
  mesh.position.x += obj.vel.x * s / 60;
  mesh.position.y += obj.vel.y * s / 60;
  mesh.position.z += obj.vel.z * s / 60;

  // ── Rotation: add angVel (rad/s) per frame (÷60 → rad/frame) ──
  mesh.rotation.x += obj.angVel.x * s / 60;
  mesh.rotation.y += obj.angVel.y * s / 60;
  mesh.rotation.z += obj.angVel.z * s / 60;

  // ── Rotational friction: 0.92 per frame ──
  const rdf = Math.pow(0.92, s);
  obj.angVel.x*=rdf; obj.angVel.y*=rdf; obj.angVel.z*=rdf;

  // ── Floor collision ──
  if(mesh.position.y - obj.dieRad < obj.floorY){
    mesh.position.y = obj.floorY + obj.dieRad;
    const preVelY   = obj.vel.y;               // save for impact intensity
    obj.vel.y  = Math.abs(obj.vel.y) * 0.45;  // bounceDamping
    obj.vel.x *= 0.88;                          // lateral friction
    obj.vel.z *= 0.88;
    obj.bounces++;
    playImpact(Math.min(1.0, Math.abs(preVelY) / 10));
  }

  // ── Area bounds — keep dice within 3 tiles of spawn centre ──
  const ax=obj.area.x, az=obj.area.z;
  if(Math.abs(mesh.position.x-ax)>3.0){
    mesh.position.x=ax+Math.sign(mesh.position.x-ax)*3.0; obj.vel.x*=-0.45;
  }
  if(Math.abs(mesh.position.z-az)>2.5){
    mesh.position.z=az+Math.sign(mesh.position.z-az)*2.5; obj.vel.z*=-0.45;
  }

  // ── Settle detection: met both velocity thresholds after ≥2 bounces ──
  // Fallback por TEMPO (espelha a versão 2D): sem ele, em quadros irregulares
  // (celular, ou quando o overlay de armadilha abre no meio da rolagem) um dado
  // podia quicar para sempre — nunca sumindo E chamando playImpact a cada quique
  // (o "chiado travado" do som). Força o assentamento depois de ~2,8 s.
  obj.t = (obj.t || 0) + dt;
  const avMag=Math.hypot(obj.angVel.x, obj.angVel.y, obj.angVel.z);
  const _assentaPorVel = obj.bounces>=2 && Math.abs(obj.vel.y)<0.05 && avMag<0.30;
  const _assentaPorTempo = obj.t > 2800;
  if(_assentaPorVel || _assentaPorTempo){
    obj.phase='snapping';
    const snap=_snapRotation(window.THREE, mesh, obj.faceNormals);
    _addTween(mesh, mesh.quaternion.clone(), snap.quaternion, 420, ()=>{
      const topIndex = snap.groupIndex;
      if(obj.mats[topIndex]){
        _disposeDieMaterials([obj.mats[topIndex]]);
        obj.mats[topIndex] = _buildDieMat(window.THREE, obj.value, obj.color, obj.dieType);
        mesh.material = obj.mats;
      }
      // O d20 recebe ainda uma inscrição plana sobre a face superior. Ela usa a
      // normal exata da face que acabou de assentar, garantindo que o resultado
      // do servidor seja legível mesmo com o reflexo da resina.
      if(obj.dieType === 'd20'){
        const normal = obj.faceNormals.find(n => n.groupIndex === topIndex);
        if(normal){
          const badge = _makeD20TopBadge(window.THREE, obj.value);
          badge.mesh.position.set(normal.x*0.635, normal.y*0.635, normal.z*0.635);
          badge.mesh.quaternion.setFromUnitVectors(
            new window.THREE.Vector3(0,0,1),
            new window.THREE.Vector3(normal.x,normal.y,normal.z));
          badge.mesh.renderOrder=10001;
          mesh.add(badge.mesh); obj.topBadge=badge;
        }
      }
      obj.phase='settling'; obj.settleT=0;
      playSettle();
      if(window.CombatScene) CombatScene.dieSettled({die: obj.dieType, value: obj.value}, performance.now());
      // Gold particle burst — usa posição mundial (mesh é filho do diceGroup)
      if(g3){ const _wp=new (window.THREE).Vector3(); mesh.getWorldPosition(_wp); _spawnGoldParticles(window.THREE,g3.scene,_wp); }
    });
  }
}

// ── Die-die sphere-sphere collision (prevents stacking / overlap) ─────────────
// Called once per frame after all individual _tickDie3 calls.
function _resolveDieCollisions(){
  const n = _dice3.length;
  if(n < 2) return;
  for(let i = 0; i < n; i++){
    const a = _dice3[i];
    // Only rolling dice participate — don't disturb snapping/settling/fading
    if(a.phase !== 'rolling') continue;
    for(let j = i+1; j < n; j++){
      const b = _dice3[j];
      if(b.phase !== 'rolling') continue;

      const dx = b.mesh.position.x - a.mesh.position.x;
      const dy = b.mesh.position.y - a.mesh.position.y;
      const dz = b.mesh.position.z - a.mesh.position.z;
      const distSq = dx*dx + dy*dy + dz*dz;
      const minDist = a.dieRad + b.dieRad;       // 0.84 units

      if(distSq >= minDist*minDist || distSq < 1e-6) continue;

      const dist   = Math.sqrt(distSq);
      const nx = dx/dist, ny = dy/dist, nz = dz/dist;

      // ── Positional correction: push both dice apart by half the overlap ──
      const overlap = (minDist - dist) * 0.5 + 0.005;  // tiny extra gap
      a.mesh.position.x -= nx*overlap;  a.mesh.position.y -= ny*overlap;  a.mesh.position.z -= nz*overlap;
      b.mesh.position.x += nx*overlap;  b.mesh.position.y += ny*overlap;  b.mesh.position.z += nz*overlap;

      // ── Velocity impulse — elastic collision, equal mass ──────────────────
      const dvx = b.vel.x - a.vel.x;
      const dvy = b.vel.y - a.vel.y;
      const dvz = b.vel.z - a.vel.z;
      const relVel = dvx*nx + dvy*ny + dvz*nz;
      if(relVel >= 0) continue;   // already separating — skip impulse

      const restitution = 0.50;
      const impulse = -(1 + restitution) * relVel * 0.5;  // ÷2 for equal masses
      a.vel.x -= impulse*nx;  a.vel.y -= impulse*ny;  a.vel.z -= impulse*nz;
      b.vel.x += impulse*nx;  b.vel.y += impulse*ny;  b.vel.z += impulse*nz;

      // Randomised spin kick on collision (feels physical)
      const spin = 4.0;
      a.angVel.x += (Math.random()-.5)*spin;  a.angVel.z += (Math.random()-.5)*spin;
      b.angVel.x += (Math.random()-.5)*spin;  b.angVel.z += (Math.random()-.5)*spin;

      // Softer impact click for die-on-die contact
      playImpact(Math.min(0.65, Math.abs(relVel) / 6));
    }
  }
}

// ── Labels dos dados (overlay 2D sobre o canvas dice-canvas) ────────────────
// Cada frame: projeta a posição mundial de cada dado para coordenadas de tela
// e desenha o label (ex.: "⚔️ Mão Principal", "🗡️ Mão Secundária", "Desvantagem
// — descartado") acima do dado, com cor sincronizada ao material do dado.
function _drawDiceLabels(){
  const dc = document.getElementById('dice-canvas');
  if(!dc || !g3 || !g3.camera || !g3.renderer) return;
  const ctx = dc.getContext('2d');
  // Limpa o overlay todo frame (não acumula).
  ctx.clearRect(0, 0, dc.width, dc.height);
  if(!_dice3.length) return;

  const T = window.THREE;
  const cssW = dc._cssW || dc.clientWidth;
  const cssH = dc._cssH || dc.clientHeight;
  const dpr  = window.devicePixelRatio || 1;
  ctx.save();
  ctx.scale(dpr, dpr);
  ctx.textAlign = 'center';
  ctx.textBaseline = 'bottom';

  for(const obj of _dice3){
    if(!obj || !obj.mesh || obj.alpha <= 0.05) continue;
    if(obj.phase === 'fading' && obj.alpha < 0.4) continue;
    if(!obj.label && !obj.meta?.formula) continue;
    // Posição do label acima da face superior do dado (mundo).
    const worldPos = new T.Vector3();
    obj.mesh.getWorldPosition(worldPos);
    worldPos.y += obj.dieRad + 0.25;
    // Projeção 3D → NDC → tela CSS.
    const ndc = worldPos.clone().project(g3.camera);
    if(ndc.z >= 1 || ndc.z <= -1) continue;   // fora do frustum
    const sx = (ndc.x * 0.5 + 0.5) * cssW;
    const sy = (-ndc.y * 0.5 + 0.5) * cssH;

    // Cor do label acompanha a variação exata da peça física.
    const color = _diceLabelInk(obj.color || '#e8d180');

    const formula = obj.meta?.formula || `${obj.dieType} ${obj.value}`;
    const context = obj.meta?.context || obj.label;
    // Sombra preta atrás para legibilidade
    ctx.globalAlpha = Math.min(1, obj.alpha) * 0.9;
    ctx.fillStyle = 'rgba(0,0,0,0.85)';
    ctx.font = `bold ${VC.dice.formulaFontSize || 14}px 'Cinzel', serif`;
    ctx.fillText(formula, sx + 1, sy + 1);
    ctx.fillStyle = color;
    ctx.fillText(formula, sx, sy);
    if(context){
      ctx.font = `bold ${VC.dice.statusFontSize || 10}px 'Cinzel', serif`;
      ctx.fillStyle = obj.discarded ? '#ff9b91' : obj.kept ? '#8dffb1' : '#f0d58b';
      ctx.fillText(context, sx, sy + 14);
    }
  }
  ctx.restore();
}

// Física dos dados 3D — executada pelo loop principal do renderer. Os dados
// vivem em g3.scene e não precisam de um requestAnimationFrame separado.
function _updateDiceLoop3D(now){
    if(!_d3) return false;
    const lastT = _d3._lastT || now - 16.67;
    const dt = Math.min(now-lastT, 50); _d3._lastT = now;
    _d3._cfr++;

    // ── Reposiciona o grupo na âncora inferior direita (segue câmera) ────────
    if(_d3._diceGroup && g3 && g3.camera){
      const T3 = window.THREE;
      const cam = g3.camera;
      // A mesma âncora usada pelos dados 2D, convertida de coordenadas de tela
      // normalizadas (0..1) para NDC (-1..1). Assim o grupo permanece reunido,
      // mas não cobre as miniaturas no centro do tabuleiro.
      const anchor = VC.dice.screenAnchor || {x:0.72, y:0.68};
      const ndcX = anchor.x * 2 - 1;
      const ndcY = 1 - anchor.y * 2;
      const near = new T3.Vector3(ndcX, ndcY, -1).unproject(cam);
      const far  = new T3.Vector3(ndcX, ndcY,  1).unproject(cam);
      const dir  = new T3.Vector3().subVectors(far, near).normalize();
      const FLOAT_Y = 2.5;   // altura de flutuação acima do tabuleiro
      if(Math.abs(dir.y) > 0.001){
        const t = (FLOAT_Y - near.y) / dir.y;
        _d3._diceGroup.position.set(near.x + dir.x*t, FLOAT_Y, near.z + dir.z*t);
      } else {
        _d3._diceGroup.position.set(near.x, FLOAT_Y, near.z);
      }
      // Escala do grupo = 1 (tamanho dos dados mantido igual ao anterior)
    }

    // Advance quaternion tweens (face-snap)
    _updateTweens(dt);
    // Advance gold particle bursts
    _updateParticles(dt);

    // Physics tick (individual)
    for(let i = 0; i < _dice3.length; i++) _tickDie3(_dice3[i], dt);

    // Die-die collision — prevents stacking / overlap
    _resolveDieCollisions();

    // Cleanup faded dice
    for(let i = _dice3.length-1; i >= 0; i--){
      if(_dice3[i].alpha <= 0.01){
        if(_d3._diceGroup) _d3._diceGroup.remove(_dice3[i].mesh);
        // Dispose COMPLETO: material.dispose() NÃO libera a CanvasTexture do map
        // — sem isto cada rolagem vazava uma textura 256² na GPU (lentidão
        // progressiva em sessões longas).
        _disposeDieMaterials(_dice3[i].mats);
        _disposeTopBadge(_dice3[i].topBadge);
        _dice3[i].geo.dispose();
        _dice3.splice(i, 1);
      }
    }

    // ── Desenha labels dos dados sobre o canvas 2D ────────────────────────────
    // Projeta a posição 3D do mesh para coordenadas de tela e desenha o label
    // acima do dado. Distingue: descartado (vermelho), kept (verde), off-hand
    // (laranja), normal (dourado). Resolve a confusão visual entre dual-wield
    // do Henrique e a desvantagem da Provocação.
    _drawDiceLabels();

    const active = _dice3.length > 0 || _particleSystems.length > 0;
    _d3.animFrame = null;
    if(!active) _d3._lastT = 0;
    return active;
}

// ── Barras de Fome e Sede (sistema de sobrevivência) ───────────────────────
// Barras de Fome/Sede do HUD — refletem o recurso AUTORITATIVO do servidor
// (player.fome / player.sede, escala 0–100), que é o que as habilidades do warrior,
// o ataque básico, o caminhar e as ações bônus consomem. `p` = jogador do game_state.
function renderBarrasSobrevivencia(p){
  if(!p) return '';
  const fomeMax = Math.max(1, Math.round(p.fome_max ?? 100));
  const sedeMax = Math.max(1, Math.round(p.sede_max ?? 100));
  const fome = Math.max(0, Math.min(fomeMax, Math.round(p.fome ?? fomeMax)));
  const sede = Math.max(0, Math.min(sedeMax, Math.round(p.sede ?? sedeMax)));
  const pctFome = fome / fomeMax * 100;
  const pctSede = sede / sedeMax * 100;

  function corBarra(v){                 // v na escala 0–100
    if(v > 70) return '#f0c040'; // dourado — saciado
    if(v > 40) return '#a0a0a0'; // cinza — neutro
    if(v > 20) return '#ff851b'; // laranja — leve
    if(v > 0)  return '#ff4500'; // laranja escuro — grave
    return '#ff1111';            // vermelho — esgotado
  }

  // Bloco de DOENÇA (sistema de doenças) — só aparece se o herói estiver doente.
  let doencaHTML = '';
  if(p.doente && p.doenca){
    const sevNome = {leve:t('ui.hud.leve'), pesada:t('ui.hud.pesada'), grave:t('ui.hud.grave')}[p.doenca.severidade] || t('ui.hud.leve');
    const descs = {
      leve:  t('ui.hud.1_reflexos_1_fortitude_1_movimento'),
      medio: t('ui.hud.exausto_efeitos'),
      grave: '-2 CON · -2 INT'
    };
    const linhas = (p.doenca.sintomas || []).map(t => `• ${descs[t] || t}`).join('<br>');
    doencaHTML = `
    <div style="width:100%; margin-bottom:6px; border:1px solid #6b3a6b; background:rgba(60,20,60,0.35); padding:4px 6px;">
      <div style="color:#cc88cc; font-family:'Cinzel',serif; font-size:9px; letter-spacing:1px; margin-bottom:2px;">${t('ui.hud.doenca_titulo', {sev:sevNome.toUpperCase()})}</div>
      <div style="color:#b59ab5; font-size:8.5px; line-height:1.35;">${linhas}</div>
      <div style="color:#7a5a7a; font-size:8px; margin-top:2px;">${t('ui.hud.doenca_curavel')}</div>
    </div>`;
  }

  return doencaHTML + `
    <!-- FOME -->
    <div style="width:100%; margin-bottom:5px;">
      <div style="display:flex; justify-content:space-between; margin-bottom:2px;">
        <span style="color:#8a7a5a; font-family:'Cinzel',serif; font-size:9px; letter-spacing:2px;">🍖 ${t('ui.sobrevivencia.fome_caixa')}</span>
        <span style="color:${corBarra(pctFome)}; font-family:'Cinzel',serif; font-size:9px;">${fome}/${fomeMax}</span>
      </div>
      <div style="width:100%; height:5px; background:#1a1a1a; border:1px solid #2a2a2a;">
        <div style="width:${pctFome}%; height:100%; background:${corBarra(pctFome)}; transition:width 0.5s ease, background 0.5s ease;"></div>
      </div>
    </div>

    <!-- SEDE -->
    <div style="width:100%; margin-bottom:5px;">
      <div style="display:flex; justify-content:space-between; margin-bottom:2px;">
        <span style="color:#8a7a5a; font-family:'Cinzel',serif; font-size:9px; letter-spacing:2px;">💧 ${t('ui.sobrevivencia.sede_caixa')}</span>
        <span style="color:${corBarra(pctSede)}; font-family:'Cinzel',serif; font-size:9px;">${sede}/${sedeMax}</span>
      </div>
      <div style="width:100%; height:5px; background:#1a1a1a; border:1px solid #2a2a2a;">
        <div style="width:${pctSede}%; height:100%; background:${corBarra(pctSede)}; transition:width 0.5s ease, background 0.5s ease;"></div>
      </div>
    </div>
  `;
}

// Vinheta de pressão na tela — reflete o pior estado (fome/sede) do herói local.
function atualizarEfeitosVisuais(heroi){
  const vinheta = document.getElementById('vinheta-sobrevivencia');
  if(!vinheta || !heroi) return;
  const piorEstado = Math.min(heroi.fome, heroi.sede);

  if(piorEstado <= 5){
    // Grave — vinheta vermelha pulsante
    vinheta.style.boxShadow = 'inset 0 0 80px rgba(255,17,17,0.4)';
    vinheta.style.animation = 'piscar 1.5s infinite';
  } else if(piorEstado <= 10){
    // Moderado — vinheta laranja fixa
    vinheta.style.boxShadow = 'inset 0 0 60px rgba(255,69,0,0.3)';
    vinheta.style.animation = 'none';
  } else if(piorEstado <= 19){
    // Leve — vinheta sutil
    vinheta.style.boxShadow = 'inset 0 0 40px rgba(255,133,27,0.15)';
    vinheta.style.animation = 'none';
  } else {
    // Normal — sem efeito
    vinheta.style.boxShadow = 'none';
    vinheta.style.animation = 'none';
  }
}

function renderPlayers(state){
  const el=$('player-cards'); el.innerHTML='';
  for(const p of state.players){
    const isMe=p.id===GS.myPid, isCur=p.id===state.current_turn;
    const disc=p.connected===false;
    const fora=p.fora_masmorra||null;   // saiu pela escada: está na cidade
    const div=document.createElement('div');
    div.className='pcard'+(isMe?' me':'')+(isCur?' current':'')+(p.alive?'':' dead')+(disc?' disconnected':'');
    if(disc||fora) div.style.opacity='0.45';
    const hpPct=Math.max(0,p.hp/p.max_hp*100);
    // MP foi removido do jogo — nenhuma classe usa mana (magias custam slots + fome/sede).
    const mpRowHTML = '';
    const _csong = p.buffs_cancao && Object.keys(p.buffs_cancao).length;
    div.innerHTML=`
      <div class="pcard-top">
        <span class="pcard-emoji">${p.emoji}</span>
        <span class="pcard-name" style="color:${p.color}">${p.name}</span>
        ${_csong ? `<span title="${t('ui.hud.inspirado_cancao')}" style="color:#4db8ff;font-size:11px;">🎵</span>` : ''}
        <span class="pcard-lvl">Lv${p.level}</span>
      </div>
      ${fora ? `<div class="pcard-fora" style="font-size:11px;color:#8fc6ff;">${t('ui.hud.na_cidade_volta_em', {n: fora.rodadas_restantes|0})}</div>` : ''}
      <div class="bars">
        <div class="bar-row">
          <span class="bar-label">HP</span>
          <div class="bar-bg"><div class="bar-fill hp" style="width:${hpPct}%"></div></div>
          <span class="bar-val">${p.hp}/${p.max_hp}</span>
        </div>${mpRowHTML}
        <div class="survival-bars">${renderBarrasSobrevivencia(p)}</div>
      </div>`;
    // Clique no mini-card abre a ficha do herói correspondente.
    div.style.cursor = 'pointer';
    div.title        = t('ui.hud.clique_para_ver_a_ficha');
    div.onclick      = () => {
      const key = _classIdParaHeroiKey(p.cls || p.class_id || p.key);
      abrirFichaEmJogo(key);
    };
    el.appendChild(div);
  }
  // Vinheta de pressão reflete o herói local (fome/sede autoritativos do servidor, 0–100).
  const _localP = state.players.find(x => x.id === GS.myPid);
  if (_localP) atualizarEfeitosVisuais({ fome: _localP.fome, sede: _localP.sede });
}

// ── Flags ativas do warrior (Victor) no turno atual ──────────────────────────
// Pré-visualiza as habilidades ARMADAS (toggle, client-side via GS) com o custo
// total que será cobrado ao atacar. Mostra também flags já APLICADAS no servidor
// (durante a janela de combate). Retorna '' quando não há nada armado/ativo.
function renderFlagsWarrior(me) {
  const armadas = (typeof GS !== 'undefined' && GS.getWarriorSelected) ? GS.getWarriorSelected() : []
  const EFEITO = {
    mira_certeira:    '<span style="color:#c8a951">⚔️ +2 acerto</span>',
    golpe_devastador: '<span style="color:#ff851b">' + t('ui.hud.dano_x2') + '</span>',
    furia_berserker:  '<span style="color:#ff4444">' + t('ui.hud.ataque_extra') + '</span>',
  }

  // Caso armadas (fase de seleção, antes do ataque)
  if (armadas.length) {
    const skills = (me.skills || []).filter(s => armadas.includes(s.id))
    const fome = skills.reduce((a, s) => a + (s.fome_cost || 0), 0)
    const sede = skills.reduce((a, s) => a + (s.sede_cost || 0), 0)
    const chips = skills.map(s => EFEITO[s.id] || `<span>${s.name}</span>`)
    return `
      <div style="margin-top:6px; padding:6px 8px; background:rgba(200,169,81,0.10);
        border:1px solid #c8a95155; font-family:'Cinzel',serif; font-size:9px; letter-spacing:1px;">
        <div style="display:flex; gap:8px; flex-wrap:wrap;">${chips.join(' | ')}</div>
        <div style="margin-top:3px; color:#8a7a5a;">${t('ui.hud.custo_ao_atacar', {fome, sede: sede ? ` 💧-${sede}` : ''})}</div>
      </div>`
  }

  // Caso flags já aplicadas no servidor (após atacar, dentro do turno)
  const bonusAcerto = me.skill_bonus_acerto || 0
  const dobrarDano  = me.skill_dobrar_dano || false
  const ataqueExtra = !!me.skill_ataque_extra
  if (!bonusAcerto && !dobrarDano && !ataqueExtra) return ''
  const ativos = []
  if (bonusAcerto > 0) ativos.push(`<span style="color:#c8a951">⚔️ +${bonusAcerto} acerto</span>`)
  if (dobrarDano)      ativos.push(EFEITO.golpe_devastador)
  if (ataqueExtra)     ativos.push(EFEITO.furia_berserker)
  return `
    <div style="margin-top:6px; padding:6px 8px; background:rgba(200,169,81,0.08);
      border:1px solid #c8a95133; font-family:'Cinzel',serif; font-size:9px; letter-spacing:1px;
      display:flex; gap:8px; flex-wrap:wrap;">
      ${ativos.join(' | ')}
    </div>`
}

