// ═══════════════════════════════════════════════════════════════════════════
// HENRIQUE, O BARDO — Interface das 3 habilidades (Prompt 2)
//   • Conhecimento das Lendas (passiva): tooltip completo do inimigo no hover
//   • Canção Heroica (principal): toggle de buffs por atributo, raio 5
//   • Provocação (bônus): força o inimigo a atacar Henrique, raio 3
// Adaptado à arquitetura REAL do cliente: class_id (não `cls`), pos[] (não
// tx/ty), GS.adicionarLog/openTargetModal, e os campos reais do monstro que o
// servidor envia (name/emoji/hp/max_hp/ac/atk_bonus/damage/tier/xp/gold/...).
// ═══════════════════════════════════════════════════════════════════════════

const CANCAO_RAIO_CLIENT = 5;
const _CANCAO_NOTAS_GLYPHS = ['♪', '♫', '♬', '♩', '♭', '♯', '𝄞'];
let _cancaoAura2DRaf = null;
let _cancaoAura2DLastFrame = 0;
let _cancaoAura2DState = null;

function _cantoresCancaoAtiva(state){
  return (state?.players || []).filter(p => p?.class_id === 'bard' && p.alive && p.cancao_ativa && Array.isArray(p.pos))
    .concat(state?.test_mode ? (state.monsters || []).filter(m => m && m.hp > 0 && m.cancao_ativa && Array.isArray(m.pos)) : []);
}

function _ensureCancaoHeroicaAura2D(state){
  _cancaoAura2DState = state;
  if(!_cantoresCancaoAtiva(state).length || _cancaoAura2DRaf != null) return;
  _cancaoAura2DRaf = _scheduleVisualFrame(_tickCancaoHeroicaAura2D);
}

function _tickCancaoHeroicaAura2D(now){
  _cancaoAura2DRaf = null;
  if(mode3D) return;
  const state = GS.gameState || _cancaoAura2DState;
  if(!state || !_cantoresCancaoAtiva(state).length) return;
  if(now - _cancaoAura2DLastFrame >= 40){
    _cancaoAura2DLastFrame = now;
    renderMap(state); // renderMap rearma este único ciclo enquanto a canção estiver ativa.
  } else {
    _cancaoAura2DRaf = _scheduleVisualFrame(_tickCancaoHeroicaAura2D);
  }
}

function _desenharNotasCancao2D(ctx, state, now, exploredSet){
  const cantores = _cantoresCancaoAtiva(state);
  if(!cantores.length) return;
  ctx.save();
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.globalCompositeOperation = 'lighter';
  for(const cantor of cantores){
    if(!exploredSet.has(`${cantor.pos[0]},${cantor.pos[1]}`)) continue;
    const cx = cantor.pos[0] * CELL + CELL / 2;
    const cy = cantor.pos[1] * CELL + CELL / 2;
    for(let i = 0; i < _CANCAO_NOTAS_GLYPHS.length; i++){
      const phase = ((now / 1900 + i / _CANCAO_NOTAS_GLYPHS.length) % 1 + 1) % 1;
      const angle = now / 1250 + i * (Math.PI * 2 / _CANCAO_NOTAS_GLYPHS.length);
      const radius = CELL * (0.28 + 0.58 * phase);
      const x = cx + Math.cos(angle) * radius;
      const y = cy - CELL * (0.25 + phase * 0.78) + Math.sin(angle) * CELL * 0.18;
      ctx.globalAlpha = Math.sin(Math.PI * phase) * 0.88;
      ctx.font = `bold ${Math.max(15, CELL * (0.25 + 0.08 * (i % 3)))}px serif`;
      ctx.fillStyle = i % 3 === 0 ? '#fff4b1' : (i % 3 === 1 ? '#ffe080' : '#d6f5ff');
      ctx.shadowColor = i % 3 === 2 ? '#75dfff' : '#ffce55';
      ctx.shadowBlur = CELL * 0.18;
      ctx.fillText(_CANCAO_NOTAS_GLYPHS[i], x, y);
    }
  }
  ctx.restore();
}

// O rótulo vem de ui.cancao.atributo.<id>; aqui fica só icone e custo.
const CANCAO_ATRIBUTOS_CLIENT = [
  { id:'acerto',      icone:'⚔️', custo:'sede' },
  { id:'dano',        icone:'💥', custo:'fome' },
  { id:'ca',          icone:'🛡️', custo:'sede' },
  { id:'movimento',   icone:'👣', custo:'fome' },
  { id:'resistencia', icone:'✊', custo:'sede' },
];
const _cancaoLabel = id => _rotulo(id, 'ui.cancao.atributo', id);

// Custo de fome/sede de um conjunto de atributos da canção (1 por atributo).
function calcularCustoCancao(ativos){
  let fome = 0, sede = 0;
  (ativos||[]).forEach(id => {
    const attr = CANCAO_ATRIBUTOS_CLIENT.find(a => a.id === id);
    if(attr) (attr.custo === 'fome') ? fome++ : sede++;
  });
  return { fome, sede };
}

// Conhecimento das Lendas é coletivo: basta um Henrique vivo no grupo.
function _partyTemBardoVivo(){
  const st = GS.gameState;
  return !!(st && st.players && st.players.some(p => p.class_id === 'bard' && p.alive));
}

// Tooltip do inimigo. `full=false` → só o nome + HP/CA (visão comum).
// `full=true` (com Henrique no grupo) → ficha completa do monstro.
function fichaInimigoTooltipHTML(m, full, attacker=null){
  const nome = `<b>${m.emoji||'👾'} ${m.name}</b>`;
  let verticalHTML = '';
  if(attacker?.pos && (attacker.weapon?.range != null || Number(m.altura) > 0 || Number(attacker.altura) > 0)){
      const info = GS.weaponReachInfo?.(attacker, m.pos?.[0], m.pos?.[1], m.altura);
    if(info){
      const delta = Math.abs(info.targetAltitude - info.attackerAltitude);
      const alcance = info.effectiveRange == null ? t('ui.ficha.corpo_a_corpo') : `${Math.max(0, info.effectiveRange)}/${attacker.weapon.range}`;
      const linhaLivre = info.effectiveRange == null || GS.hasLineOfSight?.(GS.gameState, attacker.pos[0], attacker.pos[1], m.pos[0], m.pos[1]);
      const situacao = info.effectiveRange == null
        ? (info.inRange ? t('ui.ficha.mesma_altura') : t('ui.ficha.alturas_diferentes'))
        : (!info.inRange ? t('ui.ficha.fora_do_alcance') : (linhaLivre ? 'alcance' : t('ui.ficha.linha_bloqueada')));
      verticalHTML = `<div style="margin-top:4px;padding-top:3px;border-top:1px solid #c8a95133;color:${info.inRange && linhaLivre ? '#9ee7b3' : '#ff9b9b'};font-size:9px;">${t('ui.ficha.altura_linha', {de: info.attackerAltitude, para: info.targetAltitude, delta, custo: info.verticalCost, alcance, situacao})}</div>`;
    }
  }
  if(!full) return `${nome}<br>HP ${m.hp}/${m.max_hp} | CA ${m.ac}${verticalHTML}`;
  const pct = Math.max(0, Math.min(100, (m.hp / Math.max(1,m.max_hp)) * 100));
  const cor = pct>60 ? '#2ecc40' : pct>30 ? '#ff851b' : '#ff4136';
  const TIER = {1:t('ui.ficha.comum'), 2:'Veterano', 3:'Elite', 4:t('ui.ficha.chefe')};
  const DMG_ICON = {physical:'⚔️', fire:'🔥', cold:'❄️', lightning:'⚡', holy:'✨', poison:'☠️', magic:'🔮'};
  const SAVE_LBL = {fortitude:'Fort', reflexos:'Ref', vontade:t('ui.ficha.von')};
  const ACT_LBL  = id => _rotulo(id, 'ui.mestre.acao_tipo', id);
  const mod = v => { const n = Math.floor((v-10)/2); return (n>=0?'+':'')+n; };
  const fmt = v => (v>=0?'+':'')+v;

  const tags = [];
  if(m.undead) tags.push(t('ui.ficha.morto_vivo'));
  if(m.boss)   tags.push(t('ui.ficha.chefe_2'));

  const crVal = m.cr != null ? (m.cr < 1 ? `1/${Math.round(1/m.cr)}` : String(m.cr)) : null;

  // Atributos (FOR/DES/CON/INT) — apenas monstros no novo formato
  let atribHTML = '';
  if (m.str_ != null) {
    atribHTML = `<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:2px;margin-top:5px;">
      ${[{k:'str_',l:t('ui.atributo.sigla.str_')},{k:'dex',l:t('ui.atributo.sigla.dex')},{k:'con_',l:t('ui.atributo.sigla.con_')},{k:'int_',l:t('ui.atributo.sigla.int_')}].map(({k,l})=>`
        <div style="background:rgba(255,255,255,0.04);padding:2px 0;text-align:center;">
          <div style="color:#8a7a5a;font-size:8px;">${l}</div>
          <div style="color:#c8b89a;font-size:10px;font-weight:bold;">${mod(m[k])}</div>
        </div>`).join('')}
    </div>`;
  }

  // Testes de resistência
  let savesHTML = '';
  if (m.fort != null) {
    savesHTML = `<div style="display:flex;gap:10px;margin-top:3px;font-size:9px;">
      <span style="color:#8a7a5a;">${t('ui.save.abrev.fort')} <b style="color:#c8b89a;">${fmt(m.fort)}</b></span>
      <span style="color:#8a7a5a;">${t('ui.save.abrev.ref')} <b style="color:#c8b89a;">${fmt(m.ref_)}</b></span>
      <span style="color:#8a7a5a;">${t('ui.save.abrev.von')} <b style="color:#c8b89a;">${fmt(m.will)}</b></span>
    </div>`;
  }

  // Lista de ataques (novo formato)
  let attacksHTML = '';
  if (m.attacks && m.attacks.length) {
    const rows = m.attacks.map(atk => {
      const types = (atk.damage_types||[]).map(t=>DMG_ICON[t]||t).join('');
      const mult  = atk.num_attacks > 1 ? ` ×${atk.num_attacks}` : '';
      const oh    = atk.on_hit
        ? `<div style="color:#ff851b;font-size:9px;padding-left:6px;">↳ ${atk.on_hit.replace(/_/g,' ')}</div>`
        : '';
      return `<div style="font-size:10px;color:#c8b89a;">${atk.name}: <b>${atk.damage}</b>${types}${mult} <span style="color:#8a7a5a;">(+${atk.atk_bonus})</span></div>${oh}`;
    }).join('');
    attacksHTML = `<div style="margin-top:5px;padding-top:4px;border-top:1px solid #c8a95133;">
      <div style="color:#8a7a5a;font-size:8px;letter-spacing:1px;margin-bottom:2px;">${t('ui.mestre.ataques')}</div>${rows}</div>`;
  }

  // Habilidades especiais
  let abilitiesHTML = '';
  if (m.special_abilities && m.special_abilities.length) {
    const rows = m.special_abilities.map(ab => {
      const max  = ab.uses_per_combat;
      const rem  = m.ability_uses ? (m.ability_uses[ab.id] ?? max) : max;
      const useStr = max ? ` ${rem}/${max}` : '';
      const dcStr  = ab.dc ? ` CD${ab.dc}/${SAVE_LBL[ab.save]||ab.save||''}` : '';
      const color  = (max && rem <= 0) ? '#666' : '#c8b89a';
      return `<div style="font-size:10px;color:${color};">${ab.name} <span style="color:#8a7a5a;">[${ACT_LBL(ab.action_type)}${dcStr}${useStr}]</span></div>`;
    }).join('');
    abilitiesHTML = `<div style="margin-top:5px;padding-top:4px;border-top:1px solid #c8a95133;">
      <div style="color:#8a7a5a;font-size:8px;letter-spacing:1px;margin-bottom:2px;">${t('ui.mestre.habilidades')}</div>${rows}</div>`;
  }

  // Imunidades e fraquezas
  let resistHTML = '';
  const imm  = m.immunities || [];
  const weak = m.weaknesses || [];
  if (imm.length || weak.length) {
    const immStr  = imm.map(i => DMG_ICON[i]||i).join(' ');
    const weakStr = weak.map(w => `${DMG_ICON[w.type]||w.type}${w.categoria?'/'+w.categoria:''} +${w.bonus_flat??'?'}`).join(' · ');
    resistHTML = `<div style="margin-top:4px;font-size:9px;">
      ${imm.length  ? `<div style="color:#4ec9b0;">${t('ui.ficha.imune_a_lista', {lista: immStr})}</div>` : ''}
      ${weak.length ? `<div style="color:#ff6b6b;">Fraq: ${weakStr}</div>` : ''}
    </div>`;
  }

  // Legado: acerto/dano como linha simples (monstros antigos sem m.attacks)
  const legacyAtkHTML = !m.attacks
    ? `<div>${t('ui.ficha.acerto_dano', {acerto: m.atk_bonus, dano: m.damage||'?'})}</div>` : '';

  return `
    <div style="min-width:220px;">
      <div style="display:flex;align-items:center;gap:6px;border-bottom:1px solid #c8a95155;padding-bottom:4px;margin-bottom:5px;">
        <span style="font-size:18px;">${m.emoji||'👾'}</span>
        <div>
          <div style="color:#c8a951;font-weight:bold;">${m.name}</div>
          <div style="color:#8a7a5a;font-size:.6rem;letter-spacing:2px;" data-i18n="ui.ficha.conhecimento_das_lendas">📖 CONHECIMENTO DAS LENDAS</div>
        </div>
      </div>
      <div style="display:flex;justify-content:space-between;">
        <span style="color:#8a7a5a;" data-i18n="ui.animar.vida">❤️ Vida</span>
        <span style="color:${cor};font-weight:bold;">${m.hp}/${m.max_hp}</span>
      </div>
      <div style="height:5px;background:#1a1a1a;border:1px solid #2a2a2a;margin:2px 0 6px;">
        <div style="width:${pct}%;height:100%;background:${cor};"></div>
      </div>
      <div>🛡️ ${t('ui.hud.sigla_ca')} <b>${m.ac}</b>${crVal ? ` &nbsp;·&nbsp; ${t('ui.hud.sigla_nd')} <b>${crVal}</b>` : ''}</div>
      <div>🏅 <b>${TIER[m.tier]||m.tier||'?'}</b> &nbsp;·&nbsp; ✨ ${t('ui.hud.sigla_xp')} <b>${m.xp ?? '?'}</b>${!m.attacks && m.gold != null ? ` &nbsp;·&nbsp; 🪙 <b>${m.gold}</b>` : ''}</div>
      ${verticalHTML}
      ${legacyAtkHTML}
      ${atribHTML}
      ${savesHTML}
      ${attacksHTML}
      ${abilitiesHTML}
      ${resistHTML}
      ${tags.length ? `<div style="margin-top:3px;color:#ff851b;">${tags.join(' · ')}</div>` : ''}
      ${(m.provocado && (m.provocado_turnos||0)>0) ? `<div style="margin-top:3px;color:#ff66cc;">${t('ui.ficha.provocado_turnos', {n: m.provocado_turnos})}</div>` : ''}
    </div>`;
}

// ── Canção Heroica: painel flutuante de seleção de atributos ────────────────
let _selecionadosCancao = [];

function abrirPainelCancao(opcoes = {}){
  const existente = document.getElementById('painel-cancao');
  if(existente){ existente.remove(); return; }   // toggle: reabrir fecha
  const mestreMonstro = opcoes.monstro || null;
  const me = mestreMonstro ? null : GS.me;
  if(!mestreMonstro && (!me || me.class_id !== 'bard')) return;
  if(!mestreMonstro && me.cancao_ativa){ send({type:'desativar_cancao'}); return; }

  _selecionadosCancao = [];
  const painel = document.createElement('div');
  painel.id = 'painel-cancao';
  painel.style.cssText =
    "position:fixed;bottom:180px;left:50%;transform:translateX(-50%);" +
    "background:rgba(10,8,5,0.97);border:1px solid #c8a951;width:300px;" +
    "z-index:3000;padding:16px;font-family:'Cinzel',serif;box-shadow:0 0 24px rgba(0,0,0,0.7);";

  function render(){
    const custo  = calcularCustoCancao(_selecionadosCancao);
    const ataque = { fome: custo.fome + 2, sede: custo.sede + 1 };
    // Canção Heroica Suprema reduz a MANUTENÇÃO em -1🍖/-1💧 (mín 0); só o preview.
    const _red   = (GS.bardoCancaoSuprema && GS.bardoCancaoSuprema()) ? 1 : 0;
    const man    = { fome: Math.max(0, custo.fome - _red), sede: Math.max(0, custo.sede - _red) };
    const nivelCancao = attr => mestreMonstro
      ? ((mestreMonstro.special_abilities||[]).some(a =>
          a.source_id === `bardo_cancao_${attr.id}` || a.id === `guild_bardo_cancao_${attr.id}`) ? 2 : 1)
      : (GS.bardoCancaoNivel ? GS.bardoCancaoNivel(attr.id) : 1);
    const linhas = CANCAO_ATRIBUTOS_CLIENT.map(attr => {
      const ativo = _selecionadosCancao.includes(attr.id);
      const cl    = attr.custo === 'sede' ? '💧' : '🍖';
      return `
        <div onclick="toggleAtributoCancao('${attr.id}')" style="
          display:flex;align-items:center;gap:10px;padding:7px 9px;margin-bottom:4px;
          background:${ativo?'rgba(200,169,81,0.15)':'rgba(255,255,255,0.02)'};
          border:1px solid ${ativo?'#c8a951':'#2a2a2a'};cursor:pointer;">
          <div style="width:15px;height:15px;border:1px solid ${ativo?'#c8a951':'#4a4a4a'};
            background:${ativo?'#c8a951':'transparent'};display:flex;align-items:center;
            justify-content:center;font-size:10px;color:#1a1a1a;">${ativo?'✓':''}</div>
          <span style="font-size:15px;">${attr.icone}</span>
          <div style="flex:1;color:${ativo?'#c8a951':'#c8b89a'};font-size:11px;">+${nivelCancao(attr)} ${_cancaoLabel(attr.id)}</div>
          <span style="color:#8a7a5a;font-size:9px;">${mestreMonstro ? t('ui.hud.bonus_aos_aliados') : `${cl}-1/turno`}</span>
        </div>`;
    }).join('');

    painel.innerHTML = `
      <div style="font-family:'Cinzel Decorative',serif;color:#c8a951;font-size:13px;margin-bottom:12px;text-align:center;">${mestreMonstro ? t('ui.cancao.titulo_monstro', {nome: mestreMonstro.name||t('ui.hud.xama')}) : t('ui.cancao.titulo')}</div>
      <div style="margin-bottom:12px;">${linhas}</div>
      ${mestreMonstro ? `<div style="padding:8px 10px;margin-bottom:8px;background:rgba(200,169,81,0.06);border:1px solid #c8a95133;color:#c8b89a;font-size:10px;text-align:center;">${t('ui.cancao.aviso_monstros_raio', {raio: CANCAO_RAIO_CLIENT})}</div>` : `<div style="padding:8px 10px;margin-bottom:8px;background:rgba(255,133,27,0.06);border:1px solid #ff851b33;">
        <div style="display:flex;justify-content:space-between;margin-bottom:4px;">
          <span style="color:#8a7a5a;font-size:9px;letter-spacing:2px;">${t('ui.cancao.ativar_manutencao')}${_red?` <span style="color:#c8a951;">${t('ui.cancao.suprema')}</span>`:''}</span>
          <span style="color:#ff851b;font-size:10px;">${_selecionadosCancao.length?((man.fome||man.sede)?`${man.fome?`🍖-${man.fome} `:''}${man.sede?`💧-${man.sede}`:''}${t('ui.cancao.por_turno')}`:`🍖0 💧0${t('ui.cancao.por_turno')}`):t('ui.cancao.selecione_atributos')}</span>
        </div>
        <div style="display:flex;justify-content:space-between;">
          <span style="color:#8a7a5a;font-size:9px;letter-spacing:2px;">${t('ui.cancao.se_atacar')}</span>
          <span style="color:#ff4136;font-size:10px;">${_selecionadosCancao.length?`🍖-${ataque.fome} 💧-${ataque.sede}`:'—'}</span>
        </div>
      </div>`}
      <div style="display:flex;gap:6px;">
        <button onclick="document.getElementById('painel-cancao').remove()" style="flex:1;padding:8px;background:transparent;border:1px solid #4a4a4a;color:#8a7a5a;font-family:'Cinzel',serif;font-size:10px;letter-spacing:2px;cursor:pointer;">${t('ui.geral.cancelar_caixa')}</button>
        <button onclick="confirmarCancao()" ${_selecionadosCancao.length?'':'disabled'} style="flex:2;padding:8px;background:${_selecionadosCancao.length?'rgba(200,169,81,0.15)':'transparent'};border:1px solid ${_selecionadosCancao.length?'#c8a951':'#4a4a4a'};color:${_selecionadosCancao.length?'#c8a951':'#4a4a4a'};font-family:'Cinzel',serif;font-size:10px;letter-spacing:2px;cursor:${_selecionadosCancao.length?'pointer':'not-allowed'};">${mestreMonstro ? t('ui.hud.ativar_cancao') : t('ui.cancao.cantar')}</button>
      </div>`;
  }

  render();
  document.body.appendChild(painel);

  window.toggleAtributoCancao = (id) => {
    _selecionadosCancao = _selecionadosCancao.includes(id)
      ? _selecionadosCancao.filter(s => s !== id)
      : [..._selecionadosCancao, id];
    render();
  };
  window.confirmarCancao = () => {
    if(!_selecionadosCancao.length) return;
    if(mestreMonstro) GS.mestreUsarHabilidade(mestreMonstro.id, 'hero_bard_cancao_heroica', null, null, _selecionadosCancao);
    else send({ type:'ativar_cancao', atributos:_selecionadosCancao });
    document.getElementById('painel-cancao')?.remove();
  };
}

// ── Provocação: seleção de alvo via modal padrão (raio 3, ação bônus) ───────
function iniciarProvocacao(){
  const me = GS.me;
  if(!me || me.class_id !== 'bard') return;
  if(!GS.isMyTurn || me.alive === false || (GS.gameState && GS.gameState.phase !== 'playing')){
    toast(t('ui.bardo.provocar_so_turno'), 'var(--orange)'); return;
  }
  if(me.bonus_action_used){ toast(t('ui.hud.acao_bonus_ja_usada'), 'var(--orange)'); return; }
  if(me.fome < 3 || me.sede < 3){ toast(t('ui.bardo.provocar_custo'), 'var(--orange)'); return; }

  const st  = GS.gameState;
  const pp  = me.pos || [0,0];
  const alvos = (st.monsters||[]).filter(m => m && m.hp>0 &&
    Math.max(Math.abs(pp[0]-m.pos[0]), Math.abs(pp[1]-m.pos[1])) <= _alcanceComAlturaCli(me, 3, m) &&
    !(m.provocado && (m.provocado_turnos||0) > 0));
  if(!alvos.length){ toast(t('ui.bardo.provocar_sem_alvo'), 'var(--orange)'); return; }
  if(alvos.length === 1){ send({ type:'provocacao', target_id:alvos[0].id }); return; }
  openTargetModal(t('ui.bardo.provocar_titulo'), alvos, 'monster',
    id => send({ type:'provocacao', target_id:id }));
}

// Botão de habilidade do bardo no painel (substitui o toggle genérico).
function _bardSkillBtn(me, sk){
  const btn = document.createElement('button');
  btn.className = 'skill-btn';
  const myTurnPlay = GS.isMyTurn && me.alive && GS.gameState && GS.gameState.phase === 'playing';

  if(sk.id === 'cancao_heroica'){
    if(me.cancao_ativa){
      const c = me.cancao_custo || {fome:0, sede:0};
      const labels = (me.cancao_atributos||[]).map(id => {
        return _cancaoLabel(id);
      }).join(' • ');
      btn.className += ' skill-active';
      btn.innerHTML = `
        <div class="skill-info">
          <div class="skill-name">🎵 ${sk.name} <small style="color:var(--gold);font-size:.65rem;">● ${t('ui.hud.cantando')}</small></div>
          <div class="skill-desc">${labels || '—'}</div>
        </div>
        <div class="skill-cost">🍖${c.fome} 💧${c.sede}<br><small style="font-size:.6rem;">${t('ui.hud.parar')}</small></div>`;
      btn.onclick = () => send({ type:'desativar_cancao' });   // parar a qualquer momento
    } else {
      btn.disabled = !myTurnPlay;
      btn.innerHTML = `
        <div class="skill-info">
          <div class="skill-name">🎵 ${sk.name}</div>
          <div class="skill-desc">${sk.description || t('ui.bardo.buffs_para_aliados_em_5_quadrados')}</div>
        </div>
        <div class="skill-cost">escolher</div>`;
      btn.onclick = () => abrirPainelCancao();
    }
  } else if(sk.id === 'provocacao'){
    const fc = sk.fome_cost ?? 3, sc = sk.sede_cost ?? 3;
    const temRec = me.fome >= fc && me.sede >= sc;
    const pode   = myTurnPlay && !me.bonus_action_used && temRec;
    btn.disabled = !pode;
    const aviso = me.bonus_action_used
      ? ` <small style="color:var(--text2);font-size:.62rem;">${t('ui.hud.bonus_usado')}</small>`
      : !temRec ? ' <small style="color:var(--red);font-size:.62rem;">'+t('ui.hud.sem_recursos')+'</small>' : '';
    const _pnv = GS.bardoProvocacaoNivel ? GS.bardoProvocacaoNivel() : 1;
    const _pextra = _pnv >= 3
      ? ` <span style="color:#c8a951;">${t('ui.bardo.provocacao_3')}</span>`
      : _pnv === 2
      ? ` <span style="color:#c8a951;">${t('ui.bardo.provocacao_2')}</span>`
      : '';
    btn.innerHTML = `
      <div class="skill-info">
        <div class="skill-name">😤 ${sk.name}${aviso}</div>
        <div class="skill-desc">${sk.description || t('ui.bardo.provocacao_desc')}${_pextra}</div>
      </div>
      <div class="skill-cost">🍖${fc} 💧${sc}</div>`;
    btn.onclick = () => iniciarProvocacao();
  }
  return btn;
}

// ── Instrumento do Bardo (Fase 1) — botão dedicado no HUD, fora do fluxo de
// me.skills. O instrumento vive na MÃO DO ESCUDO (me.gear.off_hand), que também
// pode conter escudo/2ª arma — por isso checamos tipo_item==='instrumento'.
// Só aparece se o instrumento equipado for modo:"ativada" (o Alaúde é passivo —
// Sinfonia Heroica não usa botão, é um hook passivo na Canção Heroica). ─────────
function _bardInstrumentoBtn(me){
  const inst = me.gear && me.gear.off_hand;
  if(!inst || inst.tipo_item !== 'instrumento') return null;
  const b = GS.instrumentoBase(inst.base);
  if(!b || b.modo !== 'ativada') return null;
  const st = GS.instrumentoStatsClient(inst) || {};
  const disponivel = GS.instrumentoDisponivel(me);
  const detalhes = [];
  if(st.alcance != null) detalhes.push(`alcance ${st.alcance}q`);
  if(st.raio != null) detalhes.push(`raio ${st.raio}q`);
  if(st.dano != null) detalhes.push(`${st.dano} dano`);
  if(st.duracao != null) detalhes.push(`${st.duracao} rodadas`);
  const btn = document.createElement('button');
  btn.className = 'skill-btn';
  btn.disabled = !disponivel;
  btn.title = `${b.habilidade_nome} — 🍖${st.custo_fome ?? 0} 💧${st.custo_sede ?? 0}`
    + (detalhes.length ? ` — ${detalhes.join(' · ')}` : '');
  btn.innerHTML = `
    <div class="skill-info">
      <div class="skill-name">${b.icon} ${b.habilidade_nome}</div>
      <div class="skill-desc">${detalhes.join(' · ') || '—'}</div>
    </div>
    <div class="skill-cost">🍖${st.custo_fome ?? 0} 💧${st.custo_sede ?? 0}</div>`;
  btn.onclick = () => acionarInstrumento(me, inst, b);
  if(b.efeito?.tipo === 'acorde_trovejante'){
    btn.addEventListener('mouseenter', () => _iniciarPreviaAcordeTrovejante(me, inst));
    btn.addEventListener('mouseleave', () => _limparPreviaAcordeTrovejante());
    btn.onclick = () => { _limparPreviaAcordeTrovejante(); acionarInstrumento(me, inst, b); };
  }
  aplicarTooltipInstrumento(btn, inst);   // quadro de hover: habilidade, efeito e custo
  return btn;
}

function _iniciarPreviaAcordeTrovejante(me, inst){
  const state = GS.gameState, raio = Number(GS.instrumentoStatsClient(inst)?.raio) || 0;
  if(!state?.tiles || !me?.pos || raio <= 0 || _aimAlgumModoAtivo()) return;
  _limparPreviaAcordeTrovejante(false);
  const oldRange = window._spellHL.range, oldArea = window._spellHL.area;
  const tiles = new Set(), bridges = new Set();
  for(const bridge of (state.pontes || []))
    for(const [x,y] of _bridgeTiles2D(bridge)) bridges.add(`${x},${y}`);
  const [px,py] = me.pos;
  for(let y=Math.max(0,py-raio);y<=Math.min(state.tiles.length-1,py+raio);y++)
    for(let x=Math.max(0,px-raio);x<=Math.min((state.tiles[y]||[]).length-1,px+raio);x++){
      if(x===px && y===py) continue;
      const tile=state.tiles[y]?.[x], key=`${x},${y}`;
      if(tile===TILE_FLOOR || tile===TILE_DOOR || bridges.has(key)) tiles.add(key);
    }
  const preview = {tiles, oldRange, oldArea};
  window._acordeTrovejantePreview = preview;
  window._spellHL.range = tiles;
  window._spellHL.area = new Set();
  _aplicarSpellHL();
}

function _limparPreviaAcordeTrovejante(render=true){
  const preview = window._acordeTrovejantePreview;
  if(!preview) return;
  window._acordeTrovejantePreview = null;
  // Se outra mira já substituiu os destaques, não restaure o estado antigo
  // por cima dela.
  if(window._spellHL.range === preview.tiles){
    window._spellHL.range = preview.oldRange;
    window._spellHL.area = preview.oldArea;
  }
  if(render) _aplicarSpellHL();
}

// Dispara a habilidade do instrumento equipado. Nota Cortante (Harpa) mira 1
// monstro dentro do alcance (mesmo padrão de mira da Provocação — modal só
// quando há mais de 1 alvo válido); Chamado do General (Trompa) mira por
// DIREÇÃO (mesmo padrão da Relâmpago — dir:[dx,dy]); Acorde Trovejante
// (Tambor, AoE centrada no bardo), Ecos Dolorosos (Sino, aura própria), Dueto
// Marcial (Lira) e Dueto Fantasma (Flauta) são auto-buffs sem alvo —
// GS.usarInstrumento(null). Improviso (Gaita, Fase 5) também cai no ramo
// default (sem alvo): a mira acontece DEPOIS da cascata 2d6, não antes — ver
// renderImprovisoQuadro/aimNextImprovisoAlvo (GS.on('improvisoResultado', …)),
// que enfileira os passos 7/9/11 (precisam de alvo) e envia GS.improvisoAlvo
// em sequência.
function _iniciarMiraInstrumento(me, inst, b){
  if(window._modoMagia) _encerrarModoMagia();
  if(window._modoThrowItem) _encerrarMiraArremesso();
  GS.pendingSkill = null;
  const st = GS.instrumentoStatsClient(inst) || {};
  const alcance = st.alcance || 0;
  const state = GS.gameState;
  const [px, py] = me.pos || [0, 0];
  // O alcance PINTADO é o disco do instrumento, do mesmo jeito que o das
  // magias (_recomputarAlcanceMagia também usa _addCheb). Antes ele já vinha
  // peneirado por chão + linha de visão, e numa sala fechada isso desenhava o
  // formato da SALA em vez do alcance da arma — o jogador via só as casas ao
  // redor e não conseguia julgar até onde a Nota Cortante chega. As paredes
  // continuam sem pintura porque a fábrica do realce recusa casa que não é
  // chão, e a névoa continua filtrando, como em qualquer outro alcance.
  const range = new Set();
  _addCheb(px, py, Math.max(0, _alcanceComAlturaCli(me, alcance)), range);
  range.delete(`${px},${py}`);   // a própria casa do bardo não é alvo
  window._modoInstrumento = { id: 'nota_cortante', base: inst.base, alcance, range };
  GS.pendingInstrumento = { id: 'nota_cortante', base: inst.base, alcance };
  // O VERDE continua marcando só o que dá para acertar de fato: inimigo no
  // alcance e com linha de visão — a mesma regra que GS.resolveTileClick usa
  // para aceitar o clique.
  const validTargets = new Set();
  for (const monster of state?.monsters || []) {
    if (monster.hp <= 0) continue;
    for (const [x, y] of GS.monsterTiles(monster)) {
      if (Math.max(Math.abs(px - x), Math.abs(py - y)) > _alcanceComAlturaCli(me, alcance, monster)) continue;
      if (GS.hasLineOfSight(state, px, py, x, y)) validTargets.add(`${x},${y}`);
    }
  }
  _aimStart({
    kind: 'instrumento',
    title: `${b.icon} ${b.habilidade_nome.toUpperCase()}`,
    instruction: t('ui.instrumento.selecione_inimigo_alcance', {alcance}),
    color: '#ff8c66', targetLabel: t('ui.instrumento.inimigo'), range, area: validTargets,
    cancelText: t('ui.instrumento.nota_cortante_cancelada'),
    cleanup: () => { window._modoInstrumento = null; GS.pendingInstrumento = null; },
  });
}

function _clickTileInstrumento(tx, ty){
  if(!window._modoInstrumento) return;
  const r = GS.resolveTileClick(tx, ty);
  if(r?.type === 'instrumento'){
    GS.usarInstrumento({ id: r.targetId });
    _encerrarMiraInstrumento();
  } else if(r?.type === 'instrumento_blocked'){
    const msg = r.reason === 'wall' ? t('ui.instrumento.uma_parede_ou_porta_fechada_bloqueia_a_not') : t('ui.instrumento.fora_do_alcance_da_nota_cortante');
    _aimSetStatus(msg, '#ffb168');
    toast(msg, 'var(--orange)');
  } else {
    _aimSetStatus(t('ui.instrumento.selecione_um_inimigo_vivo_dentro_do_alcanc'), '#ffb168');
  }
}

function _encerrarMiraInstrumento(){
  if(_aimSessionIs('instrumento')) { _aimEnd({ silent:true, reason:'resolved' }); return; }
  window._modoInstrumento = null;
  GS.pendingInstrumento = null;
  window._spellHL.range = new Set();
  window._spellHL.area = new Set();
  window._spellHL.double = new Set();
  _aplicarSpellHL();
  const leg = document.getElementById('legenda-instrumento');
  if(leg) leg.remove();
  if(typeof g3 !== 'undefined' && g3?.renderer) g3.renderer.domElement.style.cursor = 'default';
  document.removeEventListener('keydown', _keyInstrumentoEsc);
}

function _iniciarMiraInstrumentoAlvo(me, b, alcance, onSelect, targetList = null){
  const state = GS.gameState;
  const range = new Set(), validTargets = new Set();
  if(!state || !me?.pos) return false;
  if(!targetList) _addCheb(me.pos[0], me.pos[1], alcance, range);
  for(const monster of targetList || state.monsters || []){
    if(!monster || monster.hp <= 0) continue;
    for(const [x, y] of GS.monsterTiles(monster)) {
      if(targetList || Math.max(Math.abs(me.pos[0]-x), Math.abs(me.pos[1]-y)) <= _alcanceComAlturaCli(me, alcance, monster)) validTargets.add(`${x},${y}`);
    }
  }
  if(!validTargets.size){ toast(t('ui.instrumento.sem_inimigo_raio', {n:alcance}), 'var(--orange)'); return false; }
  window._modoInstrumentoAlvo = { validTargets, onSelect };
  _aimStart({
    kind:'instrumento_alvo', title:`${b.icon || '🎵'} ${(b.habilidade_nome || t('ui.instrumento.instrumento_2')).toUpperCase()}`,
    instruction:targetList ? t('ui.instrumento.selecione_um_inimigo_destacado') : t('ui.instrumento.selecione_inimigo_alcance', {alcance}),
    color:'#ff8c66', targetLabel:t('ui.instrumento.inimigo'), range, area:validTargets,
    cancelText:t('ui.instrumento.habilidade_de_instrumento_cancelada'),
    cleanup:()=>{ window._modoInstrumentoAlvo = null; },
  });
  return true;
}

function _clickTileInstrumentoAlvo(tx, ty){
  const mode = window._modoInstrumentoAlvo;
  if(!mode) return;
  const monster = (GS.gameState?.monsters || []).find(m => m?.hp > 0 &&
    GS.monsterTiles(m).some(([x, y]) => x === tx && y === ty));
  const valid = !!monster && mode.validTargets.has(`${tx},${ty}`);
  if(!valid){
    _aimSetHover(tx, ty, 'blocked');
    _aimSetStatus(t('ui.instrumento.selecione_um_inimigo_destacado_dentro_do_a'), '#ff9aa2');
    return;
  }
  const onSelect = mode.onSelect;
  _aimEnd({silent:true, reason:'resolved'});
  onSelect(monster.id);
}

function _aimHoverInstrumentoAlvo(tx, ty){
  const valid = !!window._modoInstrumentoAlvo?.validTargets?.has(`${tx},${ty}`);
  _aimSetHover(tx, ty, valid ? 'valid' : 'blocked');
  _aimSetStatus(valid ? t('ui.instrumento.inimigo_valido_confirme_para_usar') : t('ui.instrumento.selecione_um_inimigo_destacado_dentro_do_a'), valid ? '#94dfb0' : '#ff9aa2');
}

function _keyInstrumentoEsc(e){
  if(e.key === 'Escape'){
    _encerrarMiraInstrumento();
    toast(t('ui.instrumento.nota_cortante_cancelada'), '#888');
    e.preventDefault();
  }
}

function _atualizarMiraInstrumentoHover(tx, ty, tip, event){
  const mode = window._modoInstrumento;
  if(!mode) return false;
  const m = (GS.gameState?.monsters || []).find(mm => mm.hp > 0 &&
    GS.monsterTiles(mm).some(([bx, by]) => bx === tx && by === ty));
  if(m){
    const key = `${tx},${ty}`;
    const ok = mode.range.has(key) && GS.hasLineOfSight(GS.gameState, GS.me.pos[0], GS.me.pos[1], tx, ty);
    tip.innerHTML = `<b>${m.emoji} ${m.name}</b><br>HP: ${m.hp}/${m.max_hp}<br><span style="color:${ok ? '#f08080' : '#f09030'}">${ok ? t('ui.instrumento.clique_para_usar_nota_cortante') : t('ui.instrumento.fora_de_alcance_ou_bloqueado')}</span>`;
    // Sem evento a chamada veio do controle, que não tem ponteiro: mostrar a
    // dica a deixaria parada na última posição do mouse. O estado da mira (o
    // realce e a linha de status) já diz o mesmo sem depender da tela.
    tip.style.display = event ? 'block' : 'none';
    if(event){ tip.style.left = (event.clientX + 14) + 'px'; tip.style.top = (event.clientY - 10) + 'px'; }
    const canvas = document.getElementById('dungeon-canvas');
    if(canvas) canvas.style.cursor = ok ? 'crosshair' : 'not-allowed';
    _aimSetHover(tx, ty, ok ? 'valid' : 'blocked');
    _aimSetStatus(ok ? t('ui.instrumento.alvo_valido_confirmar_para_usar') : t('ui.instrumento.alvo_bloqueado_fora_do_alcance_ou_atras_de'), ok ? '#94dfb0' : '#ff9aa2');
  } else {
    tip.style.display = 'none';
    _aimSetHover(tx, ty, 'blocked');
    _aimSetStatus(t('ui.instrumento.selecione_um_inimigo_destacado_dentro_do_a'), '#ff9aa2');
  }
  return true;
}

function acionarInstrumento(me, inst, b){
  const tipo = b.efeito && b.efeito.tipo;
  if(tipo === 'nota_cortante'){
    const alcance = GS.instrumentoStatsClient(inst)?.alcance || 0;
    escolherDirecaoInstrumento(b, (dx, dy) => GS.usarInstrumento(null, [dx, dy]), true, alcance);
  } else if(tipo === 'chamado_general'){
    escolherDirecaoInstrumento(b, (dx, dy) => GS.usarInstrumento(null, [dx, dy]));
  } else if(tipo === 'requiem_final'){
    if(me.requiem_alvo){ GS.usarInstrumento(null); return; }   // clicar de novo desliga
    const st = GS.instrumentoStatsClient(inst) || {};
    const alcance = st.alcance || 0;
    const gs = GS.gameState;
    const pp = me.pos || [0,0];
    const alvos = (gs && gs.monsters || []).filter(m => m && m.hp > 0 &&
      Math.max(Math.abs(pp[0]-m.pos[0]), Math.abs(pp[1]-m.pos[1])) <= _alcanceComAlturaCli(me, alcance, m));
    if(!alvos.length){ toast(t('ui.instrumento.sem_inimigo_raio', {n:alcance}), 'var(--orange)'); return; }
    _iniciarMiraInstrumentoAlvo(me, b, alcance, id => GS.usarInstrumento({ id }));
  } else {
    GS.usarInstrumento(null);
  }
}

window.acionarInstrumento = acionarInstrumento;

// ── Seletor de direção (8 direções) — usado pelo Chamado do General (Trompa).
// Overlay mínimo e autocontido: NÃO reaproveita o pipeline de mira de magia
// (window._modoMagia/_clickTileMagia), que está fortemente acoplado ao envio
// de `{type:'magia', magia_id}` sobre o board 2D/3D. Aqui só precisamos de
// uma direção relativa ao bardo — um compasso de 8 botões resolve sem
// interferir em nenhum estado de magia/arremesso em andamento.
// Convenção dx,dy (mesma da Relâmpago/movimento — ver _facingToRotY,
// GS.move): +y = Sul, -y = Norte, +x = Leste, -x = Oeste.

function escolherDirecaoInstrumento(b, onEscolher, ortogonal=false, alcanceOverride=null){
  const me = GS.me;
  if(!me?.pos) return;
  const directions = new Set();
  if(ortogonal){
    for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]) directions.add(`${me.pos[0]+dx},${me.pos[1]+dy}`);
  }else{
    _addCheb(me.pos[0], me.pos[1], 1, directions);
    directions.delete(`${me.pos[0]},${me.pos[1]}`);
  }
  const alcanceNota = Math.max(0, Math.floor(Number(alcanceOverride) || 0));
  const modo = { onEscolher, directions, ortogonal,
    previewNota: ortogonal && alcanceNota > 0, alcanceNota };
  window._modoDirecaoInstrumento = modo;
  const area = modo.previewNota ? new Set() : directions;
  if(modo.previewNota) modo.possibleArea = _notaCortantePreviewTiles(me, alcanceNota);
  _aimStart({
    kind:'instrumento_direcao',
    title:`${b.icon || '📯'} ${(b.habilidade_nome || t('ui.instrumento.escolher_direcao')).toUpperCase()}`,
    instruction:t(ortogonal ? 'ui.instrumento.selecione_uma_das_quatro_casas_ortogonais' : 'ui.instrumento.selecione_uma_das_oito_casas_ao_redor_do_b'),
    color:'#ff8c66', targetLabel:t('ui.instrumento.direcao'),
    range:modo.previewNota ? modo.possibleArea : directions, area,
    cancelText:t('ui.instrumento.escolha_de_direcao_cancelada'),
    cleanup:()=>{ window._modoDirecaoInstrumento = null; },
  });
}

function _notaCortantePreviewTiles(me, alcance, direcao=null){
  const state = GS.gameState, tiles = state?.tiles || [], out = new Set();
  if(!me?.pos || !Number.isFinite(Number(alcance)) || alcance <= 0) return out;
  const dirs = direcao ? [direcao] : [[1,0],[-1,0],[0,1],[0,-1]];
  const doors = GS.doorSets?.(state)?.closed || new Set();
  const decorSolida = new Set();
  for(const d of (state?.decorations || [])) if(d && !d.pisavel)
    for(const [x,y] of GS.decorTilesOf(d)) decorSolida.add(`${x},${y}`);
  const pontes = new Set();
  for(const ponte of (state?.pontes || [])) for(const [x,y] of (ponte.tiles || [])) pontes.add(`${x},${y}`);
  const materiais = state?.materiais || {};
  for(const [dx,dy] of dirs){
    for(let i=1;i<=alcance;i++){
      const x=me.pos[0]+dx*i,y=me.pos[1]+dy*i,key=`${x},${y}`,tile=tiles[y]?.[x];
      const onBridge=pontes.has(key);
      const passable=onBridge || tile===TILE_FLOOR || (tile===TILE_DOOR && !doors.has(key));
      if(!passable || decorSolida.has(key) || (!onBridge && materiais[key]==='entulho')) break;
      out.add(key);
    }
  }
  return out;
}

function _clickTileDirecaoInstrumento(tx, ty){
  const mode = window._modoDirecaoInstrumento, me = GS.me;
  if(!mode || !me?.pos) return;
  const key = `${tx},${ty}`;
  if(mode.previewNota){
    const dx=tx-me.pos[0],dy=ty-me.pos[1];
    const dir=[Math.sign(dx),Math.sign(dy)];
    if(!mode.possibleArea?.has(key) || Math.abs(dir[0])+Math.abs(dir[1])!==1){
      _aimSetHover(tx, ty, 'blocked');
      _aimSetStatus(t('ui.instrumento.escolha_uma_das_quatro_casas_ortogonais'), '#ff9aa2');
      return;
    }
    const onEscolher=mode.onEscolher;
    _aimEnd({silent:true,reason:'resolved'});
    onEscolher(dir[0],dir[1]);
    return;
  }
  if(!mode.directions.has(key)){
    _aimSetHover(tx, ty, 'blocked');
    _aimSetStatus(t(mode.ortogonal ? 'ui.instrumento.escolha_uma_das_quatro_casas_ortogonais' : 'ui.instrumento.escolha_uma_das_oito_casas_ao_redor_do_bar'), '#ff9aa2');
    return;
  }
  const [dx, dy] = _dir8(tx - me.pos[0], ty - me.pos[1]);
  const onEscolher = mode.onEscolher;
  _aimEnd({silent:true, reason:'resolved'});
  onEscolher(dx, dy);
}

// ── Improviso da Gaita (Fase 5) — quadro da cascata + fila de mira ──────────
// Overlay autocontido via createElement (mesmo padrão de
// escolherDirecaoInstrumento/mostrarOverlayEscolhaMagia — não depende do HTML
// estático injetado no topo do arquivo). Mostra a lista de passos rolados
// (msg.cascata: {res,nome,precisa_alvo}) e destaca Encore Menor/Grande Encore;
// o botão OK fecha o quadro e, se houver passos pendentes (res 7/9/11 —
// Nota Cortante/Réquiem/Chamado do General improvisados), inicia a mira
// sequencial deles.
function renderImprovisoQuadro(msg){
  const existente = document.getElementById('improviso-overlay');
  if(existente) existente.remove();

  const overlay = document.createElement('div');
  overlay.id = 'improviso-overlay';
  overlay.style.cssText = `
    position:fixed; inset:0; z-index:9999; background:rgba(0,0,0,.7);
    display:flex; align-items:center; justify-content:center;`;

  const painel = document.createElement('div');
  painel.style.cssText = `
    background:var(--bg2); border:2px solid var(--gold); border-radius:12px;
    padding:20px 26px; text-align:center; max-width:340px;
    box-shadow:0 8px 32px rgba(0,0,0,.6);`;

  const linhas = (msg.cascata || []).map(c => `
    <li style="font-size:.82rem; padding:4px 8px; margin-bottom:4px;
               background:var(--bg3); border-radius:var(--radius); text-align:left;">
      🎲 ${c.res} — ${c.nome}${c.precisa_alvo ? ' <span style="color:var(--orange);">'+t('ui.hud.aguardando_alvo_parens')+'</span>' : ''}
    </li>`).join('');

  let destaque = '';
  if(msg.grande_encore) destaque = `<div style="color:var(--red); font-weight:bold; margin:6px 0;">${t('ui.instrumento.grande_encore')}</div>`;
  else if(msg.encore_menor) destaque = `<div style="color:var(--gold); font-weight:bold; margin:6px 0;">${t('ui.instrumento.encore_menor')}</div>`;

  painel.innerHTML = `
    <div style="color:var(--gold); font-weight:bold; font-size:1rem; margin-bottom:2px;" data-i18n="ui.hud.improviso_2">🪗 Improviso</div>
    ${destaque}
    <ul style="list-style:none; padding:0; margin:10px 0 6px;">
      ${linhas || '<li style="color:var(--text2); font-size:.82rem;">'+t('ui.instrumento.nada_aconteceu')+'</li>'}
    </ul>
    <button class="btn-cancel" id="improviso-ok-btn" style="color:var(--gold); border-color:var(--gold);">OK</button>`;

  overlay.appendChild(painel);
  document.body.appendChild(overlay);

  const pendentes = msg.pendentes || [];
  let fechado = false;
  function fechar(){
    if(fechado) return;
    fechado = true;
    overlay.remove();
    if(pendentes.length) aimNextImprovisoAlvo(pendentes, 0);
  }
  painel.querySelector('#improviso-ok-btn').onclick = fechar;
  overlay.onclick = e => { if(e.target === overlay) fechar(); };
}

// Mira, em sequência, os passos pendentes da cascata do Improviso (FIFO —
// mesma ordem de msg.pendentes, que é a ordem que o servidor consome da fila
// `improviso_pendente`). Cancelar um passo (Cancelar do target-modal, ou Esc
// no seletor de direção) interrompe a fila: os passos restantes não são
// enviados e expiram sozinhos no fim do turno (_limpar_improviso_pendente no
// servidor) — nenhuma limpeza extra é necessária aqui.
function aimNextImprovisoAlvo(pendentes, i){
  if(i >= pendentes.length) return;
  const step = pendentes[i];
  if(step.alvo_tipo === 'monstro'){
    const gs = GS.gameState;
    const alvos = (gs && gs.monsters || []).filter(m => m && m.hp > 0);
    if(!alvos.length){ toast(t('ui.hud.nenhum_inimigo_vivo_para_o_improviso'), 'var(--orange)'); return; }
    _iniciarMiraInstrumentoAlvo(GS.me, { icon:'🪗', habilidade_nome:t('ui.hud.improviso') }, 0,
      id => { GS.improvisoAlvo(id, null); aimNextImprovisoAlvo(pendentes, i + 1); }, alvos);
  } else if(step.alvo_tipo === 'direcao' || step.alvo_tipo === 'direcao_ortogonal'){
    const harpaBase = step.alvo_tipo === 'direcao_ortogonal' ? GS.instrumentoBase('harpa') : null;
    const alcanceNota = harpaBase?.stats?.[step.tier]?.alcance || 0;
    escolherDirecaoInstrumento({ icon: '🪗', habilidade_nome: t('ui.instrumento.improviso_direcao') },
      (dx, dy) => { GS.improvisoAlvo(null, [dx, dy]); aimNextImprovisoAlvo(pendentes, i + 1); },
      step.alvo_tipo === 'direcao_ortogonal', alcanceNota);
  }
}

// Ring 3D da Canção Heroica — criado/atualizado/removido conforme o estado.
function _sync3DCancaoRing(state){
  if(!g3 || !g3.scene || !window.THREE) return;
  const T = window.THREE;
  const cantores = _cantoresCancaoAtiva(state);
  const wanted = new Map(cantores.map(c => [String(c.id), c]));
  if(!g3._cancaoRings) g3._cancaoRings = new Map();
  // Compatibilidade com uma cena criada antes da coleção de anéis existir.
  if(g3._cancaoRing && !g3._cancaoRings.size){
    g3._cancaoRings.set('__legacy__', g3._cancaoRing);
    g3._cancaoRing = null;
  }
  for(const [id, grupo] of g3._cancaoRings){
    if(wanted.has(id)) continue;
    if(grupo.parent) grupo.parent.remove(grupo);
    grupo.traverse(obj => {
      if(obj.geometry) obj.geometry.dispose();
      if(obj.material){
        const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
        for(const mat of mats){ if(mat.map) mat.map.dispose(); mat.dispose(); }
      }
    });
    g3._cancaoRings.delete(id);
  }
  for(const [id, cantor] of wanted){
    let grupo = g3._cancaoRings.get(id);
    if(!grupo){
      grupo = new T.Group();
      grupo.name = 'cancao-heroica-aura';
      const raio = CANCAO_RAIO_CLIENT + 0.5; // borda externa do raio de 5 casas
      const area = new T.Mesh(
        new T.CircleGeometry(raio, 64).rotateX(-Math.PI/2),
        new T.MeshBasicMaterial({ color:0xe8bd55, transparent:true, opacity:0.10, depthWrite:false, side:T.DoubleSide }));
      area.position.y = .235; area.renderOrder = 68;
      const borda = new T.Mesh(
        new T.RingGeometry(raio-0.075, raio, 96).rotateX(-Math.PI/2),
        new T.MeshBasicMaterial({ color:0xffd76b, transparent:true, opacity:0.78, depthWrite:false, side:T.DoubleSide }));
      borda.position.y = .247; borda.renderOrder = 72;
      const bordaInterna = new T.Mesh(
        new T.RingGeometry(raio-0.20, raio-0.16, 96).rotateX(-Math.PI/2),
        new T.MeshBasicMaterial({ color:0xfff0b0, transparent:true, opacity:0.42, depthWrite:false, side:T.DoubleSide }));
      bordaInterna.position.y = .249; bordaInterna.renderOrder = 73;
      grupo.add(area, borda, bordaInterna);
      const notas = [];
      for(let i = 0; i < _CANCAO_NOTAS_GLYPHS.length; i++){
        const canvas = document.createElement('canvas'); canvas.width = canvas.height = 128;
        const ctx = canvas.getContext('2d');
        ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
        ctx.font = 'bold 90px serif';
        ctx.shadowColor = i % 3 === 2 ? '#75dfff' : '#ffce55'; ctx.shadowBlur = 18;
        ctx.fillStyle = i % 3 === 0 ? '#fff4b1' : (i % 3 === 1 ? '#ffe080' : '#d6f5ff');
        ctx.fillText(_CANCAO_NOTAS_GLYPHS[i], 64, 65);
        const texture = new T.CanvasTexture(canvas); texture.needsUpdate = true;
        const sprite = new T.Sprite(new T.SpriteMaterial({
          map:texture, transparent:true, opacity:0.0, depthWrite:false,
          blending:T.AdditiveBlending, sizeAttenuation:true,
        }));
        sprite.scale.set(.36, .36, 1); sprite.renderOrder = 145;
        sprite.userData.noteIndex = i; grupo.add(sprite); notas.push(sprite);
      }
      grupo.userData.cancaoAura = {area, borda, bordaInterna, notas};
      g3.scene.add(grupo);
      g3._cancaoRings.set(id, grupo);
    }
    const w = casaParaMundo(cantor.pos[0], cantor.pos[1]);
    const topo = topoTerreno3D(state, cantor.pos[0], cantor.pos[1], .22);
    grupo.position.set(w.x, topo - .22, w.z);
  }
}

function _atualizarCancaoHeroicaAura3D(now){
  if(!g3?._cancaoRings) return;
  const pulso = 0.5 + 0.5 * Math.sin(now / 520);
  for(const grupo of g3._cancaoRings.values()){
    const fx = grupo.userData.cancaoAura;
    if(!fx) continue; // descarta um anel legado caso ainda exista na cena
    fx.area.material.opacity = .075 + pulso * .045;
    fx.borda.material.opacity = .62 + pulso * .28;
    fx.borda.scale.setScalar(1 + pulso * .012);
    fx.bordaInterna.material.opacity = .28 + pulso * .22;
    fx.bordaInterna.rotation.y = -now / 2600;
    for(const sprite of fx.notas){
      const i = sprite.userData.noteIndex;
      const phase = ((now / 1900 + i / fx.notas.length) % 1 + 1) % 1;
      const angle = now / 1250 + i * (Math.PI * 2 / fx.notas.length);
      const radius = .26 + phase * .56;
      sprite.position.set(Math.cos(angle) * radius, .42 + phase * .80, Math.sin(angle) * radius);
      sprite.material.opacity = Math.sin(Math.PI * phase) * .9;
      const size = .30 + .07 * Math.sin(Math.PI * phase);
      sprite.scale.set(size, size, 1);
    }
  }
}

// Exposição global p/ onclick inline e integração externa.
window.abrirPainelCancao = abrirPainelCancao;
window.iniciarProvocacao = iniciarProvocacao;

// ════════════════════════════════════════════════════════════════════════════
// PALADINO (Richard) — UI das 5 habilidades
// Mensagens WebSocket (ver server.py): imposicao_maos {target_id},
// golpe_sagrado / desativar_golpe_sagrado, protetor {target_id} /
// desativar_protetor, acao_livre_richard {habilidade_id, bonus?}.
// Alvos de aliado são escolhidos via openTargetModal (mesmo padrão da Provocação),
// não por crosshair 3D. Estado lido de me.* (guerreiro_luz_ativo/_bonus/_custo,
// golpe_sagrado_ativo, protetor_ativo/_alvo, regeneracao_ativa).
// ════════════════════════════════════════════════════════════════════════════

// O rótulo vem de ui.guerreiro_luz.<id>, resolvido no RENDER. Chamar t() aqui
// seria erro de TDZ: este const roda no carregamento, e o tradutor (`const t`)
// só é inicializado bem depois no arquivo — e o erro aborta o resto do game.js.
const GUERREIRO_LUZ_BONUS_CLIENT = [
  { id:'visao',  icone:'👁️', custo:'sede', max:2 },
  { id:'ataque', icone:'⚔️', custo:'sede', max:2 },
  { id:'dano',   icone:'💥', custo:'fome', max:2 },
  { id:'ca',     icone:'🛡️', custo:'fome', max:2 },
];
const _glLabel = id => _rotulo(id, 'ui.guerreiro_luz', id);
let _bonusGuerreiro = { visao:0, ataque:0, dano:0, ca:0 };

// Painel com steppers +/- por bônus (0..2 cada). Sede paga Visão+Ataque,
// Fome paga Dano+CA — espelha _ativar_guerreiro_luz em server.py.
function abrirPainelGuerreiroLuz(){
  const existente = document.getElementById('painel-guerreiro-luz');
  if(existente){ existente.remove(); return; }   // toggle: reabrir fecha
  const me = GS.me;
  if(!me || me.class_id !== 'paladin') return;
  if(me.guerreiro_luz_ativo){ send({type:'acao_livre_richard', habilidade_id:'guerreiro_luz'}); return; }

  _bonusGuerreiro = { visao:0, ataque:0, dano:0, ca:0 };
  let gamepadFocusKey = 'visao-plus';
  const painel = document.createElement('div');
  painel.id = 'painel-guerreiro-luz';
  painel.style.cssText =
    "position:fixed;bottom:180px;left:50%;transform:translateX(-50%);" +
    "background:rgba(10,8,5,0.97);border:1px solid #c8a951;width:300px;" +
    "z-index:3000;padding:16px;font-family:'Cinzel',serif;box-shadow:0 0 24px rgba(0,0,0,0.7);";

  function calcularCusto(){
    return { fome:_bonusGuerreiro.dano + _bonusGuerreiro.ca,
             sede:_bonusGuerreiro.visao + _bonusGuerreiro.ataque };
  }
  function render(){
    const custo = calcularCusto();
    const linhas = GUERREIRO_LUZ_BONUS_CLIENT.map(attr => {
      const valor = _bonusGuerreiro[attr.id];
      const cl = attr.custo === 'sede' ? '💧' : '🍖';
      return `
        <div style="display:flex;align-items:center;gap:10px;padding:8px 10px;margin-bottom:4px;
          background:${valor>0?'rgba(200,169,81,0.10)':'rgba(255,255,255,0.02)'};
          border:1px solid ${valor>0?'#c8a951':'#2a2a2a'};">
          <span style="font-size:16px;">${attr.icone}</span>
          <div style="flex:1;color:${valor>0?'#c8a951':'#c8b89a'};font-size:11px;">+${valor} ${_glLabel(attr.id)}</div>
          <div style="display:flex;gap:4px;align-items:center;">
            <button data-gdl-control="${attr.id}-minus" onclick="ajustarBonusGuerreiro('${attr.id}',-1)" ${valor===0?'disabled':''}
              style="width:24px;height:24px;background:transparent;border:1px solid ${valor>0?'#c8a951':'#2a2a2a'};
              color:${valor>0?'#c8a951':'#4a4a4a'};cursor:${valor>0?'pointer':'not-allowed'};font-size:14px;line-height:1;">−</button>
            <span style="color:#c8a951;font-size:13px;font-weight:bold;min-width:16px;text-align:center;">${valor}</span>
            <button data-gdl-control="${attr.id}-plus" onclick="ajustarBonusGuerreiro('${attr.id}',1)" ${valor>=attr.max?'disabled':''}
              style="width:24px;height:24px;background:transparent;border:1px solid ${valor<attr.max?'#c8a951':'#2a2a2a'};
              color:${valor<attr.max?'#c8a951':'#4a4a4a'};cursor:${valor<attr.max?'pointer':'not-allowed'};font-size:14px;line-height:1;">+</button>
          </div>
          <span style="color:#8a7a5a;font-size:9px;min-width:38px;text-align:right;">${valor>0?`${cl}-${valor}/t`:''}</span>
        </div>`;
    }).join('');

    painel.innerHTML = `
      <div style="font-family:'Cinzel Decorative',serif;color:#c8a951;font-size:13px;margin-bottom:6px;text-align:center;">${t('ui.paladino.luz_titulo')}</div>
      <div style="color:#8a7a5a;font-size:9px;letter-spacing:2px;margin-bottom:12px;text-align:center;">${t('ui.paladino.luz_subtitulo')}</div>
      <div style="margin-bottom:8px;">${linhas}</div>
      <div style="padding:8px 10px;margin-bottom:8px;background:rgba(255,133,27,0.06);border:1px solid #ff851b33;display:flex;justify-content:space-between;">
        <span style="color:#8a7a5a;font-size:9px;letter-spacing:2px;">${t('ui.paladino.custo_turno')}</span>
        <span style="color:#ff851b;font-size:10px;">${(custo.fome||custo.sede)?`${custo.fome?`🍖-${custo.fome} `:''}${custo.sede?`💧-${custo.sede}`:''}`:t('ui.paladino.selecione_bonus')}</span>
      </div>
      <div style="display:flex;gap:6px;">
        <button data-gdl-control="cancelar" onclick="document.getElementById('painel-guerreiro-luz').remove()" style="flex:1;padding:8px;background:transparent;border:1px solid #4a4a4a;color:#8a7a5a;font-family:'Cinzel',serif;font-size:10px;letter-spacing:2px;cursor:pointer;">${t('ui.geral.cancelar_caixa')}</button>
        <button data-gdl-control="confirmar" onclick="confirmarGuerreiroLuz()" ${(custo.fome+custo.sede)===0?'disabled':''} style="flex:2;padding:8px;background:${(custo.fome+custo.sede)>0?'rgba(200,169,81,0.15)':'transparent'};border:1px solid ${(custo.fome+custo.sede)>0?'#c8a951':'#4a4a4a'};color:${(custo.fome+custo.sede)>0?'#c8a951':'#4a4a4a'};font-family:'Cinzel',serif;font-size:10px;letter-spacing:2px;cursor:${(custo.fome+custo.sede)>0?'pointer':'not-allowed'};">${t('ui.paladino.ativar')}</button>
      </div>`;
    if(_gamepadInput.active && painel.isConnected){
      const alvo = painel.querySelector(`[data-gdl-control="${gamepadFocusKey}"]:not(:disabled)`)
        || painel.querySelector('[data-gdl-control="visao-plus"]:not(:disabled)')
        || painel.querySelector('button:not(:disabled)');
      if(alvo) _gamepadSetUiFocus(alvo);
    }
  }
  render();
  document.body.appendChild(painel);
  if(_gamepadInput.active) _gamepadSetUiFocus(painel.querySelector('[data-gdl-control="visao-plus"]'));

  window.ajustarBonusGuerreiro = (id, delta) => {
    const focado = _gamepadUi.focusEl?.dataset?.gdlControl || document.activeElement?.dataset?.gdlControl;
    if(focado) gamepadFocusKey = focado;
    const attr = GUERREIRO_LUZ_BONUS_CLIENT.find(a => a.id === id);
    if(!attr) return;
    // Teto de atributos simultâneos (Fase 1c): ativar um NOVO atributo (0→>0)
    // além do limite possuído é bloqueado; o servidor também recusa (autoritativo).
    if(delta > 0 && _bonusGuerreiro[id] === 0){
      const cap = GS.paladinLuzMaxAtributos ? GS.paladinLuzMaxAtributos() : 2;
      const ativos = Object.values(_bonusGuerreiro).filter(v => v > 0).length;
      if(ativos >= cap){
        toast(t('ui.paladino.guerreiro_luz_permite', {n: cap}), 'var(--gold)');
        return;
      }
    }
    _bonusGuerreiro[id] = Math.max(0, Math.min(attr.max, _bonusGuerreiro[id] + delta));
    render();
  };
  window.confirmarGuerreiroLuz = () => {
    const custo = calcularCusto();
    if(custo.fome + custo.sede === 0) return;
    send({ type:'acao_livre_richard', habilidade_id:'guerreiro_luz', bonus:_bonusGuerreiro });
    document.getElementById('painel-guerreiro-luz')?.remove();
  };
}

// Aliados vivos (exceto Richard) dentro de `raio` (Chebyshev) da posição de me.
function _aliadosNoRaioPaladin(me, raio){
  const st = GS.gameState; if(!st) return [];
  const pp = me.pos || [0,0];
  const alvos = (st.players || []).filter(a => a && a.alive && a.id !== me.id && a.pos &&
    Math.max(Math.abs(pp[0]-a.pos[0]), Math.abs(pp[1]-a.pos[1])) <= _alcanceComAlturaCli(me, raio, a));
  const pr = st.prisoner;
  if(pr && pr.alive && pr.freed && pr.pos &&
      Math.max(Math.abs(pp[0]-pr.pos[0]), Math.abs(pp[1]-pr.pos[1])) <= _alcanceComAlturaCli(me, raio, pr)){
    alvos.push({...pr, id:'__prisioneiro__', name:pr.nome || t('ui.hud.prisioneiro'), emoji:'🔗'});
  }
  return alvos;
}

// Protetor — ação bônus. Escolhe aliado/prisioneiro via modal.
function iniciarModoProtetor(){
  const me = GS.me;
  if(!me || me.class_id !== 'paladin') return;
  if(!GS.isMyTurn || me.alive === false || (GS.gameState && GS.gameState.phase !== 'playing')){
    toast(t('ui.paladino.protetor_so_turno'), 'var(--orange)'); return;
  }
  if(me.bonus_action_used){ toast(t('ui.hud.acao_bonus_ja_usada'), 'var(--orange)'); return; }
  if(me.fome < 2 || me.sede < 2){ toast(t('ui.hud.protetor_requer_2_e_2'), 'var(--orange)'); return; }
  const raio = GS.paladinDefensorRaio ? GS.paladinDefensorRaio() : 4;
  const alvos = _aliadosNoRaioPaladin(me, raio);
  if(!alvos.length){ toast(t('ui.hud.sem_aliado_raio4'), 'var(--orange)'); return; }
  if(alvos.length === 1){ send({ type:'protetor', target_id:alvos[0].id }); return; }
  openTargetModal(t('ui.paladino.protetor_escolha_aliado', {raio}), alvos, 'player',
    id => send({ type:'protetor', target_id:id }));
}

// Imposição das Mãos — ação principal (aliado adjacente, raio 1).
function iniciarModoImposicaoMaos(){
  const me = GS.me;
  if(!me || me.class_id !== 'paladin') return;
  if(!GS.isMyTurn || me.alive === false || (GS.gameState && GS.gameState.phase !== 'playing')){
    toast(t('ui.paladino.imposicao_so_turno'), 'var(--orange)'); return;
  }
  if(me.action_done){ toast(t('ui.hud.acao_principal_ja_usada'), 'var(--orange)'); return; }
  if(me.fome < 3 || me.sede < 2){ toast(t('ui.paladino.imposicao_custo'), 'var(--orange)'); return; }
  const alvos = _aliadosNoRaioPaladin(me, 1);
  if(!alvos.length){ toast(t('ui.hud.sem_aliado_adjacente'), 'var(--orange)'); return; }
  if(alvos.length === 1){ _enviarImposicaoMaos(alvos[0].id); return; }
  openTargetModal(t('ui.paladino.imposicao_titulo'), alvos, 'player',
    id => _enviarImposicaoMaos(id));
}

// Cura pelas Mãos III (opcional): +1d6 por +2🍖/+2💧, até 3×. Sem a especialização
// envia extra_d6:0 direto (fluxo idêntico ao anterior).
function _enviarImposicaoMaos(targetId){
  if(!GS.paladinCuraMaosExtra || !GS.paladinCuraMaosExtra()){
    send({ type:'imposicao_maos', target_id:targetId, extra_d6:0 }); return;
  }
  document.getElementById('painel-imposicao-extra')?.remove();
  let extra = 0;
  const painel = document.createElement('div');
  painel.id = 'painel-imposicao-extra';
  painel.style.cssText =
    "position:fixed;bottom:180px;left:50%;transform:translateX(-50%);" +
    "background:rgba(10,8,5,0.97);border:1px solid #c8a951;width:280px;" +
    "z-index:3000;padding:16px;font-family:'Cinzel',serif;box-shadow:0 0 24px rgba(0,0,0,0.7);";
  function render(){
    const custoFome = 3 + 2*extra, custoSede = 2 + 2*extra;
    painel.innerHTML = `
      <div style="font-family:'Cinzel Decorative',serif;color:#c8a951;font-size:13px;margin-bottom:8px;text-align:center;">${t('ui.paladino.imposicao_painel_titulo')}</div>
      <div style="color:#8a7a5a;font-size:9px;letter-spacing:2px;margin-bottom:10px;text-align:center;">${t('ui.paladino.imposicao_extra')}</div>
      <div style="display:flex;align-items:center;gap:10px;padding:8px 10px;margin-bottom:10px;background:rgba(200,169,81,0.06);border:1px solid #c8a95133;">
        <button onclick="window._imposicaoExtraAjustar(-1)" ${extra===0?'disabled':''}
          style="width:26px;height:26px;background:transparent;border:1px solid ${extra>0?'#c8a951':'#2a2a2a'};color:${extra>0?'#c8a951':'#4a4a4a'};cursor:${extra>0?'pointer':'not-allowed'};font-size:15px;">−</button>
        <span style="flex:1;text-align:center;color:#c8a951;font-size:13px;">${t('ui.paladino.dados_extra', {n:extra})}</span>
        <button onclick="window._imposicaoExtraAjustar(1)" ${extra>=3?'disabled':''}
          style="width:26px;height:26px;background:transparent;border:1px solid ${extra<3?'#c8a951':'#2a2a2a'};color:${extra<3?'#c8a951':'#4a4a4a'};cursor:${extra<3?'pointer':'not-allowed'};font-size:15px;">+</button>
      </div>
      <div style="padding:8px 10px;margin-bottom:10px;background:rgba(255,133,27,0.06);border:1px solid #ff851b33;display:flex;justify-content:space-between;">
        <span style="color:#8a7a5a;font-size:9px;letter-spacing:2px;" data-i18n="ui.hud.custo_total">CUSTO TOTAL</span>
        <span style="color:#ff851b;font-size:10px;">🍖-${custoFome} 💧-${custoSede}</span>
      </div>
      <div style="display:flex;gap:6px;">
        <button onclick="document.getElementById('painel-imposicao-extra').remove()" style="flex:1;padding:8px;background:transparent;border:1px solid #4a4a4a;color:#8a7a5a;font-family:'Cinzel',serif;font-size:10px;letter-spacing:2px;cursor:pointer;" data-i18n="ui.geral.cancelar_caixa">CANCELAR</button>
        <button onclick="window._imposicaoExtraConfirmar()" style="flex:2;padding:8px;background:rgba(200,169,81,0.15);border:1px solid #c8a951;color:#c8a951;font-family:'Cinzel',serif;font-size:10px;letter-spacing:2px;cursor:pointer;" data-i18n="ui.hud.curar">🙏 CURAR</button>
      </div>`;
  }
  render();
  document.body.appendChild(painel);
  window._imposicaoExtraAjustar = (delta) => { extra = Math.max(0, Math.min(3, extra + delta)); render(); };
  window._imposicaoExtraConfirmar = () => {
    send({ type:'imposicao_maos', target_id:targetId, extra_d6:extra });
    document.getElementById('painel-imposicao-extra')?.remove();
  };
}

// Indicador de visão expandida — mostrado no botão ativo do Guerreiro da Luz.
function renderIndicadorVisao(me){
  if(me.class_id !== 'paladin' || !me.guerreiro_luz_ativo) return '';
  const bonusVisao = me.guerreiro_luz_bonus?.visao || 0;
  if(bonusVisao === 0) return '';
  return `<div style="color:#c8a951;font-size:9px;letter-spacing:1px;margin-top:3px;">${t('ui.hud.visao_mais', {n:bonusVisao})}</div>`;
}

// Botão de habilidade do paladino (dedicado, fora do fluxo MP/toggle genérico).
function _paladinSkillBtn(me, sk){
  const btn = document.createElement('button');
  const myTurnPlay = GS.isMyTurn && me.alive && GS.gameState && GS.gameState.phase === 'playing';
  const fc = sk.fome_cost ?? 0, scst = sk.sede_cost ?? 0;
  const costStr = [fc?`🍖${fc}`:'', scst?`💧${scst}`:''].filter(Boolean).join(' ') || '—';
  const temRec  = me.fome >= fc && me.sede >= scst;

  const setBtn = (name, desc, cost, disabled, onclick, active) => {
    btn.className = 'skill-btn' + (active ? ' skill-active' : '');
    btn.disabled  = !!disabled;
    btn.innerHTML = `
      <div class="skill-info">
        <div class="skill-name" data-ability-id="${sk.id || ''}">${name}</div>
        <div class="skill-desc">${desc}</div>
      </div>
      <div class="skill-cost">${cost}</div>`;
    if(onclick) btn.onclick = onclick;
  };

  if(sk.id === 'guerreiro_luz'){
    if(me.guerreiro_luz_ativo){
      const b = me.guerreiro_luz_bonus || {};
      const c = me.guerreiro_luz_custo || {fome:0, sede:0};
      const lbls = Object.entries(b).filter(([,v]) => v>0).map(([k,v]) => `+${v} ${k}`).join(' • ');
      setBtn(`💡 ${sk.name} <small style="color:var(--gold);font-size:.65rem;">● ${t('ui.hud.ativo')}</small>`,
             (lbls || '—') + renderIndicadorVisao(me), `🍖${c.fome} 💧${c.sede}<br><small style="font-size:.6rem;">${t('ui.hud.parar')}</small>`,
             false, () => send({type:'acao_livre_richard', habilidade_id:'guerreiro_luz'}), true);
    } else {
      const _capLuz = GS.paladinLuzMaxAtributos ? GS.paladinLuzMaxAtributos() : 2;
      setBtn(`💡 ${sk.name} <small style="color:var(--text2);font-size:.62rem;">livre</small>`,
             t('ui.hud.ate_atributos',{n:_capLuz}), 'escolher', !myTurnPlay,
             () => abrirPainelGuerreiroLuz(), false);
    }
  } else if(sk.id === 'regeneracao_divina'){
    const _raioRegen = GS.paladinRegenRaio ? GS.paladinRegenRaio() : 0;
    const _descRegen = _raioRegen > 0 ? t('ui.paladino.regen_aliados_raio', {raio: _raioRegen}) : t('ui.paladino.1_hp_por_turno');
    if(me.regeneracao_ativa){
      setBtn(`✨ ${sk.name} <small style="color:var(--gold);font-size:.65rem;">● ${t('ui.hud.ativa')}</small>`,
             _descRegen, `🍖1 💧1<br><small style="font-size:.6rem;">${t('ui.hud.parar')}</small>`,
             false, () => send({type:'acao_livre_richard', habilidade_id:'regeneracao_divina'}), true);
    } else {
      const hpFull = (me.hp != null && me.max_hp != null && me.hp >= me.max_hp);
      const aviso  = hpFull ? ' <small style="color:var(--text2);font-size:.62rem;">HP cheio</small>'
                   : !temRec ? ' <small style="color:var(--red);font-size:.62rem;">'+t('ui.hud.sem_recursos')+'</small>' : '';
      setBtn(`✨ ${sk.name}${aviso}`, _descRegen, costStr,
             !myTurnPlay || hpFull, () => send({type:'acao_livre_richard', habilidade_id:'regeneracao_divina'}), false);
    }
  } else if(sk.id === 'golpe_sagrado'){
    const _dadosSagrado = GS.paladinAtaqueSagradoDados ? GS.paladinAtaqueSagradoDados() : 1;
    const _nivelSagrado = me.golpe_sagrado_ativo
      ? (Number(me.golpe_sagrado_nivel) || 1)
      : (GS.paladinAtaqueSagradoNivel ? GS.paladinAtaqueSagradoNivel() : 1);
    const _manutSagrado = {1:[1,1],2:[2,1],3:[2,2]}[_nivelSagrado] || [1,1];
    const _tipoSagradoId = ({fogo:'fogo', gelo:'gelo', eletricidade:'eletricidade', sagrado:'sagrado', fire:'fogo', cold:'gelo', lightning:'eletricidade', holy:'sagrado'})[me.golpe_sagrado_tipo_extra] || '';
    const _tipoSagrado = _tipoSagradoId ? t(`ui.paladino.tipo_${_tipoSagradoId}`) : '';
    if(me.golpe_sagrado_ativo){
      const _descSagrado = _nivelSagrado >= 3
        ? t('ui.paladino.golpe_extra_por_ataque', {tipo:_tipoSagrado || t('ui.paladino.tipo_escolhido')})
        : t('ui.paladino.d8_sagrado_por_ataque', {n:_dadosSagrado});
      setBtn(`⚔️ ${sk.name} <small style="color:var(--gold);font-size:.65rem;">● ${t('ui.hud.ativo')}</small>`,
             _descSagrado, `manut. 🍖${_manutSagrado[0]} 💧${_manutSagrado[1]}<br><small style="font-size:.6rem;">${t('ui.hud.parar')}</small>`,
             false, () => send({type:'desativar_golpe_sagrado'}), true);
    } else {
      const pode  = myTurnPlay && !me.bonus_action_used && temRec;
      const aviso = me.bonus_action_used ? ` <small style="color:var(--text2);font-size:.62rem;">${t('ui.hud.bonus_usado')}</small>`
                  : !temRec ? ' <small style="color:var(--red);font-size:.62rem;">'+t('ui.hud.sem_recursos')+'</small>' : '';
      setBtn(`⚔️ ${sk.name}${aviso}`, sk.description || sk.desc || '', t('ui.paladino.escolher_nivel'), !pode,
             () => _abrirPainelEscolhaGolpeSagrado((nivel, tipo) => send({type:'golpe_sagrado', nivel, tipo_extra:tipo})), false);
    }
  } else if(sk.id === 'protetor'){
    const _raioDef  = GS.paladinDefensorRaio  ? GS.paladinDefensorRaio()  : 4;
    const _nivelDef = GS.paladinDefensorNivel ? GS.paladinDefensorNivel() : 1;
    const _splitDef = _nivelDef === 3 ? '50/50' : t('ui.paladino.split_defensor', {split: _nivelDef === 2 ? '65/35' : '75/25'});
    if(me.protetor_ativo){
      const alvo = (GS.gameState?.players || []).find(p => String(p.id) === String(me.protetor_alvo))
        || (GS.gameState?.prisoner && String(me.protetor_alvo) === '__prisioneiro__'
          ? {name:GS.gameState.prisoner.nome || t('ui.paladino.prisioneiro')} : null);
      setBtn(`🛡️ ${sk.name} <small style="color:var(--gold);font-size:.65rem;">● ${t('ui.hud.ativo')}</small>`,
             alvo ? `protegendo ${alvo.name} (${_splitDef})` : '—',
             `manut. 🍖1<br><small style="font-size:.6rem;">${t('ui.hud.parar')}</small>`,
             false, () => send({type:'desativar_protetor'}), true);
    } else {
      const pode  = myTurnPlay && !me.bonus_action_used && temRec;
      const aviso = me.bonus_action_used ? ` <small style="color:var(--text2);font-size:.62rem;">${t('ui.hud.bonus_usado')}</small>`
                  : !temRec ? ' <small style="color:var(--red);font-size:.62rem;">'+t('ui.hud.sem_recursos')+'</small>' : '';
      setBtn(`🛡️ ${sk.name}${aviso}`, `${sk.description || sk.desc || ''} (raio ${_raioDef}; ${_splitDef})`, costStr, !pode,
             () => iniciarModoProtetor(), false);
    }
  } else if(sk.id === 'imposicao_maos'){
    const pode  = myTurnPlay && !me.action_done && temRec;
    const aviso = me.action_done ? ` <small style="color:var(--text2);font-size:.62rem;">${t('ui.hud.acao_usada')}</small>`
                : !temRec ? ' <small style="color:var(--red);font-size:.62rem;">'+t('ui.hud.sem_recursos')+'</small>' : '';
    const _dadosCura = GS.paladinCuraMaosDados ? GS.paladinCuraMaosDados() : 1;
    setBtn(`🙏 ${sk.name}${aviso}`, `${_dadosCura}d6 + FOR`, costStr, !pode,
           () => iniciarModoImposicaoMaos(), false);
  } else {
    setBtn(`${sk.icon || ''} ${sk.name}`, sk.description || sk.desc || '', costStr, !myTurnPlay, null, false);
  }
  return btn;
}

window.abrirPainelGuerreiroLuz  = abrirPainelGuerreiroLuz;
window.iniciarModoProtetor      = iniciarModoProtetor;
window.iniciarModoImposicaoMaos = iniciarModoImposicaoMaos;

// ═══════════════════════════════════════════════════════════════════════════
// LADINO (Luccas) — habilidades no cliente. Integra com os sistemas de venenos
// (CATALOGO_ITENS / weapon_poison) e armadilhas (game_state.armadilhas) já
// implementados no servidor. Convenções reais: me.class_id, me.pos[0/1],
// me.level, me.weapon_poison/_hits, arm.pos. Mensagens: detectar_armadilhas,
// esconder_sombras, veneno_rapido (livre), criar_armadilha, desarmar_armadilha.
// ═══════════════════════════════════════════════════════════════════════════

// Custos das armadilhas — alinhados ao servidor (ARMADILHA_CUSTO_FOME=2/SEDE=1
// + custo_ouro por tipo em ARMADILHAS).
const ARMADILHAS_LUCCAS = [
  { id:'buraco',                 nome:'Buraco',                icone:'🕳️', custo_ouro:0,  desc:'Reflexos dif 10 ou perde movimento. Permanente.' },
  { id:'armadilha_urso',         nome:'Armadilha de Urso',     icone:'🪤', custo_ouro:1,  desc:'1d4 dano + perde movimento. Some após ativar.' },
  { id:'fosso_estacas',          nome:'Fosso com Estacas',     icone:'⛏️', custo_ouro:2,  desc:'1d6 dano + perde movimento. Fica visível após ativar.' },
  { id:'rede',                   nome:'Rede',                  icone:'🕸️', custo_ouro:4,  desc:'Perde a rodada inteira. Some após ativar.' },
  { id:'armadilha_incendiaria',  nome:'Armadilha Incendiária', icone:'🔥', custo_ouro:10, desc:'1d6+1d4+1 fogo em 3 rodadas. Some após ativar.' },
  { id:'mina_terrestre',         nome:'Mina Terrestre',        icone:'💣', custo_ouro:20, desc:'2d6 em área (1 quad). Save reduz à metade. Some após ativar.' },
  { id:'fosso_envenenado',       nome:'Fosso Envenenado',      icone:'☠️', custo_ouro:2,  requer_veneno:true, desc:'1d6 dano + veneno escolhido. Fica visível após ativar.' },
  { id:'lamina_escondida',       nome:'Lâmina Escondida',      icone:'🗡️', custo_ouro:8,  permite_veneno:true, desc:'Reflexos dif 15 ou sofre 1d8. Veneno opcional. Some após ativar.' },
  { id:'lamina_pendulo',         nome:'Lâmina Pêndulo',        icone:'🗡️', custo_ouro:12, desc:'Reflexos dif 14 ou sofre 2d6. Permanece ativa por 3 rodadas.' },
  { id:'nuvem_gas',              nome:'Nuvem de Gás',          icone:'🌫️', custo_ouro:25, desc:'-1d6 CON por 3 rodadas em área. Save Fortitude dif 13.' },
  { id:'camara_gas',             nome:'Câmara de Gás',          icone:'☠️', custo_ouro:30, desc:'Ao ativar, afeta toda a sala por 1d6+1 rodadas. Fortitude CD 13 a cada turno; falha causa 1d6 de dano.' },
  { id:'jato_acido',             nome:'Jato de Ácido',         icone:'🧪', custo_ouro:15, desc:'Reflexos CD 18 evita. Na falha, 2d6 ácido + 1 nível de corrosão em equipamento; metade do dano na rodada seguinte.' },
  { id:'armadilha_raio_congelante', nome:'Armadilha de Raio Congelante', icone:'❄️', custo_ouro:25, desc:'3d4 de dano de gelo. Fortitude CD 15 evita a paralisia; escape com Força CD 16.' },
  { id:'teto_esmagador',         nome:'Teto Esmagador',         icone:'🪨', custo_ouro:30, desc:'Ao ativar, afeta toda a sala. Reflexos CD 20 evita; na falha, sofre 4d6 de dano.' },
  { id:'bau_engolidor',          nome:'Baú Engolidor',          icone:'📦', custo_ouro:35, apenas_objeto:true, desc:'Só pode ser colocado em um objeto. Reflexos CD 20 evita; na falha, fica preso até passar em Força CD 20.' },
  { id:'guilhotina',              nome:'Guilhotina',              icone:'🪓', custo_ouro:18, desc:'Reflexos CD 14 evita. Na falha, sofre 3d6 de dano.' },
  { id:'fosso',                   nome:'Fosso',                   icone:'🕳️', custo_ouro:8,  desc:'Reflexos CD 15 evita. Na falha, sofre 1d6, perde o movimento e a próxima rodada; fica oculto e protegido nesse período.' },
];
const ARMADILHA_FOME = 2, ARMADILHA_SEDE = 1;

// Venenos na bolsa — o servidor manda itens com `id`/`veneno_id`, sem `tipo`;
// cruzamos com CATALOGO_ITENS p/ nome/descrição/ícone. Retorna lista normalizada.
function _venenosNaBolsa(me){
  const cat = (window.GS && GS.CATALOGO_ITENS) ? GS.CATALOGO_ITENS : {};
  const out = [];
  for(const it of (me && me.bag || [])){
    if(!it) continue;
    const c = cat[it.id] || (it.veneno_id ? cat[it.veneno_id] : null);
    const ehVeneno = it.tipo === 'veneno' || (c && c.tipo === 'veneno') || !!it.veneno_id;
    if(!ehVeneno) continue;
    out.push({
      id:        it.veneno_id || it.id,   // server casa por veneno_id OU id
      nome:      it.nome || it.name || (c && c.nome) || it.id,
      descricao: it.descricao || (c && c.descricao) || '',
      icone:     it.icone || it.emoji || (c && c.icone) || '☠️',
    });
  }
  return out;
}

function _rogueMyTurn(me){
  return !!(GS.isMyTurn && me && me.alive !== false && GS.gameState && GS.gameState.phase === 'playing');
}

// ── Painel: Criar Armadilha (ação principal) ────────────────────────────────
function abrirPainelCriarArmadilha(){
  const existente = document.getElementById('painel-armadilha');
  if(existente){ existente.remove(); return; }

  const me = GS.me;
  if(!me || me.class_id !== 'rogue') return;
  if(!_rogueMyTurn(me)){ toast(t('ui.hud.so_no_seu_turno'), 'var(--orange)'); return; }
  if(me.action_done){ GS.adicionarLog(t('ui.hud.log_acao_principal_usada')); return; }

  const ouro    = me.gold || 0;
  const venenos = _venenosNaBolsa(me);
  let selecionada = null;
  let veneno_id   = null;

  const painel = document.createElement('div');
  painel.id = 'painel-armadilha';
  painel.style.cssText = `position:fixed; bottom:180px; left:50%; transform:translateX(-50%);
    background:rgba(10,8,5,0.97); border:1px solid #c8a951; width:320px; max-height:70vh;
    overflow-y:auto; z-index:200; padding:16px; font-family:'Cinzel',serif;`;

  function renderPainel(){
    painel.innerHTML = `
      <div style="font-family:'Cinzel Decorative',serif; color:#c8a951; font-size:13px; margin-bottom:12px; text-align:center;">${t('ui.ladino.criar_armadilha_titulo')}</div>
      <div style="color:#8a7a5a; font-size:9px; letter-spacing:2px; margin-bottom:10px; text-align:center;">${t('ui.ladino.criar_armadilha_custo', {ouro, fome:ARMADILHA_FOME, sede:ARMADILHA_SEDE})}</div>
      ${ARMADILHAS_LUCCAS.map(arm => {
        const desbloqueada = (GS.ladinoArmadilhasDesbloqueadas ? GS.ladinoArmadilhasDesbloqueadas() : ['buraco']).includes(arm.id);
        const podeComprar = ouro >= arm.custo_ouro;
        const escolheVeneno = arm.requer_veneno || arm.permite_veneno;
        const temVeneno   = arm.requer_veneno ? venenos.length > 0 : true;
        const pode        = desbloqueada && podeComprar && temVeneno;
        const sel         = selecionada === arm.id;
        return `
          <div ${pode ? `onclick="selecionarArmadilha('${arm.id}')"` : ''} style="
            padding:10px 12px; margin-bottom:4px;
            background:${sel ? 'rgba(200,169,81,0.15)' : 'rgba(255,255,255,0.02)'};
            border:1px solid ${sel ? '#c8a951' : pode ? '#2a2a2a' : '#1a1a1a'};
            cursor:${pode ? 'pointer' : 'not-allowed'}; opacity:${pode ? 1 : 0.4};">
            <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:3px;">
              <span style="color:${sel ? '#c8a951' : '#c8b89a'}; font-size:12px;">${arm.icone} ${arm.nome}</span>
              <span style="color:#c8a951; font-size:11px;">${arm.custo_ouro}🪙</span>
            </div>
            <div style="color:#8a7a5a; font-size:9px; line-height:1.5;">${arm.desc}</div>
            ${!desbloqueada ? `<div style="color:#ff851b; font-size:9px; margin-top:3px;">${t('ui.ladino.compre_formula')}</div>` : ''}
            ${desbloqueada && escolheVeneno ? `<div style="color:${arm.requer_veneno && !venenos.length ? '#ff4136' : '#9900cc'}; font-size:9px; margin-top:3px;">${arm.requer_veneno ? t(venenos.length>0?'ui.ladino.requer_veneno_ok':'ui.ladino.requer_veneno_falta') : t('ui.ladino.veneno_opcional')}</div>` : ''}
          </div>`;
      }).join('')}
      ${selecionada && ((ARMADILHAS_LUCCAS.find(a=>a.id===selecionada)?.requer_veneno) || (ARMADILHAS_LUCCAS.find(a=>a.id===selecionada)?.permite_veneno)) ? `
        <div style="margin-top:10px;">
          <div style="color:#9900cc; font-size:9px; letter-spacing:2px; margin-bottom:6px;" data-i18n="ui.armadilha.escolha_o_veneno">ESCOLHA O VENENO:</div>
          ${venenos.map(v => `
            <div onclick="selecionarVenenoPara('${v.id}')" style="
              padding:6px 10px; margin-bottom:3px;
              background:${veneno_id===v.id?'rgba(150,0,200,0.15)':'rgba(255,255,255,0.02)'};
              border:1px solid ${veneno_id===v.id?'#9900cc':'#2a2a2a'}; cursor:pointer;">
              <span style="color:#c8b89a; font-size:10px;">${v.icone} ${v.nome}</span>
            </div>`).join('')}
        </div>` : ''}
      <div style="display:flex; gap:6px; margin-top:12px;">
        <button onclick="document.getElementById('painel-armadilha').remove()" style="flex:1; padding:8px; background:transparent; border:1px solid #4a4a4a; color:#8a7a5a; font-family:'Cinzel',serif; font-size:10px; letter-spacing:2px; cursor:pointer;" data-i18n="ui.geral.cancelar_caixa">CANCELAR</button>
        <button onclick="confirmarCriarArmadilha()" ${!selecionada ? 'disabled' : ''} style="flex:2; padding:8px;
          background:${selecionada?'rgba(200,169,81,0.15)':'transparent'};
          border:1px solid ${selecionada?'#c8a951':'#4a4a4a'};
          color:${selecionada?'#c8a951':'#4a4a4a'}; font-family:'Cinzel',serif; font-size:10px; letter-spacing:2px; cursor:pointer;" data-i18n="ui.armadilha.posicionar">🪤 POSICIONAR</button>
      </div>`;
  }

  renderPainel();
  document.body.appendChild(painel);

  window.selecionarArmadilha = function(id){ selecionada = (selecionada === id ? null : id); veneno_id = null; renderPainel(); };
  window.selecionarVenenoPara = function(vid){ veneno_id = vid; renderPainel(); };
  window.confirmarCriarArmadilha = function(){
    if(!selecionada) return;
    const arm = ARMADILHAS_LUCCAS.find(a => a.id === selecionada);
    if(arm?.requer_veneno && !veneno_id){ GS.adicionarLog(t('ui.armadilha.escolha_um_veneno_para_a_armadilha')); return; }
    document.getElementById('painel-armadilha')?.remove();
    _ativarModoPlacementArmadilha(selecionada, veneno_id);
  };
}

function _ativarModoPlacementArmadilha(tipoId, venenoId){
  window._modoPlacementArmadilha = { tipoId, venenoId };
  const meta = ARMADILHAS_LUCCAS.find(a => a.id === tipoId);
  const me = GS.me;
  const range = new Set(), area = new Set();
  if (me?.pos) {
    _addCheb(me.pos[0], me.pos[1], 1, range);
    if (meta?.apenas_objeto) {
      for (const decor of GS.decorations || []) {
        if (decor.pisavel) continue;
        for (const [x, y] of GS.decorTilesOf(decor)) if (range.has(`${x},${y}`)) area.add(`${x},${y}`);
      }
    } else {
      for (const key of range) area.add(key);
    }
  }
  _aimStart({
    kind: 'armadilha', title: `🪤 ${meta?.nome || t('ui.armadilha.posicionar_armadilha')}`,
    instruction: meta?.apenas_objeto ? t('ui.armadilha.selecione_um_objeto_solido_adjacente') : t('ui.armadilha.selecione_a_sua_casa_ou_uma_casa_adjacente'),
    color: '#c8a951', targetLabel: meta?.apenas_objeto ? t('ui.armadilha.objeto') : t('ui.armadilha.casa'), range, area,
    cancelText: t('ui.armadilha.posicionamento_de_armadilha_cancelado'),
    cleanup: () => { window._modoPlacementArmadilha = null; },
  });
}

function _cancelarPlacementArmadilha(){
  if(_aimSessionIs('armadilha')) { _aimEnd({ silent:true, reason:'resolved' }); return; }
  window._modoPlacementArmadilha = null;
  try { if(g3 && g3.renderer) g3.renderer.domElement.style.cursor = 'default'; } catch(e){}
  document.getElementById('legenda-armadilha')?.remove();
}

function onClickTileParaArmadilha(tx, ty){
  if(!window._modoPlacementArmadilha) return;
  const { tipoId, venenoId } = window._modoPlacementArmadilha;
  const meta = ARMADILHAS_LUCCAS.find(a => a.id === tipoId);
  if(meta?.apenas_objeto){
    const objetos = (GS.decorations || []).filter(d =>
      GS.decorTilesOf(d).some(([x,y]) => x === tx && y === ty) && !d.pisavel);
    const objeto = objetos[0];
    if(!objeto){
      _aimSetStatus(t('ui.armadilha.selecione_um_objeto_solido_adjacente'), '#ffb168');
      toast(t('ui.armadilha.selecione_um_objeto_ao_alcance'), 'var(--orange)'); return;
    }
    send({ type:'criar_armadilha', tipo:tipoId, decor_id:objeto.id, tx:tx, ty:ty, veneno_id:venenoId || null });
  } else {
    send({ type:'criar_armadilha', tipo:tipoId, tx:tx, ty:ty, veneno_id:venenoId || null });
  }
  _cancelarPlacementArmadilha();
}

// ── Painel: Veneno Rápido (ação livre) ──────────────────────────────────────
function abrirPainelVenenoRapido(){
  const existente = document.getElementById('painel-veneno-rapido');
  if(existente){ existente.remove(); return; }

  const me = GS.me;
  if(!me || me.class_id !== 'rogue') return;
  if(!_rogueMyTurn(me)){ toast(t('ui.hud.so_no_seu_turno'), 'var(--orange)'); return; }
  if((me.sede||0) < 1){ GS.adicionarLog(t('ui.ladino.sede_insuficiente')); return; }

  const venenos = _venenosNaBolsa(me);
  if(venenos.length === 0){ GS.adicionarLog(t('ui.ladino.sem_venenos')); return; }

  const painel = document.createElement('div');
  painel.id = 'painel-veneno-rapido';
  painel.style.cssText = `position:fixed; bottom:180px; left:50%; transform:translateX(-50%);
    background:rgba(10,8,5,0.97); border:1px solid #9900cc; width:280px; z-index:200; padding:16px;
    font-family:'Cinzel',serif;`;
  painel.innerHTML = `
    <div style="font-family:'Cinzel Decorative',serif; color:#cc44ff; font-size:13px; margin-bottom:12px; text-align:center;">${t('ui.ladino.veneno_rapido_titulo')}</div>
    <div style="color:#8a7a5a; font-size:9px; letter-spacing:2px; margin-bottom:10px; text-align:center;">${t('ui.ladino.veneno_rapido_custo')}</div>
    ${venenos.map(v => `
      <div onclick="confirmarVenenoRapido('${v.id}')" style="padding:10px 12px; margin-bottom:4px;
        background:rgba(150,0,200,0.06); border:1px solid #9900cc44; cursor:pointer; transition:all 0.2s;"
        onmouseover="this.style.borderColor='#9900cc'" onmouseout="this.style.borderColor='#9900cc44'">
        <div style="color:#cc44ff; font-size:11px; margin-bottom:3px;">${v.icone} ${v.nome}</div>
        <div style="color:#8a7a5a; font-size:9px;">${v.descricao || ''}</div>
      </div>`).join('')}
    <button onclick="document.getElementById('painel-veneno-rapido').remove()" style="width:100%; margin-top:10px; padding:8px; background:transparent; border:1px solid #4a4a4a; color:#8a7a5a; font-family:'Cinzel',serif; font-size:10px; letter-spacing:2px; cursor:pointer;" data-i18n="ui.geral.cancelar_caixa">CANCELAR</button>`;
  document.body.appendChild(painel);

  window.confirmarVenenoRapido = function(venenoId){
    send({ type:'veneno_rapido', veneno_id:venenoId });
    document.getElementById('painel-veneno-rapido')?.remove();
  };
}

// ── Botões de habilidade do ladino (padrão skill-btn, como _paladinSkillBtn) ──
function _rogueSkillBtn(me, sk){
  const btn = document.createElement('button');
  const myTurnPlay = _rogueMyTurn(me);
  const fc = sk.fome_cost ?? 0, scst = sk.sede_cost ?? 0;
  const costStr = [fc?`🍖${fc}`:'', scst?`💧${scst}`:''].filter(Boolean).join(' ') || '—';
  const temRec  = (me.fome ?? 0) >= fc && (me.sede ?? 0) >= scst;

  const setBtn = (name, desc, cost, disabled, onclick, active) => {
    btn.className = 'skill-btn' + (active ? ' skill-active' : '');
    btn.disabled  = !!disabled;
    btn.innerHTML = `
      <div class="skill-info">
        <div class="skill-name" data-ability-id="${sk.id || ''}">${name}</div>
        <div class="skill-desc">${desc}</div>
      </div>
      <div class="skill-cost">${cost}</div>`;
    if(onclick) btn.onclick = onclick;
  };

  if(sk.id === 'ataque_furtivo'){
    const nd4 = (me.level ?? 1) <= 2 ? '2' : (me.level ?? 1) <= 4 ? '3' : '4';
    const nivelFurtivo = GS.ladinoFurtivoNivel ? GS.ladinoFurtivoNivel() : 1;
    const descFurtivo = nivelFurtivo >= 3
      ? t('ui.hud.furtivo_3',{n:nd4})
      : nivelFurtivo === 2
      ? t('ui.hud.furtivo_2',{n:nd4})
      : t('ui.hud.furtivo_1',{n:nd4});
    setBtn(`🗡️ ${sk.name} <small style="color:var(--text2);font-size:.62rem;">${t('ui.hud.passiva')}</small>`,
           descFurtivo, '—', true, null, false);

  } else if(sk.id === 'detectar_armadilhas'){
    if(me.detectar_ativo){
      setBtn(`🔍 ${sk.name} <small style="color:var(--gold);font-size:.65rem;">● ${t('ui.hud.ativa')}</small>`,
             t('ui.hud.detectar_desc'), `manut. 💧1<br><small style="font-size:.6rem;">${t('ui.hud.parar')}</small>`,
             false, () => send({type:'detectar_armadilhas'}), true);
    } else {
      const aviso = me.bonus_action_used ? ` <small style="color:var(--text2);font-size:.62rem;">${t('ui.hud.bonus_usado')}</small>` : '';
      setBtn(`🔍 ${sk.name}${aviso}`, sk.description || sk.desc || '', 'manut. 💧1',
             !(myTurnPlay && !me.bonus_action_used), () => send({type:'detectar_armadilhas'}), false);
    }

  } else if(sk.id === 'esconder_sombras'){
    const bonusEsc  = GS.ladinoEsconderBonus ? GS.ladinoEsconderBonus() : 0;
    const revelaCaEsc = GS.ladinoEsconderRevelaCA ? GS.ladinoEsconderRevelaCA() : false;
    const descEsc = t('ui.ladino.esconder_desc', {b: bonusEsc>0?` (+${bonusEsc})`:''});
    if(me.invisivel_sombras){
      setBtn(`🌑 ${sk.name} <small style="color:var(--gold);font-size:.65rem;">● ${t('ui.hud.invisivel')}</small>`,
             t('ui.hud.invisivel_desc')+(revelaCaEsc?' · '+t('ui.hud.mais_ca_revelar'):''), `manut. 🍖1 💧1<br><small style="font-size:.6rem;">${t('ui.hud.sair')}</small>`,
             false, () => send({type:'esconder_sombras'}), true);
    } else {
      const pode  = myTurnPlay && !me.bonus_action_used && temRec;
      const aviso = me.bonus_action_used ? ` <small style="color:var(--text2);font-size:.62rem;">${t('ui.hud.bonus_usado')}</small>`
                  : !temRec ? ' <small style="color:var(--red);font-size:.62rem;">'+t('ui.hud.sem_recursos')+'</small>' : '';
      setBtn(`🌑 ${sk.name}${aviso}`, descEsc, costStr, !pode,
             () => send({type:'esconder_sombras'}), false);
    }

  } else if(sk.id === 'veneno_rapido'){
    const venenos = _venenosNaBolsa(me);
    const maxHits = GS.ladinoVenenoMaxHits ? GS.ladinoVenenoMaxHits() : 1;
    const doisSlots = GS.ladinoVeneno2Slots ? GS.ladinoVeneno2Slots() : false;
    if(me.weapon_poison){
      const hits = me.weapon_poison_hits ?? 0;
      const slot2 = me.weapon_poison_2 ? t('ui.ladino.segundo_veneno_golpes', {n: me.weapon_poison_2_hits ?? 0}) : (doisSlots ? t('ui.ladino.pode_aplicar_segundo_veneno') : '');
      setBtn(`☠️ ${sk.name} <small style="color:#cc44ff;font-size:.65rem;">● ${t('ui.hud.arma_envenenada')}</small>`,
             t('ui.ladino.golpes_restantes_trocar', {hits, max: maxHits, extra: slot2}), costStr,
             !(myTurnPlay && (me.sede ?? 0) >= scst && venenos.length > 0),
             () => abrirPainelVenenoRapido(), true);
    } else {
      const pode  = myTurnPlay && (me.sede ?? 0) >= scst && venenos.length > 0;
      const aviso = venenos.length === 0 ? ' <small style="color:var(--red);font-size:.62rem;">'+t('ui.hud.sem_venenos')+'</small>' : '';
      setBtn(`☠️ ${sk.name}${aviso}`, t('ui.ladino.dura_golpes_certeiros', {n: maxHits, extra: doisSlots?' · '+t('ui.ladino.dois_venenos'):''}), costStr, !pode,
             () => abrirPainelVenenoRapido(), false);
    }

  } else if(sk.id === 'criar_armadilha'){
    const pode  = myTurnPlay && !me.action_done;
    const aviso = me.action_done ? ` <small style="color:var(--text2);font-size:.62rem;">${t('ui.hud.acao_usada')}</small>` : '';
    setBtn(`🪤 ${sk.name}${aviso}`, sk.description || sk.desc || '', costStr, !pode,
           () => abrirPainelCriarArmadilha(), false);

  } else if(sk.id === 'desarmar_armadilha'){
    const ativo = GS.pendingSkill && GS.pendingSkill.id === sk.id;
    const pode = myTurnPlay && !me.action_done && (me.fome ?? 0) >= 1 && (me.sede ?? 0) >= 1;
    const bonusDes = GS.ladinoDesarmeBonus ? GS.ladinoDesarmeBonus() : 0;
    const recupera = GS.ladinoDesarmeRecupera ? GS.ladinoDesarmeRecupera() : false;
    const desc = t('ui.hud.criar_armadilha_desc',{b:bonusDes ? ` (+${bonusDes})` : ''})+(recupera ? ' '+t('ui.hud.recupera_ouro') : '');
    setBtn(`🔧 ${sk.name}${ativo ? ` <small style="color:var(--gold);font-size:.65rem;">● ${t('ui.hud.selecione_casa')}</small>` : ''}`,
           desc, '🍖1 💧1', !(pode || ativo), () => {
             if (ativo) { GS.pendingSkill = null; _removerEfeitoVisualLocal(sk.id); renderMyPanel(GS.gameState); toast(t('ui.ladino.habilidade_cancelada'), 'var(--text2)'); }
             else { GS.pendingSkill = { ...sk, target: 'tile' }; _registrarEfeitoVisualLocal(sk.id, 'skill'); renderMyPanel(GS.gameState); toast(t('ui.ladino.selecione_uma_casa_adjacente_para_desarmar'), 'var(--gold)'); }
           }, false);

  } else {
    setBtn(`${sk.icon || ''} ${sk.name}`, sk.description || sk.desc || '', costStr, !myTurnPlay, null, false);
  }
  return btn;
}

window.abrirPainelCriarArmadilha = abrirPainelCriarArmadilha;
window.abrirPainelVenenoRapido   = abrirPainelVenenoRapido;
window.onClickTileParaArmadilha  = onClickTileParaArmadilha;

// ═══════════════════════════════════════════════════════════════════════════
// FRADE LEWIS (cleric) — habilidades no cliente. Os 4 milagres (cura, cura_area,
// purificacao, ressurreicao) são ações principais dedicadas implementadas no
// servidor (ver server.py). Convenções REAIS do cliente: me.class_id (não `cls`),
// me.pos[0/1] (não tx/ty), GS.adicionarLog/toast, e seleção de alvo via
// openTargetModal — NÃO via highlights 3D. Cor temática: verde #44cc88.
// ═══════════════════════════════════════════════════════════════════════════

// Aliados VIVOS dentro de `raio` (Chebyshev). incluirSelf inclui o próprio Lewis.
function _aliadosVivosNoRaioCleric(me, raio, incluirSelf){
  const st = GS.gameState; if(!st) return [];
  const pp = me.pos || [0,0];
  return (st.players || []).filter(a => a && a.alive && a.pos &&
    (incluirSelf || a.id !== me.id) &&
    Math.max(Math.abs(pp[0]-a.pos[0]), Math.abs(pp[1]-a.pos[1])) <= _alcanceComAlturaCli(me, raio, a));
}

// Aliados MORTOS dentro de `raio` (Ressurreição). Exclui o próprio Lewis.
function _aliadosMortosNoRaioCleric(me, raio){
  const st = GS.gameState; if(!st) return [];
  const pp = me.pos || [0,0];
  return (st.players || []).filter(a => a && a.alive === false && a.id !== me.id && a.pos &&
    Math.max(Math.abs(pp[0]-a.pos[0]), Math.abs(pp[1]-a.pos[1])) <= _alcanceComAlturaCli(me, raio, a));
}

// Tipos de purificação — espelha PURIFICACAO_CUSTOS em server.py. `cond` lê os
// campos reais que o servidor envia no game_state (efeitos_veneno/cego/etc.).
const PURIFICACAO_TIPOS_LEWIS = [
  { id:'veneno',       icone:'☠️', custo:'🍖-1',      cond: p => (p.efeitos_veneno && p.efeitos_veneno.length > 0) || p.cego },
  { id:'doenca',       icone:'🤒', custo:'🍖-2 💧-1', cond: p => !!p.doente },
  { id:'maldicao',     icone:'💀', custo:'🍖-3 💧-2', cond: p => !!p.amaldicoado },
  { id:'petrificacao', icone:'🗿', custo:'🍖-5 💧-5', cond: p => !!p.petrificado },
];

function _clericPodeAgir(me){
  if(!me || me.class_id !== 'cleric') return false;
  if(!GS.isMyTurn || me.alive === false || (GS.gameState && GS.gameState.phase !== 'playing')){
    toast(t('ui.clerigo.milagre_so_turno'), 'var(--orange)'); return false;
  }
  if(me.action_done){ toast(t('ui.hud.acao_principal_ja_usada'), 'var(--orange)'); return false; }
  return true;
}

// ── Cura individual — painel de configuração (dados + alcance) → alvo via modal ──
function abrirPainelCura(){
  const ex = document.getElementById('painel-cura');
  if(ex){ ex.remove(); return; }
  const me = GS.me;
  if(!_clericPodeAgir(me)) return;

  let numDados = 1, alcanceExtra = 0;
  const painel = document.createElement('div');
  painel.id = 'painel-cura';
  painel.style.cssText = `position:fixed;bottom:180px;left:50%;transform:translateX(-50%);
    background:rgba(10,8,5,0.97);border:1px solid #44cc88;width:300px;z-index:200;
    padding:16px;font-family:'Cinzel',serif;`;

  function render(){
    const bonusInt = getBonusAtributo(me.int_ ?? 10);
    const alcance  = 1 + alcanceExtra * 3;
    const custoFome = alcanceExtra, custoSede = numDados;
    painel.innerHTML = `
      <div style="font-family:'Cinzel Decorative',serif;color:#44cc88;font-size:13px;margin-bottom:12px;text-align:center;">${t('ui.clerigo.cura_titulo')}</div>
      <div style="color:#8a7a5a;font-size:9px;letter-spacing:2px;margin-bottom:8px;">${t('ui.clerigo.cura_dados')}</div>
      <div style="display:flex;gap:6px;margin-bottom:14px;">
        ${[1,2,3].filter(n => n <= GS.clericCuraTeto()).map(n => `<button onclick="window._curaSetDados(${n})" style="flex:1;padding:10px;
          background:${numDados===n?'rgba(68,204,136,0.20)':'transparent'};
          border:1px solid ${numDados===n?'#44cc88':'#2a2a2a'};color:${numDados===n?'#44cc88':'#c8b89a'};
          font-family:'Cinzel',serif;font-size:12px;cursor:pointer;">${n}d8</button>`).join('')}
      </div>
      <div style="color:#8a7a5a;font-size:9px;letter-spacing:2px;margin-bottom:8px;">${t('ui.clerigo.cura_alcance')}</div>
      <div style="display:flex;gap:6px;margin-bottom:14px;">
        ${[{v:0,l:t('ui.item.desc.adjacente')},{v:1,l:'+3 '+t('ui.geral.quad')},{v:2,l:'+6 '+t('ui.geral.quad')}].map(o => `<button onclick="window._curaSetAlcance(${o.v})" style="flex:1;padding:8px;
          background:${alcanceExtra===o.v?'rgba(68,204,136,0.15)':'transparent'};
          border:1px solid ${alcanceExtra===o.v?'#44cc88':'#2a2a2a'};color:${alcanceExtra===o.v?'#44cc88':'#c8b89a'};
          font-family:'Cinzel',serif;font-size:10px;cursor:pointer;">${o.l}</button>`).join('')}
      </div>
      <div style="padding:10px 12px;margin-bottom:12px;background:rgba(68,204,136,0.06);border:1px solid #44cc8833;">
        <div style="display:flex;justify-content:space-between;margin-bottom:4px;"><span style="color:#8a7a5a;font-size:10px;" data-i18n="ui.hud.cura_estimada">Cura estimada</span><span style="color:#44cc88;font-size:12px;font-weight:bold;">${t('ui.clerigo.cura_formula', {n: numDados, sinal: bonusInt>=0?'+':'', bonus: bonusInt})}</span></div>
        <div style="display:flex;justify-content:space-between;margin-bottom:4px;"><span style="color:#8a7a5a;font-size:10px;" data-i18n="ui.pergaminho.alcance">Alcance</span><span style="color:#44cc88;font-size:11px;">${t('ui.clerigo.n_quadrados', {n: alcance})}</span></div>
        <div style="display:flex;justify-content:space-between;"><span style="color:#8a7a5a;font-size:10px;" data-i18n="ui.acoes.custo">Custo</span><span style="color:#ff851b;font-size:11px;">${custoFome>0?`🍖-${custoFome} `:''}💧-${custoSede}</span></div>
      </div>
      <div style="display:flex;gap:6px;">
        <button onclick="document.getElementById('painel-cura').remove()" style="flex:1;padding:8px;background:transparent;border:1px solid #4a4a4a;color:#8a7a5a;font-family:'Cinzel',serif;font-size:10px;letter-spacing:2px;cursor:pointer;" data-i18n="ui.geral.cancelar_caixa">CANCELAR</button>
        <button onclick="window._curaConfirmar()" style="flex:2;padding:8px;background:rgba(68,204,136,0.15);border:1px solid #44cc88;color:#44cc88;font-family:'Cinzel',serif;font-size:10px;letter-spacing:2px;cursor:pointer;" data-i18n="ui.hud.curar_2">🙌 CURAR</button>
      </div>`;
  }

  window._curaSetDados   = (n) => { numDados = n; render(); };
  window._curaSetAlcance = (v) => { alcanceExtra = v; render(); };
  window._curaConfirmar  = () => {
    const meNow = GS.me;
    const alcance = 1 + alcanceExtra * 3;
    if((meNow.sede||0) < numDados){ toast(t('ui.clerigo.sede_insuficiente', {n: numDados}), 'var(--orange)'); return; }
    if((meNow.fome||0) < alcanceExtra){ toast(t('ui.clerigo.fome_insuficiente', {n: alcanceExtra}), 'var(--orange)'); return; }
    const alvos = _aliadosVivosNoRaioCleric(meNow, alcance, true);
    document.getElementById('painel-cura')?.remove();
    if(!alvos.length){ toast(t('ui.hud.nenhum_aliado_no_alcance'), 'var(--orange)'); return; }
    const enviar = (id) => send({ type:'cura', target_id:id, num_dados:numDados, alcance_extra:alcanceExtra });
    if(alvos.length === 1){ enviar(alvos[0].id); return; }
    openTargetModal(t('ui.clerigo.cura_modal_titulo', {n: numDados, alcance}), alvos, 'player', enviar);
  };

  render();
  document.body.appendChild(painel);
}

// ── Cura em área — painel de configuração (dados) → envia (sem alvo) ──
function abrirPainelCuraArea(){
  const ex = document.getElementById('painel-cura-area');
  if(ex){ ex.remove(); return; }
  const me = GS.me;
  if(!_clericPodeAgir(me)) return;

  let numDados = 1;
  const painel = document.createElement('div');
  painel.id = 'painel-cura-area';
  painel.style.cssText = `position:fixed;bottom:180px;left:50%;transform:translateX(-50%);
    background:rgba(10,8,5,0.97);border:1px solid #44cc88;width:280px;z-index:200;
    padding:16px;font-family:'Cinzel',serif;`;

  function render(){
    const bonusInt = getBonusAtributo(me.int_ ?? 10);
    const custo = numDados * 4;
    const _mNivel = GS.clericMassaNivel(), _mRaio = 2 * _mNivel;
    painel.innerHTML = `
      <div style="font-family:'Cinzel Decorative',serif;color:#44cc88;font-size:13px;margin-bottom:12px;text-align:center;">${t('ui.clerigo.cura_area_titulo')}</div>
      <div style="color:#8a7a5a;font-size:9px;letter-spacing:2px;margin-bottom:8px;text-align:center;">${t('ui.clerigo.cura_area_sub', {raio:_mRaio})}</div>
      <div style="display:flex;gap:6px;margin-bottom:14px;">
        ${[1,2,3].filter(n => n <= _mNivel).map(n => `<button onclick="window._curaAreaSetDados(${n})" style="flex:1;padding:10px;
          background:${numDados===n?'rgba(68,204,136,0.20)':'transparent'};
          border:1px solid ${numDados===n?'#44cc88':'#2a2a2a'};color:${numDados===n?'#44cc88':'#c8b89a'};
          font-family:'Cinzel',serif;font-size:12px;cursor:pointer;">${n}d8</button>`).join('')}
      </div>
      <div style="padding:10px 12px;margin-bottom:12px;background:rgba(68,204,136,0.06);border:1px solid #44cc8833;">
        <div style="display:flex;justify-content:space-between;margin-bottom:4px;"><span style="color:#8a7a5a;font-size:10px;">${t('ui.clerigo.cura_todos')}</span><span style="color:#44cc88;font-size:12px;">${numDados}d8 ${bonusInt>=0?'+':''}${bonusInt}</span></div>
        <div style="display:flex;justify-content:space-between;margin-bottom:4px;"><span style="color:#8a7a5a;font-size:10px;">${t('ui.instrumento.raio')}</span><span style="color:#44cc88;font-size:11px;">${t('ui.instrumento.quadrados', {n:_mRaio})}</span></div>
        <div style="display:flex;justify-content:space-between;"><span style="color:#8a7a5a;font-size:10px;">${t('ui.instrumento.custo')}</span><span style="color:#ff851b;font-size:11px;">🍖-${custo} 💧-${custo}</span></div>
      </div>
      <div style="display:flex;gap:6px;">
        <button onclick="document.getElementById('painel-cura-area').remove()" style="flex:1;padding:8px;background:transparent;border:1px solid #4a4a4a;color:#8a7a5a;font-family:'Cinzel',serif;font-size:10px;cursor:pointer;" data-i18n="ui.geral.cancelar_caixa">CANCELAR</button>
        <button onclick="window._curaAreaConfirmar()" style="flex:2;padding:8px;background:rgba(68,204,136,0.15);border:1px solid #44cc88;color:#44cc88;font-family:'Cinzel',serif;font-size:10px;letter-spacing:2px;cursor:pointer;">${t('ui.clerigo.curar_area_botao')}</button>
      </div>`;
  }

  window._curaAreaSetDados  = (n) => { numDados = n; render(); };
  window._curaAreaConfirmar = () => {
    const meNow = GS.me, custo = numDados * 4;
    if((meNow.fome||0) < custo || (meNow.sede||0) < custo){ toast(t('ui.clerigo.recursos_insuficientes', {n: custo}), 'var(--orange)'); return; }
    send({ type:'cura_area', num_dados:numDados });
    document.getElementById('painel-cura-area')?.remove();
  };

  render();
  document.body.appendChild(painel);
}

// ── Purificação — escolhe aliado adjacente afligido via modal; se vários efeitos,
// abre painel de escolha do tipo. Envia { type:'purificacao', target_id, tipo }. ──
function iniciarModoPurificacao(){
  const me = GS.me;
  if(!_clericPodeAgir(me)) return;
  // Só os tipos destravados pela Guilda (Fase 1b): venenos base; +doenças; +maldições/petrificação.
  const _permitidos = GS.clericPurifTipos();
  const alvos = _aliadosVivosNoRaioCleric(me, 1, true)
    .filter(a => PURIFICACAO_TIPOS_LEWIS.some(t => _permitidos.includes(t.id) && t.cond(a)));
  if(!alvos.length){ toast(t('ui.clerigo.purificar_sem_alvo'), 'var(--orange)'); return; }
  const escolher = (id) => {
    const alvo = (GS.gameState.players || []).find(p => p.id === id);
    if(!alvo) return;
    const efeitos = PURIFICACAO_TIPOS_LEWIS.filter(t => _permitidos.includes(t.id) && t.cond(alvo));
    if(efeitos.length === 0){ toast(t('ui.clerigo.purificar_alvo_limpo', {nome:alvo.name}), 'var(--orange)'); return; }
    if(efeitos.length === 1){ send({ type:'purificacao', target_id:id, tipo:efeitos[0].id }); return; }
    _abrirPainelEscolhaPurificacao(alvo, efeitos);
  };
  if(alvos.length === 1){ escolher(alvos[0].id); return; }
  openTargetModal(t('ui.clerigo.purificar_titulo'), alvos, 'player', escolher);
}

function _abrirPainelEscolhaPurificacao(alvo, efeitos){
  document.getElementById('painel-purificacao')?.remove();
  const painel = document.createElement('div');
  painel.id = 'painel-purificacao';
  painel.style.cssText = `position:fixed;bottom:180px;left:50%;transform:translateX(-50%);
    background:rgba(10,8,5,0.97);border:1px solid #cc44ff;width:260px;z-index:200;
    padding:16px;font-family:'Cinzel',serif;`;
  painel.innerHTML = `
    <div style="font-family:'Cinzel Decorative',serif;color:#cc44ff;font-size:12px;margin-bottom:10px;text-align:center;">${t('ui.clerigo.purificar_alvo_titulo', {nome: (alvo.name||'').toUpperCase()})}</div>
    ${efeitos.map(ef => `<button onclick="window._purificarConfirmar('${alvo.id}','${ef.id}')" style="width:100%;padding:10px 12px;margin-bottom:4px;background:rgba(204,68,255,0.06);border:1px solid #cc44ff44;color:#c8b89a;font-family:'Cinzel',serif;font-size:11px;text-align:left;cursor:pointer;display:flex;justify-content:space-between;" onmouseover="this.style.borderColor='#cc44ff'" onmouseout="this.style.borderColor='#cc44ff44'"><span>${ef.icone} ${_rotulo(ef.id, 'ui.purificacao', ef.id)}</span><span style="color:#ff851b;font-size:10px;">${ef.custo}</span></button>`).join('')}
    <button onclick="document.getElementById('painel-purificacao').remove()" style="width:100%;margin-top:6px;padding:8px;background:transparent;border:1px solid #4a4a4a;color:#8a7a5a;font-family:'Cinzel',serif;font-size:10px;letter-spacing:2px;cursor:pointer;" data-i18n="ui.geral.cancelar_caixa">CANCELAR</button>`;
  document.body.appendChild(painel);
  window._purificarConfirmar = (targetId, tipo) => {
    send({ type:'purificacao', target_id:targetId, tipo });
    document.getElementById('painel-purificacao')?.remove();
  };
}

// ── Ressurreição — escolhe aliado MORTO adjacente via modal e envia. ──
function iniciarModoRessurreicao(){
  const me = GS.me;
  if(!_clericPodeAgir(me)) return;
  // Custo e efeito por nível da especialização (Fase 1b): 1 HP/10 · metade/15 · cheio/20.
  const _rNivel = GS.clericRessurNivel();
  const _rCusto = {1:10, 2:15, 3:20}[_rNivel];
  const _rEfeito = _rotulo(String(_rNivel), 'ui.clerigo.ressur_efeito', '');
  if((me.fome||0) < _rCusto || (me.sede||0) < _rCusto){ toast(t('ui.clerigo.ressur_custo', {n:_rCusto}), 'var(--orange)'); return; }
  const mortos = _aliadosMortosNoRaioCleric(me, 1);
  if(!mortos.length){ toast(t('ui.clerigo.sem_aliado_morto'), 'var(--orange)'); return; }
  const enviar = (id) => send({ type:'ressurreicao', target_id:id });
  if(mortos.length === 1){ enviar(mortos[0].id); return; }
  openTargetModal(t('ui.clerigo.ressur_titulo', {efeito:_rEfeito}), mortos, 'player', enviar);
}

// Botão de habilidade do Frade Lewis (padrão skill-btn, como _paladinSkillBtn).
function _clericSkillBtn(me, sk){
  const btn = document.createElement('button');
  const myTurnPlay = GS.isMyTurn && me.alive && GS.gameState && GS.gameState.phase === 'playing';
  const fc = sk.fome_cost ?? 0, scst = sk.sede_cost ?? 0;
  const costStr = [fc?`🍖${fc}`:'', scst?`💧${scst}`:''].filter(Boolean).join(' ') || '—';
  const acaoUsada = me.action_done;
  const podePrincipal = myTurnPlay && !acaoUsada;
  const avisoAcao = acaoUsada ? ` <small style="color:var(--text2);font-size:.62rem;">${t('ui.hud.acao_usada')}</small>` : '';

  const setBtn = (name, desc, cost, disabled, onclick) => {
    btn.className = 'skill-btn';
    btn.disabled  = !!disabled;
    btn.innerHTML = `
      <div class="skill-info">
        <div class="skill-name" data-ability-id="${sk.id || ''}">${name}</div>
        <div class="skill-desc">${desc}</div>
      </div>
      <div class="skill-cost">${cost}</div>`;
    if(onclick) btn.onclick = onclick;
  };

  const desc = sk.description || sk.desc || '';
  if(sk.id === 'cura'){
    setBtn(`🙌 ${sk.name}${avisoAcao}`, desc, '💧1+ / dado', !podePrincipal, () => abrirPainelCura());
  } else if(sk.id === 'cura_area'){
    setBtn(`🌟 ${sk.name}${avisoAcao}`, desc, '🍖4 💧4 / dado', !podePrincipal, () => abrirPainelCuraArea());
  } else if(sk.id === 'purificacao'){
    setBtn(`✨ ${sk.name}${avisoAcao}`, desc, '🍖1 a 5', !podePrincipal, () => iniciarModoPurificacao());
  } else if(sk.id === 'ressurreicao'){
    const temRec = (me.fome||0) >= 10 && (me.sede||0) >= 10;
    const aviso  = acaoUsada ? avisoAcao
                 : !temRec ? ' <small style="color:var(--red);font-size:.62rem;">'+t('ui.hud.sem_recursos')+'</small>' : '';
    setBtn(`💫 ${sk.name}${aviso}`, desc, costStr, !podePrincipal || !temRec, () => iniciarModoRessurreicao());
  } else {
    setBtn(`${sk.icon || ''} ${sk.name}`, desc, costStr, !myTurnPlay, null);
  }
  return btn;
}

// ─── Mago (Pedro): METAMAGIA (cliente) ──────────────────────────────────────
// 3 ações livres (toggles) EMPILHÁVEIS que MODIFICAM a magia do GRIMÓRIO lançada
// no turno (mensagem `magia` / handle_magia). O servidor cobra o custo ao LANÇAR
// e SÓ se a habilidade tiver efeito. Aqui só armamos/desarmamos (toggle).
// Magnitudes BASE (escalam com as especializações da Guilda — Fase 1f); baseline:
// só 1 metamagia por lançamento (Tecelagem Arcana desbloqueia empilhar 2/3).
//   🎯 Aprimorar  → +1 na CD do teste de resistência (base) (🍖-3)
//   ⏱️ Estender   → +1 turno na duração (base)              (🍖-3 💧-3)
//   💥 Fortalecer → dano ×1,25 (base)                       (🍖-6 💧-6)
function _mageSkillBtn(me, sk){
  const btn = document.createElement('button');
  const myTurnPlay = GS.isMyTurn && me.alive && GS.gameState && GS.gameState.phase === 'playing';
  let desc = sk.description || sk.desc || '';
  // A descrição reflete a magnitude possuída da especialização e o teto de
  // empilhamento (Fase 1f). Texto informativo — o servidor é autoritativo.
  {
    const cap = GS.magoTecelagemCap ? GS.magoTecelagemCap() : 1;
    const capTxt = ' ' + t('ui.metamagia.empilha_ate', {n:cap});
    if (sk.id === 'fortalecer_magia') {
      const mult = GS.magoFortalecerMult ? GS.magoFortalecerMult() : 1.25;
      desc = t('ui.metamagia.fortalecer', {mult:String(mult).replace('.', ',')}) + capTxt;
    } else if (sk.id === 'aprimorar_magia') {
      const b = GS.magoAprimorarBonus ? GS.magoAprimorarBonus() : 1;
      desc = t('ui.metamagia.aprimorar', {n:b}) + capTxt;
    } else if (sk.id === 'estender_magia') {
      const b = GS.magoEstenderBonus ? GS.magoEstenderBonus() : 1;
      desc = t(b !== 1 ? 'ui.metamagia.estender_plural' : 'ui.metamagia.estender', {n:b}) + capTxt;
    }
  }
  const cfg = ({
    aprimorar_magia:  { icon: '🎯', flag: 'aprimorar_ativo',  custo: '🍖3'     },
    estender_magia:   { icon: '⏱️', flag: 'estender_ativo',   custo: '🍖3 💧3' },
    fortalecer_magia: { icon: '💥', flag: 'fortalecer_ativo', custo: '🍖6 💧6' },
  })[sk.id];
  if(!cfg){
    btn.className = 'skill-btn'; btn.disabled = true;
    btn.innerHTML = `<div class="skill-info"><div class="skill-name">${sk.icon||''} ${sk.name}</div></div>`;
    return btn;
  }
  const ativo = !!me[cfg.flag];
  btn.className = 'skill-btn' + (ativo ? ' skill-active' : '');
  btn.disabled  = !myTurnPlay;
  btn.innerHTML = `
    <div class="skill-info">
      <div class="skill-name">${cfg.icon} ${sk.name}${ativo ? ` <small style="color:var(--gold);font-size:.65rem;">● ${t('ui.hud.armada')}</small>` : ''}</div>
      <div class="skill-desc">${desc}</div>
    </div>
    <div class="skill-cost">${ativo ? 'parar' : cfg.custo}</div>`;
  btn.onclick = () => send({ type: sk.id });   // toggle: o servidor arma/desarma
  return btn;
}

// Exposição global (paridade com as demais classes; usado pelo loop de skills).
window._mageSkillBtn = _mageSkillBtn;

