  wrap.style.cssText = 'position:fixed;right:14px;top:14px;z-index:61;font-family:inherit;';
  wrap.innerHTML =
    '<button id="audio-gear" data-i18n-title="ui.menu.audio_title" title="Áudio, idioma e opções" style="width:42px;height:42px;'
