  anim.innerRing = new T.Mesh(new T.TorusGeometry(.12, .018, 7, 32), innerMat);
  anim.innerRing.rotation.x = Math.PI / 2; anim.innerRing.renderOrder = 123; group.add(anim.innerRing);
