  const beamGlow=new T.Mesh(new T.BufferGeometry(),glowMat),beamCore=new T.Mesh(new T.BufferGeometry(),coreMat);beamGlow.renderOrder=70;beamCore.renderOrder=71;group.add(beamGlow,beamCore);
