    const age = now - burst.start, f = age < 820 ? Math.sin(Math.PI * Math.min(1, age / 820)) : 0;
    burst.mesh.position.set(x, .34, z); burst.mesh.material.opacity = .88 * f * fade; burst.mesh.scale.setScalar(1 + f * (burst.revive ? 2.2 : 1.6));
