function _tocarSomLentidao(a){const ctx=getAudioContext();if(!ctx||ctx.state!=='running')return;try{const now=ctx.currentTime,bus=_sfxBus(),dur=(a.travelMs+a.expandMs)/1000+.4,g=ctx.createGain(),o=ctx.createOscillator();o.type='sawtooth';o.frequency.setValueAtTime(120,now);o.frequency.exponentialRampToValueAtTime(46,now+dur);g.gain.setValueAtTime(.001,now);g.gain.exponentialRampToValueAtTime(.06,now+.12);g.gain.exponentialRampToValueAtTime(.001,now+dur);o.connect(g);g.connect(bus);o.start(now);o.stop(now+dur+.03);a.sound={ctx,nodes:[o],gains:[g]};}catch(e){}}
function _pararSomLentidao(a){if(!a.sound)return;try{const now=a.sound.ctx.currentTime;for(const n of a.sound.nodes)n.stop(now+.01);for(const g of a.sound.gains)g.disconnect();}catch(e){}a.sound=null;}
function _tickLentidao(now){let active=false;for(let i=_lentidaoAnims.length-1;i>=0;i--){const a=_lentidaoAnims[i],p=_lentidaoProgress(a,now);if(p.impacting&&!a.impactPlayed){a.impactPlayed=true;_liberarDadosMagia();}if(a.resolved&&!_lentidaoAtiva(a)&&now-a.resolveAt>1400&&a.endingAt==null)a.endingAt=now;if(a.endingAt!=null&&now-a.endingAt>=LENTIDAO_FADE_MS){_pararSomLentidao(a);_lentidaoDispose3D(a);_lentidaoAnims.splice(i,1);continue;}active=true;if(mode3D&&g3)_lentidaoUpdate3D(a,now);}if(!mode3D&&GS.gameState&&active)renderMap(GS.gameState);_lentidaoRaf=active?_scheduleVisualFrame(_tickLentidao):null;}
function _receberAnimacaoLentidao(msg){if(!msg||msg.spell_id!=='lentidao')return;const id=msg.animation_id==null?null:String(msg.animation_id);if(msg.phase==='start'){for(const old of _lentidaoAnims)if(old.endingAt==null)old.endingAt=performance.now();if(_lentidaoAnims.some(a=>a.animationId===id))return;const a=_lentidaoAnimFromMessage(msg);_lentidaoAnims.push(a);_tocarSomLentidao(a);if(!_lentidaoRaf)_lentidaoRaf=_scheduleVisualFrame(_tickLentidao);return;}const a=_lentidaoAnims.find(x=>x.animationId===id);if(!a)return;if(msg.phase==='resolve'){a.resolved=true;a.resolveAt=performance.now();a.slowedIds=(msg.slowed_ids||[]).map(String);a.resistedIds=(msg.resisted_ids||[]).map(String);}if(!_lentidaoRaf)_lentidaoRaf=_scheduleVisualFrame(_tickLentidao);}

function restoreTileSpacing3D(){
  if(_tileFootprint3D === 0.94) return;
  _tileFootprint3D = 0.94;
  const btn=$('btn-tile-spacing-reset'); if(btn){ btn.disabled=true; btn.textContent=t('ui.hud.espaco_ok'); }
  if(mode3D && GS.gameState){ dispose3D(); renderMap3D(GS.gameState); }
  toast(t('ui.hud.espaco_restaurado'));
}

function toggle3D(){
  if(!window.THREE){
    toast(t('ui.hud.three_indisponivel'),'var(--orange)');
    return;
  }
  mode3D = !mode3D;
  const btn   = $('btn-3d-toggle');
  const hint  = $('orbit-hint');
  const reset = $('btn-cam-reset');
  const spacingReset = $('btn-tile-spacing-reset');
  if(mode3D){
    btn.classList.add('active');
    btn.textContent = '◀ 2D';
    if(hint)  hint.style.display  = 'inline';
    if(reset) reset.style.display = 'inline-block';
    if(spacingReset){ spacingReset.style.display='inline-block'; spacingReset.disabled=_tileFootprint3D===0.94; spacingReset.textContent=t(_tileFootprint3D===0.94?'ui.hud.espaco_ok':'ui.hud.espaco_voltar'); }
    $('dungeon-canvas').style.display = 'none';
    if(GS.gameState) renderMap3D(GS.gameState);   // init3D called lazily inside
    _syncMouseAltitudeControl(GS.gameState);
  } else {
    btn.classList.remove('active');
    btn.textContent = '🎲 3D';
    if(hint)  hint.style.display  = 'none';
    if(reset) reset.style.display = 'none';
    if(spacingReset) spacingReset.style.display = 'none';
    $('dungeon-canvas').style.display = 'block';
    dispose3D();
    _syncMouseAltitudeControl(GS.gameState);
    if(GS.gameState) renderMap(GS.gameState);
  }
}

// A malha 3D do tabuleiro é criada uma vez e reutilizada durante o turno. Esta
// assinatura separa mudanças estáticas (tiles/materiais) das atualizações comuns
// de jogo, para reconstituir o chão quando o editor carrega ou pinta grama/terra.
// Nº de luzes do pool de tochas/arandelas (contagem constante — ver init3D).
const LIGHT_POOL_N = 8;

function _assinaturaVisualTabuleiro3D(state){
  const tiles = (state.tiles || []).map(row => row.join('')).join('|');
  const materiais = state.materiais || {};
  const pintura = Object.keys(materiais).sort()
    .map(key => `${key}:${materiais[key]}`).join('|');
  const elevacoes = Object.keys(state.elevacoes || {}).sort()
    .map(key => `${key}:${state.elevacoes[key]}`).join('|');
  const pontes = (state.pontes || []).map(p =>
    `${p.id || ''}:${(p.inicio || []).join(',')}-${(p.fim || []).join(',')}:${p.largura || 1}:${p.altura || 0}:${p.material || 'madeira'}`).sort().join('|');
  const segredos = (state.secret_passages || []).map(sp =>
    `${sp.pos?.[0]},${sp.pos?.[1]}:${sp.wall_material || ''}`).sort().join('|');
  return `${tiles}#${pintura}#${elevacoes}#${pontes}#${state.transicao_altura || 'rampa'}#${segredos}`;
}

// Each TILE_FLOOR cell → chunky physical floor piece (thickness 0.22, gap 0.07/side)
// Each TILE_WALL cell → tall stone wall column, or an organic dune mound when
// the authored wall material is duna_deserto.
// Dark table surface underneath → gap between pieces = visible grid lines

// ── Pool preguiçoso de overlay por casa ──────────────────────────────────────
// Cada família de realce (movimento, ataque, alcance de magia, prévias do
// mestre, fogo persistente…) cobria UMA casa de cada vez, mas era construída
// para TODAS as casas de chão ao entrar na masmorra. Num mapa 44×40 isso dava
// 37.586 nós na cena com ~140 visíveis; como o renderer percorre a árvore
// inteira a cada quadro, o custo aparecia mesmo sem nada desenhado
// (8,20 ms/quadro com 2 draw calls). Congelar `matrixAutoUpdate` nesses nós não
// mudou nada (7,05 → 6,89 ms): o peso é a TRAVESSIA, não a conta de matriz —
// por isso a saída é reduzir a QUANTIDADE de nós.
//
// O pool nasce vazio: o mesh de uma casa é criado na primeira vez que ela
// precisa aparecer e fica em cache até a masmorra ser trocada (init3D refaz a
// cena inteira). Medido no mesmo mapa: 37.586 → ~3.900 nós, 8,20 → ~1,2 ms.
//
// ATENÇÃO: `_make` é não-enumerável de propósito — os consumidores varrem o
// pool com `for…in` / `Object.entries`, e a fábrica não pode aparecer ali.
function _mkOverlayPool(make){
  const pool = {};
  Object.defineProperty(pool, '_make', { value: make, enumerable: false, writable: true });
  return pool;
}

// Devolve (criando na primeira vez) o mesh da casa `key`. A fábrica devolve
// null para casa que não é elegível — era o que o filtro de tipo de casa do
// laço antigo fazia, e continua sendo load-bearing: os conjuntos de área de
// magia incluem paredes, que nunca podem receber o realce.
function _overlayAt(pool, key){
  if(!pool) return null;
  const pronto = pool[key];
  if(pronto !== undefined) return pronto;
  const feito = pool._make ? pool._make(key) : null;
  pool[key] = feito || null;
  return feito || null;
}

// Mostra exatamente as casas de `keys` e esconde todo o resto já criado.
// Substitui o antigo `for(const k in dict) dict[k].visible = set.has(k)`, que
// dependia de o dicionário já conter a casa.
function _overlayShowOnly(pool, keys){
  if(!pool) return;
  for(const k in pool){ const m = pool[k]; if(m) m.visible = false; }
  if(!keys) return;
  for(const k of keys){ const m = _overlayAt(pool, k); if(m) m.visible = true; }
}

function init3D(state){
  if(!window.THREE){ console.error('Three.js not loaded'); return; }
  if(!window.THREE.OrbitControls){ console.error('OrbitControls not loaded'); return; }
  if(g3) dispose3D();
  if(window.CombatScene) CombatScene.reset();
  _projetilLimparTodos();

  const T   = window.THREE;
  const boardVisualSig = _assinaturaVisualTabuleiro3D(state);
  const wrap = $('map-wrap');
  const W = state.tiles[0].length, H = state.tiles.length;

  // Use offsetWidth/Height so the canvas covers map-wrap including its padding.
  // wrap.style is also set to position:relative so the canvas can be absolute.
  wrap.style.position = 'relative';
  const CW = wrap.offsetWidth  || 640;
  const CH = wrap.offsetHeight || 480;

  // ── Ambiente de iluminação (preset por mapa). Default "masmorra".
  // Controla luz/fog/exposição dos tiles explorados; a névoa de guerra é igual.
  const AMB = (VC.ambientes && VC.ambientes[state.ambiente]) || VC.ambientes.masmorra;
  const AMBL = AMB.lighting;

  // ── Scene
  const scene = new T.Scene();
  scene.background = new T.Color(AMB.scene.bgColor);
  // Subtle fog — keeps depth cue without hiding explored areas.
  // Mestre: sem fog — enxerga tiles distantes com nitidez total (visão sem névoa).
  scene.fog = (GS.isMaster() || state.test_mode) ? null : new T.FogExp2(AMB.scene.fogColor, AMB.scene.fogDensity);

  // ── Renderer
  const renderer = new T.WebGLRenderer({ antialias:true, powerPreference:'high-performance' });
  // Limita a resolução interna a 1,5×: mantém nitidez no 3D, mas evita que
  // telas HiDPI renderizem milhões de pixels extras a cada quadro.
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.5));
  renderer.setSize(CW, CH);
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type    = T.PCFShadowMap   /* PCF simples: ~igual visualmente, bem mais barato que PCFSoft */;
  renderer.toneMapping       = T.ACESFilmicToneMapping;
  renderer.toneMappingExposure = AMB.exposure;
  // Absolute-fill so canvas covers the full map-wrap area (including 8px padding)
  Object.assign(renderer.domElement.style, {
    display: 'block', position: 'absolute',
    top: '0', left: '0', width: '100%', height: '100%',
  });
  wrap.appendChild(renderer.domElement);

  // ── Orthographic isometric camera
  const aspect = CW / CH;
  const fH     = Math.max(W, H) * 0.60;
  const camera = new T.OrthographicCamera(-fH*aspect, fH*aspect, fH, -fH, -300, 300);
  camera.updateProjectionMatrix();

  // Mesa de madeira sob uma placa de papelão: cobre também a área além do
  // mapa, para o tabuleiro parecer montado numa sala em vez de flutuar no preto.
  // O fallback procedural mantém o cenário funcional se a textura não carregar.
  let tableTex = generateTexture('wood');
  try {
    tableTex = new T.TextureLoader().load('assets/textures/tabletop-walnut.png');
  } catch (_) { /* usa a textura procedural criada acima */ }
  if(tableTex){
    if(T.SRGBColorSpace) tableTex.colorSpace=T.SRGBColorSpace; else if(T.sRGBEncoding) tableTex.encoding=T.sRGBEncoding;
  }
  const tableSpan = Math.max(W, H) * 3 + 12;
  const tableGeo = new T.BoxGeometry(tableSpan, 0.24, tableSpan);
  const tableMat = new T.MeshStandardMaterial({ map:tableTex, color:0x5a341c, roughness:0.88, metalness:0.0 });
  const tableM   = new T.Mesh(tableGeo, tableMat);
  tableM.position.set((W-1)/2, -0.20, (H-1)/2);
  tableM.receiveShadow = true; tableM.castShadow = true;
  scene.add(tableM);

  const boardMat = new T.MeshStandardMaterial({ color:0x2b211a, roughness:0.97, metalness:0.0 });
  const boardM = new T.Mesh(new T.BoxGeometry(W + 0.55, 0.11, H + 0.55), boardMat);
  boardM.position.set((W-1)/2, -0.065, (H-1)/2);
  boardM.receiveShadow = true; boardM.castShadow = true;
  scene.add(boardM);

  // Teste atual: 0,97 numa grade de 1,0 deixa 0,03 de fresta. Pode voltar
  // a 0,94 pelo botão do HUD, sem reiniciar a partida.
  const TW = _tileFootprint3D;
  const TH = 0.22;   // floor tile thickness         (chunky physical piece)
  const WH = 1.75;   // wall tile height             (from table to top)

  const floorTex = generateTexture('floor');   // 512×512 paved tiles
  const wallTex  = generateTexture('wall');    // 512×512 irregular brickwork

  // ── BASE MATERIALS (cloned per tile for individual colour tint) ─────────────
  // Textures are in mid-gray range so material.color tints them to final hue.
  // wallBaseMat uses the same texture as roughnessMap so block faces catch light
  // differently from mortar gaps — creates tactile stone surface feel.
  const floorBaseMat = new T.MeshStandardMaterial({
    map:floorTex, bumpMap:floorTex, bumpScale:VC.floor.bumpScale ?? 0.035,
    roughness:VC.floor.roughness ?? 0.86, metalness:0.03
  });
  const wallBaseMat  = new T.MeshStandardMaterial({
    map:wallTex, bumpMap:wallTex, roughnessMap:wallTex,
    bumpScale:VC.wall.bumpScale ?? 0.045,
    roughness:VC.wall.roughness ?? 0.88, metalness:0.04
  });

  // Textura de canvas por material (cache por id). Usa os MESMOS painters do 2D
  // para a aparência 2D/3D coincidir. Materiais "de pedra" (cinza/normal/negra)
  // retornam null e seguem usando floorTex/wallTex tingidos pela cor.
  const _matTexCache = {};
  function makeMaterialTex(matId){
    if(matId in _matTexCache) return _matTexCache[matId];
    const S=256, cv=document.createElement('canvas'); cv.width=cv.height=S;
    const c=cv.getContext('2d'); const r=_rng((matId.length*2654435761)>>>0);
    let tex=null;
    switch(matId){
      case 'grama':         paintGrass(c,0,0,S,r); break;
      case 'terra':         paintDirt(c,0,0,S,r); break;
      case 'areia_deserto': paintSand(c,0,0,S,r); break;
      case 'lava':          paintLava(c,0,0,S,r); break;
      case 'pantano':       paintSwamp(c,0,0,S,r); break;
      case 'rodamoinho':    paintWhirlpool(c,0,0,S,r); break;
      case 'rodamoinho_profundo': paintWhirlpool(c,0,0,S,r,true); break;
      case 'piso_congelado': paintIce(c,0,0,S,r); break;
      case 'planicie_nevada': paintSnowPlain(c,0,0,S,r); break;
      case 'agua':
      case 'agua_profunda': {
        // Textura própria para a água: não reutilizar floorTex, porque ele é
        // compartilhado com os pisos de pedra e não pode ser deslocado pela
        // animação sem mover a textura do tabuleiro inteiro.
        const profunda = matId === 'agua_profunda';
        c.fillStyle = profunda ? '#06173f' : '#0078c6';
        c.fillRect(0, 0, S, S);
        for(let row = 0; row < (profunda ? 12 : 18); row++){
          const yy = row * (S / (profunda ? 12 : 18)) + S * (0.02 + r() * 0.08);
          const amp = S * (profunda ? 0.018 : 0.028);
          c.strokeStyle = profunda
            ? `rgba(66,143,224,${(0.16 + r() * 0.10).toFixed(2)})`
            : `rgba(167,240,255,${(0.22 + r() * 0.14).toFixed(2)})`;
          c.lineWidth = S * (profunda ? 0.006 : 0.008);
          c.beginPath();
          c.moveTo(-S * 0.08, yy);
          c.bezierCurveTo(S * 0.18, yy - amp, S * 0.36, yy + amp, S * 0.58, yy);
          c.bezierCurveTo(S * 0.76, yy - amp, S * 0.94, yy + amp, S * 1.08, yy);
          c.stroke();
        }
        for(let n = 0; n < (profunda ? 14 : 24); n++){
          const px = r() * S, py = r() * S;
          c.fillStyle = profunda
            ? `rgba(111,181,255,${(0.08 + r() * 0.10).toFixed(2)})`
            : `rgba(218,252,255,${(0.12 + r() * 0.16).toFixed(2)})`;
          c.beginPath();
          c.ellipse(px, py, S * (0.012 + r() * 0.025), S * (0.004 + r() * 0.010), r() * Math.PI, 0, Math.PI * 2);
          c.fill();
        }
        break;
      }
      case 'duna_deserto':  paintSand(c,0,0,S,r); break;
      case 'caverna_congelada': paintFrozenCaveWall(c,0,0,S,r); break;
      case 'duna_neve':      paintSnowDuneWall(c,0,0,S,r); break;
      case 'rocha':         paintRock(c,0,0,S,r); break;
      case 'rocha_marrom':  paintRock(c,0,0,S,r,true); break;
      case 'pedra_negra':   paintStone(c,0,0,S,r,[30,28,34]); break;
      case 'enegrecida':    paintBrick(c,0,0,S,r,[22,21,26],'#070709'); break;
      case 'pedra_caverna': paintCave(c,0,0,S,r); break;
      case 'desmoronada':   paintRubble(c,0,0,S,r); break;
      case 'entulho':       paintRubble(c,0,0,S,r); break;
      case 'madeira': {
        c.fillStyle='#4a270f'; c.fillRect(0,0,S,S);
        for(let y=0;y<S;y+=32){
          c.fillStyle='rgba(32,12,3,.78)'; c.fillRect(0,y+29,S,3);
          c.strokeStyle='rgba(238,172,82,.18)'; c.lineWidth=2;
          for(let k=0;k<3;k++){const yy=y+5+((r()*18)|0);c.beginPath();c.moveTo(0,yy);c.bezierCurveTo(S*.3,yy-5,S*.7,yy+5,S,yy-2);c.stroke();}
        }
        break;
      }
      case 'madeira_escura': {
        c.fillStyle='#241108'; c.fillRect(0,0,S,S);
        for(let y=0;y<S;y+=32){
          c.fillStyle='rgba(5,2,1,.85)'; c.fillRect(0,y+29,S,3);
          c.strokeStyle='rgba(176,103,42,.16)'; c.lineWidth=2;
          for(let k=0;k<2;k++){const yy=y+6+((r()*16)|0);c.beginPath();c.moveTo(0,yy);c.bezierCurveTo(S*.3,yy-4,S*.7,yy+4,S,yy-1);c.stroke();}
        }
        break;
      }
    }
    if(matId==='grama'||matId==='terra'||matId==='areia_deserto'||matId==='agua'||matId==='agua_profunda'||matId==='rodamoinho'||matId==='rodamoinho_profundo'||matId==='lava'||matId==='pantano'||matId==='piso_congelado'||matId==='planicie_nevada'||matId==='duna_deserto'||matId==='caverna_congelada'||matId==='duna_neve'||matId==='rocha'||matId==='rocha_marrom'||matId==='pedra_negra'||matId==='enegrecida'||matId==='pedra_caverna'||matId==='desmoronada'||matId==='entulho'||matId==='madeira'||matId==='madeira_escura'){
      tex=new T.CanvasTexture(cv); tex.wrapS=tex.wrapT=T.RepeatWrapping;
      // Canvas é desenhado em sRGB. Declarar isso impede o Three.js de tratar
      // os verdes/marrons como cores lineares lavadas no renderizador 3D.
      if(T.SRGBColorSpace) tex.colorSpace=T.SRGBColorSpace;
      else if(T.sRGBEncoding) tex.encoding=T.sRGBEncoding;
    }
    _matTexCache[matId]=tex; return tex;
  }

  const floorGeo = new T.BoxGeometry(TW, TH, TW);
  // Pisos comuns mantêm a fresta de peça de tabuleiro. A água, por outro
  // lado, encosta exatamente na célula vizinha para parecer uma superfície
  // contínua, mesmo quando é construída com várias casas do mapa.
  const waterFloorGeo = new T.BoxGeometry(1, TH, 1);
  const lavaFloorGeo = new T.BoxGeometry(1, TH, 1);
  const swampFloorGeo = new T.BoxGeometry(1, TH, 1);
  const waterMats = [];
  const deepWaterMats = [];
  const whirlpoolMats = [];
  const lavaBubbleMeshes = [];
  const lavaBubbleGeo = new T.SphereGeometry(0.032, 8, 6);
  const lavaBubbleMat = new T.MeshStandardMaterial({
    color: 0xffa51f, emissive: 0xff3a00, emissiveIntensity: 1.5,
    roughness: 0.28, metalness: 0.02, transparent: true, opacity: 0.82,
    depthWrite: false
  });
  const waterRippleGeo = new T.RingGeometry(0.11, 0.16, 20);
  const waterRippleMat = new T.MeshBasicMaterial({
    color: 0xb8f5ff, transparent: true, opacity: 0.25,
    side: T.DoubleSide, depthWrite: false, blending: T.AdditiveBlending
  });
  const deepWaterRippleMat = new T.MeshBasicMaterial({
    color: 0x4f9be6, transparent: true, opacity: 0.13,
    side: T.DoubleSide, depthWrite: false, blending: T.AdditiveBlending
  });
  const whirlpoolRippleMat = new T.MeshBasicMaterial({
    color: 0xd2fbff, transparent: true, opacity: 0.34,
    side: T.DoubleSide, depthWrite: false, blending: T.AdditiveBlending
  });
  // Faixa espiral contínua: os anéis independentes pareciam círculos
  // artificiais. A faixa começa no centro e abre em espiral, como uma
  // corrente de água sendo puxada para o ralo.
  const whirlpoolRibbonGeo = (() => {
    const vertices = [], indices = [], samples = 150, turns = Math.PI * 3.7;
    for(let i=0; i<samples; i++){
      const q = i / (samples - 1);
      const angle = q * turns;
      const radius = 0.035 + q * 0.405;
      const dr = 0.405 / (samples - 1);
      const tx = -Math.sin(angle) * radius + Math.cos(angle) * dr;
      const ty =  Math.cos(angle) * radius + Math.sin(angle) * dr;
      const len = Math.max(0.0001, Math.hypot(tx, ty));
      const nx = -ty / len, ny = tx / len;
      const width = 0.010 + q * 0.009;
      const px = Math.cos(angle) * radius, py = Math.sin(angle) * radius;
      vertices.push(px + nx * width, py + ny * width, 0,
                    px - nx * width, py - ny * width, 0);
      if(i){
        const a = (i - 1) * 2, b = i * 2;
        indices.push(a, a + 1, b, a + 1, b + 1, b);
      }
    }
    const geo = new T.BufferGeometry();
    geo.setAttribute('position', new T.Float32BufferAttribute(vertices, 3));
    geo.setIndex(indices); geo.computeBoundingSphere();
    return geo;
  })();
  const waterRippleMeshes = [];
  const deepWaterRippleMeshes = [];
  const whirlpoolMeshes = [];
  const wallGeo  = new T.BoxGeometry(TW, WH, TW);
  function makeDuneWallGeo(gx, gy){
    const r = _rng(((gx * 73856093) ^ (gy * 19349663) ^ 0xD00DE) >>> 0);
    const segs = 14;
    const height = 1.18 + r() * .42;
    const rings = [
      { radius:.18, y:height*.86 },
      { radius:.40, y:height*.62 },
      { radius:.63, y:height*.31 },
      { radius:.80, y:.035 },
    ];
    const pos = [0, height, 0], uv = [.5, 1];
    const starts = [];
    for(const ring of rings){
      starts.push(pos.length / 3);
      for(let i=0;i<segs;i++){
        const a = i/segs*Math.PI*2;
        const wobble = .94 + r()*.12;
        const rx = ring.radius * wobble * (1 + .06*Math.sin(a*3 + gx));
        const rz = ring.radius * (1.02 - .08*Math.cos(a*2 + gy)) * wobble;
        pos.push(Math.cos(a)*rx, ring.y, Math.sin(a)*rz);
        uv.push(.5 + Math.cos(a)*ring.radius/.9, ring.y/height);
      }
    }
    const bottom = pos.length / 3;
    pos.push(0, 0, 0); uv.push(.5, 0);
    const idx = [];
    for(let i=0;i<segs;i++) idx.push(0, starts[0]+i, starts[0]+(i+1)%segs);
    for(let ring=0;ring<rings.length-1;ring++){
      const a=starts[ring], b=starts[ring+1];
      for(let i=0;i<segs;i++){
        const n=(i+1)%segs;
        idx.push(a+i,b+i,a+n, a+n,b+i,b+n);
      }
    }
    const last=starts[starts.length-1];
    for(let i=0;i<segs;i++) idx.push(bottom,last+(i+1)%segs,last+i);
    const geo = new T.BufferGeometry();
    geo.setAttribute('position', new T.Float32BufferAttribute(pos,3));
    geo.setAttribute('uv', new T.Float32BufferAttribute(uv,2));
    geo.setIndex(idx); geo.computeVertexNormals();
    return geo;
  }
  function makeRockWallGeo(gx, gy){
    const r = _rng(((gx * 83492791) ^ (gy * 29712133) ^ 0xC0BA17) >>> 0);
    const segs = 9;
    const height = 1.40 + r() * .30;
    const rings = [
      { radius:.58, y:.035 },
      { radius:.54, y:height*.28 },
      { radius:.43, y:height*.62 },
      { radius:.28, y:height*.88 },
    ];
    const pos = [], uv = [], starts = [];
    const cx = (r()-.5)*.12, cz = (r()-.5)*.12;
    for(const ring of rings){
      starts.push(pos.length / 3);
      for(let i=0;i<segs;i++){
        const a=i/segs*Math.PI*2;
        const wobble=.80+r()*.36;
        const facet = 1 + .10*Math.sin(a*2 + gx*.7) + .07*Math.cos(a*3 + gy);
        const rx=ring.radius*wobble*facet, rz=ring.radius*(.86+r()*.25)*wobble;
        pos.push(cx+Math.cos(a)*rx, ring.y + (r()-.5)*.035, cz+Math.sin(a)*rz);
        uv.push(.5+Math.cos(a)*.5, ring.y/height);
      }
    }
    const top = pos.length / 3;
    pos.push(cx+(r()-.5)*.16, height+(r()-.5)*.035, cz+(r()-.5)*.16); uv.push(.5,1);
    const bottom = pos.length / 3;
    pos.push(cx, 0, cz); uv.push(.5,0);
    const idx=[];
    for(let i=0;i<segs;i++) idx.push(top, starts[3]+(i+1)%segs, starts[3]+i);
    for(let ring=0;ring<rings.length-1;ring++){
      const a=starts[ring], b=starts[ring+1];
      for(let i=0;i<segs;i++){
        const n=(i+1)%segs;
        idx.push(a+i,b+i,a+n, a+n,b+i,b+n);
      }
    }
    for(let i=0;i<segs;i++) idx.push(bottom, starts[0]+i, starts[0]+(i+1)%segs);
    const geo=new T.BufferGeometry();
    geo.setAttribute('position', new T.Float32BufferAttribute(pos,3));
    geo.setAttribute('uv', new T.Float32BufferAttribute(uv,2));
    geo.setIndex(idx); geo.computeVertexNormals();
    return geo;
  }

  // Warm brownish ambient — dark but not pitch-black. Areas away from torches
  // are still barely readable; the torches provide the main visible illumination.
  // Warm-white ambient — ensures shadow areas are still readable
  const ambient = new T.AmbientLight(AMBL.ambient.color, AMBL.ambient.intensity);
  scene.add(ambient);

  // Main directional — warm key light from front-right above
  const showcase = new T.DirectionalLight(AMBL.dirMain.color, AMBL.dirMain.intensity);
  showcase.position.set(...AMBL.dirMain.pos);
  showcase.castShadow = true;
  showcase.shadow.mapSize.width = showcase.shadow.mapSize.height = 2048;
  showcase.shadow.camera.far    = 120;
  showcase.shadow.camera.left   = -(W + 6);
  showcase.shadow.camera.right  =  (W + 6);
  showcase.shadow.camera.top    =  (H + 6);
  showcase.shadow.camera.bottom = -(H + 6);
  showcase.shadow.bias = -0.0004;
  // O sol nunca se mexe: re-renderizar o mapa inteiro no shadow map a cada frame
  // é desperdício (231 draw calls/frame). Congelado aqui; quem move geometria
  // pede a atualização via _pedirSombraDirecional() — o Three.js baixa o
  // needsUpdate sozinho depois de redesenhar uma vez.
  showcase.shadow.autoUpdate = false;
  showcase.shadow.needsUpdate = true;   // primeiro quadro precisa desenhar
  scene.add(showcase);

  // Cool fill — back-left; contrasts lit vs shadow without over-darkening
  const fillLight = new T.DirectionalLight(AMBL.dirFill.color, AMBL.dirFill.intensity);
  fillLight.position.set(...AMBL.dirFill.pos);
  scene.add(fillLight);

  // Warm back-rim — preserves silhouette readability on miniature backs
  const rimLight = new T.DirectionalLight(AMBL.rimLight.color, AMBL.rimLight.intensity);
  rimLight.position.set(...AMBL.rimLight.pos);
  scene.add(rimLight);

  // SW pawn-front light — as frentes das miniaturas apontam para sudoeste
  // (lado da câmera padrão) e ficavam de costas para dirMain (NE). Antes cada
  // peão carregava 2–3 PointLights próprias para compensar; esta directional
  // única ilumina todas as frentes com custo fixo e contagem de luzes ESTÁVEL
  // (variar o nº de luzes força o Three.js a recompilar todos os shaders).
  const pawnLight = new T.DirectionalLight(AMBL.dirPawn.color, AMBL.dirPawn.intensity);
  pawnLight.position.set(...AMBL.dirPawn.pos);
  scene.add(pawnLight);

  // Player-carried torch — warm flicker, follows player each frame.
  const torch = new T.PointLight(0xff9520, 5.5, 14.0, 1.8);
  // SEM sombra: sombra de PointLight é um cubemap — 6 renders da cena inteira por
  // frame — e esta luz acompanha o peão, então nada é reaproveitável entre frames.
  // Medido no mapa 44×40 revelado: 4,8 ms/frame (21% do quadro) e 561 draw calls
  // só nela. Os peões seguem ancorados pela sombra blob (isGroundDecal).
  torch.castShadow = false;
  scene.add(torch);

  // Vision lamp — bright white-warm fill ensuring clear sight within ~3 tiles.
  // No shadows (performance), positioned at eye-level so it lights miniatures well.
  // Decay=1.6 gives smooth falloff: bright at <2 tiles, dim at 4, invisible at 5.
  const visionLamp = new T.PointLight(0xfff8e8, 14.0, 9.0, 1.4);  // large bright halo around player
  scene.add(visionLamp);

  // ── WALL-SCONCE ANCHORS (posições de luz; iluminadas pelo POOL fixo) ─────────
  // Sem PointLight própria por arandela: ligar/desligar luzes ao revelar área
  // muda a CONTAGEM de luzes visíveis e força o Three.js a recompilar todos os
  // shaders (travada perceptível). O pool de luzes abaixo cobre as âncoras
  // reveladas mais próximas do herói.
  const sconces = [];
  for(let ty=0; ty<H; ty++){
    for(let tx=0; tx<W; tx++){
      if(state.tiles[ty][tx] !== TILE_WALL) continue;
      const th = ((tx*3761)^(ty*2399))&0xFF;
      if(th%7 !== 0) continue;
      const hasFloor = [[0,1],[0,-1],[1,0],[-1,0]].some(([dx,dy])=>{
        const nx=tx+dx, ny=ty+dy;
        return nx>=0&&ny>=0&&nx<W&&ny<H&&state.tiles[ny][nx]===TILE_FLOOR;
      });
      if(!hasFloor) continue;
      sconces.push({x:tx, y:ty, revealed:false});
    }
  }

  // ── PER-ROOM TORCHES (bracket + flame geometry; luz vem do pool) ─────────────
  const wallTorches = [];
  let torchStaticMeshes = {};
  try{ torchStaticMeshes = buildRoomTorches(T, scene, state, wallTorches, TW, TH, WH) || {}; }
  catch(e){ console.warn('buildRoomTorches:', e); }

  // ── LIGHT POOL (contagem de luzes CONSTANTE — zero recompilações em jogo) ────
  // Pool fixo de PointLights sempre-visíveis, reatribuídas às âncoras reveladas
  // (tochas de sala + arandelas) mais próximas do herói. "Apagada" = intensity 0
  // — nunca visible=false, que mudaria a contagem e recompilaria os shaders.
  const lightPool = [];
  for(let i=0; i<LIGHT_POOL_N; i++){
    const pl = new T.PointLight(0xffaa44, 0, 7.5, 1.8);
    pl.position.set(0, -50, 0);   // estacionada fora do tabuleiro até ser atribuída
    scene.add(pl);
    lightPool.push({ light: pl, anchor: null });
  }

  // Sombra de contato suave: melhora a leitura da miniatura no tile sem criar
  // uma PointLight ou um shadow map individual para cada peão.
  const softShadowCanvas = document.createElement('canvas');
  softShadowCanvas.width = softShadowCanvas.height = 96;
  const softShadowCtx = softShadowCanvas.getContext('2d');
  const softShadowGrad = softShadowCtx.createRadialGradient(48,48,5,48,48,48);
  softShadowGrad.addColorStop(0, 'rgba(0,0,0,0.72)');
  softShadowGrad.addColorStop(0.48, 'rgba(0,0,0,0.42)');
  softShadowGrad.addColorStop(1, 'rgba(0,0,0,0)');
  softShadowCtx.fillStyle = softShadowGrad;
  softShadowCtx.fillRect(0,0,96,96);
  const softShadowTex = new T.CanvasTexture(softShadowCanvas);
  const softShadowMat = new T.MeshBasicMaterial({
    map:softShadowTex, color:0x000000, transparent:true,
    opacity:VC.feedback?.shadowOpacity ?? 0.60, depthWrite:false
  });

  // ── ROOM FLOOR OVERLAYS (colored translucent plane per room role) ─────────────
  const roomOverlayMeshes = {};
  try{ buildRoomOverlays(T, scene, state, roomOverlayMeshes, TW, TH); }catch(e){ console.warn('buildRoomOverlays:', e); }

  let sceneryMeshes = {};
  try{ sceneryMeshes = buildSceneryBarrels(T, scene, state, TW, TH, WH); }catch(e){ console.warn('buildSceneryBarrels:', e); }

  // ── GLOWING GROUT (magic rune grid lines in trap rooms) ───────────────────────
  let groutMeshes = {}, groutMats = [];
  try{ ({ meshes: groutMeshes, mats: groutMats } = buildGlowingGrout(T, scene, state, TW, TH)); }catch(e){ console.warn('buildGlowingGrout:', e); }

  // ── MOVEMENT HIGHLIGHT PLANES (blue — MeshBasicMaterial, unaffected by lighting)
  // Todas as famílias abaixo cobrem uma casa por vez e ficam invisíveis quase
  // o tempo todo: nascem sob demanda (ver _mkOverlayPool). O filtro de tipo de
  // casa que o laço antigo fazia vive agora dentro da fábrica.
  const _ehChao   = (x, y) => (state.tiles[y] && state.tiles[y][x] === TILE_FLOOR)
    || !!ponteNaCasa3D(state, x, y);
  const _ehPisavel = (x, y) => (state.tiles[y] &&
    (state.tiles[y][x] === TILE_FLOOR || state.tiles[y][x] === TILE_DOOR))
    || !!ponteNaCasa3D(state, x, y);
  // "12,7" → [12, 7]
  const _xyDaChave = (key) => { const v = key.split(','); return [+v[0], +v[1]]; };
  // Fábrica comum dos realces de chão: um plano deitado na casa, invisível.
  const _mkPlano = (geo, mat, yoff, elegivel, topoFn = topoSuperficie3D) => (key) => {
    const [x, y] = _xyDaChave(key);
    if(!elegivel(x, y)) return null;
    const m = new T.Mesh(geo, mat);
    m.rotation.x = -Math.PI / 2;
    m.position.set(x, topoFn(state, x, y, TH) + yoff, y);
    m.visible = false;
    scene.add(m);
    return m;
  };

  const moveHighlightMat = new T.MeshBasicMaterial({ color: 0x1e6bff, opacity: 0.45, transparent: true, depthWrite: false });
  const moveHighlightMeshes = _mkOverlayPool(
    _mkPlano(new T.PlaneGeometry(TW * 0.90, TW * 0.90), moveHighlightMat, 0.004, _ehChao, topoSuperficie3D));

  // Cursor virtual do joystick: uma única malha, deslocada sobre a casa-alvo.
  // Não participa do raycast, nem do estado autoritativo do tabuleiro.
  const gamepadCursorMat = new T.MeshBasicMaterial({
    color: 0xff3434, transparent: true, opacity: 0.82,
    side: T.DoubleSide, depthWrite: false
  });
  const gamepadCursorMesh = new T.Mesh(new T.PlaneGeometry(TW * 0.88, TW * 0.88), gamepadCursorMat);
  gamepadCursorMesh.rotation.x = -Math.PI / 2;
  gamepadCursorMesh.position.y = TH + 0.036;
  gamepadCursorMesh.visible = false;
  gamepadCursorMesh.renderOrder = 30;
  gamepadCursorMesh.userData.noRay = true;
  scene.add(gamepadCursorMesh);

  // ── ATTACK HIGHLIGHT PLANES (red — MeshBasicMaterial, unaffected by lighting)
  const atkHighlightMeshes = _mkOverlayPool(
    _mkPlano(new T.PlaneGeometry(TW * 0.90, TW * 0.90),
      new T.MeshBasicMaterial({ color: 0xff2222, opacity: 0.35, transparent: true, depthWrite: false }),
      0.006, _ehChao));

  // ── WEAPON RANGE PREVIEW PLANES (vermelho forte — hover no ícone da arma)
  const weaponRangeMeshes = _mkOverlayPool(
    _mkPlano(new T.PlaneGeometry(TW * 0.92, TW * 0.92),
      new T.MeshBasicMaterial({ color: 0xff0000, opacity: 0.62, transparent: true, depthWrite: false }),
      0.010, _ehChao));

  // ── PRÉVIA DO MESTRE: alcance e zona efetiva do monstro sob o cursor ────────
  // Estas cinco também cobrem porta, não só chão.
  const _geoMestre = new T.PlaneGeometry(TW * 0.90, TW * 0.90);
  const masterAttackRangeMeshes = _mkOverlayPool(
    _mkPlano(_geoMestre, new T.MeshBasicMaterial({ color: 0xff3838, opacity: 0.16, transparent: true, depthWrite: false }), 0.013, _ehPisavel));
  const masterAttackZoneMeshes = _mkOverlayPool(
    _mkPlano(_geoMestre, new T.MeshBasicMaterial({ color: 0xd21218, opacity: 0.38, transparent: true, depthWrite: false }), 0.015, _ehPisavel));
  const masterFootprintMeshes = _mkOverlayPool(
    _mkPlano(_geoMestre, new T.MeshBasicMaterial({ color: 0xffc22e, opacity: 0.22, transparent: true, depthWrite: false }), 0.017, _ehPisavel));
  const masterHistoryAttackerMeshes = _mkOverlayPool(
    _mkPlano(_geoMestre, new T.MeshBasicMaterial({ color: 0x54d8ff, opacity: 0.34, transparent: true, depthWrite: false }), 0.019, _ehPisavel));
  const masterHistoryTargetMeshes = _mkOverlayPool(
    _mkPlano(_geoMestre, new T.MeshBasicMaterial({ color: 0xff6b8a, opacity: 0.34, transparent: true, depthWrite: false }), 0.021, _ehPisavel));

  // ── SPELL HIGHLIGHT PLANES — alcance (vermelho), zona (laranja), 2x (verde escuro), área (verde)
  const _geoSpell = new T.PlaneGeometry(TW * 0.98, TW * 0.98);
  const _mkSpell = (hex, op, yoff) => _mkOverlayPool(_mkPlano(_geoSpell,
    new T.MeshBasicMaterial({ color: hex, opacity: op, transparent: true, depthWrite: false }),
    yoff, _ehChao));
  const spellEscuridaoMeshes = _mkSpell(0x0a061a, 0.60, 0.007);   // névoa escura (sob os peões)
  const spellSilencioMeshes  = _mkSpell(0x7888c8, 0.26, 0.0072);  // véu de silêncio
  // A intensidade das duas camadas de MIRA vem de AIM_COLORS (fonte unica,
  // com a calibragem medida documentada la). As demais sao efeitos do jogo,
  // nao mira, e mantem os proprios valores.
  const spellRangeMeshes     = _mkSpell(AIM_COLORS.range.hex, AIM_COLORS.range.op, 0.008);
  const spellZonaMeshes      = _mkSpell(0xff6a00, 0.30, 0.009);
  const spellDoubleMeshes    = _mkSpell(0x0a5a16, 0.60, 0.010);
  const spellAreaMeshes      = _mkSpell(AIM_COLORS.valid.hex, AIM_COLORS.valid.op, 0.012);
  const spellTargetMeshes = {
    self:  _mkSpell(0xf5be2a, 0.52, 0.014),
    ally:  _mkSpell(0x3791ff, 0.44, 0.0145),
    enemy: _mkSpell(0xeb2d32, 0.52, 0.015),
  };

  // ── Fogo persistente da Bola de Fogo: 1 brilho + 5 chamas + 14 brasas ────────
  // Eram 21 objetos com geometria e material PRÓPRIOS por casa de chão — 18.522
  // nós num mapa 44×40, metade da cena inteira, para um efeito que cobre poucas
  // casas e só depois que alguém conjura. Nasce sob demanda como o resto; as
  // geometrias e o formato das chamas são compartilhados entre as casas.
  const _fireGlowGeo = new T.PlaneGeometry(TW * .96, TW * .96);
  const _fireFlameDefs = [[-.39,.18,0xff3b00], [-.21,.28,0xff6a00], [.00,.36,0xffa800], [.22,.27,0xff6a00], [.40,.16,0xffd43b]];
  const _fireFlameGeos = _fireFlameDefs.map((d, i) => new T.ConeGeometry(TW * (.075 + (i % 2) * .018), TH * d[1], 8));
  const _fireEmberGeos = [0,1,2].map(k => new T.SphereGeometry(.016 + k * .006, 6, 4));
  const spellFireFx = _mkOverlayPool((key) => {
    const [fx, fy] = _xyDaChave(key);
    if(!_ehChao(fx, fy)) return null;
    const fireGroup = new T.Group(); fireGroup.position.set(fx, 0, fy);
    const fireGlowMat = new T.MeshBasicMaterial({ color:0xff4a00, transparent:true, opacity:0.52, depthWrite:false, side:T.DoubleSide, blending:T.AdditiveBlending });
    // Plano quase do tamanho total da casa: a brasa persistente ocupa o tile
    // inteiro, e não apenas um círculo no centro.
    const fireGlow = new T.Mesh(_fireGlowGeo, fireGlowMat);
    fireGlow.rotation.x = -Math.PI / 2; fireGlow.position.y = TH + .021; fireGlow.renderOrder = 18; fireGroup.add(fireGlow);
    const flames = _fireFlameDefs.map(([ox,h,col], i) => {
      const mat = new T.MeshBasicMaterial({ color:col, transparent:true, opacity:.76, depthWrite:false, side:T.DoubleSide, blending:T.AdditiveBlending });
      const m = new T.Mesh(_fireFlameGeos[i], mat);
      m.position.set(ox, TH + .07 + TH * h * .5, -.34 + (i % 3) * .31);
      m.userData.firePhase = i * 1.9 + fx * .37 + fy * .61;
      m.renderOrder = 19; fireGroup.add(m); return m;
    });
    const embers = [];
    for(let i = 0; i < 14; i++){
      const phase = i * 1.37 + fx * .41 + fy * .73;
      const ex = -.43 + _bolaFogoHash(fx * 7919 + fy * 1543 + i * 31337) * .86;
      const ez = -.43 + _bolaFogoHash(fx * 9283 + fy * 2713 + i * 17389) * .86;
      const mat = new T.MeshBasicMaterial({ color:i % 4 ? 0xff7a13 : 0xffe06a, transparent:true, opacity:.68, depthWrite:false, depthTest:false, blending:T.AdditiveBlending });
      const m = new T.Mesh(_fireEmberGeos[i % 3], mat);
      m.position.set(ex, TH + .036 + (i % 3) * .006, ez);
      m.userData.firePhase = phase; m.userData.baseX = ex; m.userData.baseZ = ez;
      m.renderOrder = 20; fireGroup.add(m); embers.push(m);
    }
    fireGroup.visible = false; scene.add(fireGroup);
    // `visible` é delegado ao grupo para o pool poder tratar esta família como
    // as outras (_overlayShowOnly só conhece `.visible`).
    const fx3 = { group:fireGroup, glow:fireGlow, flames, embers };
    Object.defineProperty(fx3, 'visible', {
      get(){ return fireGroup.visible; },
      set(v){ fireGroup.visible = v; },
    });
    return fx3;
  });

  // ── Labaredas persistentes da Prisão de Chamas ─────────────────────────────
  // Diferente do fogo procedural usado pela Bola de Fogo, cada casa da borda
  // recebe o mesmo GLB animado da decoração Chama Viva. O pool continua
  // preguiçoso: só cria/carrega as casas que pertencem a uma prisão ativa.
  const spellLivingFlameFx = _mkOverlayPool((key) => {
    const [fx, fy] = _xyDaChave(key);
    if(!_ehChao(fx, fy)) return null;
    const fireGroup = new T.Group();
    fireGroup.name = 'prisao-chamas-viva';
    fireGroup.position.set(fx, 0, fy);
    fireGroup.visible = false;
    scene.add(fireGroup);
    const embers = [];
    const emberGeo = new T.SphereGeometry(.018, 5, 4);
    for(let i = 0; i < 5; i++){
      const phase = i * 1.47 + fx * .31 + fy * .67;
      const emberMat = new T.MeshBasicMaterial({
        color: i % 3 ? 0xff7a13 : 0xffe06a, transparent:true, opacity:.7,
        depthWrite:false, depthTest:false, blending:T.AdditiveBlending
      });
      const ember = new T.Mesh(emberGeo, emberMat);
      ember.position.set(
        -.30 + (i * .147) % .60,
        DECOR_GLB_FLOOR_Y + .08 + (i % 3) * .04,
        -.25 + ((i * .193) % .50)
      );
      ember.renderOrder = 81;
      ember.userData = {
        phase, speed: .72 + (i % 3) * .16,
        baseX: ember.position.x, baseZ: ember.position.z
      };
      fireGroup.add(ember); embers.push(ember);
    }
    // Línguas de fogo (sprites aditivos) + brilho de base. O ciclo de cada
    // uma é determinístico pela casa, para casas vizinhas não pulsarem juntas.
    const tongueTex = _texturaLinguaFogo(T);
    const tongues = [];
    for(let i = 0; i < 6; i++){
      const h = k => _bolaFogoHash(fx * 7919 + fy * 1543 + i * 31337 + k * 7127);
      const mat = new T.SpriteMaterial({
        map:tongueTex, color:0xffc060, transparent:true, opacity:0,
        depthWrite:false, blending:T.AdditiveBlending
      });
      const s = new T.Sprite(mat);
      s.renderOrder = 82;
      s.userData = {
        phase: h(1), speed: .85 + h(2) * .75, swayHz: 5 + h(3) * 4,
        ox: -.30 + h(4) * .60, oz: -.26 + h(5) * .52,
        rise: .40 + h(6) * .35, w: .16 + h(7) * .10, h: .42 + h(8) * .30
      };
      fireGroup.add(s); tongues.push(s);
    }
    const glowMat = new T.SpriteMaterial({
      map:_texturaBrilhoFogo(T), color:0xffffff, transparent:true, opacity:.35,
      depthWrite:false, blending:T.AdditiveBlending
    });
    const glow = new T.Sprite(glowMat);
    glow.position.set(0, DECOR_GLB_FLOOR_Y + .18, 0);
    glow.scale.set(1.0, .7, 1);
    glow.renderOrder = 78;
    glow.userData.phase = fx * 1.3 + fy * 2.7;
    fireGroup.add(glow);
    const fx3 = { group:fireGroup, livingFlames:[], embers, tongues, glow };
    Object.defineProperty(fx3, 'visible', {
      get(){ return fireGroup.visible; },
      set(v){ fireGroup.visible = v; },
    });

    const flamePath = (typeof DECOR_GLB_TYPES !== 'undefined' && DECOR_GLB_TYPES.chama_viva)
      || 'assets/objetos/chama_viva.glb';
    _loadDecorGLB(T, flamePath, template => {
      if(!template || !fireGroup.parent) return;
      const inst = template.clone(true);
      const box = new T.Box3().setFromObject(inst);
      const size = box.getSize(new T.Vector3());
      const fit = Math.min(
        .84 / Math.max(size.x, 1e-3),
        .84 / Math.max(size.z, 1e-3),
        .98 / Math.max(size.y, 1e-3)
      );
      inst.position.set(
        -(box.min.x + box.max.x) / 2,
        -box.min.y,
        -(box.min.z + box.max.z) / 2
      );
      inst.traverse(o => {
        if(o.isMesh){ o.castShadow = true; o.receiveShadow = true; }
      });
      const wrap = new T.Group();
      wrap.position.y = DECOR_GLB_FLOOR_Y;
      wrap.renderOrder = 79;
      wrap.add(inst);
      wrap.scale.setScalar(fit);
      // A visibilidade é controlada pelo grupo do pool; não esconda o wrap
      // quando o GLB carregar enquanto a zona já estiver ativa.
      wrap.visible = true;
      fireGroup.add(wrap);
      const clips = (template.userData && template.userData._gltfAnimations) || [];
      const mixer = clips.length ? new T.AnimationMixer(inst) : null;
      if(mixer) for(const clip of clips) mixer.clipAction(clip).play();
      fx3.livingFlames.push({
        mixer, lastAt:performance.now(), wrap, baseScale:fit,
        phase: (fx * 1.71 + fy * 2.39 + Math.random() * Math.PI * 2)
      });
    });
    return fx3;
  });

  // ── WET FLOOR REFLECTION (damp specular sheen — all dungeon floor tiles) ──────
  // A near-black low-roughness plane floats 2mm above each floor piece.
  // MeshStandardMaterial roughness 0.10 produces sharp torch reflections.
  // Uma InstancedMesh no lugar de um mesh por casa. Eram 882 draw calls num
  // mapa 44x40 -- 2,5 ms/quadro de um brilho sutil -- e o custo so aparecia
  // conforme a nevoa abria, porque cada casa revelada acrescentava um objeto
  // desenhado. Medido: 3.582 draw calls custavam 10,8 ms/quadro, ~3 us cada.
  // Aqui todas as casas ja compartilham UMA geometria e UM material, entao
  // instanciar e direto: mesmo visual, 1 draw call.
  //
  // A nevoa vira `count` + matrizes: ver _atualizarWetFloor3D. O rebuild so
  // acontece quando o conjunto revelado muda (andar), nao a cada quadro.
  const wetFloorKeys = [];          // ordem fixa; o indice e o slot da instancia
  let wetFloorInst = null;
  {
    const wetGeo = new T.PlaneGeometry(TW * 0.94, TW * 0.94);
    const wetMat = new T.MeshStandardMaterial({
      color: new T.Color(0x111111), roughness: 0.10, metalness: 0.0,
      opacity: 0.30, transparent: true, depthWrite: false
    });
    for(let fy=0; fy<H; fy++)
      for(let fx=0; fx<W; fx++)
        if(state.tiles[fy][fx] === TILE_FLOOR) wetFloorKeys.push([fx, fy]);
    if(wetFloorKeys.length){
      wetFloorInst = new T.InstancedMesh(wetGeo, wetMat, wetFloorKeys.length);
      wetFloorInst.count = 0;                       // nada revelado ainda
      wetFloorInst.instanceMatrix.setUsage(T.DynamicDrawUsage);
      // O bounding da InstancedMesh sai da geometria de UMA instancia, que fica
      // na origem; sem isto o tabuleiro inteiro seria descartado pelo frustum.
      wetFloorInst.frustumCulled = false;
      wetFloorInst.receiveShadow = true;
      scene.add(wetFloorInst);
    }
  }

  const tileMeshes = {};

  // ── Cache de materiais de casa ───────────────────────────────────────────────
  // Antes cada casa clonava floorBaseMat/wallBaseMat só para aplicar um jitter de
  // cor minúsculo: 1.760 materiais distintos num mapa 44×40. Como o renderer troca
  // de estado a cada material, isso custava ~30% do quadro (medido no mapa todo
  // revelado: 22,6 → 15,9 ms/frame, com o MESMO número de draw calls — o custo era
  // troca de estado, não quantidade de objetos). Agora o jitter é quantizado em
  // JITTER_PASSOS faixas (imperceptível a olho) e casas de mesma aparência
  // compartilham o material. Casas com textura própria têm a cor forçada a
  // (1,1,1), então colapsam num único material por tipo de material.
  //
  // ATENÇÃO: material compartilhado NÃO pode ser mutado por casa. Quem precisa
  // mutar (as paredes de passagem secreta, em renderMap3D) usa uma cópia própria
  // guardada em userData.secretMat e volta para userData.sharedMat depois.
  const JITTER_PASSOS = 12;
  const _tileMatCache = {};
  const lavaMats = [];
  const swampMats = [];
  const _quantJit = (v) => Math.round(v * (JITTER_PASSOS - 1)) / (JITTER_PASSOS - 1);

  for(let y=0; y<H; y++){
    for(let x=0; x<W; x++){
      const key = `${x},${y}`;
      let mesh;
      // Per-tile hash: drives independent colour variation per piece
      const vf = ((x*7919^y*3467)&0xFF) / 255;
      const vw = ((x*6271^y*4423)&0xFF) / 255;

      if(state.tiles[y][x] === TILE_FLOOR || state.tiles[y][x] === TILE_DOOR){
        const elev3 = elevacaoTerreno(state, x, y);
        // Cor base por material (default pedra_cinza); jitter por casa preserva o relevo.
        const mid3 = (state.materiais && state.materiais[key]) || 'pedra_cinza';
        const mc = (VC.materiais[mid3] || VC.materiais.pedra_cinza).color;
        // A água não recebe jitter por tile: variações independentes fariam
        // aparecer uma grade onde deveriam existir apenas ondas contínuas.
        const isWater3 = mid3==='agua' || mid3==='agua_profunda';
        const isWhirlpool3 = mid3==='rodamoinho';
        const isDeepWhirlpool3 = mid3==='rodamoinho_profundo';
        const isLava3 = mid3==='lava';
        const isSwamp3 = mid3==='pantano';
        const ftex = makeMaterialTex(mid3);
        // Com textura própria ou água a cor final não depende do jitter (é fixada
        // abaixo), então essas casas colapsam num material único por tipo.
        const jitQ = (isWater3 || isWhirlpool3 || isDeepWhirlpool3 || isLava3 || isSwamp3 || ftex) ? 0 : _quantJit(vf);
        const fKey = `f|${mid3}|${jitQ}`;
        let mat = _tileMatCache[fKey];
        if(!mat){
          mat = floorBaseMat.clone();
          const jit = jitQ * VC.floor.baseVariance;
          mat.color.setRGB(mc[0]+jit, mc[1]+jit, mc[2]+jit);
          if(ftex){
            mat.map = ftex; mat.color.setRGB(1,1,1);
            mat.bumpMap = ftex;
            mat.bumpScale = mid3==='terra' ? 0.075 : mid3==='grama' ? 0.045 : mid3==='areia_deserto' ? 0.012 : mid3==='lava' ? 0.024 : 0.035;
            // Grama e terra recebem o mesmo desenho procedimental do 2D também
            // como relevo, tornando a textura perceptível sob a luz do 3D.
            if(mid3==='grama' || mid3==='terra' || mid3==='areia_deserto' || mid3==='lava' || mid3==='pantano'){
              mat.bumpMap = ftex;
              mat.bumpScale = mid3==='terra' ? 0.075 : mid3==='areia_deserto' ? 0.012 : mid3==='lava' ? 0.024 : mid3==='pantano' ? 0.018 : 0.045;
              mat.roughness = mid3==='terra' ? 0.94 : mid3==='lava' ? 0.38 : mid3==='pantano' ? 0.58 : 0.98;
            }
          }
          mat.emissive.set(VC.floor.emissive);
          mat.emissiveIntensity = 1.0;
          if(isWater3){
            // Superfície azul e mais lustrosa que pedra: indica água rasa ou
            // profunda sem transformá-la em obstáculo de navegação. A textura
            // própria pode deslizar sem afetar os demais pisos.
            const profunda = mid3 === 'agua_profunda';
            mat.roughness = 0.24;
            mat.metalness = 0.12;
            mat.emissive.set(profunda ? 0x06173f : 0x0075bd);
            mat.emissiveIntensity = profunda ? 0.58 : 0.92;
            mat.bumpMap = null;
            mat.bumpScale = 0;
            mat.emissiveMap = null;
          }
          if(isWhirlpool3){
            mat.roughness = 0.20;
            mat.metalness = 0.10;
            mat.emissive.set(0x0075bd);
            mat.emissiveIntensity = 0.82;
            mat.bumpMap = null;
            mat.bumpScale = 0;
            mat.emissiveMap = null;
          }
          if(isDeepWhirlpool3){
            mat.roughness = 0.20;
            mat.metalness = 0.10;
            mat.emissive.set(0x06173f);
            mat.emissiveIntensity = 0.58;
            mat.bumpMap = null;
            mat.bumpScale = 0;
            mat.emissiveMap = null;
          }
          if(isLava3){
            mat.roughness = 0.34;
            mat.metalness = 0.08;
            mat.emissiveMap = ftex;
            mat.emissive.set(0xff3b08);
            mat.emissiveIntensity = 1.25;
            mat.bumpMap = ftex;
          }
          if(isSwamp3){
            mat.roughness = 0.56;
            mat.metalness = 0.02;
            mat.emissiveMap = ftex;
            mat.emissive.set(0x17351d);
            mat.emissiveIntensity = 0.22;
            mat.bumpMap = ftex;
          }
          if(mid3 === 'piso_congelado'){
            mat.roughness = 0.10;
            mat.metalness = 0.16;
            mat.emissive.set(0x168fc9);
            mat.emissiveIntensity = 0.52;
            mat.bumpMap = ftex;
            mat.bumpScale = 0.018;
          }
          if(mid3 === 'planicie_nevada'){
            mat.roughness = 0.90;
            mat.metalness = 0.00;
            mat.emissive.set(0xa7b3b3);
            mat.emissiveIntensity = 0.08;
            mat.bumpMap = ftex;
            mat.bumpScale = 0.012;
          }
          // Auto-iluminação: a própria textura emite, deixando a cor forte e
          // diferenciada mesmo na penumbra (grama/terra/pedra negra).
          if(ftex && (mid3==='grama' || mid3==='terra' || mid3==='pedra_negra')){
            mat.emissiveMap = ftex;
            mat.emissive.set(0xffffff);
            mat.emissiveIntensity = (mid3==='pedra_negra') ? 0.35 : 0.6;
          }
          if(mid3 === 'areia_deserto'){
            // A emissão branca do piso de pedra lavava a cor ocre da areia,
            // deixando uma película cinza sobre a textura. A areia recebe
            // apenas um preenchimento quente e discreto, sem emissiveMap.
            mat.emissiveMap = null;
            mat.emissive.set(0x3a210b);
            mat.emissiveIntensity = 0.12;
          }
          _tileMatCache[fKey] = mat;
        }
        if(mid3 === 'agua' && !waterMats.includes(mat)) waterMats.push(mat);
        if(mid3 === 'agua_profunda' && !deepWaterMats.includes(mat)) deepWaterMats.push(mat);
        if(isWhirlpool3 && !whirlpoolMats.includes(mat)) whirlpoolMats.push(mat);
        if(isDeepWhirlpool3 && !whirlpoolMats.includes(mat)) whirlpoolMats.push(mat);
        if(isLava3 && !lavaMats.includes(mat)) lavaMats.push(mat);
        if(isSwamp3 && !swampMats.includes(mat)) swampMats.push(mat);
        mesh = new T.Mesh((isWater3 || isWhirlpool3 || isDeepWhirlpool3 || isLava3 || isSwamp3)
          ? (isLava3 ? lavaFloorGeo : isSwamp3 ? swampFloorGeo : waterFloorGeo) : floorGeo, mat);
        const terrainTop = TH + elev3 * TERRENO_ELEVACAO_STEP_3D;
        const terrainHeight = elev3 >= 0 ? Math.max(TH * 0.5, terrainTop) : TH;
        mesh.scale.y = terrainHeight / TH;
        mesh.position.set(x, elev3 >= 0 ? terrainHeight / 2 : terrainTop - TH / 2, y);
        mesh.receiveShadow = true;
        mesh.userData.isFloor = true;
        mesh.userData.gridX   = x;
        mesh.userData.gridY   = y;
        if((state.materiais && state.materiais[key]) === 'entulho'){
          // Entulho oclui visão → bloco altura-de-parede de escombros sobre o chão.
          let eMat = _tileMatCache['entulho'];
          if(!eMat){
            const ec = VC.materiais.entulho.color;
            eMat = wallBaseMat.clone();
            eMat.color.setRGB(ec[0], ec[1], ec[2]);
            const etex = makeMaterialTex('entulho');
            if(etex){ eMat.map = etex; eMat.color.setRGB(1,1,1); eMat.bumpMap = etex; eMat.bumpScale = 0.06; }
            eMat.emissive.set(VC.wall.emissive); eMat.emissiveIntensity = 1.0;
            _tileMatCache['entulho'] = eMat;
          }
          const eMesh = new T.Mesh(wallGeo, eMat);
          eMesh.position.set(x, elev3 * TERRENO_ELEVACAO_STEP_3D + WH/2, y);
          eMesh.scale.y = 0.7;                 // pilha um pouco mais baixa que a parede
          eMesh.castShadow = eMesh.receiveShadow = true;
          eMesh.visible = false;
          eMesh.userData.gridX = x; eMesh.userData.gridY = y;
          _prepararTileProxy(eMesh);
          tileMeshes[`entulho:${key}`] = eMesh;   // revelado junto com a casa (ver visibilidade)
        }
      } else {
        const matId3 = matDaCasa(state, x, y);
        const wc = (VC.materiais[matId3] || VC.materiais.pedra_normal).color;
        const wtex = makeMaterialTex(matId3);
        // Com textura própria a cor vira (1,1,1): jitter não muda a aparência.
        const jwQ = wtex ? 0 : _quantJit(vw);
        const wKey = `w|${matId3}|${jwQ}`;
        let mat = _tileMatCache[wKey];
        if(!mat){
          mat = wallBaseMat.clone();
          // Cor base por material (default pedra_normal); jitter por casa preserva o relevo.
          const jw = jwQ*VC.wall.variance;
          mat.color.setRGB(wc[0]+jw, wc[1]+jw, wc[2]+jw);
          if(wtex){
            mat.map = wtex; mat.color.setRGB(1,1,1); mat.bumpMap = wtex;
            mat.bumpScale = (matId3 === 'duna_deserto' || matId3 === 'duna_neve') ? 0.018
              : (matId3 === 'rocha' || matId3 === 'rocha_marrom') ? 0.065 : (VC.wall.bumpScale ?? 0.045);
            // wallBaseMat nasce com o roughnessMap da textura de pedra. Para
            // dunas, substituí-lo pela textura arenosa evita a borda cinza
            // herdada do material de alvenaria.
            if(matId3 === 'duna_deserto' || matId3 === 'duna_neve') mat.roughnessMap = wtex;
            if(matId3 === 'rocha' || matId3 === 'rocha_marrom'){
              mat.roughnessMap = wtex;
              mat.roughness = 0.78;
              mat.metalness = 0.02;
            }
          }
          mat.emissive.set(VC.wall.emissive);
          mat.emissiveIntensity = 1.0;
          _tileMatCache[wKey] = mat;
        }
        const isDune3 = matId3 === 'duna_deserto' || matId3 === 'duna_neve';
        const isRock3 = matId3 === 'rocha' || matId3 === 'rocha_marrom';
        mesh = new T.Mesh(isDune3 ? makeDuneWallGeo(x, y)
          : isRock3 ? makeRockWallGeo(x, y) : wallGeo, mat);
        mesh.position.set(x, (isDune3 || isRock3) ? 0 : WH/2, y);
        mesh.castShadow    = true;
        mesh.receiveShadow = true;
        mesh.userData.isWall = true;
        // Guardado para a troca de material das passagens secretas (renderMap3D):
        // o material agora é COMPARTILHADO e não pode ser mutado por casa.
        mesh.userData.sharedMat = mat;
      }
      // Também identifica paredes no grid: necessário para que uma parede
      // ilusória possa receber clique e ser tratada como terreno atravessável.
      mesh.userData.gridX = x;
      mesh.userData.gridY = y;
      mesh.visible = false;     // revealed progressively as player explores
      // NAO entra na cena: quem desenha e a InstancedMesh montada por
      // _rebuildTileInstances. Este mesh continua existindo como "procuracao"
      // -- guarda userData/visible/material e serve de alvo do raycast do
      // clique --, mas nao custa draw call nem travessia. Ver o comentario da
      // funcao para o porque (1.760 draw calls = ~5 ms/quadro).
      _prepararTileProxy(mesh);
      tileMeshes[key] = mesh;
    }
  }

  // ── PONTES ────────────────────────────────────────────────────────────────
  // A ponte é uma camada visual/caminhável própria: cobre o que estiver abaixo
  // sem substituir o tile, seu material ou sua elevação original.
  const bridgeMeshes = [];
  // Madeira permanece como padrão. A variante pedra_rustica usa a textura
  // autoral da ponte e materiais próprios, permitindo misturar os dois tipos
  // no mesmo mapa sem alterar a lógica de movimento.
  const bridgeMaterialSets = new Map();
  function bridgeMaterials(materialId){
    const key = String(materialId || 'madeira').toLowerCase() === 'pedra_rustica'
      ? 'pedra_rustica' : 'madeira';
    if(bridgeMaterialSets.has(key)) return bridgeMaterialSets.get(key);
    let tex;
    if(key === 'pedra_rustica'){
      tex = new T.TextureLoader().load(_assetURL('assets/textures/bridge-stone-rustic.png'));
      tex.wrapS = tex.wrapT = T.RepeatWrapping;
      if(T.SRGBColorSpace) tex.colorSpace = T.SRGBColorSpace;
      else if(T.sRGBEncoding) tex.encoding = T.sRGBEncoding;
    }else{
      tex = makeMaterialTex('madeira_escura');
    }
    const mats = {
      base: new T.MeshStandardMaterial({
        map: tex,
        color: key === 'pedra_rustica' ? 0x4b4844 : 0x5b3217,
        roughness: key === 'pedra_rustica' ? 0.98 : 0.92,
        metalness: 0.0
      }),
      deck: new T.MeshStandardMaterial({
        map: tex,
        color: key === 'pedra_rustica' ? 0xaaa096 : 0xb87838,
        roughness: key === 'pedra_rustica' ? 0.96 : 0.88,
        metalness: 0.0
      })
    };
    bridgeMaterialSets.set(key, mats);
    return mats;
  }
  const bridgeDeckGeoH = new T.BoxGeometry(TW * 0.88, 0.105, 0.88);
  const bridgeDeckGeoV = new T.BoxGeometry(0.88, 0.105, TW * 0.88);
  for(const bridge of (state.pontes || [])){
    const bridgeTiles = _bridgeTiles2D(bridge);
    if(!bridgeTiles.length) continue;
    const bridgeMats = bridgeMaterials(bridge.material);
    const horizontal = bridge.inicio?.[1] === bridge.fim?.[1];
    const height = Number.isInteger(Number(bridge.altura)) ? Number(bridge.altura) : 0;
    const minX = Math.min(...bridgeTiles.map(t => t[0]));
    const maxX = Math.max(...bridgeTiles.map(t => t[0]));
    const minY = Math.min(...bridgeTiles.map(t => t[1]));
    const maxY = Math.max(...bridgeTiles.map(t => t[1]));
    const centerX = (minX + maxX) / 2;
    const centerZ = (minY + maxY) / 2;
    const span = horizontal ? (maxX - minX + 1) : (maxY - minY + 1);
    const width = horizontal ? (maxY - minY + 1) : (maxX - minX + 1);
    const top = TH + height * TERRENO_ELEVACAO_STEP_3D;
    const railLength = Math.max(TW * 0.9, span * TW - 0.10);
    const railGeo = horizontal
      ? new T.BoxGeometry(railLength, 0.14, 0.14)
      : new T.BoxGeometry(0.14, 0.14, railLength);
    const railOffset = Math.max(0.16, width * TW / 2 - 0.18);
    for(const side of [-1, 1]){
      const rail = new T.Mesh(railGeo, bridgeMats.base);
      rail.position.set(
        horizontal ? centerX : centerX + side * railOffset,
        top + 0.065,
        horizontal ? centerZ + side * railOffset : centerZ
      );
      rail.castShadow = true; rail.receiveShadow = true;
      rail.userData.isBridge = true; rail.userData.bridgeBase = true;
      rail.userData.bridgeKey = `${minX},${minY}`;
      rail.userData.bridgeKeys = bridgeTiles.map(([x, y]) => `${x},${y}`);
      rail.userData.gridX = Math.round(centerX);
      rail.userData.gridY = Math.round(centerZ);
      rail.visible = false;
      scene.add(rail); bridgeMeshes.push(rail);
    }
    // Uma tábua por casa no comprimento da ponte, cruzando toda a largura.
    // O pequeno intervalo entre elas deixa as duas longarinas aparecerem.
    for(let step = 0; step < span; step++){
      const bx = horizontal ? minX + step : centerX;
      const by = horizontal ? centerZ : minY + step;
      const plank = new T.Mesh(horizontal ? bridgeDeckGeoH : bridgeDeckGeoV, bridgeMats.deck);
      plank.position.set(bx, top + 0.145, by);
      plank.scale.set(horizontal ? 1 : width, 1, horizontal ? width : 1);
      plank.castShadow = true; plank.receiveShadow = true;
      plank.userData.isBridge = true; plank.userData.bridgeDeck = true;
      plank.userData.bridgeKey = `${Math.round(bx)},${Math.round(by)}`;
      plank.userData.gridX = Math.round(bx);
      plank.userData.gridY = Math.round(by);
      plank.visible = false;
      scene.add(plank); bridgeMeshes.push(plank);
    }
  }

  // Transições puramente visuais entre pisos com um nível de diferença. O
  // declive já é formado pelas laterais espessas das peças; no modo rampa,
  // acrescentamos uma cunha que liga suavemente as duas superfícies. Nenhuma
  // destas malhas participa de colisão, movimento ou linha de visão.
  const terrainTransitionMeshes = [];
  if(state.transicao_altura === 'rampa'){
    // Todas as transições têm sempre a mesma diferença de um nível. Antes uma
    // geometria independente era criada para CADA fronteira entre casas; em
    // mapas grandes isso podia atrasar ou travar a abertura do modo Mestre.
    // Reutilizamos uma geometria por nível inferior (os quatro níveis possíveis).
    const rampGeometries = new Map();
    const rampGeo = (lowLevel) => {
      const cached = rampGeometries.get(lowLevel);
      if(cached) return cached;
      const lowTop = TH + lowLevel * TERRENO_ELEVACAO_STEP_3D;
      const highTop = lowTop + TERRENO_ELEVACAO_STEP_3D;
      const halfLen = 0.25, halfWidth = 0.45, bottom = Math.min(lowTop, highTop) - 0.002;
      const geo = new T.BufferGeometry();
      geo.setAttribute('position', new T.Float32BufferAttribute([
        -halfLen, bottom, -halfWidth, -halfLen, bottom, halfWidth,
         halfLen, bottom, -halfWidth,  halfLen, bottom, halfWidth,
        -halfLen, lowTop + 0.004, -halfWidth, -halfLen, lowTop + 0.004, halfWidth,
         halfLen, highTop + 0.004, -halfWidth,  halfLen, highTop + 0.004, halfWidth,
      ], 3));
      geo.setIndex([
        4, 6, 7, 4, 7, 5, 0, 1, 5, 0, 5, 4,
        2, 6, 3, 3, 6, 7, 0, 4, 2, 2, 4, 6, 1, 3, 7, 1, 7, 5,
      ]);
      geo.computeVertexNormals();
      rampGeometries.set(lowLevel, geo);
      return geo;
    };
    const addRamp = (low, high, horizontal) => {
      const [lx, ly] = low, [hx, hy] = high;
      const lowMesh = tileMeshes[`${lx},${ly}`];
      const lowLevel = elevacaoTerreno(state, lx, ly);
      const highLevel = elevacaoTerreno(state, hx, hy);
      if(!lowMesh || highLevel - lowLevel !== 1) return;
      const ramp = new T.Mesh(rampGeo(lowLevel), lowMesh.material);
      ramp.position.set((lx + hx) / 2, 0, (ly + hy) / 2);
      if(!horizontal) ramp.rotation.y = -Math.PI / 2;
      ramp.castShadow = true; ramp.receiveShadow = true;
      ramp.userData.terrainTransition = true;
      ramp.userData.terrainKeys = [`${lx},${ly}`, `${hx},${hy}`];
      ramp.visible = false;
      scene.add(ramp); terrainTransitionMeshes.push(ramp);
    };
    for(let y=0; y<H; y++) for(let x=0; x<W; x++){
      if(state.tiles[y][x] !== TILE_FLOOR && state.tiles[y][x] !== TILE_DOOR) continue;
      if(x + 1 < W && (state.tiles[y][x+1] === TILE_FLOOR || state.tiles[y][x+1] === TILE_DOOR)
          && elevacaoTerreno(state, x, y) < elevacaoTerreno(state, x+1, y)) addRamp([x, y], [x+1, y], true);
      if(y + 1 < H && (state.tiles[y+1][x] === TILE_FLOOR || state.tiles[y+1][x] === TILE_DOOR)
          && elevacaoTerreno(state, x, y) < elevacaoTerreno(state, x, y+1)) addRamp([x, y], [x, y+1], false);
    }
  }

  // Pequenas bolhas emissivas sobem e encolhem sobre a lava. São poucas por
  // casa para manter o efeito sutil e barato mesmo em rios grandes de lava.
  for(let y=0; y<H; y++) for(let x=0; x<W; x++){
    if((state.materiais && state.materiais[`${x},${y}`]) !== 'lava') continue;
    const floorTop = topoTerreno3D(state, x, y, TH);
    const br = _rng(((x * 92821) ^ (y * 68917) ^ 0xBABB1E) >>> 0);
    for(let i=0; i<2; i++){
      const b = new T.Mesh(lavaBubbleGeo, lavaBubbleMat);
      b.position.set(x + (br()-.5)*.62, floorTop + .018, y + (br()-.5)*.62);
      b.scale.setScalar(.55 + br()*.65);
      b.userData.lavaBubble = true;
      b.userData.lavaKey = `${x},${y}`;
      b.userData.lavaPhase = br() * Math.PI * 2;
      b.userData.lavaBaseY = floorTop + .018;
      b.userData.lavaBaseScale = b.scale.x;
      scene.add(b); lavaBubbleMeshes.push(b);
    }
  }

  // Ondulações leves na superfície: uma por casa, com fase e deslocamento
  // determinísticos para evitar que toda a água pulse de forma idêntica.
  for(let y=0; y<H; y++) for(let x=0; x<W; x++){
    const kind = state.materiais && state.materiais[`${x},${y}`];
    if(kind !== 'agua' && kind !== 'agua_profunda') continue;
    const floorTop = topoTerreno3D(state, x, y, TH);
    const br = _rng(((x * 7547) ^ (y * 4217) ^ 0xA71E) >>> 0);
    const ripple = new T.Mesh(waterRippleGeo, kind === 'agua_profunda' ? deepWaterRippleMat : waterRippleMat);
    const baseScale = kind === 'agua_profunda' ? 1.15 + br() * 0.42 : 0.72 + br() * 0.30;
    ripple.position.set(x + (br() - 0.5) * 0.18, floorTop + 0.014, y + (br() - 0.5) * 0.18);
    ripple.rotation.x = -Math.PI / 2;
    ripple.rotation.z = br() * Math.PI;
    ripple.scale.setScalar(baseScale);
    ripple.userData.waterRipple = true;
    ripple.userData.waterKey = `${x},${y}`;
    ripple.userData.waterKind = kind;
    ripple.userData.waterPhase = br() * Math.PI * 2;
    ripple.userData.waterBaseX = ripple.position.x;
    ripple.userData.waterBaseZ = ripple.position.z;
    ripple.userData.waterBaseScale = baseScale;
    scene.add(ripple);
    (kind === 'agua_profunda' ? deepWaterRippleMeshes : waterRippleMeshes).push(ripple);
  }

  // Uma área contínua pintada no editor vira um único vórtice grande. Isso
  // evita a aparência de vários redemoinhos independentes quando o jogador
  // arrasta o pincel por vários quadrados.
  const whirlpoolAreas3D = _collectWhirlpoolAreas(state, null);
  for(const area of whirlpoolAreas3D){
    const x = area.x0, y = area.y0, kind = area.mid;
    const areaW = area.x1 - area.x0 + 1, areaH = area.y1 - area.y0 + 1;
    const centerX = (area.x0 + area.x1) * .5;
    const centerZ = (area.y0 + area.y1) * .5;
    const br = _rng(((x * 11717) ^ (y * 7321) ^ 0xB00A) >>> 0);
    for(let i=0; i<4; i++){
      const vortex = new T.Mesh(whirlpoolRibbonGeo, whirlpoolRippleMat.clone());
      if(kind === 'rodamoinho_profundo'){
        vortex.material.color.setHex(0x82c6ff);
        vortex.material.opacity = 0.30;
      }
      // O raio externo cobre a maior parte da área, com uma margem pequena
      // para manter a animação dentro do retângulo pintado.
      const baseScale = (0.60 + i * 0.13) * (0.94 + br() * 0.06);
      // A espiral foi modelada dentro de um raio local de 0,44. A margem
      // restante garante que nem o pulso nem a turbulência atravessem a área.
      const areaScaleX = areaW * 1.02;
      const areaScaleZ = areaH * 1.02;
      const areaElev = area.tiles.reduce((sum, tile) => sum + elevacaoTerreno(state, tile.x, tile.y), 0)
        / Math.max(1, area.tiles.length);
      vortex.position.set(centerX, TH + areaElev * TERRENO_ELEVACAO_STEP_3D + 0.023 + i * 0.001, centerZ);
      vortex.rotation.x = -Math.PI / 2;
      vortex.rotation.z = br() * Math.PI * 2;
      vortex.scale.set(areaScaleX * baseScale, areaScaleZ * baseScale, 1);
      vortex.userData.whirlpool = true;
      vortex.userData.whirlpoolDeep = kind === 'rodamoinho_profundo';
      vortex.userData.whirlpoolKey = area.tiles[0].key;
      vortex.userData.whirlpoolKeys = area.tiles.map(tile => tile.key);
      vortex.userData.whirlpoolPhase = br() * Math.PI * 2;
      vortex.userData.whirlpoolBaseScaleX = areaScaleX * baseScale;
      vortex.userData.whirlpoolBaseScaleZ = areaScaleZ * baseScale;
      vortex.userData.whirlpoolLayer = i;
      vortex.userData.whirlpoolBaseX = centerX;
      vortex.userData.whirlpoolBaseZ = centerZ;
      vortex.userData.whirlpoolBaseY = TH + areaElev * TERRENO_ELEVACAO_STEP_3D + 0.023 + i * 0.001;
      vortex.userData.whirlpoolBaseOpacity = kind === 'rodamoinho_profundo'
        ? 0.30 + i * 0.055 : 0.34 + i * 0.065;
      scene.add(vortex);
      whirlpoolMeshes.push(vortex);
    }
  }

  // ── DOOR LEAVES — wooden slab over each DOOR tile (hidden when open) ──────────
  const doorMeshes = {};
  {
    const isWall3D = (tx,ty)=> ty<0||tx<0||ty>=H||tx>=W || state.tiles[ty][tx]===TILE_WALL;
    const doorGeo  = new T.BoxGeometry(TW, WH*0.80, 0.12);
    const ironGeo  = new T.BoxGeometry(TW, 0.07, 0.14);
    const doorTex = generateTexture('wood');
    if(doorTex){
      doorTex.wrapS=doorTex.wrapT=T.RepeatWrapping; doorTex.repeat.set(1,2);
      if(T.SRGBColorSpace) doorTex.colorSpace=T.SRGBColorSpace; else if(T.sRGBEncoding) doorTex.encoding=T.sRGBEncoding;
    }
    for(let y=0; y<H; y++){
      for(let x=0; x<W; x++){
        if(state.tiles[y][x] !== TILE_DOOR) continue;
        const dMat = new T.MeshStandardMaterial({ map:doorTex, bumpMap:doorTex, bumpScale:0.06, color:0x8a5b32, roughness:0.78, metalness:0.06,
                                                  emissive:0x110a04, emissiveIntensity:1.0 });
        const grp = new T.Group();
        const leaf = new T.Mesh(doorGeo, dMat);
        leaf.castShadow = true; leaf.receiveShadow = true;
        grp.add(leaf);
        const iMat = new T.MeshStandardMaterial({ color:0x2a2a30, roughness:0.6, metalness:0.5 });
        for(const oy of [WH*0.22, -WH*0.22]){
          const band = new T.Mesh(ironGeo, iMat); band.position.y = oy; grp.add(band);
        }
        // Maçaneta de latão: pequeno detalhe que deixa a porta parecer uma peça
        // moldada e pintada, não uma textura plana no cenário.
        const knob = new T.Mesh(new T.SphereGeometry(0.055, 10, 8),
          new T.MeshStandardMaterial({color:0xb78938, roughness:0.35, metalness:0.72}));
        knob.position.set(TW*0.25, 0, 0.105); knob.castShadow=true; grp.add(knob);
        // Corredor sobe/desce (paredes L+R) ⇒ folha atravessa em X (rotação 0).
        // Senão (paredes em cima/baixo) ⇒ folha ao longo de Z (gira 90°).
        const vertical = isWall3D(x-1,y) && isWall3D(x+1,y);
        const extraTurns = GS.doorOrientation(state, x, y);
        grp.rotation.y = (vertical ? 0 : Math.PI/2) + (extraTurns == null ? 0 : extraTurns * Math.PI/2);
        grp.position.set(x, TH + elevacaoTerreno(state, x, y) * TERRENO_ELEVACAO_STEP_3D + WH*0.40, y);
        grp.visible = false;
        scene.add(grp);
        doorMeshes[`${x},${y}`] = grp;
      }
    }
  }

  // ── WALL ARCHITECTURE DETAILS (door arches, corner columns, baseboards) ───────
  let wallDetailMeshes = {};
  try{ wallDetailMeshes = buildWallDetails(T, scene, state, wallTex, TW, TH, WH); }catch(e){ console.warn('buildWallDetails:', e); }

  // Built once; visibility driven by exploredSet in renderMap3D.
  let stairGroup = null;
  if(state.stairs_pos){
    const [sx, sy] = state.stairs_pos;
    stairGroup = new T.Group();
    const sMat  = new T.MeshStandardMaterial({color:0x4a3620, roughness:0.86, metalness:0.10});
    const sEdge = new T.MeshStandardMaterial({color:0x6a5030, roughness:0.72, metalness:0.15});
    const sGold = new T.MeshStandardMaterial({
      color:new T.Color(0xffd060), emissive:new T.Color(0xffd060),
      emissiveIntensity:0.55, roughness:0.25, metalness:0.90
    });
    const NSTEPS=4, SW=0.80, SD=0.14, SH=0.055;
    for(let i=0;i<NSTEPS;i++){
      const sm=new T.Mesh(new T.BoxGeometry(SW,SH,SD),i===NSTEPS-1?sEdge:sMat);
      sm.position.set(sx, TH+(i+0.5)*SH, sy+(i-NSTEPS/2+0.5)*SD);
      sm.castShadow=sm.receiveShadow=true; stairGroup.add(sm);
    }
    // Gold inlay lines on each step edge
    for(let i=0;i<NSTEPS;i++){
      const gl=new T.Mesh(new T.BoxGeometry(SW+0.02,0.012,0.012),sGold);
      gl.position.set(sx, TH+(i+1)*SH-0.004, sy+(i-NSTEPS/2+1)*SD-SD/2);
      gl.userData.isStairGlow=true; stairGroup.add(gl);
    }
    // Glow ring at floor level
    const ring=new T.Mesh(new T.TorusGeometry(0.40,0.022,6,28),sGold);
    ring.rotation.x=Math.PI/2; ring.position.set(sx,TH+0.005,sy);
    ring.userData.isStairGlow=true; stairGroup.add(ring);
    // Warm point light above stairs
    const stairLight=new T.PointLight(0xffd080,1.2,3.5);
    stairLight.position.set(sx,TH+0.9,sy); stairGroup.add(stairLight);
    stairGroup.visible=false;
    scene.add(stairGroup);
  }

  // Marcadores 3D das posições iniciais por herói (mapas sem escada).
  const heroSpawnGroups = [];
  if(state.start_mode === 'hero_spawns'){
    const colors = { warrior:0x9b78ff, mage:0x66b8ff, rogue:0xd084ff,
      cleric:0x70e0a0, bard:0xff66cc, paladin:0xffd060 };
    for(const hs of (state.hero_spawns||[])){
      const pos = hs.pos || [], gx=pos[0], gy=pos[1];
      if(!Number.isInteger(gx)||!Number.isInteger(gy)) continue;
      const group = new T.Group();
      const mat = new T.MeshStandardMaterial({color:colors[hs.class_id]||0x9b78ff,
        emissive:colors[hs.class_id]||0x9b78ff, emissiveIntensity:0.45,
        transparent:true, opacity:0.9, roughness:0.35, metalness:0.2});
      const ring = new T.Mesh(new T.TorusGeometry(0.32,0.035,8,24), mat);
      ring.rotation.x=Math.PI/2; ring.position.set(gx,TH+0.018,gy); group.add(ring);
      group.visible=false; group.userData.heroSpawnClass=hs.class_id;
      scene.add(group); heroSpawnGroups.push({group, pos:[gx,gy]});
    }
  }

  // ── Exit marker (Fase 3 — masmorra autorada): mastro + bandeira 🏁 ────────────
  // Estático; visibilidade por fog (exploredSet) em renderMap3D, como stairGroup.
  let exitGroup = null;
  {
    const ex = (window.GS && GS.exitPos) || null;
    if(ex){
      const [exx, exy] = ex;
      exitGroup = new T.Group();
      const poleMat = new T.MeshStandardMaterial({color:0x8a8a96, roughness:0.5, metalness:0.6});
      const pole = new T.Mesh(new T.CylinderGeometry(0.025,0.025,0.95,8), poleMat);
      pole.position.set(exx, TH+0.475, exy); pole.castShadow=true; exitGroup.add(pole);
      const flagMat = new T.MeshStandardMaterial({
        color:new T.Color(0x3cdcb4), emissive:new T.Color(0x1c8a70),
        emissiveIntensity:0.55, roughness:0.45, metalness:0.10, side:T.DoubleSide
      });
      const flag = new T.Mesh(new T.PlaneGeometry(0.34,0.20), flagMat);
      flag.position.set(exx+0.18, TH+0.82, exy); exitGroup.add(flag);
      const ring = new T.Mesh(new T.TorusGeometry(0.40,0.020,6,28), flagMat);
      ring.rotation.x=Math.PI/2; ring.position.set(exx,TH+0.006,exy); exitGroup.add(ring);
      const exLight = new T.PointLight(0x60e0c0,0.9,3.0);
      exLight.position.set(exx,TH+0.9,exy); exitGroup.add(exLight);
      exitGroup.visible=false;
      scene.add(exitGroup);
    }
  }

  const entityGroup = new T.Group();
  scene.add(entityGroup);

  const raycaster = new T.Raycaster();

  const resizeObs = new ResizeObserver(() => { if(g3) resize3D(); });
  resizeObs.observe(wrap);

  const controls = new T.OrbitControls(camera, renderer.domElement);
  controls.enableDamping     = true;      // smooth deceleration on release
  controls.dampingFactor     = 0.08;
  controls.screenSpacePanning = true;    // right-drag pans parallel to screen
  controls.mouseButtons = {
    LEFT:   T.MOUSE.ROTATE,
    MIDDLE: T.MOUSE.DOLLY,
    RIGHT:  T.MOUSE.PAN,
  };
  // Zoom limits (OrthographicCamera: camera.zoom is modified by controls)
  controls.minZoom = 0.28;
  controls.maxZoom = 8.0;
  // Polar angle clamp — prevents camera from dipping below the board
  controls.minPolarAngle = 8  * Math.PI / 180;   //  8° above horizon  (wide low shot)
  controls.maxPolarAngle = 82 * Math.PI / 180;   // 82° = nearly straight down

  // ── FLOATING DUST PARTICLES (200 motes drifting upward — spore/smoke ambience)
  // Each mote has a fixed XZ position and a slowly increasing Y (resets at ceiling).
  // BufferGeometry + PointsMaterial — zero draw calls, ~6 KB of data.
  const DUST_N    = 200;
  const DUST_CEIL = WH + 0.6;   // reset threshold slightly above wall tops
  const _dXZ  = new Float32Array(DUST_N * 2);   // current XZ position
  const _dY   = new Float32Array(DUST_N);        // current Y height
  const _dVel = new Float32Array(DUST_N);        // upward drift speed
  const _dPosArr = new Float32Array(DUST_N * 3); // packed XYZ for BufferAttribute

  for(let i = 0; i < DUST_N; i++){
    _dXZ[i*2]   = Math.random() * (W - 1);
    _dXZ[i*2+1] = Math.random() * (H - 1);
    _dY[i]      = Math.random() * DUST_CEIL;
    _dVel[i]    = 0.00022 + Math.random() * 0.00060;  // 0.22–0.82 mm per ms upward
    _dPosArr[i*3]   = _dXZ[i*2];
    _dPosArr[i*3+1] = _dY[i];
    _dPosArr[i*3+2] = _dXZ[i*2+1];
  }
  const dustBuf = new T.BufferGeometry();
  dustBuf.setAttribute('position', new T.BufferAttribute(_dPosArr, 3));
  const dustPts = new T.Points(dustBuf,
    new T.PointsMaterial({
      color: 0xfff0cc, size: 0.024,
      transparent: true, opacity: 0.15,
      depthWrite: false, sizeAttenuation: true
    })
  );
  dustPts.visible = false;   // shown once the player reveals tiles
  scene.add(dustPts);

  // ── Hover showcase spotlight — dim gold point-light, driven each tick ───────
  // Intensity starts at 0 (off); the animation loop lerps it up when a figure
  // is hovered.  No shadow cast — cheap fill only.
  const hoverSpot = new T.PointLight(0xffd080, 0, 1.5);
  hoverSpot.castShadow = false;
  hoverSpot.userData.isHoverLight = true;
  scene.add(hoverSpot);

  // ── Halo do turno ativo — luz PERMANENTE (mesmo padrão do hoverSpot acima) ────
  // Antes ela nascia dentro do peão da vez (build3DFig) e morria quando o turno
  // passava aos monstros, fazendo a CONTAGEM de luzes visíveis oscilar 1↔0 a cada
  // troca de turno — exatamente o que o pool de luzes e a dirPawn existem para
  // evitar. Medido: a primeira oscilação congela ~3,4 s (recompila todos os
  // materiais da cena) e as seguintes custam ~38 ms. Aqui ela é criada uma vez e
  // só é movida/acesa; "apagada" = intensity 0, nunca visible = false.
  const haloLight = new T.PointLight(0xf0a820, 0, 1.6);
  haloLight.castShadow = false;
  scene.add(haloLight);

  // Ícones de habilidades/magias ativas, sempre acima dos peões dos heróis.
  // Ficam em um grupo separado para serem reconciliados sem reconstruir os
  // modelos 3D nem interferir nas animações de movimento.
  const activeEffectGroup = new T.Group();
  activeEffectGroup.renderOrder = 80;
  scene.add(activeEffectGroup);

  // Rota de movimento selecionada, mas ainda não confirmada pelo jogador.
  // O grupo fica acima do piso e fora do raycast para não alterar a interação.
  const movePreviewGroup = new T.Group();
  movePreviewGroup.renderOrder = 90;
  scene.add(movePreviewGroup);

  // Efeito persistente do Protetor: separado dos ícones e dos peões para não
  // forçar reconstruções da cena quando a proteção apenas pulsa.
  const protetorEffectGroup = new T.Group();
  protetorEffectGroup.renderOrder = 86;
  scene.add(protetorEffectGroup);

  g3 = {
    T, scene, renderer, camera, controls,
    ambient, torch, visionLamp, rimLight, fillLight, sconces, lightPool,
    showcase, haloLight,
    tileMeshes, doorMeshes, wallDetailMeshes, entityGroup, raycaster,
    wallTorches, torchStaticMeshes, roomOverlayMeshes,
    sceneryMeshes, groutMeshes, groutMats, waterMats, deepWaterMats, lavaMats, swampMats,
    lavaBubbleMeshes, waterRippleMeshes, deepWaterRippleMeshes, whirlpoolMeshes,
    terrainTransitionMeshes, bridgeMeshes,
    whirlpoolMats,
    wetFloorInst, wetFloorKeys, wetFloorTH: TH,
    moveHighlightMeshes, atkHighlightMeshes, moveHighlightMat, gamepadCursorMesh,
    softShadowMat,
    weaponRangeMeshes,
    masterAttackRangeMeshes, masterAttackZoneMeshes, masterFootprintMeshes,
    masterHistoryAttackerMeshes, masterHistoryTargetMeshes,
    spellRangeMeshes, spellZonaMeshes, spellDoubleMeshes, spellAreaMeshes, spellTargetMeshes, spellEscuridaoMeshes, spellSilencioMeshes, spellFireFx, spellLivingFlameFx,
    dustPts, dustVel: _dVel, dustXZ: _dXZ, dustY: _dY,
    dustCount: DUST_N, dustCeil: DUST_CEIL,
    W, H, boardVisualSig, animFrame:null, resizeObs,
    hoverSpot,
    activeEffectGroup, movePreviewGroup, protetorEffectGroup,
    activeEffectSprites: {},
    stairGroup,                          // staircase mesh (null if no stairs)
    heroSpawnGroups,                     // markers for separated hero starts
    exitGroup,                           // Fase 3: marcador de saída 🏁 (null se não houver)
    chestMeshes: {},                     // chest_id → THREE.Group
    groundItemMeshes: {},                // ground_item id → THREE.Group (item largado no chão)
    groundItemSeenIds: new Set((state.ground_items || []).map(item => String(item.id))),
    decorMeshes: {},                     // decor id → THREE.Mesh
    hoveredPos:  null,   // [gx, gy] of figure under cursor, or null
    selectedPos: null    // [gx, gy] of clicked-selected figure, or null
  };

  // ── Initial camera position + first OrbitControls sync ───────────────────
  resetCamera3D();
  // Ao entrar na masmorra, o jogador deve começar vendo o próprio herói.
  // `resetCamera3D()` fornece o ângulo/zoom padrão; o reenquadramento abaixo
  // apenas desloca o alvo para o peão local, sem esperar o primeiro movimento.
  const peaoInicial = (state.players || []).find(p =>
    p && String(p.id) === String(GS.myPid) && p.alive && Array.isArray(p.pos));
  if(peaoInicial) centralizarCamera3DNoPeao(peaoInicial.pos);
  resize3D();
  // Quando init3D roda logo após showScreen('screen-game'), o map-wrap pode
  // ainda não ter layout (offsetWidth=0) → o resize acima usa o fallback
  // 640×480. Re-mede após o navegador pintar para corrigir o aspect/escala
  // (a tela preta intermitente costumava vir daqui). O ResizeObserver cobre
  // mudanças posteriores; estes rAFs cobrem o primeiro frame.
  requestAnimationFrame(() => { if(g3) resize3D(); });
  requestAnimationFrame(() => requestAnimationFrame(() => { if(g3) resize3D(); }));
  // Pré-compila os shaders com a contagem FINAL de luzes já na entrada da
  // masmorra (momento de carregamento) — como o pool mantém a contagem
  // constante, nenhum outro programa precisa compilar durante a partida.
  // A qualidade vem ANTES do compile: ela pode tirar luzes da cena, e o compile
  // precisa ver a contagem FINAL — senao os programas seriam refeitos no
  // primeiro quadro, dentro da partida, que e exatamente o que se quer evitar.
  _aplicarQualidade3D();
  try{ renderer.compile(scene, camera); }catch(e){ console.warn('renderer.compile:', e); }
  startLoop3D();

  // ── Drag-guard listeners (detect any button drag → block next click) ──────
  // OrbitControls handles the actual camera movement; we only need to know
  // "did the pointer travel while a button was held?" to suppress tile clicks.
  const domEl = renderer.domElement;
  // Com o botão direito pressionado, o scroll vira um passo vertical. Fora
  // desse gesto, o OrbitControls continua controlando o zoom normalmente.
  domEl.addEventListener('wheel', _handleAltitudeWheel, { passive:false, capture:true });
  domEl.addEventListener('mousedown',  e  => {
    _orbitDragMoved = false;
    if(e.button === 2) _mouseRightHeld = true;
  });
  domEl.addEventListener('mouseup',    e  => {
    if(e.button === 2) _mouseRightHeld = false;
  });
  domEl.addEventListener('contextmenu', e  => {
    if(e.button === 2 || _mouseRightHeld) e.preventDefault();
  });
  domEl.addEventListener('mousemove',  e  => { if(e.buttons) _orbitDragMoved = true; });

  domEl.addEventListener('click',      on3DClick);
  domEl.addEventListener('mousemove',  on3DMouseMove);
  domEl.addEventListener('mouseleave', () => {
    $('tooltip').style.display = 'none';
    if(g3) g3.hoveredPos = null;   // kill hover lift when cursor leaves canvas
    _setMasterMonsterHover(null);
  });

  // ── Toque no 3D: OrbitControls cuida de girar/pan/zoom; aqui detectamos um
  // TOQUE CURTO (sem arrastar) e o tratamos como clique para mover/atacar. ──
  let _t3x, _t3y, _t3moved;
  domEl.addEventListener('touchstart', e => {
    if(e.touches.length === 1){ _t3x = e.touches[0].clientX; _t3y = e.touches[0].clientY; _t3moved = 0; }
    else { _t3moved = 999; }   // 2 dedos = gesto de câmera, nunca clique
  }, { passive:true });
  domEl.addEventListener('touchmove', e => {
    if(e.touches.length === 1)
      _t3moved += Math.abs(e.touches[0].clientX - _t3x) + Math.abs(e.touches[0].clientY - _t3y);
  }, { passive:true });
  domEl.addEventListener('touchend', (e) => {
    if(_t3moved < 14){
      e.preventDefault();   // evita o "click" sintético duplicar o movimento
      _orbitDragMoved = false;
      on3DClick({ clientX: _t3x, clientY: _t3y });
    }
  }, { passive:false });
}

// generateTexture(type) → CanvasTexture.  Types: 'wall', 'floor', 'wood'.
// All textures use Math.random() — every session gets unique stone / grain.

function generateTexture(type){
  const T = window.THREE;
  if(!T) return null;
  switch(type){
    case 'wall':  return _mkWallTex(T, 512);
    case 'floor': return _mkFloorTex(T, 512);
    case 'wood':  return _mkWoodTex(T);
    default:      return null;
  }
}

// ── Wall: 512×512 irregular brickwork with mortar, per-block tone variation ──
function _mkWallTex(T, size){
  const cv = document.createElement('canvas');
  cv.width = cv.height = size;
  const c = cv.getContext('2d');

  // Mortar background — slightly blue-dark gap between stone blocks
  c.fillStyle = VC.wall.mortarHex;
  c.fillRect(0, 0, size, size);

  // Brickwork courses: random block height 40–60 px, alternating row offset
  let ry = 0, rowI = 0;
  while(ry < size + 2){
    const rh  = 40 + Math.floor(Math.random() * 21);   // 40–60 px tall
    const off = (rowI % 2 === 0) ? 0 : 55;             // brickwork offset
    let rx = -off;
    while(rx < size + 2){
      const bw = 80 + Math.floor(Math.random() * 41);  // 80–120 px wide
      // Independent ±15 variation per RGB channel
      const r = Math.min(255, Math.max(0, 90 + Math.round((Math.random()-0.5)*30)));
      const g = Math.min(255, Math.max(0, 90 + Math.round((Math.random()-0.5)*30)));
      const b = Math.min(255, Math.max(0, 90 + Math.round((Math.random()-0.5)*30)));
      c.fillStyle = `rgb(${r},${g},${b})`;
      // Inset 1.5 px so the 3px mortar gap is the background showing through
      c.fillRect(rx + 1.5, ry + 1.5, bw - 3, rh - 3);
      rx += bw;
    }
    ry += rh;
    rowI++;
  }

  // Subtle noise dots — simulates rough stone texture
  c.fillStyle = 'rgba(0,0,0,0.03)';
  for(let n = 0; n < 45000; n++){
    c.fillRect(Math.random()*size|0, Math.random()*size|0, 1, 1);
  }

  // Edge vignette — darkens corners so tiling looks atmospheric
  const grad = c.createRadialGradient(size/2,size/2, size*0.28, size/2,size/2, size*0.72);
  grad.addColorStop(0, 'rgba(0,0,0,0)');
  grad.addColorStop(1, 'rgba(0,0,0,0.30)');
  c.fillStyle = grad;
  c.fillRect(0, 0, size, size);

  const tex = new T.CanvasTexture(cv);
  tex.wrapS = tex.wrapT = T.RepeatWrapping;
  return tex;
}

// ── Floor: 512×512 paved stone tiles 64×64 with cracks and bevels ─────────────
function _mkFloorTex(T, size){
  const cv = document.createElement('canvas');
  cv.width = cv.height = size;
  const c = cv.getContext('2d');
  const TILE = 64, N = size / TILE | 0;  // 8 tiles per axis at 512

  // Grout fill — visible mid-dark seam between tiles
  c.fillStyle = VC.floor.groutHex;
  c.fillRect(0, 0, size, size);

  for(let ty = 0; ty < N; ty++){
    for(let tx = 0; tx < N; tx++){
      const px = tx * TILE, py = ty * TILE;

      // Per-tile tone variation ±10
      const v = Math.min(255, Math.max(0, 96 + Math.round((Math.random()-0.5)*20)));
      c.fillStyle = `rgb(${v},${v},${v})`;
      c.fillRect(px+2, py+2, TILE-4, TILE-4);

      // Top-left warm bevel — torch light catches raised tile edge
      c.fillStyle = 'rgba(255,200,120,0.11)';
      c.fillRect(px+2, py+2, TILE-4, 3);
      c.fillRect(px+2, py+2, 3, TILE-4);

      // Bottom-right shadow bevel
      c.fillStyle = 'rgba(0,0,0,0.22)';
      c.fillRect(px+2, py+TILE-5, TILE-4, 3);
      c.fillRect(px+TILE-5, py+2, 3, TILE-4);

      // 15% chance of a diagonal crack
      if(Math.random() < 0.15){
        const cx0 = px + 8 + Math.random()*(TILE-16);
        const cy0 = py + 8 + Math.random()*(TILE-16);
        const a   = Math.PI*0.22 + Math.random()*0.30;
        const len = 12 + Math.random()*18;
        const cx1 = cx0 + Math.cos(a)*len, cy1 = cy0 + Math.sin(a)*len;
        c.strokeStyle = 'rgba(0,0,0,0.42)'; c.lineWidth = 1.2;
        c.beginPath(); c.moveTo(cx0, cy0); c.lineTo(cx1, cy1); c.stroke();
        // Subtle highlight alongside crack edge
        c.strokeStyle = 'rgba(255,255,255,0.10)'; c.lineWidth = 0.8;
        c.beginPath(); c.moveTo(cx0+0.6, cy0+0.6); c.lineTo(cx1+0.6, cy1+0.6); c.stroke();
      }
    }
  }

  // ImageData micro-noise (step 8 px for performance on 512×512)
  const id = c.getImageData(0, 0, size, size);
  const d  = id.data;
  for(let i = 0; i < d.length; i += 32){
    const n = (Math.random()-0.5) * 14;
    d[i]   = Math.min(255, Math.max(0, d[i]   + n));
    d[i+1] = Math.min(255, Math.max(0, d[i+1] + n));
    d[i+2] = Math.min(255, Math.max(0, d[i+2] + n));
  }
  c.putImageData(id, 0, 0);

  const tex = new T.CanvasTexture(cv);
  tex.wrapS = tex.wrapT = T.RepeatWrapping;
  return tex;
}

// ── Wood: 256×512 vertical grain with plank seams and nails (for doors) ───────
function _mkWoodTex(T){
  const W = 256, H = 512;
  const cv = document.createElement('canvas');
  cv.width = W; cv.height = H;
  const c = cv.getContext('2d');

  // Medium brown base
  c.fillStyle = '#6b3f1f';
  c.fillRect(0, 0, W, H);

  // Vertical grain bands (8–12 px wide, ±20 tone per channel)
  let gx = 0;
  while(gx < W){
    const gw = 8 + Math.floor(Math.random() * 5);
    const v  = Math.round((Math.random()-0.5) * 40);
    const r  = Math.min(255, Math.max(0, 107 + v));
    const g  = Math.min(255, Math.max(0,  63 + Math.round(v * 0.65)));
    const b  = Math.min(255, Math.max(0,  31 + Math.round(v * 0.40)));
    c.fillStyle = `rgb(${r},${g},${b})`;
    c.fillRect(gx, 0, gw, H);
    gx += gw;
  }

  // Thin wavy dark streaks — fine wood grain lines
  c.strokeStyle = 'rgba(0,0,0,0.18)'; c.lineWidth = 0.9;
  for(let s = 0; s < 22; s++){
    const sx   = Math.random() * W;
    const amp  = 1.5 + Math.random() * 3;
    const freq = 0.008 + Math.random() * 0.012;
    c.beginPath(); c.moveTo(sx, 0);
    for(let y = 2; y < H; y += 4){
      c.lineTo(sx + Math.sin(y * freq + Math.random()*0.18) * amp, y);
    }
    c.stroke();
  }

  // Horizontal plank seams (every 120–160 px)
  let sy = 110 + Math.random() * 50;
  while(sy < H){
    c.strokeStyle = 'rgba(0,0,0,0.56)'; c.lineWidth = 1.8;
    c.beginPath(); c.moveTo(0, sy); c.lineTo(W, sy); c.stroke();
    c.strokeStyle = 'rgba(255,200,100,0.13)'; c.lineWidth = 1.0;
    c.beginPath(); c.moveTo(0, sy+1.5); c.lineTo(W, sy+1.5); c.stroke();
    sy += 120 + Math.random() * 40;
  }

  // Nails — dark circle with bright highlight
  for(const ny of [56, H/2-56, H/2+56, H-56]){
    for(const nx of [14, W-14]){
      c.fillStyle = 'rgba(28,16,6,0.82)';
      c.beginPath(); c.arc(nx, ny, 3.5, 0, Math.PI*2); c.fill();
      c.fillStyle = 'rgba(255,210,110,0.32)';
      c.beginPath(); c.arc(nx-1, ny-1, 1.6, 0, Math.PI*2); c.fill();
    }
  }

  // Per-pixel micro noise (step 8 px)
  const id = c.getImageData(0, 0, W, H);
  const d  = id.data;
  for(let i = 0; i < d.length; i += 32){
    const n = (Math.random()-0.5) * 18;
    d[i]   = Math.min(255, Math.max(0, d[i]   + n));
    d[i+1] = Math.min(255, Math.max(0, d[i+1] + Math.round(n * 0.65)));
    d[i+2] = Math.min(255, Math.max(0, d[i+2] + Math.round(n * 0.40)));
  }
  c.putImageData(id, 0, 0);

  const tex = new T.CanvasTexture(cv);
  tex.wrapS = tex.wrapT = T.RepeatWrapping;
  return tex;
}

function dispose3D(){
  if(!g3) return;
  cancelAnimationFrame(g3.animFrame);
  // Sem o laço 3D ninguém mais tica as cenas: um herói morto ficaria
  // "tombando" para sempre (isDying) e seria desenhado vivo no 2D. Lacuna
  // aceita: um número ainda não emitido de um ataque em curso se perde na troca.
  if(window.CombatScene) CombatScene.reset();
  _projetilLimparTodos();
  // As nuvens de fumaça continuam (a zona segue ativa); só os objetos da cena
  // morrem com ela e são refeitos no próximo init3D/2D.
  for(const n of _fumacaNuvens.values()) _fumacaDispose3D(n);
  g3.resizeObs.disconnect();
  if(g3.controls) g3.controls.dispose();

  // ── Reset do sistema de dados 3D ──────────────────────────────────────────
  // _d3._diceGroup pertence à cena que está sendo destruída. Sem este reset,
  // na próxima masmorra os dados eram adicionados a um grupo ÓRFÃO (fora da
  // cena nova) e nunca mais apareciam — só o rótulo flutuante era desenhado.
  if(_d3 && _d3.animFrame) cancelAnimationFrame(_d3.animFrame);
  for(const die of _dice3){
    _disposeDieMaterials(die.mats);
    _disposeTopBadge(die.topBadge);
    die.geo.dispose();
  }
  _dice3.length = 0;
  _d3 = null;

  g3.renderer.dispose();
  const el = g3.renderer.domElement;
  if(el.parentNode) el.parentNode.removeChild(el);
  if(g3.activeEffectGroup){
    Object.values(g3.activeEffectSprites || {}).forEach(sprite => {
      if(sprite.material) sprite.material.dispose();
    });
    g3.activeEffectGroup.clear?.();
  }
  if(g3.protetorEffectGroup){
    for(const fx of _protetorVisuals.values())
      if(fx.group && fx.group.parent === g3.protetorEffectGroup) _disposeProtetor3D(fx);
    g3.protetorEffectGroup.clear?.();
  }
  _clearMovePreviewVisual();
  for(const f of _combatFeedbacks) _disposeCombatFeedback3D(f);
  // Restore map-wrap positioning so the 2D canvas flows normally
  const wrap = $('map-wrap');
  if(wrap) wrap.style.position = '';
  g3 = null;
  _wakeVisualAnimScheduler();
}

// ── Reset camera to default Diablo-like isometric view ───────────────────────
// Called by the ⌂ button, the R key, and on init3D first frame.
// Moves the camera to SW-above position and snaps OrbitControls target to
// board centre; zoom is reset to 1 so frustum returns to its base size.

function resetCamera3D(){
  if(!g3) return;
  const { W, H, camera, controls } = g3;
  const cx = (W-1)/2, cz = (H-1)/2;
  const d  = Math.max(W, H) * 1.15;
  const az = 225 * Math.PI / 180;   // SW  — classic Diablo look
  const el = 52  * Math.PI / 180;   // ~isometric elevation

  camera.up.set(0, 1, 0);
  camera.position.set(
    cx + d * Math.cos(el) * Math.cos(az),
    d  * Math.sin(el),
    cz + d * Math.cos(el) * Math.sin(az)
  );
  camera.zoom = 1.0;
  camera.updateProjectionMatrix();

  controls.target.set(cx, 0.4, cz);
  controls.update();
}

function resize3D(){
  if(!g3) return;
  const wrap = $('map-wrap');
  // offsetWidth/Height includes the padding so the canvas fills the full container.
  const CW = wrap.offsetWidth, CH = wrap.offsetHeight;
  if(!CW || !CH) return;
  const { W, H, camera, renderer } = g3;
  const aspect = CW / CH;
  // Base frustum half-height — zoom handled by OrbitControls via camera.zoom.
  const fH = Math.max(W, H) * 0.60;
  camera.left   = -fH * aspect;  camera.right  = fH * aspect;
  camera.top    =  fH;           camera.bottom = -fH;
  camera.updateProjectionMatrix();
  renderer.setSize(CW, CH);
}

// ── Pool de luzes: atribui as N luzes fixas às âncoras REVELADAS (tochas de
// sala + arandelas) mais próximas do herói. As luzes nunca mudam de visible
// (contagem constante → zero recompilações de shader); "apagar" = intensity 0.
function _atribuirLightPool(){
  if(!g3 || !g3.lightPool) return;
  const px = g3.torch.position.x, pz = g3.torch.position.z;
  const cands = [];
  if(g3.wallTorches){
    for(const wt of g3.wallTorches){
      if(!wt.group.visible) continue;
      cands.push({x:wt.lx, y:wt.ly, z:wt.lz, kind:'torch', offset:wt.offset});
    }
  }
  if(g3.sconces){
    for(const sc of g3.sconces){
      if(!sc.revealed) continue;
      cands.push({x:sc.x, y:1.2, z:sc.y, kind:'sconce', offset:0});
    }
  }
  for(const c of cands){
    const dx = c.x - px, dz = c.z - pz;
    c.d2 = dx*dx + dz*dz;
  }
  cands.sort((a,b) => a.d2 - b.d2);
  for(let i=0; i<g3.lightPool.length; i++){
    const slot = g3.lightPool[i];
    const c = cands[i] || null;
    slot.anchor = c;
    if(!c){ slot.light.intensity = 0; continue; }
    slot.light.position.set(c.x, c.y, c.z);
    if(c.kind === 'torch'){
      // mesmos parâmetros da antiga PointLight por tocha de sala
      slot.light.color.setHex(0xff8800);
      slot.light.distance = 5.5;
      slot.light.decay    = 2.0;
      slot.light.intensity = 3.8;   // o tick anima o flicker por cima
    } else {
      // mesmos parâmetros da antiga PointLight por arandela
      slot.light.color.setHex(0xffaa44);
      slot.light.distance = 7.5;
      slot.light.decay    = 1.8;
      slot.light.intensity = 2.8;
    }
  }
}

// Lava, água e pântano têm animação visual própria, mas não precisam acompanhar a
// taxa máxima do renderizador. Atualizar em ~30 Hz preserva a fluidez percebida
// e evita percorrer os materiais do tabuleiro em todos os frames.
function _atualizarTerrenoAnimado3D(t){
  if(!g3) return;
  const temTerreno = (g3.lavaMats && g3.lavaMats.length)
    || (g3.waterMats && g3.waterMats.length)
    || (g3.deepWaterMats && g3.deepWaterMats.length)
    || (g3.whirlpoolMats && g3.whirlpoolMats.length)
    || (g3.swampMats && g3.swampMats.length)
    || (g3.lavaBubbleMeshes && g3.lavaBubbleMeshes.length)
    || (g3.waterRippleMeshes && g3.waterRippleMeshes.length)
    || (g3.deepWaterRippleMeshes && g3.deepWaterRippleMeshes.length);
  if(!temTerreno) return;
  if(g3._terrainAnimLastAt && t - g3._terrainAnimLastAt < 33) return;
  g3._terrainAnimLastAt = t;

  if(g3.lavaMats){
    const lp = 0.5 + 0.5 * Math.sin(t / 390) + 0.18 * Math.sin(t / 137);
    for(const mat of g3.lavaMats){
      if(mat.map){
        mat.map.offset.x = (t / 18000) % 1;
        mat.map.offset.y = (t / 26000) % 1;
        // Alterar offset não exige reenvio da textura para a GPU.
      }
      mat.emissiveIntensity = 1.00 + lp * 0.72;
    }
  }
  if(g3.waterMats){
    const wp = 0.5 + 0.5 * Math.sin(t / 520) + 0.08 * Math.sin(t / 173);
    for(const mat of g3.waterMats){
      if(mat.map){
        mat.map.offset.x = (t / 15000) % 1;
        mat.map.offset.y = (t / 23000) % 1;
      }
      mat.emissiveIntensity = 0.82 + wp * 0.20;
    }
  }
  if(g3.deepWaterMats){
    const dwp = 0.5 + 0.5 * Math.sin(t / 1050) + 0.06 * Math.sin(t / 307);
    for(const mat of g3.deepWaterMats){
      if(mat.map){
        mat.map.offset.x = (t / 27000) % 1;
        mat.map.offset.y = (t / 39000) % 1;
      }
      mat.emissiveIntensity = 0.50 + dwp * 0.12;
    }
  }
  if(g3.swampMats){
    const sp = 0.5 + 0.5 * Math.sin(t / 1100) + 0.12 * Math.sin(t / 330);
    for(const mat of g3.swampMats){
      if(mat.map){
        mat.map.offset.x = (t / 36000) % 1;
        mat.map.offset.y = (t / 47000) % 1;
      }
      mat.emissiveIntensity = 0.18 + sp * 0.10;
    }
  }
  if(g3.whirlpoolMats){
    const wvp = 0.5 + 0.5 * Math.sin(t / 205) + 0.16 * Math.sin(t / 61);
    for(const mat of g3.whirlpoolMats){
      if(mat.map){
        mat.map.offset.x = (t / 1550) % 1;
        mat.map.offset.y = (t / 2100) % 1;
      }
      // Pulso forte e irregular: a superfície parece acelerar e perder
      // estabilidade, em vez de apenas brilhar de forma uniforme.
      mat.emissiveIntensity = 0.78 + wvp * 0.46;
    }
  }
  if(g3.lavaBubbleMeshes){
    for(const bubble of g3.lavaBubbleMeshes){
      if(!bubble.visible) continue;
      const q = 0.5 + 0.5 * Math.sin(t / 560 + (bubble.userData.lavaPhase || 0));
      const base = bubble.userData.lavaBaseScale || 0.7;
      bubble.position.y = (bubble.userData.lavaBaseY || 0.238) + q * 0.028;
      bubble.scale.set(base * (0.72 + q * 0.42), base * (0.58 + q * 0.24), base * (0.72 + q * 0.42));
    }
  }
  if(g3.waterRippleMeshes){
    for(const ripple of g3.waterRippleMeshes){
      if(!ripple.visible) continue;
      const phase = ripple.userData.waterPhase || 0;
      const q = 0.5 + 0.5 * Math.sin(t / 760 + phase);
      const base = ripple.userData.waterBaseScale || 0.85;
      ripple.position.x = (ripple.userData.waterBaseX || 0) + Math.sin(t / 1450 + phase) * 0.035;
      ripple.position.z = (ripple.userData.waterBaseZ || 0) + Math.cos(t / 1710 + phase) * 0.028;
      ripple.scale.setScalar(base * (0.70 + q * 0.52));
      ripple.rotation.z += 0.002;
    }
  }
  if(g3.deepWaterRippleMeshes){
    for(const ripple of g3.deepWaterRippleMeshes){
      if(!ripple.visible) continue;
      const phase = ripple.userData.waterPhase || 0;
      const q = 0.5 + 0.5 * Math.sin(t / 1350 + phase);
      const base = ripple.userData.waterBaseScale || 1.25;
      ripple.position.x = (ripple.userData.waterBaseX || 0) + Math.sin(t / 2400 + phase) * 0.022;
      ripple.position.z = (ripple.userData.waterBaseZ || 0) + Math.cos(t / 2750 + phase) * 0.018;
      ripple.scale.setScalar(base * (0.82 + q * 0.34));
      ripple.rotation.z += 0.001;
    }
  }
  if(g3.whirlpoolMeshes){
    for(const vortex of g3.whirlpoolMeshes){
      if(!vortex.visible) continue;
      const phase = vortex.userData.whirlpoolPhase || 0;
      const layer = vortex.userData.whirlpoolLayer || 0;
      const q = 0.5 + 0.5 * Math.sin(t / 175 + phase)
        + 0.16 * Math.sin(t / 57 + phase * 1.7 + layer);
      const baseX = vortex.userData.whirlpoolBaseScaleX || 0.6;
      const baseZ = vortex.userData.whirlpoolBaseScaleZ || 0.6;
      const pulse = Math.max(0, Math.min(1, q));
      const spin = (0.038 + pulse * 0.030) * (layer % 2 ? -1 : 1);
      // Deslocamento mínimo: a espiral vibra, mas nunca sai da área pintada.
      const swirl = 0.003 + layer * 0.001;
      const pulseScale = 0.88 + pulse * 0.10;
      vortex.scale.set(baseX * pulseScale, baseZ * pulseScale, 1);
      vortex.rotation.z += spin;
      vortex.position.x = (vortex.userData.whirlpoolBaseX || 0)
        + Math.cos(t / 115 + phase) * swirl;
      vortex.position.z = (vortex.userData.whirlpoolBaseZ || 0)
        + Math.sin(t / 132 + phase * 1.3) * swirl * 0.82;
      vortex.position.y = (vortex.userData.whirlpoolBaseY || 0)
        + Math.sin(t / 92 + phase) * 0.004;
      vortex.material.opacity = (vortex.userData.whirlpoolBaseOpacity || 0.30)
        * (0.58 + q * 0.78);
    }
  }
}

// ── Aplicação da pose da cena de combate no peão ─────────────────────────────
// Por CHAVE (o Group pode ser reconstruído no meio da cena). Idempotente: a
// base é gridX/gridY + footprint; ao terminar, restaura uma vez e não escreve
// mais. A inclinação usa rotateOnWorldAxis porque rotation é Euler XYZ e o
// facing (rotation.y) misturaria os eixos.
const _sceneAxis = new (window.THREE ? window.THREE.Vector3 : Object)();
function _figSceneKey(fig){
  const u = fig.userData || {};
  return u.pid != null ? `p:${u.pid}`
    : u.monId != null ? `m:${u.monId}`
    : u.animadoId != null ? `a:${u.animadoId}`
    : u.prisoner ? 'pr:singleton' : null;
}
function _materiaisCena(fig){
  const u = fig.userData;
  if(u._sceneMats) return u._sceneMats;
  const lista = [];
  fig.traverse(o => {
    if(!(o.isMesh || o.isSprite) || !o.material) return;
    const ud = o.userData || {};
    // A arte GLB é marcada isGroundDecal (reuso como "fora do passe de outline")
    // E isGLB — só o decal de verdade (sombra blob, anel de visão, base) fica
    // de fora. O contorno (isOutline) entra, mas só recebe opacidade (abaixo).
    if((ud.isGroundDecal && !ud.isGLB) || ud.isPulseRing || ud.isSelectionRing) return;
    const mats = Array.isArray(o.material) ? o.material : [o.material];
    const clones = mats.map(m => { const c = m.clone(); c.userData._sceneOwned = true; return c; });
    o.material = Array.isArray(o.material) ? clones : clones[0];
    for(const m of mats) if(m.userData && m.userData._sceneOwned) m.dispose();   // clone antigo (re-clonagem após arte tardia)
    for(const c of clones) lista.push({
      mat: c,
      outline: !!ud.isOutline,
      color: c.color ? c.color.clone() : null,
      emissive: c.emissive ? c.emissive.clone() : null,
      opacity: c.opacity, transparent: c.transparent,
    });
  });
  u._sceneMats = lista;
  return lista;
}
function _pintarMateriaisCena(fig, pose){
  for(const e of _materiaisCena(fig)){
    const m = e.mat, flash = pose.flash || 0;
    if(e.outline){   // casca do contorno: só desvanece com o peão (nunca clareia/escurece)
      if(pose.opacity !== undefined){ m.transparent = true; m.opacity = e.opacity * pose.opacity; }
      else { m.transparent = e.transparent; m.opacity = e.opacity; }
      continue;
    }
    if(e.emissive){
      if(flash) m.emissive.setRGB(flash, flash, flash); else m.emissive.copy(e.emissive);
    }
    if(e.color){
      m.color.copy(e.color);
      if(flash && !e.emissive) m.color.addScalar(flash);        // sprites: clareia
      if(pose.darken !== undefined) m.color.multiplyScalar(pose.darken);
    }
    if(pose.opacity !== undefined){ m.transparent = true; m.opacity = e.opacity * pose.opacity; }
    else { m.transparent = e.transparent; m.opacity = e.opacity; }
  }
}
function _restaurarMateriaisCena(fig){
  for(const e of (fig.userData._sceneMats || [])){
    const m = e.mat;
    if(e.color) m.color.copy(e.color);
    if(e.emissive) m.emissive.copy(e.emissive);
    m.opacity = e.opacity; m.transparent = e.transparent;
  }
}
function _aplicarPoseCena(fig, now){
  if(!window.CombatScene) return;
  const key = _figSceneKey(fig);
  if(!key) return;
  const pose = CombatScene.poseFor(key, now);
  const u = fig.userData;
  if(!pose){
    if(u._scenePoseAtiva){
      u._scenePoseAtiva = false;
      fig.position.x = u.gridX + (Number(u.footprintOffsetX) || 0);
      fig.position.z = u.gridY + (Number(u.footprintOffsetZ) || 0);
      fig.rotation.set(0, u._sceneBaseRotY || 0, u._hitBaseRotationZ || 0);
      if(u._sceneBaseScale) fig.scale.copy(u._sceneBaseScale);
      _restaurarMateriaisCena(fig);
    }
    return;
  }
  if(!u._scenePoseAtiva){
    u._scenePoseAtiva = true;
    // Casa AUTORITATIVA da cena (attack_feedback do servidor). gridX/gridY só são
    // renovados por renderMap3D a partir de um game_state — um monstro que anda
    // (deslize entity_step) e ataca no mesmo turno NÃO recebe game_state entre o
    // passo e o golpe, e a pose o devolveria à casa de antes do passo. Gravar a
    // base aqui faz a pose E a restauração partirem da casa certa.
    if(Array.isArray(pose.base)){ u.gridX = pose.base[0]; u.gridY = pose.base[1]; }
    // Sob o redemoinho rotation.y já traz o giro do frame: a base é a de antes.
    u._sceneBaseRotY = (u._whirlpoolWasSpinning && u._whirlpoolBaseRotationY != null)
      ? u._whirlpoolBaseRotationY : (fig.rotation.y || 0);
    u._sceneBaseScale = fig.scale.clone();
  }
  fig.position.x = u.gridX + (Number(u.footprintOffsetX) || 0) + pose.dx;
  fig.position.z = u.gridY + (Number(u.footprintOffsetZ) || 0) + pose.dz;
  fig.rotation.set(0, u._sceneBaseRotY, 0);
  if(pose.tilt){
    const d = pose.tiltDir;
    _sceneAxis.set(d[1], 0, -d[0]).normalize();      // eixo ⟂ à direção: y × d
    fig.rotateOnWorldAxis(_sceneAxis, pose.tilt);
  }
  const b = u._sceneBaseScale;
  fig.scale.set(b.x, b.y * (pose.scaleY == null ? 1 : pose.scaleY), b.z);
  if(pose.flash || pose.opacity !== undefined || pose.darken !== undefined) _pintarMateriaisCena(fig, pose);
  else if(u._sceneMats) _restaurarMateriaisCena(fig);
}

// Shake de câmera do crítico/morte. OrbitControls recalcula a câmera a partir de
// position − target a cada update(): o offset precisa ser retirado ANTES e
// posto de volta DEPOIS, senão vira deriva permanente.
function _desfazerShakeCamera(){
  if(g3 && g3._shakeOffset){ g3.camera.position.sub(g3._shakeOffset); g3._shakeOffset = null; }
}
function _reduzMovimento(){
  try{ return !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches); }
  catch(e){ return false; }
}
function _aplicarShakeCamera(now){
  if(!g3 || !window.CombatScene) return;
  const sh = CombatScene.shake(now);        // consome/limpa a lista mesmo com movimento reduzido
  if(!sh || _reduzMovimento()) return;
  const T = g3.T, q = g3.camera.quaternion;
  const off = new T.Vector3(1,0,0).applyQuaternion(q).multiplyScalar(sh.x)
    .add(new T.Vector3(0,1,0).applyQuaternion(q).multiplyScalar(sh.y));
  g3.camera.position.add(off);
  g3._shakeOffset = off;
}

function startLoop3D(){
  let lastDecorAnimAt = performance.now();
  function tick(){
    if(!g3) return;
    g3.animFrame = requestAnimationFrame(tick);
    const t = Date.now();
    const now = performance.now();
    const decorAnimDt = Math.min(0.1, Math.max(0, now - lastDecorAnimAt) / 1000);
    lastDecorAnimAt = now;
    if(g3.decorMeshes){
      for(const decor of Object.values(g3.decorMeshes)){
        const mixer = decor && decor.userData && decor.userData.animationMixer;
        if(mixer) mixer.update(decorAnimDt);
      }
    }
    _updateGroundItemDropAnimations3D(now);
    _fpsTick(now);
    // Todos os efeitos de magia compartilham este mesmo frame do renderer.
    _flushVisualAnimFrame3D(now);
    _updateFlightFallAnimations3D(now);
    _updateDiceLoop3D(now);
    _tickCombatScene(now);
    _spinAttackFxUpdateAll3D(now);
    // Não depende de renderMap3D: ele pode ser adiado enquanto uma miniatura
    // caminha. Isso garante que ativar/cancelar uma habilidade reflita no
    // próximo frame 3D, e que o ícone acompanhe a posição animada do herói.
    if(GS.gameState && (g3._activeEffectsDirty || g3._activeEffectsState !== GS.gameState))
      _sincronizarEfeitosAtivos3DImediatamente(GS.gameState);
    if(GS.gameState){
      try { _sync3DCancaoRing(GS.gameState); } catch(e) { console.warn('cancaoAura3D:', e); }
    }
    _atualizarCancaoHeroicaAura3D(now);
    _atualizarPosicoesEfeitosAtivos3D();
    _atualizarProtetor3D(now);
    _atualizarProvocacaoMarks3D(now);

    // ── OrbitControls damping (pausado durante o seguimento de câmera) ───────
    _desfazerShakeCamera();   // o offset do frame anterior não pode ser absorvido pelo OrbitControls
    if(!configCamera.seguindoPeao) g3.controls.update();
    atualizarCamera();   // seguimento suave do peão (quando ativo)
    _aplicarShakeCamera(now);

    // ── Player torch flicker (two sine waves for organic feel) ──────────────
    g3.torch.intensity = 8.5 + Math.sin(t/112)*1.0 + Math.sin(t/197)*0.7;

    // ── Wall torch flicker (each torch has a random phase offset) ───────────
    if(g3.wallTorches){
      for(const wt of g3.wallTorches){
        if(!wt.group.visible) continue;
        // Two overlapping sine waves → irregular organic crackle
        const fl = Math.sin(t*0.003  + wt.offset)*0.28
                 + Math.sin(t*0.0071 + wt.offset*1.3)*0.10;
        if(wt.flames){
          for(const cone of wt.flames){
            const subFl = fl + Math.sin(t*0.005 + cone.userData.subOffset)*0.12;
            if(cone.material) cone.material.emissiveIntensity = (cone.userData.baseEmissive||2.0) + subFl;
            cone.scale.y = 1.0 + subFl * 0.18;
          }
        }
      }
    }

    // ── Pool de luzes: reatribuição periódica (segue o herói) + flicker ──────
    if(g3.lightPool){
      if(!g3._poolNextAt || t > g3._poolNextAt){
        g3._poolNextAt = t + 150;   // reatribuir 6-7×/s é de sobra e quase grátis
        _atribuirLightPool();
      }
      for(const slot of g3.lightPool){
        const a = slot.anchor;
        if(!a || a.kind !== 'torch') continue;
        const fl = Math.sin(t*0.003  + a.offset)*0.28
                 + Math.sin(t*0.0071 + a.offset*1.3)*0.10;
        slot.light.intensity = 3.8 + fl;
      }
    }

    // ── Glowing grout pulse (trap-room magic rune lines) ─────────────────────
    if(g3.groutMats){
      const gp = 0.5 + 0.5 * Math.sin(t / 820);   // slow, deep purple breath
      for(const mat of g3.groutMats)
        mat.emissiveIntensity = 0.35 + gp * 0.90;
    }

    // ── Movement highlight pulse (blue overlay planes — slow sine breath) ───────
    if(g3.moveHighlightMat){
      const pulse = 0.5 + 0.5 * Math.sin(t / 420);
      g3.moveHighlightMat.opacity = 0.36 + 0.40 * pulse;
    }

    _atualizarTerrenoAnimado3D(t);
    _animarFogoPersistente3D(t);
    // A parede da Prisão de Chamas dura várias rodadas: precisa avançar a
    // cada quadro, e não só durante a animação de conjuração.
    _animarChamasVivasPersistentes3D(now);
    _updateArmadilhas3D(now);
    _updateFumaca3D(now);

    // ── Floating dust motes (upward drift, reset at ceiling, re-randomise XZ) ─
    if(g3.dustPts && g3.dustPts.visible &&
       (!g3._dustLastAt || t - g3._dustLastAt >= 33)){
      const dustDt = g3._dustLastAt ? Math.min(80, t - g3._dustLastAt) / 16.667 : 1;
      g3._dustLastAt = t;
      const attr = g3.dustPts.geometry.attributes.position;
      for(let i = 0; i < g3.dustCount; i++){
        g3.dustY[i] += g3.dustVel[i] * dustDt;
        if(g3.dustY[i] > g3.dustCeil){
          g3.dustY[i]      = 0;
          g3.dustXZ[i*2]   = Math.random() * g3.W;    // respawn at new XZ
          g3.dustXZ[i*2+1] = Math.random() * g3.H;
        }
        attr.array[i*3]   = g3.dustXZ[i*2];
        attr.array[i*3+1] = g3.dustY[i];
        attr.array[i*3+2] = g3.dustXZ[i*2+1];
      }
      attr.needsUpdate = true;
    }

    if(g3.stairGroup && g3.stairGroup.visible){
      const sp=0.45+0.55*Math.sin(t/600);
      g3.stairGroup.traverse(c=>{
        if(c.userData.isStairGlow&&c.material) c.material.emissiveIntensity=0.30+0.55*sp;
      });
    }

    // ── Chest glow pulse (golden shimmer on floor around each chest) ──────────
    if(g3.chestMeshes){
      const cp = 0.5 + 0.5 * Math.sin(t / 480);   // ~3 s breath cycle
      for(const grp of Object.values(g3.chestMeshes)){
        if(!grp.visible) continue;
        grp.traverse(c => {
          if(c.userData.isChestGlow && c.material){
            c.material.emissiveIntensity = 0.8 + 1.2 * cp;
            c.material.opacity = 0.25 + 0.30 * cp;
          }
        });
      }
    }

    // pulse: 0 → 1 → 0 on a ~2.2 s cycle.  Ring breathes in XZ; light fades.
    const pulse = 0.5 + 0.5 * Math.sin(t / 350);
    if(g3._pulseNodesDirty || !g3._pulseNodes){
      g3._pulseNodes = [];
      g3.entityGroup.traverse(child => {
        if(child.userData.isPulseRing || child.userData.isSelectionRing)
          g3._pulseNodes.push(child);
      });
      g3._pulseNodesDirty = false;
    }
    for(const child of g3._pulseNodes){
      if(!child.parent || !child.visible) continue;
      if(child.userData.isPulseRing || child.userData.isSelectionRing){
        if(!child.userData._pulseBaseScale) child.userData._pulseBaseScale = child.scale.clone();
        const selectedPulse = child.userData.isSelectionRing;
        const p = selectedPulse
          ? 0.5 + 0.5 * Math.sin(t / (VC.feedback?.selectionPulseSpeed ?? 260))
          : pulse;
        const amount = selectedPulse ? (VC.feedback?.selectionPulseAmount ?? 0.075) : 0.14;
        const s = 1.0 + amount * p;
        const b = child.userData._pulseBaseScale;
        child.scale.set(b.x * s, b.y, b.z * s);
        if(child.material && child.material.emissiveIntensity !== undefined){
          child.material.emissiveIntensity = selectedPulse ? 1.45 + 0.75 * p : 1.1 + 1.1 * p;
        }
      }
    }

    // Each figure Group (direct child of entityGroup) tagged with gridX/gridY:
    //   • Hover  → smooth Y-lift toward 0.15 units + dim gold vitrine spotlight
    //   • Select → slow Y-axis spin (ring glows by emissive; no extra light needed)
    const hovP  = g3.hoveredPos;
    const selP  = g3.selectedPos;
    const hspot = g3.hoverSpot;
    let hovFigY = 0.30;   // world-Y for the vitrine light (default when not hovering)
    let curFig  = null;   // figura da vez — recebe a g3.haloLight permanente
    g3.entityGroup.children.forEach(fig => {
      if(fig.type !== 'Group') return;
      const _magicInvisible = !!fig.userData.magicalInvisible ||
        (fig.userData.pid != null && _invisibilidadeAnimAtiva(fig.userData.pid));
      // A invisibilidade só altera os materiais quando o estado realmente
      // muda. Antes, todos os meshes de cada peão eram percorridos a cada
      // frame, mesmo estando visíveis e sem nenhuma alteração.
      if(fig.userData._magicInvisibleApplied !== _magicInvisible){
        fig.userData._magicInvisibleApplied = _magicInvisible;
        fig.traverse(obj => {
          if(!obj.material) return;
          const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
          for(const mat of mats){
            if(mat.userData._invisOrigOpacity === undefined){
              mat.userData._invisOrigOpacity = mat.opacity;
              mat.userData._invisOrigTransparent = mat.transparent;
              mat.userData._invisOrigDepthWrite = mat.depthWrite;
            }
            mat.opacity = _magicInvisible ? mat.userData._invisOrigOpacity * .18 : mat.userData._invisOrigOpacity;
            mat.transparent = _magicInvisible ? true : mat.userData._invisOrigTransparent;
            mat.depthWrite = _magicInvisible ? false : mat.userData._invisOrigDepthWrite;
          }
        });
      }
      // Antes dos returns abaixo: o peão da vez também precisa carregar o halo
      // enquanto está andando (entityGroup fica na origem, então position é mundo).
      if(fig.userData.isCurrentFig) curFig = fig;
      // Não interfere no peão em movimento — _animarPasso controla o Y dele.
      if(estadoMovimento.emMovimento && fig === estadoMovimento.peaoAtivo) return;
      // Idem para o servo/prisioneiro movido à mão (_animarPassoMinion).
      if(typeof estadoMininoMov !== 'undefined' && estadoMininoMov.emMovimento && fig === estadoMininoMov.peaoAtivo) return;
      const gx = fig.userData.gridX, gy = fig.userData.gridY;
      if(gx === undefined) return;
      // Reação de impacto no 3D: inclina o grupo inteiro por poucos frames.
      // A rotação é aplicada sobre a pose normal; não altera facing, grade ou
      // a posição usada pelo movimento/seleção.
      if(fig.userData._hitBaseRotationZ === undefined)
        fig.userData._hitBaseRotationZ = fig.rotation.z || 0;
      fig.rotation.z = fig.userData._hitBaseRotationZ
        + _hitReaction3DAngle(_figSceneKey(fig), performance.now());
      // O redemoinho arrasta visualmente a criatura presa. A rotação é
      // aplicada à raiz inteira, preservando a pose/facing quando o efeito
      // termina e sem alterar posição, colisão ou regras autoritativas.
      if(fig.userData.whirlpoolTrapped){
        if(!fig.userData._whirlpoolWasSpinning)
          fig.userData._whirlpoolBaseRotationY = fig.rotation.y || 0;
        fig.userData._whirlpoolWasSpinning = true;
        fig.rotation.y = (fig.userData._whirlpoolBaseRotationY || 0) + performance.now() / 360;
      } else if(fig.userData._whirlpoolWasSpinning){
        fig.rotation.y = fig.userData._whirlpoolBaseRotationY || 0;
        delete fig.userData._whirlpoolWasSpinning;
        delete fig.userData._whirlpoolBaseRotationY;
      }
      // Alvo que falhou no teste do ciclone: gira na mesma velocidade do
      // funil correspondente. O estado é apenas visual; a regra autoritativa
      // continua nos flags temporários enviados pelo servidor.
      const _tempestadeSpin = fig.userData.tempestadeCicloneSpin;
      if(_tempestadeSpin){
        if(!fig.userData._tempestadeWasSpinning)
          fig.userData._tempestadeBaseRotationY = fig.rotation.y || 0;
        fig.userData._tempestadeWasSpinning = true;
        fig.rotation.y = (fig.userData._tempestadeBaseRotationY || 0)
          + performance.now() / Math.max(1, Number(_tempestadeSpin.speedMs) || 520);
      } else if(fig.userData._tempestadeWasSpinning){
        fig.rotation.y = fig.userData._tempestadeBaseRotationY || 0;
        delete fig.userData._tempestadeWasSpinning;
        delete fig.userData._tempestadeBaseRotationY;
      }
      const isHov = hovP && gx === hovP[0] && gy === hovP[1];
      const isSel = selP && gx === selP[0] && gy === selP[1];
      // Smooth vertical lift (lerp coefficient 0.14 ≈ snappy but not instant)
      const targetY = (fig.userData.baseY || 0) + (isHov ? (VC.feedback?.hoverLift ?? 0.13) : 0);
      fig.position.y += (targetY - fig.position.y) * 0.14;
      if(isHov) hovFigY = fig.position.y + 0.30;   // light tracks above base
      // Slow Y-rotation while selected (~3 rpm)
      if(isSel) fig.rotation.y += 0.008;
      _aplicarPoseCena(fig, now);
      // O giro vem depois da pose do CombatScene para não ser sobrescrito.
      _aplicarGiroAtaque3D(fig, now);
    });
    // Fade vitrine spotlight in/out
    if(hovP && hspot){
      hspot.position.set(hovP[0], hovFigY, hovP[1]);
      hspot.intensity += ((VC.feedback?.hoverLightIntensity ?? 0.72) - hspot.intensity) * 0.18;
    } else if(hspot){
      hspot.intensity *= 0.82;   // fast fade-out
    }

    // ── Halo do turno ativo: move a luz permanente para o peão da vez ────────────
    // Sem peão da vez (turno dos monstros, herói na névoa) ela só apaga por
    // intensidade — a contagem de luzes da cena nunca muda.
    if(g3.haloLight){
      if(curFig){
        g3.haloLight.position.set(curFig.position.x, curFig.position.y + 0.29, curFig.position.z);
        g3.haloLight.intensity = 0.7 + 1.0 * pulse;
      } else {
        g3.haloLight.intensity = 0;
      }
    }

    // ── Sombra direcional congelada: só redesenha o shadow map quando algo mexeu ─
    // Enquanto a cena está parada (orbitando a câmera, lendo o HUD) o mapa de
    // sombra anterior continua válido — é aí que a economia aparece.
    if(g3.showcase && (estadoMovimento.emMovimento || _tweens.length
        || g3.hoveredPos || g3.selectedPos)){
      // A sombra direcional congelada não precisa ser renderizada 60×/s para
      // acompanhar uma miniatura. Duas atualizações por quadro mantêm a reação
      // visual imediata sem repetir o shadow pass completo desnecessariamente.
      g3._shadowFrame = (g3._shadowFrame || 0) + 1;
      if(g3._shadowFrame % 2 === 0) g3.showcase.shadow.needsUpdate = true;
    }

    // Portrait is HTML-only (class selection screen). Never meshes on the board.

    g3.renderer.render(g3.scene, g3.camera);
  }
  tick();
}

// ── Scene update (called wherever renderMap() is called) ─────────────────────

// Builds door arches, pillars, wood door panels, corner columns and baseboards.
// Returns a dict: tile-key → [mesh, ...] for fog-of-war visibility management.
// Called once from init3D; meshes start hidden (visible = false).
function buildWallDetails(T, scene, state, wallTex, TW, TH, WH){
  const tiles = state.tiles;
  const H = tiles.length, W = tiles[0].length;
  const det = {};
  const isDuneWall = (x, y) => tiles[y]?.[x] === TILE_WALL
    && new Set(['duna_deserto', 'rocha', 'rocha_marrom']).has(
      matDaCasa(state, x, y));

  // Stone material matching wallBaseMat, brightness-adjustable
  // Memoizado por brilho: `v` assume 5 valores (0.70, 0.94, 1.06, 1.12, 1.18),
  // mas isto criava um material NOVO por chamada -- 439 materiais num mapa
  // 44x40 para 5 aparencias. E o mesmo erro que o cache das casas ja corrigiu
  // ("nunca clonar material por casa"): o renderer troca de estado a cada
  // material distinto.
  const _stCache = new Map();
  const mkSt = (v) => {
    let m = _stCache.get(v);
    if(m) return m;
    m = new T.MeshStandardMaterial({
      map: wallTex, roughnessMap: wallTex, roughness: 0.92, metalness: 0.04
    });
    m.color.setRGB(0.52*v, 0.50*v, 0.47*v);
    _stCache.set(v, m);
    return m;
  };
  const woodTex  = generateTexture('wood');
  const woodMat  = new T.MeshStandardMaterial({
    map: woodTex, color: new T.Color(0x2a1208), roughness: 0.95, metalness: 0
  });
  const hingeMat = new T.MeshStandardMaterial({
    color: new T.Color(0x7a5a1a), roughness: 0.50, metalness: 0.84
  });

  const add = (key, mesh) => {
    mesh.receiveShadow = true;
    mesh.visible = false;
    // Fora da cena: quem desenha e a InstancedMesh de _rebuildDetailInstances.
    // Eram 439 draw calls (arcos, pilares, rodapes) num mapa 44x40, e todos
    // usam so 3 geometrias -- instanciar leva isso a meia duzia de draw calls.
    // A matriz de MUNDO precisa ser calculada aqui: as pedras do arco vivem
    // dentro de um Group rotacionado, e fora da cena ninguem mais a atualiza.
    mesh.updateMatrixWorld(true);
    (det[key] = det[key] || []).push(mesh);
  };

  // Arch peak = WH exactly: pilH + 2*archR = WH - TH
  const archR  = 0.36;                     // arch major radius
  const archT  = 0.09;                     // arch tube radius
  const pilH   = WH - TH - 2 * archR;     // pillar height = 0.81
  const archCY = TH + pilH + archR;        // arch center Y = 1.39
  const pilCY  = TH + pilH * 0.5;         // pillar center Y = 0.625
  const doorW  = archR * 1.85;             // door panel width = 0.666

  const bsH  = 0.055;                      // baseboard height
  const bsDp = 0.10;                       // baseboard depth (from wall face)
  const bsY  = TH + bsH * 0.5;            // center Y (sits on floor surface)
  const bsFO = TW * 0.5 - bsDp * 0.30;   // wall-face offset (slight protrusion)

  // ── Shared geometries (one instance, many meshes via clone/direct reuse) ──
  const pilGeo = new T.BoxGeometry(0.22, pilH, 0.22);
  const colGeo = new T.CylinderGeometry(0.11, 0.14, WH, 8);
  const hinGeo = new T.CylinderGeometry(0.030, 0.030, 0.14, 6);
  const bsGX   = new T.BoxGeometry(TW + 0.04, bsH, bsDp);  // baseboard N/S faces
  const bsGZ   = new T.BoxGeometry(bsDp, bsH, TW + 0.04);  // baseboard E/W faces

  // ── Helper: count floor-tile orthogonal neighbors of tile (fx,fy) ─────────
  const floorNeighbors = (fx, fy) =>
    [[0,-1],[0,1],[1,0],[-1,0]].reduce((acc,[dx,dy]) => {
      const nx=fx+dx, ny=fy+dy;
      return acc + (nx>=0&&ny>=0&&nx<W&&ny<H&&tiles[ny][nx]===TILE_FLOOR ? 1 : 0);
    }, 0);

  for(let y = 0; y < H; y++){
    for(let x = 0; x < W; x++){
      const tile = tiles[y][x];
      const key  = `${x},${y}`;

      const gT  = (dx,dy) => { const nx=x+dx,ny=y+dy; return (nx>=0&&ny>=0&&nx<W&&ny<H)?tiles[ny][nx]:TILE_WALL; };
      const isW = (dx,dy) => gT(dx,dy) === TILE_WALL;
      const isF = (dx,dy) => gT(dx,dy) === TILE_FLOOR;

      if(tile === TILE_FLOOR){
        const wN=isW(0,-1), wS=isW(0,1), wE=isW(1,0), wW=isW(-1,0);
        const wCnt = (wN?1:0)+(wS?1:0)+(wE?1:0)+(wW?1:0);

        // Door = floor tile with walls on exactly 2 opposite sides,
        // and at least one open side leads to a wider area (≥3 floor neighbours = room tile)
        let axis = null;
        if(wCnt===2 && wN && wS){
          // Passage runs E-W; check if E or W side opens into a room
          const eRoom = isF(1,0)  && floorNeighbors(x+1, y) >= 3;
          const wRoom = isF(-1,0) && floorNeighbors(x-1, y) >= 3;
          if(eRoom || wRoom) axis = 'NS';
        } else if(wCnt===2 && wE && wW){
          const nRoom = isF(0,-1) && floorNeighbors(x, y-1) >= 3;
          const sRoom = isF(0, 1) && floorNeighbors(x, y+1) >= 3;
          if(nRoom || sRoom) axis = 'EW';
        }

        if(axis){
          // ── Stone arch: 7 individual voussoir BoxGeometry blocks in a fan ──
          // Each stone is tangentially rotated to follow the arc curvature.
          // Keystone (centre, i=3) is slightly brighter; blocks alternate tone.
          try{
            const N      = 7;
            const arcStp = archR * Math.PI / (N - 1);   // arc length per stone
            const stoneW = arcStp * 0.78;                // tangential width (gap for mortar)
            const stoneH = 0.17;                         // radial depth
            const stoneDp= archT * 2.2;                  // depth through arch thickness
            const archGrp = new T.Group();
            archGrp.position.set(x, archCY, y);
            // NS door: arch must span Z (N-S) — rotate group 90° around Y
            // EW door: arch spans X by default, no rotation needed
            if(axis === 'NS') archGrp.rotation.y = Math.PI / 2;
            for(let i = 0; i < N; i++){
              const θ  = i * Math.PI / (N - 1);    // 0 = right foot → π = left foot
              const cx = archR * Math.cos(θ);       // local X in arch plane
              const cy = archR * Math.sin(θ);       // local Y (up)
              const isKey = (i === Math.floor(N / 2));
              const stone = new T.Mesh(
                new T.BoxGeometry(stoneW, stoneH, stoneDp),
                mkSt(isKey ? 1.18 : (i % 2 === 0 ? 0.94 : 1.06))
              );
              stone.position.set(cx, cy, 0);
              stone.rotation.z = Math.PI / 2 + θ;  // tangential alignment
              stone.receiveShadow = true;
              archGrp.add(stone);
            }
            add(key, archGrp);
          }catch(e){}

          const pPos = axis === 'NS'
            ? [[x, pilCY, y-archR], [x, pilCY, y+archR]]
            : [[x-archR, pilCY, y], [x+archR, pilCY, y]];
          for(const [px,py,pz] of pPos){
            try{
              const pm = new T.Mesh(pilGeo, mkSt(1.06));
              pm.position.set(px, py, pz);
              add(key, pm);
            }catch(e){}
          }

          // ── Wood door panel (recessed 0.05 into passage) ─────────────────
          try{
            const dGeo = axis === 'NS'
              ? new T.BoxGeometry(doorW, pilH, 0.065)   // door face visible from E/W
              : new T.BoxGeometry(0.065, pilH, doorW);  // door face visible from N/S
            const dm = new T.Mesh(dGeo, woodMat.clone());
            dm.position.set(
              x + (axis === 'EW' ? 0.05 : 0),
              TH + pilH * 0.5,
              y + (axis === 'NS' ? 0.05 : 0)
            );
            add(key, dm);
          }catch(e){}

          // ── Hinges (2 aged-gold cylinders on the hinge-side pillar face) ──
          for(const hFrac of [0.26, 0.70]){
            try{
              const hm = new T.Mesh(hinGeo, hingeMat.clone());
              const hY = TH + pilH * hFrac;
              if(axis === 'NS'){
                hm.rotation.z = Math.PI / 2;  // cylinder axis → X (horizontal)
                hm.position.set(x + doorW*0.5 + 0.025, hY, y - archR + 0.06);
              } else {
                hm.rotation.x = Math.PI / 2;  // cylinder axis → Z (horizontal)
                hm.position.set(x - archR + 0.06, hY, y + doorW*0.5 + 0.025);
              }
              add(key, hm);
            }catch(e){}
          }
        }
      }

      // ── WALL TILE: baseboards on every floor-adjacent face ───────────────
      // Dunas já têm uma base orgânica própria na geometria do monte. O
      // rodapé de pedra herdado das paredes da masmorra criava uma faixa
      // cinza artificial na face interna; não o use nesses tiles.
      else if(tile === TILE_WALL){
        if(!isDuneWall(x, y) && isF(0, 1)){  // floor to south
          try{ const bs=new T.Mesh(bsGX, mkSt(0.70)); bs.position.set(x, bsY, y+bsFO); add(key,bs); }catch(e){}
        }
        if(!isDuneWall(x, y) && isF(0,-1)){  // floor to north
          try{ const bs=new T.Mesh(bsGX, mkSt(0.70)); bs.position.set(x, bsY, y-bsFO); add(key,bs); }catch(e){}
        }
        if(!isDuneWall(x, y) && isF(1, 0)){  // floor to east
          try{ const bs=new T.Mesh(bsGZ, mkSt(0.70)); bs.position.set(x+bsFO, bsY, y); add(key,bs); }catch(e){}
        }
        if(!isDuneWall(x, y) && isF(-1,0)){  // floor to west
          try{ const bs=new T.Mesh(bsGZ, mkSt(0.70)); bs.position.set(x-bsFO, bsY, y); add(key,bs); }catch(e){}
        }
      }
    }
  }

  // At each 2×2 block of tiles, add a column where exactly 3 walls meet 1 floor
  // (the classic dungeon inner-corner with an L-shaped wall junction).
  // Column sits in the inter-tile gap at (gx+0.5, WH/2, gy+0.5), always visible.
  for(let gy = 0; gy < H-1; gy++){
    for(let gx = 0; gx < W-1; gx++){
      const tNW = tiles[gy][gx],   tNE = tiles[gy][gx+1];
      const tSW = tiles[gy+1][gx], tSE = tiles[gy+1][gx+1];
      const wCnt = (tNW===TILE_WALL?1:0)+(tNE===TILE_WALL?1:0)+
                   (tSW===TILE_WALL?1:0)+(tSE===TILE_WALL?1:0);

      // Only handle 3-walls-1-floor intersections (true inner corners)
      if(wCnt !== 3) continue;

      // A duna corner already has its own organic volume. The old dungeon
      // corner column would reappear as a gray stone pillar in the middle of
      // two dune walls, so omit it when the corner is formed by dunes.
      const duneCnt = [[gx,gy],[gx+1,gy],[gx,gy+1],[gx+1,gy+1]]
        .filter(([x,y]) => isDuneWall(x,y)).length;
      if(duneCnt >= 2) continue;

      // The visibility key is the single floor tile in this 2×2 block
      let visKey = null;
      for(const [dx,dy] of [[0,0],[1,0],[0,1],[1,1]]){
        const nx=gx+dx, ny=gy+dy;
        if(tiles[ny][nx] === TILE_FLOOR){ visKey=`${nx},${ny}`; break; }
      }
      if(!visKey) continue;

      try{
        const col = new T.Mesh(colGeo, mkSt(1.12));
        col.position.set(gx + 0.5, WH * 0.5, gy + 0.5);
        add(visKey, col);
      }catch(e){}
    }
  }

  return det;
}

// ── Per-room wall torches (bracket + flame + animated PointLight) ─────────────
// Selects 1–2 wall tiles per room and places a full torch assembly on each.
// wallTorches entries: { group, lx, ly, lz, flames, offset, wallKey }
// L-shaped iron bracket via CatmullRomCurve3 + TubeGeometry
// Flattened TorusGeometry rusty bowl
// 3 overlapping ConeGeometry fire cones with independent Y-scale animation
function buildRoomTorches(T, scene, state, wallTorches, TW, TH, WH){
  if(!state.rooms || !state.tiles) return {};
  const tiles = state.tiles;
  const H = tiles.length, W = tiles[0].length;

  // Iron material — dark rusty iron. UM material para todas as tochas: antes
  // cada suporte e cada tigela clonavam este material, gerando 70 copias
  // identicos e nunca mutados.
  const ironMat = new T.MeshStandardMaterial({
    color: new T.Color(0x3a2010), roughness: 0.84, metalness: 0.55
  });
  // Geometrias compartilhadas: a tigela e igual em toda tocha e o cone depende
  // so do indice da chama. Antes eram 175 geometrias distintas.
  const bowlGeo = new T.TorusGeometry(0.063, 0.025, 5, 12);
  const brkGeoCache = new Map();          // suporte: uma por direcao de parede
  const coneSpecs = [
    { r:0.046, h:0.18, col:0xff5500, em:0xff3300, ei:2.0, dy:0.000, ry: 0.00, rx: 0.00 },
    { r:0.030, h:0.16, col:0xff8800, em:0xff6600, ei:2.2, dy:0.010, ry: 1.00, rx: 0.10 },
    { r:0.018, h:0.13, col:0xffee80, em:0xffcc00, ei:2.5, dy:0.022, ry:-1.00, rx:-0.10 },
  ];
  const coneGeos = coneSpecs.map(sp => new T.ConeGeometry(sp.r, sp.h, 5));
  const torchStatic = {};                 // wallKey -> [suporte, tigela]

  for(const room of state.rooms){
    const {x: rx, y: ry, w: rw, h: rh} = room;

    // Collect wall-tile candidates on every boundary side
    const cands = [];
    for(let tx=rx; tx<rx+rw; tx++){
      const ty=ry-1;
      if(ty>=0 && tiles[ty][tx]===TILE_WALL && tiles[ry][tx]===TILE_FLOOR)
        cands.push({wx:tx, wy:ty, fdx:0, fdz:1});
    }
    for(let tx=rx; tx<rx+rw; tx++){
      const ty=ry+rh;
      if(ty<H && tiles[ty][tx]===TILE_WALL && tiles[ry+rh-1][tx]===TILE_FLOOR)
        cands.push({wx:tx, wy:ty, fdx:0, fdz:-1});
    }
    for(let ty=ry; ty<ry+rh; ty++){
      const tx=rx-1;
      if(tx>=0 && tiles[ty][tx]===TILE_WALL && tiles[ty][rx]===TILE_FLOOR)
        cands.push({wx:tx, wy:ty, fdx:1, fdz:0});
    }
    for(let ty=ry; ty<ry+rh; ty++){
      const tx=rx+rw;
      if(tx<W && tiles[ty][tx]===TILE_WALL && tiles[ty][rx+rw-1]===TILE_FLOOR)
        cands.push({wx:tx, wy:ty, fdx:-1, fdz:0});
    }
    if(!cands.length) continue;

    // Deterministic pick: 1 torch for small rooms, 2 for larger
    const hash = ((room.cx*7919)^(room.cy*3467)) & 0xFFFF;
    const nPick = (rw+rh >= 8 && cands.length >= 3) ? 2 : 1;
    const i1 = hash % cands.length;
    const i2 = (i1 + Math.floor(cands.length/2)) % cands.length;
    const picks = [cands[i1]];
    if(nPick === 2 && i2 !== i1) picks.push(cands[i2]);

    for(const {wx, wy, fdx, fdz} of picks){
      // Base da tocha em coordenadas de MUNDO. O suporte e a tigela sao criados
      // aqui ja em mundo (fora do Group) porque vao para InstancedMesh: eram
      // 70 dos 175 draw calls das tochas, com uma geometria E um material
      // clonados por tocha sem necessidade nenhuma -- nada neles e animado.
      const bx = wx + fdx*0.38, by = WH*0.50, bz = wy + fdz*0.38;
      const grp = new T.Group();
      grp.position.set(bx, by, bz);
      const estaticos = [];

      // ── L-shaped iron bracket via CatmullRomCurve3 ─────────────────────
      // A curva so depende da direcao da parede: 4 variantes, nao uma por tocha.
      try{
        const dirKey = fdx + ',' + fdz;
        let brkGeo = brkGeoCache.get(dirKey);
        if(!brkGeo){
          const curve = new T.CatmullRomCurve3([
            new T.Vector3(0,         0.02,         0),
            new T.Vector3(fdx*0.04,  0.03,  fdz*0.04),
            new T.Vector3(fdx*0.11,  0.055, fdz*0.11),
            new T.Vector3(fdx*0.15,  0.08,  fdz*0.15)
          ]);
          brkGeo = new T.TubeGeometry(curve, 10, 0.013, 5, false);
          brkGeoCache.set(dirKey, brkGeo);
        }
        const brkMesh = new T.Mesh(brkGeo, ironMat);
        brkMesh.position.set(bx, by, bz);
        brkMesh.receiveShadow = true;
        brkMesh.visible = false;
        brkMesh.updateMatrixWorld(true);
        estaticos.push(brkMesh);
      }catch(e){}

      try{
        const bowl = new T.Mesh(bowlGeo, ironMat);
        bowl.rotation.x = Math.PI / 2;   // lay ring flat
        bowl.scale.y    = 0.40;           // squash into shallow cup
        bowl.position.set(bx + fdx*0.15, by + 0.11, bz + fdz*0.15);
        bowl.receiveShadow = true;
        bowl.visible = false;
        bowl.updateMatrixWorld(true);
        estaticos.push(bowl);
      }catch(e){}

      const fx = fdx*0.15, fz = fdz*0.15;
      const flames = [];
      // As chamas CONTINUAM meshes proprios dentro do grupo: cada cone tem o
      // seu emissiveIntensity animado com fase propria (por tocha e por cone),
      // e emissive e uniform de material -- compartilhar material faria todas
      // as chamas do mapa piscarem juntas.
      coneSpecs.forEach((sp, ci) => {
        try{
          const cm = new T.Mesh(
            coneGeos[ci],
            new T.MeshStandardMaterial({
              color: new T.Color(sp.col), emissive: new T.Color(sp.em),
              emissiveIntensity: sp.ei, roughness: 0.30, metalness: 0
            })
          );
          cm.position.set(fx, 0.16 + sp.dy, fz);
          cm.rotation.y = sp.ry;
          cm.rotation.x = sp.rx;
          cm.userData.baseEmissive = sp.ei;
          cm.userData.subOffset    = flames.length * 1.37;  // phase spread: 0 / 1.37 / 2.74 rad
          grp.add(cm);
          flames.push(cm);
        }catch(e){}
      });

      // Sem PointLight própria: a luz da tocha vem do POOL fixo (init3D), que é
      // atribuído às âncoras reveladas mais próximas do herói. Luz por tocha
      // mudava a contagem de luzes ao revelar a sala → recompilação de shaders.
      grp.visible = false;
      scene.add(grp);
      const wallKey = `${wx},${wy}`;
      if(estaticos.length) (torchStatic[wallKey] = torchStatic[wallKey] || []).push(...estaticos);
      wallTorches.push({
        group:   grp,
        // Ancora de luz em MUNDO. Antes era `fx`/`fz`, que sao o deslocamento
        // LOCAL dentro do grupo (no maximo +-0,15): o pool trata lx/lz como
        // coordenada de mundo, entao TODA luz de tocha ia parar perto da
        // origem do mapa, em vez de ficar na tocha.
        lx: bx + fx, ly: by + 0.28, lz: bz + fz,   // âncora de luz p/ o pool
        flames:  flames,
        offset:  ((wx*7919 ^ wy*3467) & 0xFF) / 255 * Math.PI * 2,
        wallKey: `${wx},${wy}`
      });
    }
  }
  return torchStatic;
}

// ── Room floor colour overlays (translucent planes per room role) ─────────────
// chest → golden glow  |  boss → ominous dark red  |  trap → arcane purple
// Each floor tile inside the room gets a PlaneGeometry overlay slightly above it.
function buildRoomOverlays(T, scene, state, roomOverlayMeshes, TW, TH){
  if(!state.rooms || !state.tiles) return;
  const tiles = state.tiles;
  const H = tiles.length, W = tiles[0].length;

  const roleSpec = {
    chest: { color: 0xc8a030, opacity: 0.30 },
    boss:  { color: 0x6a1a1a, opacity: 0.20 },
    trap:  { color: 0x4a2a6a, opacity: 0.25 },
  };

  // One shared plane geometry, materials per role
  const planeGeo = new T.PlaneGeometry(TW * 0.92, TW * 0.92);
  const matCache = {};

  for(const room of state.rooms){
    const spec = roleSpec[room.role];
    if(!spec) continue;

    if(!matCache[room.role]){
      matCache[room.role] = new T.MeshBasicMaterial({
        color:       new T.Color(spec.color),
        transparent: true,
        opacity:     spec.opacity,
        depthWrite:  false,
        side:        T.DoubleSide
      });
    }
    const mat = matCache[room.role];

    for(let ty=room.y; ty<room.y+room.h; ty++){
      for(let tx=room.x; tx<room.x+room.w; tx++){
        if(ty<0||ty>=H||tx<0||tx>=W) continue;
        if(tiles[ty][tx] !== TILE_FLOOR) continue;
        const key = `${tx},${ty}`;
        if(roomOverlayMeshes[key]) continue;  // already has overlay (room overlap)
        const m = new T.Mesh(planeGeo, mat);
        m.rotation.x = -Math.PI / 2;
        m.position.set(tx, topoTerreno3D(state, tx, ty, TH) + 0.004, ty);  // float 4mm above floor surface
        m.visible = false;
        scene.add(m);
        roomOverlayMeshes[key] = m;
      }
    }
  }
}

// ── Scenery barrels — CylinderGeometry + TorusGeometry hoops at room corners ──
function buildSceneryBarrels(T, scene, state, TW, TH, WH){
  if(!state.rooms || !state.tiles) return {};
  const tiles = state.tiles;
  const mapH = tiles.length, mapW = tiles[0].length;
  const sceneryMeshes = {};

  const woodMat = new T.MeshStandardMaterial({
    color: new T.Color(0x4a2a10), roughness: 0.90, metalness: 0.05
  });
  const hoopMat = new T.MeshStandardMaterial({
    color: new T.Color(0x282828), roughness: 0.70, metalness: 0.65
  });
  // Shared geometries (reused across all barrels)
  const bodyGeo = new T.CylinderGeometry(0.11, 0.13, 0.28, 10);
  const lidGeo  = new T.CylinderGeometry(0.11, 0.11, 0.03, 10);
  const baseGeo = new T.CylinderGeometry(0.13, 0.13, 0.02, 10);
  const hoopGeo = new T.TorusGeometry(0.12, 0.013, 5, 12);

  for(const room of state.rooms){
    const {x: rx, y: ry, w: rw, h: rh} = room;
    const isDuneWall = (x, y) => y >= 0 && x >= 0 && y < mapH && x < mapW
      && tiles[y][x] === TILE_WALL
      && new Set(['duna_deserto', 'rocha', 'rocha_marrom']).has(
        ((state.materiais && state.materiais[`${x},${y}`]) || 'pedra_normal'));

    // Collect L-corner floor tiles inside this room
    const corners = [];
    for(let fy=ry; fy<ry+rh; fy++){
      for(let fx=rx; fx<rx+rw; fx++){
        if(tiles[fy][fx] !== TILE_FLOOR) continue;
        const wallN = (fy > 0)       && tiles[fy-1][fx] === TILE_WALL;
        const wallS = (fy < mapH-1)  && tiles[fy+1][fx] === TILE_WALL;
        const wallW = (fx > 0)       && tiles[fy][fx-1] === TILE_WALL;
        const wallE = (fx < mapW-1)  && tiles[fy][fx+1] === TILE_WALL;
        // Dunas não usam barris decorativos: o volume orgânico da parede já
        // ocupa visualmente esse encontro e o aro metálico destoaria do tema.
        if(isDuneWall(fx, fy-1) || isDuneWall(fx, fy+1)
           || isDuneWall(fx-1, fy) || isDuneWall(fx+1, fy)) continue;
        // Only perpendicular pairs (L-corners), not opposite pairs (corridors)
        if     (wallN && wallW) corners.push({fx, fy, ox:-0.21, oz:-0.21});
        else if(wallN && wallE) corners.push({fx, fy, ox: 0.21, oz:-0.21});
        else if(wallS && wallW) corners.push({fx, fy, ox:-0.21, oz: 0.21});
        else if(wallS && wallE) corners.push({fx, fy, ox: 0.21, oz: 0.21});
      }
    }
    if(!corners.length) continue;

    // Deterministic pick: 1 barrel for small rooms, up to 2 for larger
    const hash = ((room.cx * 5381) ^ (room.cy * 2731)) & 0xFFFF;
    const nPick = (rw+rh >= 8 && corners.length >= 2) ? 2 : 1;
    const i1 = hash % corners.length;
    const i2 = (i1 + Math.floor(corners.length / 2)) % corners.length;
    const picks = [corners[i1]];
    if(nPick === 2 && i2 !== i1) picks.push(corners[i2]);

    for(const {fx, fy, ox, oz} of picks){
      const key = `${fx},${fy}`;
      const grp = new T.Group();

      // Deterministic Y rotation for variety
      const rotHash = ((fx * 4127) ^ (fy * 6311)) & 0xFF;
      grp.rotation.y = (rotHash / 255) * Math.PI * 0.5 - Math.PI * 0.25;
      grp.position.set(fx + ox, TH, fy + oz);

      // Body (tapered cylinder)
      const body = new T.Mesh(bodyGeo, woodMat);
      body.position.y = 0.14;   // half-height above base
      body.castShadow = true;
      grp.add(body);

      // Lid cap
      const lid = new T.Mesh(lidGeo, woodMat);
      lid.position.y = 0.295;   // body top + half of lid
      lid.castShadow = true;
      grp.add(lid);

      // Base disc
      const base = new T.Mesh(baseGeo, woodMat);
      base.position.y = 0.01;
      grp.add(base);

      // 3 metal hoops — evenly spaced vertically
      for(const hy of [0.07, 0.14, 0.21]){
        const hoop = new T.Mesh(hoopGeo, hoopMat);
        hoop.rotation.x = Math.PI / 2;   // lay flat around barrel
        hoop.position.y = hy;
        grp.add(hoop);
      }

      grp.visible = false;
      // Fora da cena: desenhados por _rebuildDetailInstances. Os barris ja
      // compartilham geometria e material entre si, entao instanciam direto --
      // eram 156 draw calls.
      grp.updateMatrixWorld(true);
      if(!sceneryMeshes[key]) sceneryMeshes[key] = [];
      sceneryMeshes[key].push(grp);
    }
  }
  return sceneryMeshes;
}

// ── Glowing grout — emissive rune lines on trap/magic room floor grids ────────
function buildGlowingGrout(T, scene, state, TW, TH){
  if(!state.rooms || !state.tiles) return { meshes:{}, mats:[] };
  const tiles = state.tiles;

  // Single shared emissive material — animated in startLoop3D
  const groutMat = new T.MeshStandardMaterial({
    color:    new T.Color(0x5500aa),
    emissive: new T.Color(0xaa00ff),
    emissiveIntensity: 0.6,
    roughness: 0.5, metalness: 0,
    transparent: true, opacity: 0.80,
    depthWrite: false
  });

  // Two strip orientations — horizontal (N/S edges) and vertical (W/E edges)
  const hGeo = new T.BoxGeometry(TW * 0.88, 0.007, 0.09);  // E–W strip
  const vGeo = new T.BoxGeometry(0.09, 0.007, TW * 0.88);  // N–S strip

  const groutMeshes = {};

  for(const room of state.rooms){
    if(room.role !== 'trap') continue;   // only in magic / trap rooms
    const {x: rx, y: ry, w: rw, h: rh} = room;

    for(let fy=ry; fy<ry+rh; fy++){
      for(let fx=rx; fx<rx+rw; fx++){
        if(tiles[fy][fx] !== TILE_FLOOR) continue;
        const key = `${fx},${fy}`;
        const meshes = [];

        // N grout edge (top border of this tile)
        const mN = new T.Mesh(hGeo, groutMat);
        mN.position.set(fx, TH + 0.006, fy - 0.5);
        mN.visible = false;
        scene.add(mN);
        meshes.push(mN);

        // W grout edge (left border of this tile)
        const mW = new T.Mesh(vGeo, groutMat);
        mW.position.set(fx - 0.5, TH + 0.006, fy);
        mW.visible = false;
        scene.add(mW);
        meshes.push(mW);

        groutMeshes[key] = meshes;
      }
    }
  }
  return { meshes: groutMeshes, mats: [groutMat] };
}

// Returns a THREE.Group placed at (chest.pos[0], 0.22, chest.pos[1]).
// Call once per chest; manage visibility externally via .visible.
function buildChest3D(T, chest){
  const TH = 0.22;   // floor tile top surface
  const grp = new T.Group();
  grp.position.set(chest.pos[0], TH, chest.pos[1]);
  grp.userData.chestId = chest.id;

  const glowMat = new T.MeshStandardMaterial({
    color:    new T.Color(0xffaa00),
    emissive: new T.Color(0xffaa00),
    emissiveIntensity: 1.0,
    transparent: true, opacity: 0.40, depthWrite: false
  });

  // Gold glow halo on the floor around the chest
  const glow = new T.Mesh(new T.PlaneGeometry(0.90, 0.90), glowMat);
  glow.rotation.x = -Math.PI / 2;
  glow.position.set(0, 0.004, 0);   // just above floor surface
  glow.userData.isChestGlow = true;
  grp.add(glow);

  // O baú é SÓ o GLB — não há mais baú geométrico provisório (as caixas de
  // madeira/metal da primeira versão do jogo). Enquanto o arquivo carrega, só o
  // halo dourado marca a casa. Com o GLB já em cache o callback roda
  // SÍNCRONO, antes do chamador fazer scene.add(grp): por isso NÃO há guarda
  // por `grp.parent` aqui — era ela que descartava o GLB de todo baú criado
  // depois do primeiro, deixando o provisório na tela para sempre.
  _loadDecorGLB(T, 'assets/objetos/bau.glb', template => {
    if (!template) {
      // Falha de rede: o renderMap3D reconstrói este baú quando a marca de erro
      // sair do cache (_agendarRecargaArte).
      grp.userData.chestSemGLB = true;
      return;
    }
    const inst = template.clone();
    const box = new T.Box3().setFromObject(inst);
    const size = box.getSize(new T.Vector3());
    const scale = Math.min(
      0.72 / Math.max(size.x, 1e-3),
      0.62 / Math.max(size.z, 1e-3),
      0.54 / Math.max(size.y, 1e-3)
    );
    // Centraliza e encosta a base no topo do tile; o grupo já está em TH.
    inst.position.set(
      -(box.min.x + box.max.x) / 2,
      -box.min.y,
      -(box.min.z + box.max.z) / 2
    );
    inst.traverse(o => {
      if (o.isMesh) {
        o.castShadow = true; o.receiveShadow = true;
        o.userData.isChestGLB = true;
      }
    });
    const wrap = new T.Group();
    wrap.userData.isChestGLB = true;
    wrap.scale.setScalar(scale);
    wrap.add(inst);
    grp.add(wrap);
  });

  return grp;
}

// Item largado no chão: modelo 3D quando há GLB correspondente; emoji apenas
// como fallback enquanto carrega ou para itens sem miniatura.
// Posicionado por casa (mesma convenção dos baús: x=pos[0], z=pos[1]). O clique
// é resolvido por casa em handleTileClick (o raycast pega o chão sob o sprite).
const _GROUND_ITEM_GLB_MODELS = Object.freeze({
  gold_coins: {path: 'assets/itens/moedas_ouro.glb', footprint: 0.68},
  // Variantes de machado compartilham o mesmo modelo 3D do Machado Duplo.
  // A família é resolvida abaixo para também cobrir prata e futuros machados.
  machado: {path: 'assets/itens/machado.glb', layFlat: true, footprint: 0.78},
  // Bordões e cajados compartilham a miniatura do bastão no chão.
  bastao: {path: 'assets/itens/bastao.glb', layFlat: true, footprint: 0.78},
  // O mesmo modelo representa as variantes de espada no chão; nomes em
  // português e IDs do catálogo do servidor precisam apontar para o GLB.
  espada_curta: {path: 'assets/itens/espada.glb', layFlat: true, footprint: 0.78},
  espada_longa: {path: 'assets/itens/espada.glb', layFlat: true, footprint: 0.78},
  espada_bastarda: {path: 'assets/itens/espada.glb', layFlat: true, footprint: 0.78},
  espada_duas_maos: {path: 'assets/itens/espada.glb', layFlat: true, footprint: 0.78},
  sword: {path: 'assets/itens/espada.glb', layFlat: true, footprint: 0.78},
  shortsword: {path: 'assets/itens/espada.glb', layFlat: true, footprint: 0.78},
  longsword: {path: 'assets/itens/espada.glb', layFlat: true, footprint: 0.78},
  bastsword: {path: 'assets/itens/espada.glb', layFlat: true, footprint: 0.78},
  espada2m: {path: 'assets/itens/espada.glb', layFlat: true, footprint: 0.78},
  shortsword_prata: {path: 'assets/itens/espada.glb', layFlat: true, footprint: 0.78},
  longsword_prata: {path: 'assets/itens/espada.glb', layFlat: true, footprint: 0.78},
  bastsword_prata: {path: 'assets/itens/espada.glb', layFlat: true, footprint: 0.78},
  espada2m_prata: {path: 'assets/itens/espada.glb', layFlat: true, footprint: 0.78},
  lanca: {path: 'assets/itens/lanca.glb', layFlat: true, footprint: 0.78},
  lanca_curta: {path: 'assets/itens/lanca.glb', layFlat: true, footprint: 0.78},
  alabarda: {path: 'assets/itens/alabarda.glb', layFlat: true, footprint: 0.78},
  besta_mao: {path: 'assets/itens/besta.glb', footprint: 0.78},
  hand_crossbow: {path: 'assets/itens/besta.glb', footprint: 0.78},
  besta: {path: 'assets/itens/besta.glb', footprint: 0.78},
  besta_leve: {path: 'assets/itens/besta.glb', footprint: 0.78},
  besta_pesada: {path: 'assets/itens/besta.glb', footprint: 0.78},
  health_potion: {path: 'assets/itens/pocao_cura.glb', maxSize: 0.42},
  health_potion_small: {path: 'assets/itens/pocao_cura.glb', maxSize: 0.42},
  health_potion_concentrated: {path: 'assets/itens/pocao_cura.glb', maxSize: 0.42},
  health_potion_improved: {path: 'assets/itens/pocao_cura.glb', maxSize: 0.42},
  pocao_cura: {path: 'assets/itens/pocao_cura.glb', maxSize: 0.42},
});

function _groundItemGlbConfig(gi){
  const itemId = String(gi?.item?.id || '').trim().toLowerCase();
  return _GROUND_ITEM_GLB_MODELS[itemId]
    || (itemId.startsWith('machado_') ? _GROUND_ITEM_GLB_MODELS.machado : null)
    || ((itemId === 'staff' || itemId.startsWith('staff_')
      || itemId === 'bordao' || itemId.startsWith('bordao_')
      || itemId === 'cajado_madeira' || itemId.startsWith('cajado_madeira_'))
      ? _GROUND_ITEM_GLB_MODELS.bastao : null);
}

function buildGroundItem3D(T, gi, animateDrop=false){
  const grp = new T.Group();
  grp.position.set(gi.pos[0], 0.22, gi.pos[1]);   // TH do topo do chão (como o baú)
  const visual = new T.Group();
  grp.add(visual);
  grp.userData = {
    groundId: gi.id,
    dropVisual: visual,
    dropAnimation: animateDrop ? {
      startedAt: performance.now(), duration: 900,
      fromX: Number.isFinite(Number(gi.drop_from?.[0]))
        ? Math.max(-1, Math.min(1, Number(gi.drop_from[0]) - Number(gi.pos[0]))) : 0,
      fromZ: Number.isFinite(Number(gi.drop_from?.[1]))
        ? Math.max(-1, Math.min(1, Number(gi.drop_from[1]) - Number(gi.pos[1]))) : 0,
      finalAngle: (String(gi.id).split('').reduce((n, c) => n + c.charCodeAt(0), 0) % 628) / 100,
    } : null,
  };

  const cv = document.createElement('canvas'); cv.width = cv.height = 64;
  const c2 = cv.getContext('2d');
  c2.font = '48px serif'; c2.textAlign = 'center'; c2.textBaseline = 'middle';
  c2.fillText((gi.item && gi.item.emoji) || '📦', 32, 36);
  const tex = new T.CanvasTexture(cv);
  tex._owned = true;
  const spr = new T.Sprite(new T.SpriteMaterial({ map: tex, transparent: true, depthWrite: false }));
  spr.scale.set(0.55, 0.55, 0.55);
  spr.position.y = 0.32;
  spr.userData.isGroundItemFallback = true;
  visual.add(spr);

  const modelConfig = _groundItemGlbConfig(gi);
  const modelPath = modelConfig?.path;
  if(modelPath){
    _loadDecorGLB(T, modelPath, template => {
      if(grp.userData.removed) return;
      if(!template){
        grp.userData.groundModelFailed = true;
        grp.userData.groundModelFailureCache = _decorGLBCache[modelPath] ?? null;
        return;
      }
      const inst = template.clone();
      // Armas exportadas em pé ficam deitadas sobre o piso. A orientação usa
      // o maior eixo do modelo, sem presumir como foi exportado pelo Blender.
      if(modelConfig.layFlat){
        const originalBounds = new T.Box3().setFromObject(inst);
        const originalSize = originalBounds.getSize(new T.Vector3());
        if(originalSize.y >= originalSize.x && originalSize.y >= originalSize.z)
          inst.rotation.x = Math.PI / 2;
        else if(originalSize.x >= originalSize.y && originalSize.x >= originalSize.z)
          inst.rotation.y = Math.PI / 2;
      }
      inst.updateMatrixWorld(true);
      const bounds = new T.Box3().setFromObject(inst);
      const size = bounds.getSize(new T.Vector3());
      const center = bounds.getCenter(new T.Vector3());
      const scale = modelConfig.footprint
        ? modelConfig.footprint / Math.max(size.x, size.z, 0.001)
        : modelConfig.maxSize / Math.max(size.x, size.y, size.z, 0.001);
      inst.position.set(-center.x, -bounds.min.y, -center.z);
      const model = new T.Group();
      model.scale.setScalar(scale);
      model.position.y = 0.012;
      model.add(inst);

      for(const child of [...visual.children]){
        if(!child.userData.isGroundItemFallback) continue;
        visual.remove(child);
        if(child.material?.map?._owned) child.material.map.dispose();
        child.material?.dispose();
      }
      visual.add(model);
      grp.userData.groundModelPath = modelPath;
      grp.userData.groundModelFailed = false;
    }, 'item largado no chão');
  }

  const glowColor = gi.kind === 'gold' ? 0xffc640 : 0x8ce08c;
  const glowMat = new T.MeshStandardMaterial({
    color: new T.Color(glowColor), emissive: new T.Color(glowColor),
    emissiveIntensity: 0.7, transparent: true, opacity: 0.30, depthWrite: false
  });
  const glow = new T.Mesh(new T.CircleGeometry(0.40, 20), glowMat);
  glow.rotation.x = -Math.PI / 2;
  glow.position.set(0, 0.004, 0);
  grp.add(glow);

  return grp;
}

function _updateGroundItemDropAnimations3D(now){
  if(!g3 || !g3.groundItemMeshes) return;
  for(const grp of Object.values(g3.groundItemMeshes)){
    const anim = grp?.userData?.dropAnimation;
    const visual = grp?.userData?.dropVisual;
    if(!anim || !visual) continue;
    const progress = Math.max(0, Math.min(1, (now - anim.startedAt) / anim.duration));
    if(progress >= 1){
      visual.position.set(0, 0, 0);
      visual.rotation.set(0, anim.finalAngle, 0);
      delete grp.userData.dropAnimation;
      continue;
    }
    const flightProgress = Math.min(1, progress / 0.78);
    const easedFlight = flightProgress * flightProgress * (3 - 2 * flightProgress);
    visual.position.x = anim.fromX * (1 - easedFlight);
    visual.position.z = anim.fromZ * (1 - easedFlight);
    if(progress < 0.78){
      // Arco curto do ponto de origem até o quadrado de queda.
      visual.position.y = 0.06 + 0.48 * Math.sin(flightProgress * Math.PI);
    } else {
      const bounceProgress = (progress - 0.78) / 0.22;
      visual.position.y = 0.10 * Math.abs(Math.sin(bounceProgress * Math.PI * 2))
        * (1 - bounceProgress);
    }
    visual.rotation.y = anim.finalAngle + (1 - progress) * Math.PI * 3;
  }
}

// ═══════════════════════════════════════════════════════════════════════════
// MOVIMENTO ANIMADO DO PEÃO (3D) — segue o caminho do pathfinding, casa por
// casa, com fases levantar/avançar/pousar. Anima LOCALMENTE e só então envia
// os passos ao servidor (durante a animação não chega game_state, então o mesh
// do peão persiste). Bloqueia input enquanto anima.
// Adaptações ao código real: tile==world (casaParaMundo = identidade);
// getPeaoMesh busca no g3.entityGroup (peões taggeados com userData.pid);
// som de passo via playImpact. O consumo de fome/sede NÃO é feito aqui — é
// autoritativo no servidor (sistema unificado _consumir_recursos).
// ═══════════════════════════════════════════════════════════════════════════
const estadoMovimento = {
  emMovimento: false,
  filaCaminho: [],
  peaoAtivo:   null,
  heroi:       null,
  onConclucao: null,
};

// ── Estado de animação de movimentação dos minions (elementais/animados) ──────
// Bloqueia input da mesma forma que estadoMovimento durante animação de peão.
const estadoMininoMov = {
  emMovimento: false,
  peaoAtivo:   null,   // Three.js Group durante animação 3D
  onConclucao: null,
};

// map animadoId → {fromX,fromY,toX,toY,startTime,dur,onDone} — estado de anim 2D
const _mininoAnimState = new Map();
let   _mininoAnimRafId = null;

function podeReceberInput(){
  return !estadoMovimento.emMovimento && !estadoMininoMov.emMovimento;
}

// tile (x,y) → world (x,0,z). O tabuleiro usa 1 unidade por casa (identidade).
function casaParaMundo(x, z){ return { x: x, y: 0, z: z }; }

// Mesh (Group) do peão de um jogador no entityGroup 3D (taggeado por pid).
function getPeaoMesh(pid){
  if(!g3 || !g3.entityGroup) return null;
  return g3.entityGroup.children.find(c => c.userData && c.userData.pid === pid) || null;
}

// Mesh (Group) de um minion/animado no entityGroup 3D (taggeado por animadoId).
function getAnimadoMesh(animadoId){
  if(!g3 || !g3.entityGroup) return null;
  return g3.entityGroup.children.find(c => c.userData && c.userData.animadoId === animadoId) || null;
}

// Mesh (Group) de um monstro inimigo no entityGroup 3D (taggeado por monId).
function getMonsterMesh(monId){
  if(!g3 || !g3.entityGroup) return null;
  return g3.entityGroup.children.find(c => c.userData && c.userData.monId === monId) || null;
}

// Mesh (Group) do prisioneiro no entityGroup 3D (taggeado por userData.prisoner).
function getPrisonerMesh(){
  if(!g3 || !g3.entityGroup) return null;
  return g3.entityGroup.children.find(c => c.userData && c.userData.prisoner) || null;
}

// ── Deslize fiel passo-a-passo de inimigos / servos auto-comandados ──────────
// O servidor emite `entity_step` (from→to, 1 casa) a cada STEP_ANIM_DELAY. O
// cliente interpola por TEMPO a partir de um startTime fixo, acumulando os
// waypoints conforme chegam — assim acompanha o ritmo do servidor sem acumular
// atraso. Vale p/ 2D (override de posição no render) e 3D (reposiciona o mesh +
// leve "saltinho" do peão, o mesmo efeito de movimentação dos heróis).
const _serverStepAnim = new Map();   // id -> { pts:[[x,y]...], startTime, segDur }
let   _serverStepRaf  = null;
const SERVER_STEP_DUR_MS = 150;      // duração por casa (≥ STEP_ANIM_DELAY do servidor)

function _onEntityStep(msg){
  const id = msg.id, frm = msg.from, to = msg.to;
  const ent = _serverStepAnim.get(id);
  if(ent && ent.pts.length){
    const last = ent.pts[ent.pts.length - 1];
    // Encadeia se o novo passo continua de onde parou; senão recomeça limpo.
    if(last[0]===frm[0] && last[1]===frm[1]) ent.pts.push(to);
    else _serverStepAnim.set(id, { pts:[frm, to], startTime: performance.now(), segDur: SERVER_STEP_DUR_MS });
  } else {
    _serverStepAnim.set(id, { pts:[frm, to], startTime: performance.now(), segDur: SERVER_STEP_DUR_MS });
  }
  if(!_serverStepRaf) _serverStepRaf = _scheduleVisualFrame(_tickServerStep);
  // Som de passo no pouso da casa (~85% do segmento). Heróis ('player') ficam
  // de fora: o diff de posição do game_state já cobre os peões de jogador.
  if(msg.kind !== 'player'){
    try{
      const e = _serverStepAnim.get(id);
      const pousoEm = e.startTime + (e.pts.length - 2 + 0.85) * e.segDur;
      setTimeout(() => _somPassoEm(to), Math.max(0, pousoEm - performance.now()));
    }catch(err){}
  }
}

// Passo de um peão que não é o que você está animando: só soa se a casa
// (de chegada) estiver na sua visão — um passo na névoa entregaria o monstro.
function _somPassoEm(pos){
  if(GS.isPreview || !Array.isArray(pos)) return;
  const st = GS.gameState;
  if(!st) return;
  const me = (st.players || []).find(p => String(p.id) === String(GS.myPid)) || null;
  const visao = _sfxVisaoDe(st, me);
  if(visao && !visao.has(`${pos[0]},${pos[1]}`)) return;
  tocarSomPasso({ pos });
}

// Peões de JOGADOR vistos de fora: o servidor não manda entity_step no
// movimento comum — o peão só muda de casa entre dois game_state. Compara as
// posições e toca um passo por casa andada, espaçados no ritmo da animação
// (DURACAO_PASSO_MS). O seu peão no 3D já soa pela própria animação
// (_animarPasso); no 2D ele entra aqui. A mesa de teste do editor move os
// heróis-teste com a animação 3D local, então fica de fora (tocaria dobrado).
let _passosPosAnt = new Map();          // pid -> [x,y]
const _passosProxT = new Map();         // pid -> performance.now() do próximo passo livre
function _passosReset(){ _passosPosAnt = new Map(); _passosProxT.clear(); }
function _sonsPassosDeEstado(state){
  if(GS.isPreview || !state || state.test_mode) return;
  const atual = new Map();
  for(const p of (state.players || [])){
    if(!p || !p.alive || !Array.isArray(p.pos) || p.pos[0] < 0) continue;
    atual.set(String(p.id), p.pos);
    const ant = _passosPosAnt.get(String(p.id));
    if(!ant) continue;
    if(String(p.id) === String(GS.myPid) && mode3D) continue;
    const d = Math.max(Math.abs(p.pos[0] - ant[0]), Math.abs(p.pos[1] - ant[1]));
    if(d < 1 || d > 4) continue;          // 0 = parado; >4 = teleporte/reentrada
    const agora = performance.now();
    let t = Math.max(agora, _passosProxT.get(String(p.id)) || 0);
    for(let i = 1; i <= d; i++){
      const casa = [ant[0] + Math.round((p.pos[0] - ant[0]) * i / d),
                    ant[1] + Math.round((p.pos[1] - ant[1]) * i / d)];
      setTimeout(() => _somPassoEm(casa), t - agora);
      t += DURACAO_PASSO_MS;
    }
    _passosProxT.set(String(p.id), t);
  }
  _passosPosAnt = atual;
}

// Posição interpolada atual de uma entidade em deslize (ou null se não há).
// Retorna {x, y, hop} — hop∈[0,1] para o saltinho 3D.
function _serverStepPos(id){
  const ent = _serverStepAnim.get(id);
  if(!ent) return null;
  const segs = ent.pts.length - 1;
  const f = (performance.now() - ent.startTime) / ent.segDur;
  if(f >= segs){
    const p = ent.pts[segs];
    return { x:p[0], y:p[1], hop:0 };
  }
  const si = Math.floor(f), st = f - si, e = easeInOut(st);
  const [x0,y0] = ent.pts[si], [x1,y1] = ent.pts[si+1];
  return { x:x0+(x1-x0)*e, y:y0+(y1-y0)*e, hop:Math.sin(st*Math.PI) };
}

function _movementFacingFromPath(pathPts, fraction){
  if(!pathPts || pathPts.length < 2) return null;
  const segs = pathPts.length - 1;
  const f = Math.max(0, Math.min(segs - 1e-6, Number(fraction) || 0));
  const i = Math.min(Math.floor(f), segs - 1);
  const a = pathPts[i], b = pathPts[i + 1];
  const dx = Math.sign(b[0] - a[0]), dy = Math.sign(b[1] - a[1]);
  return (dx || dy) ? [dx, dy] : null;
}

function _serverStepFacing(id){
  const ent = _serverStepAnim.get(id);
  if(!ent) return null;
  return _movementFacingFromPath(ent.pts,
    (performance.now() - ent.startTime) / ent.segDur);
}

function _tickServerStep(){
  let any = false;
  for(const [id, ent] of _serverStepAnim){
    const segs = ent.pts.length - 1;
    const f = (performance.now() - ent.startTime) / ent.segDur;
    if(f >= segs){
      // Concluiu todos os waypoints recebidos: restaura o y do peão 3D e descarta.
      const mesh = getMonsterMesh(id) || getAnimadoMesh(id);
      if(mesh && mesh.userData._stepBaseY !== undefined){
        mesh.position.y = mesh.userData._stepBaseY;
        delete mesh.userData._stepBaseY;
      }
      _serverStepAnim.delete(id);
    } else any = true;
  }
  if(GS.gameState) renderMap(GS.gameState);
  _serverStepRaf = any ? _scheduleVisualFrame(_tickServerStep) : null;
}

// ── Animação 2D de minion ao longo de um caminho (lerp contínuo) ────────────
// Anima 2D contínuo ao longo de um caminho (pts = tiles absolutos, com origem).
// A duração escala com o nº de passos para manter ~DURACAO_PASSO_MS por casa.
function _startMininoAnimCaminho2D(animadoId, pts, onDone){
  _mininoAnimState.set(animadoId, {
    pathPts: pts,
    startTime: performance.now(),
    dur: DURACAO_PASSO_MS * Math.max(1, pts.length - 1),
    onDone,
  });
  if(!_mininoAnimRafId) _tickMininoAnim2D();
}

function _tickMininoAnim2D(){
  const now = performance.now();
  let anyActive = false;
  const done = [];
  for(const [id, anim] of _mininoAnimState){
    const t = (now - anim.startTime) / anim.dur;
    if(t >= 1) done.push(id);
    else anyActive = true;
  }
  if(GS.gameState) renderMap(GS.gameState);
  for(const id of done){
    const anim = _mininoAnimState.get(id);
    _mininoAnimState.delete(id);
    if(anim && anim.onDone) anim.onDone();
  }
  if(anyActive){
    _mininoAnimRafId = _scheduleVisualFrame(_tickMininoAnim2D);
  } else {
    _mininoAnimRafId = null;
  }
}

// Anima um minion ao longo de um CAMINHO inteiro (igual ao herói): o 3D faz
// lift/glide/land por casa via _animarPasso; o 2D interpola contínuo pelos
// segmentos. Os passos vão ao servidor já no início (mesmo padrão do herói),
// para a posição autoritativa e a névoa atualizarem em paralelo à animação.
function _animarEEnviarMoverCaminhoMinino(animado, passos){
  if(estadoMininoMov.emMovimento) return;
  if(!passos || !passos.length) return;
  estadoMininoMov.emMovimento = true;

  // Tiles absolutos do caminho (inclui a origem) para a animação contínua.
  const pts = [[animado.pos[0], animado.pos[1]]];
  let cx = animado.pos[0], cy = animado.pos[1];
  for(const [dx,dy] of passos){ cx+=dx; cy+=dy; pts.push([cx,cy]); }

  // Envia todos os passos ao servidor já (ele valida/decrementa cada um).
  for(const [dx,dy] of passos) GS.moverAnimado(animado.id, dx, dy);

  const onDone = () => {
    estadoMininoMov.emMovimento = false;
    estadoMininoMov.peaoAtivo   = null;
    // Os estados autoritativos chegam enquanto o renderer está congelado para
    // não disputar a animação. Esta renderização final aplica a última
    // posição e o último facing ao modelo GLB.
    if(GS.gameState){
      if(mode3D && g3) renderMap3D(GS.gameState);
      else renderMap(GS.gameState);
    }
  };

  if(mode3D && g3){
    const peao = getAnimadoMesh(animado.id);
    if(peao){
      estadoMininoMov.peaoAtivo = peao;
      _animarCaminhoPeao3D(peao, pts.slice(1), onDone, pts[0]);   // anima casa a casa
      return;
    }
    // mesh não encontrado (fora da visão) — passos já enviados; nada a animar.
    onDone();
    return;
  }

  // Modo 2D — interpola contínuo ao longo do caminho.
  _startMininoAnimCaminho2D(animado.id, pts, onDone);
}

// Move o prisioneiro liberto ao longo de um CAMINHO — igual ao herói/minion:
// 3D faz lift/glide/land por casa via _animarPasso (com o som de peão); o 2D
// interpola contínuo. Os passos vão ao servidor já no início (ele valida/decrementa).
function _animarEEnviarMoverPrisioneiroCaminho(pris, passos){
  if(estadoMininoMov.emMovimento) return;
  if(!pris || !passos || !passos.length) return;
  estadoMininoMov.emMovimento = true;

  const pts = [[pris.pos[0], pris.pos[1]]];
  let cx = pris.pos[0], cy = pris.pos[1];
  for(const [dx,dy] of passos){ cx+=dx; cy+=dy; pts.push([cx,cy]); }

  for(const [dx,dy] of passos) GS.moverPrisioneiro(dx, dy);

  const onDone = () => {
    estadoMininoMov.emMovimento = false;
    estadoMininoMov.peaoAtivo   = null;
    if(GS.gameState){ if(mode3D && g3) renderMap3D(GS.gameState); else renderMap(GS.gameState); }
  };

  if(mode3D && g3){
    const peao = getPrisonerMesh();
    if(peao){
      estadoMininoMov.peaoAtivo = peao;
      _animarCaminhoPeao3D(peao, pts.slice(1), onDone);   // anima casa a casa (+ som)
      return;
    }
    onDone();   // mesh fora da visão — passos já enviados
    return;
  }
  // Modo 2D — interpola contínuo ao longo do caminho.
  _startMininoAnimCaminho2D('prisoner', pts, onDone);
}

// Sequência 3D: anima o peão casa a casa pelo caminho (tiles absolutos).
function _animarCaminhoPeao3D(peao, tilesAbs, onDone, startPos){
  let i = 0;
  const gridX = Number(peao.userData.gridX);
  const gridY = Number(peao.userData.gridY);
  let previous = startPos ? [startPos[0], startPos[1]] : [
    Number.isFinite(gridX) ? gridX : (tilesAbs[0] ? tilesAbs[0][0] : 0),
    Number.isFinite(gridY) ? gridY : (tilesAbs[0] ? tilesAbs[0][1] : 0),
  ];
  const passo = () => {
    if(i >= tilesAbs.length){ if(onDone) onDone(); return; }
    const [tx,ty] = tilesAbs[i++];
    const facing = [Math.sign(tx - previous[0]), Math.sign(ty - previous[1])];
    if(facing[0] || facing[1]) _setMonsterMeshFacing3D(peao, facing);
    previous = [tx, ty];
    _animarPasso(peao, {x: tx, z: ty}, passo);
  };
  passo();
}

// Som de peão de plástico oco batendo na madeira — Web Audio puro, 3 camadas
// (tom do plástico ~280Hz + ressonância grave da madeira + clique de superfície),
// com leve variação aleatória e compressor para evitar distorção. Reusa o
// AudioContext existente (getAudioContext).
// Ganho de saída DEPOIS do compressor: subir as camadas antes dele seria
// esmagado pelo próprio compressor. Medido em 2026-09-24 (pico no canal): o
// passo saía a 0,05, abaixo até do clique de botão (0,16) e encoberto pelo
// loop grave do ambiente (mesma faixa, 80–280 Hz). ×6 ≈ +15,5 dB → pico ~0,29,
// entre o clique e a porta (0,39); o golpe fica em 0,69.
const PASSO_GANHO_SAIDA = 6;
const PASSO_INTERVALO_MIN_S = 0.04;   // vários peões pousando juntos = 1 batida
let _passoUltimoT = -1;
// opts.pos: casa de quem pisou — dá panorâmica pela tela (sem pos = centro).
function tocarSomPasso(opts = {}){
  const ctx = getAudioContext();
  if(!ctx || ctx.state !== 'running') return;
  if(ctx.currentTime - _passoUltimoT < PASSO_INTERVALO_MIN_S) return;
  _passoUltimoT = ctx.currentTime;
  try{
    const now = ctx.currentTime;
    const variacao = 0.85 + Math.random() * 0.30;

    // Compressor final — todas as camadas passam por ele antes da saída.
    const comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -18;
    comp.ratio.value     = 6;
    comp.attack.value    = 0.001;
    comp.release.value   = 0.08;
    const saida = ctx.createGain();
    saida.gain.value = PASSO_GANHO_SAIDA;
    comp.connect(saida);
    let fim = saida;
    if(Array.isArray(opts.pos) && ctx.createStereoPanner){
      const pan = ctx.createStereoPanner();
      pan.pan.value = _sfxPan(opts.pos);
      saida.connect(pan); fim = pan;
    }
    fim.connect(_stepsBus());

    // CAMADA 1 — Tom principal do plástico (ruído filtrado, bandpass ~280Hz)
    const bufSize = Math.floor(ctx.sampleRate * 0.06);
    const buffer  = ctx.createBuffer(1, bufSize, ctx.sampleRate);
    const data    = buffer.getChannelData(0);
    for(let i = 0; i < bufSize; i++){
      const t = i / bufSize;
      data[i] = (Math.random() * 2 - 1) * Math.pow(1 - t, 3);   // ataque seco, decay
    }
    const ruido = ctx.createBufferSource();
    ruido.buffer = buffer;
    const filtro = ctx.createBiquadFilter();
    filtro.type = 'bandpass'; filtro.frequency.value = 280 * variacao; filtro.Q.value = 1.8;
    const ganho1 = ctx.createGain();
    ganho1.gain.setValueAtTime(0.55 * variacao, now);
    ganho1.gain.exponentialRampToValueAtTime(0.001, now + 0.07);
    ruido.connect(filtro); filtro.connect(ganho1); ganho1.connect(comp);
    ruido.start(now);

    // CAMADA 2 — Ressonância grave da madeira (sine 140→80Hz)
    const osc = ctx.createOscillator();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(140 * variacao, now);
    osc.frequency.exponentialRampToValueAtTime(80, now + 0.08);
    const ganho2 = ctx.createGain();
    ganho2.gain.setValueAtTime(0.20 * variacao, now);
    ganho2.gain.exponentialRampToValueAtTime(0.001, now + 0.10);
    osc.connect(ganho2); ganho2.connect(comp);
    osc.start(now); osc.stop(now + 0.10);

    // CAMADA 3 — Clique de superfície (transiente agudo, highpass 2400Hz)
    const bufClique  = ctx.createBuffer(1, Math.floor(ctx.sampleRate * 0.012), ctx.sampleRate);
    const dataClique = bufClique.getChannelData(0);
    for(let i = 0; i < dataClique.length; i++){
      const t = i / dataClique.length;
      dataClique[i] = (Math.random() * 2 - 1) * Math.pow(1 - t, 5);
    }
    const clique = ctx.createBufferSource();
    clique.buffer = bufClique;
    const filtroClique = ctx.createBiquadFilter();
    filtroClique.type = 'highpass'; filtroClique.frequency.value = 2400;
    const ganhoClique = ctx.createGain();
    ganhoClique.gain.setValueAtTime(0.30 * variacao, now);
    ganhoClique.gain.exponentialRampToValueAtTime(0.001, now + 0.015);
    clique.connect(filtroClique); filtroClique.connect(ganhoClique); ganhoClique.connect(comp);
    clique.start(now);
  } catch(e){}
}

function easeOut(t){ return 1 - Math.pow(1 - t, 2); }
function easeIn(t){ return t * t; }
function easeInOut(t){ return t < 0.5 ? 2*t*t : 1 - Math.pow(-2*t+2, 2)/2; }

const DURACAO_PASSO_MS = 250;   // 0.25s por casa
const ALTURA_ELEVACAO  = 0.4;   // unidades Three.js

function moverPeaoAoCaminho(peao, heroi, caminho, onConclucao){
  if(estadoMovimento.emMovimento) return;
  if(!peao || !caminho || caminho.length === 0){ if(onConclucao) onConclucao(); return; }
  estadoMovimento.emMovimento = true;
  estadoMovimento.filaCaminho = [...caminho];
  estadoMovimento.peaoAtivo   = peao;
  estadoMovimento.heroi       = heroi;
  estadoMovimento.onConclucao = onConclucao || null;
  // O estado autoritativo ainda está na casa inicial enquanto os passos são
  // animados localmente. Guardar a casa visual atual permite calcular a
  // transição de altura quando o caminho entra ou sai de uma ponte.
  peao.userData._moveGridPos = [heroi.pos[0], heroi.pos[1]];
  iniciarSeguimentoCamera(peao);              // câmera passa a seguir o peão
  _executarProximoPasso();
}

function _executarProximoPasso(){
  if(estadoMovimento.filaCaminho.length === 0){
    estadoMovimento.emMovimento = false;        // libera input ANTES do callback
    encerrarSeguimentoCamera();                 // re-sincroniza OrbitControls
    if(estadoMovimento.peaoAtivo) delete estadoMovimento.peaoAtivo.userData._moveGridPos;
    const cb = estadoMovimento.onConclucao;
    estadoMovimento.onConclucao = null;
    if(cb) cb();
    return;
  }
  const destino = estadoMovimento.filaCaminho.shift();
  _animarPasso(estadoMovimento.peaoAtivo, destino, () => _executarProximoPasso());
}

function _animarPasso(peao, destino, onPasso){
  if (destino.rotY !== undefined) peao.rotation.y = destino.rotY;   // vira primeiro, antes de andar
  const inicio = { x: peao.position.x, y: peao.position.y, z: peao.position.z };
  const destinoWorld = casaParaMundo(destino.x, destino.z);
  const bridgeState = GS.gameState;
  const origemGrid = peao.userData._moveGridPos || [peao.userData.gridX, peao.userData.gridY];
  const origemPonteY = Array.isArray(origemGrid) && Number.isFinite(origemGrid[0])
    ? baseSuperficiePonte3D(bridgeState, origemGrid[0], origemGrid[1]) : null;
  const destinoPonteY = baseSuperficiePonte3D(bridgeState, destino.x, destino.z);
  const transitaPonte = origemPonteY !== null || destinoPonteY !== null;
  const inicioSuperficieY = origemPonteY !== null ? origemPonteY : inicio.y;
  const fimSuperficieY = destinoPonteY !== null
    ? destinoPonteY
    : (origemPonteY !== null
      ? topoTerreno3D(bridgeState, destino.x, destino.z) - 0.22
      : inicio.y);
  if(transitaPonte) peao.position.y = inicioSuperficieY;
  let startTime = null;
  function tick(timestamp){
    if(startTime === null) startTime = timestamp;
    const progress = Math.min((timestamp - startTime) / DURACAO_PASSO_MS, 1);

    if(progress < 0.3){
      // FASE 1 — levanta
      const t = progress / 0.3, eased = easeOut(t);
      peao.position.y = inicioSuperficieY + ALTURA_ELEVACAO * eased;
      peao.rotation.x = -0.08 * eased;
    } else if(progress < 0.7){
      // FASE 2 — avança no ar
      const t = (progress - 0.3) / 0.4, eased = easeInOut(t);
      peao.position.y = inicioSuperficieY + (fimSuperficieY - inicioSuperficieY) * eased + ALTURA_ELEVACAO;
      peao.position.x = inicio.x + (destinoWorld.x - inicio.x) * eased;
      peao.position.z = inicio.z + (destinoWorld.z - inicio.z) * eased;
      peao.rotation.x = -0.08;
    } else {
      // FASE 3 — pousa
      const t = (progress - 0.7) / 0.3, eased = easeIn(t);
      peao.position.y = fimSuperficieY + ALTURA_ELEVACAO * (1 - eased);
      peao.position.x = destinoWorld.x;
      peao.position.z = destinoWorld.z;
      peao.rotation.x = -0.08 * (1 - t);
      if(progress > 0.85 && progress < 0.95){
        const impacto = Math.sin((progress - 0.85) / 0.10 * Math.PI);
        peao.scale.y = 1.0 - (0.12 * impacto);
        peao.scale.x = 1.0 + (0.06 * impacto);
        peao.scale.z = 1.0 + (0.06 * impacto);
      } else {
        peao.scale.set(1, 1, 1);
      }
      if(progress >= 0.88 && !peao._somTocado){
        peao._somTocado = true;
        tocarSomPasso();
      }
    }

    if(progress < 1){
      // O movimento compartilha o mesmo agendador visual dos efeitos de
      // combate/magia e do lançamento de dados.
      _scheduleVisualFrame(tick);
    } else {
      peao.position.set(destinoWorld.x, fimSuperficieY, destinoWorld.z);
      peao.userData._moveGridPos = [destino.x, destino.z];
      peao.rotation.set(0, peao.rotation.y, 0);
      peao.scale.set(1, 1, 1);
      peao._somTocado = false;
      onPasso();
    }
  }
  _scheduleVisualFrame(tick);
}

// ═══════════════════════════════════════════════════════════════════════════
// CÂMERA QUE SEGUE O PEÃO (3D) — durante o movimento desliza suavemente (lerp)
// para acompanhar o peão, PRESERVANDO o ângulo isométrico atual (captura o
// offset câmera→alvo e o translada). OrbitControls é desativado durante o
// seguimento e re-sincronizado ao final (sem cortes). Câmera ortográfica → não
// há "zoom por distância"; mantém-se o offset/zoom atuais.
// ═══════════════════════════════════════════════════════════════════════════
const configCamera = {
  seguindoPeao: false,
  velocidade:   0.08,                 // 0..1 — suavidade do lerp
  offset:       new THREE.Vector3(),  // offset câmera→alvo (preserva isométrico)
  alvoAtual:    new THREE.Vector3(),  // ponto observado (lerp suave)
};

function iniciarSeguimentoCamera(peao){
  if(!g3 || !g3.camera || !g3.controls) return;
  configCamera.seguindoPeao = true;
  g3.controls.enabled = false;                                   // evita conflito
  configCamera.offset.copy(g3.camera.position).sub(g3.controls.target);
  configCamera.alvoAtual.copy(g3.controls.target);
}

function atualizarCamera(){
  if(!configCamera.seguindoPeao || !g3 || !g3.camera) return;
  if(!estadoMovimento.emMovimento || !estadoMovimento.peaoAtivo) return;
  const peao = estadoMovimento.peaoAtivo;
  // Alvo desliza para a base do peão (y=0 → câmera não balança com o pulo).
  const destino = new THREE.Vector3(peao.position.x, 0, peao.position.z);
  configCamera.alvoAtual.lerp(destino, configCamera.velocidade);
  g3.camera.position.copy(configCamera.alvoAtual).add(configCamera.offset);
  g3.camera.lookAt(configCamera.alvoAtual);
}

// Reenquadra após cada passo recebido do controle, preservando ângulo e zoom.
// Diferente do seguimento animado acima, aqui o servidor já confirmou um passo
// discreto e basta transportar câmera e alvo para a nova casa.
function centralizarCamera3DNoPeao(pos){
  if(!g3?.camera || !g3?.controls || !Array.isArray(pos)) return;
  const world = casaParaMundo(pos[0], pos[1]);
  const alvo = new THREE.Vector3(world.x, 0, world.z);
  const offset = g3.camera.position.clone().sub(g3.controls.target);
  g3.controls.target.copy(alvo);
  g3.camera.position.copy(alvo).add(offset);
  g3.camera.lookAt(alvo);
  g3.controls.update();
}

function encerrarSeguimentoCamera(){
  if(!g3 || !g3.controls) return;
  configCamera.seguindoPeao = false;
  // Re-sincroniza o OrbitControls com a posição final (sem corte) e reativa.
  if(estadoMovimento.peaoAtivo){
    const p = estadoMovimento.peaoAtivo.position;
    g3.controls.target.set(p.x, 0, p.z);
  }
  g3.controls.update();          // re-deriva o estado interno (sem snap)
  g3.controls.enabled = true;
}

// Libera os recursos de GPU de um peão/sprite removido do entityGroup.
// THREE.js NÃO libera geometria/material/textura ao remover da cena — sem este
// descarte, cada game_state vazava dezenas de buffers (lentidão progressiva).
function _disposeEntityTree(root){
  for(const e of ((root.userData && root.userData._sceneMats) || [])) e.mat.dispose();   // clones do flash (Material.dispose não toca texturas)
  root.traverse(o => {
    // Clones GLB compartilham geometria/material/texturas com o template em
    // cache (_heroGLBCache) — descartar aqui quebraria os próximos clones.
    if(o.userData && o.userData.isGLB){
      // Só o clone da cena de combate (_sceneOwned) é nosso: pode ficar preso à
      // malha se a arte tardia apagou _sceneMats sem uma nova pose re-clonar.
      for(const m of (Array.isArray(o.material) ? o.material : [o.material]))
        if(m && m.userData && m.userData._sceneOwned) m.dispose();
      return;
    }
    if(!(o.isMesh || o.isSprite)) return;
    // Sprites no r128 compartilham UMA geometria global — nunca descartá-la.
    if(o.isMesh && o.geometry) o.geometry.dispose();
    const mats = Array.isArray(o.material) ? o.material : [o.material];
    for(const m of mats){
      if(!m) continue;
      // Só descarta texturas EXCLUSIVAS do peão (placa de nome, sprite de
      // armadilha). Texturas em cache (_pawnTexCache, madeira da base, etc.)
      // são compartilhadas entre todos os peões e ficam vivas.
      for(const k of ['map','bumpMap','normalMap','emissiveMap','alphaMap']){
        if(m[k] && m[k]._owned) m[k].dispose();
      }
      m.dispose();
    }
  });
}

// ── Helpers para miniaturas extrudadas de decorações (PNG → 3D) ───────────────
function _disposeDecorMesh(obj){
  if(obj && obj.userData && obj.userData.animationMixer){
    const mixer = obj.userData.animationMixer;
    mixer.stopAllAction();
    if(mixer.uncacheRoot) mixer.uncacheRoot(obj);
  }
  obj.traverse(o => {
    // Instâncias GLB compartilham os recursos com o template em cache.
    if (o.userData && o.userData.isGLB) return;
    if (o.geometry) o.geometry.dispose();
    if (o.material) {
      const mats = Array.isArray(o.material) ? o.material : [o.material];
      // _shared: textura cacheada (ex.: chão via _pawnTexCache) reusada por outras
      // decorações — não descartar aqui, senão some das demais.
      mats.forEach(mm => { if (mm.map && !mm.map._shared) mm.map.dispose(); mm.dispose(); });
    }
  });
}
const _objImg3D = {};
// Motivo da última falha de cada GLB (caminho → texto curto). O cache só guarda
// 'erro'; a prévia do editor precisa dizer ao autor POR QUE falhou. O servidor
// não responde a HEAD (a lib websockets só aceita GET), então sondar por HTTP
// não é opção — o motivo tem de vir do próprio carregador.
const _glbErroMsg = {};
// Tentativas extras por arquivo. Um GLB pedido sob demanda cai com frequência
// num socket que o navegador guardou no pool mas o servidor já fechou: o XHR
// morre na hora, com status 0 e sem resposta. Abrir conexão nova resolve, então
// vale insistir antes de marcar 'erro' — que é definitivo e some com o objeto
// até a página ser recarregada.
const GLB_TENTATIVAS = 3;

// ── Auto-recuperação de arte que falhou por REDE ─────────────────────────────
// Marcar um arquivo como 'erro' é DEFINITIVO: ele some (ou vira miniatura
// genérica) até a página ser recarregada. Isso está certo para 404, mas é ruim
// para falha de conexão — que acontece em rajada quando o mapa inteiro é
// revelado de uma vez (teste do editor / visão do Mestre) e pede dezenas de
// arquivos ao mesmo tempo. Aqui a falha de rede agenda uma nova tentativa:
// limpa a marca de erro e redesenha, para o modelo real substituir o fallback.
const _ASSET_RETRY_MS      = 2000;
const _ASSET_MAX_RECARGAS  = 3;
const _assetRecargas = {};     // chave -> nº de recargas já agendadas
// Muda a cada recarga: entra na assinatura da figura do monstro para forçar a
// reconstrução do peão (senão obterFig reusaria o que já está na cena).
let _arteGen = 0;

// Descobre o status HTTP de um arquivo que acabou de falhar. Existe porque o
// carregador de textura usa uma <img>, e o evento de erro dela não diz se o
// arquivo não existe (404) ou se a conexão caiu — distinção que decide entre
// insistir e desistir. Só é chamado NA FALHA, então não custa nada no caminho
// feliz. Devolve 0 quando nem a conexão foi feita.
function _statusDoArquivo(url){
  if(!window.fetch) return Promise.resolve(0);
  return fetch(url, { method: 'GET' }).then(r => r.status).catch(() => 0);
}

// Erro com status HTTP (404/403) é definitivo; sem status = falha de conexão.
function _erroDefinitivoArte(error){
  const alvo = error && error.target;
  return !!(alvo && typeof alvo.status === 'number' && alvo.status > 0);
}

function _agendarRecargaArte(chave, error, limpar){
  if(_erroDefinitivoArte(error)) return;
  const n = _assetRecargas[chave] || 0;
  if(n >= _ASSET_MAX_RECARGAS) return;
  _assetRecargas[chave] = n + 1;
  setTimeout(() => {
    limpar();
    _arteGen++;
    if(GS.gameState){ try { renderMap(GS.gameState); } catch(_){} }
  }, _ASSET_RETRY_MS * (n + 1));
}

// ── Fila de carregamento de arte ─────────────────────────────────────────────
// Ao entrar numa masmorra (e principalmente no teste do editor, que revela o
// mapa inteiro de uma vez) o cliente pede TODOS os modelos e texturas no mesmo
// instante. O servidor é um laço asyncio só: uma dezena de .glb de vários MB
// disputando a vez é exatamente o cenário em que pedidos morrem na rede. A fila
// mantém no máximo _ASSET_PARALELO downloads em voo; o resto espera a sua vez.
const _ASSET_PARALELO = 4;
let _assetEmVoo = 0;
const _assetFila = [];

function _enfileirarArte(iniciar){
  _assetFila.push(iniciar);
  _bombearFilaArte();
}

function _bombearFilaArte(){
  while(_assetEmVoo < _ASSET_PARALELO && _assetFila.length){
    const iniciar = _assetFila.shift();
    _assetEmVoo++;
    // `terminou` é chamado UMA vez por download (sucesso ou falha); a guarda
    // impede que um carregador distraído libere duas vagas e estoure o teto.
    let fechado = false;
    const terminou = () => {
      if(fechado) return;
      fechado = true;
      _assetEmVoo--;
      _bombearFilaArte();
    };
    try { iniciar(terminou); }
    catch(e){ console.warn('[arte] falha ao iniciar download:', e); terminou(); }
  }
}

function _glbVaiRetentar(error, restam){
  if(restam <= 0) return false;
  const alvo = error && error.target;
  // Só re-tenta falha de CONEXÃO. 404/403 não melhoram com insistência.
  return !alvo || typeof alvo.status !== 'number' || alvo.status === 0;
}
function _glbMotivo(error){
  if(!error) return t('ui.hud.erro_desconhecido');
  // O GLTFLoader entrega um ProgressEvent do XHR. String(ProgressEvent) é
  // "[object ProgressEvent]" — inútil. O que informa é o status: 0 significa
  // falha de CONEXÃO (socket morto/recusado), não resposta do servidor.
  const alvo = error.target;
  if(alvo && typeof alvo.status === 'number'){
    if(alvo.status === 0) return t('ui.diag.conexao_falhou');
    return 'HTTP ' + alvo.status + (alvo.statusText ? ' ' + alvo.statusText : '');
  }
  const m = String(error.message || error);
  return m.length > 120 ? m.slice(0, 120) + '…' : m;
}
const _decorGLBCache = {};
const _decorGLBQueue = {};

function _loadDecorGLB(T, path, cb, assetType='decoração'){
  const cached = _decorGLBCache[path];
  if (cached && cached !== 'erro') { cb(cached); return; }
  if (cached === 'erro' || !T.GLTFLoader) { cb(null); return; }
  if (_decorGLBQueue[path]) { _decorGLBQueue[path].push(cb); return; }

  _decorGLBQueue[path] = [cb];
  const tentar = (restam, liberarVaga) => {
    new T.GLTFLoader().load(
      _assetURL(path),
      gltf => {
        liberarVaga();
        const template = gltf.scene;
        // Os clips ficam no template em cache; Object3D.clone() preserva esta
        // referência e cada instância recebe seu próprio AnimationMixer.
        template.userData._gltfAnimations = gltf.animations || [];
        template.traverse(o => {
          if (o.isMesh) { o.castShadow = true; o.receiveShadow = true; }
        });
        _decorGLBCache[path] = template;
        _decorGLBQueue[path].forEach(fn => fn(template));
        delete _decorGLBQueue[path];
      },
      undefined,
      error => {
        // A retentativa reentra na FILA: sem isso ela furaria o teto de paralelismo
        // justamente quando a rede já está congestionada.
        if (_glbVaiRetentar(error, restam)) {
          liberarVaga();
          setTimeout(() => _enfileirarArte(v => tentar(restam - 1, v)), 250);
          return;
        }
        liberarVaga();
        console.warn(`[GLB] falha ao carregar ${assetType} ${path}: ${_glbMotivo(error)}`);
        _glbErroMsg[path] = _glbMotivo(error);
        _decorGLBCache[path] = 'erro';
        _decorGLBQueue[path].forEach(fn => fn(null));
        delete _decorGLBQueue[path];
        // Falha de rede: tenta de novo mais tarde — o renderMap3D reconstrói a
        // decoração com o GLB assim que a marca de erro sai do cache.
        _agendarRecargaArte('decor:' + path, error, () => { delete _decorGLBCache[path]; });
      }
    );
  };
  _enfileirarArte(liberarVaga => tentar(GLB_TENTATIVAS, liberarVaga));
}

function _buildObjetoGLB(decorId, imageName, path, wCells, hCells, facing){
  const montar = template => {
    const slot = g3 && g3.decorMeshes[decorId];
    if (!slot || slot.userData.glbPath !== path) return;
    if (!template) {
      // Mantém a arte 2D atual caso o arquivo não possa ser aberto.
      slot.userData = { isDecor: true, decorId, imageName };
      _buildObjetoMini(decorId, imageName, Math.max(wCells, hCells), facing);
      return;
    }

    const inst = template.clone();
    const animations = (template.userData && template.userData._gltfAnimations) || [];
    const animationMixer = animations.length ? new g3.T.AnimationMixer(inst) : null;
    if(animationMixer){
      for(const clip of animations) animationMixer.clipAction(clip).play();
    }
    const box = new g3.T.Box3().setFromObject(inst);
    const size = box.getSize(new g3.T.Vector3());
    const scale = Math.min(
      (wCells * 0.92) / Math.max(size.x, 1e-3),
      (hCells * 0.92) / Math.max(size.z, 1e-3)
    );
    // Centraliza o modelo e assenta sua base no piso da masmorra.
    inst.position.set(
      -(box.min.x + box.max.x) / 2,
      -box.min.y,
      -(box.min.z + box.max.z) / 2
    );
    inst.traverse(o => {
      if (!o.isMesh) return;
      o.userData.isGLB = true;
    });
    const wrap = new g3.T.Group();
    wrap.add(inst);
    wrap.scale.setScalar(scale);
    const grp = new g3.T.Group();
    grp.userData = { isDecor: true, decorId, glbPath: path, animationMixer };
    grp.add(wrap);
    grp.position.copy(slot.position);
    grp.position.y = DECOR_GLB_FLOOR_Y;
    grp.rotation.y = _facingAngleY3D(facing, undefined, imageName, path);
    grp.visible = slot.visible;
    g3.scene.remove(slot); _disposeDecorMesh(slot);
    g3.scene.add(grp);
    g3.decorMeshes[decorId] = grp;
  };
  _loadDecorGLB(g3.T, path, montar);
}

// Brasões e cortinas são decorações de parede: o GLB fica vertical, centrado na face da
// parede e com a base apoiada no piso. O PNG segue como fallback para manter a
// decoração visível enquanto o GLB carrega ou se o arquivo não estiver disponível.
function _buildWallDecorGLB(d, path){
  const montar = template => {
    const slot = g3 && g3.decorMeshes[d.id];
    if (!slot || slot.userData.wallGlbPath !== path) return;
    if (!template) {
      slot.userData = { isDecor:true, decorId:d.id, wallImage:d.image,
        wallGlbPath:'png', wallFace:(d.facing || [0,1]).join(',') };
      _buildWallDecor3D(d);
      return;
    }

    const T = g3.T, face = d.facing || [0,1];
    const vs = Array.isArray(d.vscale) ? d.vscale : [1,1];
    const inst = template.clone();
    const box = new T.Box3().setFromObject(inst);
    const size = box.getSize(new T.Vector3());
    const isCurtain = d.type === 'cortina_vermelha' || d.type === 'cortina_branca';
    const targetW = (isCurtain ? 0.96 : 0.74) * (vs[0] || 1);
    const targetH = (isCurtain ? 1.24 : 0.92) * (vs[1] || 1);
    const scaleX = targetW / Math.max(size.x, 1e-3);
    const scaleY = targetH / Math.max(size.y, 1e-3);
    const scaleZ = scaleX;
    // Centraliza horizontalmente e remove a folga inferior do modelo original.
    inst.position.set(
      -(box.min.x + box.max.x) / 2,
      -box.min.y,
      -(box.min.z + box.max.z) / 2
    );
    inst.traverse(o => { if (o.isMesh) o.userData.isGLB = true; });
    const wrap = new T.Group();
    wrap.add(inst);
    wrap.scale.set(scaleX, scaleY, scaleZ);

    const grp = new T.Group();
    grp.userData = { isDecor:true, decorId:d.id, wallImage:d.image,
      wallGlbPath:path, wallFace:face.join(','), wallScale:vs.join(',') };
    const WALL_DECOR_GLB_SURFACE = 0.575;
    // O brasão é uma placa suspensa: sua base acompanha a altura do decal PNG
    // (em vez de começar no piso), deixando o topo dentro do terço superior da
    // parede de 1,75 unidades.
    const wallBaseY = d.type === 'brasao_leao' ? 0.58 : DECOR_GLB_FLOOR_Y;
    grp.position.set(
      d.pos[0] + face[0] * WALL_DECOR_GLB_SURFACE,
      wallBaseY,
      d.pos[1] + face[1] * WALL_DECOR_GLB_SURFACE
    );
    grp.rotation.y = _wallDecorRotation(face);
    grp.add(wrap);
    grp.visible = slot.visible;
    g3.scene.remove(slot); _disposeDecorMesh(slot);
    g3.scene.add(grp); g3.decorMeshes[d.id] = grp;
  };
  _loadDecorGLB(g3.T, path, montar);
}

function _buildObjetoMini(decorId, imageName, cells, facing){
  const make = (img) => {
    const slot = g3 && g3.decorMeshes[decorId];
    // a decoração pode ter sido removida/trocada enquanto carregava
    if (!slot || slot.userData.imageName !== imageName) return;
    // g3.T = alias do THREE (esta função é de módulo; o `T` local só existe
    // dentro de renderMap3D, então usamos g3.T para não dar ReferenceError).
    // DECOR_MINI_ESCALA: tamanho da miniatura por casa de footprint (ajuste aqui
    // para deixar as miniaturas maiores/menores no 3D).
    const grp = window.Miniatura3D.build(g3.T, { image: img, tileSize: Math.max(1, cells) * DECOR_MINI_ESCALA });
    grp.userData = { isDecor: true, decorId: decorId, imageName: imageName };
    grp.position.copy(slot.position);
    grp.rotation.y = _facingAngleY3D(facing, undefined, imageName);   // giro 90° aplicado já na construção assíncrona
    grp.visible = slot.visible;
    g3.scene.remove(slot); _disposeDecorMesh(slot);
    g3.scene.add(grp);
    g3.decorMeshes[decorId] = grp;
  };
  let img = _objImg3D[imageName];
  if (img) {
    if (img.complete && img.naturalWidth) make(img);
    // addEventListener (não `onload=`): várias decorações com o MESMO PNG ainda
    // carregando registram callbacks distintos sem sobrescrever umas às outras.
    else img.addEventListener('load', () => make(img), { once: true });
    return;
  }
  img = new Image();
  _objImg3D[imageName] = img;
  img.addEventListener('load', () => make(img), { once: true });
  img.src = _assetURL(`assets/objetos/${imageName}`);
  // Imagem em cache do navegador pode já estar `complete` ao definir o src,
  // sem disparar 'load' — então constrói na hora nesse caso.
  if (img.complete && img.naturalWidth) make(img);
}

// ── Decais de parede (PNG vertical, sem ocupar o piso) ───────────────────────
const _wallDecorTextures = {};
function _wallDecorTexture(T, imageName, done){
  if (_wallDecorTextures[imageName]) { done(_wallDecorTextures[imageName]); return; }
  const loader = new T.TextureLoader();
  loader.load(_assetURL(`assets/objetos/${imageName}`), tex => {
    // Os três assets iniciais vieram com fundo preto opaco. Convertemos somente
    // preto absoluto/quase absoluto em alfa, preservando sombras e detalhes.
    const img = tex.image, cv = document.createElement('canvas');
    cv.width = img.width; cv.height = img.height;
    const c = cv.getContext('2d', {willReadFrequently:true}); c.drawImage(img, 0, 0);
    const data = c.getImageData(0, 0, cv.width, cv.height);
    for(let i=0; i<data.data.length; i+=4){
      const hi = Math.max(data.data[i], data.data[i+1], data.data[i+2]);
      if(hi <= 10) data.data[i+3] = 0;
      else if(hi < 32) data.data[i+3] = Math.round(data.data[i+3] * (hi - 10) / 22);
    }
    c.putImageData(data, 0, 0);
    const out = new T.CanvasTexture(cv);
    if(T.SRGBColorSpace) out.colorSpace=T.SRGBColorSpace;
    else if(T.sRGBEncoding) out.encoding=T.sRGBEncoding;
    out.needsUpdate = true; out._shared = true; _wallDecorTextures[imageName] = out; done(out);
  }, undefined, () => done(null));
}

function _wallDecorRotation(face){
  if(face[0] === 1) return Math.PI/2;
  if(face[0] === -1) return -Math.PI/2;
  return face[1] === -1 ? Math.PI : 0;
}

function _buildWallDecor3D(d){
  const slot = g3 && g3.decorMeshes[d.id];
  if(!slot) return;
  _wallDecorTexture(g3.T, d.image, tex => {
    const current = g3 && g3.decorMeshes[d.id];
    if(!current || current !== slot || !tex) return;
    const T = g3.T, face = d.facing || [0,1];
    const vs = Array.isArray(d.vscale) ? d.vscale : [1,1];
    const isCurtain = d.type === 'cortina_vermelha' || d.type === 'cortina_branca';
    const h = (isCurtain ? 1.55 : 0.92) * (vs[1] || 1);
    const w = (isCurtain ? 0.96 : 0.74) * (vs[0] || 1);
    const mat = new T.MeshBasicMaterial({map:tex, transparent:true, alphaTest:0.02,
      depthWrite:false, side:T.DoubleSide});
    const mesh = new T.Mesh(new T.PlaneGeometry(w, h), mat);
    mesh.userData = {isDecor:true, decorId:d.id, wallImage:d.image, wallFace:face.join(','), wallScale:vs.join(',')};
    mesh.rotation.y = _wallDecorRotation(face);
    // A parede 3D ocupa ±0,5 da casa. O valor antigo (0,451) deixava o
    // decal parcialmente dentro do bloco; como o depthTest continua ativo,
    // brasões e cortinas desapareciam atrás da própria parede. Coloque a arte
    // alguns milímetros para o lado jogável da face, evitando z-fighting.
    const WALL_DECOR_SURFACE = 0.516;
    mesh.position.set(d.pos[0] + face[0]*WALL_DECOR_SURFACE, isCurtain ? 0.84 : 1.05,
      d.pos[1] + face[1]*WALL_DECOR_SURFACE);
    mesh.visible = slot.visible;
    g3.scene.remove(slot); _disposeDecorMesh(slot);
    g3.scene.add(mesh); g3.decorMeshes[d.id] = mesh;
  });
}

// ── Casas do tabuleiro em InstancedMesh ──────────────────────────────────────
// Um mesh por casa dava 1.760 draw calls num mapa 44x40. Como o custo por draw
// call e ~3 us de CPU, isso sozinho valia ~5 ms/quadro -- e so aparecia CONFORME
// A NEVOA ABRIA, porque cada casa revelada acrescentava um objeto desenhado.
// Era essa a "lentidao ao longo do jogo": com o mapa todo explorado o quadro
// ia de 1,9 ms (186 draw calls) para 10,8 ms (3.582).
//
// As casas nunca se movem e so existem 30 combinacoes de (geometria, material)
// para 1.760 casas -- entao instanciar leva 1.760 draw calls para ~38.
//
// O mesh por casa CONTINUA existindo, fora da cena, como procuracao: e nele que
// o resto do codigo escreve `visible` (nevoa) e `material` (passagem secreta), e
// e ele o alvo do raycast do clique. Assim nada mais precisou mudar: o rebuild
// so le esse estado e o traduz em instancias.
const TILE_INST_MIN = 4;      // grupo menor que isto nao compensa instanciar

function _prepararTileProxy(mesh){
  // Fora da cena o matrixWorld nao e atualizado por ninguem; o raycast e as
  // instancias dependem dele, entao fixamos aqui (a casa nunca se move).
  mesh.updateMatrix();
  mesh.matrixWorld.copy(mesh.matrix);
  mesh.matrixWorldNeedsUpdate = false;
  mesh.matrixAutoUpdate = false;
}

// Marcado por quem muda `visible` ou `material` de uma casa. Sem isto o rebuild
// (9,3 ms num mapa 44x40) rodaria a CADA game_state, e a nevoa so muda quando
// alguem anda.
let _tilesDirty = true;
function _rebuildTileInstances(){
  if(!g3 || !g3.tileMeshes) return;
  if(!_tilesDirty) return;
  _tilesDirty = false;
  const T = g3.T, scene = g3.scene;
  const pool = g3._tileInstPool || (g3._tileInstPool = new Map());
  const grupos = new Map();
  for(const k in g3.tileMeshes){
    const m = g3.tileMeshes[k];
    if(!m || !m.visible || !m.geometry) continue;
    const mat = Array.isArray(m.material) ? m.material[0] : m.material;
    if(!mat) continue;
    // As flags de sombra entram na chave: chao e parede se comportam diferente
    // no shadow pass e nao podem cair na mesma instancia.
    const chave = m.geometry.uuid + '|' + mat.uuid + '|' + (m.castShadow?1:0) + (m.receiveShadow?1:0);
    let g = grupos.get(chave);
    if(!g){ g = { geo:m.geometry, mat, cast:m.castShadow, receive:m.receiveShadow, itens:[] };
            grupos.set(chave, g); }
    g.itens.push(m);
  }
  const usados = new Set();
  for(const [chave, g] of grupos){
    if(g.itens.length < TILE_INST_MIN){
      // Poucos exemplares (ex.: parede de rocha, com geometria propria por casa):
      // instanciar nao pagaria, entao a propria procuracao entra na cena.
      for(const m of g.itens) if(m.parent !== scene) scene.add(m);
      continue;
    }
    for(const m of g.itens) if(m.parent === scene) scene.remove(m);
    let inst = pool.get(chave);
    if(!inst || inst.instanceMatrix.count < g.itens.length){
      if(inst){ scene.remove(inst); inst.dispose(); }
      inst = new T.InstancedMesh(g.geo, g.mat, Math.max(16, g.itens.length * 2));
      inst.instanceMatrix.setUsage(T.DynamicDrawUsage);
      // O bounding sai de UMA instancia na origem; sem isto o tabuleiro inteiro
      // seria descartado pelo frustum.
      inst.frustumCulled = false;
      inst.castShadow = g.cast; inst.receiveShadow = g.receive;
      scene.add(inst);
      pool.set(chave, inst);
    }
    for(let i = 0; i < g.itens.length; i++) inst.setMatrixAt(i, g.itens[i].matrix);
    inst.count = g.itens.length;
    inst.instanceMatrix.needsUpdate = true;
    usados.add(chave);
  }
  // Grupo que sumiu (nevoa fechou, material trocou) para de desenhar.
  for(const [chave, inst] of pool) if(!usados.has(chave)) inst.count = 0;
}

// Mesma ideia do _rebuildTileInstances, para os detalhes de parede (arcos,
// pilares, portas de madeira, rodapes). Difere em um ponto: aqui a entrada pode
// ser um Group (as pedras do arco), entao agrupa-se pelos MESHES descendentes e
// usa-se a matrixWorld ja congelada, nao a matriz local.
let _detailDirty = true;
function _rebuildDetailInstances(){
  if(!g3) return;
  if(!_detailDirty) return;
  _detailDirty = false;
  const T = g3.T, scene = g3.scene;
  const pool = g3._detailInstPool || (g3._detailInstPool = new Map());
  const grupos = new Map();
  // Duas familias com a mesma forma (chave -> lista de entradas) e o mesmo
  // comportamento (estaticas, so ligadas/desligadas pela nevoa).
  const familias = [g3.wallDetailMeshes, g3.sceneryMeshes, g3.torchStaticMeshes];
  for(const familia of familias){
   if(!familia) continue;
   for(const key in familia){
    for(const entrada of (familia[key] || [])){
      if(!entrada || !entrada.visible) continue;
      entrada.traverse(o => {
        if(!o.isMesh || !o.geometry || !o.visible) return;
        const mat = Array.isArray(o.material) ? o.material[0] : o.material;
        if(!mat) return;
        const chave = o.geometry.uuid + '|' + mat.uuid + '|' + (o.castShadow?1:0) + (o.receiveShadow?1:0);
        let g = grupos.get(chave);
        if(!g){ g = { geo:o.geometry, mat, cast:o.castShadow, receive:o.receiveShadow, itens:[] };
                grupos.set(chave, g); }
        g.itens.push(o);
      });
    }
   }
  }
  const usados = new Set();
  for(const [chave, g] of grupos){
    if(g.itens.length < TILE_INST_MIN){
      for(const m of g.itens) if(m.parent !== scene) scene.add(m);
      continue;
    }
    for(const m of g.itens) if(m.parent === scene) scene.remove(m);
    let inst = pool.get(chave);
    if(!inst || inst.instanceMatrix.count < g.itens.length){
      if(inst){ scene.remove(inst); inst.dispose(); }
      inst = new T.InstancedMesh(g.geo, g.mat, Math.max(16, g.itens.length * 2));
      inst.instanceMatrix.setUsage(T.DynamicDrawUsage);
      inst.frustumCulled = false;
      inst.castShadow = g.cast; inst.receiveShadow = g.receive;
      scene.add(inst);
      pool.set(chave, inst);
    }
    for(let i = 0; i < g.itens.length; i++) inst.setMatrixAt(i, g.itens[i].matrixWorld);
    inst.count = g.itens.length;
    inst.instanceMatrix.needsUpdate = true;
    usados.add(chave);
  }
  for(const [chave, inst] of pool) if(!usados.has(chave)) inst.count = 0;
}

// Reposiciona as instancias do brilho de chao para cobrir exatamente as casas
// reveladas. Substitui o antigo laco que ligava/desligava 882 meshes.
// So e chamada de renderMap3D (ou seja, quando o estado muda), nunca por quadro.
const _wetTmpM4 = (typeof THREE !== 'undefined' && THREE.Matrix4) ? new THREE.Matrix4() : null;
function _atualizarWetFloor3D(terrainSet, state){
  if(!g3 || !g3.wetFloorInst || !_wetTmpM4) return;
  const inst = g3.wetFloorInst, TH = g3.wetFloorTH;
  let n = 0;
  for(const [x, y] of g3.wetFloorKeys){
    if(!terrainSet.has(`${x},${y}`)) continue;
    _wetTmpM4.makeRotationX(-Math.PI / 2);
    _wetTmpM4.setPosition(x, topoTerreno3D(state, x, y, TH) + 0.002, y);   // 2mm acima do piso
    inst.setMatrixAt(n++, _wetTmpM4);
  }
  inst.count = n;
  inst.instanceMatrix.needsUpdate = true;
}

function _clearMovePreviewVisual(){
  const group = g3?.movePreviewGroup;
  if(!group) return;
  const geometries = new Set(), materials = new Set();
  for(const child of [...group.children]){
    child.traverse?.(obj => {
      if(obj.geometry) geometries.add(obj.geometry);
      if(obj.material){
        if(Array.isArray(obj.material)) obj.material.forEach(m => materials.add(m));
        else materials.add(obj.material);
      }
    });
    group.remove(child);
  }
  geometries.forEach(geo => geo.dispose?.());
  materials.forEach(mat => mat.dispose?.());
}

function _renderMovePreview3D(state, terrainSet, TH){
  const group = g3?.movePreviewGroup;
  if(!group) return;
  _clearMovePreviewVisual();
  const preview = GS.pendingMove;
  const me = preview?.testHeroId != null
    ? state?.players?.find(p => String(p.id) === String(preview.testHeroId) && p.alive)
    : state?.players?.find(p => p.id === GS.myPid && p.alive);
  if(!preview?.path?.length || !me) return;
  const origin = Array.isArray(preview.origin) ? preview.origin : me.pos;
  let x = origin[0], y = origin[1];
  const cells = [];
  if(terrainSet.has(`${x},${y}`)) cells.push([x, y]);
  for(const step of preview.path){
    x += step[0]; y += step[1];
    if(!terrainSet.has(`${x},${y}`)) break;
    cells.push([x, y]);
  }
  if(cells.length < 2) return;

  const { T } = g3;
  const mat = new T.MeshBasicMaterial({
    color: 0xffd04a, transparent: true, opacity: .92,
    depthWrite: false, depthTest: false
  });
  const up = new T.Vector3(0, 1, 0);
  for(let i = 1; i < cells.length; i++){
    const [ax, ay] = cells[i - 1], [bx, by] = cells[i];
    const dir = new T.Vector3(bx - ax, 0, by - ay);
    const len = dir.length();
    const mesh = new T.Mesh(new T.CylinderGeometry(.038, .038, len, 8), mat);
    mesh.position.set((ax + bx) / 2,
      (topoSuperficie3D(state, ax, ay, TH) + topoSuperficie3D(state, bx, by, TH)) / 2 + .075,
      (ay + by) / 2);
    mesh.quaternion.setFromUnitVectors(up, dir.normalize());
    mesh.renderOrder = 90;
    mesh.userData.noRay = true;
    group.add(mesh);
  }
  const nodeGeo = new T.SphereGeometry(.075, 8, 6);
  for(const [cx, cy] of cells.slice(1)){
    const node = new T.Mesh(nodeGeo, mat);
    node.position.set(cx, topoSuperficie3D(state, cx, cy, TH) + .075, cy);
    node.renderOrder = 91;
    node.userData.noRay = true;
    group.add(node);
  }

  const [px, py] = cells[cells.length - 1];
  const [ox, oy] = cells[cells.length - 2];
  const arrowDir = new T.Vector3(px - ox, 0, py - oy).normalize();
  const arrow = new T.Mesh(new T.ConeGeometry(.16, .34, 6), mat);
  arrow.position.set(px + arrowDir.x * .12, topoSuperficie3D(state, px, py, TH) + .075, py + arrowDir.z * .12);
  arrow.quaternion.setFromUnitVectors(up, arrowDir);
  arrow.renderOrder = 92;
  arrow.userData.noRay = true;
  group.add(arrow);

  const ringMat = new T.MeshBasicMaterial({
    color: 0xfff0a0, transparent: true, opacity: .9,
    depthWrite: false, depthTest: false
  });
  const ring = new T.Mesh(new T.TorusGeometry(.29, .025, 6, 24), ringMat);
  ring.rotation.x = Math.PI / 2;
  ring.position.set(px, topoSuperficie3D(state, px, py, TH) + .075, py);
  ring.renderOrder = 91;
  ring.userData.noRay = true;
  group.add(ring);
}

function _renderMasterMonsterMovePreview3D(state, terrainSet, TH){
  const group = g3?.movePreviewGroup;
  if(!group) return;
  const preview = _masterMonsterMovePreviewAtual(state);
  if(!preview?.path?.length) return;
  let x = preview.origin[0], y = preview.origin[1];
  const cells = [];
  if(terrainSet.has(`${x},${y}`)) cells.push([x, y]);
  for(const step of preview.path){
    x += step[0]; y += step[1];
    if(!terrainSet.has(`${x},${y}`)) break;
    cells.push([x, y]);
  }
  if(cells.length < 2) return;
  const { T } = g3;
  const mat = new T.MeshBasicMaterial({
    color: 0xffa43d, transparent: true, opacity: .94,
    depthWrite: false, depthTest: false
  });
  const up = new T.Vector3(0, 1, 0);
  for(let i = 1; i < cells.length; i++){
    const [ax, ay] = cells[i - 1], [bx, by] = cells[i];
    const dir = new T.Vector3(bx - ax, 0, by - ay);
    const len = dir.length();
    const mesh = new T.Mesh(new T.CylinderGeometry(.042, .042, len, 8), mat);
    mesh.position.set((ax + bx) / 2,
      (topoSuperficie3D(state, ax, ay, TH) + topoSuperficie3D(state, bx, by, TH)) / 2 + .08,
      (ay + by) / 2);
    mesh.quaternion.setFromUnitVectors(up, dir.normalize());
    mesh.renderOrder = 93; mesh.userData.noRay = true; group.add(mesh);
  }
  const nodeGeo = new T.SphereGeometry(.082, 8, 6);
  for(const [cx, cy] of cells.slice(1)){
    const node = new T.Mesh(nodeGeo, mat);
    node.position.set(cx, topoSuperficie3D(state, cx, cy, TH) + .08, cy);
    node.renderOrder = 94; node.userData.noRay = true; group.add(node);
  }
  const [px, py] = cells[cells.length - 1], [ox, oy] = cells[cells.length - 2];
  const arrowDir = new T.Vector3(px - ox, 0, py - oy).normalize();
  const arrow = new T.Mesh(new T.ConeGeometry(.18, .38, 6), mat);
  arrow.position.set(px + arrowDir.x * .13,
    topoSuperficie3D(state, px, py, TH) + .08, py + arrowDir.z * .13);
  arrow.quaternion.setFromUnitVectors(up, arrowDir);
  arrow.renderOrder = 95; arrow.userData.noRay = true; group.add(arrow);
  const ring = new T.Mesh(new T.TorusGeometry(.32, .028, 6, 24),
    new T.MeshBasicMaterial({color: 0xffffa8, transparent: true, opacity: .94,
      depthWrite: false, depthTest: false}));
  ring.rotation.x = Math.PI / 2;
  ring.position.set(px, topoSuperficie3D(state, px, py, TH) + .08, py);
  ring.renderOrder = 94; ring.userData.noRay = true; group.add(ring);
}

// A cena 3D pode precisar ser recriada quando o chão muda de material. A
// câmera, porém, pertence à experiência do jogador e deve sobreviver a essa
// troca. Capturamos somente os dados da visão — nenhum objeto da cena antiga
// é reutilizado depois do dispose3D().
function _capturarCamera3D(){
  _desfazerShakeCamera();   // o offset do shake nunca pode ser assado numa cena reconstruída
  if(!g3?.camera || !g3?.controls) return null;
  return {
    position: g3.camera.position.clone(),
    target: g3.controls.target.clone(),
    up: g3.camera.up.clone(),
    zoom: Number(g3.camera.zoom) || 1,
  };
}

function _restaurarCamera3D(view){
  if(!view || !g3?.camera || !g3?.controls) return;
  const { camera, controls } = g3;
  camera.up.copy(view.up);
  camera.position.copy(view.position);
  camera.zoom = view.zoom;
  camera.updateProjectionMatrix();
  controls.target.copy(view.target);
  // Recalcula o estado interno do OrbitControls a partir da posição que foi
  // restaurada, sem aplicar novamente a câmera padrão de init3D().
  controls.update();
}

function renderMap3D(state){
  if(!state || !state.tiles) return;
  state = _estadoComMortosVisuais(state);
  _requiemFinalSyncFromState(state);
  _syncMouseAltitudeControl(state);
  _syncInvisibilidadeState(state);
  _syncProtecaoEnergiaState(state);
  _syncProtetorVisualState(state);
  _tempestadeSyncFromState(state);
  // Durante a animação de movimento não reconstrói os peões (preserva o mesh
  // animado). Ao terminar, emMovimento=false e o próximo render reconcilia.
  // Idem para animação de minions (estadoMininoMov).
  if(estadoMovimento.emMovimento || estadoMininoMov.emMovimento) return;
  const boardVisualSig = _assinaturaVisualTabuleiro3D(state);
  if(!g3 || g3.boardVisualSig !== boardVisualSig){
    // Alterações de terreno (por exemplo, as áreas criadas por Senhor das
    // Águas, Sopro do Inverno e Ira da Rocha Ardente) mudam a assinatura
    // visual e exigem reconstruir a cena. A reconstrução cria uma câmera nova
    // e normalmente chama resetCamera3D(); guarde a visão atual para que uma
    // magia nunca force o jogador a perder seu zoom, ângulo ou enquadramento.
    const cameraView = _capturarCamera3D();
    try {
      init3D(state);
      _restaurarCamera3D(cameraView);
    }
    catch(err){
      console.error('init3D failed:', err);
      toast(t('ui.hud.erro_ao_iniciar_3d', {erro: err.message}), 'var(--red)');
      // Fall back to 2D so the board is still visible
      mode3D = false;
      const btn=$('btn-3d-toggle'); if(btn){ btn.classList.remove('active'); btn.textContent='🎲 3D'; }
      const hint=$('orbit-hint'); if(hint) hint.style.display='none';
      _syncMouseAltitudeControl(state);
      const reset=$('btn-cam-reset'); if(reset) reset.style.display='none';
      $('dungeon-canvas').style.display='block';
      renderMap(state);
      return;
    }
  }
  // Este render pode revelar/esconder casas, portas e decorações — a sombra
  // direcional está congelada (autoUpdate=false), então precisa ser redesenhada.
  if(g3.showcase) g3.showcase.shadow.needsUpdate = true;
  if(!g3) return;

  // Feedbacks criados enquanto a cena 3D estava sendo inicializada ganham seus
  // sprites assim que o grupo da cena já existe.
  _updateCombatFeedback3D(performance.now());

  const { T, tileMeshes, doorMeshes, W, H, entityGroup, sconces, torch } = g3;
  // Superfície superior dos pisos 3D. Mantém a correção de escala das
  // miniaturas no mesmo nível de referência usado pelos demais elementos.
  const TH = 0.22;
  let exploredSet = new Set(state.explored.map(([x,y])=>`${x},${y}`));
  // Terreno visível ao vivo: explorado + revelado (Clarividência/minions). Reverte
  // à névoa sozinho quando o minion sai. exploredSet segue governando a lógica.
  const revealedSet = new Set((state.revealed||[]).map(([x,y])=>`${x},${y}`));
  let terrainSet = revealedSet.size
    ? new Set([...exploredSet, ...revealedSet]) : exploredSet;
  // Mestre: sem névoa — todos os meshes de tile/porta/decoração ficam visíveis
  // (mesma lógica-espelho do renderMap 2D). `me` continua undefined (Mestre
  // não é herói), então BFS/alcance abaixo não usam isto.
  if(GS.isMaster() || state.test_mode){
    const full = new Set();
    for(let y=0;y<H;y++) for(let x=0;x<W;x++) full.add(`${x},${y}`);
    exploredSet = full;
    terrainSet  = full;
  }
  const { closed:doorClosed3D } = GS.doorSets(state);
  const me = state.players.find(p => p.id===GS.myPid && p.alive);
  const testeHeroiAtivo = state.test_mode ? _testeHeroiAtivoNoMapa(state) : null;
  const testeHeroiSelecionado = state.test_mode ? _testeHeroiSelecionado(state) : null;
  const testeHeroiControlado = testeHeroiSelecionado && testeHeroiAtivo
    && String(testeHeroiSelecionado.id) === String(testeHeroiAtivo.id)
    ? testeHeroiSelecionado : null;
  let visionSet = computeVisionSet(state, me);
  if(GS.isMaster() || state.test_mode) visionSet = new Set(exploredSet);

  // Reachable tiles (movement highlight)
  const isAnimadosTurn3D = state.animados_turn === GS.myPid;
  const meAnimados3D = (state.players.find(p=>p.id===GS.myPid)?.animados||[]).filter(a=>a.vida_atual>0);
  const selAnimado3D = isAnimadosTurn3D && _animadoSel
    ? meAnimados3D.find(a=>a.id===_animadoSel) : null;
  const meuPris3D = state.prisoner && state.prisoner.alive && state.prisoner.freed
    && state.prisoner.rescuer_pid === GS.myPid;
  const selPris3D = isAnimadosTurn3D && _prisSel && meuPris3D ? state.prisoner : null;

  const reachable = new Set();
  if(selAnimado3D && selAnimado3D.moves_left > 0)
    bfsReachable(state.tiles, exploredSet, selAnimado3D.pos[0], selAnimado3D.pos[1], selAnimado3D.moves_left, reachable);
  else if(selPris3D && (selPris3D.moves_left||0) > 0)
    bfsReachable(state.tiles, exploredSet, selPris3D.pos[0], selPris3D.pos[1], selPris3D.moves_left, reachable);
  else if(!isAnimadosTurn3D && GS.isMyTurn && me && me.moves_left > 0)
    bfsReachable(state.tiles, exploredSet, me.pos[0], me.pos[1], me.moves_left, reachable);
  if(testeHeroiControlado && (testeHeroiControlado.moves_left || 0) > 0){
    bfsReachable(state.tiles, exploredSet, testeHeroiControlado.pos[0], testeHeroiControlado.pos[1],
      testeHeroiControlado.moves_left, reachable,
      {state, materiais: state.materiais, actor: testeHeroiControlado});
  }
  if(GS.isMaster()){
    _masterReachSet(state).forEach(k => reachable.add(k));
  }

  // Attackable tiles (attack range highlight)
  const attackable3d = new Set();
  // Ataque do jogador (apenas no próprio turno, fora do turno dos servos)
  if(!isAnimadosTurn3D && GS.isMyTurn && me && !me.action_done){
    const wRng = me.weapon?.range ?? null;
    for(const m of state.monsters){
      if(!m || m.hp <= 0 || m._morteVisualPendente) continue;
      const dx = Math.abs(me.pos[0] - m.pos[0]), dy = Math.abs(me.pos[1] - m.pos[1]);
      const inR = _alvoNoAlcanceArmaClient(me, m.pos[0], m.pos[1], m.altura)
        && (wRng == null || GS.hasLineOfSight(state, me.pos[0],me.pos[1], m.pos[0],m.pos[1]));
      if(inR) attackable3d.add(`${m.pos[0]},${m.pos[1]}`);
    }
  }
  if(testeHeroiControlado && !testeHeroiControlado.action_done){
    for(const m of state.monsters || []){
      if(!m || m.hp <= 0 || m._morteVisualPendente) continue;
      for(const [tx,ty] of GS.monsterTiles(m)){
        if(GS.weaponCanReachTile(testeHeroiControlado, tx, ty, m.altura)
          && (testeHeroiControlado.weapon?.range == null
            || GS.hasLineOfSight(state, testeHeroiControlado.pos[0], testeHeroiControlado.pos[1], tx, ty, testeHeroiControlado)))
          attackable3d.add(`${tx},${ty}`);
      }
    }
  }
  // Alcance de ataque do animado selecionado (turno dos servos) ou em hover — aditivo
  // Mesma fonte do 2D — ver GS.animadoAttackTargetTiles.
  const atkRefAnimado3D = selAnimado3D || window._animadoHover;
  for(const alvo of GS.animadoAttackTargetTiles(atkRefAnimado3D))
    attackable3d.add(`${alvo.x},${alvo.y}`);
  for(const tile of GS.animadoAttackRangeTiles(atkRefAnimado3D))
    attackable3d.add(`${tile.x},${tile.y}`);
  if(GS.isMaster()){
    _masterAttackSet(state).forEach(k => attackable3d.add(k));
  }

  // Durante a mira de magia, oculta realces de movimento/ataque (mostra alcance/área).
  if(_aimSessionIs() || window._modoMagia || window._modoMestreMira || window._modoThrowItem || window._modoAnimarMortos){ reachable.clear(); attackable3d.clear(); }

  // ── Tile visibility
  for(let y=0; y<H; y++){
    for(let x=0; x<W; x++){
      const key  = `${x},${y}`;
      const mesh = tileMeshes[key];
      if(!mesh) continue;
      const vis = terrainSet.has(key);
      if(mesh.visible !== vis){ mesh.visible = vis; _tilesDirty = true; }
      const ent3 = tileMeshes[`entulho:${key}`];
      if(ent3 && ent3.visible !== vis){ ent3.visible = vis; _tilesDirty = true; }
    }
  }
  if(g3.lavaBubbleMeshes){
    for(const bubble of g3.lavaBubbleMeshes)
      bubble.visible = terrainSet.has(bubble.userData.lavaKey);
  }
  if(g3.waterRippleMeshes){
    for(const ripple of g3.waterRippleMeshes)
      ripple.visible = terrainSet.has(ripple.userData.waterKey);
  }
  if(g3.deepWaterRippleMeshes){
    for(const ripple of g3.deepWaterRippleMeshes)
      ripple.visible = terrainSet.has(ripple.userData.waterKey);
  }
  if(g3.whirlpoolMeshes){
    for(const vortex of g3.whirlpoolMeshes){
      const keys = vortex.userData.whirlpoolKeys;
      vortex.visible = keys
        ? keys.some(key => terrainSet.has(key))
        : terrainSet.has(vortex.userData.whirlpoolKey);
    }
  }
  // Pontes sao uma camada estatica, mas sua visibilidade depende da nevoa do
  // mapa. Este bloco fica no escopo correto, onde `terrainSet` existe.
  if(g3.bridgeMeshes){
    for(const bridgeMesh of g3.bridgeMeshes){
      const keys = bridgeMesh.userData.bridgeKeys;
      const vis = keys ? keys.some(key => terrainSet.has(key))
        : terrainSet.has(bridgeMesh.userData.bridgeKey);
      if(bridgeMesh.visible !== vis) bridgeMesh.visible = vis;
    }
  }
  // Rampas de elevação: a cunha aparece assim que UMA das duas casas que ela
  // liga sai da névoa, senão o desnível apareceria cortado no limite do
  // explorado. Mora aqui, e não no laço de animação do terreno, porque depende
  // do `terrainSet` desta função.
  if(g3.terrainTransitionMeshes){
    for(const ramp of g3.terrainTransitionMeshes){
      ramp.visible = (ramp.userData.terrainKeys || []).some(key => terrainSet.has(key));
    }
  }
  if(g3.gamepadCursorMesh){
    const cursor = _gamepadCursorTile(state);
    const valid = cursor && state.tiles[cursor[1]]?.[cursor[0]] != null;
    const visible = !!(valid && terrainSet.has(`${cursor[0]},${cursor[1]}`));
    g3.gamepadCursorMesh.visible = visible;
    if(visible){
      const pulse = 0.5 + 0.5 * Math.sin(performance.now() / 260);
      const tone = _gamepadCursorTone(state);
      g3.gamepadCursorMesh.position.set(cursor[0], topoSuperficie3D(state, cursor[0], cursor[1], TH) + 0.036, cursor[1]);
      const selecionandoAtaque = !!_gamepadInput.attackMode;
      g3.gamepadCursorMesh.scale.setScalar(selecionandoAtaque ? 1.08 + pulse * 0.13 : 0.92 + pulse * 0.18);
      g3.gamepadCursorMesh.material.color.set(tone.hex);
      g3.gamepadCursorMesh.material.opacity = selecionandoAtaque ? 0.82 + pulse * 0.18 : 0.58 + pulse * 0.34;
    }
  }
  // Segredos 3D: Encontrar Armadilhas ou Clarividência os revela. A parede
  // continua existindo; a transparência é somente uma indicação visual.
  const _detectSecrets3D = !!(me && me.class_id === 'rogue' && me.detectar_ativo);
  const _secretWalls3D = new Map((state.secret_passages || [])
    .filter(sp => !sp.opened && (_detectSecrets3D || sp.revealed_by_clarividencia))
    .map(sp => [`${sp.pos[0]},${sp.pos[1]}`, sp.type]));
  for (const [key, mesh] of Object.entries(tileMeshes)) {
    if (!mesh.userData?.isWall || !mesh.material) continue;
    const secretType = _secretWalls3D.get(key);
    const shared = mesh.userData.sharedMat;
    if (secretType) {
      // O material das paredes é COMPARTILHADO entre casas de mesma aparência:
      // mutar transparent/opacity aqui deixaria TODAS as paredes translúcidas.
      // Cada parede secreta ganha (uma vez) a sua própria cópia.
      if (!mesh.userData.secretMat) mesh.userData.secretMat = shared.clone();
      const sm = mesh.userData.secretMat;
      sm.transparent = true;
      sm.opacity = secretType === 'illusion' ? 0.28 : 0.55;
      sm.depthWrite = false;
      if (mesh.material !== sm){ mesh.material = sm; _tilesDirty = true; }
    } else if (shared && mesh.material !== shared) {
      mesh.material = shared;   // volta ao compartilhado (opaco) quando some o realce
      _tilesDirty = true;
    }
  }
  // Depois da visibilidade E da troca de material das secretas: as instancias
  // sao montadas a partir do estado final das procuracoes.
  _rebuildTileInstances();

  // ── Door leaves: visible only while closed AND the door tile is visível ──────
  if(doorMeshes){
    for(const [key, grp] of Object.entries(doorMeshes))
      grp.visible = terrainSet.has(key) && doorClosed3D.has(key);
  }

  // Os realces por casa nascem sob demanda: em vez de varrer o dicionário,
  // passa-se o conjunto final de casas a acender (ver _mkOverlayPool).
  const _soExploradas = (keys) => { const r = new Set(); for(const k of keys) if(exploredSet.has(k)) r.add(k); return r; };

  // ── Movement highlight overlay visibility (blue planes)
  _overlayShowOnly(g3.moveHighlightMeshes, _soExploradas(reachable));
  _renderMovePreview3D(state, terrainSet, TH);
  _renderMasterMonsterMovePreview3D(state, terrainSet, TH);

  // ── Attack highlight overlay visibility (red planes)
  _overlayShowOnly(g3.atkHighlightMeshes, _soExploradas(attackable3d));

  // ── Weapon range preview planes (vermelho forte — hover no ícone da arma)
  {
    const wRngTiles = ((window._weaponRangePreview || window._gamepadAttackRangePreview) && me)
      ? _computeWeaponRangeTiles(state, me) : new Set();
    const giroTiles = (window._ataqueGiratorioPreview && me)
      ? _ataqueGiratorioPreviewTiles(state, me) : new Set();
    _overlayShowOnly(g3.weaponRangeMeshes,
      _soExploradas(new Set([...wRngTiles, ...giroTiles])));
  }

  // Prévia do Mestre: vermelho claro = alcance total; vermelho escuro =
  // casas efetivamente atacáveis pela orientação e pelos ataques da criatura.
  const masterHoverMonster = _masterMonsterHoverEnabled() && _masterMonsterHoverId
    ? (state.monsters || []).find(m => m.id === _masterMonsterHoverId && m.hp > 0)
    : null;
  const masterHoverPreview = masterHoverMonster
    ? _masterMonsterAttackPreviewClient(state, masterHoverMonster)
    : { range: new Set(), zone: new Set() };
  _overlayShowOnly(g3.masterAttackRangeMeshes,
    masterHoverMonster ? _soExploradas(masterHoverPreview.range) : null);
  _overlayShowOnly(g3.masterAttackZoneMeshes,
    masterHoverMonster ? _soExploradas(masterHoverPreview.zone) : null);
  {
    const footprint = new Set();
    for(const id of _masterSelectedMonsterIds(state)){
      const monster = (state.monsters || []).find(m => String(m.id) === String(id));
      for(const [x,y] of _masterMonsterFootprintTiles(state, monster)) footprint.add(`${x},${y}`);
    }
    _overlayShowOnly(g3.masterFootprintMeshes, _soExploradas(footprint));
  }
  const historyFocus = _masterHistoryFocus && performance.now() <= Number(_masterHistoryFocus.until || 0)
    ? _masterHistoryFocus : null;
  if(!historyFocus) _masterHistoryFocus = null;
  const historyAttacker = new Set(), historyTarget = new Set();
  if(historyFocus){
    for(const [x,y] of _masterHistoryEntityTiles(state, historyFocus.attackerId, historyFocus.attackerPos)) historyAttacker.add(`${x},${y}`);
    for(const [x,y] of _masterHistoryEntityTiles(state, historyFocus.targetId, historyFocus.targetPos)) historyTarget.add(`${x},${y}`);
  }
  _overlayShowOnly(g3.masterHistoryAttackerMeshes,
    historyFocus ? _soExploradas(historyAttacker) : null);
  _overlayShowOnly(g3.masterHistoryTargetMeshes,
    historyFocus ? _soExploradas(historyTarget) : null);

  // ── Realce de MAGIA (alcance vermelho / zona laranja / área verde) ──────────
  // O mesmo filtro de névoa usado pelos pisos evita que a prévia colorida
  // revele alvos em casas ainda ocultas no modo 3D.
  g3.spellVisibleSet = exploredSet;
  _aplicarSpellHL3D();

  // ── Explosão do Elemental de Fogo — meshes vermelhos temporários (3D) ───────
  if(g3.atkHighlightMeshes && _explosionTiles && _explosionTiles.size){
    // Acende por cima do realce de ataque, sem apagar o que já estava aceso.
    for(const key of _explosionTiles){
      if(!exploredSet.has(key)) continue;
      const m = _overlayAt(g3.atkHighlightMeshes, key);
      if(m) m.visible = true;
    }
  }

  // ── Wall detail visibility (arches, corner columns, baseboards) ─────────────
  if(g3.wallDetailMeshes){
    for(const [key, arr] of Object.entries(g3.wallDetailMeshes)){
      const vis = terrainSet.has(key);
      for(const m of arr) if(m.visible !== vis){ m.visible = vis; _detailDirty = true; }
    }
    // O rebuild roda UMA vez, depois que as duas familias (detalhe de parede
    // e cenario) ja definiram sua visibilidade -- ver abaixo.
  }

  // ── Wall torch visibility (whole bracket group, keyed by wall tile) ──────────
  if(g3.wallTorches){
    for(const wt of g3.wallTorches){
      const vis = terrainSet.has(wt.wallKey);
      wt.group.visible = vis;   // so as chamas moram no grupo agora
      for(const m of (g3.torchStaticMeshes && g3.torchStaticMeshes[wt.wallKey]) || [])
        if(m.visible !== vis){ m.visible = vis; _detailDirty = true; }
    }
  }

  // ── Room floor overlay visibility (transparent color planes) ─────────────────
  if(g3.roomOverlayMeshes){
    for(const [key, mesh] of Object.entries(g3.roomOverlayMeshes))
      mesh.visible = terrainSet.has(key);
  }

  if(g3.sceneryMeshes){
    for(const [key, arr] of Object.entries(g3.sceneryMeshes)){
      const vis = terrainSet.has(key);
      for(const m of arr) if(m.visible !== vis){ m.visible = vis; _detailDirty = true; }
    }
    _rebuildDetailInstances();
  }

  // ── Glowing grout visibility (magic rune grid, trap rooms only) ───────────────
  if(g3.groutMeshes){
    for(const [key, arr] of Object.entries(g3.groutMeshes))
      for(const m of arr) m.visible = terrainSet.has(key);
  }

  // ── Wet floor reflection visibility (revealed with its floor tile) ───────────
  _atualizarWetFloor3D(terrainSet, state);

  // ── Dust motes: show once the player has revealed any tiles ──────────────────
  if(g3.dustPts && !g3.dustPts.visible && exploredSet.size > 0 && _perfCfg().poeira)
    g3.dustPts.visible = true;

  if(me){
    torch.position.set(me.pos[0], 1.1, me.pos[1]);
    g3.visionLamp.position.set(me.pos[0], 1.8, me.pos[1]);
  } else {
    torch.position.set(W/2, 1.1, H/2);
    g3.visionLamp.position.set(W/2, 1.8, H/2);
  }

  // ── Sconce anchors: marca as reveladas e reatribui o pool de luzes na hora
  // (a área recém-aberta já acende no mesmo frame, sem esperar o tick).
  for(const sc of sconces)
    sc.revealed = exploredSet.has(`${sc.x},${sc.y}`);
  _atribuirLightPool();

  // ── Staircase visibility
  if(g3.stairGroup && state.stairs_pos)
    g3.stairGroup.visible = exploredSet.has(`${state.stairs_pos[0]},${state.stairs_pos[1]}`);
  for(const hs of (g3.heroSpawnGroups||[]))
    hs.group.visible = exploredSet.has(`${hs.pos[0]},${hs.pos[1]}`);
  // Fase 3: marcador de saída visível quando a casa foi explorada.
  if(g3.exitGroup && GS.exitPos)
    g3.exitGroup.visible = exploredSet.has(`${GS.exitPos[0]},${GS.exitPos[1]}`);

  // ── Chest 3D models — persistent meshes, created/removed as chests appear/go ─
  const chests = state.chests || [];
  const liveChestIds = new Set(chests.map(c => c.id));

  // Remove meshes for chests that no longer exist
  for(const [cid, grp] of Object.entries(g3.chestMeshes)){
    if(!liveChestIds.has(cid)){
      g3.scene.remove(grp);
      delete g3.chestMeshes[cid];
    }
  }
  // Add new chest meshes + update visibility
  for(const chest of chests){
    const key = `${chest.pos[0]},${chest.pos[1]}`;
    // Baú cujo GLB falhou: refaz quando a retentativa limpar a marca de erro.
    const antigo = g3.chestMeshes[chest.id];
    if(antigo && antigo.userData.chestSemGLB
       && _decorGLBCache['assets/objetos/bau.glb'] !== 'erro'){
      g3.scene.remove(antigo);
      delete g3.chestMeshes[chest.id];
    }
    if(!g3.chestMeshes[chest.id]){
      const grp = buildChest3D(g3.T, chest);
      g3.scene.add(grp);
      g3.chestMeshes[chest.id] = grp;
    }
    g3.chestMeshes[chest.id].position.y = topoTerreno3D(state, chest.pos[0], chest.pos[1], 0.22);
    g3.chestMeshes[chest.id].visible = exploredSet.has(key);
  }

// ── Itens no chão 3D — modelos GLB persistentes, queda animada e emoji fallback ─
  const gItems3D = state.ground_items || [];
  const liveGiIds = new Set(gItems3D.map(g => g.id));
  for(const [gid, grp] of Object.entries(g3.groundItemMeshes)){
    if(!liveGiIds.has(gid)){
      grp.userData.removed = true;
      g3.scene.remove(grp);
      delete g3.groundItemMeshes[gid];
    }
  }
  for(const gi of gItems3D){
    const key = `${gi.pos[0]},${gi.pos[1]}`;
    const modelConfig = _groundItemGlbConfig(gi);
    let existing = g3.groundItemMeshes[gi.id];
    const modelCacheState = modelConfig ? (_decorGLBCache[modelConfig.path] ?? null) : null;
    // Se uma primeira tentativa de rede falhou, o emoji fica como fallback. O
    // cache do carregador é invalidado por _agendarRecargaArte; reconstrói o
    // mesh ao detectar isso para a nova tentativa também alcançar este item.
    if(existing?.userData.groundModelFailed
        && modelCacheState !== existing.userData.groundModelFailureCache
        && modelCacheState !== 'erro'){
      existing.userData.removed = true;
      g3.scene.remove(existing);
      delete g3.groundItemMeshes[gi.id];
      existing = null;
    }
    if(!g3.groundItemMeshes[gi.id]){
      const groundId = String(gi.id);
      const animateDrop = !g3.groundItemSeenIds.has(groundId);
      const grp = buildGroundItem3D(g3.T, gi, animateDrop);
      g3.scene.add(grp);
      g3.groundItemMeshes[gi.id] = grp;
      g3.groundItemSeenIds.add(groundId);
    }
    g3.groundItemMeshes[gi.id].position.y = topoTerreno3D(state, gi.pos[0], gi.pos[1], 0.22);
    g3.groundItemMeshes[gi.id].visible = exploredSet.has(key);
  }

  // ── Decoration 3D meshes — procedural boxes/cylinders, ou miniatura extrudada ─
  {
    const decors = GS.decorations;
    const vistosDec = new Set();
    for (const d of decors) {
      vistosDec.add(d.id);
      const tiles = GS.decorTilesOf(d);
      // Determine footprint bounds
      const minX = Math.min(...tiles.map(t => t[0]));
      const maxX = Math.max(...tiles.map(t => t[0]));
      const minY = Math.min(...tiles.map(t => t[1]));
      const maxY = Math.max(...tiles.map(t => t[1]));
      const wCells = maxX - minX + 1;
      const hCells = maxY - minY + 1;
      // Center of footprint in world coords (tile x,y map directly to world x,z)
      const _dvo = Array.isArray(d.voffset) ? d.voffset : [0, 0];
      const worldX = (minX + maxX) / 2 + Math.max(-.45, Math.min(.45, Number(_dvo[0]) || 0));
      const worldZ = (minY + maxY) / 2 + Math.max(-.45, Math.min(.45, Number(_dvo[1]) || 0));
      const dElevation = tiles.reduce((sum, tile) => sum + elevacaoTerreno(state, tile[0], tile[1]), 0)
        / Math.max(1, tiles.length);
      const dFloorY = dElevation * TERRENO_ELEVACAO_STEP_3D;
      const visivel = tiles.some(([tx2, ty2]) => exploredSet.has(`${tx2},${ty2}`));

      let mesh = g3.decorMeshes[d.id];

      if (d.special === 'wall' && d.image) {
        const faceSig = (d.facing || [0,1]).join(',');
        const scaleSig = (Array.isArray(d.vscale) ? d.vscale : [1,1]).join(',');
        const wallGlbPath = d.model3d || (d.image && DECOR_GLB_MODELS[d.image]) || DECOR_GLB_TYPES[d.type];
        const wallMode = wallGlbPath && _decorGLBCache[wallGlbPath] !== 'erro' ? wallGlbPath : 'png';
        if (!mesh || mesh.userData.wallImage !== d.image || mesh.userData.wallFace !== faceSig
            || mesh.userData.wallScale !== scaleSig || mesh.userData.wallGlbPath !== wallMode) {
          if (mesh) { g3.scene.remove(mesh); _disposeDecorMesh(mesh); }
          mesh = new T.Group();
          // A assinatura completa evita recriar o placeholder a cada render
          // enquanto o PNG ainda está carregando.
          mesh.userData = {isDecor:true, decorId:d.id, wallImage:d.image,
            wallFace:faceSig, wallScale:scaleSig, wallGlbPath:wallMode, pending:true};
          mesh.visible = visivel; g3.scene.add(mesh); g3.decorMeshes[d.id] = mesh;
          if (wallMode === 'png') _buildWallDecor3D(d);
          else _buildWallDecorGLB(d, wallGlbPath);
        }
        mesh = g3.decorMeshes[d.id];
        if (mesh) mesh.visible = visivel;
        continue;
      }

      if (d.special === 'floor' && d.image) {
        // ── Chão: decal deitado preenchendo TODO o footprint, borda-a-borda ──
        if (!mesh || mesh.userData.imageName !== d.image || mesh.userData.floorW !== wCells || mesh.userData.floorH !== hCells) {
          if (mesh) { g3.scene.remove(mesh); _disposeDecorMesh(mesh); }
          mesh = _chaoDecal3D(d, wCells, hCells);
          g3.scene.add(mesh);
          g3.decorMeshes[d.id] = mesh;
        }
        mesh.position.set(worldX, 0.222 + dFloorY, worldZ);   // logo acima do piso, sob os realces
        mesh.visible = visivel;
        continue;
      }

      const glbPath = d.model3d || (d.image && DECOR_GLB_MODELS[d.image]) || DECOR_GLB_TYPES[d.type];
      if (glbPath && _decorGLBCache[glbPath] !== 'erro') {
        // ── Modelo 3D real (GLB) ──
        if (!mesh || mesh.userData.glbPath !== glbPath) {
          if (mesh) { g3.scene.remove(mesh); _disposeDecorMesh(mesh); }
          const placeholder = new T.Group();
          placeholder.userData = { isDecor: true, decorId: d.id, glbPath, pending: true };
          placeholder.position.set(worldX, 0, worldZ);
          placeholder.visible = visivel;
          g3.scene.add(placeholder);
          g3.decorMeshes[d.id] = placeholder;
          mesh = placeholder;
          _buildObjetoGLB(d.id, d.image, glbPath, wCells, hCells, d.facing);
          mesh = g3.decorMeshes[d.id];
        }
        mesh.position.set(worldX, DECOR_GLB_FLOOR_Y + dFloorY, worldZ);
        const glbScale = Array.isArray(d.vscale) ? d.vscale : [1, 1];
        mesh.scale.set(glbScale[0] || 1, glbScale[1] || 1, glbScale[0] || 1);
        mesh.visible = visivel;
        continue;
      }

      if (d.image && window.Miniatura3D) {
        // ── Caminho miniatura extrudada (PNG) ──
        // (re)constrói se ainda não existe OU se a imagem mudou
        if (!mesh || mesh.userData.imageName !== d.image) {
          if (mesh) { g3.scene.remove(mesh); _disposeDecorMesh(mesh); }
          const placeholder = new T.Group();
          placeholder.userData = { isDecor: true, decorId: d.id, imageName: d.image, pending: true };
          // Posiciona ANTES de construir: se a imagem já estiver em cache, o
          // build roda síncrono e copia esta posição (senão a miniatura cairia em 0,0).
          placeholder.position.set(worldX, 0, worldZ);
          placeholder.visible = visivel;
          g3.scene.add(placeholder);
          g3.decorMeshes[d.id] = placeholder;
          mesh = placeholder;
          _buildObjetoMini(d.id, d.image, Math.max(wCells, hCells), d.facing);   // assíncrono (ou síncrono se em cache)
          mesh = g3.decorMeshes[d.id];   // _buildObjetoMini pode ter trocado o mesh (cache)
        }
        mesh.position.set(worldX, dFloorY, worldZ);
        // Giro 90° (facing): roda a miniatura em pé sobre o eixo vertical.
        mesh.rotation.y = _facingAngleY3D(d.facing, d.type, d.image, glbPath);
        // Escala visual (vscale): largura no plano (x,z), altura p/ cima (y);
        // o footprint já está embutido na geometria via tileSize.
        const _mvs = Array.isArray(d.vscale) ? d.vscale : [1, 1];
        mesh.scale.set(_mvs[0] || 1, _mvs[1] || 1, _mvs[0] || 1);
        mesh.visible = visivel;
        continue;
      }

      // ── Caminho procedural (sem image) ──
      // Se havia uma miniatura PNG antes (imageName), destrói e reconstrói como procedural
      if (mesh && mesh.userData.imageName) {
        g3.scene.remove(mesh); _disposeDecorMesh(mesh);
        mesh = null;
      }
      const spec = DECOR_3D[d.type] || { shape: 'box', h: 0.6, color: 0x999999 };
      if (!mesh) {
        const geo = spec.shape === 'cyl'
          ? new T.CylinderGeometry(0.4, 0.4, spec.h, 16)
          : new T.BoxGeometry(1, spec.h, 1);
        mesh = new T.Mesh(geo, new T.MeshStandardMaterial({ color: spec.color }));
        mesh.userData.isDecor = true;
        mesh.userData.decorId = d.id;
        g3.scene.add(mesh);
        g3.decorMeshes[d.id] = mesh;
      }
      // Escala visual (vscale): largura no plano ×sx, altura ×sy (ancorada no chão).
      const _pvs = Array.isArray(d.vscale) ? d.vscale : [1, 1];
      const _psx = _pvs[0] || 1, _psy = _pvs[1] || 1;
      mesh.position.set(worldX, dFloorY + spec.h * _psy / 2, worldZ);
      // Scale box to cover full footprint; cylinder mantém o raio (só vscale)
      if (spec.shape === 'box') mesh.scale.set(wCells * 0.9 * _psx, _psy, hCells * 0.9 * _psx);
      else mesh.scale.set(_psx, _psy, _psx);
      // Visibility: show if any footprint tile is explored
      mesh.visible = visivel;
    }

    // Perigo identificado pelo Ladino: mantém um marcador visível também no
    // modo 3D. O marcador é filho da própria decoração e desaparece junto com
    // ela quando a armadilha é desarmada ou disparada.
    for (const d of decors) {
      const mesh = g3.decorMeshes[d.id];
      if (!mesh) continue;
      const perigosa = (d.trap || d.chest_trap) && d.trap_revealed;
      let badge = mesh.userData && mesh.userData._trapBadge;
      if (perigosa && !badge) {
        badge = _decorTrapBadge3D();
        mesh.add(badge);
        mesh.userData._trapBadge = badge;
      }
      if (badge) {
        badge.visible = !!(perigosa && mesh.visible);
        badge.position.set(0, 1.25, 0);
      }
    }

    // Remove meshes for decorations that no longer exist
    for (const id of Object.keys(g3.decorMeshes)) {
      if (!vistosDec.has(id)) {
        const m = g3.decorMeshes[id];
        g3.scene.remove(m); _disposeDecorMesh(m);
        delete g3.decorMeshes[id];
      }
    }
  }

  // ── Rebuild entity group ────────────────────────────────────────────────────
  // Assinatura do que é visível: se nada mudou desde o último game_state, NÃO
  // reconstrói os peões. Reconstruir a cada mensagem criava/vazava dezenas de
  // geometrias, materiais, texturas e PointLights — e a variação na contagem de
  // luzes força o Three.js a recompilar shaders (travadas perceptíveis).
  const gamepadAttackTarget3D = _gamepadSelectedAttackTarget(state);
  const entitySig = JSON.stringify([
    state.players.map(p => [p.id, p.pos, p.altura, p.alive, p.color, p.class_id, p.pawn_override, !!p.metamorfose_ativa, p.metamorfose_forma_type, p.bau_engolido, p.fosso_oculto, !!p.invisivel_magico, !!p.petrificado, _invisibilidadeAnimAtiva(p.id), p.em_chamas_rodadas > 0,
      p.acido_residual > 0, (p.efeitos_veneno||[]).length > 0,
      (p.animados||[]).map(a => [a.id, a.pos, a.vida_atual, a.tipo, a.image, a.porte, a.size, a.oriented, a.facing])]),
    state.monsters.map(m => [m.type, m.pos, m.hp, m.image, !!m.metamorfose_ativa, m.metamorfose_forma_type, m.vscale, m.size, !!m.oriented, !!m.fill_footprint_3d, m.facing, m.em_chamas_rodadas > 0,
    m.acido_residual > 0, (m.efeitos_veneno||[]).length > 0, !!m.petrificado, m.altura,
    !!(m.provocado && Number(m.provocado_turnos) > 0)]),
    state.prisoner ? [state.prisoner.pos, state.prisoner.alive, state.prisoner.freed, state.prisoner.image, _prisSel] : null,
    state.corpses || [],
    state.hero_corpses || [],
    (state.armadilhas||[]).map(a => [a.id, a.pos, a.ativada, a.so_luccas, a.icone, a.visivel, a.aliada, a.image]),
    (state.decorations||[]).map(d => [d.id, d.pos, d.facing, d.trap, d.chest_trap, d.trap_revealed, d.tem_loot]),
    state.rooms.map(r => [r.cx, r.cy, r.role, r.cleared]),
    state.current_turn, state.animados_turn, GS.myPid, gamepadAttackTarget3D?.targetId || null,
    g3.selectedPos, _animadoSel,
    GS.isMaster() ? [..._masterSelectedMonsterIds(state)].sort().join('|') : '',
    state.explored.length, [...visionSet].sort().join('|'),
    // Arte liberada para nova tentativa depois de falhar por rede. Sem isto o
    // bloco inteiro de entidades é pulado (nada no estado mudou) e o peão fica
    // com a miniatura genérica para sempre, mesmo com o arquivo já disponível.
    _arteGen,
  ]);
  if(entitySig !== g3._entitySig){
  g3._entitySig = entitySig;

  // ── Cache por entidade: cada peão só é RECONSTRUÍDO quando sua aparência
  // muda (classe, cor, turno ativo, seleção...). Mudança apenas de posição
  // reaproveita o grupo inteiro e atualiza x/z — o movimento de UM peão não
  // recria os outros 10+ peões da cena.
  if(!g3._figCache) g3._figCache = new Map();
  const figCache = g3._figCache;
  const figsUsadas = new Set();

  // Esvazia o grupo SEM descartar — os peões vivem no cache; os que não forem
  // reutilizados nesta passada são descartados (com GPU liberada) no final.
  while(entityGroup.children.length) entityGroup.remove(entityGroup.children[0]);

  // Reaproveita a figura `key` se a assinatura visual não mudou; senão
  // reconstrói (descartando a antiga). Reposiciona em (x, z) quando passado.
  const obterFig = (key, sig, construir, x, y, altitude = 0) => {
    let ent = figCache.get(key);
    if(!ent || ent.sig !== sig){
      if(ent) _disposeEntityTree(ent.fig);
      ent = { sig, fig: construir() };
      figCache.set(key, ent);
    }
    const fig = ent.fig;
    if(x !== undefined){
      fig.position.x = x;   // y é animado pelo hover-lift — não tocar
      fig.position.z = y;
      fig.userData.gridX = x;
      fig.userData.gridY = y;
      const altitudeNum = Number(altitude);
      const altitudeNormalizada = Math.max(0, Math.min(10,
        Number.isFinite(altitudeNum) ? Math.trunc(altitudeNum) : 0));
      fig.userData.altitude = altitudeNormalizada;
      if(fig.userData.flightBody){
        fig.userData.flightBody.position.y = altitudeNormalizada * FLIGHT_ALTITUDE_STEP;
      }
      // Água rasa/profunda: afunda cada miniatura em 25%/45% da própria altura.
      // O deslocamento fica no grupo-raiz e serve para heróis e monstros.
      if(fig.userData._waterSinkDeepY === undefined){
        const bounds = new T.Box3().setFromObject(fig);
        const h = bounds.getSize(new T.Vector3()).y;
        fig.userData._waterSinkShallowY = -Math.max(0.10, h) * 0.25;
        fig.userData._waterSinkDeepY = -Math.max(0.10, h) * 0.45;
        fig.userData._whirlpoolSinkY = -Math.max(0.10, h) * 0.60;
        fig.userData._lavaSinkY = -Math.max(0.10, h) * 0.30;
        fig.userData._swampSinkY = -Math.max(0.10, h) * 0.20;
        fig.userData._snowPlainSinkY = -Math.max(0.10, h) * 0.15;
      }
      // A ponte substitui a superfície do material inferior: o peão fica
      // apoiado no tabuleiro e não afunda nem recebe aparência de lava/água.
      const waterKind = ponteNaCasa3D(state, x, y) ? null
        : state.materiais && state.materiais[`${x},${y}`];
      const waterSinkY = (waterKind === 'rodamoinho' || waterKind === 'rodamoinho_profundo') && altitudeNormalizada <= 0 ? fig.userData._whirlpoolSinkY
        : waterKind === 'planicie_nevada' && altitudeNormalizada <= 0 ? fig.userData._snowPlainSinkY
        : waterKind === 'pantano' ? fig.userData._swampSinkY
        : waterKind === 'lava' ? fig.userData._lavaSinkY
        : waterKind === 'agua_profunda' ? fig.userData._waterSinkDeepY
        : waterKind === 'agua' ? fig.userData._waterSinkShallowY : 0;
      // vscale é aplicado ao grupo inteiro, cujo pivô fica no mapa (y=0).
      // Compensa a redução vertical para manter a menor parte da miniatura
      // apoiada na superfície do piso, sem interferir no tamanho visual.
      const terrainLiftY = topoSuperficie3D(state, x, y, TH) - TH;
      fig.userData.baseY = terrainLiftY + waterSinkY + (Number(fig.userData._floorAnchorLiftY) || 0);
      fig.position.y = fig.userData.baseY;
      fig.userData._stepBaseY = fig.userData.baseY;
    }
    figsUsadas.add(key);
    entityGroup.add(fig);
    return fig;
  };

  // Players
  for(const p of state.players){
    if(!p.alive) continue;
    if(p.engolido || p.bau_engolido || p.fosso_oculto) continue;
    if(p.connected === false) continue;   // desconectado: fora da masmorra, não desenha
    const [px,py] = p.pos;
    if(p.id !== GS.myPid && !visionSet.has(`${px},${py}`)) continue;
    const pSel = (g3.selectedPos && g3.selectedPos[0]===px && g3.selectedPos[1]===py)
      || !!(state.test_mode && testeHeroiSelecionado
        && String(p.id) === String(testeHeroiSelecionado.id));
    const isCur = p.id===state.current_turn;
    const formaVisual = _metamorfoseVisualName(p);
    const _figInvis = obterFig(`pl:${p.id}`,
      JSON.stringify([p.color, p.class_id, formaVisual, p.metamorfose_ativa, p.metamorfose_forma_type, p.id===GS.myPid, isCur, !!pSel, p.facing, p.em_chamas_rodadas > 0, !!p.petrificado,
        p.acido_residual > 0, (p.efeitos_veneno||[]).length > 0]),
      () => {
        const f = build3DFig(p.color, !!formaVisual, p.id===GS.myPid, isCur, px, py, p.class_id,
          formaVisual ? (p.metamorfose_forma_type || formaVisual) : null, pSel, formaVisual,
          undefined, undefined, p.facing, p.em_chamas_rodadas > 0,
          // Os `undefined` cobrem monsterVisionRadius, mModel3D, mFillFootprint
          // e mSize — parâmetros só de monstro. Faltava o de mSize, então
          // `petrificado` caía uma posição antes e o herói NUNCA virava pedra.
          p.acido_residual > 0, (p.efeitos_veneno||[]).length > 0,
          undefined, undefined, undefined, undefined, !!p.petrificado);
        f.userData.pid = p.id;          // permite getPeaoMesh(pid) p/ animação
        return f;
      }, px, py, p.altura);
    _figInvis.userData.magicalInvisible = !!p.invisivel_magico || _invisibilidadeAnimAtiva(p.id);
    _figInvis.userData.whirlpoolTrapped = !!(p.rodamoinho_preso || p.rodamoinho_profundo_preso);
  }

  // Os mesmos efeitos ativos do HUD 2D aparecem presos ao peão no espaço 3D.
  // Como a lista vem do estado recebido, expira e desaparece junto com a regra.
  _syncEfeitosAtivos3D(state, visionSet);

  // Prisioneiro (Fase 3): peão com imagem editável; só quando visível/explorado.
  const _pris3D = state.prisoner;
  if(_pris3D && _pris3D.alive){
    const [prx,pry] = _pris3D.pos;
    if(visionSet.has(`${prx},${pry}`) || exploredSet.has(`${prx},${pry}`)){
      const prisSelNow = !!(_prisSel && isAnimadosTurn3D && _pris3D.freed
        && _pris3D.rescuer_pid === GS.myPid);
      const _prisFig3D = obterFig('prisoner',
        JSON.stringify([_pris3D.freed, _pris3D.image, prisSelNow]),
        () => {
          const f = build3DPrisoner(g3.T, _pris3D, prisSelNow);
          f.userData.prisoner = true;   // permite getPrisonerMesh() p/ animação
          return f;
        },
        prx, pry);
      _prisFig3D.userData.whirlpoolTrapped = !!(_pris3D.rodamoinho_preso || _pris3D.rodamoinho_profundo_preso);
    }
  }

  // Monsters — only visible within player's current vision radius
  for(const m of state.monsters){
    if(m.hp <= 0) continue;
    const [mx,my] = m.pos;
    if(!visionSet.has(`${mx},${my}`)) continue;
    const mSel = (g3.selectedPos && g3.selectedPos[0]===mx && g3.selectedPos[1]===my)
      || (GS.isMaster() && _masterSelectedMonsterIds(state).has(String(m.id)));
    const gamepadAttackTargeted = gamepadAttackTarget3D?.targetId === m.id;
    const imageName = _monsterImageName(m);
    const _monFig3D = obterFig(`mon:${m.id}`,
      // _arteGen: muda quando uma arte que falhou por rede é liberada para nova
      // tentativa — sem ele o peão continuaria com a miniatura genérica, porque
      // a assinatura seria idêntica e obterFig reusaria a figura já construída.
      JSON.stringify([m.type, imageName, m.model3d, !!mSel, gamepadAttackTargeted, m.porte, m.vscale, m.size, !!m.oriented, !!m.fill_footprint_3d, m.facing, m.em_chamas_rodadas > 0, !!m.petrificado,
        m.acido_residual > 0, (m.efeitos_veneno||[]).length > 0, m.vision_radius, m.altura, GS.sorrateiroAtivo(), _arteGen]),
      () => {
        const f = build3DFig('#c82020', true, false, false, mx, my, null, m.type, mSel || gamepadAttackTargeted, imageName, m.porte, m.oriented, m.facing, m.em_chamas_rodadas > 0,
          m.acido_residual > 0, (m.efeitos_veneno||[]).length > 0, m.vision_radius, m.model3d, !!m.fill_footprint_3d, m.size, !!m.petrificado);
        const vs = Array.isArray(m.vscale) ? m.vscale : [1, 1];
        const sx = Math.max(.2, Math.min(4, Number(vs[0]) || 1));
        const sy = Math.max(.2, Math.min(4, Number(vs[1]) || 1));
        // Escala só a aparência: posição, footprint e regras continuam iguais.
        const focusScale = gamepadAttackTargeted ? 1.05 : 1;
        f.scale.set(sx * focusScale, sy * focusScale, sx * focusScale);
        // O grupo começa no nível do piso; ao reduzir sy, a base também seria
        // multiplicada e afundaria. O lift é aplicado pelo posicionamento
        // comum das entidades, preservando hover, água e saltos de movimento.
        f.userData._floorAnchorLiftY = TH * (1 - sy) + (gamepadAttackTargeted ? .045 : 0);
        f.userData.monId = m.id;   // taggeado para getMonsterMesh() / deslize fiel
        return f;
      },
      mx, my, m.altura);
    _monFig3D.userData.whirlpoolTrapped = !!(m.rodamoinho_preso || m.rodamoinho_profundo_preso);
    _syncProvocacaoMark3D(_monFig3D, m);
    // m.pos continua sendo a âncora autoritativa para seleção e colisão; a
    // raiz visual é deslocada para o centro geométrico do footprint.
    // A âncora é a fileira frontal. Centralizamos qualquer footprint orientado
    // que não tenha feito esse ajuste dentro do GLB; 2x2 não orientado também
    // continua sendo centralizado como antes.
    const needsVisualCenter = _monsterIs2x2(m) || (m.oriented && !m.fill_footprint_3d);
    const [moffX, moffY] = needsVisualCenter ? _monsterVisualCenterOffset(m) : [0, 0];
    const _m3d = g3._figCache && g3._figCache.get(`mon:${m.id}`);
    if(_m3d && _m3d.fig){
      _m3d.fig.position.x = mx + moffX;
      _m3d.fig.position.z = my + moffY;
      _m3d.fig.userData.gridX = mx;
      _m3d.fig.userData.gridY = my;
      _m3d.fig.userData.footprintOffsetX = moffX;
      _m3d.fig.userData.footprintOffsetZ = moffY;
    }

  }

  // Cadáveres — marca onde o Pedro pode reanimar (na visão atual)
  for(const c of (state.corpses||[])){
    const [cx,cy] = c.pos;
    if(!visionSet.has(`${cx},${cy}`)) continue;
    const corpFig = obterFig(`corp:${c.id}`, JSON.stringify(c), () => build3DCorpse(c));
    corpFig.visible = !(window.CombatScene && CombatScene.isDying(`m:${c.id}`));
  }

  // Lápides dos heróis derrotados — somem quando a Ressurreição remove o
  // registro autoritativo e o peão vivo volta a ser renderizado acima.
  for(const c of (state.hero_corpses||[])){
    const [hx, hy] = c.pos || [];
    if(!Number.isFinite(hx) || !Number.isFinite(hy)) continue;
    if(!visionSet.has(`${hx},${hy}`)) continue;
    const heroCorpFig = obterFig(`hero-corpse:${c.hero_id || c.id}`, JSON.stringify(c), () => build3DCorpse(c), hx, hy);
    heroCorpFig.visible = !(window.CombatScene && CombatScene.isDying(`p:${c.hero_id || c.id}`));
  }

  // Animados (servos do Pedro) — peão do MONSTRO ORIGINAL com base/aro roxo (aliado)
  for(const pl of state.players){
    for(const a of (pl.animados||[])){
      if(!a.pos || (a.vida_atual||0) <= 0) continue;
      const [ax,ay] = a.pos;
      if(!visionSet.has(`${ax},${ay}`)) continue;
      const _aniFig3D = obterFig(`ani:${a.id}`,
        JSON.stringify([a.tipo, a.image, a.porte, a.size, a.oriented, a.fill_footprint_3d, a.facing, _animadoSel===a.id]),
        () => {
          const f = build3DFig('#9900cc', true, false, false, ax, ay, null, a.tipo, _animadoSel===a.id,
            a.image, a.porte, a.oriented, a.facing, false, false, false, 6, undefined, !!a.fill_footprint_3d, a.size);
          f.userData.animadoId = a.id;   // taggeado para getAnimadoMesh()
          return f;
        }, ax, ay);
      _aniFig3D.userData.whirlpoolTrapped = !!(a.rodamoinho_preso || a.rodamoinho_profundo_preso);
    }
  }

  // Room icons (glowing spheres — only for un-looted/cleared non-chest rooms)
  for(const room of state.rooms){
    if(room.cleared || !exploredSet.has(`${room.cx},${room.cy}`)) continue;
    if(room.role === 'chest') continue;   // chest rooms show the 3D chest model instead
    obterFig(`room:${room.cx},${room.cy}`, room.role, () => {
      const cols = { boss:0xff2020, trap:0xff8800 };
      const col  = cols[room.role] ?? 0xffffff;
      const geo  = new T.SphereGeometry(0.13, 8, 6);
      const mat  = new T.MeshStandardMaterial({ color:col, emissive:col, emissiveIntensity:0.75 });
      const s    = new T.Mesh(geo, mat);
      s.position.set(room.cx, 0.22+0.18, room.cy);
      return s;
    });
  }

  // ── Armadilhas colocáveis (Passo 2) — sprites de emoji sobre o tile ─────────
  for(const arm of (state.armadilhas||[])){
    const [ax,ay] = arm.pos;
    if(!exploredSet.has(`${ax},${ay}`)) continue;
    if(!_armadilhaVisivelParaMim(arm, me)) continue;   // escondida até ser revelada
    if(arm.image){
      // Com imagem: decal deitado no chão (plano horizontal sobre a casa).
      const dec = obterFig(`arm:${arm.id}`,
        JSON.stringify([arm.image, arm.ativada]),
        () => _armadilhaDecal3D(arm, ax, ay));
      dec.position.set(ax, 0.232, ay);   // logo acima do piso (TH=0.22)
    } else {
      const sp = obterFig(`arm:${arm.id}`,
        JSON.stringify([arm.icone, arm.ativada, arm.so_luccas]),
        () => _armadilhaSprite3D(arm, ax, ay));
      sp.position.set(ax, 0.34, ay);   // sprite não tem hover-lift — y fixo
    }
  }

  // Descarta as figuras que saíram de cena (morte, fora da visão, consumidas).
  for(const [key, ent] of figCache){
    if(!figsUsadas.has(key)){
      _disposeEntityTree(ent.fig);
      figCache.delete(key);
    }
  }
  // O loop 3D usa este sinal para reconstruir a lista de anéis pulsantes só
  // quando a composição das entidades realmente mudou.
  g3._pulseNodesDirty = true;

  }   // fim do bloco de reconstrução condicionada por entitySig

  // ── Deslize fiel (entity_step): reposiciona meshes em animação ───────────────
  // Fora do gate do entitySig: roda todo frame para que, mesmo quando o
  // game_state não muda, os peões de monstros/servos deslizem casa a casa.
  if(_serverStepAnim.size){
    for(const [id] of _serverStepAnim){
      const step = _serverStepPos(id);
      if(!step) continue;
      const mesh = getMonsterMesh(id) || getAnimadoMesh(id);
      if(!mesh) continue;
      if(window.CombatScene && CombatScene.poseFor(_figSceneKey(mesh), performance.now())) continue;
      if(mesh.userData._stepBaseY === undefined) mesh.userData._stepBaseY = mesh.position.y;
      // entity_step usa a âncora do servidor. Criaturas 2x2 deslizam com o
      // mesmo offset visual usado no estado parado, sem voltar para o canto.
      mesh.position.x = step.x + (Number(mesh.userData.footprintOffsetX) || 0);
      mesh.position.z = step.y + (Number(mesh.userData.footprintOffsetZ) || 0);
      const stepFacing = _serverStepFacing(id);
      if(stepFacing) _setMonsterMeshFacing3D(mesh, stepFacing);
      // Saltinho do peão (efeito de movimentação) — a entidade em deslize não
      // está sob o cursor, então não conflita com o hover-lift.
      const stepAnim = _serverStepAnim.get(id);
      const stepFraction = stepAnim
        ? (performance.now() - stepAnim.startTime) / stepAnim.segDur : 0;
      const ponteBaseY = stepAnim
        ? basePonteInterpolada3D(state, stepAnim.pts, stepFraction,
            mesh.userData._stepBaseY, TH)
        : null;
      const stepBaseY = ponteBaseY !== null
        ? ponteBaseY : mesh.userData._stepBaseY;
      mesh.position.y = stepBaseY + step.hop * ALTURA_ELEVACAO * 0.5;
    }
  }

  // Canção Heroica: anel dourado de raio 5 ao redor de bardos e Xamãs de teste.
  try { _sync3DCancaoRing(state); } catch(e) { console.warn('cancaoRing:', e); }
  try { _atualizarProtetor3D(performance.now()); } catch(e) { console.warn('protetorFx:', e); }

  // Portraits are exclusive to the class selection screen (HTML). Not on the board.
}

// Sprite de armadilha (emoji em canvas). Verde/normal = armada; vermelho = ativada.
function _decorTrapBadge3D(){
  const T = g3.T;
  const cv = document.createElement('canvas'); cv.width = cv.height = 96;
  const ctx = cv.getContext('2d');
  ctx.clearRect(0, 0, 96, 96);
  ctx.beginPath(); ctx.arc(48, 48, 39, 0, Math.PI * 2);
  ctx.fillStyle = '#5b1010'; ctx.fill();
  ctx.lineWidth = 5; ctx.strokeStyle = '#ff6b52'; ctx.stroke();
  ctx.font = 'bold 58px sans-serif'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.fillStyle = '#fff1d0'; ctx.fillText('!', 48, 51);
  const tex = new T.CanvasTexture(cv);
  tex._owned = true;
  const badge = new T.Sprite(new T.SpriteMaterial({
    map: tex, transparent: true, depthWrite: false,
  }));
  badge.scale.set(0.42, 0.42, 1);
  badge.renderOrder = 8;
  badge.userData.isTrapBadge = true;
  return badge;
}

function _armadilhaSprite3D(arm, x, y){
  const T = g3.T;
  const cv = document.createElement('canvas'); cv.width = cv.height = 64;
  const ctx = cv.getContext('2d');
  ctx.font = '46px serif'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.fillText(arm.icone || '🪤', 32, 36);
  const tex = new T.CanvasTexture(cv);
  tex._owned = true;   // textura exclusiva deste sprite — descartável com ele (r128: Texture não tem userData)
  const sp  = new T.Sprite(new T.SpriteMaterial({
    map: tex, transparent: true, depthWrite: false,
    opacity: arm.so_luccas ? 0.6 : (arm.ativada ? 1.0 : 0.92),
    color:   arm.ativada ? new T.Color(0xff6655) : new T.Color(0xffffff),
  }));
  sp.scale.set(0.6, 0.6, 1);
  sp.position.set(x, 0.34, y);
  sp.userData.armadilhaId = arm.id;
  sp.userData.tipo = 'armadilha';
  return sp;
}

// Armadilha com imagem (PNG de assets/objetos): decal DEITADO no chão da casa.
// Plano horizontal (rotacionado -90° em X) com a textura do PNG, ajustado à
// proporção da arte sem invadir os tiles vizinhos. Vermelho quando ativada.
function _armadilhaDecal3D(arm, x, y){
  const T = g3.T;
  const grp = new T.Group();
  const mat = new T.MeshBasicMaterial({
    transparent: true, alphaTest: 0.12, depthWrite: false,
    color: arm.ativada ? new T.Color(0xff7766) : new T.Color(0xffffff),
  });
  const mesh = new T.Mesh(new T.PlaneGeometry(0.92, 0.92), mat);
  mesh.rotation.x = -Math.PI/2;     // deita o plano no chão
  mesh.renderOrder = 2;             // desenha sobre o piso, sob os peões
  mesh.userData.isGroundDecal = true;   // fora do passe de outline
  grp.add(mesh);
  const cacheKey = '__arm_' + arm.image;
  const aplicar = (tex) => {
    const im = tex.image; if(!im || !im.width) return;
    const ar = im.width / im.height;
    let w = 0.92, h = 0.92/ar;
    if(h > 0.92){ h = 0.92; w = 0.92*ar; }
    mesh.geometry.dispose();
    mesh.geometry = new T.PlaneGeometry(w, h);
  };
  let tex = _pawnTexCache[cacheKey];
  if(tex){ mat.map = tex; if(tex.image && tex.image.width) aplicar(tex); }
  else {
    tex = new T.TextureLoader().load(_assetURL(`assets/objetos/${arm.image}`), aplicar);
    _pawnTexCache[cacheKey] = tex;
    mat.map = tex;
  }
  grp.position.set(x, 0.232, y);
  grp.userData.armadilhaId = arm.id;
  grp.userData.tipo = 'armadilha';
  return grp;
}

// Chão (decoração pisável): decal DEITADO no chão que preenche TODO o footprint
// borda-a-borda (estica a textura, sem manter proporção — é um piso). Peões andam
// por cima. `wCells`/`hCells` = footprint efetivo (já com facing aplicado).
function _chaoDecal3D(d, wCells, hCells){
  const T = g3.T;
  const grp = new T.Group();
  const mat = new T.MeshBasicMaterial({ transparent: true, depthWrite: false });
  const mesh = new T.Mesh(new T.PlaneGeometry(wCells, hCells), mat);
  mesh.rotation.x = -Math.PI/2;      // deita o plano no chão
  // renderOrder -1: o chão é PISO — deve ficar SOB os realces de movimento/ataque
  // (planos azuis/vermelhos em TH+0.004…), senão a grama esconderia a indicação.
  mesh.renderOrder = -1;
  mesh.userData.isGroundDecal = true;   // fora do passe de outline
  grp.add(mesh);
  const cacheKey = '__chao_' + d.image;
  let tex = _pawnTexCache[cacheKey];
  if(tex){ mat.map = tex; }
  else {
    tex = new T.TextureLoader().load(_assetURL(`assets/objetos/${d.image}`));
    tex._shared = true;   // cacheada/reusada — _disposeDecorMesh não deve descartá-la
    _pawnTexCache[cacheKey] = tex;
    mat.map = tex;
  }
  grp.userData = { isDecor: true, decorId: d.id, imageName: d.image,
                   floorW: wCells, floorH: hCells };
  return grp;
}

// MINIATURE BUILDER SYSTEM
// Each hero class and monster type gets a distinctive 3D miniature.
// All figures sit on a round plastic base on top of the floor tile (TH=0.22).
// Positions and movement rules are UNCHANGED — only visuals differ.

// Creates a StandardMaterial mesh, adds it to the group, and returns the mesh.
function _addM(group, geo, mp, pos, rotZ){
  const T   = g3.T;
  const mat = new T.MeshStandardMaterial({
    color:            mp.color  instanceof T.Color ? mp.color  : new T.Color(mp.color  ?? 0x888888),
    emissive:         mp.emissive instanceof T.Color ? mp.emissive : new T.Color(mp.emissive ?? 0x000000),
    emissiveIntensity: mp.emissiveIntensity ?? 0,
    roughness: mp.roughness ?? 0.82,
    metalness: mp.metalness ?? 0.04,
    side:      mp.side ?? T.FrontSide
  });
  const mesh = new T.Mesh(geo, mat);
  if(pos)  mesh.position.set(pos[0], pos[1], pos[2]);
  if(rotZ) mesh.rotation.z = rotZ;
  mesh.castShadow    = true;
  mesh.receiveShadow = true;
  group.add(mesh);
  return mesh;
}

// Resin statue / painted collectible style.  Spec:
//   Metal  : roughness 0.25, metalness 0.85, yellowish tint
//   Sword  : roughness 0.22, metalness 0.88
//   Cloth  : roughness 0.95, metalness 0.00
//   Leather: roughness 0.80, metalness 0.05
//   Skin   : roughness 0.84, metalness 0.00
//   Wood   : roughness 1.00, metalness 0.00
//   Glow   : emissive = color, intensity i (default 1.2)

// Acabamento de MINIATURA DE PLÁSTICO PINTADA — roughness baixa-média dá o
// brilho satinado que define o volume (antes era fosco/poligonal).
function _mMtl(hex){ return {color:new g3.T.Color(hex??0xd4c870), roughness:0.24, metalness:0.86}; }
function _mSwd(hex){ return {color:new g3.T.Color(hex??0xd4dcec), roughness:0.20, metalness:0.90}; }
function _mClth(hex){
  const c = hex instanceof g3.T.Color ? hex : new g3.T.Color(hex);
  return {color:c, roughness:0.52, metalness:0.02, emissive:c.clone(), emissiveIntensity:VC.pawns.emissiveIntensity};
}
function _mLeather(hex){
  const c = new g3.T.Color(hex ?? 0x5a3818);
  return {color:c, roughness:0.46, metalness:0.04, emissive:c.clone(), emissiveIntensity:VC.pawns.emissiveIntensity};
}
function _mSkin(hex){
  const c = new g3.T.Color(hex ?? 0xd4a060);
  return {color:c, roughness:0.42, metalness:0.02, emissive:c.clone(), emissiveIntensity:VC.pawns.emissiveIntensity};
}
function _mWood(hex){ return {color:new g3.T.Color(hex??0x7a4a18), roughness:0.62, metalness:0.02}; }
function _mGlw(hex,i){ const c=new g3.T.Color(hex); return {color:c,emissive:c,emissiveIntensity:i??1.2,roughness:0.22,metalness:0.05}; }

// Cobblestone texture: cached procedural CanvasTexture (deterministic pattern).

// ── Tampo de MADEIRA ESCURA para a base dos peões (corte de tora: anéis) ──────
let _woodTopTex = null;
function _getWoodTopTex(T){
  if(_woodTopTex) return _woodTopTex;
  const c = document.createElement('canvas');
  c.width = c.height = 128;
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#241106';
  ctx.fillRect(0, 0, 128, 128);
  // anéis de crescimento (elipses levemente excêntricas)
  for(let r = 62; r > 2; r -= 3.0){
    const tom = Math.sin(r * 1.7) * 0.5 + 0.5;
    ctx.strokeStyle = `rgb(${44 + tom*30},${24 + tom*17},${10 + tom*8})`;
    ctx.lineWidth = 2.3;
    ctx.beginPath();
    ctx.ellipse(64, 64, r, r * 0.93, 0.30, 0, Math.PI * 2);
    ctx.stroke();
  }
  // rachaduras radiais sutis
  ctx.strokeStyle = 'rgba(8,4,2,0.55)';
  ctx.lineWidth = 1.4;
  for(const [x1, y1] of [[118, 32], [22, 96], [98, 112], [40, 14]]){
    ctx.beginPath(); ctx.moveTo(64, 64); ctx.lineTo(x1, y1); ctx.stroke();
  }
  _woodTopTex = new T.CanvasTexture(c);
  return _woodTopTex;
}

// Gold name-plate sprite (billboards toward camera — always readable).
function _makeNamePlate(T, label){
  const c = document.createElement('canvas');
  c.width = 256; c.height = 44;
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#5a3600';
  ctx.fillRect(0,0,256,44);
  ctx.fillStyle = VC.ui.colors.gold;        // aged gold as requested
  ctx.fillRect(3,3,250,38);
  // Inner bevel lines
  ctx.strokeStyle = '#e0c060';
  ctx.lineWidth = 1;
  ctx.strokeRect(5,5,246,34);
  ctx.font = 'bold 17px Georgia,serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  // Embossed effect: pale highlight shifted (+1,−1) then dark main text
  ctx.fillStyle = 'rgba(255,235,130,0.50)';
  ctx.fillText(label.toUpperCase(), 129, 21);
  ctx.fillStyle = '#1e0e00';
  ctx.fillText(label.toUpperCase(), 128, 22);
  const tex = new T.CanvasTexture(c);
  tex._owned = true;   // textura exclusiva deste sprite — descartável com ele (r128: Texture não tem userData)
  const sp  = new T.Sprite(new T.SpriteMaterial({map:tex, depthWrite:false}));
  sp.scale.set(0.46, 0.080, 1.0);
  return sp;
}

function _figureName(isMonster, classId, mType){
  if(!isMonster)
    // O nome do herói já é catálogo traduzido no servidor desde a etapa 2.
    return _rotulo(classId + '.nome', 'cat.classe', t('ui.tabuleiro.heroi'));
  return ({goblin:'Goblin',skeleton:'Skeleton',orc:'Orc Warrior',
           dark_mage:'Dark Mage',troll:'Troll',dragon:'Dragon'}[mType]) || 'Monster';
}

