window.limparHighlightArremessoLanca = limparHighlightArremessoLanca;

function get3DTile(e){
  if(!g3) return null;
  const { T, renderer, raycaster, camera, tileMeshes } = g3;
  const rect = renderer.domElement.getBoundingClientRect();
  const mx   = ((e.clientX - rect.left) / rect.width)  *  2 - 1;
  const my   = ((e.clientY - rect.top)  / rect.height) * -2 + 1;
  raycaster.setFromCamera(new T.Vector2(mx, my), camera);
  const illusionKeys = new Set(((GS.gameState && GS.gameState.secret_passages) || [])
    .filter(p => p.type === 'illusion').map(p => `${p.pos[0]},${p.pos[1]}`));
  const bridgeMeshes = g3.bridgeMeshes || [];
  const clickableTiles = Object.values(tileMeshes).filter(m => m.visible &&
    (m.userData.isFloor || (m.userData.isWall && illusionKeys.has(`${m.userData.gridX},${m.userData.gridY}`))))
    .concat(bridgeMeshes.filter(m => m.visible));
  const hits   = raycaster.intersectObjects(clickableTiles);
  if(!hits.length) return null;
  const obj = hits[0].object;
  if(obj.userData.isBridge){
    // A ponte não possui um tileMesh próprio. Use o ponto real atingido pelo
    // raio para identificar inclusive a faixa lateral de uma ponte larga;
    // sem isso o clique retornava [undefined, undefined] e não era possível
    // escolher a casa da ponte como destino de movimento.
    const bx = Math.round(hits[0].point.x), by = Math.round(hits[0].point.z);
    const bkey = `${bx},${by}`;
    const bridgeHit = bridgeMeshes.some(mesh => mesh.visible
      && (mesh.userData.bridgeKeys || []).includes(bkey));
    if(bridgeHit) return [bx, by];
  }
  return [obj.userData.gridX, obj.userData.gridY];
}

function get3DMonsterAtPointer(e){
  if(!g3 || !g3.entityGroup) return null;
  const {T,renderer,raycaster,camera,entityGroup}=g3;
  const rect=renderer.domElement.getBoundingClientRect();
  const mx=((e.clientX-rect.left)/rect.width)*2-1;
  const my=((e.clientY-rect.top)/rect.height)*-2+1;
  raycaster.setFromCamera(new T.Vector2(mx,my),camera);
  const hits=raycaster.intersectObjects(entityGroup.children,true);
  for(const hit of hits){
    let obj=hit.object;
    while(obj && obj!==entityGroup){
      if(obj.userData && obj.userData.monId){
        return (GS.gameState?.monsters||[]).find(m=>m.id===obj.userData.monId)||null;
      }
      obj=obj.parent;
    }
  }
  return null;
}

function get3DTestHeroAtPointer(e){
  if(!g3?.entityGroup || !GS.gameState?.test_mode) return null;
  const {T, renderer, raycaster, camera, entityGroup} = g3;
  const rect = renderer.domElement.getBoundingClientRect();
  const mx = ((e.clientX - rect.left) / rect.width) * 2 - 1;
  const my = ((e.clientY - rect.top) / rect.height) * -2 + 1;
  raycaster.setFromCamera(new T.Vector2(mx, my), camera);
  const hits = raycaster.intersectObjects(entityGroup.children, true);
  for(const hit of hits){
    let obj = hit.object;
    while(obj && obj !== entityGroup){
      const pid = obj.userData?.pid;
      if(pid != null){
        const hero = (GS.gameState.players || []).find(p => p.test_hero && p.alive
          && String(p.id) === String(pid));
        if(hero) return hero;
      }
      obj = obj.parent;
    }
  }
  return null;
}

// O raycast do piso pode cair numa casa vizinha quando o modelo 3D do monstro
// cobre visualmente um item largado. Para o clique normal do herói, usa a
// criatura sob o ponteiro e escolhe uma casa do footprint que realmente pode
// ser atacada, antes de deixar o piso decidir uma coleta.
function _alvoAtaqueDoMonstroSobPonteiro(monster){
  if(!monster || monster.hp <= 0 || !GS.gameState || GS.canControlMonster?.()) return null;
  const me = GS.gameState.players?.find(p => p.id === GS.myPid && p.alive);
  if(!me || !GS.isMyTurn || me.action_done) return null;
  const tiles = (GS.monsterTiles?.(monster) || [monster.pos]).filter(Boolean);
  const attack = tiles
    .map(pos => ({ pos, action: GS.resolveTileClick(pos[0], pos[1]) }))
    .filter(entry => entry.action?.type === 'attack')
    .sort((a, b) =>
      Math.max(Math.abs(me.pos[0] - a.pos[0]), Math.abs(me.pos[1] - a.pos[1]))
      - Math.max(Math.abs(me.pos[0] - b.pos[0]), Math.abs(me.pos[1] - b.pos[1])))[0];
  if(attack) return attack;
  const fallback = tiles[0];
  return fallback ? { pos: fallback, action: null } : null;
}

// Mira LIVRE no 3D: intersecta um plano matemático na altura do chão e converte
// para coordenadas de grade. Funciona em QUALQUER casa do mapa — inclusive sob
// névoa (meshes invisíveis são ignorados pelo raycaster). Usado pela
// Clarividência, cujo alcance é o tabuleiro inteiro.
function get3DTilePlane(e){
  if(!g3) return null;
  const { T, renderer, raycaster, camera, W, H } = g3;
  const rect = renderer.domElement.getBoundingClientRect();
  const mx   = ((e.clientX - rect.left) / rect.width)  *  2 - 1;
  const my   = ((e.clientY - rect.top)  / rect.height) * -2 + 1;
  raycaster.setFromCamera(new T.Vector2(mx, my), camera);
  const plane = new T.Plane(new T.Vector3(0, 1, 0), -0.22);   // y = TH (topo do chão)
  const pt = new T.Vector3();
  if(!raycaster.ray.intersectPlane(plane, pt)) return null;
  const gx = Math.round(pt.x), gy = Math.round(pt.z);
  if(gx < 0 || gy < 0 || gx >= W || gy >= H) return null;
  return [gx, gy];
}

// ── 3D click handler: delegates to unified handleTileClick ───────────────────
// Guard: if the pointer moved while any button was held (orbit / pan / dolly),
// the mousedown → mousemove → mouseup sequence is a camera gesture, not a tap.
// Consume the synthetic click event and reset the flag for the next interaction.

function on3DClick(e){
  if(_orbitDragMoved){ _orbitDragMoved = false; return; }
  if(window._modoDirecaoInstrumento){
    const tDirection = get3DTilePlane(e);
    if(tDirection) _clickTileDirecaoInstrumento(tDirection[0], tDirection[1]);
    return;
  }
  if(window._modoAtaqueMira){
    const tAttack = get3DTile(e);
    if(tAttack) _clickTileAtaque(tAttack[0], tAttack[1]);
    return;
  }
  if(window._modoInstrumentoAlvo){
    const tInstrument = get3DTile(e);
    if(tInstrument) _clickTileInstrumentoAlvo(tInstrument[0], tInstrument[1]);
    return;
  }
  if(window._modoArremessoArma){
    const tWeapon = get3DTile(e);
    if(tWeapon) _clickTileArremessoArma(tWeapon[0], tWeapon[1]);
    return;
  }
  if(window._modoInstrumento){
    const tInst = get3DTile(e);
    if(tInst) _clickTileInstrumento(tInst[0], tInst[1]);
    return;
  }
  if(window._modoSenhorDasAguas){
    const tAgua = get3DTile(e);
    if(tAgua) _clickTileSenhorDasAguas(tAgua[0], tAgua[1]);
    return;
  }
  if(window._modoIraRocha){
    const tIra = get3DTile(e);
    if(tIra) _clickTileIraRocha(tIra[0], tIra[1]);
    return;
  }
  if(window._modoTempestadePlacement){
    const tStormPlacement = get3DTile(e);
    if(tStormPlacement) _clickTileTempestadePlacement(tStormPlacement[0], tStormPlacement[1]);
    return;
  }
  if(window._modoTempestadeMove){
    const tStorm = get3DTile(e);
    if(tStorm) _clickTileTempestade(tStorm[0], tStorm[1]);
    return;
  }
  if(window._modoTeleporteAlvo){
    const tTele = get3DTile(e);
    if(tTele) _clickTileTeleporteAlvo(tTele[0], tTele[1]);
    return;
  }
  if(window._modoTeleporteDestino){
    const tDestino = get3DTilePlane(e);
    if(tDestino) _clickTileTeleporteDestino(tDestino[0], tDestino[1]);
    return;
  }
  // Modo de mira de MAGIA: clicar uma carta arma a mira; aqui o clique no
  // tabuleiro resolve o alvo/casa e envia a mensagem `magia` (ver castarMagia).
  if(window._modoMagia){
    const tMag = window._modoMagia.alvoLivre ? get3DTilePlane(e) : get3DTile(e);
    if(tMag) _clickTileMagia(tMag[0], tMag[1]);
    return;
  }
  if(window._modoHabilidadeTeste){
    const tSkill = get3DTile(e);
    if(tSkill) _clickTileHabilidadeTeste(tSkill[0], tSkill[1]);
    return;
  }
  if(window._modoAnimarMortos){
    const tAni = get3DTile(e);
    if(tAni) _clickTileAnimarMortos(tAni[0], tAni[1]);
    return;
  }
  // Modo de mira de ARREMESSÁVEL (frasco_oleo/fogo_grego): resolve o alvo.
  if(window._modoThrowItem){
    const tThr = get3DTile(e);
    if(tThr) _clickTileThrow(tThr[0], tThr[1]);
    return;
  }
  if(window._modoMestreMira){
    const tMestre = get3DTile(e);
    if(tMestre) _clickMiraMestre(tMestre[0],tMestre[1]);
    return;
  }
  // Modo posicionamento de ARMADILHA (Luccas): clique numa casa para criar.
  if(window._modoPlacementArmadilha){
    const tArm = get3DTile(e);
    if(tArm) onClickTileParaArmadilha(tArm[0], tArm[1]);
    return;
  }
  // Modo arremesso da LANÇA CURTA (verde): clique no tabuleiro mira o alvo.
  if(window._modoArremessoLanca){
    const tArr = get3DTile(e);
    if(tArr) onClickTileArremessoLanca(tArr);
    if(!_highlightArremessoLanca.ativo) window._modoArremessoLanca = false;
    return;
  }
  // Modo arremesso da adaga PRINCIPAL (azul): clique no tabuleiro mira o alvo.
  if(window._modoArremessoPrincipal){
    const tArr = get3DTile(e);
    if(tArr) onClickTileArremessoPrincipal(tArr);
    if(!_highlightArremessoPrincipal.ativo) window._modoArremessoPrincipal = false;
    return;
  }
  // Modo arremesso da adaga SECUNDÁRIA (laranja): clique no tabuleiro mira o alvo.
  if(window._modoArremessoAtivo){
    const tArr = get3DTile(e);
    if(tArr) onClickTileArremesso(tArr);
    if(!_highlightArremesso.ativo) window._modoArremessoAtivo = false;  // arremessou → sai do modo
    return;
  }
  const monsterUnderPointer = get3DMonsterAtPointer(e);
  const attackUnderPointer = _alvoAtaqueDoMonstroSobPonteiro(monsterUnderPointer);
  if(attackUnderPointer?.action?.type === 'attack'){
    handleTileClick(attackUnderPointer.pos[0], attackUnderPointer.pos[1]);
    return;
  }
  // Mesmo fora do alcance, clicar no monstro não pode cair no piso e coletar
  // um item que esteja sob ou perto do modelo 3D.
  if(attackUnderPointer && monsterUnderPointer) return;
  if(GS.isMaster() && GS.gameState?.test_mode){
    const heroDireto = get3DTestHeroAtPointer(e);
    if(heroDireto){
      handleTileClick(heroDireto.pos[0], heroDireto.pos[1]);
      return;
    }
  }
  // No teste livre, a própria miniatura é clicável. O raycast anterior usava
  // somente o piso e podia selecionar a casa que aparecia atrás de uma figura alta.
  if(GS.isMaster() && GS.gameState?.test_mode){
    const monDireto=get3DMonsterAtPointer(e);
    if(monDireto){
      // Usa a casa sob o cursor, não a âncora do monstro. Assim qualquer uma
      // das quatro casas de uma criatura 2×2 pode virar alvo no teste 3D.
      const tileDireto = get3DTile(e) || monDireto.pos;
      handleTileClick(tileDireto[0], tileDireto[1]);
      return;
    }
  }
  const tile = get3DTile(e);
  if(!tile) return;
  const [tx, ty] = tile;

  if(GS.gameState){
    const chest = (GS.gameState.chests||[]).find(c=>c.pos[0]===tx&&c.pos[1]===ty);
    if(chest){
      const myP = GS.gameState.players.find(p=>p.id===GS.myPid&&p.alive);
      const dist = myP ? Math.max(Math.abs(myP.pos[0]-tx), Math.abs(myP.pos[1]-ty)) : 99;
      if(dist <= 2){ openChestWindow(chest); return; }
      else { toast(t('ui.tabuleiro.perto_do_bau'), 'var(--gold)'); return; }
    }
    // ── Decoration click (3D path — check footprint of each decoration) ─────────
    // Interativa (loot/fonte) → interage. Sólida (não-pisável) → bloqueia o clique.
    // Pisável (chão/fogueira) sem interação → deixa passar p/ a lógica de movimento
    // (o personagem caminha sobre o chão normalmente).
    const decsHere3D = GS.decorations.filter(d =>
      GS.decorTilesOf(d).some(t => t[0] === tx && t[1] === ty));
    if(decsHere3D.length){
      const inter3D = decsHere3D.find(d => d.tem_loot || d.chest_trap || d.trap || d.key_objective || d.special === 'fountain' || d.special === 'plaque');
      if(inter3D){ GS.interagirDecor(inter3D.id); return; }
      if(decsHere3D.some(d => !d.pisavel)) return;   // objeto sólido bloqueia o caminho
      // só decoração(ões) pisável(is) → segue para o movimento
    }
  }

  if(g3 && GS.gameState){
    const hasEntity =
      GS.gameState.players.some(p  => p.alive && p.pos[0]===tx && p.pos[1]===ty) ||
      GS.gameState.monsters.some(m => m.hp>0 &&
        (typeof GS.monsterTiles === 'function' ? GS.monsterTiles(m) : [m.pos])
          .some(([x, y]) => x === tx && y === ty));
    if(hasEntity){
      g3.selectedPos = (g3.selectedPos && g3.selectedPos[0]===tx && g3.selectedPos[1]===ty)
        ? null : [tx, ty];
    } else {
      g3.selectedPos = null;
    }
  }
  handleTileClick(tx, ty);
}

function on3DMouseMove(e){
  if(!GS.gameState || !g3) return;
  // A cadeia de mira mora em _aimPreviewAt (compartilhada com o 2D e com o
  // controle). Aqui fica só o que é do mouse no 3D: qual raycast usa a casa e o
  // estilo do cursor. `alvoLivre` (Clarividência) e o seletor de direção miram
  // o PLANO do chão, para alcançar casas ainda na névoa.
  if(_aimAlgumModoAtivo()){
    const noPlano = !!window._modoDirecaoInstrumento || !!window._modoMagia?.alvoLivre;
    const tile = noPlano ? get3DTilePlane(e) : get3DTile(e);
    if(tile) _aimPreviewAt(tile[0], tile[1], { event: e, tip: $('tooltip') });
    else _aimPreviewNone();
    g3.renderer.domElement.style.cursor = _aimCursorStyle();
    return;
  }
  if(window._modoArremessoLanca){ onMouseMoveArremessoLanca(e); return; }
  if(window._modoArremessoPrincipal){ onMouseMoveArremessoPrincipal(e); return; }
  if(window._modoArremessoAtivo){ onMouseMoveArremesso(e); return; }
  const tile = get3DTile(e);
  const tip  = $('tooltip');
  if(!tile){
    tip.style.display='none';
    g3.renderer.domElement.style.cursor='default';
    g3.hoveredPos = null;
    _setMasterMonsterHover(null);
    return;
  }
  const [tx,ty] = tile;
  if(_masterMonsterHoverEnabled()){
    _setMasterMonsterHover(_masterMonsterAtTileClient(GS.gameState, tx, ty)?.id || null);
  } else if(_masterMonsterHoverId){
    _setMasterMonsterHover(null);
  }
  const myP = GS.gameState.players.find(p=>p.id===GS.myPid&&p.alive);
  const el  = g3.renderer.domElement;

  if(GS.gameState.stairs_pos){
    const [sx,sy]=GS.gameState.stairs_pos;
    if(tx===sx&&ty===sy){
      tip.innerHTML=`🪜 <b>${t('ui.tabuleiro.escada_saida')}</b><br><span style="color:#ffd040">${t('ui.tabuleiro.clique_voltar_cidade')}</span>`;
      tip.style.display='block'; tip.style.left=(e.clientX+14)+'px'; tip.style.top=(e.clientY-10)+'px';
      el.style.cursor='pointer';
      g3.hoveredPos=null;   // don't hover-lift the tile as if it were a figure
      return;
    }
  }

  const hovChest = (GS.gameState.chests||[]).find(c=>c.pos[0]===tx&&c.pos[1]===ty);
  if(hovChest){
    const nItems = hovChest.items ? hovChest.items.length : 0;
    const dist   = myP ? Math.max(Math.abs(myP.pos[0]-tx), Math.abs(myP.pos[1]-ty)) : 99;
    const canOpen= dist <= 2;
    tip.innerHTML = `🎁 <b>${t('ui.bau.nome')}</b><br>` +
      `${hovChest.gold>0?`🪙 ${t('ui.bau.ouros', {n:hovChest.gold})}  `:''}` +
      `${nItems>0?`📦 ${nItems} item(s)`:''}` +
      (canOpen
        ? `<br><span style="color:#ffd040">${t('ui.tabuleiro.clique_para_abrir')}</span>`
        : `<br><span style="color:#888">${t('ui.tabuleiro.aproxime_se_para_abrir')}</span>`);
    tip.style.display='block'; tip.style.left=(e.clientX+14)+'px'; tip.style.top=(e.clientY-10)+'px';
    el.style.cursor = canOpen ? 'pointer' : 'default';
    g3.hoveredPos = null;
    return;
  }

  const heroCorpse = (GS.gameState.hero_corpses||[]).find(c=>c.pos?.[0]===tx&&c.pos?.[1]===ty);
  if(heroCorpse){
    tip.innerHTML=`🪦 <b>${heroCorpse.nome || t('ui.tabuleiro.heroi_derrotado')}</b><br><span style="color:#c7b0d8" data-i18n="ui.tabuleiro.heroi_derrotado">Herói derrotado</span>`;
    tip.style.display='block'; tip.style.left=(e.clientX+14)+'px'; tip.style.top=(e.clientY-10)+'px';
    el.style.cursor='default';
    g3.hoveredPos=null;
    return;
  }

  const monster = _masterMonsterAtTileClient(GS.gameState, tx, ty);
  if(monster){
    const dx=myP?Math.abs(myP.pos[0]-tx):99, dy=myP?Math.abs(myP.pos[1]-ty):99;
    const wRng = myP?.weapon?.range ?? null;
    const inR  = myP ? _alvoNoAlcanceArmaClient(myP, tx, ty, monster.altura) : false;
    const lineClear = !myP?.weapon?.range || GS.hasLineOfSight(GS.gameState, myP.pos[0], myP.pos[1], tx, ty);
    const canA = GS.isMyTurn && myP && !myP.action_done && inR && lineClear && GS.gameState.phase==='playing';
    tip.innerHTML=fichaInimigoTooltipHTML(monster, _partyTemBardoVivo(), myP) +
                  (canA ? `<br><span style="color:#f88">${t('ui.tabuleiro.clique_seta_atacar')}</span>` : '');
    tip.style.display='block'; tip.style.left=(e.clientX+14)+'px'; tip.style.top=(e.clientY-10)+'px';
    el.style.cursor = canA ? 'crosshair' : 'default';
    g3.hoveredPos = [tx, ty];   // trigger hover-lift + vitrine light
    return;
  }

  const player = GS.gameState.players.find(p=>p.pos[0]===tx&&p.pos[1]===ty&&p.alive);
  if(player){
    tip.innerHTML=`<b>${player.emoji} ${player.name}</b> Lv${player.level}<br>HP ${player.hp}/${player.max_hp}`;
    tip.style.display='block'; tip.style.left=(e.clientX+14)+'px'; tip.style.top=(e.clientY-10)+'px';
    el.style.cursor='default';
    g3.hoveredPos = [tx, ty];   // trigger hover-lift + vitrine light
    return;
  }

  // Empty tile — clear hover state
  g3.hoveredPos = null;
  tip.style.display='none';
  if(GS.isMyTurn && GS.gameState.phase==='playing' && myP && myP.moves_left>0)
    el.style.cursor='pointer';
  else
    el.style.cursor='default';
}

// `peca` opcional: quando vem preenchida (GS.pecaControlada()), a previa e da
// peca controlada — o servo da vez na janela pos-turno — em vez do heroi.
function _selecionarPreviaMovimento(action, tx, ty, notify=true, peca=null){
  const st = GS.gameState;
  const me = st?.players?.find(p => p.id === GS.myPid && p.alive);
  const origem = peca || me;
  if(!origem?.pos || !action?.path?.length) return false;
  GS.pendingMove = {
    target: [tx, ty],
    path: action.path.map(step => [step[0], step[1]]),
    stopAtDoor: !!action.stopAtDoor,
    origin: [origem.pos[0], origem.pos[1]],
    moves_left: Number(origem.moves_left) || 0,
    animadoId: (peca && peca.kind !== 'hero') ? peca.id : null
  };
  renderMap(st);
  if(notify) toast(t('ui.tabuleiro.clique_novamente_para_confirmar'), 'var(--gold)');
  return true;
}

function _executarMovimentoConfirmado(action){
  const st = GS.gameState;
  const myP = st?.players?.find(p => p.id === GS.myPid && p.alive);
  if(!myP || !action?.path?.length) return;
  const peao = (mode3D && g3) ? getPeaoMesh(GS.myPid) : null;
  if(peao){
    // Caminho absoluto (passos relativos → casas {x,z}) p/ a animação.
    let cx = myP.pos[0], cy = myP.pos[1];
    const caminho = [];
    for(const [dx,dy] of action.path){
      cx += dx; cy += dy;
      caminho.push({x:cx, z:cy, rotY:_facingToRotY([dx,dy])});
    }
    // Envia os passos ao servidor JÁ — assim a névoa é revelada (server-side)
    // em paralelo à animação local, em vez de só iniciar o round-trip DEPOIS
    // dela. Isso elimina a demora de "continuidade do mapa" ao caminhar.
    for(const [dx,dy] of action.path) GS.move(dx, dy);
    // Anima localmente; ao concluir, reconcilia com o estado autoritativo.
    moverPeaoAoCaminho(peao, myP, caminho, () => {
      if(GS.gameState) renderMap3D(GS.gameState);
    });
  } else {
    // 2D ou sem peão 3D — movimento instantâneo (comportamento anterior).
    for(const [dx,dy] of action.path) GS.move(dx, dy);
  }
}

function _cancelarPreviaMovimento(){
  const tinhaHeroi = !!GS.pendingMove;
  const tinhaMonstro = !!_masterMonsterMovePreview;
  if(!tinhaHeroi && !tinhaMonstro) return false;
  if(tinhaHeroi) GS.pendingMove = null;
  if(tinhaMonstro) _clearMasterMonsterMovePreview();
  _clearMovePreviewVisual();
  if(GS.gameState) renderMap(GS.gameState);
  toast(t('ui.hud.movimento_cancelado'), 'var(--text2)');
  return true;
}

// Escape cancela apenas a seleção de movimento e não abre o menu de pausa.
document.addEventListener('keydown', (e) => {
  if(e.key !== 'Escape' || !_cancelarPreviaMovimento()) return;
  e.preventDefault();
  e.stopImmediatePropagation();
}, true);

// Called by both 2D canvas click and 3D on3DClick.
// Pure decision is delegated to GS.resolveTileClick(); this function handles
// the DOM-side effects (toast, renderMyPanel, send).
function handleTileClick(tx, ty){
  if(window._modoMestreMira){ _clickMiraMestre(tx,ty); return; }
  getAudioContext();
  if(!podeReceberInput()) return;   // bloqueia input durante a animação de movimento
  if(window._modoPlacementArmadilha){ onClickTileParaArmadilha(tx, ty); return; }
  // Durante a mira de uma magia do herói-teste, o clique pertence à magia
  // mesmo que caia sobre um monstro/peão; o painel do Mestre só pode capturar
  // cliques fora desse fluxo exclusivo do simulador.
  if(window._modoMagia?.testHeroId != null){ _clickTileMagia(tx, ty); return; }
  // Habilidades e ataque do herói-teste também capturam o clique no mapa antes
  // de qualquer seleção de miniatura ou ficha do Mestre.
  if(window._modoHabilidadeTeste){ _clickTileHabilidadeTeste(tx, ty); return; }
  // No simulador do editor, o clique em herói/monstro passa primeiro pelo
  // mesmo resolvedor de alcance e caminho usado por um jogador. Fora de
  // `test_mode` esta guarda é falsa e o fluxo mestre normal segue intacto.
  if(_handleTesteHeroiTileClick(tx, ty)) return;
  // ── Mestre: clicar num monstro abre a ficha; o mestre não faz ações de herói ──
  if(GS.canControlMonster()){
    const commandControl = GS.isCommandController();
    const st = GS.gameState;
    if(!commandControl && st?.test_mode && window._modoAdicionarHeroiTeste){
      GS.mestreAdicionarHeroiTeste(window._modoAdicionarHeroiTeste, tx, ty);
      window._modoAdicionarHeroiTeste = null;
      return;
    }
    if(!commandControl && window._modoImplantarReforco){
      GS.mestreImplantarReforco(window._modoImplantarReforco, tx, ty);
      window._modoImplantarReforco = null;
      return;
    }
      const mm = GS.masterManual();
      if(mm){
        const monM = (st.monsters||[]).find(x=>x.id===mm.mid);
      const targetMonster = _masterMonsterAtTileClient(st, tx, ty);
      const alvo = (st.players||[]).find(p=>p.alive && p.pos[0]===tx && p.pos[1]===ty)
        || ((st.test_mode || commandControl) && targetMonster && targetMonster.id!==mm.mid
             ? targetMonster : null);
      if(monM && alvo && GS.masterPodeAtacar()){
        _clearMasterMonsterMovePreview();
        // Golpe armado na ficha manda; sem golpe armado, o primeiro com carga.
        let idx = window._mpGolpeArmado;
        if(idx == null){
          const n = ((monM.attacks||[]).length) || 1;
          for(let i=0;i<n;i++){ if(GS.masterAttackCharges(i) > 0){ idx = i; break; } }
        }
        if(idx != null && GS.masterAttackCharges(idx) > 0){
          const atk = (monM.attacks||[{}])[idx] || {};
          const rng = atk.range || null;
          const inR = _monsterAttackInRangeClient(monM,[tx,ty],atk);
          if(inR && (!atk.range || GS.hasLineOfSight(st, monM.pos[0], monM.pos[1], tx, ty))){
            GS.mestreAtacarMonstro(mm.mid, alvo.id, idx); window._mpGolpeArmado = null; return;
          }
          toast(t('ui.hud.alvo_fora_do_alcance_deste_golpe'), 'var(--orange)'); return;
        }
      }
      if((st.master_manual_reach||[]).some(([x,y])=>x===tx&&y===ty)){
        // Assim como para os heróis, o primeiro clique apenas arma a rota e o
        // segundo confirma. O servidor continua recalculando/validando o
        // caminho quando recebe o comando.
        const prev = _masterMonsterMovePreviewAtual(st);
        if(prev && prev.target[0] === tx && prev.target[1] === ty){
          _clearMasterMonsterMovePreview();
          GS.mestreMoverMonstroPara(mm.mid, tx, ty); return;
        }
        if(_setMasterMonsterMovePreview(st, tx, ty)) return;
        _clearMasterMonsterMovePreview();
        return;
      }
    }
    if(commandControl) return;
    _clearMasterMonsterMovePreview();
    const mon = _monstroEmCasa(tx, ty);
    if(mon){
      if(st.test_mode){
        const atorTeste = st.test_combat?.active
          ? st.test_combat.queue?.[st.test_combat.index] : null;
        if(!atorTeste || atorTeste.kind === 'monster')
          window._testeHeroiSelecionadoId = null;
      }
      window._mpFocoMid = mon.id; window._masterTab = 'ativo';
      if(st.test_mode) GS.mestreSelecionarTeste(mon.id);
      else renderMasterPanel(GS.gameState);
      _redrawMasterSelection();
    }
    return;
  }
  // ── Mira de MAGIA (2D e 3D): resolve alvo/casa e envia `magia` ─────────────
  // (No 3D, on3DClick já intercepta antes; aqui cobre o caminho do canvas 2D.)
  if(window._modoDirecaoInstrumento){ _clickTileDirecaoInstrumento(tx, ty); return; }
  if(window._modoAtaqueMira){ _clickTileAtaque(tx, ty); return; }
  if(window._modoInstrumentoAlvo){ _clickTileInstrumentoAlvo(tx, ty); return; }
  if(window._modoArremessoArma){ _clickTileArremessoArma(tx, ty); return; }
  if(window._modoInstrumento){ _clickTileInstrumento(tx, ty); return; }
  if(window._modoSenhorDasAguas){ _clickTileSenhorDasAguas(tx, ty); return; }
  if(window._modoIraRocha){ _clickTileIraRocha(tx, ty); return; }
  if(window._modoTempestadePlacement){ _clickTileTempestadePlacement(tx, ty); return; }
  if(window._modoTempestadeMove){ _clickTileTempestade(tx, ty); return; }
  if(window._modoTeleporteAlvo){ _clickTileTeleporteAlvo(tx, ty); return; }
  if(window._modoTeleporteDestino){ _clickTileTeleporteDestino(tx, ty); return; }
  if(window._modoMagia){ _clickTileMagia(tx, ty); return; }
  if(window._modoAnimarMortos){ _clickTileAnimarMortos(tx, ty); return; }
  // ── Mira de ARREMESSÁVEL (2D e 3D): resolve o alvo e envia `throw_item` ─────
  // (No 3D, on3DClick já intercepta antes; aqui cobre o caminho do canvas 2D.)
  if(window._modoThrowItem){ _clickTileThrow(tx, ty); return; }
  // ── Escada: sair é INDIVIDUAL — custa fome/sede e tem espera em rodadas ────
  const _st = GS.gameState;
  if(_st && _st.stairs_pos){
    const [sx,sy] = _st.stairs_pos;
    if(tx===sx && ty===sy){
      const me = (_st.players||[]).find(p=>p.id===GS.myPid && p.alive);
      if(!me) return;
      if(_st.saida_permitida === false){ toast(t('ui.tabuleiro.sem_saida'), 'var(--red)'); return; }
      if(!GS.isMyTurn){ toast(t('ui.tabuleiro.so_no_seu_turno'), 'var(--red)'); return; }
      const pertoDaEscada = Math.max(Math.abs(me.pos[0]-sx), Math.abs(me.pos[1]-sy)) <= 1;
      if(!pertoDaEscada){ toast(t('ui.tabuleiro.perto_da_escada'), 'var(--red)'); return; }
      const custo = _st.custo_saida || {fome:0, sede:0};
      const espera = _st.espera_saida || '0';
      if(me.fome < custo.fome || me.sede < custo.sede){
        toast(t('ui.tabuleiro.provisoes_insuficientes',{f: custo.fome, s: custo.sede}), 'var(--red)');
        return;
      }
      confirmarSaidaMasmorra(custo, espera);
      return;
    }
  }

  // ── Item no chão (2D e 3D): clicar num item adjacente pega; senão avisa ──────
  // Não-guardado por modo: o 3D funil por handleTileClick(tx,ty) via on3DClick.
  if(_st && Array.isArray(_st.ground_items)){
    const gi = _st.ground_items.find(g => g.pos[0]===tx && g.pos[1]===ty);
    if(gi){
      const me = _st.players.find(p=>p.id===GS.myPid&&p.alive);
      const podePegar = !!(me && GS.groundItemPickable(gi, me));
      const ataque = GS.resolveTileClick(tx, ty);
      // O ataque é a ação prioritária quando um monstro e um item ocupam a
      // mesma casa. A coleta só acontece se não houver ataque válido.
      if(podePegar && ataque?.type === 'attack'){
        GS.notifyAttack();
        sendAttack(ataque.targetId, ataque.targetPos);
        return;
      }
      if(podePegar){ GS.pickupItem(gi.id); return; }
      // Um item distante não pode bloquear um ataque válido no mesmo tile.
      if(ataque?.type !== 'attack'){
        toast(t('ui.hud.muito_longe_do_item'), 'var(--text2)'); return;
      }
    }
  }

  // ── Chest click (2D canvas path — 3D path handled in on3DClick) ────────────
  if(_st){
    const chest = (_st.chests||[]).find(c=>c.pos[0]===tx&&c.pos[1]===ty);
    if(chest){
      const myP = _st.players.find(p=>p.id===GS.myPid&&p.alive);
      const dist = myP ? Math.max(Math.abs(myP.pos[0]-tx), Math.abs(myP.pos[1]-ty)) : 99;
      if(dist <= 2){ openChestWindow(chest); return; }
      else { toast(t('ui.tabuleiro.perto_do_bau'), 'var(--gold)'); return; }
    }
  }

  // ── Decoration click (2D canvas path — 3D path handled in on3DClick) ─────────
  // Interativa (loot/fonte) → interage. Sólida → bloqueia o clique. Pisável
  // (chão/fogueira) sem interação → deixa passar p/ a lógica de movimento.
  if(_st){
    const decsHere = GS.decorations.filter(d =>
      GS.decorTilesOf(d).some(t => t[0] === tx && t[1] === ty));
    if(decsHere.length){
      const inter = decsHere.find(d => d.tem_loot || d.chest_trap || d.trap || d.key_objective || d.special === 'fountain' || d.special === 'plaque');
      if(inter){ GS.interagirDecor(inter.id); return; }
      if(decsHere.some(d => !d.pisavel)) return;   // objeto sólido bloqueia o caminho
      // só decoração(ões) pisável(is) → segue para o movimento
    }
  }

  // ── Controle de servos/elementais (clique no tabuleiro, 2D e 3D) ────────────
  // Clique em servo = seleciona/deseleciona. Com servo selecionado: clique em
  // monstro adjacente = ataca; clique em casa adjacente livre = move 1 passo.
  // Só disponível durante o turno dos servos (animados_turn === myPid).
  if(_st && GS.isMyTurn && _st.animados_turn === GS.myPid){
    // ── Prisioneiro liberto: o resgatador o controla (só movimento) ───────────
    const _prisC = _st.prisoner;
    const meuPrisClk = _prisC && _prisC.alive && _prisC.freed && _prisC.rescuer_pid === GS.myPid;
    if(meuPrisClk && _prisC.pos[0]===tx && _prisC.pos[1]===ty){
      _prisSel = !_prisSel; _animadoSel = null; renderMap(_st); return;
    }
    if(meuPrisClk && _prisSel){
      const expSetP = new Set(_st.explored.map(([x,y])=>`${x},${y}`));
      for(const [rx,ry] of (_st.revealed||[])) expSetP.add(`${rx},${ry}`);
      const passosP = GS.findPath(_st.tiles, expSetP, _prisC.pos[0], _prisC.pos[1], tx, ty, _prisC.moves_left||0);
      if(passosP && passosP.length){
        GS.pendingMove = null; _clearMovePreviewVisual();
        _animarEEnviarMoverPrisioneiroCaminho(_prisC, passosP); return;
      }
      _prisSel=false; renderMap(_st); return;   // sem caminho/alcance → desseleciona
    }
    const meP  = _st.players.find(p=>p.id===GS.myPid && p.alive);
    const meus = (meP && meP.animados) ? meP.animados.filter(a=>a.pos && a.vida_atual>0) : [];
    if(meus.length){
      const sobre = meus.find(a=>a.pos[0]===tx && a.pos[1]===ty);
      if(sobre){
        if(window._animadoAbilityPending &&
           (window._animadoAbilityPending.animadoId !== sobre.id || _animadoSel === sobre.id)){
          window._animadoAbilityPending = null;
        }
        _animadoSel = (_animadoSel===sobre.id) ? null : sobre.id;
        renderMap(_st);
        renderMyPanel(_st);
        return;
      }
      if(_animadoSel){
        const a = meus.find(x=>x.id===_animadoSel);
        if(a){
           const mon = _masterMonsterAtTileClient(_st, tx, ty);
          if(mon){
            const pendingAbility = window._animadoAbilityPending;
            if(pendingAbility && pendingAbility.animadoId === a.id){
              GS.usarHabilidadeAnimado(a.id, pendingAbility.abilityId, mon.id);
              window._animadoAbilityPending = null;
              renderMyPanel(GS.gameState);
              return;
            }
            const ataqueA = (a.attacks || [])[0] || {};
            const alcanceA = Number(ataqueA.range || 0);
            // Mesma regra do realce (e do servidor): corpo a corpo e CARDINAL.
            // Antes esta copia aceitava a diagonal e mandava um ataque que o
            // servidor recusava por falta de adjacencia.
            const emAlcanceA = GS.animadoAttackTargetTiles(a)
              .some(alvo => alvo.x === mon.pos[0] && alvo.y === mon.pos[1]);
            if(emAlcanceA) GS.atacarAnimado(a.id, mon.id,
              GS.animadoAttackRangeTiles(a).length ? [tx,ty] : null);
            else toast(alcanceA
              ? t('ui.mestre.ataque_alcanca', {n: alcanceA, forma: ataqueA.range_shape ? t('ui.mestre.em_linha_reta') : ''})
              : t('ui.hud.o_servo_precisa_estar_adjacente_ao_alvo'));
            return;
          }
          // Movimento fluido: percorre o caminho inteiro até a casa clicada,
          // dentro do orçamento de movimento do minion (igual ao herói). O
          // pathfinding considera tiles explorados + revelados ao vivo (a área
          // que o próprio minion enxerga).
          const raioTiles = GS.animadoAttackRangeTiles(a);
          if(raioTiles.some(tile => tile.x === tx && tile.y === ty)){
            GS.atacarAnimado(a.id, null, [tx,ty]);
            return;
          }
          const expSetMin = new Set(_st.explored.map(([x,y])=>`${x},${y}`));
          for(const [rx,ry] of (_st.revealed||[])) expSetMin.add(`${rx},${ry}`);
          const passosMin = GS.findPath(_st.tiles, expSetMin, a.pos[0], a.pos[1], tx, ty, a.moves_left||0);
          if(passosMin && passosMin.length){
            GS.pendingMove = null; _clearMovePreviewVisual();
            _animarEEnviarMoverCaminhoMinino(a, passosMin); return;
          }
          _animadoSel=null; renderMap(_st); return;   // sem caminho/alcance → desseleciona
        }
      }
    }
  }

  let action = GS.resolveTileClick(tx, ty);
  const preview = GS.pendingMove;
  if(preview){
    const sameTarget = preview.target?.[0] === tx && preview.target?.[1] === ty;
    if(sameTarget){
      // Recalcula a rota no estado mais recente antes de confirmar. Se o
      // servidor já mudou a situação, a prévia não pode disparar uma rota velha.
      if(action?.type === 'move'){
        GS.pendingMove = null;
        _clearMovePreviewVisual();
        _executarMovimentoConfirmado(action);
        return;
      }
      GS.pendingMove = null;
      _clearMovePreviewVisual();
      if(!action) { renderMap(GS.gameState); return; }
    } else if(action?.type === 'move'){
      // Clicar outra casa troca a seleção; o segundo clique nessa nova casa
      // será a confirmação, como no fluxo de seleção do Rezrog.
      _selecionarPreviaMovimento(action, tx, ty);
      return;
    } else {
      // Um clique em monstro/porta/interação abandona a prévia e segue para a
      // ação correspondente, sem exigir um clique extra para limpar o estado.
      GS.pendingMove = null;
      _clearMovePreviewVisual();
      renderMap(GS.gameState);
    }
  }
  if(!action) return; // nothing to do (null = consume silently)
  switch(action.type){
    case 'open_door':
      send({type:'open_door', tx:action.x, ty:action.y});
      break;
    case 'door_far':
      toast(t('ui.hud.aproxime_se_da_porta_para_abri_la'), 'var(--gold)');
      break;
    case 'attack_blocked_wall':
      toast(t('ui.hud.uma_parede_bloqueia_a_linha_de_tiro'), 'var(--orange)');
      break;
    case 'movement_blocked':
      if(action.reason === 'petrified')
        toast(t('erro.voce_esta_petrificado_e_nao_pode_se_move'), 'var(--orange)');
      break;
    case 'skill_blocked':
      { const msg = t('ui.hud.selecione_uma_casa_adjacente_ao_luccas');
        _aimSetStatus(msg, '#ffb168'); toast(msg, 'var(--orange)'); }
      break;
    case 'disarm_trap':
      if(_aimSessionIs('desarmar_armadilha')) _aimEnd({silent:true, reason:'resolved'});
      GS.desarmarArmadilha(action.tx, action.ty);
      GS.pendingSkill = null;
      _removerEfeitoVisualLocal('desarmar_armadilha');
      renderMyPanel(GS.gameState);
      break;
    case 'attack':
      GS.notifyAttack();
      sendAttack(action.targetId, action.targetPos);
      break;
    case 'move': {
      // Primeiro clique apenas seleciona a rota; o segundo confirma.
      _selecionarPreviaMovimento(action, tx, ty);
      break;
    }
  }
}

